(* ===== 配对战役 vander 系支撑引理（探针 _dbg_kdr.v 690-775 行，随 vander 块合入） ===== *)
(* Q 层 2·(1/x) == 2/x（Qdiv 展开 ring）——E_0/O_0 抵消用 *)
Lemma q_div_scale2 : forall (x : Q), 2 * (1 / x) == 2 / x.
Proof.
  intro x. unfold Qdiv. ring.
Qed.

(* Qeq 移项通用引理：SE + Em - SO - Om == 0 ⟹ SO - SE == Em - Om
   （Qopp_comp 取反 + transitivity + ring——免 Hz 句法匹配，E143-265 模式） *)
Lemma qeq_moved : forall (SE SO Em Om : Q),
  SE + Em - SO - Om == 0 -> SO - SE == Em - Om.
Proof.
  intros SE SO Em Om H.
  assert (Hdiff : (SO - SE) - (Em - Om) == 0).
  { transitivity (- (SE + Em - SO - Om)).
    - ring.
    - assert (Hopp : - (SE + Em - SO - Om) == - 0).
      { apply (Qopp_comp (SE + Em - SO - Om) 0 H). }
      rewrite <- Hopp.
      ring. }
  transitivity ((SO - SE) - (Em - Om) + (Em - Om)).
  - ring.
  - rewrite Hdiff. ring.
Qed.

(* Qeq 移项变体：A + B + (-C) == 0 ⟹ C - A == B（Hz 的 2ΣE + Em + 2·(-ΣO) == 0 形态） *)
Lemma qeq_moved_neg : forall (A B C : Q),
  A + B + (- C) == 0 -> C - A == B.
Proof.
  intros A B C H.
  (* H : A + B + (-C) == 0 ⟹ -(A + B + (-C)) == 0（Qopp_comp）
     C - A - B == -(A + B + (-C))（ring 恒等） *)
  assert (Hdiff : (C - A) - B == 0).
  { transitivity (- (A + B + (- C))).
    - ring.
    - assert (Hopp : - (A + B + (- C)) == - 0).
      { apply (Qopp_comp (A + B + (- C)) 0 H). }
      rewrite <- Hopp.
      ring. }
  (* (C-A) - B == 0 ⟹ C - A == B（两边加 B） *)
  transitivity ((C - A) - B + B).
  - ring.
  - rewrite Hdiff. ring.
Qed.

(* Qeq 移项变体2：A + B + 2*(-C) == 0 ⟹ 2C - A == B（Hz 的 `2ΣE + Em + 2·(-ΣO) == 0` 形态）
   用 qeq_moved_neg 于 (A, B, 2C)：A + B + (-(2C)) == 0 由前提经 ring（2·(-C) == -(2·C)） *)
Lemma qeq_moved_neg2 : forall (A B C : Q),
  A + B + 2 * (- C) == 0 -> 2 * C - A == B.
Proof.
  intros A B C H.
  apply (qeq_moved_neg A B (2 * C)).
  (* 需证 A + B + (-(2*C)) == 0——由 H（A + B + 2*(-C) == 0）经 ring *)
  rewrite <- H.
  ring.
Qed.

(* sum_upto 移位：Σ_{j=0}^{n-1} f (j+1) == Σ_{j=0}^{n} f j - f 0（首项移出，rot 反向）
   sum_upto (S n) f == f 0 + sum_upto n (fun j => f (S j))（rot）⟹ 移项 *)
Lemma sum_upto_shift : forall (n : nat) (f : nat -> Q),
  sum_upto n (fun j => f (j + 1)%nat) == sum_upto (n + 1) f - f 0%nat.
Proof.
  intros n f.
  assert (Hn : (n + 1 = Datatypes.S n)%nat) by lia.
  rewrite (sum_upto_nat_eq (n + 1)%nat (Datatypes.S n) f Hn).
  rewrite (sum_upto_rot n f).
  rewrite (sum_upto_ext n (fun j => f (j + 1)%nat) (fun j => f (Datatypes.S j))).
  2: { intro j. assert (Hj : (j + 1 = Datatypes.S j)%nat) by lia. rewrite Hj. reflexivity. }
  unfold Qminus. ring.
Qed.

(* sum_upto 数乘线性：Σ(c·f) == c·Σf（归纳，simpl + ring） *)
Lemma sum_upto_scale : forall (n : nat) (c : Q) (f : nat -> Q),
  sum_upto n (fun j => c * f j) == c * sum_upto n f.
Proof.
  intros n. induction n as [| n' IH]; intros c f; simpl.
  - ring.
  - setoid_rewrite IH. ring.
Qed.

(* sum_upto 数乘线性（-2 系数）：Σ(-2·f) == -2·Σf *)
Lemma sum_upto_scale_neg2 : forall (n : nat) (f : nat -> Q),
  sum_upto n (fun j => - 2 * f j) == - 2 * sum_upto n f.
Proof.
  intros n f.
  setoid_rewrite <- (sum_upto_scale n (- 2) f).
  reflexivity.
Qed.

(* ============ 配对战役第三步：Vandermonde 恒等（vander_4m2 / vander_4m4，探针 _dbg_kdr.v 67 Qed 合入） ============ *)
(* q_pow 1 任意幂 == 1 *)
Lemma q_pow_one : forall n, q_pow 1 n == 1.
Proof.
  intro n. induction n as [| n' IH]; simpl.
  - reflexivity.
  - rewrite IH. ring.
Qed.

(* (−1)^{2n} == 1 *)
Lemma q_pow_neg1_even : forall n, q_pow (-1) (2 * n) == 1.
Proof.
  intro n.
  setoid_rewrite (q_pow_neg_even 1 n).
  apply q_pow_one.
Qed.

(* (−1)^{2n+1} == −1 *)
Lemma q_pow_neg1_odd : forall n, q_pow (-1) (2 * n + 1) == -1.
Proof.
  intro n.
  assert (Hidx : (2 * n + 1 = Datatypes.S (2 * n))%nat) by lia.
  setoid_replace (q_pow (-1) (2 * n + 1)) with (q_pow (-1) (Datatypes.S (2 * n))).
  2: { apply (q_pow_comp_proper (-1) (-1) (Qeq_refl (-1)) (2 * n + 1)%nat (Datatypes.S (2 * n))%nat Hidx). }
  setoid_rewrite (q_pow_neg_odd 1 n).
  setoid_rewrite (q_pow_one (Datatypes.S (2 * n))).
  ring.
Qed.

(* altf 转 sum_upto：altf N == Σ_{u=0}^{N} q_pow (−1) u / (u!(N−u)!) *)
Lemma altf_as_sum_upto : forall N, altf N ==
  sum_upto (N + 1) (fun u => q_pow (-1) u / (q_fact u * q_fact (N - u))).
Proof.
  intro N.
  (* 先证通用：altf_aux N u == sum_upto (u+1) (fun t => q_pow (−1) t / (t!(N−t)!))，归纳于 u *)
  assert (Haux : forall u, altf_aux N u ==
                 sum_upto (u + 1) (fun t => q_pow (-1) t / (q_fact t * q_fact (N - t)))).
  { intro u. induction u as [| u' IH]; simpl.
    - (* u=0：altf_aux N 0 == Qinv(q_fact N)；sum_upto 1 f == f 0 == 1/(0!(N−0)!) *)
      assert (Hs : sum_upto (0 + 1) (fun t : nat => q_pow (-1) t / (q_fact t * q_fact (N - t))) ==
                   q_pow (-1) 0 / (q_fact 0 * q_fact (N - 0))).
      { simpl. ring. }
      rewrite Hs.
      assert (H0 : (N - 0 = N)%nat) by lia.
      rewrite H0.
      simpl.
      unfold Qdiv.
      setoid_rewrite (Qmult_1_l (q_fact N)).
      ring.
    - (* u = S u'：altf_aux N (S u') == altf_aux N u' + q_pow (−1) (S u')/((S u')!(N−S u')!) *)
      change (altf_aux N u' + q_pow (-1) (Datatypes.S u') / (q_fact (Datatypes.S u') * q_fact (N - Datatypes.S u')) ==
              sum_upto (Datatypes.S u' + 1) (fun t => q_pow (-1) t / (q_fact t * q_fact (N - t)))).
      assert (Hsu : (Datatypes.S u' + 1 = Datatypes.S (u' + 1))%nat) by lia.
      rewrite Hsu.
      change (sum_upto (Datatypes.S (u' + 1)) (fun t => q_pow (-1) t / (q_fact t * q_fact (N - t)))) with
        (sum_upto (u' + 1) (fun t => q_pow (-1) t / (q_fact t * q_fact (N - t))) +
         q_pow (-1) (u' + 1) / (q_fact (u' + 1) * q_fact (N - (u' + 1)))).
      setoid_rewrite IH.
      (* 尾项：q_pow (−1) (S u') vs q_pow (−1) (u'+1)——S u' == u'+1 定义性？u'+1 == S u' 需 lia *)
      assert (Hp : (u' + 1 = Datatypes.S u')%nat) by lia.
      setoid_replace (q_pow (-1) (u' + 1)) with (q_pow (-1) (Datatypes.S u')).
      2: { apply (q_pow_comp_proper (-1) (-1) (Qeq_refl (-1)) (u' + 1)%nat (Datatypes.S u')%nat Hp). }
      assert (Hf : (N - (u' + 1) = N - Datatypes.S u')%nat) by lia.
      setoid_replace (q_fact (N - (u' + 1))) with (q_fact (N - Datatypes.S u')).
      2: { apply q_fact_nat_eq. lia. }
      assert (Hq : (u' + 1 = Datatypes.S u')%nat) by lia.
      setoid_replace (q_fact (u' + 1)) with (q_fact (Datatypes.S u')).
      2: { apply q_fact_nat_eq. exact Hq. }
      ring. }
  (* altf N == altf_aux N N；sum_upto (N+1) 与 u=N 形态一致 *)
  unfold altf.
  setoid_rewrite (Haux N).
  assert (Hn : (N + 1 = N + 1)%nat) by lia.
  reflexivity.
Qed.

(* sum_upto 偶奇拆分（偶数项数）：Σ_{i=0}^{2n−1} f i == Σ_{j=0}^{n−1} f (2j) + Σ_{j=0}^{n−1} f (2j+1) *)
Lemma sum_upto_even_split : forall (n : nat) (f : nat -> Q),
  sum_upto (2 * n)%nat f ==
  sum_upto n (fun j => f (2 * j)%nat) + sum_upto n (fun j => f (2 * j + 1)%nat).
Proof.
  intros n. induction n as [| n' IH]; intros f.
  - (* n=0：sum_upto 0 f == 0 + 0 *)
    simpl. ring.
  - (* 2·S n' == S(S(2n'))——sum_upto_nat_eq 换形（simpl 不可，2·S n' 对变量 n' 不化简） *)
    assert (Hidx : (2 * Datatypes.S n' = Datatypes.S (Datatypes.S (2 * n')))%nat) by lia.
    rewrite (sum_upto_nat_eq (2 * Datatypes.S n')%nat (Datatypes.S (Datatypes.S (2 * n'))) f Hidx).
    (* LHS 逐层拆：sum_upto (S(S(2n'))) f == sum_upto (2n') f + f (2n') + f (S(2n')) *)
    change (sum_upto (Datatypes.S (Datatypes.S (2 * n'))) f) with
      (sum_upto (Datatypes.S (2 * n')) f + f (Datatypes.S (2 * n'))).
    change (sum_upto (Datatypes.S (2 * n')) f) with
      (sum_upto (2 * n')%nat f + f (2 * n')%nat).
    setoid_rewrite (IH f).
    (* RHS：sum_upto (S n') 拆尾项——逐项 change（大项 change 不可靠） *)
    change (sum_upto (Datatypes.S n') (fun j => f (2 * j)%nat)) with
      (sum_upto n' (fun j => f (2 * j)%nat) + f (2 * n')%nat).
    change (sum_upto (Datatypes.S n') (fun j => f (2 * j + 1)%nat)) with
      (sum_upto n' (fun j => f (2 * j + 1)%nat) + f (2 * n' + 1)%nat).
    (* 尾项换形：f (S(2n')) == f (2n'+1)（lia 非定义性，rewrite 显式） *)
    assert (Ht : (Datatypes.S (2 * n') = 2 * n' + 1)%nat) by lia.
    rewrite Ht.
    ring.
Qed.

(* sum_upto 偶奇拆分（奇数项数）：Σ_{i=0}^{2n} f i == Σ_{j=0}^{n} f (2j) + Σ_{j=0}^{n−1} f (2j+1) *)
Lemma sum_upto_even_split_odd : forall (n : nat) (f : nat -> Q),
  sum_upto (2 * n + 1)%nat f ==
  sum_upto (n + 1)%nat (fun j => f (2 * j)%nat) + sum_upto n (fun j => f (2 * j + 1)%nat).
Proof.
  intros n. induction n as [| n' IH]; intros f.
  - (* n=0：sum_upto 1 f == f 0 == f 0 + 0 *)
    simpl. ring.
  - (* 2·S n'+1 == S(S(S(2n')))——sum_upto_nat_eq 换形 *)
    assert (Hidx : (2 * Datatypes.S n' + 1 = Datatypes.S (Datatypes.S (Datatypes.S (2 * n'))))%nat) by lia.
    rewrite (sum_upto_nat_eq (2 * Datatypes.S n' + 1)%nat (Datatypes.S (Datatypes.S (Datatypes.S (2 * n')))) f Hidx).
    (* LHS 逐层拆：sum_upto (2n'+3) f == sum_upto (2n'+1) f + f (2n'+1) + f (2n'+2) *)
    change (sum_upto (Datatypes.S (Datatypes.S (Datatypes.S (2 * n')))) f) with
      (sum_upto (Datatypes.S (Datatypes.S (2 * n'))) f + f (Datatypes.S (Datatypes.S (2 * n')))).
    change (sum_upto (Datatypes.S (Datatypes.S (2 * n'))) f) with
      (sum_upto (Datatypes.S (2 * n')) f + f (Datatypes.S (2 * n'))).
    (* sum_upto (S(2n')) f 与 IH 的 sum_upto (2n'+1) f 形态统一（lia 非定义性） *)
    assert (Hsn : (2 * n' + 1 = Datatypes.S (2 * n'))%nat) by lia.
    rewrite <- (sum_upto_nat_eq (2 * n' + 1)%nat (Datatypes.S (2 * n')) f Hsn).
    (* 对 sum_upto (2n'+1) f 用 IH *)
    setoid_rewrite (IH f).
    (* RHS 逐项拆尾项：先 nat_eq 统一 S n'+1 == S(n'+1)，再逐项 change *)
    assert (Hsr : (Datatypes.S n' + 1 = Datatypes.S (n' + 1))%nat) by lia.
    rewrite (sum_upto_nat_eq (Datatypes.S n' + 1)%nat (Datatypes.S (n' + 1)) (fun j => f (2 * j)%nat) Hsr).
    change (sum_upto (Datatypes.S (n' + 1)) (fun j => f (2 * j)%nat)) with
      (sum_upto (n' + 1)%nat (fun j => f (2 * j)%nat) + f (2 * (n' + 1))%nat).
    change (sum_upto (Datatypes.S n') (fun j => f (2 * j + 1)%nat)) with
      (sum_upto n' (fun j => f (2 * j + 1)%nat) + f (2 * n' + 1)%nat).
    (* 尾项统一：f (2(n'+1)) == f (S(S(2n')))（H6）；f (S(2n')) == f (2n'+1)（Ht1） *)
    assert (H6 : (2 * (n' + 1) = Datatypes.S (Datatypes.S (2 * n')))%nat) by lia.
    rewrite H6.
    assert (Ht1 : (Datatypes.S (2 * n') = 2 * n' + 1)%nat) by lia.
    rewrite Ht1.
    ring.
Qed.

(* 和分割（通用版，无范围前提）：Σ_{i=0}^{a+b−1} f i == Σ_{i=0}^{a−1} f i + Σ_{i=0}^{b−1} f (a+i)
   证明：归纳于 a；归纳步两侧都 sum_upto_rot 移出首项 f 0，IH 于 g = f∘S（E143-243 g∘S 模式） *)
Lemma sum_upto_split_gen : forall (a b : nat) (f : nat -> Q),
  sum_upto (a + b)%nat f == sum_upto a f + sum_upto b (fun i => f (a + i)%nat).
Proof.
  intros a. induction a as [| a' IH]; intros b f.
  - (* a=0：sum_upto b f == 0 + sum_upto b (fun i => f (0+i)) *)
    change (sum_upto (0 + b) f) with (sum_upto b f).
    change (sum_upto 0 f) with 0.
    rewrite (sum_upto_ext b (fun i => f (0 + i)%nat) f).
    2: { intro i. change (f (0 + i)%nat) with (f i). reflexivity. }
    ring.
  - (* a = S a'：LHS 与 RHS 都先 rot 移出首项 f 0，再 IH 于 g = f∘S *)
    assert (Hadd : (Datatypes.S a' + b = Datatypes.S (a' + b))%nat) by lia.
    rewrite (sum_upto_nat_eq (Datatypes.S a' + b) (Datatypes.S (a' + b)) f Hadd).
    rewrite (sum_upto_rot (a' + b) f).
    setoid_rewrite (sum_upto_rot a' f).
    setoid_rewrite (IH b (fun i => f (Datatypes.S i))).
    rewrite (sum_upto_ext b (fun i => f (Datatypes.S (a' + i))%nat) (fun i => f (Datatypes.S a' + i)%nat)).
    2: { intro i. assert (Hnat : (Datatypes.S (a' + i) = Datatypes.S a' + i)%nat) by lia.
         rewrite Hnat. reflexivity. }
    ring.
Qed.

(* 镜像对称（偶数项数）：f j == f (2n+1−j)（j ≤ n）⟹ Σ_{j=0}^{2n+1} f j == 2·Σ_{j=0}^{n} f j *)
Lemma sum_upto_mirror_even : forall (n : nat) (f : nat -> Q),
  (forall j, (j <= n)%nat -> f j == f (2 * n + 1 - j)%nat) ->
  sum_upto (2 * n + 2)%nat f == 2 * sum_upto (n + 1) f.
Proof.
  intros n f Hmir.
  (* 2n+2 == (n+1)+(n+1)：split *)
  assert (Hadd : (2 * n + 2 = (n + 1) + (n + 1))%nat) by lia.
  rewrite (sum_upto_nat_eq (2 * n + 2)%nat ((n + 1) + (n + 1)) f Hadd).
  setoid_rewrite (sum_upto_split_gen (n + 1) (n + 1) f).
  (* 第二和：Σ_{i=0}^{n} f (n+1+i) == Σ_{i=0}^{n} f i（镜像 f (2n+1−i) == f i） *)
  assert (Hsec : sum_upto (n + 1) (fun i => f (n + 1 + i)%nat) == sum_upto (n + 1) f).
  { (* sum_upto_rev 反向：sum_upto (n+1) h == sum_upto (n+1) (fun i => h (n−i))，h i = f (n+1+i) *)
    setoid_rewrite <- (sum_upto_rev (n + 1) (fun i => f (n + 1 + i)%nat)).
    (* n+1+(n−i) == 2n+1−i 只对 i ≤ n 成立——ext_below（i < n+1） *)
    rewrite (sum_upto_ext_below (n + 1) (fun i => f (n + 1 + (n + 1 - 1 - i))%nat) (fun i => f (2 * n + 1 - i)%nat)).
    2: { intros i Hi. assert (Hnat : (n + 1 + (n + 1 - 1 - i) = 2 * n + 1 - i)%nat) by lia.
         rewrite Hnat. reflexivity. }
    rewrite (sum_upto_ext_below (n + 1) (fun i => f (2 * n + 1 - i)%nat) f).
    2: { intros i Hi. apply Qeq_sym. apply (Hmir i). lia. }
    reflexivity. }
  setoid_rewrite Hsec.
  ring.
Qed.

(* 镜像对称（奇数项数）：f j == f (2n−j)（j ≤ n）⟹ Σ_{j=0}^{2n} f j == 2·Σ_{j=0}^{n−1} f j + f n *)
Lemma sum_upto_mirror_odd : forall (n : nat) (f : nat -> Q),
  (forall j, (j <= n)%nat -> f j == f (2 * n - j)%nat) ->
  sum_upto (2 * n + 1)%nat f == 2 * sum_upto n f + f n.
Proof.
  intros n f Hmir.
  (* 2n+1 == n+(n+1)：split *)
  assert (Hadd : (2 * n + 1 = n + (n + 1))%nat) by lia.
  rewrite (sum_upto_nat_eq (2 * n + 1)%nat (n + (n + 1)) f Hadd).
  setoid_rewrite (sum_upto_split_gen n (n + 1) f).
  (* 第二和：Σ_{i=0}^{n} f (n+i) == Σ_{i=0}^{n} f (2n−i) == Σ_{i=0}^{n} f i（镜像） *)
  assert (Hsec : sum_upto (n + 1) (fun i => f (n + i)%nat) == sum_upto (n + 1) f).
  { setoid_rewrite <- (sum_upto_rev (n + 1) (fun i => f (n + i)%nat)).
    rewrite (sum_upto_ext_below (n + 1) (fun i => f (n + (n + 1 - 1 - i))%nat) (fun i => f (2 * n - i)%nat)).
    2: { intros i Hi. assert (Hnat : (n + (n + 1 - 1 - i) = 2 * n - i)%nat) by lia.
         rewrite Hnat. reflexivity. }
    rewrite (sum_upto_ext_below (n + 1) (fun i => f (2 * n - i)%nat) f).
    2: { intros i Hi. apply Qeq_sym. apply (Hmir i). lia. }
    reflexivity. }
  setoid_rewrite Hsec.
  (* sum_upto (n+1) f == sum_upto n f + f n（n+1 非 S n 句法，nat_eq 桥接） *)
  assert (Hs : (n + 1 = Datatypes.S n)%nat) by lia.
  rewrite (sum_upto_nat_eq (n + 1)%nat (Datatypes.S n) f Hs).
  change (sum_upto (Datatypes.S n) f) with (sum_upto n f + f n).
  ring.
Qed.

(* ===== vander_4m2：a^{4m+2} 层 Vandermonde 恒等 =====
   Σ_{j=0}^{m−1} [−2/((4m+2−2j)!(2j)!) + 2/((4m+1−2j)!(2j+1)!)]
   == 2/((2m+2)!(2m)!) − 1/((2m+1)!(2m+1)!)
   证明路线：altf_zero (4m+2)（== 0）→ altf_as_sum_upto → 偶奇拆分
   → q_pow_neg1 奇偶归约 → 镜像对称（偶部×2、奇部×2+中项）→ 代数变形。
   核心：0 == 2·Σ_{j=0}^{m} E_j − (2·Σ_{j=0}^{m−1} O_j + O_m)
        ⟹ 2·Σ_{j=0}^{m−1}(O_j−E_j) == 2·E_m − O_m == RHS（分母交换）。 *)
Lemma vander_4m2 : forall (m : nat),
  (1 <= m)%nat ->
  sum_upto m
    (fun j =>
       - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))
       + 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1))) ==
  2 / (q_fact (2 * m + 2) * q_fact (2 * m)) -
  1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1)).
Proof.
  intros m Hm.
  (* 1. altf_zero (4m+2)：altf (4m+2) == 0；altf_as_sum_upto 转换 *)
  assert (Hz : altf (4 * m + 2) == 0).
  { apply altf_zero. lia. }
  setoid_rewrite (altf_as_sum_upto (4 * m + 2)) in Hz.
  (* 2. 偶奇拆分：sum_upto (4m+3) g == Σ_{j=0}^{2m+1} g (2j) + Σ_{j=0}^{2m} g (2j+1)
     先 nat_eq 把 Hz 的 sum_upto (4m+2+1) 换成 sum_upto (2(2m+1)+1)（非定义性） *)
  assert (Hn1 : (4 * m + 2 + 1 = 2 * (2 * m + 1) + 1)%nat) by lia.
  rewrite (sum_upto_nat_eq (4 * m + 2 + 1)%nat (2 * (2 * m + 1) + 1)%nat
            (fun u => q_pow (-1) u / (q_fact u * q_fact (4 * m + 2 - u))) Hn1) in Hz.
  rewrite (sum_upto_even_split_odd (2 * m + 1)
            (fun u => q_pow (-1) u / (q_fact u * q_fact (4 * m + 2 - u)))) in Hz.
  (* RHS 的 sum_upto (2m+1+1) == sum_upto (2m+2)（非定义性，nat_eq） *)
  assert (Hn2 : (2 * m + 1 + 1 = 2 * m + 2)%nat) by lia.
  rewrite (sum_upto_nat_eq (2 * m + 1 + 1)%nat (2 * m + 2)%nat
            (fun j => q_pow (-1) (2 * j) / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) Hn2) in Hz.
  (* 3. 逐点归约：g (2j) == 1/((2j)!(4m+2−2j)!)；g (2j+1) == −1/((2j+1)!(4m+1−2j)!) *)
  rewrite (sum_upto_ext (2 * m + 2)
            (fun j => q_pow (-1) (2 * j) / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))
            (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))) in Hz.
  2: { intro j. setoid_rewrite (q_pow_neg1_even j). ring. }
  rewrite (sum_upto_ext (2 * m + 1)
            (fun j => q_pow (-1) (2 * j + 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 2 - (2 * j + 1))))
            (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))) in Hz.
  2: { intro j. setoid_rewrite (q_pow_neg1_odd j).
       assert (Hn : (4 * m + 2 - (2 * j + 1) = 4 * m + 1 - 2 * j)%nat) by lia.
       setoid_replace (q_fact (4 * m + 2 - (2 * j + 1))) with (q_fact (4 * m + 1 - 2 * j)).
       2: { apply q_fact_nat_eq. lia. }
       ring. }
  (* 4. 镜像对称：偶部 Σ_{j=0}^{2m+1} E_j == 2·Σ_{j=0}^{m} E_j *)
  assert (HmirE : sum_upto (2 * m + 2)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) ==
           2 * sum_upto (m + 1)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))).
  { apply (sum_upto_mirror_even m
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))).
    intros j Hj.
    assert (H1 : (2 * (2 * m + 1 - j) = 4 * m + 2 - 2 * j)%nat) by lia.
    assert (H2 : (4 * m + 2 - 2 * (2 * m + 1 - j) = 2 * j)%nat) by lia.
    setoid_replace (q_fact (2 * (2 * m + 1 - j))) with (q_fact (4 * m + 2 - 2 * j)).
    2: { apply q_fact_nat_eq. exact H1. }
    setoid_replace (q_fact (4 * m + 2 - 2 * (2 * m + 1 - j))) with (q_fact (2 * j)).
    2: { apply q_fact_nat_eq. exact H2. }
    field.
    all: split; apply q_neq_of_lt; apply q_fact_pos. }
  (* 5. 镜像对称：奇部 Σ_{j=0}^{2m} O_j == 2·Σ_{j=0}^{m−1} O_j + O_m（O_m = −1/((2m+1)!(2m+1)!)） *)
  assert (HmirO : sum_upto (2 * m + 1)
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) ==
           2 * sum_upto m
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) +
           (- 1) / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
  { (* 用 mirror_odd 于 f（f j = -1/((2j+1)!(4m+1−2j)!)），产生 f m 项；
        先证 f m 的 q_fact 第二参数归约（4m+1−2m == 2m+1），替换后再用 mirror_odd *)
    assert (Hmid : (4 * m + 1 - 2 * m = 2 * m + 1)%nat) by lia.
    assert (Hfmid : - 1 / (q_fact (2 * m + 1) * q_fact (4 * m + 1 - 2 * m)) ==
                    - 1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
    { setoid_replace (q_fact (4 * m + 1 - 2 * m)) with (q_fact (2 * m + 1)).
      2: { apply q_fact_nat_eq. exact Hmid. }
      reflexivity. }
    (* 目标 = 2·Σ f + (-1)/((2m+1)!(2m+1)!)；f m = (-1)/((2m+1)!(4m+1−2m)!) == 目标末项 *)
    setoid_rewrite <- Hfmid.
    apply (sum_upto_mirror_odd m
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))).
    intros j Hj.
    assert (H1 : (2 * (2 * m - j) + 1 = 4 * m + 1 - 2 * j)%nat) by lia.
    assert (H2 : (4 * m + 1 - 2 * (2 * m - j) = 2 * j + 1)%nat) by lia.
    setoid_replace (q_fact (2 * (2 * m - j) + 1)) with (q_fact (4 * m + 1 - 2 * j)).
    2: { apply q_fact_nat_eq. exact H1. }
    setoid_replace (q_fact (4 * m + 1 - 2 * (2 * m - j))) with (q_fact (2 * j + 1)).
    2: { apply q_fact_nat_eq. exact H2. }
    field.
    all: split; apply q_neq_of_lt; apply q_fact_pos. }
  (* 6. 代入镜像：Hz == 2·Σ_{j=0}^{m} E_j − (2·Σ_{j=0}^{m−1} O_j + O_m) == 0 *)
  setoid_rewrite HmirE in Hz.
  setoid_rewrite HmirO in Hz.
  (* 7. 拆分 E 和：Σ_{j=0}^{m} E_j == Σ_{j=0}^{m−1} E_j + E_m，E_m = 1/((2m)!(2m+2)!) *)
  assert (HsplitE : sum_upto (m + 1)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) ==
            sum_upto m
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
           1 / (q_fact (2 * m) * q_fact (2 * m + 2))).
  { assert (Hs : (m + 1 = Datatypes.S m)%nat) by lia.
    rewrite (sum_upto_nat_eq (m + 1)%nat (Datatypes.S m)
              (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) Hs).
    change (sum_upto (Datatypes.S m)
              (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))) with
      (sum_upto m (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
       1 / (q_fact (2 * m) * q_fact (4 * m + 2 - 2 * m))).
    setoid_replace (q_fact (4 * m + 2 - 2 * m)) with (q_fact (2 * m + 2)).
    2: { apply q_fact_nat_eq. lia. }
    reflexivity. }
  setoid_rewrite HsplitE in Hz.
  (* 8. Hz 代数：Hz == 2·ΣE' + 2·Em − 2·ΣO'' − Om == 0（O'' = 1/((2j+1)!(4m+1−2j)!)）
        先用 HzO 把 Hz 里的 Σ(−1/X) 换成 −Σ(1/X)（sum_upto_neg + ext 逐点） *)
  assert (HzO : sum_upto m (fun j => (- 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) ==
                - sum_upto m (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))).
  { setoid_rewrite <- (sum_upto_neg m
             (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))).
    apply (sum_upto_ext m
             (fun j => (- 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))
             (fun j => - (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))))).
    intro j. unfold Qdiv. ring. }
  rewrite HzO in Hz.
  (* 9. Hz 移项（qeq_moved 模式）：2·ΣO'' − 2·ΣE' == 2·Em − Om
        用 Qopp_comp 于 Hz 取反（免句法），transitivity + ring *)
  assert (Hmoved : 2 * sum_upto m
                     (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) -
                    2 * sum_upto m
                      (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) ==
                   2 * (1 / (q_fact (2 * m) * q_fact (2 * m + 2))) -
                   1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
  { (* Hdiff : LHS - RHS == 0；LHS - RHS == -(Hz LHS)（ring）；-(Hz LHS) == 0（Hz 取反） *)
    assert (Hdiff : (2 * sum_upto m
                       (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) -
                      2 * sum_upto m
                        (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))) -
                     (2 * (1 / (q_fact (2 * m) * q_fact (2 * m + 2))) -
                      1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))) == 0).
    { (* Hdiff LHS == -A（ring）；-A == 0（Hz 取反）——A 用 set 从 Hz 提取（免句法） *)
      set (A := 2 * (sum_upto m
                       (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
                      1 / (q_fact (2 * m) * q_fact (2 * m + 2))) +
                  (2 * (- sum_upto m
                          (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))) +
                   (- 1) / (q_fact (2 * m + 1) * q_fact (2 * m + 1)))).
      change (A == 0) in Hz.
      transitivity (- A).
      - unfold A. unfold Qdiv. ring.
      - (* -A == 0：Qopp_comp A 0 Hz 给 -A == -0；-0 == 0（ring） *)
        assert (Hopp : - A == - 0).
        { apply (Qopp_comp A 0 Hz). }
        rewrite <- Hopp. unfold Qdiv. ring. }
    (* Hdiff : LHS - RHS == 0 ⟹ LHS == RHS（两边加 RHS，Qeq 移项） *)
    transitivity ((2 * sum_upto m
                     (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) -
                    2 * sum_upto m
                      (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))) -
                   (2 * (1 / (q_fact (2 * m) * q_fact (2 * m + 2))) -
                    1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))) +
                   (2 * (1 / (q_fact (2 * m) * q_fact (2 * m + 2))) -
                    1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1)))).
    - unfold Qdiv. ring.
    - rewrite Hdiff. ring. }
  (* 10. vander 目标 LHS == Σ(-2E + 2O)（原始）→ 需转成 -2ΣE' + 2ΣO''（sum_upto 线性）
        但当前目标是 vander 的原始陈述——先做线性转换 *)
  (* 目标：sum_upto m (fun j => -2/X_j + 2/Y_j) == 2/((2m+2)!(2m)!) - 1/((2m+1)!(2m+1)!)
     LHS 线性：Σ(-2E+2O) == -2ΣE' + 2ΣO''（sum_upto_ext 逐点 + 归纳线性） *)
  assert (Hlin : sum_upto m
                   (fun j => - 2 * (1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
                             2 * (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))) ==
                 - 2 * sum_upto m (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
                 2 * sum_upto m (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))).
  { rewrite (sum_upto_plus m
              (fun j => - 2 * (1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))))
              (fun j => 2 * (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))))).
    assert (Hsc1 : sum_upto m (fun j => - 2 * (1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))) ==
                  - 2 * sum_upto m (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))).
    { exact (sum_upto_scale_neg2 m (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))). }
    assert (Hsc2 : sum_upto m (fun j => 2 * (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))) ==
                  2 * sum_upto m (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))).
    { exact (sum_upto_scale m 2 (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j)))). }
    setoid_rewrite Hsc1. setoid_rewrite Hsc2. reflexivity. }
  (* vander LHS 逐点归一到 -2*(1/X') + 2*(1/Y')（分母交换） *)
  rewrite (sum_upto_ext m
            (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j)) +
                      2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1)))
            (fun j => - 2 * (1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j))) +
                      2 * (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))))).
  2: { intro j. unfold Qdiv. field.
       all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
            apply q_neq_of_lt; apply q_fact_pos. }
  setoid_rewrite Hlin.
  (* 目标：-2ΣE' + 2ΣO'' == 2/((2m+2)!(2m)!) - 1/((2m+1)!(2m+1)!)
     Hmoved : 2ΣO'' - 2ΣE' == 2Em' - Om'
     RHS：2Em' - Om' == 2/((2m+2)!(2m)!) - 1/((2m+1)!(2m+1)!)（分母交换，ring） *)
  setoid_replace (2 / (q_fact (2 * m + 2) * q_fact (2 * m)))
    with (2 * (1 / (q_fact (2 * m) * q_fact (2 * m + 2)))).
  2: { unfold Qdiv. field.
       all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
            apply q_neq_of_lt; apply q_fact_pos. }
  (* 目标：-2ΣE' + 2ΣO'' == 2Em' - Om'；用 Hmoved（LHS ring 等价） *)
  transitivity (2 * sum_upto m
                  (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 1 - 2 * j))) -
                2 * sum_upto m
                  (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 2 - 2 * j)))).
  - unfold Qdiv. ring.
  - exact Hmoved.
Qed.

(* ===== vander_4m4：a^{4m+4} 层 Vandermonde 恒等 =====
   Σ_{j=0}^{m−1} [−2/((4m+2−2j)!(2j+2)!) + 2/((4m+1−2j)!(2j+3)!)]
   + [−2/((4m+4)!(0)!) + 2/((4m+3)!(1)!)] == 1/((2m+2)!(2m+2)!)
   证明路线（同构 vander_4m2）：altf_zero (4m+4) → altf_as_sum_upto (4m+4)
   → 偶奇拆分（sum_upto (4m+5) = sum_upto (2(2m+2)+1)）→ q_pow_neg1 归约
   → 镜像（偶部×2、奇部×2，无中项）→ Qeq 移项（Qopp_comp 模式）。
   尾项 [−2/((4m+4)!(0)!) + 2/((4m+3)!(1)!)] 与 j=0 项合并：j=0 时
   −2/((4m+2)!(2)!) + 2/((4m+1)!(3)!) + 尾项——需整体配对。 *)
Lemma vander_4m4 : forall (m : nat),
  (1 <= m)%nat ->
  sum_upto m
    (fun j =>
       - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2))
       + 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))
  - 2 / (q_fact (4 * m + 4) * q_fact 0)
  + 2 / (q_fact (4 * m + 3) * q_fact 1) ==
  1 / (q_fact (2 * m + 2) * q_fact (2 * m + 2)).
Proof.
  intros m Hm.
  (* 1. altf_zero (4m+4)：altf (4m+4) == 0；altf_as_sum_upto 转换 *)
  assert (Hz : altf (4 * m + 4) == 0).
  { apply altf_zero. lia. }
  setoid_rewrite (altf_as_sum_upto (4 * m + 4)) in Hz.
  (* 2. 偶奇拆分：sum_upto (4m+5) g == Σ_{j=0}^{2m+2} g (2j) + Σ_{j=0}^{2m+1} g (2j+1)
     先 nat_eq 把 Hz 的 sum_upto (4m+4+1) 换成 sum_upto (2(2m+2)+1) *)
  assert (Hn1 : (4 * m + 4 + 1 = 2 * (2 * m + 2) + 1)%nat) by lia.
  rewrite (sum_upto_nat_eq (4 * m + 4 + 1)%nat (2 * (2 * m + 2) + 1)%nat
            (fun u => q_pow (-1) u / (q_fact u * q_fact (4 * m + 4 - u))) Hn1) in Hz.
  rewrite (sum_upto_even_split_odd (2 * m + 2)
            (fun u => q_pow (-1) u / (q_fact u * q_fact (4 * m + 4 - u)))) in Hz.
  assert (Hn2 : (2 * m + 2 + 1 = 2 * m + 3)%nat) by lia.
  rewrite (sum_upto_nat_eq (2 * m + 2 + 1)%nat (2 * m + 3)%nat
            (fun j => q_pow (-1) (2 * j) / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) Hn2) in Hz.
  (* 3. 逐点归约：g (2j) == 1/((2j)!(4m+4−2j)!)；g (2j+1) == −1/((2j+1)!(4m+3−2j)!) *)
  rewrite (sum_upto_ext (2 * m + 3)
            (fun j => q_pow (-1) (2 * j) / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j)))
            (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j)))) in Hz.
  2: { intro j. setoid_rewrite (q_pow_neg1_even j). ring. }
  rewrite (sum_upto_ext (2 * m + 2)
            (fun j => q_pow (-1) (2 * j + 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 4 - (2 * j + 1))))
            (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))) in Hz.
  2: { intro j. setoid_rewrite (q_pow_neg1_odd j).
       assert (Hn : (4 * m + 4 - (2 * j + 1) = 4 * m + 3 - 2 * j)%nat) by lia.
       setoid_replace (q_fact (4 * m + 4 - (2 * j + 1))) with (q_fact (4 * m + 3 - 2 * j)).
       2: { apply q_fact_nat_eq. lia. }
       ring. }
  (* 4. 镜像对称：
         偶部 sum_upto (2m+3) E（2m+3 项，j=0..2m+2）：mirror_odd n=m+1 ⟹ 2·Σ_{j=0}^{m} E_j + E_{m+1}
         奇部 sum_upto (2m+2) O（2m+2 项，j=0..2m+1）：mirror_even n=m ⟹ 2·Σ_{j=0}^{m} O_j *)
  assert (HmirE : sum_upto (2 * m + 3)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) ==
           2 * sum_upto (m + 1)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) +
           1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1)))).
  { (* mirror_odd (m+1) 结论：sum_upto (2(m+1)+1) f == 2·sum_upto (m+1) f + f (m+1)
         2(m+1)+1 == 2m+3 非句法同形——先 nat_eq 于目标 LHS 再 apply *)
    assert (Hidx : (2 * (m + 1) + 1 = 2 * m + 3)%nat) by lia.
    rewrite <- (sum_upto_nat_eq (2 * (m + 1) + 1)%nat (2 * m + 3)%nat
              (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) Hidx).
    apply (sum_upto_mirror_odd (m + 1)
             (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j)))).
    intros j Hj.
    assert (H1 : (2 * (2 * (m + 1) - j) = 4 * m + 4 - 2 * j)%nat) by lia.
    assert (H2 : (4 * m + 4 - 2 * (2 * (m + 1) - j) = 2 * j)%nat) by lia.
    setoid_replace (q_fact (2 * (2 * (m + 1) - j))) with (q_fact (4 * m + 4 - 2 * j)).
    2: { apply q_fact_nat_eq. exact H1. }
    setoid_replace (q_fact (4 * m + 4 - 2 * (2 * (m + 1) - j))) with (q_fact (2 * j)).
    2: { apply q_fact_nat_eq. exact H2. }
    field.
    all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
         apply q_neq_of_lt; apply q_fact_pos. }
  assert (HmirO : sum_upto (2 * m + 2)
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))) ==
           2 * sum_upto (m + 1)
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))).
  { apply (sum_upto_mirror_even m
             (fun j => - 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))).
    intros j Hj.
    assert (H1 : (2 * (2 * m + 1 - j) + 1 = 4 * m + 3 - 2 * j)%nat) by lia.
    assert (H2 : (4 * m + 3 - 2 * (2 * m + 1 - j) = 2 * j + 1)%nat) by lia.
    setoid_replace (q_fact (2 * (2 * m + 1 - j) + 1)) with (q_fact (4 * m + 3 - 2 * j)).
    2: { apply q_fact_nat_eq. exact H1. }
    setoid_replace (q_fact (4 * m + 3 - 2 * (2 * m + 1 - j))) with (q_fact (2 * j + 1)).
    2: { apply q_fact_nat_eq. exact H2. }
    field.
    all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
         apply q_neq_of_lt; apply q_fact_pos. }
  (* 5. 代入镜像：Hz == 偶部 + 奇部 == 0（q_pow_neg1 后 even − odd == 0）
         even == 2·Σ_{j=0}^{m} E_j + E_{m+1}，odd == 2·Σ_{j=0}^{m} O_j
         ⟹ (2Σ_{j=0}^{m} E_j + E_{m+1}) − 2Σ_{j=0}^{m} O_j == 0
         ⟹ 2Σ_{j=0}^{m} O_j − 2Σ_{j=0}^{m} E_j == E_{m+1} == 1/((2m+2)!(2m+2)!) *)
  (* Hz 是 even + odd 形态（O 带负号）：(2ΣE + E_{m+1}) + (2ΣO') == 0，O' = -1/X *)
  setoid_rewrite HmirE in Hz.
  setoid_rewrite HmirO in Hz.
  (* Hz 里 O 部分是 2·Σ(-1/X)——先用 HzO 模式归约负号 *)
  assert (HzO : sum_upto (m + 1) (fun j => (- 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))) ==
                - sum_upto (m + 1) (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))).
  { setoid_rewrite <- (sum_upto_neg (m + 1)
             (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))).
    apply (sum_upto_ext (m + 1)
             (fun j => (- 1) / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))
             (fun j => - (1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))))).
    intro j. unfold Qdiv. ring. }
  rewrite HzO in Hz.
  (* Hz（E_{m+1} 归约）：2·Σ_{j=0}^{m} E_j + E_{m+1} − 2·Σ_{j=0}^{m} O_j == 0 *)
  (* E_{m+1} = 1/((2m+2)!(2m+2)!)——set 提取 + change 验证 + Qeq 移项 *)
  set (A := 2 * (sum_upto m
                    (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) +
                   1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1)))) +
             (2 * (- sum_upto m
                     (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j)))))).
  (* Hz 的 LHS 是否 == A：change 验证 *)
  (* 注意 Hz 的 O 部分经 HzO 后是 2·(-ΣO_j)，E 部分是 2·(ΣE_j + E_{m+1}) *)
  (* 由于 Hz 结构可能不同，先打印/用 change 尝试 *)
  (* 直接构造 Hmoved：2ΣO − 2ΣE == E_{m+1}（Qeq 移项模式） *)
  assert (Hmoved : 2 * sum_upto (m + 1)
                     (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))) -
                    2 * sum_upto (m + 1)
                      (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) ==
                   1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1)))).
  { (* Hz : 2·ΣE + E_{m+1} + 2·(-ΣO) == 0（HzO 后）
         Hmoved : 2ΣO - 2ΣE == E_{m+1}
         用 qeq_moved_neg2 于 (A=2ΣE, B=E_{m+1}, C=ΣO)：
         A + B + 2*(-C) == 0 ⟹ 2C - A == B——前提恰是 Hz（ring 等价：Hz 是 2ΣE + E_{m+1} + 2*(-ΣO) == 0） *)
    apply (qeq_moved_neg2
             (2 * sum_upto (m + 1) (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))))
             (1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1))))
             (sum_upto (m + 1) (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))))).
    (* 需证：2ΣE + E_{m+1} + 2*(-ΣO) == 0——Hz 的 ring 等价（transitivity 于 Hz LHS） *)
    transitivity (2 * sum_upto (m + 1)
                    (fun j => 1 / (q_fact (2 * j) * q_fact (4 * m + 4 - 2 * j))) +
                   1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1))) +
                   2 * (- sum_upto (m + 1)
                          (fun j => 1 / (q_fact (2 * j + 1) * q_fact (4 * m + 3 - 2 * j))))).
    - unfold Qdiv. ring.
    - exact Hz. }
  (* 6. vander LHS == −2·Σ_{k=0}^{m} E_k + 2·Σ_{k=0}^{m} O_k（E''_j=E_{j+1} 换元 + 尾项合并）
         目标 LHS：sum_upto m (fun j => -2/((4m+2−2j)!(2j+2)!) + 2/((4m+1−2j)!(2j+3)!))
         − 2/((4m+4)!(0)!) + 2/((4m+3)!(1)!)
         == -2·Σ_{k=1}^{m} E_k + 2·Σ_{k=1}^{m} O_k − 2·E_0 + 2·O_0
         == -2·Σ_{k=0}^{m} E_k + 2·Σ_{k=0}^{m} O_k
         而 Hmoved : 2Σ_{0}^{m}O − 2Σ_{0}^{m}E == E_{m+1}
         且 E_{m+1} == 1/((2m+2)!(2m+2)!)（分母交换） *)
  (* vander LHS 换元：sum_upto_ext 于 j，E''_j 换 E_{j+1} 形态（先写分母同形） *)
  assert (Hlin : sum_upto m
                   (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)) +
                             2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3))) ==
                 - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2))) +
                 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
  { rewrite (sum_upto_plus m
              (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))
              (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
    assert (Hsc1 : sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2))) ==
                   - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))).
    { rewrite (sum_upto_ext m
                (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))
                (fun j => - 2 * (1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2))))).
      2: { intro j. unfold Qdiv. ring. }
      apply (sum_upto_scale_neg2 m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))). }
    assert (Hsc2 : sum_upto m (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3))) ==
                   2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
    { rewrite (sum_upto_ext m
                (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))
                (fun j => 2 * (1 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3))))).
      2: { intro j. unfold Qdiv. ring. }
      apply (sum_upto_scale m 2 (fun j => 1 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))). }
    setoid_rewrite Hsc1. setoid_rewrite Hsc2.
    reflexivity. }
  (* Hlin 的 RHS 项换元到 E/O（k=j+1）：1/((2j+2)!(4m+2−2j)!) == E_{j+1} 等——需 sum_upto_ext *)
  (* 目标最终：-2Σ_{j=0}^{m}E_{j+1} + 2Σ_{j=0}^{m}O_{j+1} - 2E_0 + 2O_0 == 1/((2m+2)!(2m+2)!)
     而 Hmoved : 2Σ_{0}^{m}O_j - 2Σ_{0}^{m}E_j == E_{m+1}
     E_{j+1} vs E_j 差一索引——需换元 sum_upto_ext (fun j => E_{j+1}) 为 sum_upto m ... *)
  (* 这一步较繁：vander LHS 的 Σ_{j=0}^{m-1} 是 m 项（j=0..m-1），而 Hmoved 的 Σ_{j=0}^{m} 是 m+1 项
     vander LHS = -2Σ_{j=0}^{m-1}E''_j + 2Σ_{j=0}^{m-1}O''_j + tail
                = -2Σ_{k=1}^{m}E_k + 2Σ_{k=1}^{m}O_k - 2E_0 + 2O_0
                = -2Σ_{k=0}^{m}E_k + 2Σ_{k=0}^{m}O_k
     与 Hmoved 完全对齐 ✓ *)
  (* 收尾：vander LHS == -2Σ_{k=0}^{m}E_k + 2Σ_{k=0}^{m}O_k == Hmoved LHS == E_{m+1} == RHS *)
  setoid_rewrite Hlin.
  (* 目标：-2·Σ_{j=0}^{m-1}(1/E''_j) + 2·Σ_{j=0}^{m-1}(1/O''_j) - 2/((4m+4)!0!) + 2/((4m+3)!1!) == RHS
     E''_j = 1/((4m+2-2j)!(2j+2)!)，O''_j = 1/((4m+1-2j)!(2j+3)!) *)
  (* 换元：E''_j == E_{j+1}（E_k = 1/((4m+4-2k)!(2k)!)），sum_upto_shift 于 E 部分 *)
  assert (HshiftE : sum_upto m (fun j => 1 / (q_fact (4 * m + 4 - 2 * (j + 1)) * q_fact (2 * (j + 1)))) ==
                    sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k))) -
                    1 / (q_fact (4 * m + 4 - 2 * 0) * q_fact (2 * 0))).
  { apply (sum_upto_shift m (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k)))). }
  (* 目标 LHS 的 E 部分：-2·Σ(1/E''_j)（负号在 sum 外）——对 sum 内部 ext 换元 E''_j → E_{j+1} *)
  rewrite (sum_upto_ext m
            (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))
            (fun j => 1 / (q_fact (4 * m + 4 - 2 * (j + 1)) * q_fact (2 * (j + 1))))).
  2: { intro j. assert (H1 : (4 * m + 4 - 2 * (j + 1) = 4 * m + 2 - 2 * j)%nat) by lia.
       assert (H2 : (2 * (j + 1) = 2 * j + 2)%nat) by lia.
       setoid_replace (q_fact (4 * m + 4 - 2 * (j + 1))) with (q_fact (4 * m + 2 - 2 * j)).
       2: { apply q_fact_nat_eq. exact H1. }
       setoid_replace (q_fact (2 * (j + 1))) with (q_fact (2 * j + 2)).
       2: { apply q_fact_nat_eq. exact H2. }
       reflexivity. }
  rewrite (sum_upto_ext m
            (fun j => 1 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))
            (fun j => 1 / (q_fact (4 * m + 3 - 2 * (j + 1)) * q_fact (2 * (j + 1) + 1)))).
  2: { intro j. assert (H1 : (4 * m + 3 - 2 * (j + 1) = 4 * m + 1 - 2 * j)%nat) by lia.
       assert (H2 : (2 * (j + 1) + 1 = 2 * j + 3)%nat) by lia.
       setoid_replace (q_fact (4 * m + 3 - 2 * (j + 1))) with (q_fact (4 * m + 1 - 2 * j)).
       2: { apply q_fact_nat_eq. exact H1. }
       setoid_replace (q_fact (2 * (j + 1) + 1)) with (q_fact (2 * j + 3)).
       2: { apply q_fact_nat_eq. exact H2. }
       reflexivity. }
  (* 尾项并入：-2/((4m+4)!·0!) == -2·(1/((4m+4-2·0)!(2·0)!)) = -2·E_0 项；+2/((4m+3)!·1!) == +2·O_0 项
     目标：-2·Σ_{j=0}^{m-1}(1/E_{j+1}) + 2·Σ_{j=0}^{m-1}(1/O_{j+1}) - 2·E_0 + 2·O_0 == RHS
     用 HshiftE：Σ_{j=0}^{m-1}(1/E_{j+1}) == Σ_{k=0}^{m}(1/E_k) - E_0（E_0 = 1/((4m+4)!·0!)） *)
  setoid_replace (sum_upto m (fun j => 1 / (q_fact (4 * m + 4 - 2 * (j + 1)) * q_fact (2 * (j + 1)))))
    with (sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k))) -
           1 / (q_fact (4 * m + 4 - 2 * 0) * q_fact (2 * 0))).
  2: { exact HshiftE. }
  (* 目标：-2·(Σ_{k=0}^{m}(1/E_k) - E_0) + 2·Σ_{j=0}^{m-1}(1/O_{j+1}) - 2·E_0 + 2·O_0 == RHS
     O 部分同样 shift：Σ_{j=0}^{m-1}(1/O_{j+1}) == Σ_{k=0}^{m}(1/O_k) - O_0 *)
  assert (HshiftO : sum_upto m (fun j => 1 / (q_fact (4 * m + 3 - 2 * (j + 1)) * q_fact (2 * (j + 1) + 1))) ==
                    sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1))) -
                    1 / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1))).
  { apply (sum_upto_shift m (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1)))). }
  setoid_replace (sum_upto m (fun j => 1 / (q_fact (4 * m + 3 - 2 * (j + 1)) * q_fact (2 * (j + 1) + 1))))
    with (sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1))) -
           1 / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1))).
  2: { exact HshiftO. }
  (* 目标：-2·(ΣE_k - E_0) + 2·(ΣO_k - O_0) - 2·E_0 + 2·O_0 == RHS
     ⟹ -2·ΣE_k + 2E_0 + 2·ΣO_k - 2O_0 - 2E_0 + 2O_0 == -2ΣE_k + 2ΣO_k == RHS（ring 消 E_0/O_0） *)
  (* 归约 E_0/O_0 字面：E_0 = 1/((4m+4)!·0!)、O_0 = 1/((4m+3)!·1!)——与尾项相同（ring） *)
  (* 目标现在是：-2·(Σ_{k=0}^{m}(1/E_k) - 1/E_0) + 2·(Σ_{k=0}^{m}(1/O_k) - 1/O_0) - 2/((4m+4)!·0!) + 2/((4m+3)!·1!) == RHS
     ring 展开：-2ΣE + 2/E_0 + 2ΣO - 2/O_0 - 2/E_0 + 2/O_0 == -2ΣE + 2ΣO（E_0/O_0 抵消） *)
  (* 用 Hmoved：2ΣO - 2ΣE == E_{m+1}；E_{m+1} == 1/((2m+2)!(2m+2)!)（分母交换） *)
  transitivity (2 * sum_upto (m + 1)
                  (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1))) -
                2 * sum_upto (m + 1)
                  (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k)))).
  - (* 目标 LHS == 2ΣO - 2ΣE（E_0/O_0 抵消）——assert 独立探针目标后 exact（找差异） *)
    assert (Htmp : - 2 * (sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k))) +
                          - (1 / (q_fact (4 * m + 4) * q_fact 0))) +
                   2 * (sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1))) -
                          (1 / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1)))) -
                   2 / (q_fact (4 * m + 4) * q_fact 0) +
                   2 / (q_fact (4 * m + 3) * q_fact 1) ==
                   2 * sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1))) -
                   2 * sum_upto (m + 1) (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k)))).
    { unfold Qminus. unfold Qdiv.
      (* O_0 字面归约：change 于整个 1/(...) 项（可转换：4m+3-2·0 == 4m+3、2·0+1 == 1） *)
      change (1 / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1)))
        with (1 / (q_fact (4 * m + 3) * q_fact 1)).
      (* ring_simplify 分配 -2*(Σ+...) 并归约 1*x，再 ring（E_0/O_0 抵消） *)
      ring_simplify.
      (* ring_simplify 后 O_0 是 2*/(q_fact (4m+3-2*0) * q_fact (2*0+1)) 未归约——change 归约 *)
      (* O_0 项：-2 * / (q_fact (4m+3-2*0) * q_fact (2*0+1))——setoid_replace 归约整体（Qinv Proper） *)
      setoid_replace (- 2 * / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1)))
        with (- 2 * / (q_fact (4 * m + 3) * q_fact 1)).
      2: { setoid_replace (q_fact (4 * m + 3 - 2 * 0)) with (q_fact (4 * m + 3)).
           2: { apply q_fact_nat_eq. lia. }
           setoid_replace (q_fact (2 * 0 + 1)) with (q_fact 1).
           2: { apply q_fact_nat_eq. lia. }
           reflexivity. }
      ring. }
    (* vander 目标的 E_0/O_0 未归约（1/(q_fact (4m+4-2*0) * q_fact (2*0)) 等）——先归约再 exact Htmp *)
    setoid_replace (1 / (q_fact (4 * m + 4 - 2 * 0) * q_fact (2 * 0)))
      with (1 / (q_fact (4 * m + 4) * q_fact 0)).
    2: { setoid_replace (q_fact (4 * m + 4 - 2 * 0)) with (q_fact (4 * m + 4)).
         2: { apply q_fact_nat_eq. lia. }
         setoid_replace (q_fact (2 * 0)) with (q_fact 0).
         2: { apply q_fact_nat_eq. lia. }
         reflexivity. }
    setoid_replace (1 / (q_fact (4 * m + 3 - 2 * 0) * q_fact (2 * 0 + 1)))
      with (1 / (q_fact (4 * m + 3) * q_fact 1)).
    2: { setoid_replace (q_fact (4 * m + 3 - 2 * 0)) with (q_fact (4 * m + 3)).
         2: { apply q_fact_nat_eq. lia. }
         setoid_replace (q_fact (2 * 0 + 1)) with (q_fact 1).
         2: { apply q_fact_nat_eq. lia. }
         reflexivity. }
    unfold Qminus. unfold Qdiv.
    ring_simplify.
    ring.
  - (* 2ΣO - 2ΣE == E_{m+1}（Hmoved） *)
    transitivity (1 / (q_fact (2 * (m + 1)) * q_fact (4 * m + 4 - 2 * (m + 1)))).
    + (* 目标 LHS 的 O 部分换序（(4m+3-2k)!(2k+1)! -> (2k+1)!(4m+3-2k)!，匹配 Hmoved） *)
      { rewrite (sum_upto_ext (m + 1)
                  (fun k => 1 / (q_fact (4 * m + 3 - 2 * k) * q_fact (2 * k + 1)))
                  (fun k => 1 / (q_fact (2 * k + 1) * q_fact (4 * m + 3 - 2 * k)))).
        2: { intro k. field.
             all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
                  apply q_neq_of_lt; apply q_fact_pos. }
        rewrite (sum_upto_ext (m + 1)
                  (fun k => 1 / (q_fact (4 * m + 4 - 2 * k) * q_fact (2 * k)))
                  (fun k => 1 / (q_fact (2 * k) * q_fact (4 * m + 4 - 2 * k)))).
        2: { intro k. field.
             all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
                  apply q_neq_of_lt; apply q_fact_pos. }
        exact Hmoved. }
    + (* E_{m+1} == RHS：分母交换 1/((2m+2)!(2m+2)!) == 1/((2(m+1))!(4m+4−2(m+1))!) *)
      { assert (Hmid : (2 * (m + 1) = 2 * m + 2)%nat) by lia.
        assert (Hmid2 : (4 * m + 4 - 2 * (m + 1) = 2 * m + 2)%nat) by lia.
        setoid_replace (q_fact (2 * (m + 1))) with (q_fact (2 * m + 2)).
        2: { apply q_fact_nat_eq. exact Hmid. }
        setoid_replace (q_fact (4 * m + 4 - 2 * (m + 1))) with (q_fact (2 * m + 2)).
        2: { apply q_fact_nat_eq. exact Hmid2. }
        reflexivity. }
Qed.

End QExpEOSplit.
(* ============ 配对战役（备份 92 合入，来自 _dbg_kdr.v 探针全绿） ============
   row_pair_main：行差分闭合（分层组装：a^{4m+6} 抵消 + vander_4m2/4m4 + 低层 refl）
   ksum_diff_row：corr 差分 == RHS（corr_diff_expand + 换元 + row_pair_main）——配对战役收官 *)
Lemma esq_row_nat_eq2 : forall (N i1 i2 : nat) (a : Q),
  i1 = i2 -> esq_row N i1 a == esq_row N i2 a.
Proof. intros. subst. reflexivity. Qed.

Lemma sum_upto_opp2 : forall (n : nat) (f : nat -> Q),
  sum_upto n (fun j => - (2 * f j)) == - (2 * sum_upto n f).
Proof.
  intros n f.
  induction n as [| n' IH]; simpl.
  - ring.
  - setoid_rewrite IH. ring.
Qed.

Lemma esq_pair : forall (m j : nat) (a : Q), (j < m)%nat ->
  - 2 * esq_row (2 * m + 1 - (j + 1)) (j + 1 + 2) a
  + 2 * esq_row (2 * m - j) (j + 1) a ==
  - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))
  - 2 * q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)).
Proof.
  intros m j a Hj.
  assert (Ha : (2 * m + 1 - (j + 1) = 2 * m - j)%nat) by lia.
  assert (Hb : (j + 1 + 2 = j + 3)%nat) by lia.
  rewrite Ha. rewrite Hb.
  (* esq_row (2m−j) (j+3) == esq_row (2m−j) (j+1) + T_{j+2} + T_{j+3}（esq_row_succ 两次） *)
  assert (Hexp : esq_row (2 * m - j) (j + 3) a ==
          esq_row (2 * m - j) (j + 1) a +
          q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 1)) / (q_fact (2 * (2 * m - j)) * q_fact (2 * Datatypes.S (j + 1))) +
          q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 2)) / (q_fact (2 * (2 * m - j)) * q_fact (2 * Datatypes.S (j + 2)))).
  { assert (Hn : (j + 3 = Datatypes.S (j + 2))%nat) by lia.
    rewrite Hn.
    rewrite (esq_row_succ (2 * m - j) (j + 2)).
    setoid_replace (esq_row (2 * m - j) (j + 2) a) with (esq_row (2 * m - j) (Datatypes.S (j + 1)) a).
    2: { apply esq_row_nat_eq2. lia. }
    rewrite (esq_row_succ (2 * m - j) (j + 1)).
    reflexivity. }
  rewrite Hexp.
  (* T_{j+2} == q_pow a (4m+4)/((4m−2j)!(2j+4)!)：q_pow/q_fact 参数归约 *)
  assert (Ht2 : q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 1)) / (q_fact (2 * (2 * m - j)) * q_fact (2 * Datatypes.S (j + 1))) ==
                q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))).
  { setoid_replace (q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 1))) with (q_pow a (4 * m + 4)).
    2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m - j) + 2 * Datatypes.S (j + 1))%nat (4 * m + 4)%nat). lia. }
    setoid_replace (q_fact (2 * (2 * m - j))) with (q_fact (4 * m - 2 * j)).
    2: { apply q_fact_nat_eq. lia. }
    setoid_replace (q_fact (2 * Datatypes.S (j + 1))) with (q_fact (2 * j + 4)).
    2: { apply q_fact_nat_eq. lia. }
    reflexivity. }
  (* T_{j+3} == q_pow a (4m+6)/((4m−2j)!(2j+6)!) *)
  assert (Ht3 : q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 2)) / (q_fact (2 * (2 * m - j)) * q_fact (2 * Datatypes.S (j + 2))) ==
                q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))).
  { setoid_replace (q_pow a (2 * (2 * m - j) + 2 * Datatypes.S (j + 2))) with (q_pow a (4 * m + 6)).
    2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m - j) + 2 * Datatypes.S (j + 2))%nat (4 * m + 6)%nat). lia. }
    setoid_replace (q_fact (2 * (2 * m - j))) with (q_fact (4 * m - 2 * j)).
    2: { apply q_fact_nat_eq. lia. }
    setoid_replace (q_fact (2 * Datatypes.S (j + 2))) with (q_fact (2 * j + 6)).
    2: { apply q_fact_nat_eq. lia. }
    reflexivity. }
  setoid_rewrite Ht2.
  setoid_rewrite Ht3.
  unfold Qdiv in *. ring.
Qed.

Lemma osq_pair : forall (m j : nat) (a : Q), (j < m)%nat ->
  2 * osq_row (2 * m - (j + 1)) (j + 1 + 1) a
  - 2 * osq_row (2 * m - 1 - j) j a ==
  2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))
  + 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)).
Proof.
  intros m j a Hj.
  assert (Ha : (2 * m - (j + 1) = 2 * m - 1 - j)%nat) by lia.
  assert (Hb : (j + 1 + 1 = j + 2)%nat) by lia.
  rewrite Ha. rewrite Hb.
  (* osq_row (2m−1−j) (j+2) == osq_row (2m−1−j) j + T'_{j+1} + T'_{j+2}（osq_row_succ 两次） *)
  assert (Hexp : osq_row (2 * m - 1 - j) (j + 2) a ==
          osq_row (2 * m - 1 - j) j a +
          q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S j + 2) / (q_fact (2 * (2 * m - 1 - j) + 1) * q_fact (2 * Datatypes.S j + 1)) +
          q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S (j + 1) + 2) / (q_fact (2 * (2 * m - 1 - j) + 1) * q_fact (2 * Datatypes.S (j + 1) + 1))).
  { assert (Hn : (j + 2 = Datatypes.S (j + 1))%nat) by lia.
    rewrite Hn.
    rewrite (osq_row_succ (2 * m - 1 - j) (j + 1)).
    setoid_replace (osq_row (2 * m - 1 - j) (j + 1) a) with (osq_row (2 * m - 1 - j) (Datatypes.S j) a).
    2: { apply osq_row_nat_eq2. lia. }
    rewrite (osq_row_succ (2 * m - 1 - j) j).
    reflexivity. }
  rewrite Hexp.
  (* T'_{j+1} == q_pow a (4m+2)/((4m−1−2j)!(2j+3)!) *)
  assert (Ht2 : q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S j + 2) / (q_fact (2 * (2 * m - 1 - j) + 1) * q_fact (2 * Datatypes.S j + 1)) ==
                q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))).
  { setoid_replace (q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S j + 2)) with (q_pow a (4 * m + 2)).
    2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m - 1 - j) + 2 * Datatypes.S j + 2)%nat (4 * m + 2)%nat). lia. }
    setoid_replace (q_fact (2 * (2 * m - 1 - j) + 1)) with (q_fact (4 * m - 1 - 2 * j)).
    2: { apply q_fact_nat_eq. lia. }
    setoid_replace (q_fact (2 * Datatypes.S j + 1)) with (q_fact (2 * j + 3)).
    2: { apply q_fact_nat_eq. lia. }
    reflexivity. }
  (* T'_{j+2} == q_pow a (4m+4)/((4m−1−2j)!(2j+5)!) *)
  assert (Ht3 : q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S (j + 1) + 2) / (q_fact (2 * (2 * m - 1 - j) + 1) * q_fact (2 * Datatypes.S (j + 1) + 1)) ==
                q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))).
  { setoid_replace (q_pow a (2 * (2 * m - 1 - j) + 2 * Datatypes.S (j + 1) + 2)) with (q_pow a (4 * m + 4)).
    2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m - 1 - j) + 2 * Datatypes.S (j + 1) + 2)%nat (4 * m + 4)%nat). lia. }
    setoid_replace (q_fact (2 * (2 * m - 1 - j) + 1)) with (q_fact (4 * m - 1 - 2 * j)).
    2: { apply q_fact_nat_eq. lia. }
    setoid_replace (q_fact (2 * Datatypes.S (j + 1) + 1)) with (q_fact (2 * j + 5)).
    2: { apply q_fact_nat_eq. lia. }
    reflexivity. }
  setoid_rewrite Ht2.
  setoid_rewrite Ht3.
  unfold Qdiv in *. ring.
Qed.

Lemma esq_row_diff_closed : forall (m : nat) (a : Q), (1 <= m)%nat ->
  sum_upto m (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a
                      + 2 * esq_row (2 * m - j) (j + 1) a) ==
  2 * esq_row (m + 1) m a - 2 * esq_row (2 * m + 1) 2 a
  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))).
Proof.
  intros m a Hm.
  assert (Hm1 : ((m - 1) + 1 = m)%nat) by lia.
  assert (Hms : (m = Datatypes.S (m - 1))%nat) by lia.
  (* ① 拆分 f = esq- + esq+ *)
  rewrite (sum_upto_plus m
            (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a)
            (fun j => 2 * esq_row (2 * m - j) (j + 1) a)).
  (* ② Σ esq- == esq-@0 + Σ_{j<m−1} esq-@(j+1)（sum_upto_shift 移首项） *)
  assert (Hsh : sum_upto m (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a) ==
                (- 2 * esq_row (2 * m + 1) 2 a) +
                sum_upto (m - 1) (fun j => - 2 * esq_row (2 * m + 1 - (j + 1)) ((j + 1) + 2) a)).
  { rewrite (sum_upto_nat_eq m ((m - 1) + 1)
              (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a) (eq_sym Hm1)).
    setoid_rewrite (sum_upto_shift (m - 1)
                      (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a)).
    assert (Hf0 : (fun k : nat => - 2 * esq_row (2 * m + 1 - k) (k + 2) a) 0%nat ==
                  - 2 * esq_row (2 * m + 1) 2 a).
    { change ((fun k : nat => - 2 * esq_row (2 * m + 1 - k) (k + 2) a) 0%nat) with
        (- 2 * esq_row (2 * m + 1 - 0) (0 + 2) a).
      assert (Hn1 : (2 * m + 1 - 0 = 2 * m + 1)%nat) by lia.
      assert (Hn2 : (0 + 2 = 2)%nat) by lia.
      rewrite Hn1. rewrite Hn2.
      reflexivity. }
    setoid_rewrite Hf0.
    unfold Qminus. ring. }
  (* ③ Σ esq+ == Σ_{j<m−1} esq+@j + esq+@(m−1)（拆末项） *)
  assert (Hsl : sum_upto m (fun j => 2 * esq_row (2 * m - j) (j + 1) a) ==
                sum_upto (m - 1) (fun j => 2 * esq_row (2 * m - j) (j + 1) a) +
                2 * esq_row (2 * m - (m - 1)) (m - 1 + 1) a).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => 2 * esq_row (2 * m - j) (j + 1) a) Hms).
    reflexivity. }
  (* ④ 替换 + 重组（ring 证 Hre，把 ΣA' 与 ΣB 并拢） *)
  setoid_rewrite Hsh.
  setoid_rewrite Hsl.
  assert (Hre : ((- 2 * esq_row (2 * m + 1) 2 a) +
                 sum_upto (m - 1) (fun j => - 2 * esq_row (2 * m + 1 - (j + 1)) ((j + 1) + 2) a)) +
                (sum_upto (m - 1) (fun j => 2 * esq_row (2 * m - j) (j + 1) a) +
                 2 * esq_row (2 * m - (m - 1)) (m - 1 + 1) a) ==
                (- 2 * esq_row (2 * m + 1) 2 a) +
                (2 * esq_row (2 * m - (m - 1)) (m - 1 + 1) a) +
                (sum_upto (m - 1) (fun j => - 2 * esq_row (2 * m + 1 - (j + 1)) ((j + 1) + 2) a) +
                 sum_upto (m - 1) (fun j => 2 * esq_row (2 * m - j) (j + 1) a))).
  { ring. }
  setoid_rewrite Hre.
  setoid_rewrite <- (sum_upto_plus (m - 1)
                      (fun j => - 2 * esq_row (2 * m + 1 - (j + 1)) ((j + 1) + 2) a)
                      (fun j => 2 * esq_row (2 * m - j) (j + 1) a)).
  (* ⑤ 逐点 esq_pair（配对和 → −2·T4 − 2·T6） *)
  setoid_rewrite (sum_upto_ext_below (m - 1)
                    (fun j => - 2 * esq_row (2 * m + 1 - (j + 1)) ((j + 1) + 2) a
                            + 2 * esq_row (2 * m - j) (j + 1) a)
                    (fun j => - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))
                            - 2 * q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
  2: { intros j Hj. apply (esq_pair m j a). lia. }
  (* ⑥ 提出 −2（逐点 (-2·a)/D == -2·(a/D)，再 sum_upto_plus/scale） *)
  assert (Hstep4 : forall j, - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)) ==
                            - 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))).
  { intro j. unfold Qdiv. ring. }
  assert (Hstep6 : forall j, - 2 * q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)) ==
                            - 2 * (q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
  { intro j. unfold Qdiv. ring. }
  assert (Hsum : sum_upto (m - 1) (fun j =>
                    - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))
                    - 2 * q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))) ==
                  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
  { setoid_rewrite (sum_upto_ext_below (m - 1)
                      (fun j => - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))
                              - 2 * q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
                      (fun j => - 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                              - 2 * (q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))))).
    2: { intros j Hj. unfold Qdiv. ring. }
    setoid_rewrite (sum_upto_plus (m - 1)
                      (fun j => - 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))))
                      (fun j => - (2 * (q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))))).
    setoid_rewrite (sum_upto_scale_neg2 (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))).
    setoid_rewrite (sum_upto_opp2 (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
    ring. }
  setoid_rewrite Hsum.
  (* ⑦ 末项归约：esq+@(m−1) == 2·esq_row (m+1) m *)
  assert (Hma : (2 * m - (m - 1) = m + 1)%nat) by lia.
  assert (Hmb : (m - 1 + 1 = m)%nat) by lia.
  rewrite Hma. rewrite Hmb.
  (* ⑧ ring 组装 *)
  unfold Qdiv in *. ring.
Qed.

Lemma osq_row_diff_closed : forall (m : nat) (a : Q), (1 <= m)%nat ->
  sum_upto m (fun j => 2 * osq_row (2 * m - j) (j + 1) a
                      - 2 * osq_row (2 * m - 1 - j) j a) ==
  - 2 * osq_row m (m - 1) a + 2 * osq_row (2 * m) 1 a
  + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
  + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))).
Proof.
  intros m a Hm.
  assert (Hm1 : ((m - 1) + 1 = m)%nat) by lia.
  assert (Hms : (m = Datatypes.S (m - 1))%nat) by lia.
  (* ① 拆分 f = osq+ + osq-（目标 LHS 是 A - B 记法 == A + Qopp B，g 用 Qopp 形态） *)
  rewrite (sum_upto_plus m
            (fun j => 2 * osq_row (2 * m - j) (j + 1) a)
            (fun j => - (2 * osq_row (2 * m - 1 - j) j a))).
  (* ② Σ osq+ == osq+@0 + Σ_{j<m−1} osq+@(j+1)（sum_upto_shift 移首项） *)
  assert (Hsh : sum_upto m (fun j => 2 * osq_row (2 * m - j) (j + 1) a) ==
                (2 * osq_row (2 * m) 1 a) +
                sum_upto (m - 1) (fun j => 2 * osq_row (2 * m - (j + 1)) ((j + 1) + 1) a)).
  { rewrite (sum_upto_nat_eq m ((m - 1) + 1)
              (fun j => 2 * osq_row (2 * m - j) (j + 1) a) (eq_sym Hm1)).
    setoid_rewrite (sum_upto_shift (m - 1)
                      (fun j => 2 * osq_row (2 * m - j) (j + 1) a)).
    assert (Hf0 : (fun k : nat => 2 * osq_row (2 * m - k) (k + 1) a) 0%nat ==
                  2 * osq_row (2 * m) 1 a).
    { change ((fun k : nat => 2 * osq_row (2 * m - k) (k + 1) a) 0%nat) with
        (2 * osq_row (2 * m - 0) (0 + 1) a).
      assert (Hn1 : (2 * m - 0 = 2 * m)%nat) by lia.
      assert (Hn2 : (0 + 1 = 1)%nat) by lia.
      rewrite Hn1. rewrite Hn2.
      reflexivity. }
    setoid_rewrite Hf0.
    unfold Qminus. ring. }
  (* ③ Σ osq- == Σ_{j<m−1} osq-@j + osq-@(m−1)（拆末项） *)
  assert (Hsl : sum_upto m (fun j => - (2 * osq_row (2 * m - 1 - j) j a)) ==
                sum_upto (m - 1) (fun j => - (2 * osq_row (2 * m - 1 - j) j a)) +
                (- (2 * osq_row (2 * m - 1 - (m - 1)) (m - 1) a))).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => - (2 * osq_row (2 * m - 1 - j) j a)) Hms).
    reflexivity. }
  (* ④ 替换 + 重组 *)
  setoid_rewrite Hsh.
  setoid_rewrite Hsl.
  assert (Hre : ((2 * osq_row (2 * m) 1 a) +
                 sum_upto (m - 1) (fun j => 2 * osq_row (2 * m - (j + 1)) ((j + 1) + 1) a)) +
                (sum_upto (m - 1) (fun j => - (2 * osq_row (2 * m - 1 - j) j a)) +
                 (- (2 * osq_row (2 * m - 1 - (m - 1)) (m - 1) a))) ==
                (2 * osq_row (2 * m) 1 a) +
                (- (2 * osq_row (2 * m - 1 - (m - 1)) (m - 1) a)) +
                (sum_upto (m - 1) (fun j => 2 * osq_row (2 * m - (j + 1)) ((j + 1) + 1) a) +
                 sum_upto (m - 1) (fun j => - (2 * osq_row (2 * m - 1 - j) j a)))).
  { ring. }
  setoid_rewrite Hre.
  setoid_rewrite <- (sum_upto_plus (m - 1)
                      (fun j => 2 * osq_row (2 * m - (j + 1)) ((j + 1) + 1) a)
                      (fun j => - (2 * osq_row (2 * m - 1 - j) j a))).
  (* ⑤ 逐点 osq_pair（配对和 → 2·T'_{4m+2} + 2·T'_{4m+4}） *)
  setoid_rewrite (sum_upto_ext_below (m - 1)
                    (fun j => 2 * osq_row (2 * m - (j + 1)) ((j + 1) + 1) a
                            - 2 * osq_row (2 * m - 1 - j) j a)
                    (fun j => 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))
                            + 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
  2: { intros j Hj. apply (osq_pair m j a). lia. }
  (* ⑥ 提出 2（逐点 (2·a)/D == 2·(a/D)，再 sum_upto_plus/scale） *)
  assert (Hstep2 : forall j, 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)) ==
                            2 * (q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))).
  { intro j. unfold Qdiv. ring. }
  assert (Hstep4 : forall j, 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)) ==
                            2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
  { intro j. unfold Qdiv. ring. }
  assert (Hsum : sum_upto (m - 1) (fun j =>
                    2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))
                    + 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))) ==
                  2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                  + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
  { setoid_rewrite (sum_upto_ext_below (m - 1)
                      (fun j => 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))
                              + 2 * q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                      (fun j => 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                              + 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))))).
    2: { intros j Hj. unfold Qdiv. ring. }
    setoid_rewrite (sum_upto_plus (m - 1)
                      (fun j => 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))))
                      (fun j => 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))))).
    setoid_rewrite (sum_upto_scale (m - 1) 2 (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))).
    setoid_rewrite (sum_upto_scale (m - 1) 2 (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
    ring. }
  setoid_rewrite Hsum.
  (* ⑦ 末项归约：osq-@(m−1) == −2·osq_row m (m−1) *)
  assert (Hma : (2 * m - 1 - (m - 1) = m)%nat) by lia.
  rewrite Hma.
  (* ⑧ ring 组装 *)
  unfold Qdiv in *. ring.
Qed.

Lemma row_pair_esq2_expand : forall (m : nat) (a : Q),
  esq_row (2 * m + 1) 2 a ==
  q_pow a (4 * m + 2) / (q_fact (4 * m + 2) * q_fact 0) +
  q_pow a (4 * m + 4) / (q_fact (4 * m + 2) * q_fact 2) +
  q_pow a (4 * m + 6) / (q_fact (4 * m + 2) * q_fact 4).
Proof.
  intros m a.
  rewrite (esq_row_succ (2 * m + 1) 1).
  rewrite (esq_row_succ (2 * m + 1) 0).
  change (esq_row (2 * m + 1) 0 a) with
    (q_pow a (2 * (2 * m + 1)) / (q_fact (2 * (2 * m + 1)) * q_fact 0)).
  assert (Hn0 : (2 * (2 * m + 1) = 4 * m + 2)%nat) by lia.
  assert (Hn1 : (2 * (2 * m + 1) + 2 * Datatypes.S 0 = 4 * m + 4)%nat) by lia.
  assert (Hn2 : (2 * (2 * m + 1) + 2 * Datatypes.S 1 = 4 * m + 6)%nat) by lia.
  assert (Hf1 : (2 * Datatypes.S 0 = 2)%nat) by lia.
  assert (Hf2 : (2 * Datatypes.S 1 = 4)%nat) by lia.
  setoid_replace (q_pow a (2 * (2 * m + 1))) with (q_pow a (4 * m + 2)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m + 1))%nat (4 * m + 2)%nat). exact Hn0. }
  setoid_replace (q_pow a (2 * (2 * m + 1) + 2 * Datatypes.S 0)) with (q_pow a (4 * m + 4)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m + 1) + 2 * Datatypes.S 0)%nat (4 * m + 4)%nat). exact Hn1. }
  setoid_replace (q_pow a (2 * (2 * m + 1) + 2 * Datatypes.S 1)) with (q_pow a (4 * m + 6)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m + 1) + 2 * Datatypes.S 1)%nat (4 * m + 6)%nat). exact Hn2. }
  setoid_replace (q_fact (2 * (2 * m + 1))) with (q_fact (4 * m + 2)).
  2: { apply q_fact_nat_eq. exact Hn0. }
  setoid_replace (q_fact (2 * Datatypes.S 0)) with (q_fact 2).
  2: { apply q_fact_nat_eq. exact Hf1. }
  setoid_replace (q_fact (2 * Datatypes.S 1)) with (q_fact 4).
  2: { apply q_fact_nat_eq. exact Hf2. }
  reflexivity.
Qed.

Lemma row_pair_osq1_expand : forall (m : nat) (a : Q),
  osq_row (2 * m) 1 a ==
  q_pow a (4 * m + 2) / (q_fact (4 * m + 1) * q_fact 1) +
  q_pow a (4 * m + 4) / (q_fact (4 * m + 1) * q_fact 3).
Proof.
  intros m a.
  rewrite (osq_row_succ (2 * m) 0).
  change (osq_row (2 * m) 0 a) with
    (q_pow a (2 * (2 * m) + 2) / (q_fact (2 * (2 * m) + 1) * q_fact 1)).
  assert (Hn0 : (2 * (2 * m) + 2 = 4 * m + 2)%nat) by lia.
  assert (Hn1 : (2 * (2 * m) + 2 * Datatypes.S 0 + 2 = 4 * m + 4)%nat) by lia.
  assert (Hf1 : (2 * (2 * m) + 1 = 4 * m + 1)%nat) by lia.
  assert (Hf2 : (2 * Datatypes.S 0 + 1 = 3)%nat) by lia.
  setoid_replace (q_pow a (2 * (2 * m) + 2)) with (q_pow a (4 * m + 2)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m) + 2)%nat (4 * m + 2)%nat). exact Hn0. }
  setoid_replace (q_pow a (2 * (2 * m) + 2 * Datatypes.S 0 + 2)) with (q_pow a (4 * m + 4)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * (2 * m) + 2 * Datatypes.S 0 + 2)%nat (4 * m + 4)%nat). exact Hn1. }
  setoid_replace (q_fact (2 * (2 * m) + 1)) with (q_fact (4 * m + 1)).
  2: { apply q_fact_nat_eq. exact Hf1. }
  setoid_replace (q_fact (2 * Datatypes.S 0 + 1)) with (q_fact 3).
  2: { apply q_fact_nat_eq. exact Hf2. }
  reflexivity.
Qed.

Lemma row_pair_tail_expand : forall (m : nat) (a : Q),
  - 2 * esq_row (2 * m + 2) 1 a + 2 * osq_row (2 * m + 1) 0 a +
  2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 4) * q_fact 2) ==
  - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 4) * q_fact 0) +
  2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 3) * q_fact 1).
Proof.
  intros m a.
  rewrite (esq_row_succ (2 * m + 2) 0).
  change (esq_row (2 * m + 2) 0 a) with
    (q_pow a (2 * (2 * m + 2)) / (q_fact (2 * (2 * m + 2)) * q_fact 0)).
  change (osq_row (2 * m + 1) 0 a) with
    (q_pow a (2 * (2 * m + 1) + 2) / (q_fact (2 * (2 * m + 1) + 1) * q_fact 1)).
  assert (Hn1 : (2 * (2 * m + 2) = 4 * m + 4)%nat) by lia.
  assert (Hn2 : (2 * (2 * m + 2) + 2 * Datatypes.S 0 = 4 * m + 6)%nat) by lia.
  assert (Hn3 : (2 * (2 * m + 1) + 2 = 4 * m + 4)%nat) by lia.
  assert (Hf2 : (2 * Datatypes.S 0 = 2)%nat) by lia.
  assert (Hf3 : (2 * (2 * m + 1) + 1 = 4 * m + 3)%nat) by lia.
  (* 参数替换用 Leibniz rewrite（setoid_replace 的转换匹配会误伤 Q 数字 2 ≡ q_fact 2） *)
  rewrite Hn2. rewrite Hf2. rewrite Hn1. rewrite Hn3. rewrite Hf3.
  unfold Qdiv in *. ring.
Qed.

Lemma row_pair_high6 : forall (m : nat), (1 <= m)%nat ->
  - 2 / (q_fact (4 * m + 2) * q_fact 4)
  - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
  + 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))
  == 0.
Proof.
  intros m Hm.
  assert (Hm1 : ((m - 1) + 1 = m)%nat) by lia.
  set (f' := fun j : nat => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))).
  assert (Hf0 : f' 0%nat == 1 / (q_fact (4 * m + 2) * q_fact 4)).
  { unfold f'. change (1 / (q_fact (4 * m + 2 - 2 * 0) * q_fact (2 * 0 + 4)) ==
                       1 / (q_fact (4 * m + 2) * q_fact 4)).
    assert (Ha : (4 * m + 2 - 2 * 0 = 4 * m + 2)%nat) by lia.
    assert (Hb : (2 * 0 + 4 = 4)%nat) by lia.
    setoid_replace (q_fact (4 * m + 2 - 2 * 0)) with (q_fact (4 * m + 2)).
    2: { apply q_fact_nat_eq. exact Ha. }
    setoid_replace (q_fact (2 * 0 + 4)) with (q_fact 4).
    2: { apply q_fact_nat_eq. exact Hb. }
    reflexivity. }
  assert (Hfs : forall j, f' (j + 1)%nat ==
                          1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))).
  { intro j. unfold f'.
    change (1 / (q_fact (4 * m + 2 - 2 * (j + 1)) * q_fact (2 * (j + 1) + 4)) ==
            1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))).
    assert (Ha : (4 * m + 2 - 2 * (j + 1) = 4 * m - 2 * j)%nat) by lia.
    assert (Hb : (2 * (j + 1) + 4 = 2 * j + 6)%nat) by lia.
    setoid_replace (q_fact (4 * m + 2 - 2 * (j + 1))) with (q_fact (4 * m - 2 * j)).
    2: { apply q_fact_nat_eq. exact Ha. }
    setoid_replace (q_fact (2 * (j + 1) + 4)) with (q_fact (2 * j + 6)).
    2: { apply q_fact_nat_eq. exact Hb. }
    reflexivity. }
  assert (Hsplit : sum_upto m f' == f' 0%nat + sum_upto (m - 1) (fun j => f' (j + 1)%nat)).
  { rewrite (sum_upto_nat_eq m ((m - 1) + 1) f' (eq_sym Hm1)).
    assert (Hshift : sum_upto (m - 1) (fun j => f' (j + 1)%nat) ==
                     sum_upto ((m - 1) + 1) f' - f' 0%nat).
    { apply (sum_upto_shift (m - 1) f'). }
    setoid_rewrite Hshift.
    unfold Qminus. ring. }
  setoid_rewrite Hsplit.
  setoid_rewrite (sum_upto_ext_below (m - 1) (fun j => f' (j + 1)%nat)
                   (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
  2: { intros j Hj. apply (Hfs j). }
  setoid_rewrite Hf0.
  unfold Qdiv in *. unfold Qminus. ring.
Qed.

Lemma row_pair_mid4 : forall (m : nat), (1 <= m)%nat ->
  - 2 / (q_fact (4 * m + 2) * q_fact 2)
  - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
  + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
  + 2 / (q_fact (4 * m + 1) * q_fact 3)
  - 2 / (q_fact (4 * m + 4) * q_fact 0)
  + 2 / (q_fact (4 * m + 3) * q_fact 1)
  == 1 / (q_fact (2 * m + 2) * q_fact (2 * m + 2)).
Proof.
  intros m Hm.
  assert (Hms : (m = Datatypes.S (m - 1))%nat) by lia.
  (* H1：前两项 → Σ_{j<m} −2/((4m+2−2j)!(2j+2)!) *)
  assert (H1 : - 2 / (q_fact (4 * m + 2) * q_fact 2)
               - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))) ==
               sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2))) Hms).
    rewrite (sum_upto_rot (m - 1) (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))).
    assert (Hg0 : - 2 / (q_fact (4 * m + 2 - 2 * 0) * q_fact (2 * 0 + 2)) ==
                  - 2 / (q_fact (4 * m + 2) * q_fact 2)).
    { assert (Ha : (4 * m + 2 - 2 * 0 = 4 * m + 2)%nat) by lia.
      assert (Hb : (2 * 0 + 2 = 2)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    assert (Hgs : forall j, - 2 / (q_fact (4 * m + 2 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 2)) ==
                           - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))).
    { intro j. assert (Ha : (4 * m + 2 - 2 * Datatypes.S j = 4 * m - 2 * j)%nat) by lia.
      assert (Hb : (2 * Datatypes.S j + 2 = 2 * j + 4)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => - 2 / (q_fact (4 * m + 2 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 2)))
       (fun j => - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))).
    2: { intros j Hj. apply (Hgs j). }
    setoid_rewrite Hg0.
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
       (fun j => - 2 * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))))).
    2: { intros j Hj. unfold Qdiv. ring. }
    setoid_rewrite (sum_upto_scale_neg2 (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))).
    unfold Qdiv in *. unfold Qminus. ring. }
  (* H2：2·Σ_{j<m−1} 1/((4m−1−2j)!(2j+5)!) + 2/((4m+1)!(3)!) → Σ_{j<m} 2/((4m+1−2j)!(2j+3)!) *)
  assert (H2 : 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
               + 2 / (q_fact (4 * m + 1) * q_fact 3) ==
               sum_upto m (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3))) Hms).
    rewrite (sum_upto_rot (m - 1) (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
    assert (Hg0 : 2 / (q_fact (4 * m + 1 - 2 * 0) * q_fact (2 * 0 + 3)) ==
                  2 / (q_fact (4 * m + 1) * q_fact 3)).
    { assert (Ha : (4 * m + 1 - 2 * 0 = 4 * m + 1)%nat) by lia.
      assert (Hb : (2 * 0 + 3 = 3)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    assert (Hgs : forall j, 2 / (q_fact (4 * m + 1 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 3)) ==
                           2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))).
    { intro j. assert (Ha : (4 * m + 1 - 2 * Datatypes.S j = 4 * m - 1 - 2 * j)%nat) by lia.
      assert (Hb : (2 * Datatypes.S j + 3 = 2 * j + 5)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => 2 / (q_fact (4 * m + 1 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 3)))
       (fun j => 2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
    2: { intros j Hj. apply (Hgs j). }
    setoid_rewrite Hg0.
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => 2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
       (fun j => 2 * (1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))))).
    2: { intros j Hj. unfold Qdiv. ring. }
    setoid_rewrite (sum_upto_scale (m - 1) 2 (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
    unfold Qdiv in *. unfold Qminus. ring. }
  (* 组装：先重组（ring 证 Hre，把 H1/H2 的 LHS 并拢为连续子项），再替换 + vander_4m4 *)
  assert (Hre : - 2 / (q_fact (4 * m + 2) * q_fact 2)
                - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                + 2 / (q_fact (4 * m + 1) * q_fact 3)
                - 2 / (q_fact (4 * m + 4) * q_fact 0)
                + 2 / (q_fact (4 * m + 3) * q_fact 1) ==
                (- 2 / (q_fact (4 * m + 2) * q_fact 2)
                 - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))))
                + (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                   + 2 / (q_fact (4 * m + 1) * q_fact 3))
                - 2 / (q_fact (4 * m + 4) * q_fact 0)
                + 2 / (q_fact (4 * m + 3) * q_fact 1)).
  { unfold Qminus. ring. }
  setoid_rewrite Hre.
  setoid_rewrite H1.
  setoid_rewrite H2.
  setoid_rewrite <- (sum_upto_plus m
                      (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 2)))
                      (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 3)))).
  apply (vander_4m4 m Hm).
Qed.

Lemma row_pair_mid2 : forall (m : nat), (1 <= m)%nat ->
  - 2 / (q_fact (4 * m + 2) * q_fact 0)
  + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
  + 2 / (q_fact (4 * m + 1) * q_fact 1)
  - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))
  == - 1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1)).
Proof.
  intros m Hm.
  assert (Hms : (m = Datatypes.S (m - 1))%nat) by lia.
  (* H1：中间两项 → Σ_{j<m} 2/((4m+1−2j)!(2j+1)!) *)
  assert (H1 : 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
               + 2 / (q_fact (4 * m + 1) * q_fact 1) ==
               sum_upto m (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1)))).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1))) Hms).
    rewrite (sum_upto_rot (m - 1) (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1)))).
    assert (Hg0 : 2 / (q_fact (4 * m + 1 - 2 * 0) * q_fact (2 * 0 + 1)) ==
                  2 / (q_fact (4 * m + 1) * q_fact 1)).
    { assert (Ha : (4 * m + 1 - 2 * 0 = 4 * m + 1)%nat) by lia.
      assert (Hb : (2 * 0 + 1 = 1)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    assert (Hgs : forall j, 2 / (q_fact (4 * m + 1 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 1)) ==
                           2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))).
    { intro j. assert (Ha : (4 * m + 1 - 2 * Datatypes.S j = 4 * m - 1 - 2 * j)%nat) by lia.
      assert (Hb : (2 * Datatypes.S j + 1 = 2 * j + 3)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => 2 / (q_fact (4 * m + 1 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j + 1)))
       (fun j => 2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))).
    2: { intros j Hj. apply (Hgs j). }
    setoid_rewrite Hg0.
    setoid_rewrite (sum_upto_ext_below (m - 1)
       (fun j => 2 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
       (fun j => 2 * (1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))))).
    2: { intros j Hj. unfold Qdiv. ring. }
    setoid_rewrite (sum_upto_scale (m - 1) 2 (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))).
    unfold Qdiv in *. unfold Qminus. ring. }
  (* H2：首项 + T 和的 −2·Σ → Σ_{j<m} −2/((4m+2−2j)!(2j)!) − 2/((2m+2)!(2m)!) *)
  assert (Htail : sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) ==
                  sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) +
                  1 / (q_fact (2 * m + 2) * q_fact (2 * m))).
  { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
              (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) Hms).
    change (sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) +
            1 / (q_fact (4 * m - 2 * (m - 1)) * q_fact (2 * (m - 1) + 2)) ==
            sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) +
            1 / (q_fact (2 * m + 2) * q_fact (2 * m))).
    assert (Htm : 1 / (q_fact (4 * m - 2 * (m - 1)) * q_fact (2 * (m - 1) + 2)) ==
                  1 / (q_fact (2 * m + 2) * q_fact (2 * m))).
    { assert (Ha : (4 * m - 2 * (m - 1) = 2 * m + 2)%nat) by lia.
      assert (Hb : (2 * (m - 1) + 2 = 2 * m)%nat) by lia.
      rewrite Ha. rewrite Hb. reflexivity. }
    setoid_rewrite Htm. reflexivity. }
  assert (H2 : - 2 / (q_fact (4 * m + 2) * q_fact 0)
               - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) ==
               sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))) -
               2 / (q_fact (2 * m + 2) * q_fact (2 * m))).
  { setoid_rewrite Htail.
    assert (Hpre : - 2 / (q_fact (4 * m + 2) * q_fact 0)
                   - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) ==
                   sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j)))).
    { rewrite (sum_upto_nat_eq m (Datatypes.S (m - 1))
                (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))) Hms).
      rewrite (sum_upto_rot (m - 1) (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j)))).
      assert (Hg0 : - 2 / (q_fact (4 * m + 2 - 2 * 0) * q_fact (2 * 0)) ==
                    - 2 / (q_fact (4 * m + 2) * q_fact 0)).
      { assert (Ha : (4 * m + 2 - 2 * 0 = 4 * m + 2)%nat) by lia.
        assert (Hb : (2 * 0 = 0)%nat) by lia.
        rewrite Ha. rewrite Hb. reflexivity. }
      assert (Hgs : forall j, - 2 / (q_fact (4 * m + 2 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j)) ==
                             - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))).
      { intro j. assert (Ha : (4 * m + 2 - 2 * Datatypes.S j = 4 * m - 2 * j)%nat) by lia.
        assert (Hb : (2 * Datatypes.S j = 2 * j + 2)%nat) by lia.
        rewrite Ha. rewrite Hb. reflexivity. }
      setoid_rewrite (sum_upto_ext_below (m - 1)
         (fun j => - 2 / (q_fact (4 * m + 2 - 2 * Datatypes.S j) * q_fact (2 * Datatypes.S j)))
         (fun j => - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
      2: { intros j Hj. apply (Hgs j). }
      setoid_rewrite Hg0.
      setoid_rewrite (sum_upto_ext_below (m - 1)
         (fun j => - 2 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))
         (fun j => - 2 * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale_neg2 (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    assert (Hdist : - 2 / (q_fact (4 * m + 2) * q_fact 0)
                    - 2 * (sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) +
                           1 / (q_fact (2 * m + 2) * q_fact (2 * m))) ==
                    (- 2 / (q_fact (4 * m + 2) * q_fact 0)
                     - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))
                    - 2 / (q_fact (2 * m + 2) * q_fact (2 * m))).
    { unfold Qdiv in *. unfold Qminus. ring. }
    setoid_rewrite Hdist.
    setoid_rewrite Hpre.
    unfold Qdiv in *. unfold Qminus. ring. }
  (* 组装：H1/H2 替换后 == vander_4m2 LHS − 2/((2m+2)!(2m)!) == −1/((2m+1)!(2m+1)!) *)
  assert (Hre : - 2 / (q_fact (4 * m + 2) * q_fact 0)
                + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                + 2 / (q_fact (4 * m + 1) * q_fact 1)
                - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) ==
                (- 2 / (q_fact (4 * m + 2) * q_fact 0)
                 - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))
                + (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                   + 2 / (q_fact (4 * m + 1) * q_fact 1))).
  { unfold Qdiv in *. unfold Qminus. ring. }
  setoid_rewrite Hre.
  setoid_rewrite H2.
  setoid_rewrite H1.
  assert (Hre2 : (sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))) -
                  2 / (q_fact (2 * m + 2) * q_fact (2 * m))) +
                 sum_upto m (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1))) ==
                 (sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))) +
                  sum_upto m (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1))))
                 - 2 / (q_fact (2 * m + 2) * q_fact (2 * m))).
  { unfold Qdiv in *. unfold Qminus. ring. }
  setoid_rewrite Hre2.
  setoid_rewrite <- (sum_upto_plus m
                      (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j)))
                      (fun j => 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1)))).
  assert (Hv : sum_upto m (fun j => - 2 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j))
                               + 2 / (q_fact (4 * m + 1 - 2 * j) * q_fact (2 * j + 1))) ==
               2 / (q_fact (2 * m + 2) * q_fact (2 * m)) -
               1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
  { apply (vander_4m2 m Hm). }
  setoid_rewrite Hv.
  unfold Qdiv in *. unfold Qminus. ring.
Qed.

Lemma row_pair_main : forall (a : Q) (m : nat), (1 <= m)%nat ->
  sum_upto m
    (fun j =>
       - 2 * esq_row (2 * m + 1 - j) (j + 2) a
       + 2 * esq_row (2 * m - j) (j + 1) a
       + 2 * osq_row (2 * m - j) (j + 1) a
       - 2 * osq_row (2 * m - 1 - j) j a
       + 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
       - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))
  - 2 * esq_row (2 * m + 2) 1 a
  + 2 * osq_row (2 * m + 1) 0 a
  + 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 4) * q_fact 2) ==
  2 * esq_row (Datatypes.S m) m a +
  (q_pow a (4 * m + 4) / (q_fact (2 * m + 2) * q_fact (2 * m + 2))) -
  2 * osq_row m (m - 1) a -
  (q_pow a (4 * m + 2) / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
Proof.
  intros a m Hm.
  (* ① 行差(j) 逐点重排为 esq(j) + osq(j) + T(j)，再拆三份 *)
  setoid_rewrite (sum_upto_ext_below m
    (fun j =>
       - 2 * esq_row (2 * m + 1 - j) (j + 2) a
       + 2 * esq_row (2 * m - j) (j + 1) a
       + 2 * osq_row (2 * m - j) (j + 1) a
       - 2 * osq_row (2 * m - 1 - j) j a
       + 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
       - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))
    (fun j =>
       (- 2 * esq_row (2 * m + 1 - j) (j + 2) a + 2 * esq_row (2 * m - j) (j + 1) a) +
       (2 * osq_row (2 * m - j) (j + 1) a - 2 * osq_row (2 * m - 1 - j) j a) +
       (2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
        - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
  2: { intros j Hj. unfold Qminus. ring. }
  setoid_rewrite (sum_upto_plus m
    (fun j => (- 2 * esq_row (2 * m + 1 - j) (j + 2) a + 2 * esq_row (2 * m - j) (j + 1) a) +
              (2 * osq_row (2 * m - j) (j + 1) a - 2 * osq_row (2 * m - 1 - j) j a))
    (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
              - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
  setoid_rewrite (sum_upto_plus m
    (fun j => - 2 * esq_row (2 * m + 1 - j) (j + 2) a + 2 * esq_row (2 * m - j) (j + 1) a)
    (fun j => 2 * osq_row (2 * m - j) (j + 1) a - 2 * osq_row (2 * m - 1 - j) j a)).
  (* ② 闭合公式替换（esq/osq 行差和） *)
  setoid_rewrite (esq_row_diff_closed m a Hm).
  setoid_rewrite (osq_row_diff_closed m a Hm).
  (* ③ esq_row (m+1) m == esq_row (S m) m（共同项） *)
  assert (Hm1 : (m + 1 = Datatypes.S m)%nat) by lia.
  assert (Heq : esq_row (m + 1) m a == esq_row (Datatypes.S m) m a).
  { rewrite Hm1. reflexivity. }
  setoid_rewrite Heq.
  (* ④ 展开 esq_row(2m+1)2、osq_row(2m)1（尾项在 Hmov 重组后再展开——左结合前缀使 tail 三项不连续） *)
  setoid_rewrite (row_pair_esq2_expand m a).
  setoid_rewrite (row_pair_osq1_expand m a).
  (* ④b' 拆 ΣT 为 Σ(2·q6/D6') + Σ(-(2·q2/D2'))（Hmov 分层需要分开的两个和） *)
  setoid_rewrite (sum_upto_plus m
    (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))
    (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
  (* ⑤ Hmov：重组为 2·esqSm − 2·osqmm + R6 + R4 + R2（R6/R4/R2 按层分组，tail 原子在 R4 末尾） *)
  assert (Hmov : 2 * esq_row (Datatypes.S m) m a -
                 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 2) * q_fact 0) +
                      q_pow a (4 * m + 4) / (q_fact (4 * m + 2) * q_fact 2) +
                      q_pow a (4 * m + 6) / (q_fact (4 * m + 2) * q_fact 4)) -
                 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))) -
                 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))) +
                 (- 2 * osq_row m (m - 1) a +
                  2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 1) * q_fact 1) +
                       q_pow a (4 * m + 4) / (q_fact (4 * m + 1) * q_fact 3)) +
                  2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))) +
                  2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))) +
                 (sum_upto m (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))) +
                  sum_upto m (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))) -
                 2 * esq_row (2 * m + 2) 1 a + 2 * osq_row (2 * m + 1) 0 a +
                 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 4) * q_fact 2) ==
                 2 * esq_row (Datatypes.S m) m a - 2 * osq_row m (m - 1) a +
                 (- 2 * (q_pow a (4 * m + 6) / (q_fact (4 * m + 2) * q_fact 4))
                  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
                  + sum_upto m (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))) +
                 (- 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 2) * q_fact 2))
                  - 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                  + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                  + 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 1) * q_fact 3))
                  + (- 2 * esq_row (2 * m + 2) 1 a + 2 * osq_row (2 * m + 1) 0 a +
                     2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 4) * q_fact 2))) +
                 (- 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 2) * q_fact 0))
                  + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                  + 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 1) * q_fact 1))
                  + sum_upto m (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))))).
  { unfold Qdiv in *. unfold Qminus. ring. }
  setoid_rewrite Hmov.
  (* ⑥ 展开尾项（R4 内连续） *)
  setoid_rewrite (row_pair_tail_expand m a).
  (* ⑦ 分层断言：R6 == 0、R4 == Te²、R2 == −To² *)
  assert (H6 : - 2 * (q_pow a (4 * m + 6) / (q_fact (4 * m + 2) * q_fact 4))
               + (- (2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))))
               + sum_upto m (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))
               == 0).
  { assert (Hc : - 2 / (q_fact (4 * m + 2) * q_fact 4)
                 - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
                 + 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))) == 0).
    { apply (row_pair_high6 m Hm). }
    assert (H1' : - 2 * (q_pow a (4 * m + 6) / (q_fact (4 * m + 2) * q_fact 4)) ==
                  q_pow a (4 * m + 6) * (- 2 / (q_fact (4 * m + 2) * q_fact 4))).
    { unfold Qdiv. ring. }
    assert (H2' : - (2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))) ==
                  q_pow a (4 * m + 6) * (- 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))))).
    { setoid_rewrite (sum_upto_ext_below (m - 1)
        (fun j => q_pow a (4 * m + 6) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
        (fun j => q_pow a (4 * m + 6) * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale (m - 1) (q_pow a (4 * m + 6)) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    assert (H3' : sum_upto m (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))) ==
                  q_pow a (4 * m + 6) * (2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))))).
    { setoid_rewrite (sum_upto_ext_below m
        (fun j => 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))
        (fun j => 2 * (q_pow a (4 * m + 6) * (1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_ext_below m
        (fun j => 2 * (q_pow a (4 * m + 6) * (1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))))
        (fun j => q_pow a (4 * m + 6) * (2 * (1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))))).
      2: { intros j Hj. ring. }
       setoid_rewrite (sum_upto_scale m (q_pow a (4 * m + 6)) (fun j => 2 * (1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))))).
      setoid_rewrite (sum_upto_scale m 2 (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))).
      ring. }
    setoid_rewrite H1'. setoid_rewrite H2'. setoid_rewrite H3'.
    assert (Hfac : q_pow a (4 * m + 6) * (- 2 / (q_fact (4 * m + 2) * q_fact 4)) +
                   q_pow a (4 * m + 6) * (- 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))) +
                   q_pow a (4 * m + 6) * (2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4)))) ==
                   q_pow a (4 * m + 6) * (- 2 / (q_fact (4 * m + 2) * q_fact 4)
                                          - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 6)))
                                          + 2 * sum_upto m (fun j => 1 / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))))).
    { ring. }
    setoid_rewrite Hfac.
    setoid_rewrite Hc.
    unfold Qdiv in *. unfold Qminus. ring. }
  assert (H4 : - 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 2) * q_fact 2))
               + (- (2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))))
               + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
               + 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 1) * q_fact 3))
               + (- 2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 4) * q_fact 0) +
                  2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 3) * q_fact 1)) ==
               q_pow a (4 * m + 4) / (q_fact (2 * m + 2) * q_fact (2 * m + 2))).
  { assert (Hc : - 2 / (q_fact (4 * m + 2) * q_fact 2)
                 - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                 + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                 + 2 / (q_fact (4 * m + 1) * q_fact 3)
                 - 2 / (q_fact (4 * m + 4) * q_fact 0)
                 + 2 / (q_fact (4 * m + 3) * q_fact 1) ==
                 1 / (q_fact (2 * m + 2) * q_fact (2 * m + 2))).
    { apply (row_pair_mid4 m Hm). }
    assert (H1' : - 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 2) * q_fact 2)) ==
                  q_pow a (4 * m + 4) * (- 2 / (q_fact (4 * m + 2) * q_fact 2))).
    { unfold Qdiv. ring. }
    assert (H2' : - (2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))) ==
                  q_pow a (4 * m + 4) * (- 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))))).
    { setoid_rewrite (sum_upto_ext_below (m - 1)
        (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
        (fun j => q_pow a (4 * m + 4) * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale (m - 1) (q_pow a (4 * m + 4)) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    assert (H3' : 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))) ==
                  q_pow a (4 * m + 4) * (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))))).
    { setoid_rewrite (sum_upto_ext_below (m - 1)
        (fun j => q_pow a (4 * m + 4) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
        (fun j => q_pow a (4 * m + 4) * (1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale (m - 1) (q_pow a (4 * m + 4)) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    assert (H4' : 2 * (q_pow a (4 * m + 4) / (q_fact (4 * m + 1) * q_fact 3)) ==
                  q_pow a (4 * m + 4) * (2 / (q_fact (4 * m + 1) * q_fact 3))).
    { unfold Qdiv. ring. }
    assert (H5' : - 2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 4) * q_fact 0) +
                  2 * q_pow a (4 * m + 4) / (q_fact (4 * m + 3) * q_fact 1) ==
                  q_pow a (4 * m + 4) * (- 2 / (q_fact (4 * m + 4) * q_fact 0) +
                                         2 / (q_fact (4 * m + 3) * q_fact 1))).
    { unfold Qdiv. ring. }
    setoid_rewrite H1'. setoid_rewrite H2'. setoid_rewrite H3'. setoid_rewrite H4'. setoid_rewrite H5'.
    assert (Hfac : q_pow a (4 * m + 4) * (- 2 / (q_fact (4 * m + 2) * q_fact 2)) +
                   q_pow a (4 * m + 4) * (- 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))) +
                   q_pow a (4 * m + 4) * (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))) +
                   q_pow a (4 * m + 4) * (2 / (q_fact (4 * m + 1) * q_fact 3)) +
                   q_pow a (4 * m + 4) * (- 2 / (q_fact (4 * m + 4) * q_fact 0) + 2 / (q_fact (4 * m + 3) * q_fact 1)) ==
                   q_pow a (4 * m + 4) * (- 2 / (q_fact (4 * m + 2) * q_fact 2)
                                          - 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 4)))
                                          + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 5)))
                                          + 2 / (q_fact (4 * m + 1) * q_fact 3)
                                          - 2 / (q_fact (4 * m + 4) * q_fact 0)
                                          + 2 / (q_fact (4 * m + 3) * q_fact 1))).
    { unfold Qdiv in *. unfold Qminus. ring. }
    setoid_rewrite Hfac.
    setoid_rewrite Hc.
    unfold Qdiv in *. unfold Qminus. ring. }
  assert (H2 : - 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 2) * q_fact 0))
               + 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
               + 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 1) * q_fact 1))
               + sum_upto m (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))) ==
               - q_pow a (4 * m + 2) / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
  { assert (Hc : - 2 / (q_fact (4 * m + 2) * q_fact 0)
                 + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                 + 2 / (q_fact (4 * m + 1) * q_fact 1)
                 - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))) ==
                 - 1 / (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
    { apply (row_pair_mid2 m Hm). }
    assert (H1' : - 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 2) * q_fact 0)) ==
                  q_pow a (4 * m + 2) * (- 2 / (q_fact (4 * m + 2) * q_fact 0))).
    { unfold Qdiv. ring. }
    assert (H2' : 2 * sum_upto (m - 1) (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))) ==
                  q_pow a (4 * m + 2) * (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))))).
    { setoid_rewrite (sum_upto_ext_below (m - 1)
        (fun j => q_pow a (4 * m + 2) / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
        (fun j => q_pow a (4 * m + 2) * (1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale (m - 1) (q_pow a (4 * m + 2)) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    assert (H3' : 2 * (q_pow a (4 * m + 2) / (q_fact (4 * m + 1) * q_fact 1)) ==
                  q_pow a (4 * m + 2) * (2 / (q_fact (4 * m + 1) * q_fact 1))).
    { unfold Qdiv. ring. }
    assert (H4' : sum_upto m (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))) ==
                  q_pow a (4 * m + 2) * (- 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
    { setoid_rewrite (sum_upto_ext_below m
        (fun j => - (2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))
        (fun j => q_pow a (4 * m + 2) * (- 2 * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))))).
      2: { intros j Hj. unfold Qdiv. ring. }
      setoid_rewrite (sum_upto_scale m (q_pow a (4 * m + 2)) (fun j => - 2 * (1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
      setoid_rewrite (sum_upto_scale_neg2 m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
      unfold Qdiv in *. unfold Qminus. ring. }
    setoid_rewrite H1'. setoid_rewrite H2'. setoid_rewrite H3'. setoid_rewrite H4'.
    assert (Hfac : q_pow a (4 * m + 2) * (- 2 / (q_fact (4 * m + 2) * q_fact 0)) +
                   q_pow a (4 * m + 2) * (2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))) +
                   q_pow a (4 * m + 2) * (2 / (q_fact (4 * m + 1) * q_fact 1)) +
                   q_pow a (4 * m + 2) * (- 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))) ==
                   q_pow a (4 * m + 2) * (- 2 / (q_fact (4 * m + 2) * q_fact 0)
                                          + 2 * sum_upto (m - 1) (fun j => 1 / (q_fact (4 * m - 1 - 2 * j) * q_fact (2 * j + 3)))
                                          + 2 / (q_fact (4 * m + 1) * q_fact 1)
                                          - 2 * sum_upto m (fun j => 1 / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2))))).
    { ring. }
    setoid_rewrite Hfac.
    setoid_rewrite Hc.
    unfold Qdiv in *. unfold Qminus. ring. }
  (* ⑧ 组装：R6 + R4 + R2 == Te² − To² *)
  setoid_rewrite H6.
  setoid_rewrite H4.
  setoid_rewrite H2.
  unfold Qdiv in *. unfold Qminus. ring.
Qed.

Lemma ksum_diff_row : forall (a : Q) (m : nat),
  (1 <= m)%nat ->
  ksum_diff m m a + inner2 (2 * m + 1) (2 * Datatypes.S m - (2 * m + 1)) a ==
  2 * esq_row (Datatypes.S m) m a +
  (q_pow a (4 * m + 4) /
     (q_fact (2 * m + 2) * q_fact (2 * m + 2))) -
  2 * osq_row m (m - 1) a -
  (q_pow a (2 * m + 2 * m + 2) /
     (q_fact (2 * m + 1) * q_fact (2 * m + 1))).
Proof.
  intros a m Hm.
  (* ① LHS == corr 差分（corr_succ_decomp 反向） *)
  setoid_rewrite <- (corr_succ_decomp a m Hm).
  (* ② corr 差分 == 行表达式 k' 形态（corr_diff_expand） *)
  setoid_rewrite (corr_diff_expand a m Hm).
  (* ③ 行表达式 k' 形态 == j 形态（j = m−1−k'，sum_upto_rev + 逐点归约） *)
  assert (Hrel : sum_upto m
            (fun k' =>
               - 2 * esq_row (m + 2 + k') (m + 1 - k') a
               + 2 * esq_row (m + 1 + k') (m - k') a
               + 2 * osq_row (m + 1 + k') (m - k') a
               - 2 * osq_row (m + k') (m - k' - 1) a
               + 2 * q_pow a (4 * m + 6) / (q_fact (2 * m + 2 * k' + 4) * q_fact (2 * m + 2 - 2 * k'))
               - 2 * q_pow a (4 * m + 2) / (q_fact (2 * m + 2 * k' + 2) * q_fact (2 * m - 2 * k'))) ==
                 sum_upto m
            (fun j =>
               - 2 * esq_row (2 * m + 1 - j) (j + 2) a
               + 2 * esq_row (2 * m - j) (j + 1) a
               + 2 * osq_row (2 * m - j) (j + 1) a
               - 2 * osq_row (2 * m - 1 - j) j a
               + 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
               - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
  { rewrite <- (sum_upto_rev m
      (fun j =>
         - 2 * esq_row (2 * m + 1 - j) (j + 2) a
         + 2 * esq_row (2 * m - j) (j + 1) a
         + 2 * osq_row (2 * m - j) (j + 1) a
         - 2 * osq_row (2 * m - 1 - j) j a
         + 2 * q_pow a (4 * m + 6) / (q_fact (4 * m + 2 - 2 * j) * q_fact (2 * j + 4))
         - 2 * q_pow a (4 * m + 2) / (q_fact (4 * m - 2 * j) * q_fact (2 * j + 2)))).
    apply sum_upto_ext_below. intros k' Hk'.
    (* 逐点：corr行差(k') == row行差(m−1−k')——参数归约（lia） *)
    assert (H1 : (2 * m + 1 - (m - 1 - k') = m + 2 + k')%nat) by lia.
    assert (H2 : ((m - 1 - k') + 2 = m + 1 - k')%nat) by lia.
    assert (H3 : (2 * m - (m - 1 - k') = m + 1 + k')%nat) by lia.
    assert (H4 : ((m - 1 - k') + 1 = m - k')%nat) by lia.
    assert (H5 : (2 * m - 1 - (m - 1 - k') = m + k')%nat) by lia.
    assert (H6 : ((m - 1 - k') = m - k' - 1)%nat) by lia.
    assert (H7 : (4 * m + 2 - 2 * (m - 1 - k') = 2 * m + 2 * k' + 4)%nat) by lia.
    assert (H8 : (2 * (m - 1 - k') + 4 = 2 * m + 2 - 2 * k')%nat) by lia.
    assert (H9 : (4 * m - 2 * (m - 1 - k') = 2 * m + 2 * k' + 2)%nat) by lia.
    assert (H10 : (2 * (m - 1 - k') + 2 = 2 * m - 2 * k')%nat) by lia.
    rewrite H1. rewrite H3. rewrite H5.
    rewrite H7. rewrite H8. rewrite H9. rewrite H10.
    rewrite H2. rewrite H4. rewrite H6.
    reflexivity. }
  setoid_rewrite Hrel.
  (* ④ 行表达式 j 形态 == RHS（row_pair_main） *)
  setoid_rewrite (row_pair_main a m Hm).
  (* ⑤ To² 指数归约：2m+2m+2 == 4m+2 *)
  assert (He : (2 * m + 2 * m + 2 = 4 * m + 2)%nat) by lia.
  setoid_replace (q_pow a (2 * m + 2 * m + 2)) with (q_pow a (4 * m + 2)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * m + 2 * m + 2)%nat (4 * m + 2)%nat). exact He. }
  reflexivity.
Qed.

(* ============ esq_eq_corr 战役（备份 93 合入，探针 _dbg_kdr.v 全绿） ============
   corr_diff_eq_sq_diff：corr 差分 == E/O 平方差分差（corr_succ_decomp → ksum_diff_row → ksum_diff_row_rhs）
   esq_eq_corr：E_m²−O_m² == 1 + corr m（主恒等式，base 0/1 + 归纳 step）——注释目标 L10664 达成 *)
Lemma corr_diff_eq_sq_diff : forall (a : Q) (m : nat), (1 <= m)%nat ->
  corr (Datatypes.S m) a - corr m a ==
  (e_sum (Datatypes.S m) a * e_sum (Datatypes.S m) a -
   o_sum (Datatypes.S m) a * o_sum (Datatypes.S m) a) -
  (e_sum m a * e_sum m a - o_sum m a * o_sum m a).
Proof.
  intros a m Hm.
  setoid_rewrite (corr_succ_decomp a m Hm).
  setoid_rewrite (ksum_diff_row a m Hm).
  (* ksum_diff_row 的 To² 指数是 2m+2m+2，ksum_diff_row_rhs 是 4m+2——归约桥 *)
  assert (He : (2 * m + 2 * m + 2 = 4 * m + 2)%nat) by lia.
  setoid_replace (q_pow a (2 * m + 2 * m + 2)) with (q_pow a (4 * m + 2)).
  2: { apply (q_pow_comp_proper a a (Qeq_refl a) (2 * m + 2 * m + 2)%nat (4 * m + 2)%nat). exact He. }
  setoid_rewrite (ksum_diff_row_rhs a m Hm).
  reflexivity.
Qed.

Lemma esq_eq_corr : forall (a : Q) (m : nat),
  e_sum m a * e_sum m a - o_sum m a * o_sum m a == 1 + corr m a.
Proof.
  intros a m.
  induction m as [| m' IH].
  - (* m=0：E_0=1、O_0=0、corr 0=0 *)
    simpl. reflexivity.
  - destruct m' as [| m''].
    + (* m=1：直接计算 *)
      unfold e_sum, o_sum, corr, kloop, inner2, brk2.
      simpl.
      field.
      all: repeat (split; [apply q_neq_of_lt; apply q_fact_pos | idtac]);
           apply q_neq_of_lt; apply q_fact_pos.
    + (* m = S(S m'')：step——corr 差分公式 + IH *)
      assert (Hstep : e_sum (Datatypes.S (Datatypes.S m'')) a * e_sum (Datatypes.S (Datatypes.S m'')) a -
                      o_sum (Datatypes.S (Datatypes.S m'')) a * o_sum (Datatypes.S (Datatypes.S m'')) a ==
                      (e_sum (Datatypes.S m'') a * e_sum (Datatypes.S m'') a -
                       o_sum (Datatypes.S m'') a * o_sum (Datatypes.S m'') a) +
                      (corr (Datatypes.S (Datatypes.S m'')) a - corr (Datatypes.S m'') a)).
      { assert (Hd : corr (Datatypes.S (Datatypes.S m'')) a - corr (Datatypes.S m'') a ==
                     (e_sum (Datatypes.S (Datatypes.S m'')) a * e_sum (Datatypes.S (Datatypes.S m'')) a -
                      o_sum (Datatypes.S (Datatypes.S m'')) a * o_sum (Datatypes.S (Datatypes.S m'')) a) -
                     (e_sum (Datatypes.S m'') a * e_sum (Datatypes.S m'') a -
                      o_sum (Datatypes.S m'') a * o_sum (Datatypes.S m'') a)).
        { apply (corr_diff_eq_sq_diff a (Datatypes.S m'')). lia. }
        setoid_rewrite Hd.
        unfold Qminus. ring. }
      setoid_rewrite Hstep.
      setoid_rewrite IH.
      unfold Qminus. ring.
Qed.

(* ============ exp_even_neg_nonneg 战役（备份 94 合入，探针 _dbg_kdr.v 全绿） ============
   q_div_nonneg / e_sum_ge_one / o_sum_nonneg（辅助：E≥1、O≥0）
   exp_even_mul_eq：S_{2m}(−a)·S_{2m}(a) == 1 + corr m a（(E−O)(E+O) = E²−O²）
   exp_even_neg_nonneg：0 ≤ a ⟹ 0 ≤ exp_partial (2·m) (−a)（corr_nonneg + S(a)>0 + field 恒等） *)
Lemma q_div_nonneg : forall (x d : Q), Qle 0 x -> Qlt 0 d -> Qle 0 (x / d).
Proof.
  intros x d Hx Hd.
  unfold Qdiv.
  apply Qmult_le_0_compat.
  - exact Hx.
  - apply Qlt_le_weak. apply Qinv_lt_0_compat. exact Hd.
Qed.
Lemma e_sum_ge_one : forall (a : Q) (m : nat), Qle 0 a -> Qle 1 (e_sum m a).
Proof.
  intros a m Ha.
  induction m as [| m' IH]; simpl.
  - apply Qle_refl.
  - apply (Qle_trans _ (e_sum m' a) _).
    + exact IH.
    + apply (Qle_trans _ (e_sum m' a + 0) _).
      * setoid_rewrite (Qplus_0_r (e_sum m' a)). apply Qle_refl.
      * apply (Qplus_le_compat (e_sum m' a) (e_sum m' a) 0 (q_pow a (2 * Datatypes.S m') / q_fact (2 * Datatypes.S m'))).
        -- apply Qle_refl.
        -- apply (q_div_nonneg (q_pow a (2 * Datatypes.S m')) (q_fact (2 * Datatypes.S m'))).
           ++ apply (q_pow_nonneg a (2 * Datatypes.S m')). exact Ha.
           ++ apply q_fact_pos.
Qed.
Lemma o_sum_nonneg : forall (a : Q) (m : nat), Qle 0 a -> Qle 0 (o_sum m a).
Proof.
  intros a m Ha.
  induction m as [| m' IH]; simpl.
  - apply Qle_refl.
  - apply (Qplus_le_compat 0 (o_sum m' a) 0 (q_pow a (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))).
    + exact IH.
    + apply (q_div_nonneg (q_pow a (Datatypes.S (2 * m'))) (q_fact (Datatypes.S (2 * m')))).
      * apply (q_pow_nonneg a (Datatypes.S (2 * m'))). exact Ha.
      * apply q_fact_pos.
Qed.
Lemma exp_even_mul_eq : forall (a : Q) (m : nat),
  exp_partial (2 * m) (- a) * exp_partial (2 * m) a == 1 + corr m a.
Proof.
  intros a m.
  setoid_rewrite (e_o_split_even a m).
  setoid_rewrite (e_o_split_pos a m).
  assert (Hring : (e_sum m a - o_sum m a) * (e_sum m a + o_sum m a) ==
                  e_sum m a * e_sum m a - o_sum m a * o_sum m a) by ring.
  setoid_rewrite Hring.
  setoid_rewrite (esq_eq_corr a m).
  reflexivity.
Qed.
Lemma exp_even_neg_nonneg : forall (a : Q) (m : nat), Qle 0 a -> Qle 0 (exp_partial (2 * m) (- a)).
Proof.
  intros a m Ha.
  assert (H01 : Qlt 0 1) by (unfold Qlt; simpl; lia).
  (* ① 0 < S(−a)·S(a)：S(−a)·S(a) == 1 + corr ≥ 1 > 0 *)
  assert (Hmul_le : Qle 1 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
  { rewrite (exp_even_mul_eq a m).
    apply (Qle_trans _ (1 + 0) _).
    - setoid_rewrite (Qplus_0_r 1). apply Qle_refl.
    - apply (Qplus_le_compat 1 1 0 (corr m a)).
      * apply Qle_refl.
      * apply (corr_nonneg a m Ha). }
  assert (Hmul_pos : Qlt 0 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
  { apply (Qlt_le_trans 0 1 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
    - exact H01.
    - exact Hmul_le. }
  (* ② 0 < S(a)：S(a) == E+O，E ≥ 1 > 0、O ≥ 0 ⟹ E+O > 0 *)
  assert (Hspos : Qlt 0 (exp_partial (2 * m) a)).
  { setoid_rewrite (e_o_split_pos a m).
    apply (Qlt_le_trans 0 (e_sum m a) (e_sum m a + o_sum m a)).
    - apply (Qlt_le_trans 0 1 (e_sum m a)).
      + exact H01.
      + apply (e_sum_ge_one a m Ha).
    - apply (Qle_trans _ (e_sum m a + 0) _).
      * setoid_rewrite (Qplus_0_r (e_sum m a)). apply Qle_refl.
      * apply (Qplus_le_compat (e_sum m a) (e_sum m a) 0 (o_sum m a)).
        -- apply Qle_refl.
        -- apply (o_sum_nonneg a m Ha). }
  (* ③ S(−a) == (S(−a)·S(a))·inv(S(a))（field 恒等，S(a) ≠ 0） *)
  assert (Hinv : exp_partial (2 * m) a * Qinv (exp_partial (2 * m) a) == 1).
  { apply Qmult_inv_r. apply (q_neq_of_lt (exp_partial (2 * m) a) Hspos). }
  assert (Hfield : exp_partial (2 * m) (- a) ==
                   (exp_partial (2 * m) (- a) * exp_partial (2 * m) a) * Qinv (exp_partial (2 * m) a)).
  { transitivity (exp_partial (2 * m) (- a) *
                  (exp_partial (2 * m) a * Qinv (exp_partial (2 * m) a))).
    - setoid_rewrite Hinv. ring.
    - ring. }
  (* ④ (S(−a)·S(a))·inv(S(a)) > 0（正×正）⟹ S(−a) > 0 ⟹ ≥ 0 *)
  assert (Hpos : Qlt 0 ((exp_partial (2 * m) (- a) * exp_partial (2 * m) a) * Qinv (exp_partial (2 * m) a))).
  { apply Qmult_lt_0_compat.
    - exact Hmul_pos.
    - apply Qinv_lt_0_compat. exact Hspos. }
  setoid_rewrite <- Hfield in Hpos.
  apply (Qlt_le_weak 0 (exp_partial (2 * m) (- a))). exact Hpos.
Qed.
(* ============ exp_partial_tail_pos 战役（备份 95 合入，探针 _dbg_kdr.v 全绿） ============
   exp_even_neg_pos：0 ≤ a ⟹ 0 < exp_partial (2·m) (−a)（严格正版，S(−a)·S(a) ≥ 1 + S(a) > 0）
   exp_partial_tail_pos：0 ≤ a ⟹ 0 < exp_partial (2m+2) (−a)（尾截断正，exp_even_neg_pos 的 S m 版）
   下轮：cauchy_real_exp_pos（real_lt zero (cauchy_real_exp x)，exp_neg_pos 字段实例化材料） *)
Lemma exp_even_neg_pos : forall (a : Q) (m : nat), Qle 0 a -> Qlt 0 (exp_partial (2 * m) (- a)).
Proof.
  intros a m Ha.
  assert (H01 : Qlt 0 1) by (unfold Qlt; simpl; lia).
  assert (Hmul_le : Qle 1 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
  { rewrite (exp_even_mul_eq a m).
    apply (Qle_trans _ (1 + 0) _).
    - setoid_rewrite (Qplus_0_r 1). apply Qle_refl.
    - apply (Qplus_le_compat 1 1 0 (corr m a)).
      * apply Qle_refl.
      * apply (corr_nonneg a m Ha). }
  assert (Hmul_pos : Qlt 0 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
  { apply (Qlt_le_trans 0 1 (exp_partial (2 * m) (- a) * exp_partial (2 * m) a)).
    - exact H01.
    - exact Hmul_le. }
  assert (Hspos : Qlt 0 (exp_partial (2 * m) a)).
  { setoid_rewrite (e_o_split_pos a m).
    apply (Qlt_le_trans 0 (e_sum m a) (e_sum m a + o_sum m a)).
    - apply (Qlt_le_trans 0 1 (e_sum m a)).
      + exact H01.
      + apply (e_sum_ge_one a m Ha).
    - apply (Qle_trans _ (e_sum m a + 0) _).
      * setoid_rewrite (Qplus_0_r (e_sum m a)). apply Qle_refl.
      * apply (Qplus_le_compat (e_sum m a) (e_sum m a) 0 (o_sum m a)).
        -- apply Qle_refl.
        -- apply (o_sum_nonneg a m Ha). }
  assert (Hinv : exp_partial (2 * m) a * Qinv (exp_partial (2 * m) a) == 1).
  { apply Qmult_inv_r. apply (q_neq_of_lt (exp_partial (2 * m) a) Hspos). }
  assert (Hfield : exp_partial (2 * m) (- a) ==
                   (exp_partial (2 * m) (- a) * exp_partial (2 * m) a) * Qinv (exp_partial (2 * m) a)).
  { transitivity (exp_partial (2 * m) (- a) *
                  (exp_partial (2 * m) a * Qinv (exp_partial (2 * m) a))).
    - setoid_rewrite Hinv. ring.
    - ring. }
  assert (Hpos : Qlt 0 ((exp_partial (2 * m) (- a) * exp_partial (2 * m) a) * Qinv (exp_partial (2 * m) a))).
  { apply Qmult_lt_0_compat.
    - exact Hmul_pos.
    - apply Qinv_lt_0_compat. exact Hspos. }
  setoid_rewrite <- Hfield in Hpos.
  exact Hpos.
Qed.

Lemma exp_partial_tail_pos : forall (a : Q) (m : nat), Qle 0 a -> Qlt 0 (exp_partial (2 * m + 2) (- a)).
Proof.
  intros a m Ha.
  assert (Hn : (2 * Datatypes.S m = 2 * m + 2)%nat) by lia.
  setoid_replace (exp_partial (2 * m + 2) (- a)) with (exp_partial (2 * Datatypes.S m) (- a)).
  2: { change (exp_partial (2 * m + 2) (- a) == exp_partial (2 * Datatypes.S m) (- a)).
       rewrite <- Hn. reflexivity. }
  apply (exp_even_neg_pos a (Datatypes.S m)). exact Ha.
Qed.

(* 任意参数的偶截断正：∀y，0 < exp_partial (2·m) y（Qlt_le_dec 三分：
   0 < y ⟹ 正项和 ≥ 1 > 0；y ≤ 0 ⟹ exp_pair_alt m (−y) > 0（exp_even_neg_pos）） *)
Lemma exp_even_all_pos : forall (y : Q) (m : nat), Qlt 0 (exp_partial (2 * m) y).
Proof.
  intros y m.
  destruct (Qlt_le_dec 0 y) as [Hy | Hy0].
  - (* 0 < y：ep (2m) y ≥ 1 > 0（正项和） *)
    assert (Hy0' : Qle 0 y) by (apply (Qlt_le_weak 0 y); exact Hy).
    assert (Hle : Qle 1 (exp_partial (2 * m) y)).
    { induction m as [| m' IH].
      + simpl. apply Qle_refl.
      + assert (Hidx : (2 * Datatypes.S m' = Datatypes.S (Datatypes.S (2 * m')))%nat) by lia.
        rewrite Hidx. simpl.
        assert (HT1 : Qle 0 (q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))).
        { apply (q_div_nonneg (q_pow y (Datatypes.S (2 * m'))) (q_fact (Datatypes.S (2 * m')))).
          - apply (q_pow_nonneg y (Datatypes.S (2 * m'))). exact Hy0'.
          - apply q_fact_pos. }
        assert (HT2 : Qle 0 (q_pow y (Datatypes.S (Datatypes.S (2 * m'))) / q_fact (Datatypes.S (Datatypes.S (2 * m'))))).
        { apply (q_div_nonneg (q_pow y (Datatypes.S (Datatypes.S (2 * m')))) (q_fact (Datatypes.S (Datatypes.S (2 * m'))))).
          - apply (q_pow_nonneg y (Datatypes.S (Datatypes.S (2 * m')))). exact Hy0'.
          - apply q_fact_pos. }
        apply (Qle_trans _ (exp_partial (2 * m') y) _).
        * exact IH.
        * apply (Qle_trans _ (exp_partial (2 * m') y +
                              q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m'))) _).
          -- apply (Qle_trans _ (exp_partial (2 * m') y + 0) _).
             ++ setoid_rewrite (Qplus_0_r (exp_partial (2 * m') y)). apply Qle_refl.
             ++ apply (Qplus_le_compat (exp_partial (2 * m') y) (exp_partial (2 * m') y) 0
                        (q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))).
                ** apply Qle_refl.
                ** exact HT1.
          -- apply (Qle_trans _ (exp_partial (2 * m') y +
                                q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')) + 0) _).
             ++ setoid_rewrite (Qplus_0_r (exp_partial (2 * m') y +
                                         q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))). apply Qle_refl.
             ++ apply (Qplus_le_compat (exp_partial (2 * m') y +
                                       q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))
                                     (exp_partial (2 * m') y +
                                      q_pow y (Datatypes.S (2 * m')) / q_fact (Datatypes.S (2 * m')))
                                     0 (q_pow y (Datatypes.S (Datatypes.S (2 * m'))) / q_fact (Datatypes.S (Datatypes.S (2 * m'))))).
                ** apply Qle_refl.
                ** exact HT2. }
    apply (Qlt_le_trans 0 1 (exp_partial (2 * m) y)).
    + unfold Qlt; simpl; lia.
    + exact Hle.
  - (* y ≤ 0：ep (2m) y = exp_pair_alt m (−y) > 0（exp_even_neg_pos 于 −y ≥ 0） *)
    assert (Hny : Qle 0 (- y)).
    { change (Qle 0 (- y)) with (Qle (- 0) (- y)).
      apply (Qopp_le_compat y 0). exact Hy0. }
    assert (Hp : Qlt 0 (exp_partial (2 * m) (- (- y)))).
    { apply (exp_even_neg_pos (- y) m). exact Hny. }
    destruct y as [n d].
    destruct n; exact Hp.
Qed.
(* ============================================================
   cauchy_real_exp_pos 战役（B3 最终步：exp_neg_pos 字段材料）
   目标：real_lt zero (cauchy_real_exp x)
   策略：偶数截断统一下界 1/C（exp_even_mul_eq + corr_nonneg +
   exp_series_arch：S_{2m}(-a)·S_{2m}(a) == 1+corr ≥ 1，且 S_{2m}(a) ≤ C，
   故 S_{2m}(-a) ≥ 1/C；y ≥ 0 时 S_{2m}(y) ≥ 1 ≥ 1/C）；
   奇数截断用尾项衰减补齐（2m+1 ≥ m0 时 |y|^{2m+1}/(2m+1)! < 1/(2C)）。
   ============================================================ *)

(* 0b. exp_partial 与 exp_series 定义性同构：exp_partial n x == exp_series n x *)
Lemma exp_partial_eq_series : forall (n : nat) (x : Q), exp_partial n x == exp_series n x.
Proof.
  intros n x. induction n as [| m IH]; simpl.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

(* 0c. exp_partial 参数 wd：x == y ⟹ exp_partial n x == exp_partial n y *)
Lemma exp_partial_wd : forall (n : nat) (x y : Q), x == y -> exp_partial n x == exp_partial n y.
Proof.
  intros n x y Hxy. induction n as [| m IH]; simpl.
  - reflexivity.
  - rewrite IH.
    rewrite (q_pow_wd x y (Datatypes.S m) Hxy).
    reflexivity.
Qed.

(* 1. exp_series 对第二参数单调：0 ≤ B1 ≤ B2 ⟹ exp_series n B1 ≤ exp_series n B2 *)
Lemma exp_series_arg_mono : forall (B1 B2 : Q) (n : nat),
  Qle 0 B1 -> Qle B1 B2 -> Qle (exp_series n B1) (exp_series n B2).
Proof.
  intros B1 B2 n HB1 HB12. induction n as [| n IH]; simpl.
  - apply Qle_refl.
  - apply Qplus_le_compat.
    + exact IH.
    + apply (Qle_div_same_denom (q_pow B1 (Datatypes.S n)) (q_pow B2 (Datatypes.S n))
                               (q_fact (Datatypes.S n))).
      * apply q_fact_pos.
      * apply q_pow_mono; [exact HB1 | exact HB12].
Qed.

(* 2. 非负参数的任意截断 ≥ 1：0 ≤ y ⟹ 1 ≤ exp_partial n y（每步加非负项） *)
Lemma exp_partial_ge_one : forall (y : Q) (n : nat), Qle 0 y -> Qle 1 (exp_partial n y).
Proof.
  intros y n Hy. induction n as [| n IH]; simpl.
  - apply Qle_refl.
  - apply (Qle_trans _ (exp_partial n y) _).
    + exact IH.
    + apply (Qle_plus_nonneg_r (exp_partial n y) (q_pow y (Datatypes.S n) / q_fact (Datatypes.S n))).
      apply q_pow_fact_nonneg. exact Hy.
Qed.

(* 3. exp_partial (2m) a ≤ C：0 ≤ a ≤ M，(∀n, exp_series n M ≤ C) ⟹ exp_partial (2m) a ≤ C *)
Lemma exp_partial_even_upper : forall (a M C : Q) (m : nat),
  Qle 0 M -> Qle 0 a -> Qle a M ->
  (forall n : nat, Qle (exp_series n M) C) ->
  Qle (exp_partial (2 * m) a) C.
Proof.
  intros a M C m HM Ha Ham HC.
  apply (Qle_trans _ (exp_series (2 * m) a) _).
  - apply qeq_le. apply exp_partial_eq_series.
  - apply (Qle_trans _ (exp_series (2 * m) M) _).
    + apply exp_series_arg_mono; assumption.
    + exact (HC (2 * m)%nat).
Qed.

(* 4. 偶数截断统一下界：|y| ≤ M ⟹ 1/C ≤ exp_partial (2m) y（y ≥ 0 用正项和 ≥ 1；
   y ≤ 0 用 S(-a)·S(a) == 1+corr ≥ 1 且 S(a) ≤ C ⟹ S(-a) ≥ 1/C） *)
Lemma exp_partial_even_lower : forall (M C : Q) (y : Q) (m : nat),
  QleT' 0 M -> QleT' 1 C ->
  (forall n : nat, QleT' (exp_series n M) C) ->
  QleT' (Qabs y) M -> Qle (1 / C) (exp_partial (2 * m) y).
Proof.
  intros M C y m HM HC HCser Hy.
  destruct (Qlt_le_dec 0 y) as [Hypos | Hyneg].
  - (* 0 < y：正项和 ≥ 1 ≥ 1/C *)
    apply (Qle_trans _ 1 _).
    + (* 1/C ≤ 1：1/C == 1·Qinv C，Qinv C ≤ Qinv 1 == 1，且 1·x == x *)
      change (Qle (1 * Qinv C) 1).
      apply (Qle_trans _ (Qinv C) _).
      * apply qeq_le. apply (Qmult_1_l (Qinv C)).
      * apply (q_inv_le_contravar C 1).
        -- apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC)].
        -- unfold Qlt; simpl; lia.
        -- exact (QleT'_to_Qle _ _ HC).
    + apply exp_partial_ge_one. apply (Qlt_le_weak 0 y). exact Hypos.
  - (* y ≤ 0：a = -y ≥ 0，S_{2m}(-a) ≥ 1/S_{2m}(a) ≥ 1/C *)
    assert (Ha : Qle 0 (- y)).
    { change (Qle 0 (- y)) with (Qle (- 0) (- y)).
      apply (Qopp_le_compat y 0). exact Hyneg. }
    assert (Ham : Qle (- y) M).
    { assert (Habs : Qabs y == - y) by (apply Qabs_neg; exact Hyneg).
      rewrite <- Habs. exact (QleT'_to_Qle _ _ Hy). }
    (* S_{2m}(a) ≥ 1 > 0 且 S_{2m}(a) ≤ C（a = -y） *)
    assert (Hsa_pos : Qlt 0 (exp_partial (2 * m) (- y))).
    { apply (Qlt_le_trans _ 1 _).
      - unfold Qlt; simpl; lia.
      - apply exp_partial_ge_one. exact Ha. }
    assert (Hsa_le : Qle (exp_partial (2 * m) (- y)) C).
    { apply (exp_partial_even_upper (- y) M C m).
      - exact (QleT'_to_Qle _ _ HM).
      - exact Ha.
      - exact Ham.
      - intro n0. apply QleT'_to_Qle. exact (HCser n0). }
    (* 1 ≤ S(-(-y))·S(-y)（exp_even_mul_eq + corr_nonneg） *)
    assert (Hmul : Qle 1 (exp_partial (2 * m) (- (- y)) * exp_partial (2 * m) (- y))).
    { rewrite (exp_even_mul_eq (- y) m).
      apply (Qle_trans _ (1 + 0) _).
      - setoid_rewrite (Qplus_0_r 1). apply Qle_refl.
      - apply (Qplus_le_compat 1 1 0 (corr m (- y))).
        * apply Qle_refl.
        * apply (corr_nonneg (- y) m Ha). }
    (* 目标 1/C ≤ S_{2m}(y)：y == -(-y)，1/C ≤ 1/S(-y) ≤ S(-(-y))，再用 wd 换回 y *)
    assert (Hyid : y == - (- y)) by ring.
    apply (Qle_trans _ (exp_partial (2 * m) (- (- y))) _).
    { (* 1/C ≤ S(-(-y))：链 1/C ≤ 1/S(-y) ≤ S(-(-y)) *)
      apply (Qle_trans _ (1 / exp_partial (2 * m) (- y)) _).
      { (* 1/C ≤ 1/S(-y)：先消 1·（Qdiv 1 x 与 Qinv x 形态不同，E143-1228⑥），
         再 q_inv_le_contravar（Qinv C ≤ Qinv S），最后补回 1· *)
        apply (Qle_trans _ (Qinv C) _).
        - (* 1/C ≤ Qinv C：1·Qinv C == Qinv C *)
          apply qeq_le. apply (Qmult_1_l (Qinv C)).
        - apply (Qle_trans _ (Qinv (exp_partial (2 * m) (- y))) _).
          + (* Qinv C ≤ Qinv S(-y)：q_inv_le_contravar（0 < S(-y) ≤ C） *)
            apply (q_inv_le_contravar C (exp_partial (2 * m) (- y))).
            * apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC)].
            * exact Hsa_pos.
            * exact Hsa_le.
          + (* Qinv S(-y) ≤ 1·Qinv S(-y) == 1/S(-y)：补回 1· *)
            apply qeq_le. apply Qeq_sym. apply (Qmult_1_l (Qinv (exp_partial (2 * m) (- y)))). }
      { (* 1/S(-y) ≤ S(-(-y))：Qle_shift_div_r 1 (S(-y)) (S(-(-y)))，需 1 ≤ S(-(-y))·S(-y) *)
        apply (Qle_shift_div_r 1 (exp_partial (2 * m) (- y))
                                (exp_partial (2 * m) (- (- y)))).
        - exact Hsa_pos.
        - exact Hmul. } }
    { (* S(-(-y)) ≤ S(y)：qeq_le（y == -(-y) 的 wd 版） *)
      apply qeq_le.
      apply Qeq_sym.
      apply (exp_partial_wd (2 * m) y (- (- y))). exact Hyid. }
Qed.

(* 5. 尾项衰减：∃m0, ∀m ≥ m0, M^{2m+1}/(2m+1)! < 1/(2C)
   （q_arch_geom 给几何前提 N0，arch_decay 给 (A^{N0}/N0!·2)·(1/2)^{S t} < 1/C，
    exp_tail_arch 收尾：b ≥ N0+S t ⟹ (A^b/b!)·2 < 1/C ⟹ A^b/b! < 1/(2C)） *)
Lemma exp_partial_tail_small : forall (M C : Q), QleT' 0 M -> QleT' 1 C ->
  sigT (fun m0 : nat => forall m : nat, (m0 <= m)%nat ->
    Qlt (q_pow M (2 * m + 1) / q_fact (2 * m + 1)) (1 / (2 * C))).
Proof.
  intros M C HM HC.
  destruct (q_arch_geom M) as [N0 HN0].
  assert (HCpos : Qlt 0 C) by (apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC)]).
  assert (Hinv : Qlt 0 (1 / C)).
  { apply (Qlt_le_trans _ (Qinv C) _).
    - apply Qinv_lt_0_compat. exact HCpos.
    - apply qeq_le. apply Qeq_sym. apply (Qmult_1_l (Qinv C)). }
  destruct (arch_decay ((q_pow M N0 / q_fact N0) * (1 + 1)%Q) (1 / C)) as [t Ht].
  { apply Qle_to_QleT'. apply q_pow_fact2_nonneg. exact (QleT'_to_Qle _ _ HM). }
  { apply Qlt_to_QltT. exact Hinv. }
  exists (N0 + Datatypes.S t)%nat.
  intros m Hm.
  assert (Hb : (N0 + Datatypes.S t <= 2 * m + 1)%nat) by lia.
  (* (M^{2m+1}/(2m+1)!)·2 < 1/C *)
  assert (Harch : Qlt ((q_pow M (2 * m + 1) / q_fact (2 * m + 1)) * (1 + 1)%Q) (1 / C)).
  { apply (exp_tail_arch M N0 t (2 * m + 1) (1 / C) (QleT'_to_Qle _ _ HM) (fun u Hu => QleT'_to_Qle _ _ (HN0 u (NatLe_lift _ _ Hu))) Hinv).
    - exact (QltT_to_Qlt _ _ Ht).
    - exact Hb. }
  (* x·(1+1) < 1/C ⟹ x < (1/C)/(1+1) == 1/(2C) *)
  apply (Qlt_le_trans _ ((1 / C) / (1 + 1)%Q) _).
  - apply (Qlt_shift_div_l (q_pow M (2 * m + 1) / q_fact (2 * m + 1)) (1 / C) (1 + 1)%Q).
    + unfold Qlt; simpl; lia.
    + exact Harch.
  - apply qeq_le.
    unfold Qdiv.
    field.
    apply q_neq_of_lt. exact HCpos.
Qed.

(* 6. 奇数截断统一下界：|y| ≤ M、m ≥ m0 ⟹ 1/(2C) < exp_partial (2m+1) y
   （S_{2m+1}(y) == S_{2m}(y) + y^{2m+1}/(2m+1)!；y ≥ 0 时正项和 ≥ 1；
   y ≤ 0 时 S_{2m}(y) ≥ 1/C 且 |y|^{2m+1}/(2m+1)! < 1/(2C)） *)
Lemma exp_partial_odd_lower : forall (M C : Q) (m0 m : nat) (y : Q),
  QleT' 0 M -> QleT' 1 C ->
  (forall n : nat, QleT' (exp_series n M) C) ->
  (forall k : nat, (m0 <= k)%nat ->
    Qlt (q_pow M (2 * k + 1) / q_fact (2 * k + 1)) (1 / (2 * C))) ->
  (m0 <= m)%nat ->
  QleT' (Qabs y) M -> Qlt (1 / (2 * C)) (exp_partial (2 * m + 1) y).
Proof.
  intros M C m0 m y HM HC HCser Htail Hm0 Hy.
  assert (Hidx : (2 * m + 1 = Datatypes.S (2 * m))%nat) by lia.
  rewrite Hidx.
  destruct (Qlt_le_dec 0 y) as [Hypos | Hyneg].
  - (* 0 < y：正项和 ≥ 1 > 1/(2C) *)
    apply (Qlt_le_trans _ 1 _).
    + (* 1/(2C) < 1：1/(2C) ≤ 1/2 < 1 *)
      apply (Qle_lt_trans _ (1 / 2) _).
      * (* 1/(2C) ≤ 1/2 *)
        apply (Qle_shift_div_r 1 (2 * C) (1 / 2)).
        -- apply (Qmult_lt_0_compat 2 C).
           ++ unfold Qlt; simpl; lia.
           ++ apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC)].
        -- (* 1 ≤ (1/2)·(2C)：桥 1 ≤ C == (1/2)·(2C) *)
           apply (Qle_trans _ C _).
           ++ exact (QleT'_to_Qle _ _ HC).  (* 1 ≤ C *)
           ++ apply qeq_le. unfold Qdiv. field.
      * reflexivity.  (* 1/2 < 1 计算可判定 *)
    + apply exp_partial_ge_one. apply (Qlt_le_weak 0 y). exact Hypos.
  - (* y ≤ 0：S_{2m+1}(y) == S_{2m}(y) - |y|^{2m+1}/(2m+1)! ≥ 1/C - M^{...} > 1/(2C) *)
    assert (Ha : Qle 0 (- y)).
    { change (Qle 0 (- y)) with (Qle (- 0) (- y)).
      apply (Qopp_le_compat y 0). exact Hyneg. }
    assert (Ham : Qle (- y) M).
    { assert (Habs : Qabs y == - y) by (apply Qabs_neg; exact Hyneg).
      rewrite <- Habs. exact (QleT'_to_Qle _ _ Hy). }
    assert (Hsl : Qle (1 / C) (exp_partial (2 * m) y)).
    { apply (exp_partial_even_lower M C y m HM HC HCser). exact Hy. }
    (* 尾项界：y^{2m+1} == -|y|^{2m+1}，|y|^{2m+1}/(2m+1)! ≤ M^{2m+1}/(2m+1)! < 1/(2C) *)
    assert (Htail_le : Qle (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))
                           (q_pow M (2 * m + 1) / q_fact (2 * m + 1))).
    { apply (q_le_div_le (q_pow (Qabs y) (2 * m + 1)) (q_fact (2 * m + 1))
                         (q_pow M (2 * m + 1)) (q_fact (2 * m + 1))).
      - apply q_fact_pos.
      - apply q_fact_pos.
      - apply (Qmult_le_compat_r (q_pow (Qabs y) (2 * m + 1)) (q_pow M (2 * m + 1))
                                 (q_fact (2 * m + 1))).
        + apply q_pow_mono.
          * apply Qabs_nonneg.
          * exact (QleT'_to_Qle _ _ Hy).
        + apply (Qlt_le_weak 0 (q_fact (2 * m + 1))). apply q_fact_pos. }
    assert (Htail_lt : Qlt (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))
                           (1 / (2 * C))).
    { apply (Qle_lt_trans _ (q_pow M (2 * m + 1) / q_fact (2 * m + 1)) _).
      - exact Htail_le.
      - apply (Htail m Hm0). }
    (* S_{2m+1}(y) == S_{2m}(y) - |y|^{2m+1}/(2m+1)! *)
    assert (Hstep : exp_partial (Datatypes.S (2 * m)) y ==
                    exp_partial (2 * m) y -
                    q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)).
    { assert (Hodd : q_pow y (Datatypes.S (2 * m)) == - q_pow (Qabs y) (Datatypes.S (2 * m))).
      { assert (Hm1 : Qabs y == - y) by (apply Qabs_neg; exact Hyneg).
        assert (Hy2 : y == - (Qabs y)).
        { transitivity (- (- y)).
          - apply Qeq_sym. apply Qopp_involutive.  (* y == -(-y) *)
          - apply (Qopp_comp (- y) (Qabs y)). exact (Qeq_sym _ _ Hm1). }
        (* y^{S(2m)} == (-|y|)^{S(2m)} == -|y|^{S(2m)}：q_pow_wd 桥 y == -|y|，
           q_pow_neg_odd 给 (-|y|)^{S(2m)} == -|y|^{S(2m)}（勿 setoid_rewrite 误伤 Qabs） *)
        transitivity (q_pow (- (Qabs y)) (Datatypes.S (2 * m))).
        - apply (q_pow_wd y (- (Qabs y)) (Datatypes.S (2 * m))). exact Hy2.
        - apply (q_pow_neg_odd (Qabs y) m). }
      (* 指数桥：S (2m) == 2m+1（q_pow_comp_proper 构造 Qeq 命题，lia 证 nat 相等） *)
      assert (Hidx_pow : q_pow (Qabs y) (Datatypes.S (2 * m)) == q_pow (Qabs y) (2 * m + 1)).
      { apply (q_pow_comp_proper (Qabs y) (Qabs y) (Qeq_refl (Qabs y))
                                (Datatypes.S (2 * m))%nat (2 * m + 1)%nat).
        lia. }
      assert (Hfn : (Datatypes.S (2 * m) = 2 * m + 1)%nat) by lia.
      assert (Hfq : q_fact (Datatypes.S (2 * m)) == q_fact (2 * m + 1)).
      { apply q_fact_nat_eq. exact Hfn. }
      (* 核心：y^{S(2m)}/q_fact(S(2m)) == -|y|^{2m+1}/(2m+1)! *)
      assert (Hsub : q_pow y (Datatypes.S (2 * m)) / q_fact (Datatypes.S (2 * m)) ==
                     - (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))).
      { unfold Qdiv.
        setoid_rewrite Hodd.
        setoid_rewrite Hidx_pow.
        setoid_rewrite Hfq.
        ring. }
      (* 组装：exp_partial (S(2m)) y == exp_partial (2m) y + 尾项 == 目标 RHS *)
      transitivity (exp_partial (2 * m) y + q_pow y (Datatypes.S (2 * m)) / q_fact (Datatypes.S (2 * m))).
      - reflexivity.  (* exp_partial 定义展开：S(2m) = S (2*m) 且 2*m = 2*m *)
      - setoid_rewrite Hsub. ring. }
    rewrite Hstep.
    (* 1/C - |y|^{2m+1}/(2m+1)! > 1/(2C)：1/(2C) == 1/C - 1/(2C) < 1/C - t（t < 1/(2C)） *)
    apply (Qlt_le_trans _ (1 / C - q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)) _).
    + (* 1/(2C) < 1/C - t：Qlt_minus_iff 双射 *)
      apply (Qlt_minus_iff (1 / (2 * C)) (1 / C - q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))).
      assert (Htmp : 1 / C - q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1) +
                     - (1 / (2 * C)) ==
                     1 / (2 * C) - q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)).
      { field.
        split.
        - apply q_neq_of_lt. apply q_fact_pos.
        - apply q_neq_of_lt. apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC)]. }
      setoid_rewrite Htmp.
      change (Qlt 0 (1 / (2 * C) + - (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)))).
      apply (proj1 (Qlt_minus_iff (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)) (1 / (2 * C)))).
      exact Htail_lt.
    + (* 1/C - t ≤ S_{2m}(y) - t：Hsl 减法保序（先换形 -t == +(-t)） *)
      assert (Hrep : 1 / C - q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1) ==
                     1 / C + - (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))) by ring.
      apply (Qle_trans _ (1 / C + - (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))) _).
      { apply qeq_le. exact Hrep. }
      { apply (Qle_trans _ (exp_partial (2 * m) y +
                            - (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1))) _).
        { apply (Qplus_le_compat (1 / C) (exp_partial (2 * m) y)
                               (- (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)))
                               (- (q_pow (Qabs y) (2 * m + 1) / q_fact (2 * m + 1)))).
          - exact Hsl.
          - apply Qle_refl. }
        { apply qeq_le. ring. } }
Qed.

(* ============================================================
   cauchy_real_exp_pos 主定理：forall x : Real, real_lt zero (cauchy_real_exp x)
   （B3 最终步：exp_neg_pos 字段的实例化材料）
   策略：u 有界 |u n| ≤ M；exp_series_arch 给 C（exp_series n M ≤ C）；
   偶数截断 ≥ 1/C（exp_partial_even_lower），奇数截断 ≥ 1/(2C)
   （exp_partial_tail_small 选 m0 + exp_partial_odd_lower）；
   取 eps = 1/(2C)，对 n ≥ N（N 取 2·m0+1 保证奇偶都覆盖）。
   ============================================================ *)
Lemma cauchy_real_exp_pos : forall x : Real, real_lt real_zero (cauchy_real_exp x).
Proof.
  intros x. destruct x as [u Hu].
  destruct (real_norm_bounded (existT (fun s : Qseq => cauchy s) u Hu)) as [M [HMpos HM]].
  destruct (exp_series_arch M (qltT_leT' 0 M HMpos)) as [C [HC1 HC]].
  assert (HCposT : QltT 0 C).
  { apply (qltT_leT'_ltT 0 1 C). exact qltT_0_1. exact HC1. }
  destruct (exp_partial_tail_small M C (qltT_leT' 0 M HMpos) HC1) as [m0 Hm0].
  (* 构造 real_lt：eps = 1/(2C)（Set 正性链），N = 2·m0 + 1 *)
  exists (1 / (2 * C)).
  split.
  - apply (qltT_div_pos 1 (2 * C)).
    + exact qltT_0_1.
    + apply (qmult_ltT_0_compat 2 C). exact qltT_0_2. exact HCposT.
  - exists (2 * m0 + 1)%nat.
    intros n Hn.
    assert (Hsub0 : exp_partial n (u n) - 0 == exp_partial n (u n)) by ring.
    apply (qltT_eq_compat_r (exp_partial n (u n) - 0) (exp_partial n (u n)) (1 / (2 * C))).
    + exact Hsub0.
    + (* 目标 QltT (1/(2C)) (exp_partial n (u n))：转 Prop 后分奇偶（ex 消去限制） *)
      apply Qlt_to_QltT.
      destruct (Nat.odd n) eqn:En.
      * (* n 奇：n = 2k+1，需 m0 ≤ k *)
        apply Nat.odd_spec in En. destruct En as [k Hk].
        subst n.
        apply NatLe_drop in Hn.
        assert (Hk0 : (m0 <= k)%nat) by lia.
        apply (exp_partial_odd_lower M C m0 k (u (2 * k + 1)%nat) (qltT_leT' 0 M HMpos) HC1 HC Hm0 Hk0).
        exact (HM (2 * k + 1)%nat).
      * (* n 偶：n = 2k；1/(2C) < 1/C ≤ exp_partial (2k) (u (2k)) *)
        assert (Heven_true : Nat.even n = true).
        { rewrite <- (Nat.negb_odd n).
          rewrite En. reflexivity. }
        apply Nat.even_spec in Heven_true. destruct Heven_true as [k Hk].
        subst n.
        apply (Qlt_le_trans _ (1 / C) _).
        -- (* 1/(2C) < 1/C *)
           apply (Qlt_minus_iff (1 / (2 * C)) (1 / C)).
           unfold Qdiv.
           assert (Hf : 1 / C + - (1 / (2 * C)) == 1 / (2 * C)).
           { field.
             apply q_neq_of_lt.
             apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC1)]. }
           setoid_rewrite Hf.
           apply (Qlt_le_trans _ (Qinv (2 * C)) _).
           { apply Qinv_lt_0_compat.
             apply (Qmult_lt_0_compat 2 C).
             - unfold Qlt; simpl; lia.
             - apply (Qlt_le_trans _ 1 _); [reflexivity | exact (QleT'_to_Qle _ _ HC1)]. }
           { apply qeq_le. apply Qeq_sym. apply (Qmult_1_l (Qinv (2 * C))). }
        -- (* 1/C ≤ exp_partial (2k) (u (2k)) *)
           apply (exp_partial_even_lower M C (u (2 * k)%nat) k (qltT_leT' 0 M HMpos) HC1 HC).
           exact (HM (2 * k)%nat).
Qed.

(* 反三角：| |a| − |b| | ≤ |a − b|（Prop 层 Qle 版，real_abs 柯西性核心）
   标准库已有 Qabs_triangle_reverse : Qabs x - Qabs y <= Qabs (x - y)，
   双向版 = 该引理 + 对称（Qabs_opp + Qabs_wd）*)
Lemma q_abs_abs_triangle : forall a b : Q,
  Qle (Qabs (Qabs a - Qabs b)) (Qabs (a - b)).
Proof.
  intros a b.
  apply Qabs_Qle_condition.
  split.
  - (* 左：-|a−b| ≤ |a|−|b| ⟸ |b|−|a| ≤ |a−b| 取负 *)
    apply (Qle_trans _ (Qopp (Qabs b - Qabs a)) _).
    + apply (Qopp_le_compat (Qabs b - Qabs a) (Qabs (a - b))).
      apply (Qle_trans _ (Qabs (b - a)) _).
      * apply Qabs_triangle_reverse.
      * (* |b−a| ≤ |a−b|：b−a == −(a−b)，Qabs_opp 对称 *)
        apply qeq_le.
        transitivity (Qabs (- (a - b))).
        -- apply Qabs_wd. ring.
        -- apply Qabs_opp.
    + apply qeq_le. ring.
  - (* 右：|a|−|b| ≤ |a−b|：标准库直接给 *)
    apply Qabs_triangle_reverse.
Qed.

(* 主文件 QltT 传递桥（若需）：QltT x y -> QltT y z -> QltT x z *)
Lemma qltT_trans : forall x y z : Q, QltT x y -> QltT y z -> QltT x z.
Proof.
  intros x y z Hxy Hyz.
  apply Qlt_to_QltT.
  apply (Qlt_trans _ y _).
  - apply QltT_to_Qlt. exact Hxy.
  - apply QltT_to_Qlt. exact Hyz.
Qed.

(* real_abs：逐点 Qabs + 柯西性（反三角 + QltT 桥） *)
Definition real_abs (x : Real) : Real.
Proof.
  destruct x as [u Hu].
  exists (fun n => Qabs (u n)).
  intros eps Heps.
  destruct (Hu eps Heps) as [N HN].
  exists N.
  intros m n Hm Hn.
  (* 目标：QltT (Qabs (Qabs (u m) - Qabs (u n))) eps *)
  apply Qlt_to_QltT.
  apply (Qle_lt_trans _ (Qabs (u m - u n)) _).
  - apply (q_abs_abs_triangle (u m) (u n)).
  - apply QltT_to_Qlt. apply (HN m n Hm Hn).
Defined.

(* real_metric：|x − y| *)
Definition real_metric (x y : Real) : Real :=
  real_abs (real_plus x (real_opp y)).

(* |-x| == |x|：逐点 Qabs_opp（real_eq 版，逐 eps） *)
Lemma real_abs_opp : forall x : Real, real_eq (real_abs (real_opp x)) (real_abs x).
Proof.
  intros x. destruct x as [u Hu].
  unfold real_abs, real_opp, real_eq.
  intros eps Heps. exists 0%nat. intros n _.
  apply Qlt_to_QltT.
  apply (Qle_lt_trans _ 0 _).
  - apply qeq_le.
    apply (Qabs_wd (Qabs (Qopp (u n)) - Qabs (u n)) 0).
    rewrite (Qabs_opp (u n)). ring.
  - apply QltT_to_Qlt. exact Heps.
Qed.

(* real_abs 的逐点投影：projT1 (real_abs x) n == Qabs (projT1 x n) *)
Lemma real_abs_proj : forall (x : Real) (n : nat),
  projT1 (real_abs x) n == Qabs (projT1 x n).
Proof.
  intros x n. destruct x as [u Hu]. reflexivity.
Qed.

(* 三角不等式（逐 eps 形式，real_le 的 Or 编码无法表达"非严格且不趋近"，
   故用 Bishop 逐 eps 上界：∀eps>0 ∃N ∀n≥N，A_n ≤ B_n + eps） *)
Lemma real_abs_triangle_eps : forall (x y : Real) (eps : Q),
  QltT 0 eps -> sigT (fun N : nat => forall n : nat, (N <= n)%nat ->
    Qle (projT1 (real_abs (real_plus x y)) n)
        (projT1 (real_abs x) n + projT1 (real_abs y) n + eps)).
Proof.
  intros x y eps Heps.
  exists 0%nat. intros n _.
  rewrite (real_abs_proj (real_plus x y) n).
  rewrite (real_abs_proj x n).
  rewrite (real_abs_proj y n).
  rewrite (real_plus_proj x y n).
  destruct x as [u Hu]. destruct y as [v Hv].
  cbn [projT1].
  apply (Qle_trans _ (Qabs (u n) + Qabs (v n)) _).
  - exact (Qabs_triangle (u n) (v n)).
  - apply (Qle_trans _ (Qabs (u n) + Qabs (v n) + 0) _).
    + apply qeq_le. ring.
    + apply (Qplus_le_compat (Qabs (u n) + Qabs (v n)) (Qabs (u n) + Qabs (v n)) 0 eps).
      * apply Qle_refl.
      * apply (Qlt_le_weak 0 eps). apply QltT_to_Qlt. exact Heps.
Qed.

(* ============ 阶段 1 续：real_inv_pos（柯西倒数） ============ *)

(* 倒数差界（Qle 版）：0 < eps < a、0 < eps < b ⟹
   |1/a − 1/b| ≤ |a − b| · Qinv (eps·eps)
   证明：|1/a−1/b| == |a−b|/(|a||b|) ≤ |a−b|/eps²（q_le_div_le 扩分三明治） *)
Lemma q_inv_diff_bound :
  forall (a b eps : Q), Qlt 0 eps -> Qlt eps a -> Qlt eps b ->
  Qle (Qabs (Qinv a - Qinv b))
      (Qmult (Qabs (a - b)) (Qinv (Qmult eps eps))).
Proof.
  intros a b eps Heps Ha Hb.
  (* a,b > eps > 0 ⟹ 非零、正 *)
  assert (Ha0 : ~ a == 0) by (apply q_neq_of_lt; apply (Qlt_trans _ eps _); [exact Heps | exact Ha]).
  assert (Hb0 : ~ b == 0) by (apply q_neq_of_lt; apply (Qlt_trans _ eps _); [exact Heps | exact Hb]).
  assert (Hapos : Qlt 0 a) by (apply (Qlt_trans _ eps _); [exact Heps | exact Ha]).
  assert (Hbpos : Qlt 0 b) by (apply (Qlt_trans _ eps _); [exact Heps | exact Hb]).
  (* |1/a − 1/b| == |a − b| / (|a|·|b|) *)
  assert (Hmain : Qabs (Qinv a - Qinv b) ==
                  Qabs (a - b) / Qmult (Qabs a) (Qabs b)).
  { unfold Qdiv.
    transitivity (Qabs (Qmult (Qinv (Qmult a b)) (b - a))).
    - (* |1/a − 1/b| == |(b−a)/(ab)|：1/a − 1/b == (b−a)/(ab) *)
      apply Qabs_wd.
      field; split; assumption.
    - (* |(b−a)/(ab)| == |b−a|·|1/(ab)| == |a−b|/|ab| *)
      transitivity (Qmult (Qabs (Qinv (Qmult a b))) (Qabs (b - a))).
      + apply Qabs_Qmult.
      + transitivity (Qmult (Qabs (Qinv (Qmult a b))) (Qabs (a - b))).
        * apply Qmult_comp.
          -- apply Qeq_refl.
          -- (* Qabs (b−a) == Qabs (a−b)：b−a == −(a−b)，Qabs_wd + Qabs_opp *)
             apply (Qeq_trans _ (Qabs (- (a - b))) _).
             ++ apply Qabs_wd. ring.
             ++ apply Qabs_opp.
        * (* Qabs(|1/ab|)·|a−b| == |a−b|·Qinv(|ab|) == |a−b|·Qinv(|a||b|) *)
          transitivity (Qmult (Qabs (a - b)) (Qabs (Qinv (Qmult a b)))).
          -- apply Qeq_sym. apply Qmult_comm.
          -- transitivity (Qmult (Qabs (a - b)) (Qinv (Qabs (Qmult a b)))).
             ++ apply Qmult_comp.
                ** apply Qeq_refl.
                ** apply (Qabs_Qinv (Qmult a b)).
             ++ apply Qmult_comp.
                ** apply Qeq_refl.
                ** apply (Qinv_comp (Qabs (Qmult a b)) (Qmult (Qabs a) (Qabs b))).
                   apply Qabs_Qmult. }
  (* 用 q_le_div_le：a1=|a−b|、b1=|a||b|、c1=|a−b|、d1=eps·eps，需 |a−b|·eps² ≤ |a−b|·(|a||b|) *)
  rewrite Hmain.
  apply (q_le_div_le (Qabs (a - b)) (Qmult (Qabs a) (Qabs b))
                      (Qabs (a - b)) (Qmult eps eps)).
  - apply (Qmult_lt_0_compat (Qabs a) (Qabs b)).
    + (* 0 < |a|：a > 0 ⟹ |a| == a *)
      apply (Qlt_le_trans _ a _).
      * exact Hapos.
      * apply qeq_le. apply Qeq_sym. apply (Qabs_pos a). apply (Qlt_le_weak 0 a). exact Hapos.
    + apply (Qlt_le_trans _ b _).
      * exact Hbpos.
      * apply qeq_le. apply Qeq_sym. apply (Qabs_pos b). apply (Qlt_le_weak 0 b). exact Hbpos.
  - apply (Qmult_lt_0_compat eps eps); [exact Heps | exact Heps].
  - (* |a−b|·(eps·eps) ≤ |a−b|·(|a|·|b|)：|a−b| ≥ 0 且 eps·eps ≤ |a|·|b| *)
    (* 先换序：|a−b|·eps² == eps²·|a−b|，RHS 同理 *)
    rewrite (Qmult_comm (Qabs (a - b)) (Qmult eps eps)).
    rewrite (Qmult_comm (Qabs (a - b)) (Qmult (Qabs a) (Qabs b))).
    apply (Qmult_le_compat_r (Qmult eps eps) (Qmult (Qabs a) (Qabs b)) (Qabs (a - b))).
    + (* eps·eps ≤ |a|·|b|：eps ≤ |a|、eps ≤ |b|（a,b > eps > 0） *)
      (* 分步：eps·eps ≤ eps·|b| ≤ |a|·|b|（Qmult_le_compat_r 两次） *)
      apply (Qle_trans _ (Qmult eps (Qabs b)) _).
      * (* eps·eps ≤ eps·|b|：右乘 eps，eps ≤ |b|（x·z ≤ y·z 给 eps·eps ≤ |b|·eps，换序） *)
        apply (Qle_trans _ (Qmult (Qabs b) eps) _).
        -- apply (Qmult_le_compat_r eps (Qabs b) eps).
           ++ apply (Qle_trans _ b _).
              ** apply (Qlt_le_weak _ _ Hb).
              ** apply qeq_le. apply Qeq_sym. apply (Qabs_pos b). apply (Qlt_le_weak 0 b). exact Hbpos.
           ++ apply (Qlt_le_weak 0 eps). exact Heps.
        -- apply qeq_le. apply Qmult_comm.
      * (* eps·|b| ≤ |a|·|b|：右乘 |b|，eps ≤ |a| *)
        apply (Qmult_le_compat_r eps (Qabs a) (Qabs b)).
        -- apply (Qle_trans _ a _).
           ++ apply (Qlt_le_weak _ _ Ha).
           ++ apply qeq_le. apply Qeq_sym. apply (Qabs_pos a). apply (Qlt_le_weak 0 a). exact Hapos.
        -- apply (Qlt_le_weak 0 (Qabs b)).
           apply (Qlt_le_trans _ b _).
           ++ exact Hbpos.
           ++ apply qeq_le. apply Qeq_sym. apply (Qabs_pos b). apply (Qlt_le_weak 0 b). exact Hbpos.
    + apply Qabs_nonneg.
Qed.

(* real_inv_pos：柯西倒数（正下界 eps0 保护，m,n ≥ N0 时取 Qinv (u n)） *)
Definition real_inv_pos (x : Real) (Hx : real_lt real_zero x) : Real.
Proof.
  destruct x as [u Hu].
  destruct Hx as [eps0 [Heps0 [N0 HN0]]].
  exists (fun n => if Nat.leb N0 n then Qinv (u n) else Qinv (u N0)).
  intros eps Heps.
  set (delta := Qmult eps (Qmult eps0 eps0)).
  assert (Hdlt : QltT 0 delta).
  { unfold delta. apply Qlt_to_QltT.
    apply (Qmult_lt_0_compat eps (Qmult eps0 eps0)).
    - apply QltT_to_Qlt. exact Heps.
    - apply (Qmult_lt_0_compat eps0 eps0).
      + apply QltT_to_Qlt. exact Heps0.
      + apply QltT_to_Qlt. exact Heps0. }
  destruct (Hu delta Hdlt) as [N1 HN1].
  exists (Nat.max N0 N1).
  intros m n Hm Hn.
  apply NatLe_drop in Hm. apply NatLe_drop in Hn.
  assert (Hm0 : (N0 <= m)%nat) by lia.
  assert (Hn0 : (N0 <= n)%nat) by lia.
  rewrite (leb_correct _ _ Hm0).
  rewrite (leb_correct _ _ Hn0).
  (* 目标：QltT (Qabs (Qinv (u m) - Qinv (u n))) eps *)
  apply Qlt_to_QltT.
  (* u m, u n > eps0：HN0 直接给 QltT eps0 (projT1 x m - 0)，x 已 destruct 为 existT u Hu *)
  assert (Hum : QltT eps0 (u m - 0)).
  { change (QltT eps0 (projT1 (existT (fun s : Qseq => cauchy s) u Hu) m - projT1 real_zero m)).
    apply (HN0 m). apply NatLe_lift. exact Hm0. }
  assert (Hun : QltT eps0 (u n - 0)).
  { change (QltT eps0 (projT1 (existT (fun s : Qseq => cauchy s) u Hu) n - projT1 real_zero n)).
    apply (HN0 n). apply NatLe_lift. exact Hn0. }
  apply (Qle_lt_trans _ (Qmult (Qabs (u m - u n)) (Qinv (Qmult eps0 eps0))) _).
  - apply (q_inv_diff_bound (u m) (u n) eps0).
    + apply QltT_to_Qlt. exact Heps0.
    + (* u m - 0 < ...：先换 eps0 < u m 由 eps0 < u m - 0 与 u m - 0 == u m *)
      apply (Qlt_le_trans _ (u m - 0) _).
      * apply QltT_to_Qlt. exact Hum.
      * apply qeq_le. ring.
    + apply (Qlt_le_trans _ (u n - 0) _).
      * apply QltT_to_Qlt. exact Hun.
      * apply qeq_le. ring.
  - (* |u m − u n| · (1/eps0²) < eps：|u m − u n| < eps·eps0²（HN1 at delta） *)
    assert (Hdiff : QltT (Qabs (u m - u n)) delta).
    { apply (HN1 m n); apply NatLe_lift; lia. }
    unfold delta in Hdiff.
    (* (x·1/eps0²) < eps 由 x < eps·eps0²：乘 Qinv (eps0·eps0)（正） *)
    apply (Qlt_le_trans _ (Qmult (Qmult eps (Qmult eps0 eps0)) (Qinv (Qmult eps0 eps0))) _).
    { apply (Qmult_lt_compat_r (Qabs (u m - u n)) (Qmult eps (Qmult eps0 eps0))
                               (Qinv (Qmult eps0 eps0))).
      - apply Qinv_lt_0_compat.
        apply (Qmult_lt_0_compat eps0 eps0).
        + apply QltT_to_Qlt. exact Heps0.
        + apply QltT_to_Qlt. exact Heps0.
      - exact (QltT_to_Qlt _ _ Hdiff). }
    { (* eps·(eps0·eps0)·(1/(eps0·eps0)) ≤ eps：约分 Qmult_inv_r *)
      apply qeq_le.
      transitivity (eps * ((eps0 * eps0) * Qinv (eps0 * eps0))).
      { apply Qeq_sym.
        apply (Qmult_assoc eps (Qmult eps0 eps0) (Qinv (Qmult eps0 eps0))). }
      { transitivity (eps * 1).
        + rewrite (Qmult_inv_r (Qmult eps0 eps0)).
          * reflexivity.
          * apply q_neq_of_lt. apply (Qmult_lt_0_compat eps0 eps0).
            -- apply QltT_to_Qlt. exact Heps0.
            -- apply QltT_to_Qlt. exact Heps0.
        + ring. } }
Defined.

(* real_inv_pos 正确性：x · (1/x) == 1（n ≥ N0 时 u n·(1/u n) == 1，field） *)
Lemma real_inv_pos_correct :
  forall (x : Real) (Hx : real_lt real_zero x),
  real_eq (real_mult x (real_inv_pos x Hx)) real_one.
Proof.
  intros x Hx.
  destruct x as [u Hu].
  destruct Hx as [eps0 [Heps0 [N0 HN0]]].
  unfold real_mult, real_inv_pos, real_one, real_eq.
  intros eps Heps.
  exists N0.
  intros n Hn.
  (* 目标：QltT (Qabs (u n · (if N0≤n then 1/u n else 1/u N0) − 1)) eps *)
  (* 归约 projT1：real_mult 的序列 == fun n => u n · (if ...) *)
  cbn [projT1].
  destruct (Nat.leb N0 n) eqn:Eleb.
  - (* N0 ≤ n：用 1/u n；u n·(1/u n) == 1（Qmult_inv_r，u n ≠ 0） *)
    assert (Hun0 : ~ u n == 0).
    { apply q_neq_of_lt.
      apply (Qlt_trans _ eps0 _); [apply QltT_to_Qlt; exact Heps0 | ].
      (* 目标：eps0 < u n；HN0 给 eps0 < u n - 0，桥 u n - 0 == u n *)
      apply (Qlt_le_trans _ (u n - 0) _).
      - apply QltT_to_Qlt.
        change (QltT eps0 (projT1 (existT (fun s : Qseq => cauchy s) u Hu) n - projT1 real_zero n)).
        apply (HN0 n). apply NatLe_lift. apply Nat.leb_le. exact Eleb.
      - apply qeq_le. ring. }
    apply Qlt_to_QltT.
    apply (Qle_lt_trans _ 0 _).
    + (* |u n·(1/u n) − 1| == 0 ≤ 0：Hsub 后 Qabs_wd *)
      assert (Hsub : u n * / u n - 1 == 0).
      { rewrite (Qmult_inv_r (u n) Hun0). ring. }
      apply qeq_le.
      (* 目标：Qabs (u n·(1/u n) − 1) == 0 *)
      transitivity (Qabs 0).
      * apply (Qabs_wd (u n * / u n - 1) 0). exact Hsub.
      * (* Qabs 0 == 0：Qabs_neg（0 ≤ 0） *)
        apply (Qeq_trans _ (- 0) _).
        -- apply Qabs_neg. apply Qle_refl.
        -- ring.
    + apply QltT_to_Qlt. exact Heps.
  - (* ¬N0 ≤ n：n < N0，用 1/u N0——但 real_eq 只需最终性质，n ≥ N0 已覆盖；
      此分支不可能（n ≥ N0 由 exists N0 保证）——排除 *)
    apply Nat.leb_gt in Eleb.
    apply NatLe_drop in Hn.
    exfalso. lia.
Qed.

(* real_inv_pos 正性：x > 0 ⟹ 1/x > 0
   策略：取 eps := Qinv (M+1)，n ≥ N0 时 u n ≤ M < M+1（Qinv_lt_contravar）
   得 Qinv (M+1) < Qinv (u n)，即 inv_n − 0 > eps *)
Lemma real_inv_pos_pos :
  forall (x : Real) (Hx : real_lt real_zero x),
  real_lt real_zero (real_inv_pos x Hx).
Proof.
  intros x Hx.
  destruct x as [u Hu].
  destruct Hx as [eps0 [Heps0 [N0 HN0]]].
  (* 全局上界 M：|u k| ≤ M（real_norm_bounded） *)
  destruct (real_norm_bounded (existT (fun s : Qseq => cauchy s) u Hu)) as [M [HMpos HM]].
  (* 取 eps := Qinv (M + 1)，N := N0 *)
  unfold real_inv_pos, real_lt, real_zero.
  exists (Qinv (M + 1)).
  split.
  - (* 0 < Qinv (M+1) *)
    apply Qlt_to_QltT.
    apply Qinv_lt_0_compat.
    apply (Qlt_le_trans _ 1 _).
    + reflexivity.  (* 0 < 1 计算可判定 *)
    + (* 1 ≤ M+1：1 ≤ 1+M == M+1 *)
      apply (Qle_trans _ (1 + M) _).
      * apply (Qle_plus_nonneg_r 1 M). apply (Qlt_le_weak 0 M). apply QltT_to_Qlt. exact HMpos.
      * apply qeq_le. apply Qplus_comm.
  - exists N0.
    intros n Hn.
    cbn [projT1].
    destruct (Nat.leb N0 n) eqn:Eleb.
    + (* n ≥ N0：inv_n == Qinv (u n)；需 Qinv (M+1) < Qinv (u n) *)
      apply Qlt_to_QltT.
      (* 前提：0 < u n、0 < M+1、u n < M+1 *)
      assert (Hu0 : Qlt 0 (u n)).
      { apply (Qlt_le_trans _ (u n - 0) _).
        - apply (Qlt_trans _ eps0 _).
          + apply QltT_to_Qlt. exact Heps0.
          + apply QltT_to_Qlt. apply (HN0 n). apply NatLe_lift. apply Nat.leb_le. exact Eleb.
        - apply qeq_le. ring. }
      assert (HM1 : Qlt 0 (M + 1)).
      { apply (Qlt_le_trans _ 1 _); [reflexivity | ].
        apply (Qle_trans _ (1 + M) _).
        - apply (Qle_plus_nonneg_r 1 M). apply (Qlt_le_weak 0 M). apply QltT_to_Qlt. exact HMpos.
        - apply qeq_le. apply Qplus_comm. }
      assert (Hult : Qlt (u n) (M + 1)).
      { apply (Qle_lt_trans _ (Qabs (u n)) _).
        - apply Qle_Qabs.
        - apply (Qle_lt_trans _ M _).
          + apply QleT'_to_Qle. apply (HM n).
          + (* M < M+1：M == M+0，M+0 < M+1（Qplus_lt_r：0 < 1），再桥 M == M+0 *)
            apply (Qle_lt_trans _ (M + 0) _).
            * apply qeq_le. ring.  (* M ≤ M+0：M == M+0 *)
            * apply (proj2 (Qplus_lt_r 0 1 M)). reflexivity.  (* M+0 < M+1 ⟸ 0 < 1 *) }
      (* 目标：QltT (Qinv (M+1)) (Qinv (u n) − 0)；RHS == Qinv (u n) *)
      apply (Qlt_le_trans _ (Qinv (u n)) _).
      { exact (proj1 (Qinv_lt_contravar (u n) (M + 1) Hu0 HM1) Hult). }
      { (* Qinv (u n) ≤ Qinv (u n) − 0：Qinv(u n) − 0 == Qinv(u n) 反向 *)
        apply qeq_le. ring. }
    + (* ¬N0 ≤ n：矛盾 *)
      apply Nat.leb_gt in Eleb.
      apply NatLe_drop in Hn.
      exfalso. lia.
Qed.
Section RealExpLogInterface.

Context {RI : RealInterface}.

Variable real_exp : R -> R.
Variable real_log : R -> R.

Variable real_exp_pos : forall x : R, lt zero (real_exp x).
Variable real_log_exp : forall x : R, Id (real_log (real_exp x)) x.
Variable real_exp_zero : Id (real_exp zero) one.
Variable real_exp_plus : forall a b : R, Id (real_exp (plus a b)) (mult (real_exp a) (real_exp b)).

Variable real_log_mult : forall a b : R, lt zero a -> lt zero b ->
                           Id (real_log (mult a b)) (plus (real_log a) (real_log b)).
Variable real_log_one : Id (real_log one) zero.
Variable real_log_lt : forall a b : R, lt a b -> lt (real_log a) (real_log b).

End RealExpLogInterface.

(* ============================================================ *)
(* 可微性相关章节：组合律作为假设变量                         *)
(* ============================================================ *)

(* 注：原 DifferentiableComposeHyp Section 的 Variable differentiable_compose
   已删除——链式法则已在 L14249 完整证明（Theorem differentiable_compose），
   该 Variable 为虚假假设（零引用），P0 审计清除（v65 应证定理优先级分析）。 *)

(* ============================================================ *)
(* 熵导数与收敛性定理（假设变量形式）                          *)
(* ============================================================ *)

(* 原 Section EntropyDerivative（L8768-8805，entropy_differentiable Variable）已删除——
   P0.5 冗余清理（备份 80）：其熵可微性已由 L17171 Section EntropyDifferentiable 的
   Theorem entropy_differentiable（Differentiable entropy_ent）实质证明替代；
   旧 Section 零下游引用。 *)

Section ConvergenceTheorem.

Context {RI : RealInterfaceEnhanced}.

(* 解包 RealInterface 字段 *)
Let R := @R RI.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let abs := @abs RI.
Let lt := @lt RI.
Let le := @le RI.
Let minus := @minus RI.
Let lim := @lim RI.

Variable entropy : R -> R.
Variable entropy_gradient : R -> R.
Variable dynamics : R -> R.
Variable eta : R.

(* 动力学是梯度上升步进（诚实接口）：x_{n+1} = x_n + η·g(x_n)。
   dynamics_converges 的收敛论证依赖此结构——dynamics 抽象无定义时
   收敛不可证，补此接口使 iterate 的单步差公式成为可证定理。 *)
Variable dynamics_gradient_step : forall x : R,
  Id (dynamics x) (plus x (mult eta (entropy_gradient x))).

Variable strict_concavity :
  forall x y : R, lt x y -> lt (entropy_gradient y) (entropy_gradient x).

Variable L : R.
Variable L_pos : lt zero L.
Variable gradient_lipschitz :
  forall x y : R,
    le (abs (minus (entropy_gradient x) (entropy_gradient y)))
       (mult L (abs (minus x y))).

Variable S_max : R.
Variable entropy_upper_bound : forall E_A, le (entropy E_A) S_max.

(* iterate 的单步差公式（非平凡代数核心）：x_{n+1} − x_n == η·g(x_n)。
   归纳于 n，用 dynamics_gradient_step 逐点替换。 *)
Theorem iterate_step_diff : forall (E_A : R) (n : nat),
  Id (minus (iterate dynamics (Datatypes.S n) E_A) (iterate dynamics n E_A))
     (mult eta (entropy_gradient (iterate dynamics n E_A))).
Proof.
  intros E_A n. induction n as [| n IH]; simpl.
  - (* 基例：dynamics E_A − E_A == eta·g(E_A)。
       dynamics E_A == plus E_A (eta·g(E_A))（dynamics_gradient_step）⟹
       minus (plus E_A (eta·g)) E_A == eta·g（minus_plus_cancel_r）。 *)
    assert (Hstep : Id (dynamics E_A) (plus E_A (mult eta (entropy_gradient E_A))))
      by exact (dynamics_gradient_step E_A).
    assert (Hgoal : Id (minus (plus E_A (mult eta (entropy_gradient E_A))) E_A)
                       (mult eta (entropy_gradient E_A)))
      by exact (minus_plus_cancel_r E_A (mult eta (entropy_gradient E_A))).
    exact (id_trans (id_cong (fun z => minus z E_A) Hstep) Hgoal).
  - (* 归纳步：iterate dynamics (S(Datatypes.S n)) E_A − iterate dynamics (Datatypes.S n) E_A
       == dynamics(iterate dynamics (Datatypes.S n) E_A) − iterate dynamics (Datatypes.S n) E_A
       == eta·g(iterate dynamics (Datatypes.S n) E_A)（基例模式）。 *)
    assert (Hstep : Id (dynamics (iterate dynamics (Datatypes.S n) E_A))
                       (plus (iterate dynamics (Datatypes.S n) E_A)
                             (mult eta (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)))))
      by exact (dynamics_gradient_step (iterate dynamics (Datatypes.S n) E_A)).
    assert (Hgoal : Id (minus (plus (iterate dynamics (Datatypes.S n) E_A)
                                    (mult eta (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))))
                              (iterate dynamics (Datatypes.S n) E_A))
                       (mult eta (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))))
      by exact (minus_plus_cancel_r (iterate dynamics (Datatypes.S n) E_A)
                                    (mult eta (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)))).
    exact (id_trans (id_cong (fun z => minus z (iterate dynamics (Datatypes.S n) E_A)) Hstep) Hgoal).
Qed.

(* 梯度单调性（严格凹 ⟹ 梯度严格递减）：lt x y -> lt (g y) (g x)。
   strict_concavity 的显式化——收敛论证的凹性核心，标明迭代前提可复用。 *)
Theorem entropy_gradient_strict_mono : forall x y : R,
  lt x y -> lt (entropy_gradient y) (entropy_gradient x).
Proof.
  intros x y Hxy. exact (strict_concavity x y Hxy).
Qed.

(* 梯度差的有界性（L-Lipschitz 的零起点特化）：|g(x) − g(0)| ≤ L·|x|。
   gradient_lipschitz 于 y := zero——收敛论证中梯度绝对值的界。 *)
Theorem gradient_diff_from_zero : forall x : R,
  le (abs (minus (entropy_gradient x) (entropy_gradient zero)))
     (mult L (abs (minus x zero))).
Proof.
  intro x. exact (gradient_lipschitz x zero).
Qed.

(* 单步差的绝对值：|x_{n+1} − x_n| == |η|·|g(x_n)|。
   由 iterate_step_diff + abs_mult 换形。 *)
Theorem iterate_step_abs_diff : forall (E_A : R) (n : nat),
  Id (abs (minus (iterate dynamics (Datatypes.S n) E_A) (iterate dynamics n E_A)))
     (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))).
Proof.
  intros E_A n.
  assert (Hdiff : Id (minus (iterate dynamics (Datatypes.S n) E_A) (iterate dynamics n E_A))
                     (mult eta (entropy_gradient (iterate dynamics n E_A))))
    by exact (iterate_step_diff E_A n).
  apply (id_trans (id_cong abs Hdiff)).
  apply (abs_mult eta (entropy_gradient (iterate dynamics n E_A))).
Qed.

(* 梯度差的递推界：|g(x_{n+1}) − g(x_n)| ≤ L·|η|·|g(x_n)|。
   gradient_lipschitz 于 x_{n+1}, x_n + iterate_step_abs_diff 链。
   收敛论证的核心递推——步长差由梯度绝对值控制。 *)
Theorem gradient_step_recurrence : forall (E_A : R) (n : nat),
  le (abs (minus (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))
                 (entropy_gradient (iterate dynamics n E_A))))
     (mult (mult L (abs eta)) (abs (entropy_gradient (iterate dynamics n E_A)))).
Proof.
  intros E_A n.
  (* gradient_lipschitz：|g(x_{n+1}) − g(x_n)| ≤ L·|x_{n+1} − x_n| *)
  assert (Hlip : le (abs (minus (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))
                                (entropy_gradient (iterate dynamics n E_A))))
                    (mult L (abs (minus (iterate dynamics (Datatypes.S n) E_A)
                                        (iterate dynamics n E_A)))))
    by exact (gradient_lipschitz (iterate dynamics (Datatypes.S n) E_A)
                                 (iterate dynamics n E_A)).
  (* 换 |x_{n+1} − x_n| 为 |η|·|g(x_n)|（iterate_step_abs_diff） *)
  assert (Habs : Id (abs (minus (iterate dynamics (Datatypes.S n) E_A)
                                (iterate dynamics n E_A)))
                    (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))))
    by exact (iterate_step_abs_diff E_A n).
  apply (le_trans _ (mult L (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A))))) _).
  - (* Hlip : |g(x_{n+1})−g(x_n)| ≤ L·|x_{n+1}−x_n|，换 RHS 的 |x_{n+1}−x_n| 为 |η|·|g| *)
    apply (le_id_r (abs (minus (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))
                               (entropy_gradient (iterate dynamics n E_A))))
                   (mult L (abs (minus (iterate dynamics (Datatypes.S n) E_A)
                                       (iterate dynamics n E_A))))
                   (mult L (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))))
                   (id_cong (fun z => mult L z) Habs)
                   Hlip).
  - (* 中间项 L·(|η|·|g|) ≤ 目标 (L·|η|)·|g|：mult_assoc 换形 + le_refl *)
    apply (le_id_r (mult L (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))))
                   (mult L (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))))
                   (mult (mult L (abs eta)) (abs (entropy_gradient (iterate dynamics n E_A))))
                   (mult_assoc L (abs eta) (abs (entropy_gradient (iterate dynamics n E_A))))
                   (le_refl _)).
Qed.

(* 梯度绝对值沿上升迭代单调：x < y、0 < g(y) < g(x) ⟹ |g(y)| ≤ |g(x)|。
   由 entropy_gradient_strict_mono（g 严格递减）+ abs_pos（正数保持）。
   收敛论证关键：|g(x_{n+1})| ≤ |g(x_n)|（柯西性的收缩基础）。 *)
Theorem gradient_abs_mono : forall x y : R,
  lt x y -> lt zero (entropy_gradient y) ->
  lt (entropy_gradient y) (entropy_gradient x) ->
  le (abs (entropy_gradient y)) (abs (entropy_gradient x)).
Proof.
  intros x y Hxy Hgypos Hgygx.
  (* |g(y)| = g(y)（abs_pos，0 < g(y)）≤ g(x) = |g(x)|（abs_pos，0 < g(y) < g(x) ⟹ 0 < g(x)） *)
  assert (Hgxpos : lt zero (entropy_gradient x))
    by (apply (lt_trans _ (entropy_gradient y) _); [exact Hgypos | exact Hgygx]).
  assert (Habsy : Id (abs (entropy_gradient y)) (entropy_gradient y))
    by exact (abs_pos (entropy_gradient y) Hgypos).
  assert (Habsx : Id (abs (entropy_gradient x)) (entropy_gradient x))
    by exact (abs_pos (entropy_gradient x) Hgxpos).
  apply (le_id_l (abs (entropy_gradient y))
                 (entropy_gradient y)
                 (abs (entropy_gradient x))
                 Habsy).
  apply (le_id_r (entropy_gradient y)
                 (entropy_gradient x)
                 (abs (entropy_gradient x))
                 (id_sym Habsx)
                 (lt_le_iff _ _ (inl Hgygx))).
Qed.

(* 原 dynamics_converges Variable 已由 ConvergenceCauchy Section 内 Theorem
   dynamics_converges（备份 80 后，lim 夹逼核心 grad_squeeze_zero）替换——
   见 L9607 前：以 ConvergenceCauchy 条件集（kappa 几何衰减等）证明，
   前提为初始梯度非零 lt zero (abs (entropy_gradient (iterate dynamics 0 E_A)))。 *)

End ConvergenceTheorem.

(* ============================================================ *)
(* 工程③阶段 B / P1-2：柯西论证（合并自 probe_converge2.v）      *)
(* ============================================================ *)
Section ConvergenceCauchy.

Context {RI : RealInterfaceEnhanced}.

(* 解包 RealInterface 字段 *)
Let R := @R RI.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let abs := @abs RI.
Let lt := @lt RI.
Let le := @le RI.
Let minus := @minus RI.
Let lim := @lim RI.
Let metric := @metric RI.

(* 复制 ConvergenceTheorem 的诚实接口 Variable（同主文件 L7385-7407） *)
Variable entropy : R -> R.
Variable entropy_gradient : R -> R.
Variable dynamics : R -> R.
Variable eta : R.
Variable dynamics_gradient_step : forall x : R,
  Id (dynamics x) (plus x (mult eta (entropy_gradient x))).
Variable strict_concavity : forall x y : R, lt x y -> lt (entropy_gradient y) (entropy_gradient x).
Variable L : R.
Variable L_pos : lt zero L.
Variable gradient_lipschitz :
  forall x y : R,
    le (abs (minus (entropy_gradient x) (entropy_gradient y)))
       (mult L (abs (minus x y))).
Variable S_max : R.
Variable entropy_upper_bound : forall E_A, le (entropy E_A) S_max.

(* 新接口字段（诚实标准性质，E143-199 纪律） *)
(* (0) metric 由范数诱导（同 smetric_snorm 先例） *)
Variable metric_abs : forall a b : R, Id (metric a b) (abs (minus a b)).
(* (1) 梯度绝对值几何衰减（强凹收缩 content，诚实接口假设） *)
Variable kappa : R.
Variable kappa_pos : lt zero kappa.
Variable kappa_lt_one : lt kappa one.
Variable gradient_abs_decay : forall (E_A : R) (n : nat),
  le (abs (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)))
     (mult kappa (abs (entropy_gradient (iterate dynamics n E_A)))).
(* (2) lt+le 混合加保序（诚实接口假设，与主文件 DPO Section L12330 同族：
      抽象 R 层构造性缺此性质，0 < 1−κ 需要） *)
Variable lt_plus_compat_lt_le : forall a b c d : R, lt a b -> le c d -> lt (plus a c) (plus b d).
Variable lt_plus_compat_le_lt : forall a b c d : R, le a b -> lt c d -> lt (plus a c) (plus b d).

(* 主文件 ConvergenceTheorem 闭包定理的显式别名（Section 内 Variables 同名） *)
Let iter_abs := (@iterate_step_abs_diff RI entropy_gradient dynamics eta dynamics_gradient_step).
Let iter_diff := (@iterate_step_diff RI entropy_gradient dynamics eta dynamics_gradient_step).

(* ===== R 层幂 ===== *)
Fixpoint r_pow (x : R) (n : nat) : R :=
  match n with
  | 0%nat => one
  | Datatypes.S m => mult x (r_pow x m)
  end.

(* Step 4 新接口字段（诚实标准性质，E143-199 纪律） *)
(* (3) 度量自反零：metric a a == zero（构造性度量标准性质，抽象层缺） *)
Variable metric_refl_zero : forall a : R, Id (metric a a) zero.
(* (4) 几何击穿（R 层阿基米德性质）：0<a、0<eps ⟹ ∃n, a·κ^n < eps *)
Variable r_arch_pow : forall (a : R), lt zero a -> forall eps : R, lt zero eps ->
  sigT (fun n : nat => lt (mult a (r_pow kappa n)) eps).

(* 幂正性：0 < x ⟹ 0 < x^n *)
Lemma r_pow_pos : forall x n, lt zero x -> lt zero (r_pow x n).
Proof.
  intros x n Hx. induction n as [| m IH]; simpl.
  - exact (one_pos).
  - apply (mult_positive x (r_pow x m) Hx IH).
Qed.

(* 幂非负：0 < x ⟹ 0 ≤ x^n *)
Lemma r_pow_nonneg : forall x n, lt zero x -> le zero (r_pow x n).
Proof.
  intros x n Hx.
  apply (lt_le_iff _ _ (inl (r_pow_pos x n Hx))).
Qed.

(* 幂单调递减：0 < b < 1 ⟹ b^{S n} ≤ b^n *)
Lemma r_pow_dec : forall b n, lt zero b -> lt b one -> le (r_pow b (Datatypes.S n)) (r_pow b n).
Proof.
  intros b n Hb Hblt.
  induction n as [| m IH]; simpl.
  - (* b^1 = b·1 ≤ 1：mult_one 换形 *)
    apply (le_id_l _ b _).
    + apply (mult_one b).
    + apply (lt_le_iff _ _ (inl Hblt)).
  - apply (le_id_l _ (mult (r_pow b (Datatypes.S m)) b) _).
    + apply (mult_comm b (r_pow b (Datatypes.S m))).
    + apply (le_id_r _ (mult (r_pow b m) b) _).
      * apply (mult_comm (r_pow b m) b).
      * apply (le_mult_compat (r_pow b (Datatypes.S m)) (r_pow b m) b Hb).
        exact IH.
Qed.

(* ===== 梯度绝对值几何衰减迭代：|g(x_{n+k})| ≤ κ^k·|g(x_n)| ===== *)
Lemma grad_decay_iter : forall (E_A : R) (n k : nat),
  le (abs (entropy_gradient (iterate dynamics (n + k) E_A)))
     (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A)))).
Proof.
  intros E_A n k.
  induction k as [| k IH]; simpl.
  - (* k = 0：|g(x_n)| ≤ 1·|g(x_n)|（mult_comm + mult_one 换形） *)
    rewrite (Nat.add_0_r n).
    apply (le_id_r _ (abs (entropy_gradient (iterate dynamics n E_A))) _).
    + apply (id_trans (id_sym (mult_one (abs (entropy_gradient (iterate dynamics n E_A)))))
                      (id_sym (mult_comm one (abs (entropy_gradient (iterate dynamics n E_A)))))).
    + apply le_refl.
  - (* k = S k'：|g(x_{n+S k'})| ≤ κ·|g(x_{n+k'})| ≤ κ·(κ^{k'}·|g(x_n)|) == κ^{S k'}·|g(x_n)| *)
    apply (le_trans _ (mult kappa (abs (entropy_gradient (iterate dynamics (n + k) E_A)))) _).
    + (* 单步衰减：gradient_abs_decay at (n+k) *)
      rewrite (Nat.add_succ_r n k).
      apply (le_id_l _ (abs (entropy_gradient (iterate dynamics (Datatypes.S (n + k)) E_A))) _).
      * reflexivity.
      * exact (gradient_abs_decay E_A (n + k)).
    + (* κ·|g(x_{n+k})| ≤ κ·(κ^k·|g(x_n)|) == (κ·κ^k)·|g(x_n)|：le_trans + mult_assoc *)
      apply (le_trans _ (mult kappa (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A))))) _).
      * (* κ·Y ≤ κ·(κ^k·X)：mult_comm 换形 + le_mult_compat *)
        apply (le_id_l _ (mult (abs (entropy_gradient (iterate dynamics (n + k) E_A))) kappa) _).
        -- apply (mult_comm kappa (abs (entropy_gradient (iterate dynamics (n + k) E_A)))).
        -- apply (le_id_r _ (mult (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A)))) kappa) _).
           ++ apply (mult_comm (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A)))) kappa).
           ++ apply (le_mult_compat (abs (entropy_gradient (iterate dynamics (n + k) E_A)))
                                    (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A))))
                                    kappa kappa_pos).
              exact IH.
      * (* κ·(κ^k·X) ≤ (κ·κ^k)·X：le_id_r + mult_assoc 正向 *)
        apply (le_id_r _ (mult kappa (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A))))) _).
        -- apply (mult_assoc kappa (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A)))).
        -- apply le_refl.
Qed.

(* ===== 多步步长收缩：|x_{n+k+1} − x_{n+k}| ≤ |η|·(κ^k)·|g(x_n)| ===== *)
Lemma iterate_step_abs_diff_iter : forall (E_A : R) (n k : nat),
  le (abs (minus (iterate dynamics (n + Datatypes.S k) E_A)
                 (iterate dynamics (n + k) E_A)))
     (mult (abs eta) (mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A))))).
Proof.
  intros E_A n k.
  induction k as [| k IH]; simpl.
  - (* k = 0：|x_{n+1} − x_n| ≤ |η|·(1·|g(x_n)|) *)
    rewrite (Nat.add_1_r n). rewrite (Nat.add_0_r n).
    apply (le_id_l _ (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))) _).
    + (* 步长差 == |η|·|g|：iterate_step_abs_diff *)
      exact (iter_abs E_A n).
    + (* |η|·|g| ≤ |η|·(1·|g|)：mult_comm + mult_one 换形 *)
      apply (le_id_r _ (mult (abs eta) (abs (entropy_gradient (iterate dynamics n E_A)))) _).
      * apply (id_cong (fun z => mult (abs eta) z)
                       (id_sym (id_trans (mult_comm one (abs (entropy_gradient (iterate dynamics n E_A))))
                                         (mult_one (abs (entropy_gradient (iterate dynamics n E_A))))))).
      * apply le_refl.
  - (* k = S k'：|x_{n+S(S k')} − x_{n+S k'}| ≤ |η|·|g(x_{n+S k'})| ≤ |η|·(κ^{S k'}·|g(x_n)|) *)
    apply (le_trans _ (mult (abs eta) (abs (entropy_gradient (iterate dynamics (n + Datatypes.S k) E_A)))) _).
    + (* 单步差：iterate_step_abs_diff at (n + S k) *)
      rewrite (Nat.add_succ_r n (Datatypes.S k)).
      apply (le_id_l _ (mult (abs eta) (abs (entropy_gradient (iterate dynamics (n + Datatypes.S k) E_A)))) _).
      * exact (iter_abs E_A (n + Datatypes.S k)).
      * apply le_refl.
    + (* |η|·|g(x_{n+S k'})| ≤ |η|·(κ^{S k'}·|g(x_n)|)：mult_comm 换形 + le_mult_compat_weak + grad_decay_iter *)
      apply (le_id_l _ (mult (abs (entropy_gradient (iterate dynamics (n + Datatypes.S k) E_A))) (abs eta)) _).
      * apply (mult_comm (abs eta) (abs (entropy_gradient (iterate dynamics (n + Datatypes.S k) E_A)))).
      * apply (le_id_r _ (mult (mult (r_pow kappa (Datatypes.S k)) (abs (entropy_gradient (iterate dynamics n E_A)))) (abs eta)) _).
        -- apply (mult_comm (mult (r_pow kappa (Datatypes.S k)) (abs (entropy_gradient (iterate dynamics n E_A)))) (abs eta)).
        -- apply (le_mult_compat_weak (abs (entropy_gradient (iterate dynamics (n + Datatypes.S k) E_A)))
                                      (mult (r_pow kappa (Datatypes.S k)) (abs (entropy_gradient (iterate dynamics n E_A))))
                                      (abs eta) (abs_nonneg eta)).
           apply (grad_decay_iter E_A n (Datatypes.S k)).
Qed.

(* ===== R 层有限和 ===== *)
Fixpoint sum_R (f : nat -> R) (n : nat) : R :=
  match n with
  | 0%nat => zero
  | Datatypes.S m => plus (sum_R f m) (f m)
  end.

(* 和的逐项保序：∀k<n, f k ≤ g k ⟹ Σf ≤ Σg *)
Lemma sum_R_le : forall f g n,
  (forall k, (k < n)%nat -> le (f k) (g k)) ->
  le (sum_R f n) (sum_R g n).
Proof.
  intros f g n H.
  induction n as [| m IH]; simpl.
  - apply le_refl.
  - apply (le_trans (plus (sum_R f m) (f m)) (plus (sum_R g m) (f m)) (plus (sum_R g m) (g m))).
    + apply (le_plus_compat (sum_R f m) (sum_R g m) (f m) (f m)).
      * apply IH. intros k Hk. apply (H k). lia.
      * apply le_refl.
    + apply (le_plus_compat (sum_R g m) (sum_R g m) (f m) (g m)).
      * apply le_refl.
      * apply (H m (Nat.lt_succ_diag_r m)).
Qed.

(* 和为零：全部项为零 ⟹ 和为零 *)
Lemma sum_R_zero : forall f n,
  (forall k, (k < n)%nat -> Id (f k) zero) ->
  Id (sum_R f n) zero.
Proof.
  intros f n H.
  induction n as [| m IH]; simpl.
  - apply id_refl.
  - apply (id_trans (id_cong2 plus (IH (fun k Hk => H k (Nat.lt_trans k m (Datatypes.S m) Hk (Nat.lt_succ_diag_r m))))
                               (H m (Nat.lt_succ_diag_r m)))
                  (plus_zero zero)).
Qed.

(* mult (1−x)·y == y + (−x)·y：distrib + mult_one *)
Lemma mult_one_minus_r : forall x y,
  Id (mult (minus one x) y) (plus y (mult (opp x) y)).
Proof.
  intros x y.
  unfold minus.
  apply (id_trans (mult_plus_distr_r one (opp x) y)).
  apply (id_cong2 plus (id_trans (mult_comm one y) (mult_one y)) (id_refl)).
Qed.

(* telescoping：1−A + A−B == 1−B（R 层环代数，用主文件 plus_assoc/plus_comm/plus_opp） *)
Lemma telescoping : forall a b,
  Id (plus (minus one a) (minus a b)) (minus one b).
Proof.
  intros a b.
  unfold minus.
  apply (id_trans (id_sym (plus_assoc one (opp a) (plus a (opp b))))).
  apply (id_cong (fun z => plus one z)
    (id_trans (plus_assoc (opp a) a (opp b))
      (id_trans (id_cong (fun z => plus z (opp b)) (id_trans (plus_comm (opp a) a) (plus_opp a)))
                (id_trans (plus_comm zero (opp b)) (plus_zero (opp b)))))).
Qed.

(* ===== 几何级数闭式：(1−κ)·Σ_{k<m} κ^k == 1−κ^m ===== *)
Lemma geom_sum_closed : forall m,
  Id (mult (minus one kappa) (sum_R (r_pow kappa) m))
     (minus one (r_pow kappa m)).
Proof.
  intros m.
  induction m as [| m IH]; simpl.
  - (* m = 0：左边 (1−κ)·0 == 0，右边 1−1 == 0 *)
    apply (id_trans (mult_zero (minus one kappa)) (id_sym (plus_opp one))).
  - (* m = S m'：distrib 拆分 + IH + mult_one_minus_r + opp_mult_r + telescoping *)
    apply (id_trans (distrib (minus one kappa) (sum_R (r_pow kappa) m) (r_pow kappa m))).
    apply (id_trans (id_cong2 plus IH (id_refl))).
    apply (id_trans (id_cong2 plus (id_refl) (mult_one_minus_r kappa (r_pow kappa m)))).
    apply (id_trans (id_cong2 plus (id_refl)
                                  (id_cong (fun z => plus (r_pow kappa m) z)
                                           (opp_mult_r kappa (r_pow kappa m))))).
    apply (telescoping (r_pow kappa m) (mult kappa (r_pow kappa m))).
Qed.

(* 0 < 1−κ（from κ < 1）：lt_plus_compat_lt_le + plus_opp 构造 *)
Lemma one_minus_kappa_pos : lt zero (minus one kappa).
Proof.
  unfold minus.
  apply (lt_id_l zero (plus kappa (opp kappa)) (plus one (opp kappa))
               (id_sym (plus_opp kappa))
               (lt_plus_compat_lt_le kappa one (opp kappa) (opp kappa) kappa_lt_one (le_refl (opp kappa)))).
Qed.

(* 1−κ^m ≤ 1（from κ^m ≥ 0）：le_plus_nonneg_r + minus_plus_cancel *)
Lemma one_minus_pow_le_one : forall m, le (minus one (r_pow kappa m)) one.
Proof.
  intro m.
  apply (le_id_r _ (plus (minus one (r_pow kappa m)) (r_pow kappa m)) _).
  - apply (id_trans (plus_comm (minus one (r_pow kappa m)) (r_pow kappa m))
                    (minus_plus_cancel (r_pow kappa m) one)).
  - apply (le_plus_nonneg_r (minus one (r_pow kappa m)) (r_pow kappa m)).
    apply (r_pow_nonneg kappa m kappa_pos).
Qed.

(* 几何级数界：Σ_{k<m} κ^k ≤ 1/(1−κ)（闭式 + 1−κ^m≤1 + 乘正逆） *)
Lemma geom_sum_bound : forall m,
  le (sum_R (r_pow kappa) m) (inv_pos (minus one kappa) one_minus_kappa_pos).
Proof.
  intro m.
  set (I := inv_pos (minus one kappa) one_minus_kappa_pos).
  apply (le_id_r _ (mult one I) _).
  - (* one·I == I *)
    apply (id_trans (mult_comm one I) (mult_one I)).
  - (* Σ ≤ one·I：Σ == (mult (1−κ) Σ)·I ≤ one·I *)
    apply (le_id_l _ (mult (mult (minus one kappa) (sum_R (r_pow kappa) m)) I) _).
    + (* Σ == mult (mult (1−κ) Σ) I *)
      apply (id_trans (id_sym (mult_one (sum_R (r_pow kappa) m)))).
      apply (id_trans (id_cong (fun z => mult (sum_R (r_pow kappa) m) z)
                               (id_sym (inv_pos_correct (minus one kappa) one_minus_kappa_pos)))).
      apply (id_trans (mult_assoc (sum_R (r_pow kappa) m) (minus one kappa) I)).
      apply (id_cong (fun z => mult z I) (mult_comm (sum_R (r_pow kappa) m) (minus one kappa))).
    + (* le (mult (mult (1−κ) Σ) I) (mult one I)：le_mult_compat_r *)
      apply (le_mult_compat_weak (mult (minus one kappa) (sum_R (r_pow kappa) m)) one I).
      * (* 0 ≤ I：inv_pos_pos + lt_le_iff *)
        apply (lt_le_iff _ _ (inl (inv_pos_pos (minus one kappa) one_minus_kappa_pos))).
      * (* (1−κ)·Σ ≤ 1：geom_sum_closed + one_minus_pow_le_one *)
        apply (le_id_l _ (minus one (r_pow kappa m)) _).
        -- apply (geom_sum_closed m).
        -- apply (one_minus_pow_le_one m).
Qed.

(* ===== Step 4：柯西论证收尾 ===== *)

(* metric 三角迭代到和：metric (x_{n+m}) (x_n) ≤ Σ_{k<m} metric (x_{n+k+1}) (x_{n+k}) *)
Lemma metric_tail_le_sum : forall (E_A : R) (n m : nat),
  le (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))
     (sum_R (fun k => metric (iterate dynamics (n + Datatypes.S k) E_A)
                              (iterate dynamics (n + k) E_A)) m).
Proof.
  intros E_A n m.
  induction m as [| m IH]; simpl.
  - (* m = 0：metric (x_n) (x_n) ≤ 0：metric_refl_zero *)
    rewrite (Nat.add_0_r n).
    apply (le_id_l _ zero _ (metric_refl_zero (iterate dynamics n E_A)) (le_refl zero)).
  - (* m = S m'：metric 三角 + IH *)
    rewrite (Nat.add_succ_r n m).
    apply (le_trans _ (plus (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))
                            (metric (iterate dynamics (Datatypes.S (n + m)) E_A)
                                    (iterate dynamics (n + m) E_A))) _).
    + (* metric_triangle + plus_comm 换形（步长+尾部 == 尾部+步长） *)
      apply (le_id_r _ (plus (metric (iterate dynamics (Datatypes.S (n + m)) E_A)
                                     (iterate dynamics (n + m) E_A))
                             (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))) _).
      * apply (plus_comm (metric (iterate dynamics (Datatypes.S (n + m)) E_A)
                                 (iterate dynamics (n + m) E_A))
                         (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))).
      * apply (metric_triangle (iterate dynamics (Datatypes.S (n + m)) E_A)
                               (iterate dynamics (n + m) E_A)
                               (iterate dynamics n E_A)).
    + apply (le_plus_compat (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))
                            (sum_R (fun k => metric (iterate dynamics (n + Datatypes.S k) E_A)
                                                   (iterate dynamics (n + k) E_A)) m)
                            (metric (iterate dynamics (Datatypes.S (n + m)) E_A)
                                    (iterate dynamics (n + m) E_A))
                            (metric (iterate dynamics (Datatypes.S (n + m)) E_A)
                                    (iterate dynamics (n + m) E_A))).
      * exact IH.
      * apply le_refl.
Qed.

(* sum_R 常数提取：Σ (a·f k) == a·(Σ f) *)
Lemma sum_R_scal_l : forall a f n,
  Id (sum_R (fun k => mult a (f k)) n) (mult a (sum_R f n)).
Proof.
  intros a f n.
  induction n as [| m IH]; simpl.
  - apply (id_sym (mult_zero a)).
  - apply (id_trans (id_cong2 plus IH (id_refl)) (id_sym (distrib a (sum_R f m) (f m)))).
Qed.

(* sum_R 右侧提取：Σ (f k·b) == (Σ f)·b *)
Lemma sum_R_mult_r : forall f b n,
  Id (sum_R (fun k => mult (f k) b) n) (mult (sum_R f n) b).
Proof.
  intros f b n.
  induction n as [| m IH]; simpl.
  - apply (id_sym (id_trans (mult_comm zero b) (mult_zero b))).
  - apply (id_trans (id_cong2 plus IH (id_refl)) (id_sym (mult_plus_distr_r (sum_R f m) (f m) b))).
Qed.

(* 尾部收缩：metric (x_{n+m}) (x_n) ≤ |η|·|g(x_n)|·S（S := 1/(1−κ)） *)
Lemma iterate_metric_tail_bound : forall (E_A : R) (n m : nat),
  le (metric (iterate dynamics (n + m) E_A) (iterate dynamics n E_A))
     (mult (abs eta)
           (mult (abs (entropy_gradient (iterate dynamics n E_A)))
                 (inv_pos (minus one kappa) one_minus_kappa_pos))).
Proof.
  intros E_A n m.
  apply (le_trans _ (sum_R (fun k => metric (iterate dynamics (n + Datatypes.S k) E_A)
                                           (iterate dynamics (n + k) E_A)) m) _).
  - apply (metric_tail_le_sum E_A n m).
  - (* Σ 步长 ≤ Σ |η|κ^k|g| ≤ |η||g|·S *)
    apply (le_trans _ (sum_R (fun k => mult (abs eta)
                                           (mult (r_pow kappa k)
                                                 (abs (entropy_gradient (iterate dynamics n E_A))))) m) _).
    + (* 逐项：metric 步长 == |步长| ≤ |η|κ^k|g|（metric_abs + iterate_step_abs_diff_iter） *)
      apply (sum_R_le (fun k => metric (iterate dynamics (n + Datatypes.S k) E_A)
                                       (iterate dynamics (n + k) E_A))
                      (fun k => mult (abs eta)
                                    (mult (r_pow kappa k)
                                          (abs (entropy_gradient (iterate dynamics n E_A))))) m).
      intros k Hk.
      apply (le_id_l _ (abs (minus (iterate dynamics (n + Datatypes.S k) E_A)
                                   (iterate dynamics (n + k) E_A))) _).
      * apply (metric_abs (iterate dynamics (n + Datatypes.S k) E_A)
                          (iterate dynamics (n + k) E_A)).
      * apply (iterate_step_abs_diff_iter E_A n k).
    + (* Σ |η|κ^k|g| ≤ |η||g|·S：sum 提取公共因子 *)
      apply (le_id_l _ (mult (abs eta)
                             (mult (sum_R (r_pow kappa) m)
                                   (abs (entropy_gradient (iterate dynamics n E_A))))) _).
      * (* Σ |η|(κ^k·X) == |η|·((Σκ^k)·X)：sum_R_scal_l + sum_R_mult_r *)
        apply (id_trans (sum_R_scal_l (abs eta)
                          (fun k => mult (r_pow kappa k) (abs (entropy_gradient (iterate dynamics n E_A)))) m)
                        (id_cong (fun z => mult (abs eta) z)
                                 (sum_R_mult_r (r_pow kappa) (abs (entropy_gradient (iterate dynamics n E_A))) m))).
      * (* |η|·((Σκ^k)·X) ≤ |η|·(I·X)：le_mult_compat_r（公共因子左）*)
        apply (le_mult_compat_r (abs eta)
                                (mult (sum_R (r_pow kappa) m) (abs (entropy_gradient (iterate dynamics n E_A))))
                                (mult (abs (entropy_gradient (iterate dynamics n E_A)))
                                      (inv_pos (minus one kappa) one_minus_kappa_pos))).
        -- apply (abs_nonneg eta).
        -- (* (Σκ^k)·X ≤ X·I：le_mult_compat_weak + mult_comm 换形 *)
           apply (le_id_r _ (mult (inv_pos (minus one kappa) one_minus_kappa_pos)
                                  (abs (entropy_gradient (iterate dynamics n E_A)))) _).
           ++ apply (mult_comm (inv_pos (minus one kappa) one_minus_kappa_pos)
                               (abs (entropy_gradient (iterate dynamics n E_A)))).
           ++ apply (le_mult_compat_weak (sum_R (r_pow kappa) m)
                                         (inv_pos (minus one kappa) one_minus_kappa_pos)
                                         (abs (entropy_gradient (iterate dynamics n E_A)))).
              ** apply (abs_nonneg (entropy_gradient (iterate dynamics n E_A))).
              ** apply (geom_sum_bound m).
Qed.

(* ===== Step 4 收尾：metric-柯西 ⟹ cauchy_complete ⟹ lim 存在 ===== *)

(* 非零步长（诚实接口假设：η = 0 时动力学平凡，收敛论证需要 |η| > 0） *)
Variable eta_abs_pos : lt zero (abs eta).

(* 1/(1−κ) 与 a := |η|·|g(x_0)|·S（Section 级 Let） *)
Let S := inv_pos (minus one kappa) one_minus_kappa_pos.

(* 幂指数递减（迭代 r_pow_dec）：m ≤ n ⟹ κ^n ≤ κ^m *)
Lemma r_pow_dec_iter : forall m n, (m <= n)%nat -> le (r_pow kappa n) (r_pow kappa m).
Proof.
  intros m n Hmn.
  revert m Hmn.
  induction n as [| n IH]; intros m Hmn.
  - (* n = 0：m ≤ 0 ⟹ m = 0 *)
    assert (Hm0 : m = 0%nat) by lia. subst m. apply le_refl.
  - (* n = S n'：Nat.leb 判定 *)
    destruct (Nat.leb m n) eqn:Emn.
    + (* m ≤ n：κ^{S n} ≤ κ^n ≤ κ^m *)
      apply (le_trans _ (r_pow kappa n) _); [apply (r_pow_dec kappa n kappa_pos kappa_lt_one) | apply (IH m (proj1 (Nat.leb_le m n) Emn))].
    + (* ¬m ≤ n：m = S n（m ≤ S n 前提） *)
      apply Nat.leb_gt in Emn.
      assert (Hm : m = Datatypes.S n) by lia. subst m. apply le_refl.
Qed.

(* 乘法中项交换：(a·b)·c == (a·c)·b *)
Lemma mult_swap_mid : forall a b c, Id (mult (mult a b) c) (mult (mult a c) b).
Proof.
  intros a b c.
  apply (id_trans (id_sym (mult_assoc a b c))).
  apply (id_trans (id_cong (fun z => mult a z) (mult_comm b c))).
  apply (mult_assoc a c b).
Qed.

(* 外项交换：(a·b)·c·d == (a·d)·c·b（两次 mult_swap_mid 组合） *)
Lemma mult_swap_outer : forall a b c d,
  Id (mult (mult (mult a b) c) d) (mult (mult (mult a c) d) b).
Proof.
  intros a b c d.
  apply (id_trans (id_cong (fun z => mult z d) (mult_swap_mid a b c))
                  (mult_swap_mid (mult a c) b d)).
Qed.

(* 梯度界辅助：|η||g(x_n)|·S ≤ (|η||g0|·S)·κ^n（grad_decay_iter + 保序 + 重排） *)
Lemma grad_bound_aux : forall E_A n,
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  le (mult (abs eta) (mult (abs (entropy_gradient (iterate dynamics n E_A))) S))
     (mult (mult (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)
           (r_pow kappa n)).
Proof.
  intros E_A n Hg0pos.
  apply (le_id_r _ (mult (abs eta) (mult (mult (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)) _).
  - (* |η|·((κ^n·g0)·S) == (|η|·g0·S)·κ^n：重排 *)
    apply (id_trans (mult_assoc (abs eta) (mult (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)).
    apply (id_trans (id_cong (fun z => mult z S)
                             (mult_assoc (abs eta) (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A)))))).
    apply (mult_swap_outer (abs eta) (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A))) S).
  - (* |η|·(gn·S) ≤ |η|·((κ^n·g0)·S)：le_mult_compat_r + grad_decay_iter *)
    apply (le_mult_compat_r (abs eta)
                            (mult (abs (entropy_gradient (iterate dynamics n E_A))) S)
                            (mult (mult (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)).
    + apply (abs_nonneg eta).
    + apply (le_mult_compat_weak (abs (entropy_gradient (iterate dynamics n E_A)))
                                 (mult (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A))))
                                 S).
      * apply (lt_le_iff _ _ (inl (inv_pos_pos (minus one kappa) one_minus_kappa_pos))).
      * apply (grad_decay_iter E_A 0 n).
Qed.

(* metric (x_m) (x_n) ≤ a·κ^{min m n}：metric 对称 + 尾部收缩 + grad_bound_aux *)
Lemma iterate_metric_min_bound : forall E_A m n,
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  le (metric (iterate dynamics m E_A) (iterate dynamics n E_A))
     (mult (mult (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)
           (r_pow kappa (Nat.min m n))).
Proof.
  intros E_A m n Hg0pos.
  destruct (Nat.leb m n) eqn:Emn.
  - (* m ≤ n：metric 对称后以 m 为底 *)
    apply Nat.leb_le in Emn.
    apply (le_id_l _ (metric (iterate dynamics n E_A) (iterate dynamics m E_A)) _).
    { exact (metric_sym (iterate dynamics m E_A) (iterate dynamics n E_A)). }
    rewrite (Nat.min_l m n Emn).
    rewrite <- (Nat.sub_add m n Emn).
    rewrite (Nat.add_comm (n - m) m).
    apply (le_trans _ (mult (abs eta) (mult (abs (entropy_gradient (iterate dynamics m E_A))) S)) _).
    + apply (iterate_metric_tail_bound E_A m (n - m)).
    + apply (grad_bound_aux E_A m Hg0pos).
  - (* n ≤ m：以 n 为底 *)
    apply Nat.leb_gt in Emn.
    rewrite (Nat.min_r m n (Nat.lt_le_incl n m Emn)).
    rewrite <- (Nat.sub_add n m (Nat.lt_le_incl n m Emn)).
    rewrite (Nat.add_comm (m - n) n).
    apply (le_trans _ (mult (abs eta) (mult (abs (entropy_gradient (iterate dynamics n E_A))) S)) _).
    + apply (iterate_metric_tail_bound E_A n (m - n)).
    + apply (grad_bound_aux E_A n Hg0pos).
Qed.

(* 柯西性：对任意 eps > 0，∃N，m,n ≥ N ⟹ metric (x_m) (x_n) < eps（几何击穿收尾） *)
Lemma iterate_cauchy : forall (E_A : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  forall eps : R, lt zero eps ->
    sigT (fun N : nat => forall m n : nat, (N <= m)%nat -> (N <= n)%nat ->
      lt (metric (iterate dynamics m E_A) (iterate dynamics n E_A)) eps).
Proof.
  intros E_A Hg0pos eps Hep.
  set (a := mult (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S).
  assert (Ha : lt zero a).
  { unfold a.
    apply (mult_positive (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S).
    - apply (mult_positive (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A))) eta_abs_pos Hg0pos).
    - exact (inv_pos_pos (minus one kappa) one_minus_kappa_pos). }
  destruct (r_arch_pow a Ha eps Hep) as [N0 HN0].
  exists N0.
  intros m n Hm Hn.
  apply (le_lt_trans _ (mult a (r_pow kappa (Nat.min m n))) _).
  - (* metric (x_m) (x_n) ≤ a·κ^{min m n} *)
    unfold a.
    apply (iterate_metric_min_bound E_A m n Hg0pos).
  - (* a·κ^{min} ≤ a·κ^{N0} < eps（min ≥ N0 ⟹ κ^{min} ≤ κ^{N0}） *)
    apply (le_lt_trans _ (mult a (r_pow kappa N0)) _).
    + apply (le_mult_compat_r a (r_pow kappa (Nat.min m n)) (r_pow kappa N0)).
      * apply (lt_le_iff _ _ (inl Ha)).
      * apply (r_pow_dec_iter N0 (Nat.min m n)). lia.
    + exact HN0.
Qed.

Variable log_lt_mono_cc : forall a b : R, lt zero a -> lt zero b -> lt a b -> lt (log a) (log b).

(* nat 到 R 的嵌入（T4.2 局部；GRPO Section 的 of_nat 在文件更后处，避免前向引用） *)
Fixpoint nat_to_R (n : nat) : R :=
  match n with
  | O => zero
  | Datatypes.S n' => plus one (nat_to_R n')
  end.

(* ============ 引理 1：log 对幂的展开 ============ *)
(* log (x^n) == of_nat n · log x（log_mult 归纳） *)
Lemma log_pow_cc : forall (x : R) (n : nat), lt zero x ->
  Id (log (r_pow x n)) (mult (nat_to_R n) (log x)).
Proof.
  intros x n Hx.
  induction n as [| n IH].
  - simpl.
    apply (id_trans log_one
                   (id_sym (id_trans (mult_comm zero (log x)) (mult_zero (log x))))).
  - simpl r_pow.
    apply (id_trans (log_mult x (r_pow x n) Hx (r_pow_pos x n Hx))).
    apply (id_trans (id_cong2 plus (id_refl) IH)).
    assert (Hr : Id (mult (plus one (nat_to_R n)) (log x)) (plus (log x) (mult (nat_to_R n) (log x)))).
    {
      apply (id_trans (mult_comm (plus one (nat_to_R n)) (log x))).
      apply (id_trans (distrib (log x) one (nat_to_R n))).
      apply (id_trans (id_cong (fun y => plus y (mult (log x) (nat_to_R n))) (mult_one (log x)))).
      apply (id_cong (fun y => plus (log x) y) (mult_comm (log x) (nat_to_R n))).
    }
    apply (id_sym Hr).
Qed.

(* ============ 引理 2：r_arch_pow 的 log 闭式击穿升级 ============ *)
(* 存在性 N 升级：∃N，log(a·κ^N) ≤ log eps 且 a·κ^N < eps
   （第一个分量即显式预算函数 N(eps) 的闭式特征：
    数学上 N ≥ log(a/eps)/log(1/κ) 的 log 形式） *)
Lemma r_arch_pow_log_budget : forall a : R, lt zero a -> forall eps : R, lt zero eps ->
  sigT (fun N : nat => And (le (log (mult a (r_pow kappa N))) (log eps))
                           (lt (mult a (r_pow kappa N)) eps)).
Proof.
  intros a Ha eps Hep.
  destruct (r_arch_pow a Ha eps Hep) as [N0 HN0].
  exists N0.
  split.
  - apply (lt_le_iff _ _ (inl (log_lt_mono_cc (mult a (r_pow kappa N0)) eps
                                              (mult_positive a (r_pow kappa N0) Ha (r_pow_pos kappa N0 kappa_pos))
                                              Hep
                                              HN0))).
  - exact HN0.
Qed.

(* ============ 主定理：显式可计算收敛率 ============ *)
(* 升级 iterate_cauchy：N 满足闭式预算条件 log(a·κ^N) ≤ log eps
   （a := |η|·|g(E_A)|·S 的 log 击穿），并仍是柯西点 *)
Theorem iterate_cauchy_explicit_N : forall (E_A : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  forall eps : R, lt zero eps ->
    sigT (fun N : nat =>
      And (le (log (mult (mult (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S)
                          (r_pow kappa N)))
              (log eps))
          (forall m n : nat, (N <= m)%nat -> (N <= n)%nat ->
            lt (metric (iterate dynamics m E_A) (iterate dynamics n E_A)) eps)).
Proof.
  intros E_A Hg0pos eps Hep.
  set (a := mult (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S).
  assert (Ha : lt zero a).
  { unfold a.
    apply (mult_positive (mult (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A)))) S).
    - apply (mult_positive (abs eta) (abs (entropy_gradient (iterate dynamics 0 E_A))) eta_abs_pos Hg0pos).
    - exact (inv_pos_pos (minus one kappa) one_minus_kappa_pos). }
  destruct (r_arch_pow_log_budget a Ha eps Hep) as [N [HNlog HNgeo]].
  exists N.
  split.
  - unfold a in HNlog. exact HNlog.
  - intros m n Hm Hn.
    apply (le_lt_trans _ (mult a (r_pow kappa (Nat.min m n))) _).
    + unfold a.
      apply (iterate_metric_min_bound E_A m n Hg0pos).
    + apply (le_lt_trans _ (mult a (r_pow kappa N)) _).
      * apply (le_mult_compat_r a (r_pow kappa (Nat.min m n)) (r_pow kappa N)).
        -- apply (lt_le_iff _ _ (inl Ha)).
        -- apply (r_pow_dec_iter N (Nat.min m n)). lia.
      * exact HNgeo.
Qed.

(* NatLe（Id 包裹）→ nat ≤：bool 判定后 Nat.leb_le 桥 *)
Lemma natle_to_le : forall n m, NatLe n m -> (n <= m)%nat.
Proof.
  intros n m H.
  unfold NatLe in H.
  destruct (Nat.leb n m) eqn:E.
  - apply (proj1 (Nat.leb_le n m)). exact E.
  - inversion H.
Qed.

(* lim 存在：metric-柯西 ⟹ cauchy_complete ⟹ lim *)
Lemma iterate_lim_exists : forall (E_A : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  ExistsT (fun E_star : R => lim (fun n => iterate dynamics n E_A) E_star).
Proof.
  intros E_A Hg0pos.
  apply (cauchy_complete (fun n => iterate dynamics n E_A)).
  intros eps Hep.
  destruct (iterate_cauchy E_A Hg0pos eps Hep) as [N HN].
  exists N.
  intros m n Hm Hn.
  exact (HN m n (natle_to_le N m Hm) (natle_to_le N n Hn)).
Qed.

(* ===== P2.5 可推部分：梯度绝对值单调衰减（strict_concavity 组装） =====
   0 < η、0 < g(x_n)、0 < g(x_{n+1}) ⟹ |g(x_{n+1})| ≤ |g(x_n)|。
   链：x_n < x_{n+1}（η·g(x_n) > 0）→ g(x_{n+1}) < g(x_n)（strict_concavity）
        → |g(x_{n+1})| ≤ |g(x_n)|（gradient_abs_mono）。 *)

(* gradient_abs_mono 闭包别名（只依赖 entropy_gradient） *)
Let gmono := (@gradient_abs_mono RI entropy_gradient).

Theorem iterate_grad_abs_mono : forall (E_A : R) (n : nat),
  lt zero eta ->
  lt zero (entropy_gradient (iterate dynamics n E_A)) ->
  lt zero (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)) ->
  le (abs (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)))
     (abs (entropy_gradient (iterate dynamics n E_A))).
Proof.
  intros E_A n Heta Hgn Hgn1.
  (* x_{n+1} == x_n + η·g(x_n)（dynamics_gradient_step at iterate n） *)
  assert (Hxnext : Id (iterate dynamics (Datatypes.S n) E_A)
                      (plus (iterate dynamics n E_A) (mult eta (entropy_gradient (iterate dynamics n E_A))))).
  { simpl. exact (dynamics_gradient_step (iterate dynamics n E_A)). }
  (* 0 < η·g(x_n)（mult_positive） *)
  assert (Heta_g : lt zero (mult eta (entropy_gradient (iterate dynamics n E_A)))).
  { apply (mult_positive eta (entropy_gradient (iterate dynamics n E_A)) Heta Hgn). }
  (* x_n < x_n + η·g(x_n)（lt_plus_compat_lt_le + plus_zero） *)
  assert (Hlt0 : lt (iterate dynamics n E_A)
                   (plus (iterate dynamics n E_A) (mult eta (entropy_gradient (iterate dynamics n E_A))))).
  { apply (lt_id_l (iterate dynamics n E_A)
                   (plus (iterate dynamics n E_A) zero)
                   (plus (iterate dynamics n E_A) (mult eta (entropy_gradient (iterate dynamics n E_A))))
                   (id_sym (plus_zero (iterate dynamics n E_A)))
                   (lt_plus_compat_le_lt (iterate dynamics n E_A) (iterate dynamics n E_A) zero
                                         (mult eta (entropy_gradient (iterate dynamics n E_A)))
                                         (le_refl (iterate dynamics n E_A)) Heta_g)). }
  (* x_n < x_{n+1} *)
  assert (Hlt : lt (iterate dynamics n E_A) (iterate dynamics (Datatypes.S n) E_A)).
  { apply (lt_id_r (iterate dynamics n E_A)
                   (plus (iterate dynamics n E_A) (mult eta (entropy_gradient (iterate dynamics n E_A))))
                   (iterate dynamics (Datatypes.S n) E_A)
                   (id_sym Hxnext) Hlt0). }
  (* g(x_{n+1}) < g(x_n)：strict_concavity *)
  assert (Hgdec : lt (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))
                     (entropy_gradient (iterate dynamics n E_A))).
  { apply (strict_concavity (iterate dynamics n E_A) (iterate dynamics (Datatypes.S n) E_A)).
    exact Hlt. }
  (* |g(x_{n+1})| ≤ |g(x_n)|：gradient_abs_mono *)
  apply (gmono (iterate dynamics n E_A) (iterate dynamics (Datatypes.S n) E_A)).
  - exact Hlt.
  - exact Hgn1.
  - exact Hgdec.
Qed.

(* ===== P1-2 收尾：lim 夹逼核心 + dynamics_converges 组装（备份 80 后） ===== *)

(* 新增诚实接口字段（E143-199 纪律：标准性质先例） *)
(* (5) lim 的 eps-N 语义：收敛序列在度量下逼近极限（构造性收敛标准性质，
       Real 实例 real_lim 即 eps-N 定义；抽象 R 层接口仅 lim_unique 缺此） *)
Variable lim_metric_approx : forall (u : nat -> R) (l : R),
  lim u l -> forall eps : R, lt zero eps ->
    sigT (fun N : nat => forall n : nat, NatLe N n -> lt (metric (u n) l) eps).

(* (6) 任意小非负 ⟹ ≤ 0：∀eps>0, x < eps ⟹ x ≤ 0（构造性有序域标准性质，
       与 r_arch_pow 同族；lim 夹逼收尾需要） *)
Variable le_all_eps_zero : forall x : R,
  (forall eps : R, lt zero eps -> lt x eps) -> le x zero.

(* 辅助：abs (minus x zero) == abs x *)
Lemma abs_minus_zero : forall a : R, Id (abs (minus a zero)) (abs a).
Proof.
  intro a.
  assert (Hm : Id (minus a zero) a).
  { change (Id (plus a (opp zero)) a).
    assert (Hopp0 : Id (opp zero) zero).
    { apply (id_trans (id_sym (id_trans (plus_comm zero (opp zero))
                                        (plus_zero (opp zero))))
                      (plus_opp zero)). }
    rewrite Hopp0.
    apply plus_zero. }
  apply (id_cong abs Hm).
Qed.

(* 辅助：NatLe 构造（n ≤ m ⟹ NatLe n m） *)
Lemma natle_of_le : forall n m, (n <= m)%nat -> NatLe n m.
Proof.
  intros n m H.
  unfold NatLe.
  destruct (Nat.leb n m) eqn:E.
  - reflexivity.
  - exfalso.
    apply (proj1 (Nat.leb_gt n m)) in E.
    lia.
Qed.

(* 夹逼核心：lim x_n E_star（iterate 序列）+ 初始梯度非零 ⟹ g(E_star) == 0。
   论证：对任意 eps > 0，取 n ≥ max N1 N2——
   |g(E_star) − g(x_n)| ≤ L·metric (x_n) E_star < eps2（lim_metric_approx + gradient_lipschitz）
   |g(x_n)| ≤ κ^n·|g0| < eps2（grad_decay_iter + r_arch_pow）
   三角 + eps/2 分割 ⟹ metric (g E_star) zero < eps ⟹ le_all_eps_zero ⟹ = 0。 *)
Lemma grad_squeeze_zero : forall (E_A E_star : R),
  lim (fun n => iterate dynamics n E_A) E_star ->
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  Id (entropy_gradient E_star) zero.
Proof.
  intros E_A E_star Hlim Hg0pos.
  apply metric_zero.
  apply le_antisym.
  - apply le_all_eps_zero.
    intros eps Heps.
    pose (eps2 := mult (inv_pos (plus one one) two_pos) eps).
    assert (Heps2 : lt zero eps2) by (unfold eps2; apply half_pos; exact Heps).
    pose (eps1 := mult (inv_pos L L_pos) eps2).
    assert (Heps1 : lt zero eps1).
    { unfold eps1.
      apply (mult_positive (inv_pos L L_pos) eps2).
      - apply (@inv_pos_pos RI L L_pos).
      - exact Heps2. }
    destruct (lim_metric_approx (fun n => iterate dynamics n E_A) E_star Hlim eps1 Heps1) as [N1 HN1].
  destruct (r_arch_pow (abs (entropy_gradient (iterate dynamics 0 E_A))) Hg0pos eps2 Heps2) as [N2 HN2].
    pose (n := Nat.max N1 N2).
    assert (Hn1 : NatLe N1 n) by (unfold n; apply natle_of_le; apply Nat.le_max_l).
    assert (Hn2 : NatLe N2 n) by (unfold n; apply natle_of_le; apply Nat.le_max_r).
    assert (Ht : le (metric (entropy_gradient E_star) zero)
                   (plus (metric (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A)))
                         (metric (entropy_gradient (iterate dynamics n E_A)) zero))).
    { exact (metric_triangle (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A)) zero). }
    assert (Hhalf1 : lt (metric (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A))) eps2).
    { apply (le_lt_trans _ (mult L (metric (iterate dynamics n E_A) E_star)) _).
      - apply (le_id_l _ (abs (minus (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A)))) _).
        + apply (metric_abs (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A))).
        + apply (le_id_r _ (mult L (abs (minus E_star (iterate dynamics n E_A)))) _).
          * apply (id_cong (fun z => mult L z)
                   (id_trans (abs_minus_sym E_star (iterate dynamics n E_A))
                             (id_sym (metric_abs (iterate dynamics n E_A) E_star)))).
          * exact (gradient_lipschitz E_star (iterate dynamics n E_A)).
      - apply (lt_id_r _ (mult L eps1) _).
        + unfold eps1.
          apply (id_trans (mult_assoc L (inv_pos L L_pos) eps2)
                          (id_trans (id_cong (fun z => mult z eps2) (inv_pos_correct L L_pos))
                                    (id_trans (mult_comm one eps2) (mult_one eps2)))).
        + apply (lt_id_l _ (mult (metric (iterate dynamics n E_A) E_star) L) _).
          * apply (mult_comm L (metric (iterate dynamics n E_A) E_star)).
          * apply (lt_id_r _ (mult eps1 L) _).
            -- apply (id_sym (mult_comm L eps1)).
            -- apply (lt_mult_compat (metric (iterate dynamics n E_A) E_star) eps1 L L_pos).
               exact (HN1 n Hn1). }
    assert (Hhalf2 : lt (metric (entropy_gradient (iterate dynamics n E_A)) zero) eps2).
    { apply (le_lt_trans _ (mult (r_pow kappa n) (abs (entropy_gradient (iterate dynamics 0 E_A)))) _).
      - apply (le_id_l _ (abs (minus (entropy_gradient (iterate dynamics n E_A)) zero)) _).
        + apply (metric_abs (entropy_gradient (iterate dynamics n E_A)) zero).
        + apply (le_id_l _ (abs (entropy_gradient (iterate dynamics n E_A))) _).
          * apply (abs_minus_zero (entropy_gradient (iterate dynamics n E_A))).
          * exact (grad_decay_iter E_A 0 n).
      - apply (le_lt_trans _ (mult (r_pow kappa N2) (abs (entropy_gradient (iterate dynamics 0 E_A)))) _).
        + apply (le_mult_compat_weak (r_pow kappa n) (r_pow kappa N2)
                                     (abs (entropy_gradient (iterate dynamics 0 E_A)))
                                     (abs_nonneg (entropy_gradient (iterate dynamics 0 E_A)))).
          apply (r_pow_dec_iter N2 n). exact (natle_to_le N2 n Hn2).
        + apply (lt_id_l _ (mult (abs (entropy_gradient (iterate dynamics 0 E_A))) (r_pow kappa N2)) _).
          * apply (id_sym (mult_comm (abs (entropy_gradient (iterate dynamics 0 E_A))) (r_pow kappa N2))).
          * exact (HN2). }
    apply (lt_id_r _ (plus eps2 eps2) _).
    { apply (half_twice eps). }
    { apply (le_lt_trans _ (plus (metric (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A)))
                                 (metric (entropy_gradient (iterate dynamics n E_A)) zero)) _).
      { exact Ht. }
      { apply (lt_plus_compat
                 (metric (entropy_gradient E_star) (entropy_gradient (iterate dynamics n E_A)))
                 eps2
                 (metric (entropy_gradient (iterate dynamics n E_A)) zero)
                 eps2
                 Hhalf1 Hhalf2). } }
  - apply (@metric_pos RI).
Qed.

(* 组装：dynamics_converges（以 ConvergenceCauchy 条件集替换 ConvergenceTheorem 的 Variable）。
   前提：初始梯度非零（iterate_lim_exists 需要）+ 收敛步长条件（原 Variable 前提保留）。
   链：iterate_lim_exists 给 lim 存在 → grad_squeeze_zero 夹逼 g(E_star) == 0。
   ⚠ 2026-09-02 T4.4 判据：`lt zero (minus (plus one one) (mult L eta))`（Hstep）已移除——
   证明体零引用（仅用 Hg0pos），收敛前提链 iterate_lim_exists / grad_squeeze_zero 均不含
   该形态前提，下游零引用（grep dynamics_converges 仅注释与定义处）。 *)
Theorem dynamics_converges : forall (E_A : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  ExistsT (fun E_star : R =>
    And (lim (fun n => iterate dynamics n E_A) E_star)
        (Id (entropy_gradient E_star) zero)).
Proof.
  intros E_A Hg0pos.
  destruct (iterate_lim_exists E_A Hg0pos) as [E_star Hlim].
  exists E_star.
  split.
  - exact Hlim.
  - exact (grad_squeeze_zero E_A E_star Hlim Hg0pos).
Qed.

(* ============================================================
   论文4 收敛缺口补强（κ 定理化方向，2026-09-01 合入）：
   从 μ-强凹 + Lipschitz + 步长约束推正分支梯度收缩
   核心：gradient_step_contraction（单步收缩）、
         gradient_step_abs_contraction（绝对值收缩 κ := 1−ημ）、
         gradient_iterate_abs_decay（单步迭代收缩）、
         grad_decay_positive_iter（κ 幂衰减）。
   诚实接口新增：μ-强凹（standard 优化假设，非经典公理）。
   纪律：纯构造性 / Set 层 / 零 admit / 零经典。
   ============================================================ *)
(* 新增：μ-强凹（x < y ⟹ μ(y−x) ≤ g(x) − g(y)，凹性模量化） *)
Variable mu : R.
Variable mu_pos : lt zero mu.
Variable strong_concavity : forall x y : R, lt x y ->
  le (mult mu (minus y x)) (minus (entropy_gradient x) (entropy_gradient y)).
(* ===== K0 动力学单步展开：dynamics x = x + η·g(x) ===== *)
Lemma dynamics_step_unfold : forall x : R,
  Id (dynamics x) (plus x (mult eta (entropy_gradient x))).
Proof.
  intros x. exact (dynamics_gradient_step x).
Qed.

(* 辅助：minus a b + b == a（减法可逆） *)
Lemma minus_plus_cancel_gap : forall a b : R,
  Id (plus (minus a b) b) a.
Proof.
  intros a b. unfold minus.
  apply (id_trans (id_sym (plus_assoc a (opp b) b))).
  apply (id_trans (id_cong (fun z => plus a z) (plus_comm (opp b) b))).
  apply (id_trans (id_cong (fun z => plus a z) (plus_opp b))).
  apply (plus_zero a).
Qed.

(* ===== K1a 正分支单步收缩（非绝对值版）：
   g(x) > 0 且 ημ < 1 ⟹ g(dynamics x) ≤ (1−ημ)·g(x)
   链：x < dyn（η·g>0）→ 强凹给 μ(dyn−x) ≤ g(x)−g(dyn)
        → (ημ)g ≤ g(x)−g(dyn) → 移项得 g(dyn) ≤ g(x)−(ημ)g == (1−ημ)g *)
Lemma gradient_step_contraction : forall x : R,
  lt zero eta ->
  lt (mult eta mu) one ->
  lt zero (entropy_gradient x) ->
  le (entropy_gradient (dynamics x))
     (mult (minus one (mult eta mu)) (entropy_gradient x)).
Proof.
  intros x Heta Heta_mu Hgx.
  (* x < dynamics x：η·g(x) > 0 ⟹ x < x + η·g(x) *)
  assert (Heta_g : lt zero (mult eta (entropy_gradient x)))
    by exact (mult_positive eta (entropy_gradient x) Heta Hgx).
  assert (Hlt : lt x (dynamics x)).
  {
    apply (lt_id_l x (plus x zero) (dynamics x) (id_sym (plus_zero x))).
    apply (lt_id_r (plus x zero) (plus x (mult eta (entropy_gradient x))) (dynamics x)
                   (id_sym (dynamics_step_unfold x))).
    apply (lt_plus_compat_le_lt x x zero (mult eta (entropy_gradient x)) (le_refl x) Heta_g).
  }
  (* 强凹：μ(dynamics x − x) ≤ g(x) − g(dynamics x) *)
  pose proof (strong_concavity x (dynamics x) Hlt) as Hsc.
  (* minus (dynamics x) x == η·g(x) *)
  assert (Hdiff : Id (minus (dynamics x) x) (mult eta (entropy_gradient x))).
  {
    unfold minus.
    apply (id_trans (id_cong (fun z => plus z (opp x)) (dynamics_step_unfold x))).
    apply (id_trans (id_sym (plus_assoc x (mult eta (entropy_gradient x)) (opp x)))).
    apply (id_trans (id_cong (fun z => plus x z) (plus_comm (mult eta (entropy_gradient x)) (opp x)))).
    apply (id_trans (plus_assoc x (opp x) (mult eta (entropy_gradient x)))).
    apply (id_trans (id_cong (fun z => plus z (mult eta (entropy_gradient x))) (plus_opp x))).
    apply (id_trans (plus_comm zero (mult eta (entropy_gradient x)))).
    apply (plus_zero (mult eta (entropy_gradient x))).
  }
  (* 代入 Hdiff：μ·(η·g(x)) ≤ g(x) − g(dyn) *)
  assert (Hsc' : le (mult mu (mult eta (entropy_gradient x)))
                    (minus (entropy_gradient x) (entropy_gradient (dynamics x)))).
  { apply (le_id_l (mult mu (mult eta (entropy_gradient x)))
                   (mult mu (minus (dynamics x) x))
                   (minus (entropy_gradient x) (entropy_gradient (dynamics x)))
                   (id_sym (id_cong (fun z => mult mu z) Hdiff)) Hsc). }
  (* 换形：(ημ)·g(x) ≤ g(x) − g(dyn) *)
  assert (Hmm : Id (mult mu (mult eta (entropy_gradient x)))
                   (mult (mult eta mu) (entropy_gradient x))).
  {
    apply (id_trans (id_cong (fun z => mult mu z) (mult_comm eta (entropy_gradient x)))).
    apply (id_trans (mult_assoc mu (entropy_gradient x) eta)).
    apply (id_trans (id_cong (fun z => mult z eta) (mult_comm mu (entropy_gradient x)))).
    apply (id_trans (mult_comm (mult (entropy_gradient x) mu) eta)).
    apply (id_trans (id_cong (fun z => mult eta z) (mult_comm (entropy_gradient x) mu))).
    apply (mult_assoc eta mu (entropy_gradient x)).
  }
  assert (Hsc'' : le (mult (mult eta mu) (entropy_gradient x))
                     (minus (entropy_gradient x) (entropy_gradient (dynamics x)))).
  { apply (le_id_l (mult (mult eta mu) (entropy_gradient x))
                   (mult mu (mult eta (entropy_gradient x)))
                   (minus (entropy_gradient x) (entropy_gradient (dynamics x)))
                   (id_sym Hmm) Hsc'). }
  (* 移项：从 A ≤ B−C 推 C ≤ B−A
     1. 加 C：le (A+C) ((B−C)+C) == B ⟹ le (A+C) B
     2. 加 (opp A)：le ((A+C)+opp A) (B+opp A) ⟹ le C (B−A) *)
  pose (A := mult (mult eta mu) (entropy_gradient x)).
  pose (B := entropy_gradient x).
  pose (C := entropy_gradient (dynamics x)).
  assert (H1 : le (plus A C) B).
  {
    apply (le_id_r (plus A C) (plus (minus B C) C) B).
    - exact (minus_plus_cancel_gap B C).
    - apply (le_plus_compat A (minus B C) C C Hsc'' (le_refl C)).
  }
  assert (H2 : le (plus (plus A C) (opp A)) (plus B (opp A))).
  {
    apply (le_plus_compat (plus A C) B (opp A) (opp A) H1 (le_refl (opp A))).
  }
  (* 左侧化简：(A+C)+opp A == C *)
  assert (H3 : Id (plus (plus A C) (opp A)) C).
  {
    unfold A. unfold C.
    apply (id_trans (id_cong (fun z => plus z (opp (mult (mult eta mu) (entropy_gradient x))))
                             (plus_comm (mult (mult eta mu) (entropy_gradient x))
                                        (entropy_gradient (dynamics x))))).
    apply (id_trans (id_sym (plus_assoc (entropy_gradient (dynamics x))
                                        (mult (mult eta mu) (entropy_gradient x))
                                        (opp (mult (mult eta mu) (entropy_gradient x)))))).
    apply (id_trans (id_cong (fun z => plus (entropy_gradient (dynamics x)) z)
                             (plus_opp (mult (mult eta mu) (entropy_gradient x))))).
    apply (id_trans (plus_zero (entropy_gradient (dynamics x)))). apply id_refl.
  }
  (* 右侧：plus B (opp A) == minus (g x) ((ημ)g) == 目标形态 *)
  assert (H4 : Id (plus B (opp A)) (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x)))).
  { unfold A, B. apply id_refl. }
  (* 组装：le C (minus B ((ημ)g)) *)
  assert (H5 : le C (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x)))).
  {
    apply (le_id_l C (plus (plus A C) (opp A)) (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x))) (id_sym H3)).
    apply (le_id_r (plus (plus A C) (opp A)) (plus B (opp A)) (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x))) H4 H2).
  }
  (* 目标：le (g dyn) (mult (minus one (ημ)) (g x))；需 (1−ημ)·g == g − (ημ)g *)
  (* 目标：le C (mult (minus one (ημ)) g)；H5 : le C (minus g ((ημ)g))
     用 le_id_r 换 RHS：minus g ((ημ)g) == mult (minus one (ημ)) g *)
  assert (H6 : Id (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x)))
                  (mult (minus one (mult eta mu)) (entropy_gradient x))).
  {
    unfold minus.
    apply (id_sym (id_trans (mult_plus_distr_r one (opp (mult eta mu)) (entropy_gradient x))
                            (id_trans (id_cong (fun z => plus z (mult (opp (mult eta mu)) (entropy_gradient x))) (id_trans (mult_comm one (entropy_gradient x)) (mult_one (entropy_gradient x))))
                                      (id_cong (fun z => plus (entropy_gradient x) z) (opp_mult_r (mult eta mu) (entropy_gradient x)))))).
  }
  apply (le_id_r C (minus (entropy_gradient x) (mult (mult eta mu) (entropy_gradient x)))
                 (mult (minus one (mult eta mu)) (entropy_gradient x)) H6 H5).
Qed.

(* ===== 辅助：严格减正：a < b ⟹ 0 < b − a（K3 的 κ 正性需要） ===== *)
Lemma minus_pos : forall a b : R, lt a b -> lt zero (minus b a).
Proof.
  intros a b Hab. unfold minus.
  apply (lt_id_l zero (plus a (opp a)) (plus b (opp a)) (id_sym (plus_opp a))).
  apply (lt_plus_compat_lt_le a b (opp a) (opp a) Hab (le_refl (opp a))).
Qed.
(* ===== K1c 正分支单步绝对值收缩：g(x)>0 且 g(dyn)>0 且 ημ<1
   ⟹ |g(dyn)| ≤ (1−ημ)·|g(x)|
   证明：K1a 给 g(dyn) ≤ (1−ημ)g(x)；双正 ⟹ |g| = g（abs_pos）⟹ 直接换形 *)
Lemma gradient_step_abs_contraction : forall x : R,
  lt zero eta ->
  lt (mult eta mu) one ->
  lt zero (entropy_gradient x) ->
  lt zero (entropy_gradient (dynamics x)) ->
  le (abs (entropy_gradient (dynamics x)))
     (mult (minus one (mult eta mu)) (abs (entropy_gradient x))).
Proof.
  intros x Heta Heta_mu Hgx Hgdyn.
  (* |g(dyn)| == g(dyn)（abs_pos） *)
  assert (Habsd : Id (abs (entropy_gradient (dynamics x))) (entropy_gradient (dynamics x)))
    by exact (abs_pos (entropy_gradient (dynamics x)) Hgdyn).
  (* |g(x)| == g(x)（abs_pos） *)
  assert (Habsx : Id (abs (entropy_gradient x)) (entropy_gradient x))
    by exact (abs_pos (entropy_gradient x) Hgx).
  (* 目标换形：g(dyn) ≤ (1−ημ)·g(x)（K1a） *)
  apply (le_id_l (abs (entropy_gradient (dynamics x)))
                 (entropy_gradient (dynamics x))
                 (mult (minus one (mult eta mu)) (abs (entropy_gradient x)))
                 Habsd).
  apply (le_id_r (entropy_gradient (dynamics x))
                 (mult (minus one (mult eta mu)) (entropy_gradient x))
                 (mult (minus one (mult eta mu)) (abs (entropy_gradient x)))
                 (id_cong (fun z => mult (minus one (mult eta mu)) z) (id_sym Habsx))
                 (gradient_step_contraction x Heta Heta_mu Hgx)).
Qed.

(* ===== K2 正分支单步迭代收缩：任意步正（前提）⟹ |g(x_{n+1})| ≤ κ·|g(x_n)|
   κ := 1−ημ；证明：K1c 实例化 x := iterate dynamics n E_A *)
Theorem gradient_iterate_abs_decay : forall (E_A : R) (n : nat),
  lt zero eta ->
  lt (mult eta mu) one ->
  (forall k : nat, (k <= Datatypes.S n)%nat -> lt zero (entropy_gradient (iterate dynamics k E_A))) ->
  le (abs (entropy_gradient (iterate dynamics (Datatypes.S n) E_A)))
     (mult (minus one (mult eta mu)) (abs (entropy_gradient (iterate dynamics n E_A)))).
Proof.
  intros E_A n Heta Heta_mu Hall.
  (* x := iterate dynamics n E_A；前提 g(x) > 0 和 g(dyn x) > 0 *)
  assert (Hgn : lt zero (entropy_gradient (iterate dynamics n E_A))).
  { apply Hall. lia. }
  assert (Hgn1 : lt zero (entropy_gradient (iterate dynamics (Datatypes.S n) E_A))).
  { apply Hall. lia. }
  (* dynamics (iterate dynamics n E_A) 与 iterate (S n) E_A 定义性相等（iterate 是 Fixpoint） *)
  exact (gradient_step_abs_contraction (iterate dynamics n E_A) Heta Heta_mu Hgn Hgn1).
Qed.

(* ===== K3 正分支 κ 幂衰减：|g(x_{n+k})| ≤ κ^k·|g(x_n)|（归纳，同 grad_decay_iter 结构）
   κ := 1−ημ；前提：全轨道正（j ≤ n+k） *)
Theorem grad_decay_positive_iter : forall (E_A : R) (n k : nat),
  lt zero eta ->
  lt (mult eta mu) one ->
  (forall j : nat, (j <= n + k)%nat -> lt zero (entropy_gradient (iterate dynamics j E_A))) ->
  le (abs (entropy_gradient (iterate dynamics (n + k) E_A)))
     (mult (r_pow (minus one (mult eta mu)) k) (abs (entropy_gradient (iterate dynamics n E_A)))).
Proof.
  intros E_A n k Heta Heta_mu Hall.
  (* κ > 0：1−ημ > 0（由 ημ < 1） *)
  assert (Hkpos : lt zero (minus one (mult eta mu))).
  { apply (minus_pos _ _ Heta_mu). }
  induction k as [| k IH]; simpl.
  - (* k = 0：|g(x_n)| ≤ 1·|g(x_n)| *)
    rewrite (Nat.add_0_r n).
    apply (le_id_r _ (abs (entropy_gradient (iterate dynamics n E_A))) _).
    + apply (id_trans (id_sym (mult_one (abs (entropy_gradient (iterate dynamics n E_A)))))
                      (id_sym (mult_comm one (abs (entropy_gradient (iterate dynamics n E_A)))))).
    + apply le_refl.
  - (* k = S k'：|g(x_{n+S k'})| ≤ κ·|g(x_{n+k'})| ≤ κ·(κ^{k'}·|g(x_n)|) == κ^{S k'}·|g(x_n)| *)
    apply (le_trans _ (mult (minus one (mult eta mu)) (abs (entropy_gradient (iterate dynamics (n + k) E_A)))) _).
    + (* 单步：K2 at (n+k)，前提 j ≤ S(n+k) 由 Hall 给（n + S k' == S(n+k)） *)
      rewrite (Nat.add_succ_r n k).
      apply (gradient_iterate_abs_decay E_A (n + k) Heta Heta_mu).
      intros j Hj. apply Hall. lia.
    + (* 归纳步：κ·(κ^{k'}·|g(x_n)|) == κ^{S k'}·|g(x_n)|（mult_assoc + comm 换形） *)
      assert (IH' : le (abs (entropy_gradient (iterate dynamics (n + k) E_A)))
                        (mult (r_pow (minus one (mult eta mu)) k) (abs (entropy_gradient (iterate dynamics n E_A))))).
      { apply IH. intros j Hj. apply Hall. lia. }
      apply (le_id_r (mult (minus one (mult eta mu)) (abs (entropy_gradient (iterate dynamics (n + k) E_A))))
                     (mult (minus one (mult eta mu)) (mult (r_pow (minus one (mult eta mu)) k) (abs (entropy_gradient (iterate dynamics n E_A)))))
                     (mult (mult (minus one (mult eta mu)) (r_pow (minus one (mult eta mu)) k)) (abs (entropy_gradient (iterate dynamics n E_A))))
                     (mult_assoc (minus one (mult eta mu)) (r_pow (minus one (mult eta mu)) k) (abs (entropy_gradient (iterate dynamics n E_A))))
                     (le_mult_compat_r (minus one (mult eta mu))
                                       (abs (entropy_gradient (iterate dynamics (n + k) E_A)))
                                       (mult (r_pow (minus one (mult eta mu)) k) (abs (entropy_gradient (iterate dynamics n E_A))))
                                       (lt_le_iff _ _ (inl Hkpos))
                                       IH')).
Qed.

(* ================================================================
   论文4 差距一闭合（gradient_zero → is_truth），排序 4，2026-09-01
   诚实接口 entropy_tangent（凹函数切线不等式，一阶条件：
   f(y) ≤ f(x) + f'(x)·(y−x)，对所有 x y——标准优化假设，非经典公理）
   ⟹ gradient_zero_entropy_max：驻点（g(x)==0）是熵的全局最大点。
   绕开三分律（E216 障碍：Set 层无三分律，Real 层 Qlt_le_dec 三分
   可判定但需数百行 ε-δ）与积分（Real 层无 RInt/FTC）。
   is_truth 桥：以 L := −entropy（损失=负熵）则 is_truth (−entropy) x 成立。
   纪律：纯构造性 / Set 层 / 零 admit / 零经典。
   ================================================================ *)
(* 凹性切线不等式（诚实接口，同 strict_concavity 的量化版本） *)
Variable entropy_tangent : forall x y : R,
  le (entropy y) (plus (entropy x) (mult (entropy_gradient x) (minus y x))).

(* 差距一闭合：g(x)==0 ⟹ entropy y ≤ entropy x（驻点是全局最大点）
   证明：切线不等式 + g(x)==0 ⟹ entropy y ≤ entropy x + 0·(y−x) == entropy x。
   代数链：g(x)·(y−x) == 0·(y−x)（Hg）== 0（mult_comm + mult_zero）⟹ plus 吸收。 *)
Theorem gradient_zero_entropy_max : forall x : R,
  Id (entropy_gradient x) zero ->
  forall y : R, le (entropy y) (entropy x).
Proof.
  intros x Hg y.
  (* 切线不等式：entropy y ≤ entropy x + g(x)·(y−x) *)
  assert (Htangent : le (entropy y) (plus (entropy x) (mult (entropy_gradient x) (minus y x))))
    by exact (entropy_tangent x y).
  (* 代数：g(x)·(y−x) == 0·(y−x) == 0，plus (entropy x) 0 == entropy x *)
  assert (Hid : Id (plus (entropy x) (mult (entropy_gradient x) (minus y x))) (entropy x)).
  {
    apply (id_trans (id_cong (fun z => plus (entropy x) z)
                             (id_trans (id_cong (fun z => mult z (minus y x)) Hg)
                                       (id_trans (mult_comm zero (minus y x))
                                                 (mult_zero (minus y x)))))).
    apply (plus_zero (entropy x)).
  }
  (* 组装：entropy y ≤ plus ... 且 plus ... == entropy x ⟹ entropy y ≤ entropy x *)
  exact (le_id_r (entropy y) (plus (entropy x) (mult (entropy_gradient x) (minus y x))) (entropy x) Hid Htangent).
Qed.

(* is_truth 桥：g(x)==0 ⟹ (−entropy) 在 x 处全局最小（is_truth 形式，损失=负熵） *)
Theorem gradient_zero_neg_entropy_truth : forall x : R,
  Id (entropy_gradient x) zero ->
  forall y : R, le (opp (entropy x)) (opp (entropy y)).
Proof.
  intros x Hg y.
  (* 由差距一：le (entropy y) (entropy x) ⟹ opp 保序反号 *)
  apply (opp_le_compat (entropy y) (entropy x)).
  exact (gradient_zero_entropy_max x Hg y).
Qed.

(* ============================================================
   论文4 收敛缺口补强（差距二闭合，2026-09-01，探针 _dbg_unique_attractor.v 验证）：
   唯一吸引子 —— 任意两条轨道（任意初值）的极限相同。
   路线：弱三分（诚实接口 Variable，Real 层 real_weak_trich L32526 已证供给）
         + 严格递减（strict_concavity）⟹ 驻点唯一（gradient_zero_unique）
         ⟹ grad_squeeze_zero + 驻点唯一组装唯一吸引子（unique_attractor）
         ⟹ PCT 组装（attractor_converges_unique_truth：极限 = 唯一吸引子
           = 驻点 = −entropy 的 is_truth 点；差距一已由
           gradient_zero_neg_entropy_truth 闭合，差距二由 unique_attractor 闭合）。
   纪律：纯构造性 / Set 层 / 禁 Prop 定义 / 信息性证明 / 零 admit /
         零经典（无排中律、无经典实数公理）/ 可提取 OCaml。
   ============================================================ *)
(* 诚实接口假设：弱三分（Real 层 real_weak_trich L32526 已证，构造性成立；
   ¬(x<y) ∧ ¬(y<x) ⟹ x==y，非 LPO——整体三分律才等价 LPO） *)
Variable weak_trich : forall x y : R, Not (lt x y) -> Not (lt y x) -> Id x y.

(* K1：驻点唯一性（g 严格递减 ⟹ 至多一个驻点） *)
Lemma gradient_zero_unique : forall x y : R,
  Id (entropy_gradient x) zero ->
  Id (entropy_gradient y) zero ->
  Id x y.
Proof.
  intros x y Hgx Hgy.
  apply weak_trich.
  - (* Not (lt x y)：假设 lt x y ⟹ strict_concavity 给 lt (g y) (g x)
       ⟹ 代入 g x == 0（lt_id_r）⟹ lt (g y) zero
       ⟹ 代入 g y == 0（lt_id_l）⟹ lt zero zero ⟹ 矛盾 lt_irrefl *)
    intro Hxy.
    pose proof (strict_concavity x y Hxy) as Hdec.
    apply (lt_irrefl zero).
    apply (lt_id_l zero (entropy_gradient y) zero).
    + apply id_sym. exact Hgy.
    + apply (lt_id_r (entropy_gradient y) (entropy_gradient x) zero Hgx Hdec).
  - (* Not (lt y x)：对称 *)
    intro Hyx.
    pose proof (strict_concavity y x Hyx) as Hdec.
    apply (lt_irrefl zero).
    apply (lt_id_l zero (entropy_gradient x) zero).
    + apply id_sym. exact Hgx.
    + apply (lt_id_r (entropy_gradient x) (entropy_gradient y) zero Hgy Hdec).
Qed.

(* K3：唯一吸引子 —— 任意两条轨道（任意初值、任意极限）的极限相同。
   grad_squeeze_zero（L14234）把每条轨道的极限夹逼为驻点；
   gradient_zero_unique（K1）保证驻点唯一 ⟹ 极限相同。 *)
Theorem unique_attractor : forall (E_A E_A' : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A'))) ->
  forall E1 E2 : R,
    lim (fun n => iterate dynamics n E_A) E1 ->
    lim (fun n => iterate dynamics n E_A') E2 ->
    Id E1 E2.
Proof.
  intros E_A E_A' Hg0 Hg0' E1 E2 Hlim1 Hlim2.
  pose proof (grad_squeeze_zero E_A E1 Hlim1 Hg0) as Hg1.
  pose proof (grad_squeeze_zero E_A' E2 Hlim2 Hg0') as Hg2.
  exact (gradient_zero_unique E1 E2 Hg1 Hg2).
Qed.

(* PCT 组装：任意轨道极限 = 唯一吸引子 = 驻点 = −entropy 的 is_truth 点。
   差距一（驻点 ⟹ is_truth）由 gradient_zero_neg_entropy_truth（L14611）闭合；
   差距二（单轨 ⟹ 全局吸引）由 unique_attractor 闭合。
   And 为 Set 层信息性合取，可提取。 *)
Theorem attractor_converges_unique_truth : forall (E_A E_A' : R),
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A))) ->
  lt zero (abs (entropy_gradient (iterate dynamics 0 E_A'))) ->
  forall E1 E2 : R,
    lim (fun n => iterate dynamics n E_A) E1 ->
    lim (fun n => iterate dynamics n E_A') E2 ->
    And (Id E1 E2)
        (And (Id (entropy_gradient E1) zero)
             (forall y : R, le (opp (entropy E1)) (opp (entropy y)))).
Proof.
  intros E_A E_A' Hg0 Hg0' E1 E2 Hlim1 Hlim2.
  pose proof (grad_squeeze_zero E_A E1 Hlim1 Hg0) as Hg1.
  pose proof (grad_squeeze_zero E_A' E2 Hlim2 Hg0') as Hg2.
  split.
  - exact (gradient_zero_unique E1 E2 Hg1 Hg2).
  - split.
    + exact Hg1.
    + exact (gradient_zero_neg_entropy_truth E1 Hg1).
Qed.

End ConvergenceCauchy.
(* ============================================================ *)
(* 关键证明：SumExpPositive / ArgminCorrectness 等             *)
(* ============================================================ *)

Section KeyProofs.

Context {RI : RealInterfaceEnhanced}.

Section SumExpPositive.

Variable Token : Set.

(* 解包字段（使用不同名称避免遮蔽） *)
Let R := @R RI.
Let zero := @zero RI.
Let plus := @plus RI.
Let exp_neg := @exp_neg RI.
Let lt := @lt RI.
Let exp_neg_pos_local := @exp_neg_pos RI.
Let plus_positive_local := @plus_positive RI.
Let plus_zero_local := @plus_zero RI.

Variable neg_log_prob : list Token -> Token -> R.

Fixpoint sum_exp (prefix : list Token) (l : list Token) : R :=
  match l with
  | nil => zero
  | w :: rest => plus (exp_neg (neg_log_prob prefix w)) (sum_exp prefix rest)
  end.

Lemma sum_exp_positive :
  forall prefix l, Not (Id l nil) -> lt zero (sum_exp prefix l).
Proof.
  intros prefix l. induction l as [| w rest IH].
  - intros Hnil. contradiction Hnil. apply id_refl.
  - intros _. simpl.
    destruct rest as [| w' rest'].
    + (* rest = [] *)
      simpl.
      exact (match id_sym (plus_zero_local (exp_neg (neg_log_prob prefix w))) in (Id _ b) return (lt zero b) with
             | id_refl => exp_neg_pos_local (neg_log_prob prefix w)
             end).
    + (* rest = w' :: rest' *)
      simpl.
      apply plus_positive_local.
      * apply exp_neg_pos_local.
      * apply IH. intro H. inversion H.   (* 或者 [destruct H] *)
Qed.

End SumExpPositive.

Section ArgminCorrectness.

Variable Token : Set.
Context {DO : DecidableOrder RI}.
Let R := @R RI.
Let le := @le RI.
Let lt := @lt RI.
Let plus := @plus RI.
Let opp := @opp RI.
Let inv_pos := @inv_pos RI.
Let le_trans := @le_trans RI.
Let le_refl := @le_refl RI.

Variable total_loss : list Token -> R.

Definition candidate : Set := (Token * R)%type.

Fixpoint argmin_aux (prefix : list Token) (l : list Token) (best : candidate) : candidate :=
  match l with
  | nil => best
  | w :: rest =>
      let loss_w := total_loss (prefix ++ [w]) in
      match (@ord_le_dec RI DO) loss_w (snd best) with
      | inl _ => argmin_aux prefix rest (w, loss_w)
      | inr _ => argmin_aux prefix rest best
      end
  end.

Lemma argmin_aux_correct :
  forall prefix l best_token best_loss,
    let result := argmin_aux prefix l (best_token, best_loss) in
    And (le (snd result) best_loss)
        (forall w : Token, InT w l ->
          le (snd result) (total_loss (prefix ++ [w]))).
Proof.
  intros prefix l. induction l as [| a rest IH]; intros best_token best_loss.
  - simpl. split.
    + apply le_refl.
    + intros w HIn. inversion HIn.
  - simpl.
    destruct (@ord_le_dec _ DO (total_loss (prefix ++ [a])) best_loss) as [Hle | Hnot].
    + specialize (IH a (total_loss (prefix ++ [a]))).
      destruct IH as [IH_le IH_min].
      split.
      * eapply le_trans.
        -- apply IH_le.
        -- exact Hle.
      * intros w HIn.
        inversion HIn as [Hw | HIn']; subst.
        -- apply IH_le.
        -- apply IH_min. assumption.
    + specialize (IH best_token best_loss).
      destruct IH as [IH_le IH_min].
      split.
      * apply IH_le.
      * intros w HIn.
        inversion HIn as [Hw | HIn']; subst.
        -- assert (Hlt : lt best_loss (total_loss (prefix ++ [a]))).
           { apply not_le_lt. exact Hnot. }
           apply le_trans with best_loss.
           ++ apply IH_le.
           ++ apply lt_le_iff. left. exact Hlt.
        -- apply IH_min. assumption.
Qed.

Lemma argmin_aux_snd_correct :
  forall prefix l best_token best_loss,
    best_loss = total_loss (prefix ++ [best_token]) ->
    snd (argmin_aux prefix l (best_token, best_loss)) =
    total_loss (prefix ++ [fst (argmin_aux prefix l (best_token, best_loss))]).
Proof.
  induction l as [| a rest IH]; intros best_token best_loss Hbest.
  - simpl. exact Hbest.
  - simpl.
    destruct (@ord_le_dec _ DO (total_loss (prefix ++ [a])) best_loss) as [Hle | Hnot].
    + apply IH. reflexivity.
    + apply IH. exact Hbest.
Qed.

Variable vocab : list Token.
Variable vocab_nonempty : Not (Id vocab nil).
Variable default_token : Token.

Definition pick_best (prefix : list Token) : Token :=
  match vocab with
  | nil => default_token
  | w0 :: rest =>
      fst (argmin_aux prefix rest (w0, total_loss (prefix ++ [w0])))
  end.

Theorem pick_best_is_minimal :
  forall prefix w,
    InT w vocab ->
    le (total_loss (prefix ++ [pick_best prefix])) (total_loss (prefix ++ [w])).
Proof.
  intros prefix w HIn.
  unfold pick_best.
  destruct vocab as [| w0 rest].
  - inversion HIn.
  - simpl.
    destruct (argmin_aux_correct prefix rest w0 (total_loss (prefix ++ [w0]))) as [Hbest Hmin].
    (* 获得 snd 与 fst 的关系 *)
    assert (Hsnd := argmin_aux_snd_correct prefix rest w0 (total_loss (prefix ++ [w0])) eq_refl).
    (* 分析 w 在 vocab 中的两种可能 *)
    inversion HIn as [Hw | HIn']; subst.
    + (* 情况1：w = w0 *)
      rewrite <- Hsnd.
      apply Hbest.
    + (* 情况2：w 在 rest 中 *)
      rewrite <- Hsnd.
      apply Hmin. assumption.
Qed.

(* 贪心动力学：单步扩展为追加 pick_best（总损失最小者） *)
Definition dynamics (s : list Token) : list Token :=
  s ++ [pick_best s].

(* 贪心动力学的局部最优性（补齐预测性质.txt 模块1 目标）：
   对任意前缀 prefix 与候选 token w，动力学扩展（追加 pick_best）的
   总损失不超过追加任意 w 的总损失——贪心步是局部最优的。 *)
Theorem dynamics_greedy_locally_optimal :
  forall prefix w,
    InT w vocab ->
    le (total_loss (dynamics prefix)) (total_loss (prefix ++ [w])).
Proof.
  intros prefix w HIn.
  unfold dynamics.
  exact (pick_best_is_minimal prefix w HIn).
Qed.

End ArgminCorrectness.

Section SequenceLossPrefixApp.

Local Existing Instance RI_base.
Let R := @R RI.
Let zero := @zero RI.
Let plus := @plus RI.

Variable Token : Set.
Variable neg_log_prob : list Token -> Token -> R.

Fixpoint sequence_loss_prefix (prefix : list Token) (s : list Token) : R :=
  match s with
  | nil => zero
  | w :: rest =>
      plus (neg_log_prob prefix w) (sequence_loss_prefix (prefix ++ [w]) rest)
  end.

Lemma id_app_nil_r : forall (A : Set) (l : list A), Id (l ++ []) l.
Proof.
  induction l as [| x xs IH].
  - simpl. apply id_refl.
  - simpl. apply (id_cong (cons x)). exact IH.
Qed.

Lemma id_app_cons_assoc : forall (A : Set) (l : list A) (x : A) (rest : list A),
  Id (l ++ x :: rest) ((l ++ [x]) ++ rest).
Proof.
  induction l as [| y l' IH]; intros x rest.
  - simpl. apply id_refl.
  - simpl. apply (id_cong (cons y)). apply IH.
Qed.

Lemma sequence_loss_prefix_app :
  forall prefix s1 s2,
    Id (sequence_loss_prefix prefix (s1 ++ s2))
       (plus (sequence_loss_prefix prefix s1)
             (sequence_loss_prefix (prefix ++ s1) s2)).
Proof.
  intros prefix s1. revert prefix.
  induction s1 as [| w rest IH]; intros prefix.
  - intros s2.
    assert (H1 : Id (sequence_loss_prefix prefix s2)
                    (sequence_loss_prefix (prefix ++ []) s2)).
    { apply id_sym. apply (id_cong (fun p => sequence_loss_prefix p s2)). apply id_app_nil_r. }
    assert (H2 : Id (sequence_loss_prefix (prefix ++ []) s2)
                    (plus zero (sequence_loss_prefix (prefix ++ []) s2))).
    { apply id_sym. apply (id_trans (plus_comm zero _) (plus_zero _)). }
    exact (id_trans H1 H2).
  - intros s2.
    pose proof (IH (prefix ++ [w]) s2) as IH_s2.
    (* 步骤 1：定义展开左侧 *)
    assert (Hdef_left : Id (sequence_loss_prefix prefix ((w :: rest) ++ s2))
                           (plus (neg_log_prob prefix w)
                                 (sequence_loss_prefix (prefix ++ [w]) (rest ++ s2)))).
    { simpl. apply id_refl. }
    (* 步骤 2：使用归纳假设和结合律 *)
    assert (Hcong : Id (plus (neg_log_prob prefix w)
                            (sequence_loss_prefix (prefix ++ [w]) (rest ++ s2)))
                     (plus (neg_log_prob prefix w)
                           (plus (sequence_loss_prefix (prefix ++ [w]) rest)
                                 (sequence_loss_prefix ((prefix ++ [w]) ++ rest) s2)))).
    { apply (id_cong (fun x => plus (neg_log_prob prefix w) x)). exact IH_s2. }
    assert (Hassoc : Id (plus (neg_log_prob prefix w)
                              (plus (sequence_loss_prefix (prefix ++ [w]) rest)
                                    (sequence_loss_prefix ((prefix ++ [w]) ++ rest) s2)))
                        (plus (plus (neg_log_prob prefix w)
                                    (sequence_loss_prefix (prefix ++ [w]) rest))
                              (sequence_loss_prefix ((prefix ++ [w]) ++ rest) s2))).
    { apply plus_assoc. }
    assert (Hmid : Id (plus (neg_log_prob prefix w)
                            (sequence_loss_prefix (prefix ++ [w]) (rest ++ s2)))
                     (plus (plus (neg_log_prob prefix w)
                                 (sequence_loss_prefix (prefix ++ [w]) rest))
                           (sequence_loss_prefix ((prefix ++ [w]) ++ rest) s2))).
    { exact (id_trans Hcong Hassoc). }
    (* 步骤 3：定义展开右侧并应用列表等式 *)
    assert (Hdef_right : Id (plus (plus (neg_log_prob prefix w)
                                        (sequence_loss_prefix (prefix ++ [w]) rest))
                                  (sequence_loss_prefix ((prefix ++ [w]) ++ rest) s2))
                           (plus (sequence_loss_prefix prefix (w :: rest))
                                 (sequence_loss_prefix (prefix ++ w :: rest) s2))).
    {
      simpl.
      apply (id_cong (fun p => plus (plus (neg_log_prob prefix w)
                                          (sequence_loss_prefix (prefix ++ [w]) rest))
                                    (sequence_loss_prefix p s2))).
      apply id_sym. apply id_app_cons_assoc.
    }
    (* 最终组合 *)
    exact (id_trans Hdef_left (id_trans Hmid Hdef_right)).
Qed.

End SequenceLossPrefixApp.

End KeyProofs.

(* ============================================================ *)
(* 第八部分：论文核心内容的构造性形式化补全与缺失提取         *)
(* ============================================================ *)

Import PropositionConvergenceCore.

Section StateSpaceUtilities.
Context {RI : RealInterface}.
Context {SS : StateSpace RI}.

Definition sminus (a b : S) : S := splus a (sopp b).

Definition gradient_step (eta : R) (grad : (S -> R) -> S -> S) (L : S -> R) (s : S) : S :=
  splus s (smult eta (grad L s)).

End StateSpaceUtilities.

Section PropositionBasics.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.

Definition IsProposition (P : Proposition) : Set :=
  forall s : S, And (le zero (P s)) (le (P s) one).

Definition IsPositiveProposition (P : Proposition) : Set :=
  forall s : S, lt zero (P s).

End PropositionBasics.

Section LossAggregation.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.

Definition loss_of_proposition (P : Proposition) (s : S) : R :=
  log_inv (P s).

Definition weighted_sum_loss (props : list (Proposition * R)) (s : S) : R :=
  fold_right (fun (p_w : Proposition * R) acc =>
                let (P, w) := p_w in
                plus (mult w (loss_of_proposition P s)) acc)
             zero props.

Definition softmax_loss (props : list Proposition) (s : S) : R :=
  log_inv (fold_right (fun P acc =>
                         plus (exp_neg (loss_of_proposition P s)) acc)
                      zero props).

End LossAggregation.

Section GradientDescentAndAttractor.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

(* 解包字段 *)
Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let plus := @plus RI.
Let smult := @smult RI SS.
Let splus := @splus RI SS.
Let sopp := @sopp RI SS.
Let le := @le RI.
Let lt := @lt RI.
Let smetric := @smetric RI SS.
Let sum_over_S := @sum_over_S RI SS SO.

Variable grad : (S -> R) -> S -> S.

Definition force (L : S -> R) (s : S) : S :=
  sopp (grad L s).

Variable noise : S -> S.
Variable sigma : R.

Definition sgd_step (L : S -> R) (s : S) : S :=
  splus (smult sigma (force L s))
        (smult sigma (noise s)).

Variable transition_kernel : (S -> R) -> S -> S -> R.
Variable transition_nonneg : forall L s s', le zero (transition_kernel L s s').
Variable transition_normalization :
  forall L s, Id (sum_over_S (fun s' => transition_kernel L s s')) one.

Definition is_truth (L : S -> R) (s : S) : Set :=
  forall s' : S, le (L s) (L s').

Definition omega_limit (dyn : S -> S) (s0 : S) (s : S) : Set :=
  forall eps : R, lt zero eps ->
    sigT (fun n : nat => lt (smetric (iterate dyn n s0) s) eps).

Definition is_attractor (L : S -> R) (s : S) : Set :=
  forall s0 : S, omega_limit (sgd_step L) s0 s.

End GradientDescentAndAttractor.

(* 层级命题汇聚的聚合函数实现 *)
Section HierarchicalPropositions.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.

Let R := @R RI.
Let S := @S RI SS.
Let PropType := @Proposition RI SS.
Let loss_of_proposition := @loss_of_proposition RI SS.

Inductive PropositionLayer : Set :=
| BaseProp : PropType -> PropositionLayer
| ConjProp : list PropositionLayer -> (list R -> R) -> PropositionLayer.

Fixpoint eval_layer_loss (layer : PropositionLayer) (s : S) : R :=
  match layer with
  | BaseProp P => loss_of_proposition P s
  | ConjProp sub_layers agg =>
      agg (map (fun sub => eval_layer_loss sub s) sub_layers)
  end.

Definition softmax_aggregation (losses : list R) : R :=
  log_inv (fold_right (fun L acc => plus (exp_neg L) acc) zero losses).

Fixpoint safe_weighted_sum (weights losses : list R) : R :=
  match weights, losses with
  | w :: ws, l :: ls => plus (mult w l) (safe_weighted_sum ws ls)
  | _, _ => zero
  end.

Definition weighted_sum_aggregation (weights : list R) (losses : list R) : R :=
  safe_weighted_sum weights losses.

End HierarchicalPropositions.

Section BoltzmannSteadyState.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

(* 绑定基本类型和函数 *)
Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let inv_pos := @inv_pos RI.
Let exp_neg := @exp_neg RI.
Let le := @le RI.
Let lt := @lt RI.
Let sum_over_S := @sum_over_S RI SS SO.

Variable base_loss : S -> R.
Variable D : R.
Variable D_pos : lt zero D.

Variable Z : R.
Variable Z_pos : lt zero Z.
Variable partition_condition : Id Z (sum_over_S (fun s => exp_neg (mult (inv_pos D D_pos) (base_loss s)))).

Definition boltzmann_unnorm (s : S) : R :=
  exp_neg (mult (inv_pos D D_pos) (base_loss s)).

Definition boltzmann_prob (s : S) : R :=
  mult (inv_pos Z Z_pos) (boltzmann_unnorm s).

Variable transition : S -> S -> R.
Variable transition_nonneg : forall s s', le zero (transition s s').
Variable transition_normalization :
  forall s, Id (sum_over_S (fun s' => transition s s')) one.

Variable detailed_balance :
  forall s s',
    Id (mult (boltzmann_prob s) (transition s s'))
       (mult (boltzmann_prob s') (transition s' s)).

(* 非平凡实现：详细平衡 ⟹ 稳态（马尔可夫链基本定理）。
   纯构造性：逐点详细平衡 + 求和线性（sum_over_S_linear） + 转移归一化。
   注意：本 section 有 Let 解包（Let sum_over_S/mult 等），接口字段陈述为投影级，
   需 change 到 Let 层再 rewrite（见 E143）。 *)
Theorem steady_state_boltzmann :
  forall s,
    Id (sum_over_S (fun s' => mult (boltzmann_prob s') (transition s' s)))
       (boltzmann_prob s).
Proof.
  intro s.
  (* 1. 逐点详细平衡：∀s', p(s')·T(s',s) = p(s)·T(s,s') *)
  assert (Hpoint : forall s', Id (mult (boltzmann_prob s') (transition s' s))
                               (mult (boltzmann_prob s) (transition s s'))).
  { intro s'. apply (detailed_balance s' s). }
  (* 2. 用外延性（sum_over_S_ext）在求和参数内替换 *)
  assert (Hswap : Id (sum_over_S (fun s' => mult (boltzmann_prob s') (transition s' s)))
                     (sum_over_S (fun s' => mult (boltzmann_prob s) (transition s s')))).
  { apply sum_over_S_ext. exact Hpoint. }
  rewrite Hswap.
  (* 3. 提出常数因子 p(s)（sum_over_S_linear 投影陈述 → change 到 Let 层） *)
  pose proof (@sum_over_S_linear RI SS SO (boltzmann_prob s) (fun s' => transition s s')) as Hlin.
  change (Id (sum_over_S (fun s' => mult (boltzmann_prob s) (transition s s')))
             (mult (boltzmann_prob s) (sum_over_S (fun s' => transition s s')))) in Hlin.
  rewrite Hlin.
  (* 4. 转移归一化：Σ_{s'} T(s,s') = 1 *)
  rewrite (transition_normalization s).
  (* 5. p(s)·1 = p(s)（mult_one 投影陈述 → change 到 Let 层） *)
  pose proof (mult_one (boltzmann_prob s)) as Hm1.
  change (Id (mult (boltzmann_prob s) one) (boltzmann_prob s)) in Hm1.
  rewrite Hm1.
  reflexivity.
Qed.

End BoltzmannSteadyState.

(* ============================================================ *)
(* 项 6 工具（2026-09-02，通用接口层）：正乘严格消去（lt 版）   *)
(* ============================================================ *)
Section TempStrictTools.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one  := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp  := @opp RI.
Let le := @le RI.
Let lt := @lt RI.
Let inv_pos := @inv_pos RI.
Let sum_over_S := @sum_over_S RI SS SO.

(* 正乘严格消去：c > 0 且 a·c > 0 ⟹ a > 0（a == (a·c)·inv c） *)
Lemma lt_mult_pos_cancel : forall a c : R, lt zero c -> lt zero (mult a c) -> lt zero a.
Proof.
  intros a c Hc H.
  apply (lt_id_r zero (mult (mult a c) (inv_pos c Hc)) a).
  - apply id_sym.
    exact (id_trans (id_sym (mult_one a))
           (id_trans (id_cong (fun x => mult a x) (id_sym (inv_pos_correct c Hc)))
                     (mult_assoc a c (inv_pos c Hc)))).
  - apply mult_positive.
    + exact H.
    + apply inv_pos_pos.
Qed.

End TempStrictTools.

Section FreeEnergyMinimization.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

(* 显式绑定基本类型与函数 *)
Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let inv_pos := @inv_pos RI.
Let exp_neg := @exp_neg RI.
Let le := @le RI.
Let lt := @lt RI.
Let log := @log RI.                       (* 注意：free_energy 中使用了 log *)
Let sum_over_S := @sum_over_S RI SS SO.

Variable base_loss : S -> R.
Variable D : R.
Variable D_pos : lt zero D.

Definition free_energy (p : S -> R) : R :=
  plus (sum_over_S (fun s => mult (p s) (base_loss s)))
       (mult D (sum_over_S (fun s => mult (p s) (log (p s))))).

Definition normalized (p : S -> R) : Set := Id (sum_over_S p) one.
Definition positive_dist (p : S -> R) : Set := forall s, lt zero (p s).

Variable Z : R.
Variable Z_pos : lt zero Z.
Variable partition_condition : Id Z (sum_over_S (fun s => exp_neg (mult (inv_pos D D_pos) (base_loss s)))).

Definition boltzmann_dist : S -> R :=
  fun s => mult (inv_pos Z Z_pos) (exp_neg (mult (inv_pos D D_pos) (base_loss s))).

(* ============================================================ *)
(* 训练-推理闭环（非平凡实现：自由能与 Boltzmann 分布的精确连接）*)
(* ============================================================ *)

(* sum 的负号线性：Σ (-f) = -Σ f *)
Lemma sum_opp :
  forall (f : S -> R),
    Id (sum_over_S (fun s => opp (f s))) (opp (sum_over_S f)).
Proof.
  intro f.
  assert (Hext : Id (sum_over_S (fun s => opp (f s)))
                   (sum_over_S (fun s => mult (opp one) (f s)))).
  {
    apply sum_over_S_ext.
    intro s.
    assert (H1 : Id (mult (opp one) (f s)) (opp (mult one (f s))))
      by exact (opp_mult_r one (f s)).
    assert (H2 : Id (opp (mult one (f s))) (opp (f s)))
      by exact (id_cong opp (id_trans (mult_comm one (f s)) (mult_one (f s)))).
    exact (id_trans (id_sym H2) (id_sym H1)).
  }
  rewrite Hext.
  assert (Hlin : Id (sum_over_S (fun s => mult (opp one) (f s)))
                   (mult (opp one) (sum_over_S f)))
    by exact (sum_over_S_linear (opp one) f).
  rewrite Hlin.
  assert (H1 : Id (mult (opp one) (sum_over_S f)) (opp (mult one (sum_over_S f))))
    by exact (opp_mult_r one (sum_over_S f)).
  assert (H2 : Id (opp (mult one (sum_over_S f))) (opp (sum_over_S f)))
    by exact (id_cong opp (id_trans (mult_comm one (sum_over_S f)) (mult_one (sum_over_S f)))).
  exact (id_trans H1 H2).
Qed.

(* sum 的减法线性：Σ (f - g) = Σ f - Σ g（由 add + opp 推出） *)
Lemma sum_over_S_minus :
  forall (f g : S -> R),
    Id (sum_over_S (fun s => minus (f s) (g s)))
       (minus (sum_over_S f) (sum_over_S g)).
Proof.
  intros f g.
  unfold minus.
  assert (Hadd : Id (sum_over_S (fun s => plus (f s) (opp (g s))))
                   (plus (sum_over_S f) (sum_over_S (fun s => opp (g s)))))
    by exact (sum_over_S_add f (fun s => opp (g s))).
  assert (Hopp : Id (sum_over_S (fun s => opp (g s))) (opp (sum_over_S g)))
    by exact (sum_opp g).
  exact (id_trans Hadd (id_cong (fun x => plus (sum_over_S f) x) Hopp)).
Qed.

(* Boltzmann 分布归一化：Σ_s p_b(s) = 1（概率质量守恒；平凡版——配分函数定义的重述） *)
Theorem boltzmann_normalized :
  Id (sum_over_S boltzmann_dist) one.
Proof.
  unfold boltzmann_dist.
  assert (Hlin : Id (sum_over_S (fun s => mult (inv_pos Z Z_pos) (exp_neg (mult (inv_pos D D_pos) (base_loss s)))))
                   (mult (inv_pos Z Z_pos) (sum_over_S (fun s => exp_neg (mult (inv_pos D D_pos) (base_loss s))))))
    by exact (sum_over_S_linear (inv_pos Z Z_pos) (fun s => exp_neg (mult (inv_pos D D_pos) (base_loss s)))).
  assert (HZ : Id (sum_over_S (fun s => exp_neg (mult (inv_pos D D_pos) (base_loss s)))) Z)
    by exact (id_sym partition_condition).
  assert (Hcc : Id (mult (inv_pos Z Z_pos) Z) one)
    by exact (id_trans (mult_comm (inv_pos Z Z_pos) Z) (inv_pos_correct Z Z_pos)).
  exact (id_trans Hlin (id_trans (id_cong (fun x => mult (inv_pos Z Z_pos) x) HZ) Hcc)).
Qed.

(* 非平凡版本：凸组合归一化守恒——概率分布的凸组合闭包
   （混合策略 / 模型集成 / 蒸馏的数学基础；分布代数的守恒律，
    非配分函数定义的重述）。 *)
Theorem boltzmann_mix_normalized :
  forall (p q : S -> R) (alpha : R) (Halpha : lt zero alpha) (Halpha1 : lt zero (minus one alpha)),
    normalized p -> normalized q ->
    Id (sum_over_S (fun s => plus (mult alpha (p s)) (mult (minus one alpha) (q s)))) one.
Proof.
  intros p q alpha Halpha Halpha1 Hp Hq.
  unfold normalized in Hp, Hq.
  assert (Hadd : Id (sum_over_S (fun s => plus (mult alpha (p s)) (mult (minus one alpha) (q s))))
                   (plus (sum_over_S (fun s => mult alpha (p s))) (sum_over_S (fun s => mult (minus one alpha) (q s)))))
    by exact (sum_over_S_add (fun s => mult alpha (p s)) (fun s => mult (minus one alpha) (q s))).
  rewrite Hadd.
  assert (Hlin1 : Id (sum_over_S (fun s => mult alpha (p s))) (mult alpha (sum_over_S p)))
    by exact (sum_over_S_linear alpha p).
  rewrite Hlin1.
  assert (Hlin2 : Id (sum_over_S (fun s => mult (minus one alpha) (q s))) (mult (minus one alpha) (sum_over_S q)))
    by exact (sum_over_S_linear (minus one alpha) q).
  rewrite Hlin2.
  rewrite Hp. rewrite Hq.
  assert (Hm1 : Id (mult alpha one) alpha) by exact (mult_one alpha).
  rewrite Hm1.
  assert (Hm2 : Id (mult (minus one alpha) one) (minus one alpha)) by exact (mult_one (minus one alpha)).
  rewrite Hm2.
  (* 目标：plus alpha (minus one alpha) = one——assert + exact 链（避免 unfold/rewrite 目标依赖） *)
  assert (Hfin : Id (plus alpha (minus one alpha)) one).
  {
    unfold minus.
    assert (Hsw : Id (plus alpha (plus one (opp alpha))) (plus one (plus alpha (opp alpha)))).
    {
      assert (H1 : Id (plus alpha (plus one (opp alpha))) (plus (plus alpha one) (opp alpha)))
        by exact (plus_assoc alpha one (opp alpha)).
      assert (H2 : Id (plus (plus alpha one) (opp alpha)) (plus (plus one alpha) (opp alpha)))
        by exact (id_cong (fun x => plus x (opp alpha)) (plus_comm alpha one)).
      assert (H3 : Id (plus (plus one alpha) (opp alpha)) (plus one (plus alpha (opp alpha))))
        by exact (id_sym (plus_assoc one alpha (opp alpha))).
      exact (id_trans H1 (id_trans H2 H3)).
    }
    assert (Hfin2 : Id (plus one (plus alpha (opp alpha))) one).
    {
      assert (Hpz : Id (plus one zero) one) by exact (plus_zero one).
      assert (Hpz2 : Id (plus one (plus alpha (opp alpha))) (plus one zero))
        by exact (id_cong (fun x => plus one x) (plus_opp alpha)).
      exact (id_trans Hpz2 Hpz).
    }
    exact (id_trans Hsw Hfin2).
  }
  exact Hfin.
Qed.

(* Boltzmann 分布的对数分解：log p_b(s) = -log Z - E(s)/D *)
Theorem boltzmann_log_decomp :
  forall s : S,
    Id (log (boltzmann_dist s))
       (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))).
Proof.
  intro s.
  unfold boltzmann_dist.
  assert (Hpos1 : lt zero (inv_pos Z Z_pos)) by exact (inv_pos_pos Z Z_pos).
  assert (Hpos2 : lt zero (exp_neg (mult (inv_pos D D_pos) (base_loss s))))
    by exact (exp_neg_pos (mult (inv_pos D D_pos) (base_loss s))).
  assert (Hlm : Id (log (mult (inv_pos Z Z_pos) (exp_neg (mult (inv_pos D D_pos) (base_loss s)))))
                  (plus (log (inv_pos Z Z_pos)) (log (exp_neg (mult (inv_pos D D_pos) (base_loss s))))))
    by exact (log_mult (inv_pos Z Z_pos) (exp_neg (mult (inv_pos D D_pos) (base_loss s))) Hpos1 Hpos2).
  rewrite Hlm.
  assert (Hli : Id (log (inv_pos Z Z_pos)) (opp (log Z)))
    by exact (log_inv_one_inv Z Z_pos).
  rewrite Hli.
  assert (Hle : Id (log (exp_neg (mult (inv_pos D D_pos) (base_loss s))))
                  (opp (mult (inv_pos D D_pos) (base_loss s))))
    by exact (log_exp_neg (mult (inv_pos D D_pos) (base_loss s))).
  rewrite Hle.
  reflexivity.
Qed.

(* ============================================================ *)
(* 训练-推理闭环定理：自由能在 Boltzmann 分布处的显式值        *)
(*   F[p_b] = ⟨E⟩ + D·Σ p_b·log p_b = -D·log Z                 *)
(* ============================================================ *)
(* 训练阶段：自由能最小化（min_free_energy_is_boltzmann）给出 Boltzmann 分布；
   推理阶段：该分布的熵-能量平衡坍缩出精确闭合值 -D·log Z。
   非平凡推导链：逐点对数分解（boltzmann_log_decomp）→
   求和线性/负号线性（sum_over_S_add/linear + sum_opp）→
   归一化（boltzmann_normalized）→ 环代数坍缩。 *)
Theorem free_energy_boltzmann :
  Id (free_energy boltzmann_dist) (mult (opp D) (log Z)).
Proof.
  unfold free_energy.
  set (Eavg := sum_over_S (fun s => mult (boltzmann_dist s) (base_loss s))).
  (* Let 层桥接：字段引理 → 节内定义（E143 模式：exact 走转换，rewrite 需同层断言） *)
  assert (Hdist : forall a b c : R, Id (mult a (plus b c)) (plus (mult a b) (mult a c)))
    by exact (distrib).
  assert (Hoppl : forall a b : R, Id (mult a (opp b)) (opp (mult a b)))
    by exact (opp_mult_l).
  assert (Hoppr : forall a b : R, Id (mult (opp a) b) (opp (mult a b)))
    by exact (opp_mult_r).
  assert (Hassoc : forall a b c : R, Id (mult a (mult b c)) (mult (mult a b) c))
    by exact (mult_assoc).
  assert (Hcomm : forall a b : R, Id (mult a b) (mult b a))
    by exact (mult_comm).
  assert (Hmo : forall a : R, Id (mult a one) a)
    by exact (mult_one).
  assert (Hpa : forall a b c : R, Id (plus a (plus b c)) (plus (plus a b) c))
    by exact (plus_assoc).
  assert (Hpc : forall a b : R, Id (plus a b) (plus b a))
    by exact (plus_comm).
  assert (Hpz : forall a : R, Id (plus a zero) a)
    by exact (plus_zero).
  assert (Hpo : forall a : R, Id (plus a (opp a)) zero)
    by exact (plus_opp).
  (* 步骤 1：逐点分解 p_b(s)·log p_b(s) *)
  assert (Hpoint :
    forall s : S,
      Id (mult (boltzmann_dist s) (log (boltzmann_dist s)))
         (plus (mult (boltzmann_dist s) (opp (log Z)))
               (opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))))).
  {
    intro s.
    assert (Hld : Id (log (boltzmann_dist s))
                     (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))))
      by exact (boltzmann_log_decomp s).
    assert (Hc : Id (mult (boltzmann_dist s) (log (boltzmann_dist s)))
                    (mult (boltzmann_dist s) (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s))))))
      by exact (id_cong (fun x => mult (boltzmann_dist s) x) Hld).
    rewrite Hc.
    rewrite (Hdist (boltzmann_dist s) (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))).
    rewrite (Hoppl (boltzmann_dist s) (mult (inv_pos D D_pos) (base_loss s))).
    assert (Hswap : Id (mult (boltzmann_dist s) (mult (inv_pos D D_pos) (base_loss s)))
                       (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))).
    {
      assert (H1 : Id (mult (boltzmann_dist s) (mult (inv_pos D D_pos) (base_loss s)))
                      (mult (mult (boltzmann_dist s) (inv_pos D D_pos)) (base_loss s)))
        by exact (Hassoc (boltzmann_dist s) (inv_pos D D_pos) (base_loss s)).
      assert (H2 : Id (mult (mult (boltzmann_dist s) (inv_pos D D_pos)) (base_loss s))
                      (mult (mult (inv_pos D D_pos) (boltzmann_dist s)) (base_loss s)))
        by exact (id_cong (fun x => mult x (base_loss s)) (Hcomm (boltzmann_dist s) (inv_pos D D_pos))).
      assert (H3 : Id (mult (mult (inv_pos D D_pos) (boltzmann_dist s)) (base_loss s))
                      (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s))))
        by exact (id_sym (Hassoc (inv_pos D D_pos) (boltzmann_dist s) (base_loss s))).
      exact (id_trans H1 (id_trans H2 H3)).
    }
    rewrite Hswap.
    reflexivity.
  }
  (* 步骤 2：对 s 求和：Σ p_b·log p_b = -log Z - (1/D)·⟨E⟩ *)
  assert (Hsum :
    Id (sum_over_S (fun s => mult (boltzmann_dist s) (log (boltzmann_dist s))))
       (plus (opp (log Z))
             (opp (mult (inv_pos D D_pos) Eavg)))).
  {
    assert (Hext : Id (sum_over_S (fun s => mult (boltzmann_dist s) (log (boltzmann_dist s))))
                     (sum_over_S (fun s => plus (mult (boltzmann_dist s) (opp (log Z)))
                                                (opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))))))
      by exact (sum_over_S_ext (fun s => mult (boltzmann_dist s) (log (boltzmann_dist s)))
                               (fun s => plus (mult (boltzmann_dist s) (opp (log Z)))
                                              (opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))))
                               Hpoint).
    rewrite Hext.
    assert (Hadd : Id (sum_over_S (fun s => plus (mult (boltzmann_dist s) (opp (log Z)))
                                                (opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s))))))
                      (plus (sum_over_S (fun s => mult (boltzmann_dist s) (opp (log Z))))
                            (sum_over_S (fun s => opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))))))
      by exact (sum_over_S_add (fun s => mult (boltzmann_dist s) (opp (log Z)))
                               (fun s => opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s))))).
    rewrite Hadd.
    (* 第一项：Σ p_b·(-log Z) = (-log Z)·Σ p_b = -log Z *)
    assert (Hsw1 : Id (sum_over_S (fun s => mult (boltzmann_dist s) (opp (log Z))))
                      (sum_over_S (fun s => mult (opp (log Z)) (boltzmann_dist s)))).
    {
      apply sum_over_S_ext.
      intro s.
      apply (Hcomm (boltzmann_dist s) (opp (log Z))).
    }
    rewrite Hsw1.
    assert (Hlin1 : Id (sum_over_S (fun s => mult (opp (log Z)) (boltzmann_dist s)))
                       (mult (opp (log Z)) (sum_over_S boltzmann_dist)))
      by exact (sum_over_S_linear (opp (log Z)) boltzmann_dist).
    rewrite Hlin1.
    assert (Hnorm : Id (sum_over_S boltzmann_dist) one) by exact (boltzmann_normalized).
    rewrite Hnorm.
    assert (Hm1 : Id (mult (opp (log Z)) one) (opp (log Z))) by exact (Hmo (opp (log Z))).
    rewrite Hm1.
    (* 第二项：Σ opp((1/D)·p_b·E) = opp((1/D)·Σ p_b·E) *)
    assert (Hso : Id (sum_over_S (fun s => opp (mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))))
                     (opp (sum_over_S (fun s => mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s))))))
      by exact (sum_opp (fun s => mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s)))).
    rewrite Hso.
    assert (Hlin2 : Id (sum_over_S (fun s => mult (inv_pos D D_pos) (mult (boltzmann_dist s) (base_loss s))))
                       (mult (inv_pos D D_pos) (sum_over_S (fun s => mult (boltzmann_dist s) (base_loss s)))))
      by exact (sum_over_S_linear (inv_pos D D_pos) (fun s => mult (boltzmann_dist s) (base_loss s))).
    rewrite Hlin2.
    reflexivity.
  }
  rewrite Hsum.
  (* 步骤 3：D·(-log Z - (1/D)·⟨E⟩) = -D·log Z - ⟨E⟩ *)
  assert (Hmd : Id (mult D (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) Eavg))))
                  (plus (opp (mult D (log Z))) (opp Eavg))).
  {
    rewrite (Hdist D (opp (log Z)) (opp (mult (inv_pos D D_pos) Eavg))).
    rewrite (Hoppl D (log Z)).
    rewrite (Hoppl D (mult (inv_pos D D_pos) Eavg)).
    assert (Hmd2 : Id (mult D (mult (inv_pos D D_pos) Eavg)) Eavg).
    {
      assert (Hcc1 : Id (mult (mult D (inv_pos D D_pos)) Eavg) Eavg).
      {
        assert (Ht : Id (mult (mult D (inv_pos D D_pos)) Eavg) (mult one Eavg))
          by exact (id_cong (fun x => mult x Eavg) (inv_pos_correct D D_pos)).
        assert (Ht2 : Id (mult one Eavg) (mult Eavg one))
          by exact (Hcomm one Eavg).
        exact (id_trans Ht (id_trans Ht2 (Hmo Eavg))).
      }
      exact (id_trans (Hassoc D (inv_pos D D_pos) Eavg) Hcc1).
    }
    rewrite Hmd2.
    reflexivity.
  }
  rewrite Hmd.
  (* 步骤 4：⟨E⟩ + (-D·log Z - ⟨E⟩) = -D·log Z（环代数坍缩） *)
  assert (Hfin : Id (plus Eavg (plus (opp (mult D (log Z))) (opp Eavg)))
                    (opp (mult D (log Z)))).
  {
    assert (H1 : Id (plus Eavg (plus (opp (mult D (log Z))) (opp Eavg)))
                    (plus (plus Eavg (opp (mult D (log Z)))) (opp Eavg)))
      by exact (Hpa Eavg (opp (mult D (log Z))) (opp Eavg)).
    assert (H2 : Id (plus (plus Eavg (opp (mult D (log Z)))) (opp Eavg))
                    (plus (plus (opp (mult D (log Z))) Eavg) (opp Eavg)))
      by exact (id_cong (fun y => plus y (opp Eavg)) (Hpc Eavg (opp (mult D (log Z))))).
    assert (H3 : Id (plus (plus (opp (mult D (log Z))) Eavg) (opp Eavg))
                    (plus (opp (mult D (log Z))) (plus Eavg (opp Eavg))))
      by exact (id_sym (Hpa (opp (mult D (log Z))) Eavg (opp Eavg))).
    assert (H4 : Id (plus (opp (mult D (log Z))) (plus Eavg (opp Eavg)))
                    (plus (opp (mult D (log Z))) zero))
      by exact (id_cong (fun y => plus (opp (mult D (log Z))) y) (Hpo Eavg)).
    assert (H5 : Id (plus (opp (mult D (log Z))) zero) (opp (mult D (log Z))))
      by exact (Hpz (opp (mult D (log Z)))).
    exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5)))).
  }
  assert (Hoppr2 : Id (opp (mult D (log Z))) (mult (opp D) (log Z)))
    by exact (id_sym (Hoppr D (log Z))).
  exact (id_trans Hfin Hoppr2).
Qed.

(* ============================================================ *)
(* 训练-推理闭环皇冠定理：自由能-相对熵恒等式                  *)
(*   F[p] = F[p_b] + D·KL(p || p_b)                             *)
(* ============================================================ *)
(* 含义：对任意归一化分布 p，自由能等于 Boltzmann 自由能加上   *)
(* 温度 D 乘相对熵。⟹ 训练（自由能最小化）与推理（分布逼近     *)
(* Boltzmann）精确等价——最小化 F 就是最小化 KL。              *)
(* 非平凡推导：能量用对数分解反解 E = -D·(log p_b + log Z)，   *)
(* 逐点替换 + 求和线性/负号线性 + 归一化坍缩。                 *)
(* ------------------------------------------------------------ *)

(* 引理 1：能量反解——由 boltzmann_log_decomp 得
   E(s) = -D·(log p_b(s) + log Z) *)
Lemma energy_in_log_boltzmann :
  forall s : S,
    Id (base_loss s)
       (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))).
Proof.
  intro s.
  (* log p_b = -log Z - E/D ⟹ log p_b + log Z = -E/D *)
  assert (Hlog : Id (log (boltzmann_dist s))
                    (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))))
    by exact (boltzmann_log_decomp s).
  assert (Hsum : Id (plus (log (boltzmann_dist s)) (log Z))
                    (opp (mult (inv_pos D D_pos) (base_loss s)))).
  {
    assert (Hc : Id (plus (log (boltzmann_dist s)) (log Z))
                    (plus (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))) (log Z)))
      by exact (id_cong (fun x => plus x (log Z)) Hlog).
    assert (H1 : Id (plus (plus (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))) (log Z))
                    (plus (opp (log Z)) (plus (opp (mult (inv_pos D D_pos) (base_loss s))) (log Z))))
      by exact (id_sym (plus_assoc (opp (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s))) (log Z))).
    assert (H2 : Id (plus (opp (log Z)) (plus (opp (mult (inv_pos D D_pos) (base_loss s))) (log Z)))
                    (plus (opp (log Z)) (plus (log Z) (opp (mult (inv_pos D D_pos) (base_loss s))))))
      by exact (id_cong (fun x => plus (opp (log Z)) x)
                        (plus_comm (opp (mult (inv_pos D D_pos) (base_loss s))) (log Z))).
    assert (H3 : Id (plus (opp (log Z)) (plus (log Z) (opp (mult (inv_pos D D_pos) (base_loss s)))))
                    (plus (plus (opp (log Z)) (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s)))))
      by exact (plus_assoc (opp (log Z)) (log Z) (opp (mult (inv_pos D D_pos) (base_loss s)))).
    assert (H4 : Id (plus (plus (opp (log Z)) (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s))))
                    (plus zero (opp (mult (inv_pos D D_pos) (base_loss s))))).
    {
      assert (H4a : Id (plus (plus (opp (log Z)) (log Z)) (opp (mult (inv_pos D D_pos) (base_loss s))))
                      (plus (plus (log Z) (opp (log Z))) (opp (mult (inv_pos D D_pos) (base_loss s)))))
        by exact (id_cong (fun x => plus x (opp (mult (inv_pos D D_pos) (base_loss s))))
                          (plus_comm (opp (log Z)) (log Z))).
      assert (H4b : Id (plus (plus (log Z) (opp (log Z))) (opp (mult (inv_pos D D_pos) (base_loss s))))
                      (plus zero (opp (mult (inv_pos D D_pos) (base_loss s)))))
        by exact (id_cong (fun x => plus x (opp (mult (inv_pos D D_pos) (base_loss s)))) (plus_opp (log Z))).
      exact (id_trans H4a H4b).
    }
    assert (H5 : Id (plus zero (opp (mult (inv_pos D D_pos) (base_loss s))))
                    (opp (mult (inv_pos D D_pos) (base_loss s))))
      by exact (id_trans (plus_comm zero (opp (mult (inv_pos D D_pos) (base_loss s)))) (plus_zero (opp (mult (inv_pos D D_pos) (base_loss s))))).
    exact (id_trans Hc (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5))))).
  }
  (* D·(-E/D) = -E；目标反号后为 E = -D·(log p_b + log Z) *)
  assert (Hmd : Id (mult D (plus (log (boltzmann_dist s)) (log Z)))
                   (opp (base_loss s))).
  {
    assert (Hc2 : Id (mult D (plus (log (boltzmann_dist s)) (log Z)))
                     (mult D (opp (mult (inv_pos D D_pos) (base_loss s)))))
      by exact (id_cong (fun x => mult D x) Hsum).
    assert (Hopp : Id (mult D (opp (mult (inv_pos D D_pos) (base_loss s))))
                      (opp (mult D (mult (inv_pos D D_pos) (base_loss s)))))
      by exact (opp_mult_l D (mult (inv_pos D D_pos) (base_loss s))).
    assert (Hcc : Id (mult D (mult (inv_pos D D_pos) (base_loss s))) (base_loss s)).
    {
      assert (Hma : Id (mult D (mult (inv_pos D D_pos) (base_loss s)))
                       (mult (mult D (inv_pos D D_pos)) (base_loss s)))
        by exact (mult_assoc D (inv_pos D D_pos) (base_loss s)).
      assert (Hic : Id (mult (mult D (inv_pos D D_pos)) (base_loss s))
                       (mult one (base_loss s)))
        by exact (id_cong (fun x => mult x (base_loss s)) (inv_pos_correct D D_pos)).
      assert (Hm1 : Id (mult one (base_loss s)) (base_loss s))
        by exact (id_trans (mult_comm one (base_loss s)) (mult_one (base_loss s))).
      exact (id_trans Hma (id_trans Hic Hm1)).
    }
    exact (id_trans Hc2 (id_trans Hopp (id_cong opp Hcc))).
  }
  (* E = -D·(log p_b + log Z)：由 mult D (log p_b + log Z) = -E 反号 *)
  assert (Hinv : Id (opp (mult D (plus (log (boltzmann_dist s)) (log Z))))
                    (base_loss s)).
  {
    assert (Hd : Id (opp (mult D (plus (log (boltzmann_dist s)) (log Z))))
                    (opp (opp (base_loss s))))
      by exact (id_cong opp Hmd).
    assert (Hdn : Id (opp (opp (base_loss s))) (base_loss s))
      by exact (double_neg (base_loss s)).
    exact (id_trans Hd Hdn).
  }
  exact (id_sym Hinv).
Qed.

(* 引理 2：逐点分解 mult (p s) (base_loss s) = -D·p·log p_b - D·p·log Z *)
Lemma p_times_energy_decomp :
  forall (p : S -> R) (s : S),
    Id (mult (p s) (base_loss s))
       (plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
             (opp (mult D (mult (p s) (log Z))))).
Proof.
  intros p s.
  assert (He : Id (base_loss s)
                  (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
    by exact (energy_in_log_boltzmann s).
  assert (Hc : Id (mult (p s) (base_loss s))
                  (mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z))))))
    by exact (id_cong (fun x => mult (p s) x) He).
  assert (Hopp : Id (mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                    (opp (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))))
    by exact (opp_mult_l (p s) (mult D (plus (log (boltzmann_dist s)) (log Z)))).
  (* mult (p s) (mult D X) = mult D (mult (p s) X)（交换重组） *)
  assert (Hsw : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                   (mult D (mult (p s) (plus (log (boltzmann_dist s)) (log Z))))).
  {
    assert (H1 : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                    (mult (mult (p s) D) (plus (log (boltzmann_dist s)) (log Z))))
      by exact (mult_assoc (p s) D (plus (log (boltzmann_dist s)) (log Z))).
    assert (H2 : Id (mult (mult (p s) D) (plus (log (boltzmann_dist s)) (log Z)))
                    (mult (mult D (p s)) (plus (log (boltzmann_dist s)) (log Z))))
      by exact (id_cong (fun x => mult x (plus (log (boltzmann_dist s)) (log Z))) (mult_comm (p s) D)).
    assert (H3 : Id (mult (mult D (p s)) (plus (log (boltzmann_dist s)) (log Z)))
                    (mult D (mult (p s) (plus (log (boltzmann_dist s)) (log Z)))))
      by exact (id_sym (mult_assoc D (p s) (plus (log (boltzmann_dist s)) (log Z)))).
    exact (id_trans H1 (id_trans H2 H3)).
  }
  (* distrib：mult (p s) (log p_b + log Z) = p·log p_b + p·log Z *)
  assert (Hdist : Id (mult (p s) (plus (log (boltzmann_dist s)) (log Z)))
                     (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))))
    by exact (distrib (p s) (log (boltzmann_dist s)) (log Z)).
  assert (Hsw2 : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                    (mult D (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z)))))
    by exact (id_trans Hsw (id_cong (fun x => mult D x) Hdist)).
  assert (Hdist2 : Id (mult D (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))))
                      (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                            (mult D (mult (p s) (log Z)))))
    by exact (distrib D (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))).
  assert (Htot : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                    (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                          (mult D (mult (p s) (log Z)))))
    by exact (id_trans Hsw2 Hdist2).
  (* opp 展开：opp (X + Y) = opp X + opp Y *)
  assert (Hop : Id (opp (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                              (mult D (mult (p s) (log Z)))))
                   (plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                         (opp (mult D (mult (p s) (log Z))))))
    by exact (opp_plus (mult D (mult (p s) (log (boltzmann_dist s))))
                       (mult D (mult (p s) (log Z)))).
  assert (Hc2 : Id (opp (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                   (opp (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                              (mult D (mult (p s) (log Z))))))
    by exact (id_cong opp Htot).
  exact (id_trans Hc (id_trans Hopp (id_trans Hc2 Hop))).
Qed.

(* 主定理：F[p] = F[p_b] + D·KL(p || p_b) *)
Theorem free_energy_kl_decomp :
  forall p : S -> R,
    normalized p ->
    Id (free_energy p)
       (plus (free_energy boltzmann_dist)
             (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))).
Proof.
  intros p Hnorm.
  unfold normalized in Hnorm.
  (* 展开 LHS 的 free_energy p（RHS 的 free_energy boltzmann_dist 保持完整，供 Hfb 重写） *)
  assert (Hfe_p : Id (free_energy p)
                     (plus (sum_over_S (fun s => mult (p s) (base_loss s)))
                           (mult D (sum_over_S (fun s => mult (p s) (log (p s))))))).
  { reflexivity. }
  rewrite Hfe_p.
  (* 步骤 1：Σ p·E = -D·Σ p·log p_b - D·log Z *)
  assert (Hse : Id (sum_over_S (fun s => mult (p s) (base_loss s)))
                   (plus (opp (mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))
                         (opp (mult D (log Z))))).
  {
    assert (Hpt : forall s : S,
                    Id (mult (p s) (base_loss s))
                       (plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                             (opp (mult D (mult (p s) (log Z))))))
      by exact (p_times_energy_decomp p).
    assert (Hext : Id (sum_over_S (fun s => mult (p s) (base_loss s)))
                     (sum_over_S (fun s => plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                                                (opp (mult D (mult (p s) (log Z)))))))
      by exact (sum_over_S_ext (fun s => mult (p s) (base_loss s))
                               (fun s => plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                                              (opp (mult D (mult (p s) (log Z)))))
                               Hpt).
    rewrite Hext.
    assert (Hadd : Id (sum_over_S (fun s => plus (opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                                                 (opp (mult D (mult (p s) (log Z))))))
                      (plus (sum_over_S (fun s => opp (mult D (mult (p s) (log (boltzmann_dist s))))))
                            (sum_over_S (fun s => opp (mult D (mult (p s) (log Z)))))))
      by exact (sum_over_S_add (fun s => opp (mult D (mult (p s) (log (boltzmann_dist s)))))
                               (fun s => opp (mult D (mult (p s) (log Z))))).
    rewrite Hadd.
    assert (Hso1 : Id (sum_over_S (fun s => opp (mult D (mult (p s) (log (boltzmann_dist s))))))
                      (opp (sum_over_S (fun s => mult D (mult (p s) (log (boltzmann_dist s)))))))
      by exact (sum_opp (fun s => mult D (mult (p s) (log (boltzmann_dist s))))).
    rewrite Hso1.
    assert (Hlin1 : Id (sum_over_S (fun s => mult D (mult (p s) (log (boltzmann_dist s)))))
                       (mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))
      by exact (sum_over_S_linear D (fun s => mult (p s) (log (boltzmann_dist s)))).
    rewrite Hlin1.
    assert (Hso2 : Id (sum_over_S (fun s => opp (mult D (mult (p s) (log Z)))))
                      (opp (sum_over_S (fun s => mult D (mult (p s) (log Z))))))
      by exact (sum_opp (fun s => mult D (mult (p s) (log Z)))).
    rewrite Hso2.
    assert (Hlin2 : Id (sum_over_S (fun s => mult D (mult (p s) (log Z))))
                       (mult D (sum_over_S (fun s => mult (p s) (log Z)))))
      by exact (sum_over_S_linear D (fun s => mult (p s) (log Z))).
    rewrite Hlin2.
    (* 内层：Σ p·log Z = log Z·Σ p = log Z（归一化） *)
    assert (HlogZ : Id (sum_over_S (fun s => mult (p s) (log Z))) (log Z)).
    {
      assert (Hsw : Id (sum_over_S (fun s => mult (p s) (log Z)))
                       (sum_over_S (fun s => mult (log Z) (p s))))
        by exact (sum_over_S_ext (fun s => mult (p s) (log Z))
                                 (fun s => mult (log Z) (p s))
                                 (fun s => mult_comm (p s) (log Z))).
      rewrite Hsw.
      assert (Hl1 : Id (sum_over_S (fun s => mult (log Z) (p s))) (mult (log Z) (sum_over_S p)))
        by exact (sum_over_S_linear (log Z) p).
      rewrite Hl1.
      rewrite Hnorm.
      assert (Hm1 : Id (mult (log Z) one) (log Z)) by exact (mult_one (log Z)).
      rewrite Hm1.
      reflexivity.
    }
    rewrite HlogZ.
    reflexivity.
  }
  rewrite Hse.
  (* 步骤 2：F[p_b] = -D·log Z（已证 free_energy_boltzmann + opp_mult_r） *)
  assert (Hfb : Id (free_energy boltzmann_dist) (opp (mult D (log Z)))).
  {
    assert (Hfb0 : Id (free_energy boltzmann_dist) (mult (opp D) (log Z)))
      by exact (free_energy_boltzmann).
    assert (Hoppr : Id (mult (opp D) (log Z)) (opp (mult D (log Z))))
      by exact (opp_mult_r D (log Z)).
    exact (id_trans Hfb0 Hoppr).
  }
  rewrite Hfb.
  (* 步骤 3：KL 展开——mult D (Σ p·(log p - log p_b))
     = D·Σ p·log p - D·Σ p·log p_b *)
  assert (Hkl : Id (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                  (plus (mult D (sum_over_S (fun s => mult (p s) (log (p s)))))
                        (opp (mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s)))))))).
  {
    (* 逐点：p·(log p - log p_b) = p·log p - p·log p_b *)
    assert (Hpt2 : forall s : S,
                    Id (mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))
                       (plus (mult (p s) (log (p s)))
                             (opp (mult (p s) (log (boltzmann_dist s)))))).
    {
      intro s.
      unfold minus.
      assert (Hd : Id (mult (p s) (plus (log (p s)) (opp (log (boltzmann_dist s)))))
                      (plus (mult (p s) (log (p s))) (mult (p s) (opp (log (boltzmann_dist s))))))
        by exact (distrib (p s) (log (p s)) (opp (log (boltzmann_dist s)))).
      assert (Ho : Id (mult (p s) (opp (log (boltzmann_dist s))))
                      (opp (mult (p s) (log (boltzmann_dist s)))))
        by exact (opp_mult_l (p s) (log (boltzmann_dist s))).
      exact (id_trans Hd (id_cong (fun x => plus (mult (p s) (log (p s))) x) Ho)).
    }
    assert (Hext2 : Id (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))
                      (sum_over_S (fun s => plus (mult (p s) (log (p s)))
                                                 (opp (mult (p s) (log (boltzmann_dist s)))))))
      by exact (sum_over_S_ext (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))
                               (fun s => plus (mult (p s) (log (p s))) (opp (mult (p s) (log (boltzmann_dist s)))))
                               Hpt2).
    rewrite Hext2.
    assert (Hadd2 : Id (sum_over_S (fun s => plus (mult (p s) (log (p s)))
                                                  (opp (mult (p s) (log (boltzmann_dist s))))))
                       (plus (sum_over_S (fun s => mult (p s) (log (p s))))
                             (sum_over_S (fun s => opp (mult (p s) (log (boltzmann_dist s)))))))
      by exact (sum_over_S_add (fun s => mult (p s) (log (p s)))
                               (fun s => opp (mult (p s) (log (boltzmann_dist s))))).
    rewrite Hadd2.
    assert (Hso3 : Id (sum_over_S (fun s => opp (mult (p s) (log (boltzmann_dist s)))))
                      (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))
      by exact (sum_opp (fun s => mult (p s) (log (boltzmann_dist s)))).
    rewrite Hso3.
    (* 提取 D（线性） *)
    assert (HdistD : Id (mult D (plus (sum_over_S (fun s => mult (p s) (log (p s))))
                                      (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s)))))))
                        (plus (mult D (sum_over_S (fun s => mult (p s) (log (p s)))))
                              (mult D (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))))
      by exact (distrib D (sum_over_S (fun s => mult (p s) (log (p s))))
                         (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s)))))).
    assert (HoppD : Id (mult D (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))
                       (opp (mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s)))))))
      by exact (opp_mult_l D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))).
    assert (HcD : Id (mult D (plus (sum_over_S (fun s => mult (p s) (log (p s))))
                                   (opp (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s)))))))
                     (plus (mult D (sum_over_S (fun s => mult (p s) (log (p s)))))
                           (opp (mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))))))
      by exact (id_trans HdistD
                          (id_cong (fun x => plus (mult D (sum_over_S (fun s => mult (p s) (log (p s))))) x) HoppD)).
    exact HcD.
  }
  (* 步骤 4：主目标环代数坍缩
     (opp A + opp (D log Z)) + D·Σp log p
     = opp (D log Z) + (D·Σp log p + opp A)  其中 A := D·Σ p log p_b *)
  set (A := mult D (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))).
  set (B := mult D (sum_over_S (fun s => mult (p s) (log (p s))))).
  (* 重写 KL 侧：目标含 B 与 opp A *)
  assert (Hkl2 : Id (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                    (plus B (opp A))).
  {
    unfold A, B.
    exact Hkl.
  }
  rewrite Hkl2.
  (* 目标：(opp A + opp (D log Z)) + B = opp (D log Z) + (B + opp A) *)
  assert (Hfin : Id (plus (plus (opp A) (opp (mult D (log Z)))) B)
                    (plus (opp (mult D (log Z))) (plus B (opp A)))).
  {
    assert (H1 : Id (plus (plus (opp A) (opp (mult D (log Z)))) B)
                    (plus (opp A) (plus (opp (mult D (log Z))) B)))
      by exact (id_sym (plus_assoc (opp A) (opp (mult D (log Z))) B)).
    assert (H2 : Id (plus (opp A) (plus (opp (mult D (log Z))) B))
                    (plus (opp A) (plus B (opp (mult D (log Z))))))
      by exact (id_cong (fun x => plus (opp A) x)
                        (plus_comm (opp (mult D (log Z))) B)).
    assert (H3 : Id (plus (opp A) (plus B (opp (mult D (log Z)))))
                    (plus (plus (opp A) B) (opp (mult D (log Z)))))
      by exact (plus_assoc (opp A) B (opp (mult D (log Z)))).
    assert (H4 : Id (plus (plus (opp A) B) (opp (mult D (log Z))))
                    (plus (plus B (opp A)) (opp (mult D (log Z)))))
      by exact (id_cong (fun x => plus x (opp (mult D (log Z)))) (plus_comm (opp A) B)).
    assert (H5 : Id (plus (plus B (opp A)) (opp (mult D (log Z))))
                    (plus (opp (mult D (log Z))) (plus B (opp A))))
      by exact (plus_comm (plus B (opp A)) (opp (mult D (log Z)))).
    exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5)))).
  }
  exact Hfin.
Qed.

(* 推论：自由能差 = D × 相对熵（差形式，常用于训练目标分解） *)
Theorem free_energy_kl_diff :
  forall p : S -> R,
    normalized p ->
    Id (minus (free_energy p) (free_energy boltzmann_dist))
       (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))).
Proof.
  intros p Hnorm.
  unfold minus.
  assert (Hdecomp : Id (free_energy p)
                       (plus (free_energy boltzmann_dist)
                             (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))))
    by exact (free_energy_kl_decomp p Hnorm).
  rewrite Hdecomp.
  (* F_b + (F - F_b 项) ⟹ 目标：plus F_b KL 的 opp 形式 *)
  assert (Hcn : Id (plus (plus (free_energy boltzmann_dist)
                               (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))))
                         (opp (free_energy boltzmann_dist)))
                   (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))).
  {
    set (FB := free_energy boltzmann_dist).
    set (KL := mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))).
    assert (H1 : Id (plus (plus FB KL) (opp FB))
                    (plus FB (plus KL (opp FB))))
      by exact (id_sym (plus_assoc FB KL (opp FB))).
    assert (H2 : Id (plus FB (plus KL (opp FB)))
                    (plus FB (plus (opp FB) KL)))
      by exact (id_cong (fun x => plus FB x) (plus_comm KL (opp FB))).
    assert (H3 : Id (plus FB (plus (opp FB) KL))
                    (plus (plus FB (opp FB)) KL))
      by exact (plus_assoc FB (opp FB) KL).
    assert (H4 : Id (plus (plus FB (opp FB)) KL)
                    (plus zero KL))
      by exact (id_cong (fun x => plus x KL) (plus_opp FB)).
    assert (H5 : Id (plus zero KL) KL)
      by exact (id_trans (plus_comm zero KL) (plus_zero KL)).
    exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5)))).
  }
  exact Hcn.
Qed.

(* ============================================================ *)
(* F[p] - F[q] = D·(KL(p‖p_b) - KL(q‖p_b))
   深化意义：自由能差等于两分布各自相对 Boltzmann 的 KL 之差。
   给出任意两候选分布的相对质量排序：F[p] ≤ F[q] ⟺
   KL(p‖p_b) ≤ KL(q‖p_b)。支撑：模型选择、分布逼近偏序、
   生成模型的相对评估、蒸馏中师生差距的度量。 *)
Theorem free_energy_diff_kl :
  forall p q : S -> R,
    normalized p -> normalized q ->
    Id (minus (free_energy p) (free_energy q)) (mult D (minus (sum_over_S (fun s0 => mult (p s0) (minus (log (p s0)) (log (boltzmann_dist s0))))) (sum_over_S (fun s0 => mult (q s0) (minus (log (q s0)) (log (boltzmann_dist s0))))))).

  intros p q Hnp Hnq.
  (* 1. 两侧各自的 free_energy_kl_diff *)
  assert (Hp : Id (minus (free_energy p) (free_energy boltzmann_dist))
                  (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))))
    by exact (free_energy_kl_diff p Hnp).
  assert (Hq : Id (minus (free_energy q) (free_energy boltzmann_dist))
                  (mult D (sum_over_S (fun s => mult (q s) (minus (log (q s)) (log (boltzmann_dist s)))))))
    by exact (free_energy_kl_diff q Hnq).
  (* 2. ring_minus_trans：F[p]-F[q] = (F[p]-F_b) - (F[q]-F_b) *)
  assert (Hsplit : Id (minus (free_energy p) (free_energy q))
                      (minus (minus (free_energy p) (free_energy boltzmann_dist))
                             (minus (free_energy q) (free_energy boltzmann_dist))))
    by exact (ring_minus_trans (free_energy p) (free_energy q) (free_energy boltzmann_dist)).
  (* 3. 代入 Hp、Hq：(D·KL_p) - (D·KL_q) = D·(KL_p - KL_q) *)
  assert (Hsub : Id (minus (free_energy p) (free_energy q)) (minus (mult D (sum_over_S (fun s0 => mult (p s0) (minus (log (p s0)) (log (boltzmann_dist s0)))))) (mult D (sum_over_S (fun s0 => mult (q s0) (minus (log (q s0)) (log (boltzmann_dist s0)))))))).

  {
    assert (H1 : Id (minus (minus (free_energy p) (free_energy boltzmann_dist))
                           (minus (free_energy q) (free_energy boltzmann_dist)))
                    (minus (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                           (minus (free_energy q) (free_energy boltzmann_dist))))
      by exact (id_cong (fun x => minus x (minus (free_energy q) (free_energy boltzmann_dist))) Hp).
    assert (H2 : Id (minus (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                           (minus (free_energy q) (free_energy boltzmann_dist)))
                    (minus (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                           (mult D (sum_over_S (fun s => mult (q s) (minus (log (q s)) (log (boltzmann_dist s))))))))
      by exact (id_cong (fun x => minus (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))) x) Hq).
    exact (id_trans Hsplit (id_trans H1 H2)).
  }
  (* 4. mult_minus_distr_l 反向：D·(KL_p - KL_q) = (D·KL_p) - (D·KL_q) *)
  assert (Hm : Id (minus (mult D (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s))))))
                         (mult D (sum_over_S (fun s => mult (q s) (minus (log (q s)) (log (boltzmann_dist s)))))))
                  (mult D (minus (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist s)))))
                                 (sum_over_S (fun s => mult (q s) (minus (log (q s)) (log (boltzmann_dist s))))))))
    by exact (id_sym (mult_minus_distr_l D (sum_over_S (fun s0 => mult (p s0) (minus (log (p s0)) (log (boltzmann_dist s0))))) (sum_over_S (fun s0 => mult (q s0) (minus (log (q s0)) (log (boltzmann_dist s0))))))).
  exact (id_trans Hsub Hm).
Qed.

(* 相对熵（KL 散度）：KL(p || q) := Σ_s p(s)·(log p(s) - log q(s)) *)
Definition relative_entropy (p q : S -> R) : R :=
  sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (q s)))).

(* 关键代数引理：p·(log p - log q) = p·log(p/q)，且
   p·(q/p) = q（分式约分；用于 Gibbs 不等式逐点项） *)
Lemma gibbs_pointwise :
  forall (p q : S -> R) (s : S),
    lt zero (p s) -> lt zero (q s) ->
    le (minus (p s) (q s))
       (mult (p s) (minus (log (p s)) (log (q s)))).
Proof.
  intros p q s Hps Hqs.
  (* log(q/p) ≤ q/p - 1（log 凹性切线，q/p > 0） *)
  assert (Hratio_pos : lt zero (mult (q s) (inv_pos (p s) Hps)))
    by exact (mult_positive (q s) (inv_pos (p s) Hps) Hqs (inv_pos_pos (p s) Hps)).
  assert (Hlin : le (log (mult (q s) (inv_pos (p s) Hps)))
                    (minus (mult (q s) (inv_pos (p s) Hps)) one))
    by exact (log_le_linear (mult (q s) (inv_pos (p s) Hps)) Hratio_pos).
  (* 反号：-(q/p - 1) ≤ -log(q/p)，即 1 - q/p ≤ log(p/q) *)
  assert (Hopp : le (opp (minus (mult (q s) (inv_pos (p s) Hps)) one))
                    (opp (log (mult (q s) (inv_pos (p s) Hps)))))
    by exact (opp_le_compat (log (mult (q s) (inv_pos (p s) Hps)))
                            (minus (mult (q s) (inv_pos (p s) Hps)) one) Hlin).
  (* log(p/q) = -log(q/p)（log_div_neg） *)
  assert (Hld : Id (log (mult (p s) (inv_pos (q s) Hqs)))
                   (opp (log (mult (q s) (inv_pos (p s) Hps)))))
    by exact (log_div_neg (p s) (q s) Hps Hqs).
  (* 目标 RHS 用 log(p/q) 替换：mult (p s) (minus (log p) (log q)) = mult (p s) (log (p/q)) *)
  assert (Hrhs : Id (mult (p s) (minus (log (p s)) (log (q s))))
                    (mult (p s) (log (mult (p s) (inv_pos (q s) Hqs))))).
  {
    assert (Hlogdiv : Id (log (mult (p s) (inv_pos (q s) Hqs)))
                         (minus (log (p s)) (log (q s))))
      by exact (log_div (p s) (q s) Hps Hqs).
    exact (id_sym (id_cong (fun x => mult (p s) x) Hlogdiv)).
  }
  rewrite Hrhs.
  (* 目标：minus (p s) (q s) ≤ mult (p s) (log (p/q))
     用 p·(1 - q/p) ≤ p·log(p/q)（log_le_linear 反号 + le_mult_compat） *)
  assert (Hstep1 : le (mult (p s) (opp (minus (mult (q s) (inv_pos (p s) Hps)) one)))
                      (mult (p s) (opp (log (mult (q s) (inv_pos (p s) Hps))))))
    by exact (le_mult_compat_r (p s)
                               (opp (minus (mult (q s) (inv_pos (p s) Hps)) one))
                               (opp (log (mult (q s) (inv_pos (p s) Hps))))
                               (lt_le_iff _ _ (inl Hps)) Hopp).
  (* p·log(p/q) = p·(-log(q/p)) *)
  assert (Hstep2 : Id (mult (p s) (log (mult (p s) (inv_pos (q s) Hqs))))
                      (mult (p s) (opp (log (mult (q s) (inv_pos (p s) Hps))))))
    by exact (id_cong (fun x => mult (p s) x) Hld).
  rewrite <- Hstep2 in Hstep1.
  (* 目标 LHS：p·(1 - q/p) = p - p·(q/p) = p - q *)
  assert (Hlhs : Id (minus (p s) (q s))
                    (mult (p s) (opp (minus (mult (q s) (inv_pos (p s) Hps)) one)))).
  {
    (* mult (p s) (opp (minus X one)) = opp (mult (p s) (minus X one))
       = opp (minus (mult (p s) X) (mult (p s) one)) = opp (minus (p·X) (p·1))
       mult (p s) X = q s，mult (p s) one = p s ⟹ = opp (minus (q s) (p s)) = minus (p s) (q s) *)
    assert (Hoppl : Id (mult (p s) (opp (minus (mult (q s) (inv_pos (p s) Hps)) one)))
                       (opp (mult (p s) (minus (mult (q s) (inv_pos (p s) Hps)) one))))
      by exact (opp_mult_l (p s) (minus (mult (q s) (inv_pos (p s) Hps)) one)).
    assert (Hdist : Id (mult (p s) (minus (mult (q s) (inv_pos (p s) Hps)) one))
                       (minus (mult (p s) (mult (q s) (inv_pos (p s) Hps)))
                              (mult (p s) one)))
      by exact (mult_minus_distr_l (p s) (mult (q s) (inv_pos (p s) Hps)) one).
    assert (Hcc : Id (mult (p s) (mult (q s) (inv_pos (p s) Hps))) (q s)).
    {
      assert (H1 : Id (mult (p s) (mult (q s) (inv_pos (p s) Hps)))
                      (mult (mult (p s) (q s)) (inv_pos (p s) Hps)))
        by exact (mult_assoc (p s) (q s) (inv_pos (p s) Hps)).
      assert (H2 : Id (mult (mult (p s) (q s)) (inv_pos (p s) Hps))
                      (mult (mult (q s) (p s)) (inv_pos (p s) Hps)))
        by exact (id_cong (fun x => mult x (inv_pos (p s) Hps)) (mult_comm (p s) (q s))).
      assert (H3 : Id (mult (mult (q s) (p s)) (inv_pos (p s) Hps))
                      (mult (q s) (mult (p s) (inv_pos (p s) Hps))))
        by exact (id_sym (mult_assoc (q s) (p s) (inv_pos (p s) Hps))).
      assert (H4 : Id (mult (q s) (mult (p s) (inv_pos (p s) Hps)))
                      (mult (q s) one))
        by exact (id_cong (fun x => mult (q s) x) (inv_pos_correct (p s) Hps)).
      assert (H5 : Id (mult (q s) one) (q s)) by exact (mult_one (q s)).
      exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5)))).
    }
    assert (Hmo : Id (mult (p s) one) (p s)) by exact (mult_one (p s)).
    assert (Hfull : Id (mult (p s) (minus (mult (q s) (inv_pos (p s) Hps)) one))
                       (minus (q s) (p s)))
      by exact (id_trans Hdist (id_trans (id_cong (fun x => minus x (mult (p s) one)) Hcc)
                                         (id_cong (fun x => minus (q s) x) Hmo))).
    assert (Hopp2 : Id (opp (minus (q s) (p s))) (minus (p s) (q s)))
      by exact (id_trans (opp_minus (q s) (p s)) (id_sym (plus_comm (p s) (opp (q s))))).
    exact (id_sym (id_trans Hoppl (id_trans (id_cong opp Hfull) Hopp2))).
  }
  rewrite <- Hlhs in Hstep1.
  exact Hstep1.
Qed.

(* Gibbs 不等式：归一化正分布的相对熵非负（KL ≥ 0）。
   非平凡：log 凹性切线 + 逐点分式约分 + 求和保序。 *)
Theorem gibbs_inequality :
  forall p q : S -> R,
    normalized p -> positive_dist p ->
    normalized q -> positive_dist q ->
    le zero (relative_entropy p q).
Proof.
  intros p q Hnp Hpp Hnq Hpq.
  unfold relative_entropy.
  (* 逐点：p - q ≤ p·(log p - log q)，求和保序 ⟹ Σ(p-q) ≤ KL *)
  assert (Hpt : forall s, le (minus (p s) (q s))
                            (mult (p s) (minus (log (p s)) (log (q s)))))
    by (intro s; apply (gibbs_pointwise p q s); [exact (Hpp s) | exact (Hpq s)]).
  assert (Hle : le (sum_over_S (fun s => minus (p s) (q s)))
                   (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (q s))))))
    by exact (sum_over_S_le (fun s => minus (p s) (q s))
                            (fun s => mult (p s) (minus (log (p s)) (log (q s))))
                            Hpt).
  (* Σ(p - q) = Σp - Σq = 1 - 1 = 0（归一化 + sum_over_S_add + sum_opp） *)
  assert (Hsum0 : Id (sum_over_S (fun s => minus (p s) (q s))) zero).
  {
    unfold minus.
    assert (Hadd : Id (sum_over_S (fun s => plus (p s) (opp (q s))))
                     (plus (sum_over_S p) (sum_over_S (fun s => opp (q s)))))
      by exact (sum_over_S_add p (fun s => opp (q s))).
    assert (Hoppq : Id (sum_over_S (fun s => opp (q s))) (opp (sum_over_S q)))
      by exact (sum_opp q).
    assert (Htot : Id (sum_over_S (fun s => plus (p s) (opp (q s))))
                     (plus (sum_over_S p) (opp (sum_over_S q))))
      by exact (id_trans Hadd (id_cong (fun x => plus (sum_over_S p) x) Hoppq)).
    assert (Hnp' : Id (sum_over_S p) one) by exact Hnp.
    assert (Hnq' : Id (sum_over_S q) one) by exact Hnq.
    assert (Hfin : Id (plus (sum_over_S p) (opp (sum_over_S q))) zero)
      by exact (id_trans (id_cong (fun x => plus x (opp (sum_over_S q))) Hnp')
                         (id_trans (id_cong (fun x => plus one x) (id_cong opp Hnq')) (plus_opp one))).
    exact (id_trans Htot Hfin).
  }
  rewrite Hsum0 in Hle.
  exact Hle.
Qed.

(* Gibbs 等号条件：KL(p||q) = 0 ⟹ p = q（逐点）。
   证明链：
   1) d(s) := p·(log p - log q) - (p - q) ≥ 0（gibbs_pointwise + le_minus_nonneg）；
   2) Σ d = KL - Σ(p-q) = 0 - 0 = 0（sum_over_S_minus + 归一化）；
   3) sum_over_S_zero_nonneg：Σ d = 0 且 d ≥ 0 ⟹ d(s) = 0；
   4) minus_eq_cancel：p·(log p - log q) = p - q；
   5) log_div 换形 + mult_cancel_l（p > 0）⟹ log(q/p) = q/p - 1；
   6) log_eq_linear（log 严格凹）⟹ q/p = 1；
   7) mult_cancel_r（inv_pos p > 0）⟹ q = p。 *)
Theorem gibbs_equality :
  forall p q : S -> R,
    normalized p -> positive_dist p ->
    normalized q -> positive_dist q ->
    Id (relative_entropy p q) zero ->
    forall s : S, Id (p s) (q s).
Proof.
  intros p q Hnp Hpp Hnq Hpq Hkl0 s0.
  unfold relative_entropy in Hkl0.
  (* 1) d ≥ 0 逐点 *)
  assert (Hd_nonneg : forall s, le zero (minus (mult (p s) (minus (log (p s)) (log (q s))))
                                             (minus (p s) (q s)))).
  {
    intro s.
    apply le_minus_nonneg.
    apply (gibbs_pointwise p q s); [exact (Hpp s) | exact (Hpq s)].
  }
  (* 2) Σ d = 0 *)
  assert (Hd_sum : Id (sum_over_S (fun s => minus (mult (p s) (minus (log (p s)) (log (q s))))
                                             (minus (p s) (q s)))) zero).
  {
    assert (Hadd : Id (sum_over_S (fun s => minus (mult (p s) (minus (log (p s)) (log (q s))))
                                             (minus (p s) (q s))))
                     (minus (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (q s)))))
                            (sum_over_S (fun s => minus (p s) (q s)))))
      by exact (sum_over_S_minus (fun s => mult (p s) (minus (log (p s)) (log (q s))))
                                 (fun s => minus (p s) (q s))).
    rewrite Hadd.
    assert (Hpq0 : Id (sum_over_S (fun s => minus (p s) (q s))) zero).
    {
      unfold minus.
      assert (Hadd2 : Id (sum_over_S (fun s => plus (p s) (opp (q s))))
                        (plus (sum_over_S p) (sum_over_S (fun s => opp (q s)))))
        by exact (sum_over_S_add p (fun s => opp (q s))).
      assert (Hoppq : Id (sum_over_S (fun s => opp (q s))) (opp (sum_over_S q)))
        by exact (sum_opp q).
      assert (Htot : Id (sum_over_S (fun s => plus (p s) (opp (q s))))
                       (plus (sum_over_S p) (opp (sum_over_S q))))
        by exact (id_trans Hadd2 (id_cong (fun x => plus (sum_over_S p) x) Hoppq)).
      assert (Hfin : Id (plus (sum_over_S p) (opp (sum_over_S q))) zero)
        by exact (id_trans (id_cong (fun x => plus x (opp (sum_over_S q))) Hnp)
                           (id_trans (id_cong (fun x => plus one x) (id_cong opp Hnq)) (plus_opp one))).
      exact (id_trans Htot Hfin).
    }
    assert (Hminus : Id (minus zero zero) zero)
      by (unfold minus; exact (plus_opp zero)).
    exact (id_trans (id_cong (fun x => minus x (sum_over_S (fun s => minus (p s) (q s)))) Hkl0)
                   (id_trans (id_cong (fun x => minus zero x) Hpq0) Hminus)).
  }
  (* 3) d(s0) = 0 *)
  assert (Hd0s : Id (minus (mult (p s0) (minus (log (p s0)) (log (q s0))))
                           (minus (p s0) (q s0))) zero)
    by exact (sum_over_S_zero_nonneg
                (fun s => minus (mult (p s) (minus (log (p s)) (log (q s))))
                                (minus (p s) (q s)))
                Hd_nonneg Hd_sum s0).
  (* 4) p·(log p - log q) = p - q *)
  assert (Hrel : Id (mult (p s0) (minus (log (p s0)) (log (q s0))))
                   (minus (p s0) (q s0)))
    by exact (minus_eq_cancel (mult (p s0) (minus (log (p s0)) (log (q s0))))
                              (minus (p s0) (q s0)) Hd0s).
  (* 5) 换形：log(p/q) = log p - log q；q/p 反号 *)
  assert (Hlhs : Id (mult (p s0) (minus (log (p s0)) (log (q s0))))
                    (mult (p s0) (log (mult (p s0) (inv_pos (q s0) (Hpq s0))))))
    by exact (id_sym (id_cong (fun x => mult (p s0) x)
                              (log_div (p s0) (q s0) (Hpp s0) (Hpq s0)))).
  rewrite Hlhs in Hrel.
  (* p·log(p/q) = p·(-log(q/p)) *)
  assert (Hlogneg : Id (log (mult (p s0) (inv_pos (q s0) (Hpq s0))))
                       (opp (log (mult (q s0) (inv_pos (p s0) (Hpp s0))))))
    by exact (log_div_neg (p s0) (q s0) (Hpp s0) (Hpq s0)).
  assert (Hlhs2 : Id (mult (p s0) (log (mult (p s0) (inv_pos (q s0) (Hpq s0)))))
                     (mult (p s0) (opp (log (mult (q s0) (inv_pos (p s0) (Hpp s0)))))))
    by exact (id_cong (fun x => mult (p s0) x) Hlogneg).
  rewrite Hlhs2 in Hrel.
  (* RHS：p - q = p·(1 - q/p)（由 gibbs_pointwise 内恒等反向） *)
  assert (Hrhs : Id (minus (p s0) (q s0))
                    (mult (p s0) (opp (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)))).
  {
    assert (Hoppl : Id (mult (p s0) (opp (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)))
                       (opp (mult (p s0) (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one))))
      by exact (opp_mult_l (p s0) (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)).
    assert (Hdist : Id (mult (p s0) (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one))
                       (minus (mult (p s0) (mult (q s0) (inv_pos (p s0) (Hpp s0))))
                              (mult (p s0) one)))
      by exact (mult_minus_distr_l (p s0) (mult (q s0) (inv_pos (p s0) (Hpp s0))) one).
    assert (Hcc : Id (mult (p s0) (mult (q s0) (inv_pos (p s0) (Hpp s0)))) (q s0)).
    {
      assert (H1 : Id (mult (p s0) (mult (q s0) (inv_pos (p s0) (Hpp s0))))
                      (mult (mult (p s0) (q s0)) (inv_pos (p s0) (Hpp s0))))
        by exact (mult_assoc (p s0) (q s0) (inv_pos (p s0) (Hpp s0))).
      assert (H2 : Id (mult (mult (p s0) (q s0)) (inv_pos (p s0) (Hpp s0)))
                      (mult (mult (q s0) (p s0)) (inv_pos (p s0) (Hpp s0))))
        by exact (id_cong (fun x => mult x (inv_pos (p s0) (Hpp s0))) (mult_comm (p s0) (q s0))).
      assert (H3 : Id (mult (mult (q s0) (p s0)) (inv_pos (p s0) (Hpp s0)))
                      (mult (q s0) (mult (p s0) (inv_pos (p s0) (Hpp s0)))))
        by exact (id_sym (mult_assoc (q s0) (p s0) (inv_pos (p s0) (Hpp s0)))).
      assert (H4 : Id (mult (q s0) (mult (p s0) (inv_pos (p s0) (Hpp s0))))
                      (mult (q s0) one))
        by exact (id_cong (fun x => mult (q s0) x) (inv_pos_correct (p s0) (Hpp s0))).
      assert (H5 : Id (mult (q s0) one) (q s0)) by exact (mult_one (q s0)).
      exact (id_trans H1 (id_trans H2 (id_trans H3 (id_trans H4 H5)))).
    }
    assert (Hmo : Id (mult (p s0) one) (p s0)) by exact (mult_one (p s0)).
    assert (Hfull : Id (mult (p s0) (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one))
                       (minus (q s0) (p s0)))
      by exact (id_trans Hdist (id_trans (id_cong (fun x => minus x (mult (p s0) one)) Hcc)
                                         (id_cong (fun x => minus (q s0) x) Hmo))).
    assert (Hopp2 : Id (opp (minus (q s0) (p s0))) (minus (p s0) (q s0)))
      by exact (id_trans (opp_minus (q s0) (p s0)) (id_sym (plus_comm (p s0) (opp (q s0))))).
    exact (id_sym (id_trans Hoppl (id_trans (id_cong opp Hfull) Hopp2))).
  }
  rewrite Hrhs in Hrel.
  (* 6) mult_cancel_l（p > 0）：-log(q/p) = -(q/p - 1) ⟹ log(q/p) = q/p - 1 *)
  assert (Hopp_eq : Id (opp (log (mult (q s0) (inv_pos (p s0) (Hpp s0)))))
                       (opp (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)))
    by exact (mult_cancel_l (p s0)
                            (opp (log (mult (q s0) (inv_pos (p s0) (Hpp s0)))))
                            (opp (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one))
                            (Hpp s0) Hrel).
  assert (Hlog_eq : Id (log (mult (q s0) (inv_pos (p s0) (Hpp s0))))
                       (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)).
  {
    assert (H2 : Id (log (mult (q s0) (inv_pos (p s0) (Hpp s0))))
                    (opp (opp (log (mult (q s0) (inv_pos (p s0) (Hpp s0)))))))
      by exact (id_sym (double_neg (log (mult (q s0) (inv_pos (p s0) (Hpp s0)))))).
    assert (H3 : Id (opp (opp (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)))
                    (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one))
      by exact (double_neg (minus (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)).
    exact (id_trans H2 (id_trans (id_cong opp Hopp_eq) H3)).
  }
  (* 7) log_eq_linear：log(q/p) = q/p - 1 ⟹ q/p = 1 *)
  assert (Hratio_pos : lt zero (mult (q s0) (inv_pos (p s0) (Hpp s0))))
    by exact (mult_positive (q s0) (inv_pos (p s0) (Hpp s0)) (Hpq s0) (inv_pos_pos (p s0) (Hpp s0))).
  assert (Hratio_one : Id (mult (q s0) (inv_pos (p s0) (Hpp s0))) one)
    by exact (log_eq_linear (mult (q s0) (inv_pos (p s0) (Hpp s0))) Hratio_pos Hlog_eq).
  (* 8) q·(1/p) = 1 = p·(1/p) ⟹ q = p（mult_cancel_r 消 inv_pos p > 0） *)
  assert (Hpr : Id (mult (p s0) (inv_pos (p s0) (Hpp s0))) one)
    by exact (inv_pos_correct (p s0) (Hpp s0)).
  assert (Hqr : Id (mult (q s0) (inv_pos (p s0) (Hpp s0)))
                  (mult (p s0) (inv_pos (p s0) (Hpp s0))))
    by exact (id_trans Hratio_one (id_sym Hpr)).
  exact (id_sym (mult_cancel_r (inv_pos (p s0) (Hpp s0)) (q s0) (p s0) (inv_pos_pos (p s0) (Hpp s0)) Hqr)).
Qed.

(* Boltzmann 分布正性：p_b(s) > 0（逆元正 × 指数正） *)
Lemma boltzmann_dist_pos :
  forall s : S, lt zero (boltzmann_dist s).
Proof.
  intro s.
  unfold boltzmann_dist.
  apply mult_positive.
  - apply inv_pos_pos.
  - apply exp_neg_pos.
Qed.

(* 自由能最小化定理（原假设变量降级为定理）：
   F[p_b] ≤ F[p]——Boltzmann 分布是自由能全局极小值点。
   证明：F[p] = F[p_b] + D·KL(p||p_b)（free_energy_kl_decomp）
   + KL ≥ 0（gibbs_inequality）+ D > 0 保序。 *)
Theorem min_free_energy_is_boltzmann :
  forall p : S -> R,
    normalized p -> positive_dist p ->
    le (free_energy boltzmann_dist) (free_energy p).
Proof.
  intros p Hnp Hpp.
  (* 1. F[p] = F[p_b] + D·KL(p||p_b) *)
  assert (Hdecomp : Id (free_energy p)
                       (plus (free_energy boltzmann_dist)
                             (mult D (relative_entropy p boltzmann_dist))))
    by exact (free_energy_kl_decomp p Hnp).
  (* 2. KL ≥ 0（gibbs_inequality；boltzmann_dist 归一化 + 正性） *)
  assert (Hkl : le zero (relative_entropy p boltzmann_dist)).
  {
    apply (gibbs_inequality p boltzmann_dist).
    - exact Hnp.
    - exact Hpp.
    - exact (boltzmann_normalized).
    - intro s. exact (boltzmann_dist_pos s).
  }
  (* 3. D > 0 保序：0 ≤ KL ⟹ D·0 ≤ D·KL ⟹ 0 ≤ D·KL *)
  assert (Hdkl : le zero (mult D (relative_entropy p boltzmann_dist))).
  {
    assert (Hm : le (mult D zero) (mult D (relative_entropy p boltzmann_dist)))
      by exact (le_mult_compat_r D zero (relative_entropy p boltzmann_dist)
                                (lt_le_iff _ _ (inl D_pos)) Hkl).
    assert (Hz : Id (mult D zero) zero) by exact (mult_zero D).
    exact (le_id_l zero (mult D zero) (mult D (relative_entropy p boltzmann_dist)) (id_sym Hz) Hm).
  }
  (* 4. F[p_b] ≤ F[p_b] + D·KL = F[p]（le_plus_compat + le_refl + le_id_l 归约） *)
  assert (Hfin : le (free_energy boltzmann_dist)
                    (plus (free_energy boltzmann_dist) (mult D (relative_entropy p boltzmann_dist)))).
  {
    assert (Hplus : le (plus (free_energy boltzmann_dist) zero)
                       (plus (free_energy boltzmann_dist) (mult D (relative_entropy p boltzmann_dist))))
      by (apply (le_plus_compat (free_energy boltzmann_dist) (free_energy boltzmann_dist)
                                zero (mult D (relative_entropy p boltzmann_dist)));
          [apply le_refl | exact Hdkl]).
    assert (Hpz : Id (plus (free_energy boltzmann_dist) zero) (free_energy boltzmann_dist))
      by exact (plus_zero (free_energy boltzmann_dist)).
    exact (le_id_l (free_energy boltzmann_dist) (plus (free_energy boltzmann_dist) zero)
                   (plus (free_energy boltzmann_dist) (mult D (relative_entropy p boltzmann_dist)))
                   (id_sym Hpz) Hplus).
  }
  exact (le_id_r (free_energy boltzmann_dist) (plus (free_energy boltzmann_dist) (mult D (relative_entropy p boltzmann_dist))) (free_energy p) (id_sym Hdecomp) Hfin).
Qed.

(* 自由能最小点唯一性：若 p 达到与 Boltzmann 相同的自由能，则 p = p_b（逐点）。
   证明：F[p] = F[p_b] + D·KL 且 F[p] = F[p_b] ⟹ D·KL = 0 ⟹ KL = 0（D > 0
   mult_cancel_l）⟹ p = p_b（gibbs_equality）。 *)
Theorem free_energy_min_unique :
  forall p : S -> R,
    normalized p -> positive_dist p ->
    Id (free_energy p) (free_energy boltzmann_dist) ->
    forall s : S, Id (p s) (boltzmann_dist s).
Proof.
  intros p Hnp Hpp Hfeq s.
  (* 1. F[p] = F[p_b] + D·KL（恒等式） *)
  assert (Hdecomp : Id (free_energy p)
                       (plus (free_energy boltzmann_dist)
                             (mult D (relative_entropy p boltzmann_dist))))
    by exact (free_energy_kl_decomp p Hnp).
  (* 2. 由 F[p] = F[p_b] 得 D·KL = 0（消去 F[p_b]） *)
  assert (Hdkl0 : Id (mult D (relative_entropy p boltzmann_dist)) zero).
  {
    assert (H1 : Id (plus (free_energy boltzmann_dist)
                          (mult D (relative_entropy p boltzmann_dist)))
                   (free_energy p))
      by exact (id_sym Hdecomp).
    assert (H2 : Id (plus (free_energy boltzmann_dist)
                          (mult D (relative_entropy p boltzmann_dist)))
                   (free_energy boltzmann_dist))
      by exact (id_trans H1 Hfeq).
    (* plus FB KL = FB ⟹ KL = 0（plus_cancel 消去 FB） *)
    exact (plus_cancel_zero (free_energy boltzmann_dist) (mult D (relative_entropy p boltzmann_dist)) H2).
  }
  (* 3. D > 0 ⟹ KL = 0（mult_cancel_l） *)
  assert (Hkl0 : Id (relative_entropy p boltzmann_dist) zero).
  {
    (* mult D KL = zero 且 D > 0：需由 D·KL = 0 得 KL = 0
       （用 mult_cancel_l 的零版本：mult a b = mult a zero 且 a > 0 ⟹ b = zero） *)
    assert (Hcz : Id (mult D (relative_entropy p boltzmann_dist))
                     (mult D zero))
      by exact (id_trans Hdkl0 (id_sym (mult_zero D))).
    exact (mult_cancel_l D (relative_entropy p boltzmann_dist) zero D_pos Hcz).
  }
  (* 4. gibbs_equality：KL = 0 ⟹ p = p_b *)
  exact (gibbs_equality p boltzmann_dist Hnp Hpp (boltzmann_normalized) (fun t => boltzmann_dist_pos t) Hkl0 s).
Qed.

(* ============================================================ *)
(* 最大熵原理（统计力学第三支柱：自由能-熵对偶）               *)
(* ============================================================ *)
(* 前两条：自由能唯一极小（min_free_energy_is_boltzmann +       *)
(* free_energy_min_unique），KL 精确度量偏离（free_energy_kl_   *)
(* decomp）。此处补第三条：同能量约束下 Boltzmann 分布是熵最大 *)
(* 分布，且熵亏 = KL（偏离的熵学度量）。                       *)
(* ------------------------------------------------------------ *)

(* 信息熵：S[p] := -Σ_s p(s)·log p(s)（分布版，顶层 entropy 为 R→R 版） *)
Definition entropy_dist (p : S -> R) : R :=
  sum_over_S (fun s => mult (p s) (opp (log (p s)))).

(* 能量期望：⟨E⟩_p := Σ_s p(s)·base_loss(s)（最大熵的约束量） *)
Definition energy_expectation (p : S -> R) : R :=
  sum_over_S (fun s => mult (p s) (base_loss s)).

(* 熵分解：Σ p·log p = -S[p]（由 sum_over_S_ext + opp_mult_l + double_neg + sum_opp） *)
Lemma entropy_neg_sum :
  forall p : S -> R,
    Id (sum_over_S (fun s => mult (p s) (log (p s))))
       (opp (entropy_dist p)).
Proof.
  intro p.
  unfold entropy_dist.
  assert (Hpt : forall s, Id (mult (p s) (log (p s)))
                            (opp (mult (p s) (opp (log (p s)))))).
  {
    intro s.
    assert (H1 : Id (mult (p s) (opp (log (p s)))) (opp (mult (p s) (log (p s)))))
      by exact (opp_mult_l (p s) (log (p s))).
    assert (H2 : Id (opp (mult (p s) (opp (log (p s)))))
                    (opp (opp (mult (p s) (log (p s))))))
      by exact (id_cong opp H1).
    exact (id_sym (id_trans H2 (double_neg (mult (p s) (log (p s)))))).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p s) (log (p s))))
                   (sum_over_S (fun s => opp (mult (p s) (opp (log (p s)))))))
    by exact (sum_over_S_ext (fun s => mult (p s) (log (p s)))
                             (fun s => opp (mult (p s) (opp (log (p s))))) Hpt).
  rewrite Hext.
  assert (Hso : Id (sum_over_S (fun s => opp (mult (p s) (opp (log (p s))))))
                   (opp (sum_over_S (fun s => mult (p s) (opp (log (p s)))))))
    by exact (sum_opp (fun s => mult (p s) (opp (log (p s))))).
  exact Hso.
Qed.

(* 自由能-熵-能量恒等式：F[p] = ⟨E⟩_p - D·S[p] *)
Lemma free_energy_entropy :
  forall p : S -> R,
    Id (free_energy p)
       (plus (energy_expectation p) (mult D (opp (entropy_dist p)))).
Proof.
  intro p.
  unfold free_energy, energy_expectation.
  assert (Hneg : Id (sum_over_S (fun s => mult (p s) (log (p s))))
                    (opp (entropy_dist p)))
    by exact (entropy_neg_sum p).
  exact (id_cong (fun x => plus (sum_over_S (fun s => mult (p s) (base_loss s))) (mult D x)) Hneg).
Qed.

(* 熵差-相对熵恒等式：同能量约束（⟨E⟩_p = ⟨E⟩_b）下
   S[p_b] - S[p] = KL(p || p_b)。
   证明：F[p] = F[p_b] + D·KL（自由能恒等式）
   + 自由能-熵-能量恒等式（F = ⟨E⟩ - D·S）+ 同能量消去 + D > 0 消去。 *)
Theorem entropy_deficit_kl :
  forall p : S -> R,
    normalized p -> positive_dist p ->
    Id (energy_expectation p) (energy_expectation boltzmann_dist) ->
    Id (minus (entropy_dist boltzmann_dist) (entropy_dist p))
       (relative_entropy p boltzmann_dist).
Proof.
  intros p Hnp Hpp Henergy.
  (* 1. F[p] = F[p_b] + D·KL（自由能恒等式） *)
  assert (Hdecomp : Id (free_energy p)
                       (plus (free_energy boltzmann_dist)
                             (mult D (relative_entropy p boltzmann_dist))))
    by exact (free_energy_kl_decomp p Hnp).
  (* 2. 两侧换成 ⟨E⟩ - D·S 形式 *)
  assert (Hfe_p : Id (free_energy p)
                     (plus (energy_expectation p) (mult D (opp (entropy_dist p)))))
    by exact (free_energy_entropy p).
  assert (Hfe_b : Id (free_energy boltzmann_dist)
                     (plus (energy_expectation boltzmann_dist) (mult D (opp (entropy_dist boltzmann_dist)))))
    by exact (free_energy_entropy boltzmann_dist).
  (* 3. ⟨E⟩_p - D·S[p] = ⟨E⟩_b - D·S[p_b] + D·KL *)
  assert (Htot : Id (plus (energy_expectation p) (mult D (opp (entropy_dist p))))
                   (plus (plus (energy_expectation boltzmann_dist)
                               (mult D (opp (entropy_dist boltzmann_dist))))
                         (mult D (relative_entropy p boltzmann_dist)))).
  {
    assert (H1 : Id (plus (energy_expectation p) (mult D (opp (entropy_dist p))))
                    (plus (free_energy boltzmann_dist)
                          (mult D (relative_entropy p boltzmann_dist))))
      by exact (id_trans (id_sym Hfe_p) Hdecomp).
    assert (H2 : Id (plus (free_energy boltzmann_dist)
                          (mult D (relative_entropy p boltzmann_dist)))
                    (plus (plus (energy_expectation boltzmann_dist)
                                (mult D (opp (entropy_dist boltzmann_dist))))
                          (mult D (relative_entropy p boltzmann_dist))))
      by exact (id_cong (fun x => plus x (mult D (relative_entropy p boltzmann_dist))) Hfe_b).
    exact (id_trans H1 H2).
  }
  (* 4. 同能量消去 ⟨E⟩：-D·S[p] = -D·S[p_b] + D·KL *)
  assert (Hcancel : Id (mult D (opp (entropy_dist p)))
                       (plus (mult D (opp (entropy_dist boltzmann_dist)))
                             (mult D (relative_entropy p boltzmann_dist)))).
  {
    assert (Hsw : Id (plus (energy_expectation boltzmann_dist) (mult D (opp (entropy_dist p))))
                     (plus (energy_expectation p) (mult D (opp (entropy_dist p)))))
      by exact (id_cong (fun x => plus x (mult D (opp (entropy_dist p)))) (id_sym Henergy)).
    assert (H2 : Id (plus (energy_expectation boltzmann_dist) (mult D (opp (entropy_dist p))))
                    (plus (plus (energy_expectation boltzmann_dist)
                                (mult D (opp (entropy_dist boltzmann_dist))))
                          (mult D (relative_entropy p boltzmann_dist))))
      by exact (id_trans Hsw Htot).
    assert (Hre : Id (plus (plus (energy_expectation boltzmann_dist)
                                (mult D (opp (entropy_dist boltzmann_dist))))
                          (mult D (relative_entropy p boltzmann_dist)))
                    (plus (energy_expectation boltzmann_dist)
                          (plus (mult D (opp (entropy_dist boltzmann_dist)))
                                (mult D (relative_entropy p boltzmann_dist)))))
      by exact (id_sym (plus_assoc (energy_expectation boltzmann_dist)
                                     (mult D (opp (entropy_dist boltzmann_dist)))
                                     (mult D (relative_entropy p boltzmann_dist)))).
    assert (H2r : Id (plus (energy_expectation boltzmann_dist) (mult D (opp (entropy_dist p))))
                     (plus (energy_expectation boltzmann_dist)
                           (plus (mult D (opp (entropy_dist boltzmann_dist)))
                                 (mult D (relative_entropy p boltzmann_dist)))))
      by exact (id_trans H2 Hre).
    exact (plus_cancel_l (energy_expectation boltzmann_dist)
                         (mult D (opp (entropy_dist p)))
                         (plus (mult D (opp (entropy_dist boltzmann_dist)))
                               (mult D (relative_entropy p boltzmann_dist)))
                         H2r).
  }
  (* 5. 环消去：由 -D·S[p] = -D·S[p_b] + D·KL 且 D > 0 推出 S[p_b] - S[p] = KL *)
  exact (ring_d_cancel D (entropy_dist p) (entropy_dist boltzmann_dist)
                      (relative_entropy p boltzmann_dist) D_pos Hcancel).
Qed.

Theorem max_entropy_is_boltzmann :
  forall p : S -> R,
    normalized p -> positive_dist p ->
    Id (energy_expectation p) (energy_expectation boltzmann_dist) ->
    le (entropy_dist p) (entropy_dist boltzmann_dist).
Proof.
  intros p Hnp Hpp Henergy.
  (* 1. S[p_b] - S[p] = KL *)
  assert (Hdef : Id (minus (entropy_dist boltzmann_dist) (entropy_dist p))
                    (relative_entropy p boltzmann_dist))
    by exact (entropy_deficit_kl p Hnp Hpp Henergy).
  (* 2. KL ≥ 0（gibbs_inequality：p 与 p_b 均归一化正） *)
  assert (Hkl : le zero (relative_entropy p boltzmann_dist)).
  {
    apply (gibbs_inequality p boltzmann_dist).
    - exact Hnp.
    - exact Hpp.
    - exact (boltzmann_normalized).
    - intro s. exact (boltzmann_dist_pos s).
  }
  (* 3. 0 ≤ S[p_b] - S[p] ⟹ S[p] ≤ S[p_b]（le_minus_nonneg 的逆：用 minus_plus_cancel） *)
  assert (Hnonneg : le zero (minus (entropy_dist boltzmann_dist) (entropy_dist p)))
    by exact (le_id_r zero (relative_entropy p boltzmann_dist)
                     (minus (entropy_dist boltzmann_dist) (entropy_dist p))
                     (id_sym Hdef) Hkl).
  (* S[p] + (S[p_b] - S[p]) = S[p_b]（minus_plus_cancel）⟹ le S[p] S[p_b] *)
  assert (Hplus : Id (plus (entropy_dist p) (minus (entropy_dist boltzmann_dist) (entropy_dist p)))
                     (entropy_dist boltzmann_dist))
    by exact (minus_plus_cancel (entropy_dist p) (entropy_dist boltzmann_dist)).
  assert (Hle : le (entropy_dist p)
                   (plus (entropy_dist p) (minus (entropy_dist boltzmann_dist) (entropy_dist p))))
    by exact (le_plus_nonneg_r (entropy_dist p) (minus (entropy_dist boltzmann_dist) (entropy_dist p)) Hnonneg).
  exact (le_id_r (entropy_dist p)
                 (plus (entropy_dist p) (minus (entropy_dist boltzmann_dist) (entropy_dist p)))
                 (entropy_dist boltzmann_dist) Hplus Hle).
Qed.

(* ============================================================ *)
(* T2.2：温度-期望能量单调性（论文2 旗舰之二）                *)
(*   主定理：t1 < t2 ⟹ E_temp(t1) ≤ E_temp(t2)（温度升高 ⟹ 能量期望不降） *)
(*   方法：变分法——Gibbs 不等式交叉相加（无导数、无三分律）    *)
(*     KL(q‖p_β) ≥ 0 对 (q=p_{β2},β=β1) 与 (q=p_{β1},β=β2)    *)
(*     相加 ⟹ (β1−β2)(E1−E2) ≤ 0；β1−β2 > 0 ⟹ E1 ≤ E2        *)
(*   诚实接口假设（Real 层可实例化，非经典公理）：             *)
(*     sum_over_S_pos    —— 有限和正项和为正（Section Alignment 同款，有限和可实例化） *)
(*     inv_pos_lt_compat —— Real 层 real_inv_lt_contra（严格逆反序） *)
(*     lt_minus_nonneg   —— Real 层逐 eps 直构（Qlt_minus_iff 提升） *)
(* ============================================================ *)
Variable sum_over_S_pos : forall f : S -> R,
  (forall s : S, lt zero (f s)) -> lt zero (sum_over_S f).
Variable inv_pos_lt_compat : forall a b : R, forall Ha : lt zero a, forall Hb : lt zero b,
  lt a b -> lt (inv_pos b Hb) (inv_pos a Ha).
Variable lt_minus_nonneg : forall a b : R, lt a b -> lt zero (minus b a).

(* ---------- 自证代数引理（接口层，纯构造性） ---------- *)

(* 加法保序的逆：a+c ≤ b+c ⟹ a ≤ b（有序交换群消去，le_id 代数） *)
Lemma le_plus_cancel_l : forall a b c : R, le (plus a c) (plus b c) -> le a b.
Proof.
  intros a b c H.
  apply (le_id_l a (minus (plus a c) c)).
  - (* a == minus (plus a c) c *)
    unfold minus.
    exact (id_trans (id_trans (id_sym (plus_zero a))
              (id_sym (id_cong (fun x => plus a x) (plus_opp c))))
              (plus_assoc a c (opp c))).
  - apply (le_id_r (minus (plus a c) c) (minus (plus b c) c) b).
    + (* minus (plus b c) c == b *)
      unfold minus.
      exact (id_trans (id_trans (id_sym (plus_assoc b c (opp c)))
              (id_cong (fun x => plus b x) (plus_opp c)))
              (plus_zero b)).
    + unfold minus.
      apply (le_plus_compat (plus a c) (plus b c) (opp c) (opp c) H (le_refl (opp c))).
Qed.

(* 减法非负的逆：a − b ≤ 0 ⟹ a ≤ b *)
Lemma le_minus_nonneg_rev : forall a b : R, le (minus a b) zero -> le a b.
Proof.
  intros a b H.
  apply (le_id_l a (plus (minus a b) b)).
  - (* a == plus (minus a b) b *)
    unfold minus.
    exact (id_trans (id_sym (plus_zero a))
           (id_trans (id_sym (id_cong (fun x => plus a x)
                 (id_trans (plus_comm (opp b) b) (plus_opp b))))
                 (plus_assoc a (opp b) b))).
  - apply (le_id_r (plus (minus a b) b) (plus zero b) b).
    + exact (id_trans (plus_comm zero b) (plus_zero b)).
    + apply (le_plus_compat (minus a b) zero b b H (le_refl b)).
Qed.

(* 乘正数消去：c > 0 且 a·c ≤ 0 ⟹ a ≤ 0（a == (a·c)·inv c） *)
Lemma le_mult_pos_cancel : forall a c : R, lt zero c -> le (mult a c) zero -> le a zero.
Proof.
  intros a c Hc H.
  apply (le_id_l a (mult (mult a c) (inv_pos c Hc))).
  - (* a == mult (mult a c) (inv_pos c Hc) *)
    exact (id_trans (id_sym (mult_one a))
           (id_trans (id_cong (fun x => mult a x) (id_sym (inv_pos_correct c Hc)))
                     (mult_assoc a c (inv_pos c Hc)))).
  - apply (le_id_r (mult (mult a c) (inv_pos c Hc)) (mult zero (inv_pos c Hc)) zero).
    + exact (id_trans (mult_comm zero (inv_pos c Hc)) (mult_zero (inv_pos c Hc))).
    + apply (le_mult_compat_weak (mult a c) zero (inv_pos c Hc)).
      * apply lt_le_iff. left. apply inv_pos_pos.
      * exact H.
Qed.

(* 乘法对减法的右分配：mult (minus a b) c == minus (mult a c) (mult b c) *)
Lemma mult_minus_distr_r : forall a b c : R,
  Id (mult (minus a b) c) (minus (mult a c) (mult b c)).
Proof.
  intros a b c.
  unfold minus.
  apply (id_trans (mult_comm (plus a (opp b)) c)
         (id_trans (distrib c a (opp b))
         (id_trans (id_cong (fun x => plus x (mult c (opp b))) (mult_comm c a))
         (id_trans (id_cong (fun x => plus (mult a c) x) (mult_comm c (opp b)))
                   (id_cong (fun x => plus (mult a c) x) (opp_mult_r b c)))))).
Qed.

(* ---------- T2.2 温度参数化定义 ---------- *)

(* 温度参数化配分函数（诚实接口：温度 t 的配分 Σ_s e^{-e_s/t}） *)
Variable Z_temp : R -> R.
Variable Z_temp_spec : forall t : R, forall Ht : lt zero t,
  Id (Z_temp t) (sum_over_S (fun s => exp_neg (mult (inv_pos t Ht) (base_loss s)))).

Lemma Z_temp_pos : forall t : R, forall Ht : lt zero t,
  lt zero (Z_temp t).
Proof.
  intros t Ht.
  apply (lt_id_r zero (sum_over_S (fun s => exp_neg (mult (inv_pos t Ht) (base_loss s)))) (Z_temp t)).
  - exact (id_sym (Z_temp_spec t Ht)).
  - apply sum_over_S_pos.
    intro s.
    apply exp_neg_pos.
Qed.

(* 温度参数化 Boltzmann 分布与期望能量 *)
Definition boltzmann_dist_temp (t : R) (Ht : lt zero t) : S -> R :=
  fun s => mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))).

Definition energy_exp_temp (t : R) (Ht : lt zero t) : R :=
  sum_over_S (fun s => mult (boltzmann_dist_temp t Ht s) (base_loss s)).

Theorem boltzmann_dist_temp_normalized : forall t : R, forall Ht : lt zero t,
  Id (sum_over_S (boltzmann_dist_temp t Ht)) one.
Proof.
  intros t Ht.
  unfold boltzmann_dist_temp.
  assert (Hlin : Id (sum_over_S (fun s => mult (inv_pos (Z_temp t) (Z_temp_pos t Ht))
                                  (exp_neg (mult (inv_pos t Ht) (base_loss s)))))
                   (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht))
                         (sum_over_S (fun s => exp_neg (mult (inv_pos t Ht) (base_loss s))))))
    by exact (sum_over_S_linear (inv_pos (Z_temp t) (Z_temp_pos t Ht))
               (fun s => exp_neg (mult (inv_pos t Ht) (base_loss s)))).
  assert (HZ : Id (sum_over_S (fun s => exp_neg (mult (inv_pos t Ht) (base_loss s)))) (Z_temp t))
    by exact (id_sym (Z_temp_spec t Ht)).
  assert (Hcc : Id (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (Z_temp t)) one)
    by exact (id_trans (mult_comm (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (Z_temp t))
                       (inv_pos_correct (Z_temp t) (Z_temp_pos t Ht))).
  exact (id_trans Hlin (id_trans (id_cong (fun x => mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) x) HZ) Hcc)).
Qed.

Lemma boltzmann_dist_temp_pos : forall t : R, forall Ht : lt zero t, forall s : S,
  lt zero (boltzmann_dist_temp t Ht s).
Proof.
  intros t Ht s. unfold boltzmann_dist_temp.
  apply mult_positive.
  - apply inv_pos_pos.
  - apply exp_neg_pos.
Qed.

(* log p_β(s) == −log Z − β·e_s（温度版对数分解） *)
Theorem boltzmann_log_temp_decomp : forall t : R, forall Ht : lt zero t, forall s : S,
  Id (log (boltzmann_dist_temp t Ht s))
     (plus (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s)))).
Proof.
  intros t Ht s. unfold boltzmann_dist_temp.
  assert (Hpos1 : lt zero (inv_pos (Z_temp t) (Z_temp_pos t Ht)))
    by exact (inv_pos_pos (Z_temp t) (Z_temp_pos t Ht)).
  assert (Hpos2 : lt zero (exp_neg (mult (inv_pos t Ht) (base_loss s))))
    by exact (exp_neg_pos (mult (inv_pos t Ht) (base_loss s))).
  assert (Hlm : Id (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht))
                              (exp_neg (mult (inv_pos t Ht) (base_loss s)))))
                  (plus (log (inv_pos (Z_temp t) (Z_temp_pos t Ht)))
                        (log (exp_neg (mult (inv_pos t Ht) (base_loss s))))))
    by exact (log_mult (inv_pos (Z_temp t) (Z_temp_pos t Ht))
                       (exp_neg (mult (inv_pos t Ht) (base_loss s))) Hpos1 Hpos2).
  rewrite Hlm.
  assert (Hli : Id (log (inv_pos (Z_temp t) (Z_temp_pos t Ht))) (opp (log (Z_temp t))))
    by exact (log_inv_one_inv (Z_temp t) (Z_temp_pos t Ht)).
  rewrite Hli.
  assert (Hle : Id (log (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                  (opp (mult (inv_pos t Ht) (base_loss s))))
    by exact (log_exp_neg (mult (inv_pos t Ht) (base_loss s))).
  rewrite Hle.
  reflexivity.
Qed.

(* 熵显式公式：H(p_β) == β·E(p_β) + log Z（β := inv t） *)
Theorem entropy_temp_explicit : forall t : R, forall Ht : lt zero t,
  Id (entropy_dist (boltzmann_dist_temp t Ht))
     (plus (mult (inv_pos t Ht) (energy_exp_temp t Ht)) (log (Z_temp t))).
Proof.
  intros t Ht.
  unfold entropy_dist, energy_exp_temp, boltzmann_dist_temp.
  (* 逐点：p·(−log p) == p·(βe) + p·logZ *)
  assert (Hpt : forall s : S,
    Id (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
             (opp (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
       (plus (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                   (mult (inv_pos t Ht) (base_loss s)))
             (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                   (log (Z_temp t))))).
  { intro s.
    assert (Hlog : Id (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht))
                                 (exp_neg (mult (inv_pos t Ht) (base_loss s)))))
                      (plus (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s)))))
      by exact (boltzmann_log_temp_decomp t Ht s).
    (* −log p == logZ + βe *)
    assert (Hopp : Id (opp (plus (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s)))))
                      (plus (log (Z_temp t)) (mult (inv_pos t Ht) (base_loss s)))).
    { exact (id_trans (opp_plus (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s))))
             (id_trans (id_cong (fun x => plus x (opp (opp (mult (inv_pos t Ht) (base_loss s)))))
                                (double_neg (log (Z_temp t))))
                       (id_cong (fun x => plus (log (Z_temp t)) x)
                                (double_neg (mult (inv_pos t Ht) (base_loss s)))))). }
    (* p·(−log p) == p·(logZ + βe) == p·(βe) + p·logZ *)
    assert (Hcomm : Id (plus (log (Z_temp t)) (mult (inv_pos t Ht) (base_loss s)))
                       (plus (mult (inv_pos t Ht) (base_loss s)) (log (Z_temp t))))
      by exact (plus_comm (log (Z_temp t)) (mult (inv_pos t Ht) (base_loss s))).
    exact (id_trans (id_cong (fun x => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (opp x)) Hlog)
           (id_trans (id_cong (fun x => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) x) Hopp)
           (id_trans (id_cong (fun x => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) x) Hcomm)
                     (distrib (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                              (mult (inv_pos t Ht) (base_loss s)) (log (Z_temp t)))))). }
  (* Σ 线性：Σ p·(βe) + Σ p·logZ（手动链，无 rewrite） *)
  assert (H1 : Id (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                                           (opp (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))))
                   (sum_over_S (fun s => plus (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
                                              (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t))))))
    by exact (sum_over_S_ext (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))
                                             (opp (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
                             (fun s => plus (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
                                            (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t))))
                             Hpt).
  assert (Hadd : Id (sum_over_S (fun s => plus (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
                                              (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t)))))
                    (plus (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s))))
                          (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t))))))
    by exact (sum_over_S_add (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
                             (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t)))).
  (* Σ p·(βe) == β·Σ p·e *)
  assert (Hlin1 : Id (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s))))
                     (mult (inv_pos t Ht) (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (base_loss s))))).
  { assert (Hpt2 : forall s : S,
      Id (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
         (mult (inv_pos t Ht) (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (base_loss s)))).
    { intro s.
      apply (id_trans (mult_comm (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (mult (inv_pos t Ht) (base_loss s)))
             (id_trans (id_sym (mult_assoc (inv_pos t Ht) (base_loss s) (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))
                       (id_cong (fun x => mult (inv_pos t Ht) x)
                                (mult_comm (base_loss s) (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))). }
    exact (id_trans (sum_over_S_ext _ _ Hpt2)
           (sum_over_S_linear (inv_pos t Ht)
             (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (base_loss s)))). }
  (* Σ p·logZ == logZ·Σ p == logZ *)
  assert (Hlin2 : Id (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t))))
                     (log (Z_temp t))).
  { assert (Hpt3 : forall s : S,
      Id (mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t)))
         (mult (log (Z_temp t)) (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))
    by (intro s; apply mult_comm).
    exact (id_trans (sum_over_S_ext _ _ Hpt3)
           (id_trans (sum_over_S_linear (log (Z_temp t)) (boltzmann_dist_temp t Ht))
           (id_trans (id_cong (fun x => mult (log (Z_temp t)) x) (boltzmann_dist_temp_normalized t Ht))
                     (mult_one (log (Z_temp t)))))). }
  exact (id_trans H1 (id_trans Hadd
         (id_trans (id_cong (fun x => plus x (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (log (Z_temp t))))) Hlin1)
                   (id_cong (fun x => plus (mult (inv_pos t Ht) (sum_over_S (fun s => mult (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))) (base_loss s)))) x) Hlin2)))).
Qed.

(* ---------- T2.2 变分法主体 ---------- *)

(* 相对熵对 Boltzmann 的显式分解：KL(q‖p_β) == −H(q) + β·E(q) + log Z *)
Theorem relative_entropy_temp_decomp : forall t : R, forall Ht : lt zero t, forall q : S -> R,
  normalized q ->
  Id (relative_entropy q (boltzmann_dist_temp t Ht))
     (plus (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q)))
           (log (Z_temp t))).
Proof.
  intros t Ht q Hnq.
  unfold relative_entropy, entropy_dist, energy_expectation, boltzmann_dist_temp.
  (* 逐点：q·(log q − log p) == q·log q − q·log p *)
  assert (Hpt : forall s : S,
    Id (mult (q s) (minus (log (q s)) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
       (minus (mult (q s) (log (q s)))
              (mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))).
  { intro s. apply mult_minus_distr_l. }
  (* Σ q·log q == −H(q) *)
  assert (Hq1 : Id (sum_over_S (fun s => mult (q s) (log (q s)))) (opp (entropy_dist q))).
  { unfold entropy_dist.
    apply entropy_neg_sum. }
  (* Σ q·log p == −β·E(q) − log Z（手动链） *)
  assert (Hq2 : Id (sum_over_S (fun s => mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
                   (plus (opp (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))))
                         (opp (log (Z_temp t))))).
  { (* 逐点：q·log p == opp(q·logZ) + opp(q·βe) *)
    assert (Hpt2 : forall s : S,
      Id (mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))
         (plus (opp (mult (q s) (log (Z_temp t))))
               (opp (mult (q s) (mult (inv_pos t Ht) (base_loss s)))))).
    { intro s.
      assert (Hlog : Id (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))
                        (plus (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s)))))
        by exact (boltzmann_log_temp_decomp t Ht s).
      exact (id_trans (id_cong (fun x => mult (q s) x) Hlog)
             (id_trans (id_cong (fun x => mult (q s) x)
                                (plus_comm (opp (log (Z_temp t))) (opp (mult (inv_pos t Ht) (base_loss s)))))
             (id_trans (distrib (q s) (opp (mult (inv_pos t Ht) (base_loss s))) (opp (log (Z_temp t))))
             (id_trans (id_cong (fun x => plus x (mult (q s) (opp (log (Z_temp t)))))
                                (opp_mult_l (q s) (mult (inv_pos t Ht) (base_loss s))))
             (id_trans (id_cong (fun x => plus (opp (mult (q s) (mult (inv_pos t Ht) (base_loss s)))) x)
                                (opp_mult_l (q s) (log (Z_temp t))))
                       (plus_comm (opp (mult (q s) (mult (inv_pos t Ht) (base_loss s))))
                                  (opp (mult (q s) (log (Z_temp t)))))))))). }
    assert (H1 : Id (sum_over_S (fun s => mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
                    (sum_over_S (fun s => plus (opp (mult (q s) (log (Z_temp t))))
                                               (opp (mult (q s) (mult (inv_pos t Ht) (base_loss s)))))))
      by exact (sum_over_S_ext _ _ Hpt2).
    assert (Hadd : Id (sum_over_S (fun s => plus (opp (mult (q s) (log (Z_temp t))))
                                                 (opp (mult (q s) (mult (inv_pos t Ht) (base_loss s))))))
                      (plus (sum_over_S (fun s => opp (mult (q s) (log (Z_temp t)))))
                            (sum_over_S (fun s => opp (mult (q s) (mult (inv_pos t Ht) (base_loss s)))))))
      by exact (sum_over_S_add (fun s => opp (mult (q s) (log (Z_temp t))))
                               (fun s => opp (mult (q s) (mult (inv_pos t Ht) (base_loss s))))).
    (* Σ q·logZ == logZ（常数提取 + 归一化） *)
    assert (Hs1 : Id (sum_over_S (fun s => mult (q s) (log (Z_temp t)))) (log (Z_temp t))).
    { assert (Hc : forall s : S, Id (mult (q s) (log (Z_temp t))) (mult (log (Z_temp t)) (q s)))
        by (intro s; apply mult_comm).
      exact (id_trans (sum_over_S_ext _ _ Hc)
             (id_trans (sum_over_S_linear (log (Z_temp t)) q)
                       (id_trans (id_cong (fun x => mult (log (Z_temp t)) x) Hnq)
                                 (mult_one (log (Z_temp t)))))). }
    (* Σ q·(βe) == β·Σ q·e *)
    assert (Hs2 : Id (sum_over_S (fun s => mult (q s) (mult (inv_pos t Ht) (base_loss s))))
                     (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s))))).
    { assert (Hc2 : forall s : S, Id (mult (q s) (mult (inv_pos t Ht) (base_loss s)))
                                     (mult (inv_pos t Ht) (mult (q s) (base_loss s)))).
      { intro s.
        apply (id_trans (mult_comm (q s) (mult (inv_pos t Ht) (base_loss s)))
               (id_trans (id_sym (mult_assoc (inv_pos t Ht) (base_loss s) (q s)))
                         (id_cong (fun x => mult (inv_pos t Ht) x) (mult_comm (base_loss s) (q s))))). }
      exact (id_trans (sum_over_S_ext _ _ Hc2)
             (sum_over_S_linear (inv_pos t Ht) (fun s => mult (q s) (base_loss s)))). }
    exact (id_trans H1 (id_trans Hadd
           (id_trans (id_cong (fun x => plus x (sum_over_S (fun s => opp (mult (q s) (mult (inv_pos t Ht) (base_loss s))))))
                              (sum_opp (fun s => mult (q s) (log (Z_temp t)))))
           (id_trans (id_cong (fun x => plus (opp (sum_over_S (fun s => mult (q s) (log (Z_temp t))))) x)
                              (sum_opp (fun s => mult (q s) (mult (inv_pos t Ht) (base_loss s)))))
           (id_trans (id_cong (fun x => plus (opp x) (opp (sum_over_S (fun s => mult (q s) (mult (inv_pos t Ht) (base_loss s)))))) Hs1)
           (id_trans (id_cong (fun x => plus (opp (log (Z_temp t))) (opp x)) Hs2)
                     (plus_comm (opp (log (Z_temp t)))
                                (opp (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))))))))))). }
  (* 组装：minus (Σ q·log q) (Σ q·log p) == −H + βE + logZ（手动链） *)
  assert (Hopp : Id (opp (plus (opp (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))))
                                 (opp (log (Z_temp t)))))
                    (plus (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s))))
                          (log (Z_temp t)))).
  { exact (id_trans (opp_plus (opp (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))))
                              (opp (log (Z_temp t))))
           (id_trans (id_cong (fun x => plus x (opp (opp (log (Z_temp t)))))
                              (double_neg (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s))))))
                     (id_cong (fun x => plus (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))) x)
                              (double_neg (log (Z_temp t)))))). }
  assert (Hfin : Id (minus (sum_over_S (fun s => mult (q s) (log (q s))))
                           (sum_over_S (fun s => mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))))
                    (plus (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s)))))
                          (log (Z_temp t)))).
  { unfold minus.
    exact (id_trans (id_cong (fun x => plus x (opp (sum_over_S (fun s => mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))))) Hq1)
           (id_trans (id_cong (fun x => plus (opp (entropy_dist q)) (opp x)) Hq2)
           (id_trans (id_cong (fun x => plus (opp (entropy_dist q)) x) Hopp)
                     (plus_assoc (opp (entropy_dist q))
                                         (mult (inv_pos t Ht) (sum_over_S (fun s => mult (q s) (base_loss s))))
                                         (log (Z_temp t)))))). }
  assert (Hstep : Id (sum_over_S (fun s => mult (q s) (minus (log (q s)) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s))))))))
                     (sum_over_S (fun s => minus (mult (q s) (log (q s)))
                                                 (mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))))
    by exact (sum_over_S_ext _ _ Hpt).
  exact (id_trans Hstep
         (id_trans (sum_over_S_minus (fun s => mult (q s) (log (q s)))
                                     (fun s => mult (q s) (log (mult (inv_pos (Z_temp t) (Z_temp_pos t Ht)) (exp_neg (mult (inv_pos t Ht) (base_loss s)))))))
                   Hfin)).
Qed.

(* 变分界：任意归一化正分布 q 的熵-能量组合 ≤ log Z（Gibbs 不等式展开） *)
Theorem variational_temp_bound : forall t : R, forall Ht : lt zero t, forall q : S -> R,
  normalized q -> positive_dist q ->
  le (minus (entropy_dist q) (mult (inv_pos t Ht) (energy_expectation q)))
     (log (Z_temp t)).
Proof.
  intros t Ht q Hnq Hpq.
  assert (Hkl : le zero (relative_entropy q (boltzmann_dist_temp t Ht)))
    by (apply (gibbs_inequality q (boltzmann_dist_temp t Ht) Hnq Hpq
               (boltzmann_dist_temp_normalized t Ht) (boltzmann_dist_temp_pos t Ht))).
  assert (Hrel : Id (relative_entropy q (boltzmann_dist_temp t Ht))
                    (plus (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q))) (log (Z_temp t))))
    by (apply (relative_entropy_temp_decomp t Ht q Hnq)).
  rewrite Hrel in Hkl.
  (* 移项 1：0 ≤ −H + βE + logZ ⟹ H ≤ βE + logZ *)
  assert (Hstep1 : le (entropy_dist q) (plus (mult (inv_pos t Ht) (energy_expectation q)) (log (Z_temp t)))).
  { apply (le_id_l (entropy_dist q) (plus (entropy_dist q) zero)).
    - exact (id_sym (plus_zero (entropy_dist q))).
    - apply (le_id_r (plus (entropy_dist q) zero)
             (plus (entropy_dist q) (plus (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q))) (log (Z_temp t))))
             (plus (mult (inv_pos t Ht) (energy_expectation q)) (log (Z_temp t)))).
      + (* H + (−H + βE + logZ) == βE + logZ *)
        apply (id_trans (plus_assoc (entropy_dist q)
                                    (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q)))
                                    (log (Z_temp t)))
               (id_trans (id_cong (fun x => plus x (log (Z_temp t)))
                                  (plus_assoc (entropy_dist q) (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q))))
               (id_trans (id_cong (fun x => plus x (log (Z_temp t)))
                                  (id_cong (fun x => plus x (mult (inv_pos t Ht) (energy_expectation q)))
                                           (plus_opp (entropy_dist q))))
               (id_cong (fun x => plus x (log (Z_temp t)))
                        (id_trans (plus_comm zero (mult (inv_pos t Ht) (energy_expectation q)))
                                  (plus_zero (mult (inv_pos t Ht) (energy_expectation q)))))))).
      + apply (le_plus_compat (entropy_dist q) (entropy_dist q) zero
               (plus (plus (opp (entropy_dist q)) (mult (inv_pos t Ht) (energy_expectation q))) (log (Z_temp t)))
               (le_refl (entropy_dist q)) Hkl). }
  (* 移项 2：H ≤ βE + logZ ⟹ H − βE ≤ logZ *)
  apply (le_id_r (plus (entropy_dist q) (opp (mult (inv_pos t Ht) (energy_expectation q))))
         (plus (plus (mult (inv_pos t Ht) (energy_expectation q)) (log (Z_temp t))) (opp (mult (inv_pos t Ht) (energy_expectation q))))
         (log (Z_temp t))).
  - (* (βE + logZ) − βE == logZ *)
    apply (id_trans (id_sym (plus_assoc (mult (inv_pos t Ht) (energy_expectation q)) (log (Z_temp t)) (opp (mult (inv_pos t Ht) (energy_expectation q)))))
           (id_trans (id_cong (fun x => plus (mult (inv_pos t Ht) (energy_expectation q)) x)
                              (plus_comm (log (Z_temp t)) (opp (mult (inv_pos t Ht) (energy_expectation q)))))
           (id_trans (plus_assoc (mult (inv_pos t Ht) (energy_expectation q)) (opp (mult (inv_pos t Ht) (energy_expectation q))) (log (Z_temp t)))
           (id_trans (id_cong (fun x => plus x (log (Z_temp t))) (plus_opp (mult (inv_pos t Ht) (energy_expectation q))))
           (id_trans (plus_comm zero (log (Z_temp t))) (plus_zero (log (Z_temp t)))))))).
  - apply (le_plus_compat (entropy_dist q) (plus (mult (inv_pos t Ht) (energy_expectation q)) (log (Z_temp t)))
                           (opp (mult (inv_pos t Ht) (energy_expectation q)))
                           (opp (mult (inv_pos t Ht) (energy_expectation q)))
                           Hstep1 (le_refl (opp (mult (inv_pos t Ht) (energy_expectation q))))).
Qed.

(* ============ T2.2 主定理：温度-期望能量单调性 ============ *)
Theorem energy_exp_temp_mono : forall t1 t2 : R, forall Ht1 : lt zero t1, forall Ht2 : lt zero t2,
  lt t1 t2 -> le (energy_exp_temp t1 Ht1) (energy_exp_temp t2 Ht2).
Proof.
  intros t1 t2 Ht1 Ht2 Ht12.
  set (b1 := inv_pos t1 Ht1). set (b2 := inv_pos t2 Ht2).
  set (E1 := energy_exp_temp t1 Ht1). set (E2 := energy_exp_temp t2 Ht2).
  set (H1 := entropy_dist (boltzmann_dist_temp t1 Ht1)). set (H2 := entropy_dist (boltzmann_dist_temp t2 Ht2)).
  set (Z1 := Z_temp t1). set (Z2 := Z_temp t2).
  (* β2 < β1（inv 严格反序：t1 < t2 ⟹ 1/t2 < 1/t1） *)
  assert (Hb : lt b2 b1) by (unfold b1, b2; apply (inv_pos_lt_compat t1 t2 Ht1 Ht2 Ht12)).
  assert (Hbpos : lt zero (minus b1 b2)) by (unfold b1, b2; apply (lt_minus_nonneg b2 b1 Hb)).
  (* 变分 bound ×2 *)
  assert (Hv1 : le (minus H2 (mult b1 E2)) (log Z1)).
  { unfold H2, E2, Z1, b1.
    apply (variational_temp_bound t1 Ht1 (boltzmann_dist_temp t2 Ht2)).
    - apply boltzmann_dist_temp_normalized.
    - intro s. apply boltzmann_dist_temp_pos. }
  assert (Hv2 : le (minus H1 (mult b2 E1)) (log Z2)).
  { unfold H1, E1, Z2, b2.
    apply (variational_temp_bound t2 Ht2 (boltzmann_dist_temp t1 Ht1)).
    - apply boltzmann_dist_temp_normalized.
    - intro s. apply boltzmann_dist_temp_pos. }
  (* 熵显式代入（手动替换，无 rewrite） *)
  assert (Hex1 : Id H1 (plus (mult b1 E1) (log Z1))).
  { unfold H1, b1, E1, Z1. apply entropy_temp_explicit. }
  assert (Hex2 : Id H2 (plus (mult b2 E2) (log Z2))).
  { unfold H2, b2, E2, Z2. apply entropy_temp_explicit. }
  assert (Hv1' : le (minus (plus (mult b2 E2) (log Z2)) (mult b1 E2)) (log Z1)).
  { apply (le_id_l (minus (plus (mult b2 E2) (log Z2)) (mult b1 E2)) (minus H2 (mult b1 E2)) (log Z1)).
    - exact (id_cong (fun x => minus x (mult b1 E2)) (id_sym Hex2)).
    - exact Hv1. }
  assert (Hv2' : le (minus (plus (mult b1 E1) (log Z1)) (mult b2 E1)) (log Z2)).
  { apply (le_id_l (minus (plus (mult b1 E1) (log Z1)) (mult b2 E1)) (minus H1 (mult b2 E1)) (log Z2)).
    - exact (id_cong (fun x => minus x (mult b2 E1)) (id_sym Hex1)).
    - exact Hv2. }
  (* minus 内化简：minus (plus (mult b2 E2) (log Z2)) (mult b1 E2) == plus (mult (minus b2 b1) E2) (log Z2) *)
  assert (Hm1 : Id (minus (plus (mult b2 E2) (log Z2)) (mult b1 E2))
                   (plus (mult (minus b2 b1) E2) (log Z2))).
  { unfold minus.
    apply (id_trans (id_sym (plus_assoc (mult b2 E2) (log Z2) (opp (mult b1 E2))))
           (id_trans (id_cong (fun x => plus (mult b2 E2) x)
                              (plus_comm (log Z2) (opp (mult b1 E2))))
           (id_trans (plus_assoc (mult b2 E2) (opp (mult b1 E2)) (log Z2))
                     (id_sym (id_cong (fun x => plus x (log Z2))
                              (mult_minus_distr_r b2 b1 E2)))))). }
  assert (Hm2 : Id (minus (plus (mult b1 E1) (log Z1)) (mult b2 E1))
                   (plus (mult (minus b1 b2) E1) (log Z1))).
  { unfold minus.
    apply (id_trans (id_sym (plus_assoc (mult b1 E1) (log Z1) (opp (mult b2 E1))))
           (id_trans (id_cong (fun x => plus (mult b1 E1) x)
                              (plus_comm (log Z1) (opp (mult b2 E1))))
           (id_trans (plus_assoc (mult b1 E1) (opp (mult b2 E1)) (log Z1))
                     (id_sym (id_cong (fun x => plus x (log Z1))
                              (mult_minus_distr_r b1 b2 E1)))))). }
  assert (Hv1'' : le (plus (mult (minus b2 b1) E2) (log Z2)) (log Z1)).
  { apply (le_id_l (plus (mult (minus b2 b1) E2) (log Z2))
                   (minus (plus (mult b2 E2) (log Z2)) (mult b1 E2)) (log Z1)).
    - exact (id_sym Hm1).
    - exact Hv1'. }
  assert (Hv2'' : le (plus (mult (minus b1 b2) E1) (log Z1)) (log Z2)).
  { apply (le_id_l (plus (mult (minus b1 b2) E1) (log Z1))
                   (minus (plus (mult b1 E1) (log Z1)) (mult b2 E1)) (log Z2)).
    - exact (id_sym Hm2).
    - exact Hv2'. }
  (* 移项：le (plus X (log Z2)) (log Z1) ⟹ le X (minus (log Z1) (log Z2)) *)
  assert (Hshift1 : le (mult (minus b2 b1) E2) (minus (log Z1) (log Z2))).
  { apply (le_id_l (mult (minus b2 b1) E2) (plus (plus (mult (minus b2 b1) E2) (log Z2)) (opp (log Z2)))).
    - exact (id_trans (id_sym (plus_zero (mult (minus b2 b1) E2)))
             (id_sym (id_trans (id_sym (plus_assoc (mult (minus b2 b1) E2) (log Z2) (opp (log Z2))))
                     (id_cong (fun x => plus (mult (minus b2 b1) E2) x) (plus_opp (log Z2)))))).
    - apply (le_plus_compat (plus (mult (minus b2 b1) E2) (log Z2)) (log Z1)
                             (opp (log Z2)) (opp (log Z2)) Hv1'' (le_refl (opp (log Z2)))). }
  assert (Hshift2 : le (mult (minus b1 b2) E1) (minus (log Z2) (log Z1))).
  { apply (le_id_l (mult (minus b1 b2) E1) (plus (plus (mult (minus b1 b2) E1) (log Z1)) (opp (log Z1)))).
    - exact (id_trans (id_sym (plus_zero (mult (minus b1 b2) E1)))
             (id_sym (id_trans (id_sym (plus_assoc (mult (minus b1 b2) E1) (log Z1) (opp (log Z1))))
                     (id_cong (fun x => plus (mult (minus b1 b2) E1) x) (plus_opp (log Z1)))))).
    - apply (le_plus_compat (plus (mult (minus b1 b2) E1) (log Z1)) (log Z2)
                             (opp (log Z1)) (opp (log Z1)) Hv2'' (le_refl (opp (log Z1)))). }
  (* 相加 *)
  assert (Hsum : le (plus (mult (minus b2 b1) E2) (mult (minus b1 b2) E1))
                   (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1)))).
  { apply (le_plus_compat (mult (minus b2 b1) E2) (minus (log Z1) (log Z2))
                           (mult (minus b1 b2) E1) (minus (log Z2) (log Z1)) Hshift1 Hshift2). }
  (* RHS == zero *)
  assert (Hz : Id (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1))) zero).
  { unfold minus.
    apply (id_trans (id_sym (plus_assoc (log Z1) (opp (log Z2)) (plus (log Z2) (opp (log Z1)))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (plus_assoc (opp (log Z2)) (log Z2) (opp (log Z1))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (id_cong (fun x => plus x (opp (log Z1)))
                                       (id_trans (plus_comm (opp (log Z2)) (log Z2)) (plus_opp (log Z2)))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (id_trans (plus_comm zero (opp (log Z1))) (plus_zero (opp (log Z1)))))
                     (plus_opp (log Z1)))))). }
  (* LHS == mult (minus b1 b2) (minus E1 E2) *)
  assert (Hoppm : Id (minus b2 b1) (opp (minus b1 b2))).
  { unfold minus.
    exact (id_sym (id_trans (opp_plus b1 (opp b2))
                   (id_trans (id_cong (fun x => plus (opp b1) x) (double_neg b2))
                             (plus_comm (opp b1) b2)))). }
  assert (Hlhs : Id (plus (mult (minus b2 b1) E2) (mult (minus b1 b2) E1))
                    (mult (minus b1 b2) (minus E1 E2))).
  { apply (id_trans (id_cong (fun x => plus (mult x E2) (mult (minus b1 b2) E1)) Hoppm)
           (id_trans (id_cong (fun x => plus x (mult (minus b1 b2) E1))
                              (opp_mult_r (minus b1 b2) E2))
           (id_trans (id_cong (fun x => plus x (mult (minus b1 b2) E1))
                              (id_sym (opp_mult_l (minus b1 b2) E2)))
           (id_trans (id_sym (distrib (minus b1 b2) (opp E2) E1))
                     (id_cong (fun x => mult (minus b1 b2) x) (plus_comm (opp E2) E1)))))). }
  (* 组装：le (mult (minus b1 b2) (minus E1 E2)) zero *)
  assert (Hmain : le (mult (minus b1 b2) (minus E1 E2)) zero).
  { apply (le_id_l (mult (minus b1 b2) (minus E1 E2))
                   (plus (mult (minus b2 b1) E2) (mult (minus b1 b2) E1))).
    - exact (id_sym Hlhs).
    - apply (le_id_r (plus (mult (minus b2 b1) E2) (mult (minus b1 b2) E1))
                     (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1))) zero).
      + exact Hz.
      + exact Hsum. }
  (* 乘正数消去 ⟹ E1 ≤ E2 *)
  assert (Hcancel : le (minus E1 E2) zero).
  { apply (le_mult_pos_cancel (minus E1 E2) (minus b1 b2) Hbpos).
    apply (le_id_l (mult (minus E1 E2) (minus b1 b2)) (mult (minus b1 b2) (minus E1 E2))).
    - apply mult_comm.
    - exact Hmain. }
  apply (le_minus_nonneg_rev E1 E2 Hcancel).
Qed.


(* 熵唯一最大：同能量约束且 S[p] = S[p_b] ⟹ p = p_b。
   证明：S[p_b] - S[p] = KL 且等熵 ⟹ KL = 0 ⟹ gibbs_equality。 *)
Theorem entropy_max_unique :
  forall p : S -> R,
    normalized p -> positive_dist p ->
    Id (energy_expectation p) (energy_expectation boltzmann_dist) ->
    Id (entropy_dist p) (entropy_dist boltzmann_dist) ->
    forall s : S, Id (p s) (boltzmann_dist s).
Proof.
  intros p Hnp Hpp Henergy Hent s.
  (* 1. S[p_b] - S[p] = KL *)
  assert (Hdef : Id (minus (entropy_dist boltzmann_dist) (entropy_dist p))
                    (relative_entropy p boltzmann_dist))
    by exact (entropy_deficit_kl p Hnp Hpp Henergy).
  (* 2. 等熵 ⟹ KL = 0（minus_self_zero：S[p]=S[p_b] ⟹ S[p_b]-S[p] = 0） *)
  assert (Hkl0 : Id (relative_entropy p boltzmann_dist) zero).
  {
    assert (Hmz : Id (minus (entropy_dist boltzmann_dist) (entropy_dist p)) zero)
      by exact (minus_self_zero (entropy_dist boltzmann_dist) (entropy_dist p) (id_sym Hent)).
    exact (id_trans (id_sym Hdef) Hmz).
  }
  (* 3. gibbs_equality：KL = 0 ⟹ p = p_b *)
  exact (gibbs_equality p boltzmann_dist Hnp Hpp (boltzmann_normalized) (fun t => boltzmann_dist_pos t) Hkl0 s).
Qed.

(* ============================================================ *)
(* A-3：T2.2 对偶合拢——温度参数化 Boltzmann 族的约束熵最大     *)
(*   闭环（论文2 最大熵 Lagrange 对偶的构造性收口）             *)
(*   组装：entropy_temp_explicit（熵显式公式）+                 *)
(*   relative_entropy_temp_decomp（KL 温度分解）+               *)
(*   entropy_deficit_kl_temp（熵亏 = KL，温度版）⟹              *)
(*   max_entropy_is_boltzmann_temp（同能量 ⟹ 熵最大，温度版）   *)
(*   + entropy_max_unique_temp（同能量同熵 ⟹ 唯一，温度版）⟹    *)
(*   temp_energy_dual_closed（sigT 对偶闭环：对每个温度 t，      *)
(*   约束能量 E_temp(t) 下熵最大化问题解存在且唯一）             *)
(* ============================================================ *)

(* 熵亏 = KL（温度版）：同约束能量 E(p) == E_temp(t) 下，
   S[p_t] − S[p] == KL(p‖p_t)——组装 entropy_temp_explicit +
   relative_entropy_temp_decomp + 同能量换形（β·E(p) == β·E(p_t)）*)
Theorem entropy_deficit_kl_temp : forall t : R, forall Ht : lt zero t, forall p : S -> R,
  normalized p -> positive_dist p ->
  Id (energy_expectation p) (energy_exp_temp t Ht) ->
  Id (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p))
     (relative_entropy p (boltzmann_dist_temp t Ht)).
Proof.
  intros t Ht p Hnp Hpp Henergy.
  set (B := boltzmann_dist_temp t Ht).
  set (Et := energy_exp_temp t Ht).
  set (Sp := entropy_dist p).
  set (Spt := entropy_dist B).
  set (K := relative_entropy p B).
  (* KL(p‖p_t) == −S[p] + β·E(p) + log Z *)
  assert (Hkl : Id K (plus (plus (opp Sp) (mult (inv_pos t Ht) (energy_expectation p))) (log (Z_temp t)))).
  { unfold K, Sp, B. exact (relative_entropy_temp_decomp t Ht p Hnp). }
  (* S[p_t] == β·E(p_t) + log Z *)
  assert (Hse : Id Spt (plus (mult (inv_pos t Ht) Et) (log (Z_temp t)))).
  { unfold Spt, Et, B. exact (entropy_temp_explicit t Ht). }
  (* 换形：−S[p] + β·E(p) + log Z == [β·E(p_t) + log Z] − S[p]
     （结合/交换重组 + 同能量替换 β·E(p) == β·E(p_t)） *)
  assert (Hkl' : Id K (plus (plus (mult (inv_pos t Ht) Et) (log (Z_temp t))) (opp Sp))).
  {
    apply (id_trans Hkl).
    apply (id_trans (id_sym (plus_assoc (opp Sp) (mult (inv_pos t Ht) (energy_expectation p)) (log (Z_temp t))))).
    apply (id_trans (plus_comm (opp Sp) (plus (mult (inv_pos t Ht) (energy_expectation p)) (log (Z_temp t))))).
    apply (id_cong (fun x => plus (plus x (log (Z_temp t))) (opp Sp))
                   (id_cong (fun x => mult (inv_pos t Ht) x) Henergy)).
  }
  (* 目标：minus Spt Sp == K；minus Spt Sp == plus Spt (opp Sp) == [β·E(p_t)+log Z] − Sp（Hse 正向 + Hkl' 反向） *)
  unfold minus.
  apply (id_trans (id_cong (fun x => plus x (opp Sp)) Hse) (id_sym Hkl')).
Qed.

(* 温度版最大熵：同约束能量 E(p) == E_temp(t) ⟹ S[p] ≤ S[p_t]
   （组装 entropy_deficit_kl_temp + gibbs_inequality + le 链，仿固定温度版骨架） *)
Theorem max_entropy_is_boltzmann_temp : forall t : R, forall Ht : lt zero t, forall p : S -> R,
  normalized p -> positive_dist p ->
  Id (energy_expectation p) (energy_exp_temp t Ht) ->
  le (entropy_dist p) (entropy_dist (boltzmann_dist_temp t Ht)).
Proof.
  intros t Ht p Hnp Hpp Henergy.
  (* 1. S[p_t] - S[p] = KL（温度版熵亏） *)
  assert (Hdef : Id (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p))
                    (relative_entropy p (boltzmann_dist_temp t Ht)))
    by exact (entropy_deficit_kl_temp t Ht p Hnp Hpp Henergy).
  (* 2. KL ≥ 0（gibbs_inequality：p 与 p_t 均归一化正） *)
  assert (Hkl : le zero (relative_entropy p (boltzmann_dist_temp t Ht))).
  {
    apply (gibbs_inequality p (boltzmann_dist_temp t Ht)).
    - exact Hnp.
    - exact Hpp.
    - exact (boltzmann_dist_temp_normalized t Ht).
    - intro s. exact (boltzmann_dist_temp_pos t Ht s).
  }
  (* 3. 0 ≤ S[p_t] - S[p] ⟹ S[p] ≤ S[p_t] *)
  assert (Hnonneg : le zero (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p)))
    by exact (le_id_r zero (relative_entropy p (boltzmann_dist_temp t Ht))
                     (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p))
                     (id_sym Hdef) Hkl).
  assert (Hplus : Id (plus (entropy_dist p) (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p)))
                     (entropy_dist (boltzmann_dist_temp t Ht)))
    by exact (minus_plus_cancel (entropy_dist p) (entropy_dist (boltzmann_dist_temp t Ht))).
  assert (Hle : le (entropy_dist p)
                   (plus (entropy_dist p) (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p))))
    by exact (le_plus_nonneg_r (entropy_dist p) (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p)) Hnonneg).
  exact (le_id_r (entropy_dist p)
                 (plus (entropy_dist p) (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p)))
                 (entropy_dist (boltzmann_dist_temp t Ht)) Hplus Hle).
Qed.

(* 温度版唯一性：同约束能量 + 同熵 ⟹ p == p_t 逐点
   （组装 entropy_deficit_kl_temp + minus_self_zero + gibbs_equality，仿固定温度版骨架） *)
Theorem entropy_max_unique_temp : forall t : R, forall Ht : lt zero t, forall p : S -> R,
  normalized p -> positive_dist p ->
  Id (energy_expectation p) (energy_exp_temp t Ht) ->
  Id (entropy_dist p) (entropy_dist (boltzmann_dist_temp t Ht)) ->
  forall s : S, Id (p s) (boltzmann_dist_temp t Ht s).
Proof.
  intros t Ht p Hnp Hpp Henergy Hent s.
  (* 1. S[p_t] - S[p] = KL *)
  assert (Hdef : Id (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p))
                    (relative_entropy p (boltzmann_dist_temp t Ht)))
    by exact (entropy_deficit_kl_temp t Ht p Hnp Hpp Henergy).
  (* 2. 等熵 ⟹ KL = 0 *)
  assert (Hkl0 : Id (relative_entropy p (boltzmann_dist_temp t Ht)) zero).
  {
    assert (Hmz : Id (minus (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p)) zero)
      by exact (minus_self_zero (entropy_dist (boltzmann_dist_temp t Ht)) (entropy_dist p) (id_sym Hent)).
    exact (id_trans (id_sym Hdef) Hmz).
  }
  (* 3. gibbs_equality：KL = 0 ⟹ p = p_t *)
  exact (gibbs_equality p (boltzmann_dist_temp t Ht) Hnp Hpp (boltzmann_dist_temp_normalized t Ht)
                       (fun s => boltzmann_dist_temp_pos t Ht s) Hkl0 s).
Qed.

(* 对偶闭环（A-3 主定理）：对每个温度 t（= 每个约束能量 E_temp(t)），
   熵最大化问题解存在（sigT 见证 p_t 本身）且最优（同能量熵最大）且唯一（同能量同熵 ⟹ 逐点相等） *)
Theorem temp_energy_dual_closed : forall t : R, forall Ht : lt zero t,
  sigT (fun pb : S -> R =>
    And (And (normalized pb) (positive_dist pb))
        (And (Id (energy_expectation pb) (energy_exp_temp t Ht))
             (And (forall p : S -> R, normalized p -> positive_dist p ->
                    Id (energy_expectation p) (energy_exp_temp t Ht) ->
                    le (entropy_dist p) (entropy_dist pb))
                  (forall p : S -> R, normalized p -> positive_dist p ->
                    Id (energy_expectation p) (energy_exp_temp t Ht) ->
                    Id (entropy_dist p) (entropy_dist pb) ->
                    forall s : S, Id (p s) (pb s))))).
Proof.
  intros t Ht.
  exists (boltzmann_dist_temp t Ht).
  split.
  - split.
    + exact (boltzmann_dist_temp_normalized t Ht).
    + intro s. exact (boltzmann_dist_temp_pos t Ht s).
  - split.
    + reflexivity.
    + split.
      * intros p Hnp Hpp Henergy.
        exact (max_entropy_is_boltzmann_temp t Ht p Hnp Hpp Henergy).
      * intros p Hnp Hpp Henergy Hent.
        exact (entropy_max_unique_temp t Ht p Hnp Hpp Henergy Hent).
Qed.

(* ============================================================ *)
(* 项 6：温度-能量严格单调（2026-09-02，T2.2/A-3 严格化）       *)
(*   陈述（差正形态）：t1 < t2 且 KL(p_t2 竖线竖线 p_t1) > 0     *)
(*     ⟹ 0 < E(t2) − E(t1)。恒等：                              *)
(*     (b1−b2)·(E2−E1) == KL1 + KL2（两温度 KL 分解相减）        *)
(*   诚实条件（T4.3）：KL 严格正接口（能量非平凡 ⟹ 满足）       *)
(* ============================================================ *)

(* KL 分解换形：−S2 + b1·E2 + log Z1 == (b1−b2)·E2 + (log Z1 − log Z2)
   （S2 == b2·E2 + log Z2 代入 + opp_plus + 结合交换重排） *)
Lemma temp_strict_A_chain2 : forall (t1 t2 : R) (Ht1 : lt zero t1) (Ht2 : lt zero t2),
  Id (plus (plus (opp (entropy_dist (boltzmann_dist_temp t2 Ht2))) (mult (inv_pos t1 Ht1) (energy_exp_temp t2 Ht2))) (log (Z_temp t1)))
     (plus (mult (minus (inv_pos t1 Ht1) (inv_pos t2 Ht2)) (energy_exp_temp t2 Ht2))
           (minus (log (Z_temp t1)) (log (Z_temp t2)))).
Proof.
  intros t1 t2 Ht1 Ht2.
  set (b1 := inv_pos t1 Ht1). set (b2 := inv_pos t2 Ht2).
  set (E2 := energy_exp_temp t2 Ht2).
  set (S2 := entropy_dist (boltzmann_dist_temp t2 Ht2)).
  set (Z1 := Z_temp t1). set (Z2 := Z_temp t2).
  assert (Hse : Id S2 (plus (mult b2 E2) (log Z2))).
  { unfold S2, b2, E2, Z2. apply (entropy_temp_explicit t2 Ht2). }
  assert (H1 : Id (plus (plus (opp S2) (mult b1 E2)) (log Z1))
                  (plus (plus (opp (plus (mult b2 E2) (log Z2))) (mult b1 E2)) (log Z1))).
  { apply (id_cong (fun x => plus (plus (opp x) (mult b1 E2)) (log Z1)) Hse). }
  assert (H2 : Id (plus (plus (opp (plus (mult b2 E2) (log Z2))) (mult b1 E2)) (log Z1))
                  (plus (plus (plus (opp (mult b2 E2)) (opp (log Z2))) (mult b1 E2)) (log Z1))).
  { apply (id_cong (fun x => plus (plus x (mult b1 E2)) (log Z1))).
    apply (opp_plus (mult b2 E2) (log Z2)). }
  assert (H3 : Id (plus (plus (plus (opp (mult b2 E2)) (opp (log Z2))) (mult b1 E2)) (log Z1))
                  (plus (plus (opp (mult b2 E2)) (mult b1 E2)) (plus (opp (log Z2)) (log Z1)))).
  {
    apply (id_trans
             (id_cong (fun x => plus x (log Z1))
                      (id_trans (id_sym (plus_assoc (opp (mult b2 E2)) (opp (log Z2)) (mult b1 E2)))
                     (id_trans (id_cong (fun x => plus (opp (mult b2 E2)) x)
                                        (plus_comm (opp (log Z2)) (mult b1 E2)))
                               (plus_assoc (opp (mult b2 E2)) (mult b1 E2) (opp (log Z2))))))).
    apply id_sym.
    apply (plus_assoc (plus (opp (mult b2 E2)) (mult b1 E2)) (opp (log Z2)) (log Z1)).
  }
  assert (H4 : Id (plus (opp (mult b2 E2)) (mult b1 E2))
                  (mult (minus b1 b2) E2)).
  {
    apply (id_trans (plus_comm (opp (mult b2 E2)) (mult b1 E2))
           (id_sym (mult_minus_distr_r b1 b2 E2))).
  }
  assert (H5 : Id (plus (opp (log Z2)) (log Z1))
                  (minus (log Z1) (log Z2))).
  { unfold minus. apply (plus_comm (opp (log Z2)) (log Z1)). }
  assert (Hm4 : Id (plus (plus (opp (mult b2 E2)) (mult b1 E2)) (plus (opp (log Z2)) (log Z1)))
                   (plus (mult (minus b1 b2) E2) (plus (opp (log Z2)) (log Z1)))).
  { apply (id_cong (fun x => plus x (plus (opp (log Z2)) (log Z1))) H4). }
  assert (Hfin : Id (plus (plus (opp (mult b2 E2)) (mult b1 E2)) (plus (opp (log Z2)) (log Z1)))
                    (plus (mult (minus b1 b2) E2) (minus (log Z1) (log Z2)))).
  { apply (id_trans Hm4).
    apply (id_cong (fun x => plus (mult (minus b1 b2) E2) x) H5). }
  apply (id_trans H1).
  apply (id_trans H2).
  apply (id_trans H3).
  exact Hfin.
Qed.

(* 简化（避免超长结合链）：直接逐步 trans——见 temp_strict_ident2 *)
Lemma temp_strict_ident2 : forall (t1 t2 : R) (Ht1 : lt zero t1) (Ht2 : lt zero t2),
  Id (plus (relative_entropy (boltzmann_dist_temp t2 Ht2) (boltzmann_dist_temp t1 Ht1))
           (relative_entropy (boltzmann_dist_temp t1 Ht1) (boltzmann_dist_temp t2 Ht2)))
     (mult (minus (inv_pos t1 Ht1) (inv_pos t2 Ht2))
           (minus (energy_exp_temp t2 Ht2) (energy_exp_temp t1 Ht1))).
Proof.
  intros t1 t2 Ht1 Ht2.
  set (b1 := inv_pos t1 Ht1). set (b2 := inv_pos t2 Ht2).
  set (E1 := energy_exp_temp t1 Ht1). set (E2 := energy_exp_temp t2 Ht2).
  set (Z1 := Z_temp t1). set (Z2 := Z_temp t2).
  assert (HK1 : Id (relative_entropy (boltzmann_dist_temp t2 Ht2) (boltzmann_dist_temp t1 Ht1))
                   (plus (mult (minus b1 b2) E2) (minus (log Z1) (log Z2)))).
  {
    unfold b1, b2, E2, Z1, Z2.
    apply (id_trans
             (relative_entropy_temp_decomp t1 Ht1 (boltzmann_dist_temp t2 Ht2)
                                           (boltzmann_dist_temp_normalized t2 Ht2))
             (temp_strict_A_chain2 t1 t2 Ht1 Ht2)).
  }
  assert (HK2 : Id (relative_entropy (boltzmann_dist_temp t1 Ht1) (boltzmann_dist_temp t2 Ht2))
                   (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1)))).
  {
    unfold b1, b2, E1, Z1, Z2.
    apply (id_trans
             (relative_entropy_temp_decomp t2 Ht2 (boltzmann_dist_temp t1 Ht1)
                                           (boltzmann_dist_temp_normalized t1 Ht1))
             (temp_strict_A_chain2 t2 t1 Ht2 Ht1)).
  }
  assert (Hsum : Id (plus (relative_entropy (boltzmann_dist_temp t2 Ht2) (boltzmann_dist_temp t1 Ht1))
                          (relative_entropy (boltzmann_dist_temp t1 Ht1) (boltzmann_dist_temp t2 Ht2)))
                    (plus (plus (mult (minus b1 b2) E2) (minus (log Z1) (log Z2)))
                          (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1))))).
  {
    apply (id_cong2 plus HK1 HK2).
  }
  apply (id_trans Hsum).
  (* log 抵消（Hz 同前） *)
  assert (Hz : Id (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1))) zero).
  { unfold minus.
    apply (id_trans (id_sym (plus_assoc (log Z1) (opp (log Z2)) (plus (log Z2) (opp (log Z1)))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (plus_assoc (opp (log Z2)) (log Z2) (opp (log Z1))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (id_cong (fun x => plus x (opp (log Z1)))
                                       (id_trans (plus_comm (opp (log Z2)) (log Z2)) (plus_opp (log Z2)))))
           (id_trans (id_cong (fun x => plus (log Z1) x)
                              (id_trans (plus_comm zero (opp (log Z1))) (plus_zero (opp (log Z1)))))
                     (plus_opp (log Z1)))))). }
  assert (Hoppm : Id (minus b2 b1) (opp (minus b1 b2))).
  {
    unfold minus.
    exact (id_sym (id_trans (opp_plus b1 (opp b2))
                   (id_trans (id_cong (fun x => plus (opp b1) x) (double_neg b2))
                             (plus_comm (opp b1) b2)))).
  }
  assert (Hmain2 : Id (plus (mult (minus b1 b2) E2) (mult (minus b2 b1) E1))
                      (mult (minus b1 b2) (minus E2 E1))).
  {
    apply (id_trans (id_cong (fun x => plus (mult (minus b1 b2) E2) (mult x E1)) Hoppm)
           (id_trans (id_cong (fun x => plus (mult (minus b1 b2) E2) x)
                              (opp_mult_r (minus b1 b2) E1))
                     (id_sym (mult_minus_distr_l (minus b1 b2) E2 E1)))).
  }
  (* 逐步：M1 := plus (plus (mult d E2)(minus L1 L2)) (plus (mult d' E1)(minus L2 L1))
            == plus (mult d E2)(plus (minus L1 L2)(plus (mult d' E1)(minus L2 L1)))（assoc 反向）
            == plus (mult d E2)(plus (mult d' E1)(plus (minus L1 L2)(minus L2 L1)))（comm 交换内层）
            == plus (mult d E2)(plus (mult d' E1) zero)（Hz）
            == plus (mult d E2)(mult d' E1)（plus_zero）
            == mult d (minus E2 E1)（Hmain2） *)
  assert (H1 : Id (plus (plus (mult (minus b1 b2) E2) (minus (log Z1) (log Z2)))
                        (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1))))
                  (plus (mult (minus b1 b2) E2)
                        (plus (minus (log Z1) (log Z2))
                              (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1)))))).
  { apply id_sym.
    apply (plus_assoc (mult (minus b1 b2) E2) (minus (log Z1) (log Z2))
                      (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1)))). }
  assert (H2 : Id (plus (mult (minus b1 b2) E2)
                        (plus (minus (log Z1) (log Z2))
                              (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1)))))
                  (plus (mult (minus b1 b2) E2)
                        (plus (mult (minus b2 b1) E1)
                              (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1)))))).
  {
    assert (H2a : Id (plus (mult (minus b1 b2) E2)
                           (plus (minus (log Z1) (log Z2))
                                 (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1)))))
                     (plus (mult (minus b1 b2) E2)
                           (plus (plus (minus (log Z1) (log Z2)) (mult (minus b2 b1) E1))
                                 (minus (log Z2) (log Z1))))).
    { apply (id_cong (fun x => plus (mult (minus b1 b2) E2) x)).
      apply (plus_assoc (minus (log Z1) (log Z2)) (mult (minus b2 b1) E1) (minus (log Z2) (log Z1))). }
    assert (H2b : Id (plus (mult (minus b1 b2) E2)
                           (plus (plus (minus (log Z1) (log Z2)) (mult (minus b2 b1) E1))
                                 (minus (log Z2) (log Z1))))
                     (plus (mult (minus b1 b2) E2)
                           (plus (plus (mult (minus b2 b1) E1) (minus (log Z1) (log Z2)))
                                 (minus (log Z2) (log Z1))))).
    { apply (id_cong (fun x => plus (mult (minus b1 b2) E2) (plus x (minus (log Z2) (log Z1))))).
      apply (plus_comm (minus (log Z1) (log Z2)) (mult (minus b2 b1) E1)). }
    assert (H2c : Id (plus (mult (minus b1 b2) E2)
                           (plus (plus (mult (minus b2 b1) E1) (minus (log Z1) (log Z2)))
                                 (minus (log Z2) (log Z1))))
                     (plus (mult (minus b1 b2) E2)
                           (plus (mult (minus b2 b1) E1)
                                 (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1)))))).
    { apply (id_cong (fun x => plus (mult (minus b1 b2) E2) x)).
      apply id_sym.
      apply (plus_assoc (mult (minus b2 b1) E1) (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1))). }
    exact (id_trans H2a (id_trans H2b H2c)).
  }
  assert (H3 : Id (plus (mult (minus b1 b2) E2)
                        (plus (mult (minus b2 b1) E1) zero))
                  (plus (mult (minus b1 b2) E2) (mult (minus b2 b1) E1))).
  { apply (id_cong (fun x => plus (mult (minus b1 b2) E2) x)).
    apply (plus_zero (mult (minus b2 b1) E1)). }
  assert (Hza : Id (plus (mult (minus b1 b2) E2)
                         (plus (mult (minus b2 b1) E1)
                               (plus (minus (log Z1) (log Z2)) (minus (log Z2) (log Z1)))))
                   (plus (mult (minus b1 b2) E2)
                         (plus (mult (minus b2 b1) E1) zero))).
  { apply (id_cong (fun x => plus (mult (minus b1 b2) E2)
                                  (plus (mult (minus b2 b1) E1) x)) Hz). }
  assert (Hfin : Id (plus (plus (mult (minus b1 b2) E2) (minus (log Z1) (log Z2)))
                          (plus (mult (minus b2 b1) E1) (minus (log Z2) (log Z1))))
                    (mult (minus b1 b2) (minus E2 E1))).
  {
    apply (id_trans H1).
    apply (id_trans H2).
    apply (id_trans Hza).
    apply (id_trans H3).
    exact Hmain2.
  }
  exact Hfin.
Qed.

(* ============================================================ *)
(* 最终定理：温度-能量严格单调（差正形态）                      *)
(*   t1 < t2 且 KL(p_t2 竖线竖线 p_t1) > 0 ⟹ 0 < E2 − E1        *)
(* ============================================================ *)
Theorem energy_exp_temp_strict_mono : forall (t1 t2 : R) (Ht1 : lt zero t1) (Ht2 : lt zero t2),
  lt t1 t2 ->
  lt zero (relative_entropy (boltzmann_dist_temp t2 Ht2) (boltzmann_dist_temp t1 Ht1)) ->
  lt zero (minus (energy_exp_temp t2 Ht2) (energy_exp_temp t1 Ht1)).
Proof.
  intros t1 t2 Ht1 Ht2 Ht12 Hkl1.
  set (b1 := inv_pos t1 Ht1). set (b2 := inv_pos t2 Ht2).
  set (E1 := energy_exp_temp t1 Ht1). set (E2 := energy_exp_temp t2 Ht2).
  set (B1 := boltzmann_dist_temp t1 Ht1). set (B2 := boltzmann_dist_temp t2 Ht2).
  set (K1 := relative_entropy B2 B1). set (K2 := relative_entropy B1 B2).
  (* β2 < β1 且 d := b1 − b2 > 0 *)
  assert (Hb : lt b2 b1) by (unfold b1, b2; apply (inv_pos_lt_compat t1 t2 Ht1 Ht2 Ht12)).
  assert (Hbd : lt zero (minus b1 b2)) by (unfold b1, b2; apply (lt_minus_nonneg b2 b1 Hb)).
  (* K2 ≥ 0（gibbs 不等式） *)
  assert (Hkl2 : le zero K2).
  { unfold K2, B1, B2.
    apply (gibbs_inequality (boltzmann_dist_temp t1 Ht1) (boltzmann_dist_temp t2 Ht2)).
    - apply (boltzmann_dist_temp_normalized t1 Ht1).
    - intro s. apply (boltzmann_dist_temp_pos t1 Ht1 s).
    - apply (boltzmann_dist_temp_normalized t2 Ht2).
    - intro s. apply (boltzmann_dist_temp_pos t2 Ht2 s). }
  (* K1 + K2 > 0（K1 > 0 且 K2 ≥ 0 ⟹ K1 ≤ K1+K2 ⟹ lt 传递） *)
  assert (Hklsum : lt zero (plus K1 K2)).
  {
    apply (lt_le_trans zero K1 (plus K1 K2)).
    - unfold K1, B1, B2. exact Hkl1.
    - apply (le_plus_nonneg_r K1 K2). exact Hkl2.
  }
  (* 恒等：K1 + K2 == d·(E2−E1) *)
  assert (Hid : Id (plus K1 K2) (mult (minus b1 b2) (minus E2 E1))).
  { unfold K1, K2, b1, b2, E1, E2. exact (temp_strict_ident2 t1 t2 Ht1 Ht2). }
  (* 0 < d·(E2−E1)（lt_id_r 替换） *)
  assert (Hprod : lt zero (mult (minus b1 b2) (minus E2 E1))).
  { apply (lt_id_r zero (plus K1 K2) (mult (minus b1 b2) (minus E2 E1))).
    - exact Hid.
    - exact Hklsum. }
  (* 正乘严格消去 ⟹ 0 < E2 − E1（先 comm 换序） *)
  apply (lt_mult_pos_cancel (minus E2 E1) (minus b1 b2) Hbd).
  apply (lt_id_r zero (mult (minus b1 b2) (minus E2 E1))
                  (mult (minus E2 E1) (minus b1 b2))).
  - apply (mult_comm (minus b1 b2) (minus E2 E1)).
  - exact Hprod.
Qed.

(* ============================================================ *)



(* ============================================================ *)
(* RLHF 对齐（当前 AI 训练核心：KL 正则化奖励最大化）          *)
(* ============================================================ *)
(* 上帝视角：现代 LLM 对齐（RLHF/DPO/PPO）的目标是               *)
(*   maximize  E_π[r] - β·KL(π‖π_ref)                          *)
(* 即：在偏离参考策略 π_ref 不超过 KL 惩罚的前提下最大化奖励。 *)
(* 数学上这是 Boltzmann 机制的精确复刻（奖励替代能量，参考策略 *)
(* 替代均匀先验）——本 Section 给出闭式解与最优性定理：        *)
(*   最优策略 π*(s) ∝ π_ref(s)·e^{r(s)/β}（奖励加权 Boltzmann），*)
(*   且它是唯一最优解。                                        *)
(* ------------------------------------------------------------ *)

(* ============================================================ *)
(* 前三条支柱（自由能唯一极小 / KL 度量 / 熵最大）给出理论闭环；*)
(* 此处补实操接口：交叉熵 H(p,q) := -Σ p·log q。              *)
(* 由 energy_in_log_boltzmann（E = -D·(log p_b + log Z)）得    *)
(*   ⟨E⟩_p = -D·(H(p,p_b) + log Z)                             *)
(*   F[p] = ⟨E⟩_p - D·S[p] = -D·(H(p,p_b) + log Z + S[p])      *)
(* 即训练（最小化 F）等价于最小化交叉熵 H(p,p_b)（固定 p_b）。 *)
(* ------------------------------------------------------------ *)

(* 交叉熵：H(p,q) := -Σ_s p(s)·log q(s) *)
Definition cross_entropy (p q : S -> R) : R :=
  sum_over_S (fun s => mult (p s) (opp (log (q s)))).

(* 交叉熵-相对熵-熵恒等式：H(p,q) = S[p] + KL(p||q)
   （信息论核心：交叉熵 = 自熵 + 相对熵。由定义展开 + 求和线性） *)
Theorem cross_entropy_decomp :
  forall p q : S -> R,
    Id (cross_entropy p q)
       (plus (entropy_dist p) (relative_entropy p q)).
Proof.
  intros p q.
  unfold cross_entropy, entropy_dist, relative_entropy.
  (* Σ p·(-log q) = Σ p·(-log p) + Σ p·(log p - log q) *)
  (* 逐点：mult (p s) (opp (log (q s))) = plus (mult (p s) (opp (log (p s))))
                                            (mult (p s) (minus (log (p s)) (log (q s)))) *)
  assert (Hpt : forall s, Id (mult (p s) (opp (log (q s))))
                            (plus (mult (p s) (opp (log (p s))))
                                  (mult (p s) (minus (log (p s)) (log (q s)))))).
  {
    intro s.
    unfold minus.
    assert (Hd : Id (mult (p s) (plus (opp (log (p s))) (plus (log (p s)) (opp (log (q s))))))
                    (plus (mult (p s) (opp (log (p s))))
                          (mult (p s) (plus (log (p s)) (opp (log (q s)))))))
      by exact (distrib (p s) (opp (log (p s))) (plus (log (p s)) (opp (log (q s))))).
    (* 左侧化简：opp (log p) + (log p - log q) = -log q（minus_plus_cancel） *)
    assert (Hcancel : Id (plus (opp (log (p s))) (plus (log (p s)) (opp (log (q s)))))
                         (opp (log (q s)))).
    {
      (* assoc：opp log p + (log p - log q) = (opp log p + log p) - log q *)
      assert (Ha : Id (plus (opp (log (p s))) (plus (log (p s)) (opp (log (q s)))))
                      (plus (plus (opp (log (p s))) (log (p s))) (opp (log (q s)))))
        by exact (plus_assoc (opp (log (p s))) (log (p s)) (opp (log (q s)))).
      (* 内层抵消：opp log p + log p = 0 *)
      assert (Hz : Id (plus (opp (log (p s))) (log (p s))) zero)
        by exact (id_trans (plus_comm (opp (log (p s))) (log (p s))) (plus_opp (log (p s)))).
      (* (opp log p + log p) - log q = 0 - log q = -log q *)
      assert (Hb : Id (plus (plus (opp (log (p s))) (log (p s))) (opp (log (q s))))
                      (plus zero (opp (log (q s)))))
        by exact (id_cong (fun x => plus x (opp (log (q s)))) Hz).
      assert (Hc : Id (plus zero (opp (log (q s)))) (opp (log (q s))))
        by exact (id_trans (plus_comm zero (opp (log (q s)))) (plus_zero (opp (log (q s))))).
      exact (id_trans Ha (id_trans Hb Hc)).
    }
    assert (Hleft : Id (mult (p s) (plus (opp (log (p s))) (plus (log (p s)) (opp (log (q s))))))
                       (mult (p s) (opp (log (q s)))))
      by exact (id_cong (fun x => mult (p s) x) Hcancel).
    (* 右侧展开：mult (p s) (log p - log q) = mult (p s) (log p) + mult (p s) (-log q) *)
    assert (Hdist2 : Id (mult (p s) (plus (log (p s)) (opp (log (q s)))))
                        (plus (mult (p s) (log (p s))) (mult (p s) (opp (log (q s))))))
      by exact (distrib (p s) (log (p s)) (opp (log (q s)))).
    (* 目标：mult (p s) (-log q) = plus (mult (p s) (-log p)) (mult (p s) (log p - log q))
       由 Hd 反向（Hleft 后两侧换位） *)
    exact (id_trans (id_sym Hleft) Hd).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p s) (opp (log (q s)))))
                   (sum_over_S (fun s => plus (mult (p s) (opp (log (p s))))
                                            (mult (p s) (minus (log (p s)) (log (q s)))))))
    by exact (sum_over_S_ext (fun s => mult (p s) (opp (log (q s))))
                             (fun s => plus (mult (p s) (opp (log (p s))))
                                            (mult (p s) (minus (log (p s)) (log (q s)))))
                             Hpt).
  rewrite Hext.
  assert (Hadd : Id (sum_over_S (fun s => plus (mult (p s) (opp (log (p s))))
                                            (mult (p s) (minus (log (p s)) (log (q s))))))
                   (plus (sum_over_S (fun s => mult (p s) (opp (log (p s)))))
                         (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (q s)))))))
    by exact (sum_over_S_add (fun s => mult (p s) (opp (log (p s))))
                             (fun s => mult (p s) (minus (log (p s)) (log (q s))))).
  rewrite Hadd.
  reflexivity.
Qed.

Theorem energy_cross_entropy :
  forall p : S -> R,
    normalized p ->
    Id (energy_expectation p)
       (plus (mult D (cross_entropy p boltzmann_dist)) (opp (mult D (log Z)))).
Proof.
  intros p Hnp.
  unfold energy_expectation, cross_entropy.
  (* 逐点：mult (p s) (base_loss s) = mult (p s) (-D·(log p_b s + log Z)) *)
  assert (Hpt : forall s, Id (mult (p s) (base_loss s))
                            (mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))).
  {
    intro s.
    assert (He : Id (base_loss s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
      by exact (energy_in_log_boltzmann s).
    exact (id_cong (fun x => mult (p s) x) He).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p s) (base_loss s)))
                   (sum_over_S (fun s => mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))))
    by exact (sum_over_S_ext (fun s => mult (p s) (base_loss s))
                             (fun s => mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                             Hpt).
  rewrite Hext.
  (* 逐点展开为 -D·(p·log p_b + p·log Z) *)
  assert (Hpt2 : forall s, Id (mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                             (opp (mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                (mult (p s) (log Z)))))).
  {
    intro s.
    assert (Hopp : Id (mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                      (opp (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))))
      by exact (opp_mult_l (p s) (mult D (plus (log (boltzmann_dist s)) (log Z)))).
    assert (Hsw : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                     (mult D (mult (p s) (plus (log (boltzmann_dist s)) (log Z))))).
    {
      assert (H1 : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                      (mult (mult (p s) D) (plus (log (boltzmann_dist s)) (log Z))))
        by exact (mult_assoc (p s) D (plus (log (boltzmann_dist s)) (log Z))).
      assert (H2 : Id (mult (mult (p s) D) (plus (log (boltzmann_dist s)) (log Z)))
                      (mult (mult D (p s)) (plus (log (boltzmann_dist s)) (log Z))))
        by exact (id_cong (fun x => mult x (plus (log (boltzmann_dist s)) (log Z))) (mult_comm (p s) D)).
      assert (H3 : Id (mult (mult D (p s)) (plus (log (boltzmann_dist s)) (log Z)))
                      (mult D (mult (p s) (plus (log (boltzmann_dist s)) (log Z)))))
        by exact (id_sym (mult_assoc D (p s) (plus (log (boltzmann_dist s)) (log Z)))).
      exact (id_trans H1 (id_trans H2 H3)).
    }
    assert (Hdist : Id (mult (p s) (plus (log (boltzmann_dist s)) (log Z)))
                       (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))))
      by exact (distrib (p s) (log (boltzmann_dist s)) (log Z)).
    assert (Hd2 : Id (mult D (mult (p s) (plus (log (boltzmann_dist s)) (log Z))))
                     (mult D (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z)))))
      by exact (id_cong (fun x => mult D x) Hdist).
    assert (Hd3 : Id (mult D (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))))
                     (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                           (mult D (mult (p s) (log Z)))))
      by exact (distrib D (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))).
    assert (Htot : Id (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z))))
                     (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                           (mult D (mult (p s) (log Z)))))
      by exact (id_trans Hsw (id_trans Hd2 Hd3)).
    assert (Hopp2 : Id (opp (mult (p s) (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                      (opp (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                                 (mult D (mult (p s) (log Z))))))
      by exact (id_cong opp Htot).
    assert (Hopp3 : Id (opp (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                                 (mult D (mult (p s) (log Z)))))
                    (opp (mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                       (mult (p s) (log Z)))))).
    {
      assert (Hd4 : Id (mult D (plus (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))))
                      (plus (mult D (mult (p s) (log (boltzmann_dist s))))
                            (mult D (mult (p s) (log Z)))))
        by exact (distrib D (mult (p s) (log (boltzmann_dist s))) (mult (p s) (log Z))).
      exact (id_cong opp (id_sym Hd4)).
    }
    exact (id_trans Hopp (id_trans Hopp2 Hopp3)).
  }
  assert (Hext2 : Id (sum_over_S (fun s => mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z))))))
                     (sum_over_S (fun s => opp (mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                           (mult (p s) (log Z)))))))
    by exact (sum_over_S_ext (fun s => mult (p s) (opp (mult D (plus (log (boltzmann_dist s)) (log Z)))))
                             (fun s => opp (mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                         (mult (p s) (log Z)))))
                             Hpt2).
  rewrite Hext2.
  assert (Hso : Id (sum_over_S (fun s => opp (mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                         (mult (p s) (log Z))))))
                   (opp (sum_over_S (fun s => mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                          (mult (p s) (log Z)))))))
    by exact (sum_opp (fun s => mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                            (mult (p s) (log Z))))).
  rewrite Hso.
  assert (Hlin : Id (sum_over_S (fun s => mult D (plus (mult (p s) (log (boltzmann_dist s)))
                                                       (mult (p s) (log Z)))))
                    (mult D (sum_over_S (fun s => plus (mult (p s) (log (boltzmann_dist s)))
                                                       (mult (p s) (log Z))))))
    by exact (sum_over_S_linear D (fun s => plus (mult (p s) (log (boltzmann_dist s)))
                                                 (mult (p s) (log Z)))).
  rewrite Hlin.
  assert (Hadd : Id (sum_over_S (fun s => plus (mult (p s) (log (boltzmann_dist s)))
                                              (mult (p s) (log Z))))
                   (plus (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))
                         (sum_over_S (fun s => mult (p s) (log Z)))))
    by exact (sum_over_S_add (fun s => mult (p s) (log (boltzmann_dist s)))
                             (fun s => mult (p s) (log Z))).
  rewrite Hadd.
  (* Σ p·log p_b = -cross_entropy（cross_entropy := Σ p·(-log p_b)） *)
  assert (Hce : Id (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))
                   (opp (sum_over_S (fun s => mult (p s) (opp (log (boltzmann_dist s))))))).
  {
    assert (Hpt3 : forall s, Id (mult (p s) (log (boltzmann_dist s)))
                               (opp (mult (p s) (opp (log (boltzmann_dist s)))))).
    {
      intro s.
      apply id_sym.
      apply (id_trans (id_cong opp (opp_mult_l (p s) (log (boltzmann_dist s))))
                   (double_neg (mult (p s) (log (boltzmann_dist s))))).
    }
    assert (Hext3 : Id (sum_over_S (fun s => mult (p s) (log (boltzmann_dist s))))
                      (sum_over_S (fun s => opp (mult (p s) (opp (log (boltzmann_dist s)))))))
      by exact (sum_over_S_ext (fun s => mult (p s) (log (boltzmann_dist s)))
                               (fun s => opp (mult (p s) (opp (log (boltzmann_dist s))))) Hpt3).
    assert (Hso3 : Id (sum_over_S (fun s => opp (mult (p s) (opp (log (boltzmann_dist s))))))
                      (opp (sum_over_S (fun s => mult (p s) (opp (log (boltzmann_dist s)))))))
      by exact (sum_opp (fun s => mult (p s) (opp (log (boltzmann_dist s))))).
    exact (id_trans Hext3 Hso3).
  }
  rewrite Hce.
  (* Σ p·log Z = log Z（归一化） *)
  assert (Hlz : Id (sum_over_S (fun s => mult (p s) (log Z))) (log Z)).
  {
    assert (Hsw : Id (sum_over_S (fun s => mult (p s) (log Z)))
                     (sum_over_S (fun s => mult (log Z) (p s))))
      by exact (sum_over_S_ext (fun s => mult (p s) (log Z))
                               (fun s => mult (log Z) (p s))
                               (fun s => mult_comm (p s) (log Z))).
    rewrite Hsw.
    assert (Hl1 : Id (sum_over_S (fun s => mult (log Z) (p s))) (mult (log Z) (sum_over_S p)))
      by exact (sum_over_S_linear (log Z) p).
    rewrite Hl1.
    rewrite Hnp.
    assert (Hm1 : Id (mult (log Z) one) (log Z)) by exact (mult_one (log Z)).
    rewrite Hm1.
    reflexivity.
  }
  rewrite Hlz.
  (* 目标：opp (mult D (plus (opp (cross_entropy p boltzmann_dist)) (log Z)))
     实际 = D·(Σp log p_b + log Z) 取负 = D·(-H + log Z) 取负
     = plus (mult D H) (opp (mult D (log Z)))。 *)
  (* 直接用原始 cross_entropy 定义匹配目标 RHS *)
  unfold cross_entropy.
  (* 目标：opp (mult D (plus (opp (Σ p·(-log p_b))) (log Z)))
     = plus (mult D (Σ p·(-log p_b))) (opp (mult D (log Z)))
     由 ring_opp_plus_neg 恒等式。 *)
  assert (Hring : forall X Y : R, Id (opp (mult D (plus (opp X) Y)))
                                    (plus (mult D X) (opp (mult D Y)))).
  {
    intros X Y.
    assert (H1 : Id (opp (mult D (plus (opp X) Y)))
                    (opp (plus (mult D (opp X)) (mult D Y))))
      by exact (id_cong opp (distrib D (opp X) Y)).
    assert (H2 : Id (opp (plus (mult D (opp X)) (mult D Y)))
                    (plus (opp (mult D (opp X))) (opp (mult D Y))))
      by exact (opp_plus (mult D (opp X)) (mult D Y)).
    assert (H3 : Id (opp (mult D (opp X))) (mult D X))
      by exact (id_trans (id_sym (opp_mult_l D (opp X))) (id_cong (fun x => mult D x) (double_neg X))).
    assert (H4 : Id (plus (opp (mult D (opp X))) (opp (mult D Y)))
                    (plus (mult D X) (opp (mult D Y))))
      by exact (id_cong (fun x => plus x (opp (mult D Y))) H3).
    exact (id_trans H1 (id_trans H2 H4)).
  }
  (* 目标现在：Id (opp (mult D (plus (opp S) (log Z)))) (plus (mult D S) (opp (mult D (log Z))))
     其中 S := sum_over_S (fun s => mult (p s) (opp (log (boltzmann_dist s)))) *)
  exact (Hring (sum_over_S (fun s => mult (p s) (opp (log (boltzmann_dist s))))) (log Z)).
Qed.

(* ============================================================ *)
(* 变分推断：ELBO 与证据下界（VI 核心，改进恒等式.txt 块 1）   *)
(* ============================================================ *)
(* 在自由能框架中，ELBO(q) := -F[q] 是证据（配分函数对数的能量   *)
(* 形式 opp (free_energy boltzmann_dist)）的变分下界；训练（最大   *)
(* 化 ELBO）等价于最小化自由能。三定理：                         *)
(*   (a) elbo_lower_bound：ELBO(q) ≤ evidence（自由能最小化 + 取负）*)
(*   (b) evidence_kl_decomp：evidence = ELBO(q) + D·KL(q||p_b)     *)
(*       ——证据与 ELBO 的差距精确等于 KL 散度（VI 核心恒等式）；  *)
(*   (c) elbo_explicit：ELBO 的熵+能量显式形式。                  *)
(* ------------------------------------------------------------ *)

(* ELBO：变分分布 q 的证据下界 *)
Definition elbo (q : S -> R) : R :=
  opp (free_energy q).

(* 证据：配分函数对数的能量形式（D·log Z 的抽象，无需 D = 1） *)
Definition evidence : R :=
  opp (free_energy boltzmann_dist).

(* ELBO(q) ≤ evidence：由自由能最小化直接推出（取负 + opp_le_compat） *)
Theorem elbo_lower_bound :
  forall q : S -> R,
    normalized q -> positive_dist q ->
    le (elbo q) evidence.
Proof.
  intros q Hnq Hpq.
  unfold elbo, evidence.
  apply (opp_le_compat (free_energy boltzmann_dist) (free_energy q)).
  exact (min_free_energy_is_boltzmann q Hnq Hpq).
Qed.

(* 证据的 KL 分解：evidence = ELBO(q) + D·KL(q||p_b)
   变分推断的核心恒等式——证据与 ELBO 的差距精确等于 KL 散度
   （由 free_energy_kl_decomp 取负移项：-F[b] = -F[q] + D·KL） *)
Theorem evidence_kl_decomp :
  forall q : S -> R,
    normalized q ->
    Id evidence
       (plus (elbo q) (mult D (relative_entropy q boltzmann_dist))).
Proof.
  intros q Hnq.
  unfold evidence, elbo.
  assert (Hdecomp : Id (free_energy q)
                       (plus (free_energy boltzmann_dist)
                             (mult D (relative_entropy q boltzmann_dist))))
    by exact (free_energy_kl_decomp q Hnq).
  assert (Htarget : Id (plus (opp (free_energy q)) (mult D (relative_entropy q boltzmann_dist)))
                       (opp (free_energy boltzmann_dist))).
  {
    assert (H1 : Id (plus (opp (free_energy q)) (mult D (relative_entropy q boltzmann_dist)))
                    (plus (opp (plus (free_energy boltzmann_dist) (mult D (relative_entropy q boltzmann_dist))))
                          (mult D (relative_entropy q boltzmann_dist))))
      by exact (id_cong (fun x => plus x (mult D (relative_entropy q boltzmann_dist))) (id_cong opp Hdecomp)).
    assert (H2 : Id (plus (opp (plus (free_energy boltzmann_dist) (mult D (relative_entropy q boltzmann_dist))))
                          (mult D (relative_entropy q boltzmann_dist)))
                    (plus (plus (opp (free_energy boltzmann_dist)) (opp (mult D (relative_entropy q boltzmann_dist))))
                          (mult D (relative_entropy q boltzmann_dist))))
      by exact (id_cong (fun x => plus x (mult D (relative_entropy q boltzmann_dist)))
                        (opp_plus (free_energy boltzmann_dist) (mult D (relative_entropy q boltzmann_dist)))).
    assert (H3 : Id (plus (plus (opp (free_energy boltzmann_dist)) (opp (mult D (relative_entropy q boltzmann_dist))))
                          (mult D (relative_entropy q boltzmann_dist)))
                    (plus (opp (free_energy boltzmann_dist)) zero)).
    {
      assert (H3a : Id (plus (plus (opp (free_energy boltzmann_dist)) (opp (mult D (relative_entropy q boltzmann_dist))))
                            (mult D (relative_entropy q boltzmann_dist)))
                      (plus (opp (free_energy boltzmann_dist))
                            (plus (opp (mult D (relative_entropy q boltzmann_dist)))
                                  (mult D (relative_entropy q boltzmann_dist)))))
        by exact (id_sym (plus_assoc (opp (free_energy boltzmann_dist))
                                     (opp (mult D (relative_entropy q boltzmann_dist)))
                                     (mult D (relative_entropy q boltzmann_dist)))).
      assert (H3b : Id (plus (opp (mult D (relative_entropy q boltzmann_dist))) (mult D (relative_entropy q boltzmann_dist))) zero)
        by exact (id_trans (plus_comm (opp (mult D (relative_entropy q boltzmann_dist))) (mult D (relative_entropy q boltzmann_dist)))
                           (plus_opp (mult D (relative_entropy q boltzmann_dist)))).
      assert (H3c : Id (plus (opp (free_energy boltzmann_dist))
                             (plus (opp (mult D (relative_entropy q boltzmann_dist)))
                                   (mult D (relative_entropy q boltzmann_dist))))
                      (plus (opp (free_energy boltzmann_dist)) zero))
        by exact (id_cong (fun x => plus (opp (free_energy boltzmann_dist)) x) H3b).
      exact (id_trans H3a H3c).
    }
    assert (H4 : Id (plus (opp (free_energy boltzmann_dist)) zero) (opp (free_energy boltzmann_dist)))
      by exact (plus_zero (opp (free_energy boltzmann_dist))).
    exact (id_trans H1 (id_trans H2 (id_trans H3 H4))).
  }
  exact (id_sym Htarget).
Qed.

(* ELBO 的显式分解：-F[q] = -⟨E⟩_q + D·S[q]（S[q] := -Σ q·log q 信息熵） *)
Theorem elbo_explicit :
  forall q : S -> R,
    Id (elbo q)
       (plus (opp (sum_over_S (fun s => mult (q s) (base_loss s))))
             (mult D (entropy_dist q))).
Proof.
  intro q.
  (* free_energy 为泛化 λ，unfold 不 β-归约 ⟹ change（内核转换） *)
  change (Id (opp (plus (sum_over_S (fun s => mult (q s) (base_loss s)))
                        (mult D (sum_over_S (fun s => mult (q s) (log (q s)))))))
             (plus (opp (sum_over_S (fun s => mult (q s) (base_loss s))))
                   (mult D (sum_over_S (fun s => mult (q s) (opp (log (q s)))))))).
  assert (Hop : Id (opp (plus (sum_over_S (fun s => mult (q s) (base_loss s)))
                              (mult D (sum_over_S (fun s => mult (q s) (log (q s)))))))
                   (plus (opp (sum_over_S (fun s => mult (q s) (base_loss s))))
                         (opp (mult D (sum_over_S (fun s => mult (q s) (log (q s))))))))
    by exact (opp_plus (sum_over_S (fun s => mult (q s) (base_loss s)))
                       (mult D (sum_over_S (fun s => mult (q s) (log (q s)))))).
  rewrite Hop.
  assert (Hent : Id (opp (mult D (sum_over_S (fun s => mult (q s) (log (q s))))))
                   (mult D (sum_over_S (fun s => mult (q s) (opp (log (q s))))))).
  {
    assert (Hpt : forall s, Id (mult (q s) (opp (log (q s))))
                             (opp (mult (q s) (log (q s)))))
      by (intro s; exact (opp_mult_l (q s) (log (q s)))).
    assert (He : Id (sum_over_S (fun s => mult (q s) (opp (log (q s)))))
                    (sum_over_S (fun s => opp (mult (q s) (log (q s))))))
      by exact (sum_over_S_ext _ _ Hpt).
    assert (Hso : Id (sum_over_S (fun s => opp (mult (q s) (log (q s)))))
                     (opp (sum_over_S (fun s => mult (q s) (log (q s))))))
      by exact (sum_opp (fun s => mult (q s) (log (q s)))).
    assert (Hlin : Id (mult D (sum_over_S (fun s => mult (q s) (opp (log (q s))))))
                     (mult D (opp (sum_over_S (fun s => mult (q s) (log (q s)))))))
      by exact (id_cong (fun x => mult D x) (id_trans He Hso)).
    assert (Hoppr : Id (mult D (opp (sum_over_S (fun s => mult (q s) (log (q s))))))
                      (opp (mult D (sum_over_S (fun s => mult (q s) (log (q s)))))))
      by exact (opp_mult_l D (sum_over_S (fun s => mult (q s) (log (q s))))).
    exact (id_sym (id_trans Hlin Hoppr)).
  }
  rewrite Hent.
  reflexivity.
Qed.

(* ============================================================ *)
(* ELBO 紧性与证据差距的精确 KL 形式（变分推断闭环补全）       *)
(* ============================================================ *)
(* (a) 当变分分布 q 恰好为 Boltzmann 后验时，ELBO 无间隙地      *)
(*     达到证据值（等号条件——变分推断的"零误差"态）；           *)
(* (b) 对任意归一化 q，evidence − ELBO(q) 精确等于 D·KL(q||p_b)，*)
(*     为 VI 训练提供可量化的后验逼近误差指标。                  *)
(* ------------------------------------------------------------ *)

(* KL(p||p) = 0（相对熵自零；FreeEnergyMinimization 内自证）：
   展开定义后逐点 p s·(log p s − log p s) = p s·0 = 0，
   经 sum_over_S_ext + sum_over_S_linear + mult_zero 收尾。 *)
Lemma relative_entropy_self_zero' : forall p : S -> R,
  Id (relative_entropy p p) zero.
Proof.
  intro p.
  unfold relative_entropy.
  (* 逐点：p s·(log p s − log p s) = zero *)
  assert (Hpt : forall s, Id (mult (p s) (minus (log (p s)) (log (p s)))) zero).
  {
    intro s.
    assert (Hz : Id (minus (log (p s)) (log (p s))) zero)
      by exact (minus_self_zero (log (p s)) (log (p s)) (@id_refl R (log (p s)))).
    exact (id_trans (id_cong (fun x => mult (p s) x) Hz) (mult_zero (p s))).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (p s)))))
                    (sum_over_S (fun s => zero)))
    by exact (sum_over_S_ext _ _ Hpt).
  assert (Hzero : Id (sum_over_S (fun s => zero)) zero).
  {
    (* 零函数 = mult zero (常一函数) 逐点；sum_over_S_linear 收尾 *)
    assert (Hsame : Id (sum_over_S (fun s => zero))
                       (sum_over_S (fun s => mult zero one)))
      by (apply sum_over_S_ext; intro s; exact (id_sym (id_trans (mult_comm zero one) (mult_zero one)))).
    assert (Hlin : Id (sum_over_S (fun s => mult zero one))
                      (mult zero (sum_over_S (fun s => one))))
      by exact (sum_over_S_linear zero (fun s : S => one)).
    assert (Hmz : Id (mult zero (sum_over_S (fun s : S => one))) zero)
      by exact (id_trans (mult_comm zero (sum_over_S (fun s : S => one)))
                         (mult_zero (sum_over_S (fun s : S => one)))).
    exact (id_trans Hsame (id_trans Hlin Hmz)).
  }
  exact (id_trans Hext Hzero).
Qed.

(* (a) ELBO 在 Boltzmann 分布处紧致：ELBO[p_b] = evidence。
    证明：evidence_kl_decomp 给 evidence = ELBO[p_b] + D·KL(p_b||p_b)，
    relative_entropy_self_zero' 给 KL(p_b||p_b) = 0，故 evidence = ELBO[p_b]。
    非平凡：KL 自零 + 环代数消去。 *)
Theorem elbo_tight :
  Id (elbo boltzmann_dist) evidence.
Proof.
  unfold evidence.
  (* evidence = ELBO[p_b] + D·KL(p_b||p_b)（KL 分解在 q = p_b 处） *)
  assert (Hkl : Id (mult D (relative_entropy boltzmann_dist boltzmann_dist)) zero).
  {
    assert (Hself : Id (relative_entropy boltzmann_dist boltzmann_dist) zero)
      by exact (relative_entropy_self_zero' boltzmann_dist).
    exact (id_trans (id_cong (fun x => mult D x) Hself) (mult_zero D)).
  }
  assert (Hdec : Id evidence
                   (plus (elbo boltzmann_dist) (mult D (relative_entropy boltzmann_dist boltzmann_dist))))
    by exact (evidence_kl_decomp boltzmann_dist (boltzmann_normalized)).
  (* evidence = ELBO[p_b] + 0 = ELBO[p_b] *)
  assert (Hplus : Id (plus (elbo boltzmann_dist) (mult D (relative_entropy boltzmann_dist boltzmann_dist)))
                     (elbo boltzmann_dist))
    by exact (id_trans (id_cong (fun x => plus (elbo boltzmann_dist) x) Hkl)
                       (plus_zero (elbo boltzmann_dist))).
  exact (id_sym (id_trans Hdec Hplus)).
Qed.

(* (b) 证据-ELBO 差距 = D·KL(q||p_b)（变分差距的精确诊断）。
    证明：evidence_kl_decomp 给 evidence = ELBO(q) + D·KL(q||p_b)，
    两侧减 ELBO(q)（minus_plus_cancel_r：minus (plus a b) a = b）。
    非平凡：KL 分解恒等式 + 减法消去。 *)
Theorem evidence_gap_kl :
  forall q : S -> R,
    normalized q ->
    Id (minus evidence (elbo q))
       (mult D (relative_entropy q boltzmann_dist)).
Proof.
  intros q Hnq.
  assert (Hdec : Id evidence
                   (plus (elbo q) (mult D (relative_entropy q boltzmann_dist))))
    by exact (evidence_kl_decomp q Hnq).
  (* 两侧减 elbo q：minus evidence (elbo q) = minus (plus (elbo q) KL') (elbo q) = KL' *)
  assert (Hminus : Id (minus evidence (elbo q))
                      (minus (plus (elbo q) (mult D (relative_entropy q boltzmann_dist))) (elbo q)))
    by exact (id_cong (fun x => minus x (elbo q)) Hdec).
  assert (Hcancel : Id (minus (plus (elbo q) (mult D (relative_entropy q boltzmann_dist))) (elbo q))
                       (mult D (relative_entropy q boltzmann_dist)))
    by exact (minus_plus_cancel_r (elbo q) (mult D (relative_entropy q boltzmann_dist))).
  exact (id_trans Hminus Hcancel).
Qed.

(* ============================================================ *)
(* 交叉熵训练目标的 KL 等价性（单调改进与hentic KL 控制.txt 块3）*)
(* ============================================================ *)
(* 核心：cross_entropy(p,q) − cross_entropy(p,p) = KL(p||q)     *)
(* 含义：固定目标分布 p 时，最小化交叉熵就是最小化 KL(p||q)。    *)
(* 非平凡：cross_entropy_decomp + KL 自零 + 环代数重组。         *)
(* ------------------------------------------------------------ *)

(* 交叉熵减自熵 = KL：H(p,q) − H(p,p) = KL(p||q)。
   证明：H(p,q) = S[p] + KL(p||q)（cross_entropy_decomp），
   H(p,p) = S[p] + KL(p||p) = S[p]（KL 自零），
   相减：S[p] + KL(p||q) − S[p] = KL(p||q)（plus_assoc + plus_opp）。 *)
Theorem cross_entropy_minus_self :
  forall p q : S -> R,
    Id (minus (cross_entropy p q) (cross_entropy p p))
       (relative_entropy p q).
Proof.
  intros p q.
  (* H(p,q) = S[p] + KL(p||q) *)
  assert (H1 : Id (cross_entropy p q)
                  (plus (entropy_dist p) (relative_entropy p q)))
    by exact (cross_entropy_decomp p q).
  (* H(p,p) = S[p] + KL(p||p) = S[p]（KL 自零） *)
  assert (H2 : Id (cross_entropy p p) (entropy_dist p)).
  {
    assert (H2a : Id (cross_entropy p p)
                     (plus (entropy_dist p) (relative_entropy p p)))
      by exact (cross_entropy_decomp p p).
    assert (H2b : Id (relative_entropy p p) zero)
      by exact (relative_entropy_self_zero' p).
    assert (H2c : Id (plus (entropy_dist p) (relative_entropy p p))
                     (plus (entropy_dist p) zero))
      by exact (id_cong (fun x => plus (entropy_dist p) x) H2b).
    assert (H2d : Id (plus (entropy_dist p) zero) (entropy_dist p))
      by exact (plus_zero (entropy_dist p)).
    exact (id_trans H2a (id_trans H2c H2d)).
  }
  (* H(p,q) − H(p,p) = (S + KL) − S = KL *)
  assert (Hmain : Id (minus (plus (entropy_dist p) (relative_entropy p q)) (entropy_dist p))
                     (relative_entropy p q)).
  {
    unfold minus.
    (* plus (plus S KL) (opp S) = plus S (plus KL (opp S)) = plus S (plus (opp S) KL) = KL *)
    assert (Ha : Id (plus (plus (entropy_dist p) (relative_entropy p q)) (opp (entropy_dist p)))
                    (plus (entropy_dist p) (plus (relative_entropy p q) (opp (entropy_dist p)))))
      by exact (id_sym (plus_assoc (entropy_dist p) (relative_entropy p q) (opp (entropy_dist p)))).
    assert (Hb : Id (plus (entropy_dist p) (plus (relative_entropy p q) (opp (entropy_dist p))))
                    (plus (entropy_dist p) (plus (opp (entropy_dist p)) (relative_entropy p q))))
      by exact (id_cong (fun x => plus (entropy_dist p) x)
                        (plus_comm (relative_entropy p q) (opp (entropy_dist p)))).
    assert (Hc : Id (plus (entropy_dist p) (plus (opp (entropy_dist p)) (relative_entropy p q)))
                    (plus (plus (entropy_dist p) (opp (entropy_dist p))) (relative_entropy p q)))
      by exact (plus_assoc (entropy_dist p) (opp (entropy_dist p)) (relative_entropy p q)).
    assert (Hd : Id (plus (plus (entropy_dist p) (opp (entropy_dist p))) (relative_entropy p q))
                    (plus zero (relative_entropy p q)))
      by exact (id_cong (fun x => plus x (relative_entropy p q)) (plus_opp (entropy_dist p))).
    assert (He : Id (plus zero (relative_entropy p q)) (relative_entropy p q))
      by exact (id_trans (plus_comm zero (relative_entropy p q)) (plus_zero (relative_entropy p q))).
    exact (id_trans Ha (id_trans Hb (id_trans Hc (id_trans Hd He)))).
  }
  (* 组装：H(p,q) − H(p,p) = (S+KL) − S = KL *)
  assert (Hrepl : Id (minus (cross_entropy p q) (cross_entropy p p))
                     (minus (plus (entropy_dist p) (relative_entropy p q)) (entropy_dist p)))
    by exact (id_cong2 minus H1 H2).
  exact (id_trans Hrepl Hmain).
Qed.

(* 训练等价性：交叉熵下降量 = KL 下降量（固定目标 p）。
   若 H(p,q2) ≤ H(p,q1)，则 KL(p||q2) ≤ KL(p||q1)。
   非平凡：cross_entropy_decomp 分解 + 共同被加项消去 + 差分非负链。 *)

(* 局部引理：共同被加项消去 minus (plus A B) (plus A C) = minus B C *)
Lemma minus_plus_common_local : forall A B C : R,
  Id (minus (plus A B) (plus A C)) (minus B C).
Proof.
  intros A B C.
  unfold minus.
  assert (H1 : Id (plus (plus A B) (opp (plus A C)))
                  (plus (plus A B) (plus (opp A) (opp C))))
    by exact (id_cong (fun x => plus (plus A B) x) (opp_plus A C)).
  assert (H2 : Id (plus (plus A B) (plus (opp A) (opp C)))
                  (plus (plus A (opp A)) (plus B (opp C))))
    by exact (plus_swap_mid A B (opp A) (opp C)).
  assert (H3 : Id (plus (plus A (opp A)) (plus B (opp C)))
                  (plus zero (plus B (opp C))))
    by exact (id_cong (fun x => plus x (plus B (opp C))) (plus_opp A)).
  assert (H4 : Id (plus zero (plus B (opp C))) (plus B (opp C)))
    by exact (id_trans (plus_comm zero (plus B (opp C))) (plus_zero (plus B (opp C)))).
  exact (id_trans H1 (id_trans H2 (id_trans H3 H4))).
Qed.

Theorem training_equivalence :
  forall p q1 q2 : S -> R,
    le (cross_entropy p q2) (cross_entropy p q1) ->
    le (relative_entropy p q2) (relative_entropy p q1).
Proof.
  intros p q1 q2 Hce.
  (* 差分恒等：(H2 − H1) = (KL2 − KL1)。
     H2 = S + KL2、H1 = S + KL1（cross_entropy_decomp），
     相减经 minus_plus_common_local 消共同项 S。 *)
  assert (Hdiff : Id (minus (cross_entropy p q2) (cross_entropy p q1))
                     (minus (relative_entropy p q2) (relative_entropy p q1))).
  {
    assert (H2d : Id (cross_entropy p q2)
                     (plus (entropy_dist p) (relative_entropy p q2)))
      by exact (cross_entropy_decomp p q2).
    assert (H1d : Id (cross_entropy p q1)
                     (plus (entropy_dist p) (relative_entropy p q1)))
      by exact (cross_entropy_decomp p q1).
    assert (Hrepl : Id (minus (cross_entropy p q2) (cross_entropy p q1))
                       (minus (plus (entropy_dist p) (relative_entropy p q2))
                              (plus (entropy_dist p) (relative_entropy p q1))))
      by exact (id_cong2 minus H2d H1d).
    assert (Hcancel : Id (minus (plus (entropy_dist p) (relative_entropy p q2))
                                (plus (entropy_dist p) (relative_entropy p q1)))
                         (minus (relative_entropy p q2) (relative_entropy p q1)))
      by exact (minus_plus_common_local (entropy_dist p) (relative_entropy p q2) (relative_entropy p q1)).
    exact (id_trans Hrepl Hcancel).
  }
  (* 由 Hce : le H2 H1 得 le zero (minus H1 H2)（le_minus_nonneg H2 H1） *)
  assert (Hd : le zero (minus (cross_entropy p q1) (cross_entropy p q2)))
    by exact (le_minus_nonneg (cross_entropy p q2) (cross_entropy p q1) Hce).
  (* 替换：minus H1 H2 = minus KL1 KL2（cross_entropy_decomp + 共同项消去） *)
  assert (Hdiff' : Id (minus (cross_entropy p q1) (cross_entropy p q2))
                      (minus (relative_entropy p q1) (relative_entropy p q2))).
  {
    assert (H1d : Id (cross_entropy p q1)
                     (plus (entropy_dist p) (relative_entropy p q1)))
      by exact (cross_entropy_decomp p q1).
    assert (H2d : Id (cross_entropy p q2)
                     (plus (entropy_dist p) (relative_entropy p q2)))
      by exact (cross_entropy_decomp p q2).
    assert (Hrepl : Id (minus (cross_entropy p q1) (cross_entropy p q2))
                       (minus (plus (entropy_dist p) (relative_entropy p q1))
                              (plus (entropy_dist p) (relative_entropy p q2))))
      by exact (id_cong2 minus H1d H2d).
    assert (Hcancel : Id (minus (plus (entropy_dist p) (relative_entropy p q1))
                                (plus (entropy_dist p) (relative_entropy p q2)))
                         (minus (relative_entropy p q1) (relative_entropy p q2)))
      by exact (minus_plus_common_local (entropy_dist p) (relative_entropy p q1) (relative_entropy p q2)).
    exact (id_trans Hrepl Hcancel).
  }
  assert (Hd' : le zero (minus (relative_entropy p q1) (relative_entropy p q2)))
    by exact (le_id_r zero (minus (cross_entropy p q1) (cross_entropy p q2))
                      (minus (relative_entropy p q1) (relative_entropy p q2))
                      Hdiff' Hd).
  (* le KL2 KL1：KL2 ≤ KL2 + (KL1 − KL2) = KL1 *)
  apply (le_id_r (relative_entropy p q2)
                 (plus (relative_entropy p q2) (minus (relative_entropy p q1) (relative_entropy p q2)))
                 (relative_entropy p q1)
                 (minus_plus_cancel (relative_entropy p q2) (relative_entropy p q1))).
  exact (le_plus_nonneg_r (relative_entropy p q2)
                          (minus (relative_entropy p q1) (relative_entropy p q2)) Hd').
Qed.

End FreeEnergyMinimization.

(* ============================================================ *)
(* RLHF 对齐（当前 AI 训练核心：KL 正则化奖励最大化）          *)
(* ============================================================ *)
(* 现代 LLM 对齐（RLHF/DPO/PPO）的目标：                        *)
(*   maximize  E_π[r] - β·KL(π‖π_ref)                          *)
(* 在偏离参考策略 π_ref（SFT 策略）不超过 KL 惩罚的前提下最大化*)
(* 奖励。数学上是 Boltzmann 机制的精确复刻（奖励替代能量、参考 *)
(* 策略替代均匀先验）。闭式解：π*(s) ∝ π_ref(s)·e^{r(s)/β}。   *)
(* 最优性 J(pi) <= J(pi_star) 由奖励反解 + Gibbs 不等式严格证明。     *)
(* ------------------------------------------------------------ *)

Section Alignment.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let inv_pos := @inv_pos RI.
Let le := @le RI.
Let lt := @lt RI.
Let log := @log RI.
Let exp_neg := @exp_neg RI.
Let sum_over_S := @sum_over_S RI SS SO.

Variable reward : S -> R.          (* 奖励函数 r(s) *)
Variable beta : R.                 (* KL 正则化温度 β > 0 *)
Variable beta_pos : lt zero beta.
Variable pi_ref : S -> R.          (* 参考策略（如 SFT 策略） *)
Variable pi_ref_pos : forall s, lt zero (pi_ref s).
Variable pi_ref_norm : Id (sum_over_S pi_ref) one.

(* 闭式最优解：π*(s) ∝ π_ref(s)·e^{r(s)/β}，归一化配分函数 *)
Definition Z_align : R :=
  sum_over_S (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))).

Variable Z_align_pos : lt zero Z_align.

Definition pi_star (s : S) : R :=
  mult (inv_pos Z_align Z_align_pos)
       (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))).

(* π* 正性 *)
Lemma pi_star_pos : forall s : S, lt zero (pi_star s).
Proof.
  intro s.
  unfold pi_star.
  apply mult_positive.
  - apply inv_pos_pos.
  - apply mult_positive.
    + apply pi_ref_pos.
    + apply exp_neg_pos.
Qed.

(* π* 归一化：Σ π* = 1（与 boltzmann_normalized 同构） *)
Theorem pi_star_normalized :
  Id (sum_over_S pi_star) one.
Proof.
  assert (H1 : Id (sum_over_S (fun s => pi_star s))
                  (sum_over_S (fun s => mult (inv_pos Z_align Z_align_pos)
                                            (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))))
    by (apply sum_over_S_ext; intro s; reflexivity).
  assert (H2 : Id (sum_over_S (fun s => mult (inv_pos Z_align Z_align_pos)
                                            (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
                  (mult (inv_pos Z_align Z_align_pos)
                        (sum_over_S (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))))
    by exact (sum_over_S_linear (inv_pos Z_align Z_align_pos)
                                (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))).
  assert (H3 : Id (mult (inv_pos Z_align Z_align_pos) Z_align) one)
    by exact (id_trans (mult_comm (inv_pos Z_align Z_align_pos) Z_align)
                       (inv_pos_correct Z_align Z_align_pos)).
  assert (H4 : Id (mult (inv_pos Z_align Z_align_pos)
                        (sum_over_S (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
                  one).
  {
    assert (Hdef : Id (sum_over_S (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))) Z_align)
      by reflexivity.
    exact (id_trans (id_cong (fun x => mult (inv_pos Z_align Z_align_pos) x) (id_sym Hdef)) H3).
  }
  exact (id_trans H1 (id_trans H2 H4)).
Qed.

(* π* 的对数分解：log π*(s) = -log Z + log π_ref(s) + r(s)/β
   （由 π* 定义 + log_mult/log_inv_one_inv/log_exp_neg 逐点展开） *)
Lemma log_pi_star :
  forall s : S,
    Id (log (pi_star s))
       (plus (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)))).
Proof.
  intro s.
  unfold pi_star.
  assert (Hpos1 : lt zero (inv_pos Z_align Z_align_pos)) by exact (inv_pos_pos Z_align Z_align_pos).
  assert (Hpos2 : lt zero (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
    by (apply mult_positive; [apply pi_ref_pos | apply exp_neg_pos]).
  assert (Hlm : Id (log (mult (inv_pos Z_align Z_align_pos) (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
                  (plus (log (inv_pos Z_align Z_align_pos)) (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))))
    by exact (log_mult (inv_pos Z_align Z_align_pos) (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))) Hpos1 Hpos2).
  assert (Hli : Id (log (inv_pos Z_align Z_align_pos)) (opp (log Z_align)))
    by exact (log_inv_one_inv Z_align Z_align_pos).
  assert (Hpos3 : lt zero (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))) by exact (exp_neg_pos _).
  assert (Hlm2 : Id (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
                  (plus (log (pi_ref s)) (log (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
    by exact (log_mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))) (pi_ref_pos s) Hpos3).
  assert (Hle : Id (log (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))
                  (mult (inv_pos beta beta_pos) (reward s)))
    by exact (id_trans (log_exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))
                       (double_neg (mult (inv_pos beta beta_pos) (reward s)))).
  assert (Hlm2b : Id (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
                     (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s))))
    by exact (id_trans Hlm2 (id_cong (fun x => plus (log (pi_ref s)) x) Hle)).
  assert (Ht1 : Id (log (mult (inv_pos Z_align Z_align_pos) (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
                   (plus (opp (log Z_align)) (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))))
    by exact (id_trans Hlm (id_cong (fun x => plus x (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))) Hli)).
  assert (Ht2 : Id (plus (opp (log Z_align)) (log (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))))
                   (plus (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)))))
    by exact (id_cong (fun x => plus (opp (log Z_align)) x) Hlm2b).
  exact (id_trans Ht1 Ht2).
Qed.

(* 对齐能量：E_align(s) := -r(s) - beta*log pi_ref(s)
   使得 F_align(pi) := Σpi*E_align + beta*Σpi*log pi = -J(pi)。 *)
Definition align_energy (s : S) : R :=
  minus (opp (reward s)) (mult beta (log (pi_ref s))).

(* 对齐目标：J(pi) := -F_align(pi)
   （RLHF 目标 E_π[r] - beta*KL(pi,pi_ref) 的等价形式，
     定义性保证 rlhf_optimal 直接用自由能最小化） *)
Definition align_objective (pi : S -> R) : R :=
  opp (free_energy align_energy beta pi).

Lemma align_energy_exp :
  forall s : S,
    Id (exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))
       (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))).
Proof.
  intro s.
  unfold align_energy.
  assert (H1 : Id (mult (inv_pos beta beta_pos) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))
                  (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s)))).
  {
    assert (H1a : Id (mult (inv_pos beta beta_pos) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))
                     (minus (mult (inv_pos beta beta_pos) (opp (reward s)))
                            (mult (inv_pos beta beta_pos) (mult beta (log (pi_ref s))))))
      by exact (mult_minus_distr_l (inv_pos beta beta_pos) (opp (reward s)) (mult beta (log (pi_ref s)))).
    assert (H1b : Id (mult (inv_pos beta beta_pos) (opp (reward s)))
                     (opp (mult (inv_pos beta beta_pos) (reward s))))
      by exact (opp_mult_l (inv_pos beta beta_pos) (reward s)).
    assert (H1c : Id (mult (inv_pos beta beta_pos) (mult beta (log (pi_ref s))))
                     (log (pi_ref s))).
    {
      assert (Hc1 : Id (mult (inv_pos beta beta_pos) (mult beta (log (pi_ref s))))
                      (mult (mult (inv_pos beta beta_pos) beta) (log (pi_ref s))))
        by exact (mult_assoc (inv_pos beta beta_pos) beta (log (pi_ref s))).
      assert (Hc2 : Id (mult (mult (inv_pos beta beta_pos) beta) (log (pi_ref s)))
                      (mult one (log (pi_ref s))))
        by exact (id_cong (fun x => mult x (log (pi_ref s)))
                          (id_trans (mult_comm (inv_pos beta beta_pos) beta) (inv_pos_correct beta beta_pos))).
      assert (Hc3 : Id (mult one (log (pi_ref s))) (log (pi_ref s)))
        by exact (id_trans (mult_comm one (log (pi_ref s))) (mult_one (log (pi_ref s)))).
      exact (id_trans Hc1 (id_trans Hc2 Hc3)).
    }
    assert (H1d : Id (minus (mult (inv_pos beta beta_pos) (opp (reward s)))
                            (mult (inv_pos beta beta_pos) (mult beta (log (pi_ref s)))))
                     (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s))))
      by exact (id_trans (id_cong (fun x => minus x (mult (inv_pos beta beta_pos) (mult beta (log (pi_ref s))))) H1b)
                         (id_cong (fun x => minus (opp (mult (inv_pos beta beta_pos) (reward s))) x) H1c)).
    exact (id_trans H1a H1d).
  }
  assert (H2 : Id (opp (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s))))
                  (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s)))).
  {
    assert (H2a : Id (opp (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s))))
                    (plus (opp (opp (mult (inv_pos beta beta_pos) (reward s)))) (log (pi_ref s))))
      by exact (opp_minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s))).
    assert (H2b : Id (plus (opp (opp (mult (inv_pos beta beta_pos) (reward s)))) (log (pi_ref s)))
                    (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s))))
      by exact (id_cong (fun x => plus x (log (pi_ref s))) (double_neg (mult (inv_pos beta beta_pos) (reward s)))).
    exact (id_trans H2a H2b).
  }
  assert (H3 : Id (opp (mult (inv_pos beta beta_pos) (align_energy s)))
                  (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s)))).
  {
    assert (H3a : Id (opp (mult (inv_pos beta beta_pos) (align_energy s)))
                    (opp (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s)))))
      by exact (id_cong opp H1).
    exact (id_trans H3a H2).
  }
  (* Step 4: E_align/beta = opp (r/beta + log pi_ref) (from H1 + opp_plus) *)
  assert (H3b : Id (mult (inv_pos beta beta_pos) (align_energy s))
                  (opp (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s))))).
  {
    assert (H3b1 : Id (mult (inv_pos beta beta_pos) (align_energy s))
                     (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s))))
      by exact H1.
    assert (H3b2 : Id (minus (opp (mult (inv_pos beta beta_pos) (reward s))) (log (pi_ref s)))
                     (opp (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s))))).
    {
      unfold minus.
      assert (H3b2a : Id (plus (opp (mult (inv_pos beta beta_pos) (reward s))) (opp (log (pi_ref s))))
                        (opp (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s)))))
        by exact (id_sym (opp_plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s)))).
      exact H3b2a.
    }
    exact (id_trans H3b1 H3b2).
  }
  assert (H4 : Id (exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))
                  (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))
                        (exp_neg (opp (log (pi_ref s)))))).
  {
    assert (H4a : Id (exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))
                    (exp_neg (opp (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s))))))
      by exact (id_cong (fun t => exp_neg t) H3b).
    assert (H4b : Id (exp_neg (opp (plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s)))))
                    (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))
                          (exp_neg (opp (log (pi_ref s))))))
      by exact (exp_neg_opp_plus (mult (inv_pos beta beta_pos) (reward s)) (log (pi_ref s))).
    exact (id_trans H4a H4b).
  }
  assert (H5 : Id (exp_neg (opp (log (pi_ref s)))) (pi_ref s))
    by exact (exp_neg_opp_log (pi_ref s) (pi_ref_pos s)).
  assert (H6 : Id (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))
                        (exp_neg (opp (log (pi_ref s)))))
                  (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))).
  {
    assert (H6a : Id (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))
                          (exp_neg (opp (log (pi_ref s)))))
                    (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))) (pi_ref s)))
      by exact (id_cong (fun x => mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))) x) H5).
    assert (H6b : Id (mult (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))) (pi_ref s))
                    (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
      by exact (mult_comm (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))) (pi_ref s)).
    exact (id_trans H6a H6b).
  }
  exact (id_trans H4 H6).
Qed.

Lemma align_partition_condition :
  Id Z_align (sum_over_S (fun s => exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))).
Proof.
  unfold Z_align.
  assert (Hext : Id (sum_over_S (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
                   (sum_over_S (fun s => exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))))
    by exact (sum_over_S_ext (fun s => mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s)))))
                             (fun s => exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))
                             (fun s => id_sym (align_energy_exp s))).
  exact Hext.
Qed.

(* ============================================================ *)
(* RLHF 最优性（核心定理）                                    *)
(* ============================================================ *)
(* free_energy 函数外延性（逐点相等 ⟹ 自由能相等）            *)
Lemma free_energy_ext :
  forall f g : S -> R,
    (forall s, Id (f s) (g s)) ->
    Id (free_energy align_energy beta f) (free_energy align_energy beta g).
Proof.
  intros f g Hfg.
  unfold free_energy.
  assert (H1 : Id (sum_over_S (fun s => mult (f s) (align_energy s)))
                  (sum_over_S (fun s => mult (g s) (align_energy s))))
    by (apply sum_over_S_ext; intro s; apply (id_cong (fun x => mult x (align_energy s)) (Hfg s))).
  assert (H2 : Id (sum_over_S (fun s => mult (f s) (log (f s))))
                  (sum_over_S (fun s => mult (g s) (log (g s))))).
  {
    apply sum_over_S_ext.
    intro s.
    assert (Hc1 : Id (mult (f s) (log (f s))) (mult (g s) (log (f s))))
      by exact (id_cong (fun x => mult x (log (f s))) (Hfg s)).
    assert (Hc2 : Id (log (f s)) (log (g s))) by exact (id_cong log (Hfg s)).
    assert (Hc3 : Id (mult (g s) (log (f s))) (mult (g s) (log (g s))))
      by exact (id_cong (fun x => mult (g s) x) Hc2).
    exact (id_trans Hc1 Hc3).
  }
  assert (H3 : Id (plus (sum_over_S (fun s => mult (f s) (align_energy s)))
                        (mult beta (sum_over_S (fun s => mult (f s) (log (f s))))))
                  (plus (sum_over_S (fun s => mult (g s) (align_energy s)))
                        (mult beta (sum_over_S (fun s => mult (g s) (log (g s)))))))
    by exact (id_trans (id_cong (fun x => plus x (mult beta (sum_over_S (fun s => mult (f s) (log (f s)))))) H1)
                    (id_cong (fun x => plus (sum_over_S (fun s => mult (g s) (align_energy s))) (mult beta x)) H2)).
  exact H3.
Qed.

(* 对齐 Boltzmann 恒等：boltzmann_dist align_energy beta ... = pi_star *)
Lemma align_boltzmann_is_pi_star :
  forall s : S,
    Id (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s)
       (pi_star s).
Proof.
  intro s.
  unfold boltzmann_dist, pi_star.
  assert (Hexp : Id (exp_neg (mult (inv_pos beta beta_pos) (align_energy s)))
                    (mult (pi_ref s) (exp_neg (opp (mult (inv_pos beta beta_pos) (reward s))))))
    by exact (align_energy_exp s).
  exact (id_cong (fun x => mult (inv_pos Z_align Z_align_pos) x) Hexp).
Qed.

(* 对齐 Boltzmann 归一化（pi_star_normalized + 外延） *)
Lemma align_boltzmann_normalized :
  Id (sum_over_S (fun s => boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s)) one.
Proof.
  assert (Hext : Id (sum_over_S (fun s => boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s))
                   (sum_over_S pi_star))
    by (apply sum_over_S_ext; intro s; exact (align_boltzmann_is_pi_star s)).
  exact (id_trans Hext pi_star_normalized).
Qed.

(* 对齐 Boltzmann 正性（pi_star_pos + lt_id_l） *)
Lemma align_boltzmann_pos :
  forall s : S, lt zero (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s).
Proof.
  intro s.
  apply (lt_id_r zero (pi_star s) (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s)).
  - exact (id_sym (align_boltzmann_is_pi_star s)).
  - exact (pi_star_pos s).
Qed.

(* RLHF 最优性：J(pi) <= J(pi_star)（对齐目标在奖励加权 Boltzmann 处最大）
   证明：min_free_energy_is_boltzmann（F_align(boltzmann) <= F_align(pi)）
   + free_energy_ext（F_align(boltzmann) = F_align(pi_star)）
   + opp_le_compat（取负得 J(pi) <= J(pi_star)）。 *)
Theorem rlhf_optimal :
  forall pi : S -> R,
    normalized pi -> positive_dist pi ->
    le (align_objective pi) (align_objective pi_star).
Proof.
  intros pi Hnpi Hppi.
  unfold align_objective.
  (* 1. F_align(boltzmann) <= F_align(pi)（Boltzmann 最小自由能） *)
  assert (Hmin : le (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                    (free_energy align_energy beta pi))
    by exact (min_free_energy_is_boltzmann align_energy beta beta_pos Z_align Z_align_pos align_partition_condition pi Hnpi Hppi).
  (* 2. F_align(boltzmann) = F_align(pi_star)（free_energy_ext + 逐点恒等） *)
  assert (Hfe : Id (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                   (free_energy align_energy beta pi_star))
    by exact (free_energy_ext (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos) pi_star align_boltzmann_is_pi_star).
  (* 3. F_align(pi_star) <= F_align(pi)（le_id_l 替换） *)
  assert (Hmin2 : le (free_energy align_energy beta pi_star) (free_energy align_energy beta pi))
    by exact (le_id_l (free_energy align_energy beta pi_star)
                      (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                      (free_energy align_energy beta pi) (id_sym Hfe) Hmin).
  (* 4. 取负（opp_le_compat）：J(pi) <= J(pi_star) *)
  apply (opp_le_compat (free_energy align_energy beta pi_star) (free_energy align_energy beta pi) Hmin2).
Qed.

(* ============================================================ *)
(* DPO：直接偏好优化（隐式奖励的具体化，P2）                  *)

(* ============================================================ *)
(* DPO：直接偏好优化（隐式奖励的具体化，P2）                  *)
(* ============================================================ *)
(* DPO 的巧妙：将奖励函数隐式表示为策略比率的对数——           *)
(*   r(s) = beta * (log pi(s) - log pi_ref(s))                 *)
(* 从而绕过显式奖励建模。DPO 损失 = -J(pi)（负对齐目标），     *)
(* 由 rlhf_optimal 直接推出 dpo_optimal，完全复用已证理论。     *)
(* ------------------------------------------------------------ *)

(* DPO 隐式奖励：r_imp(pi, s) := beta * (log pi(s) - log pi_ref(s)) *)
Definition dpo_implicit_reward (pi : S -> R) (s : S) : R :=
  mult beta (minus (log (pi s)) (log (pi_ref s))).

(* DPO 损失：负对齐目标（最大化奖励 = 最小化损失） *)
Definition dpo_loss (pi : S -> R) : R :=
  opp (align_objective pi).

(* DPO 最优性：在 pi_star 处损失最小。
   证明：dpo_loss = -J(pi)，rlhf_optimal 给 J(pi) <= J(pi_star)，
   opp_le_compat 取负得 -J(pi_star) <= -J(pi)。 *)
Theorem dpo_optimal :
  forall pi : S -> R,
    normalized pi -> positive_dist pi ->
    le (dpo_loss pi_star) (dpo_loss pi).
Proof.
  intros pi Hnpi Hppi.
  unfold dpo_loss.
  assert (Hopt : le (align_objective pi) (align_objective pi_star))
    by exact (rlhf_optimal pi Hnpi Hppi).
  apply (opp_le_compat (align_objective pi) (align_objective pi_star) Hopt).
Qed.

(* ============================================================ *)
(* RLHF 最优策略唯一性（非平凡平行版本：DPO 收敛目标无歧义）   *)
(* ============================================================ *)
(* dpo_optimal 证明 π* 处 DPO 损失最小；此处证明**唯一性**：     *)
(* 任何策略 pi 若取得与 pi_star 相同的最优对齐目标值（J(pi) = J(pi_star)）， *)
(* 则 π = π*（逐点）。                                          *)
(* 证明：取负的逆（opp_eq）把目标相等翻转为自由能相等，再复用   *)
(* free_energy_min_unique（F[p] = F[p_b] ⟹ p = p_b）+            *)
(* align_boltzmann_is_pi_star（p_b = pi_star）——自由能唯一极小的     *)
(* 对偶形式，非平凡：约 12 步跨模块推导链。                     *)
(* ------------------------------------------------------------ *)

(* 取负的逆：-a = -b ⟹ a = b（double_neg 两折） *)
Lemma opp_eq : forall a b : R, Id (opp a) (opp b) -> Id a b.
Proof.
  intros a b Hab.
  assert (H1 : Id (opp (opp a)) (opp (opp b))) by exact (id_cong opp Hab).
  exact (id_trans (id_sym (double_neg a)) (id_trans H1 (double_neg b))).
Qed.

Theorem rlhf_optimal_unique :
  forall pi : S -> R,
    normalized pi -> positive_dist pi ->
    Id (align_objective pi) (align_objective pi_star) ->
    forall s : S, Id (pi s) (pi_star s).
Proof.
  intros pi Hnp Hpp Hj s.
  (* 1. 对齐目标相等（取负形式）⟹ 自由能相等（opp_eq） *)
  assert (Hfeq : Id (free_energy align_energy beta pi)
                    (free_energy align_energy beta pi_star)).
  { unfold align_objective in Hj. exact (opp_eq _ _ Hj). }
  (* 2. F(pi_star) = F(boltzmann)：free_energy_ext + 逐点恒等（p_b = pi_star） *)
  assert (Hfeq_b : Id (free_energy align_energy beta pi_star)
                      (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))).
  {
    apply free_energy_ext.
    intro t.
    exact (id_sym (align_boltzmann_is_pi_star t)).
  }
  (* 3. F(pi) = F(boltzmann)（链） *)
  assert (Hfeq0 : Id (free_energy align_energy beta pi)
                     (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos)))
    by exact (id_trans Hfeq Hfeq_b).
  (* 4. 自由能唯一极小：F(pi) = F(p_b) ⟹ pi = p_b（逐点） *)
  assert (Hpi : forall t : S,
                Id (pi t) (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos t))
    by exact (free_energy_min_unique align_energy beta beta_pos Z_align Z_align_pos align_partition_condition
                                    pi Hnp Hpp Hfeq0).
  (* 5. pi = pi_star（p_b = π* 逐点） *)
  exact (id_trans (Hpi s) (align_boltzmann_is_pi_star s)).
Qed.

(* ============================================================ *)
(* 优势分解与策略改进恒等式（PPO/TRPO 的构造性基石）           *)
(* ============================================================ *)
(* 策略梯度家族的数学基础：对齐目标 J(pi) = E_pi[r] - beta·KL(pi||pi_ref)
   可精确分解为参考策略值 + 优势期望 - KL 惩罚：
     J(pi) = J(pi_ref) + E_pi[advantage_pi_ref] - beta·KL(pi||pi_ref)
   这是 TRPO/PPO 代理目标（surrogate objective）的精确形式——非近似。
   证明：自由能展开（free_energy_align_decomp）+ 参考策略 KL 自零
   （relative_entropy_self_zero）+ 优势求和（Hadv）+ 减法双层合并
   （minus_minus_distr）+ 代数坍缩（Hfin），全部显式 Set 层推导。 *)

(* 状态值：V(pi) := E_pi[r] *)
Definition state_value (pi : S -> R) : R :=
  sum_over_S (fun s => mult (pi s) (reward s)).

(* 优势：A(pi, s) := r(s) - V(pi) *)
Definition advantage (pi : S -> R) (s : S) : R :=
  minus (reward s) (state_value pi).

(* KL 惩罚项：beta·KL(pi||pi_ref) 中的散度部分 *)
Definition kl_to_ref (pi : S -> R) : R :=
  sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))).

(* 减法双层合并：(a - b) - c = a - (b + c) *)
Lemma minus_minus_distr : forall a b c : R,
  Id (minus (minus a b) c) (minus a (plus b c)).
Proof.
  intros a b c.
  unfold minus.
  assert (H1 : Id (plus (plus a (opp b)) (opp c)) (plus a (plus (opp b) (opp c))))
    by exact (id_sym (plus_assoc a (opp b) (opp c))).
  assert (H2 : Id (plus a (plus (opp b) (opp c))) (plus a (opp (plus b c))))
    by exact (id_cong (fun x => plus a x) (id_sym (opp_plus b c))).
  exact (id_trans H1 H2).
Qed.

(* KL(p||p) = 0（自相对熵为零；Gibbs 等号条件的平凡方向） *)
Lemma relative_entropy_self_zero :
  forall p : S -> R,
    Id (relative_entropy p p) zero.
Proof.
  intro p.
  unfold relative_entropy.
  assert (Hpt : forall s, Id (mult (p s) (minus (log (p s)) (log (p s)))) zero).
  {
    intro s.
    assert (Hz : Id (minus (log (p s)) (log (p s))) zero)
      by exact (minus_self_zero (log (p s)) (log (p s)) (@id_refl R (log (p s)))).
    assert (Hm : Id (mult (p s) zero) zero) by exact (mult_zero (p s)).
    exact (id_trans (id_cong (fun x => mult (p s) x) Hz) Hm).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (p s)))))
                   (sum_over_S (fun _ : S => zero)))
    by exact (sum_over_S_ext _ _ Hpt).
  assert (Hzs : Id (sum_over_S (fun _ : S => zero)) zero).
  {
    assert (H : Id (sum_over_S (fun _ : S => zero))
                   (sum_over_S (fun s => mult zero (p s))))
      by exact (sum_over_S_ext (fun _ => zero) (fun s => mult zero (p s))
                               (fun s => id_sym (id_trans (mult_comm zero (p s)) (mult_zero (p s))))).
    rewrite H.
    assert (Hlin : Id (sum_over_S (fun s => mult zero (p s))) (mult zero (sum_over_S p)))
      by exact (sum_over_S_linear zero p).
    assert (Hz : Id (mult zero (sum_over_S p)) zero)
      by exact (id_trans (mult_comm zero (sum_over_S p)) (mult_zero (sum_over_S p))).
    exact (id_trans Hlin Hz).
  }
  exact (id_trans Hext Hzs).
Qed.

(* 自由能展开：F_align(pi) = -V(pi) + beta·KL(pi||pi_ref)（对齐能量的显式求值，
   多态引理——主定理对 pi 与 pi_ref 各用一次） *)
Lemma free_energy_align_decomp :
  forall pi : S -> R,
    Id (free_energy align_energy beta pi)
       (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))).
Proof.
  intro pi.
  (* free_energy 泛化常量为 λ 应用，unfold 不 β-归约 ⟹ 用 change（内核转换）展开形态 *)
  change (Id (plus (sum_over_S (fun s => mult (pi s) (align_energy s)))
                   (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))
             (plus (opp (state_value pi))
                   (mult beta (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))))).
  (* 逐点：pi·E_align = -(pi·r) - pi·(beta·log pi_ref)（Hext 用折叠的 align_energy） *)
  assert (Hext : Id (sum_over_S (fun s => mult (pi s) (align_energy s)))
                   (sum_over_S (fun s => minus (opp (mult (pi s) (reward s)))
                                              (mult (pi s) (mult beta (log (pi_ref s))))))).
  {
    apply sum_over_S_ext.
    intro s.
    unfold align_energy.
    assert (Hd : Id (mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))
                    (minus (mult (pi s) (opp (reward s))) (mult (pi s) (mult beta (log (pi_ref s))))))
      by exact (mult_minus_distr_l (pi s) (opp (reward s)) (mult beta (log (pi_ref s)))).
    assert (Ho : Id (mult (pi s) (opp (reward s))) (opp (mult (pi s) (reward s))))
      by exact (opp_mult_l (pi s) (reward s)).
    exact (id_trans Hd (id_cong (fun x => minus x (mult (pi s) (mult beta (log (pi_ref s))))) Ho)).
  }
  rewrite Hext.
  assert (Hsmin : Id (sum_over_S (fun s => minus (opp (mult (pi s) (reward s)))
                                                (mult (pi s) (mult beta (log (pi_ref s))))))
                     (minus (sum_over_S (fun s => opp (mult (pi s) (reward s))))
                            (sum_over_S (fun s => mult (pi s) (mult beta (log (pi_ref s)))))))
    by exact (sum_over_S_minus (fun s => opp (mult (pi s) (reward s)))
                               (fun s => mult (pi s) (mult beta (log (pi_ref s))))).
  rewrite Hsmin.
  assert (Hso : Id (sum_over_S (fun s => opp (mult (pi s) (reward s))))
                   (opp (state_value pi)))
    by (unfold state_value; exact (sum_opp (fun s => mult (pi s) (reward s)))).
  rewrite Hso.
  (* 提取 beta：Σ pi·(beta·log pi_ref) = beta·Σ pi·log pi_ref（mult 次序重组） *)
  assert (Hswp : forall s, Id (mult (pi s) (mult beta (log (pi_ref s))))
                            (mult beta (mult (pi s) (log (pi_ref s))))).
  { intro s.
    assert (H1 : Id (mult (pi s) (mult beta (log (pi_ref s)))) (mult (mult (pi s) beta) (log (pi_ref s))))
      by exact (mult_assoc (pi s) beta (log (pi_ref s))).
    assert (H2 : Id (mult (mult (pi s) beta) (log (pi_ref s))) (mult (mult beta (pi s)) (log (pi_ref s))))
      by exact (id_cong (fun x => mult x (log (pi_ref s))) (mult_comm (pi s) beta)).
    assert (H3 : Id (mult (mult beta (pi s)) (log (pi_ref s))) (mult beta (mult (pi s) (log (pi_ref s)))))
      by exact (id_sym (mult_assoc beta (pi s) (log (pi_ref s)))).
    exact (id_trans H1 (id_trans H2 H3)). }
  assert (Hext2 : Id (sum_over_S (fun s => mult (pi s) (mult beta (log (pi_ref s)))))
                     (sum_over_S (fun s => mult beta (mult (pi s) (log (pi_ref s))))))
    by exact (sum_over_S_ext _ _ Hswp).
  rewrite Hext2.
  assert (Hlin : Id (sum_over_S (fun s => mult beta (mult (pi s) (log (pi_ref s)))))
                    (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
    by exact (sum_over_S_linear beta (fun s => mult (pi s) (log (pi_ref s)))).
  rewrite Hlin.
  (* KL 展开：Σ pi·(log pi - log pi_ref) = Σ pi·log pi - Σ pi·log pi_ref *)
  assert (Hkl : Id (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))
                   (minus (sum_over_S (fun s => mult (pi s) (log (pi s))))
                          (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))).
  { assert (Hpt2 : forall s, Id (mult (pi s) (minus (log (pi s)) (log (pi_ref s))))
                               (minus (mult (pi s) (log (pi s))) (mult (pi s) (log (pi_ref s)))))
      by (intro s; exact (mult_minus_distr_l (pi s) (log (pi s)) (log (pi_ref s)))).
    assert (He : Id (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))
                    (sum_over_S (fun s => minus (mult (pi s) (log (pi s))) (mult (pi s) (log (pi_ref s))))))
      by exact (sum_over_S_ext _ _ Hpt2).
    exact (id_trans He (sum_over_S_minus (fun s => mult (pi s) (log (pi s)))
                                        (fun s => mult (pi s) (log (pi_ref s))))). }
  rewrite Hkl.
  (* mult 对减法的分配（assert + exact，避开 rewrite 对 minus 展开形态的失配） *)
  assert (Hmd : Id (mult beta (minus (sum_over_S (fun s => mult (pi s) (log (pi s))))
                                     (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                   (minus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))
                          (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))
    by exact (mult_minus_distr_l beta (sum_over_S (fun s => mult (pi s) (log (pi s))))
                                 (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))).
  assert (Hrhs : Id (plus (opp (state_value pi))
                          (mult beta (minus (sum_over_S (fun s => mult (pi s) (log (pi s))))
                                            (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))
                    (plus (opp (state_value pi))
                          (minus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))
                                 (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))))
    by exact (id_cong (fun x => plus (opp (state_value pi)) x) Hmd).
  rewrite Hrhs.
  (* 重组：((opp V) + (opp B')) + (mult beta A) = (opp V) + (mult beta A - B') *)
  assert (Hfin : Id (plus (plus (opp (state_value pi))
                                (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))
                          (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))
                   (plus (opp (state_value pi))
                         (minus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))
                                (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))).
  {
    unfold minus.
    assert (Ha : Id (plus (plus (opp (state_value pi))
                                (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))
                          (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))
                    (plus (opp (state_value pi))
                          (plus (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                                (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))))
      by exact (id_sym (plus_assoc (opp (state_value pi))
                                   (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                                   (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))).
    assert (Hb : Id (plus (opp (state_value pi))
                          (plus (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                                (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
                    (plus (opp (state_value pi))
                          (plus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))
                                (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))))))
      by exact (id_cong (fun x => plus (opp (state_value pi)) x)
                        (plus_comm (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                                   (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))).
    exact (id_trans Ha Hb).
  }
  exact Hfin.
Qed.

(* 对齐目标的精确优势分解（单步 bandit 下的恒等式，非近似） *)
Theorem align_objective_advantage_decomp :
  forall pi : S -> R,
    normalized pi -> positive_dist pi ->
    Id (align_objective pi)
       (plus (align_objective pi_ref)
             (minus (sum_over_S (fun s => mult (pi s) (advantage pi_ref s)))
                    (mult beta (kl_to_ref pi)))).
Proof.
  intros pi Hnpi Hppi.
  (* 1. align_objective 展开（取负）+ 自由能展开 *)
  unfold align_objective.
  assert (Hfe : Id (free_energy align_energy beta pi)
                   (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))
    by exact (free_energy_align_decomp pi).
  rewrite Hfe.
  (* 2. F(pi_ref) = -V(pi_ref)（KL 自为零） *)
  assert (Hfe_ref : Id (free_energy align_energy beta pi_ref) (opp (state_value pi_ref))).
  {
    assert (H : Id (free_energy align_energy beta pi_ref)
                   (plus (opp (state_value pi_ref)) (mult beta (kl_to_ref pi_ref))))
      by exact (free_energy_align_decomp pi_ref).
    rewrite H.
    assert (Hkl0 : Id (kl_to_ref pi_ref) zero) by exact (relative_entropy_self_zero pi_ref).
    assert (Hmz : Id (mult beta (kl_to_ref pi_ref)) zero)
      by exact (id_trans (id_cong (fun x => mult beta x) Hkl0) (mult_zero beta)).
    assert (Hzz : Id (plus (opp (state_value pi_ref)) (mult beta (kl_to_ref pi_ref)))
                     (plus (opp (state_value pi_ref)) zero))
      by exact (id_cong (fun x => plus (opp (state_value pi_ref)) x) Hmz).
    assert (Hpz : Id (plus (opp (state_value pi_ref)) zero) (opp (state_value pi_ref)))
      by exact (plus_zero (opp (state_value pi_ref))).
    exact (id_trans Hzz Hpz).
  }
  rewrite Hfe_ref.
  (* 3. 优势求和：Σ pi·A(pi_ref) = V(pi) - V(pi_ref) *)
  assert (Hadv : Id (sum_over_S (fun s => mult (pi s) (advantage pi_ref s)))
                    (minus (state_value pi) (state_value pi_ref))).
  {
    unfold advantage.
    assert (Hpt : forall s, Id (mult (pi s) (minus (reward s) (state_value pi_ref)))
                               (minus (mult (pi s) (reward s)) (mult (pi s) (state_value pi_ref))))
      by (intro s; exact (mult_minus_distr_l (pi s) (reward s) (state_value pi_ref))).
    assert (Hext : Id (sum_over_S (fun s => mult (pi s) (minus (reward s) (state_value pi_ref))))
                     (sum_over_S (fun s => minus (mult (pi s) (reward s)) (mult (pi s) (state_value pi_ref)))))
      by exact (sum_over_S_ext _ _ Hpt).
    rewrite Hext.
    assert (Hadd : Id (sum_over_S (fun s => minus (mult (pi s) (reward s)) (mult (pi s) (state_value pi_ref))))
                     (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                            (sum_over_S (fun s => mult (pi s) (state_value pi_ref)))))
      by exact (sum_over_S_minus _ _).
    rewrite Hadd.
    assert (Hv : Id (sum_over_S (fun s => mult (pi s) (state_value pi_ref))) (state_value pi_ref)).
    {
      assert (Hsw : Id (sum_over_S (fun s => mult (pi s) (state_value pi_ref)))
                       (sum_over_S (fun s => mult (state_value pi_ref) (pi s))))
        by exact (sum_over_S_ext _ _ (fun s => mult_comm (pi s) (state_value pi_ref))).
      rewrite Hsw.
      assert (Hlin : Id (sum_over_S (fun s => mult (state_value pi_ref) (pi s)))
                        (mult (state_value pi_ref) (sum_over_S pi)))
        by exact (sum_over_S_linear (state_value pi_ref) pi).
      rewrite Hlin.
      assert (Hv1 : Id (mult (state_value pi_ref) (sum_over_S pi)) (mult (state_value pi_ref) one))
        by exact (id_cong (fun x => mult (state_value pi_ref) x) Hnpi).
      rewrite Hv1.
      assert (Hm1 : Id (mult (state_value pi_ref) one) (state_value pi_ref))
        by exact (mult_one (state_value pi_ref)).
      exact Hm1.
    }
    rewrite Hv.
    reflexivity.
  }
  rewrite Hadv.
  (* 4. 减法双层合并：minus (minus V_pi V_ref) (beta·kl) = minus V_pi (plus V_ref (beta·kl)) *)
  rewrite (minus_minus_distr (state_value pi) (state_value pi_ref) (mult beta (kl_to_ref pi))).
  (* 5. 代数坍缩：opp(-V_ref) + (V_pi - (V_ref + beta·kl)) = -(opp V_pi + beta·kl) *)
  assert (Hfin : Id (plus (opp (opp (state_value pi_ref)))
                          (minus (state_value pi) (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))
                   (opp (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))).
  {
    unfold minus.
    assert (H1 : Id (plus (opp (opp (state_value pi_ref)))
                          (plus (state_value pi) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))))
                    (plus (state_value pi_ref)
                          (plus (state_value pi) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))))
      by exact (id_cong (fun x => plus x (plus (state_value pi) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))) (double_neg (state_value pi_ref))).
    assert (H2 : Id (plus (state_value pi_ref)
                          (plus (state_value pi) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))))
                    (plus (plus (state_value pi_ref) (state_value pi))
                          (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))))
      by exact (plus_assoc (state_value pi_ref) (state_value pi) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))).
    assert (H3 : Id (plus (plus (state_value pi_ref) (state_value pi))
                          (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))
                    (plus (plus (state_value pi) (state_value pi_ref))
                          (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))))
      by exact (id_cong (fun x => plus x (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi))))) (plus_comm (state_value pi_ref) (state_value pi))).
    assert (H4 : Id (plus (plus (state_value pi) (state_value pi_ref))
                          (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))
                    (plus (state_value pi)
                          (plus (state_value pi_ref)
                                (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))))
      by exact (id_sym (plus_assoc (state_value pi) (state_value pi_ref) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))).
    (* 消去 V_ref 与 -V_ref *)
    assert (H5 : Id (plus (state_value pi_ref) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))
                    (opp (mult beta (kl_to_ref pi)))).
    {
      assert (H5a : Id (plus (state_value pi_ref) (opp (plus (state_value pi_ref) (mult beta (kl_to_ref pi)))))
                       (plus (state_value pi_ref) (plus (opp (state_value pi_ref)) (opp (mult beta (kl_to_ref pi))))))
        by exact (id_cong (fun x => plus (state_value pi_ref) x) (opp_plus (state_value pi_ref) (mult beta (kl_to_ref pi)))).
      assert (H5b : Id (plus (state_value pi_ref) (plus (opp (state_value pi_ref)) (opp (mult beta (kl_to_ref pi)))))
                       (plus (plus (state_value pi_ref) (opp (state_value pi_ref))) (opp (mult beta (kl_to_ref pi)))))
        by exact (plus_assoc (state_value pi_ref) (opp (state_value pi_ref)) (opp (mult beta (kl_to_ref pi)))).
      assert (H5c : Id (plus (plus (state_value pi_ref) (opp (state_value pi_ref))) (opp (mult beta (kl_to_ref pi))))
                       (plus zero (opp (mult beta (kl_to_ref pi)))))
        by exact (id_cong (fun x => plus x (opp (mult beta (kl_to_ref pi)))) (plus_opp (state_value pi_ref))).
      assert (H5d : Id (plus zero (opp (mult beta (kl_to_ref pi)))) (opp (mult beta (kl_to_ref pi))))
        by exact (id_trans (plus_comm zero (opp (mult beta (kl_to_ref pi)))) (plus_zero (opp (mult beta (kl_to_ref pi))))).
      exact (id_trans H5a (id_trans H5b (id_trans H5c H5d))).
    }
    (* 目标右侧反向重组：plus V_pi (opp (beta·kl)) = opp (plus (opp V_pi) (beta·kl)) *)
    assert (H6 : Id (plus (state_value pi) (opp (mult beta (kl_to_ref pi))))
                    (opp (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))).
    {
      assert (H6a : Id (opp (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))
                       (plus (opp (opp (state_value pi))) (opp (mult beta (kl_to_ref pi)))))
        by exact (opp_plus (opp (state_value pi)) (mult beta (kl_to_ref pi))).
      assert (H6b : Id (plus (opp (opp (state_value pi))) (opp (mult beta (kl_to_ref pi))))
                       (plus (state_value pi) (opp (mult beta (kl_to_ref pi)))))
        by exact (id_cong (fun x => plus x (opp (mult beta (kl_to_ref pi)))) (double_neg (state_value pi))).
      exact (id_sym (id_trans H6a H6b)).
    }
    exact (id_trans (id_trans (id_trans (id_trans H1 H2) H3) (id_trans H4 (id_cong (fun x => plus (state_value pi) x) H5))) H6).
  }
  exact (id_sym Hfin).
Qed.

(* ============================================================ *)
(* PPO：裁剪代理目标（改进恒等式.txt 块 2）                     *)
(* ============================================================ *)
(* 策略梯度家族：重要性采样比率 r(s) = pi_star(s)/pi_old(s)，裁剪  *)
(* 到 [1-eps, 1+eps]（clip），PPO 目标取 min(r, clip(r)) 的期望。  *)
(* ppo_conservative 证明裁剪使目标保守（≤ 未裁剪 IS 目标——         *)
(* advantage ≥ 0 时逐点 min_le_l + le_mult_compat_r，经             *)
(* sum_over_S_le 提升）；clip_lower 给出裁剪的下界（r_max_le_r）。*)

Variable pi_old : S -> R.
Variable pi_old_pos : forall s, lt zero (pi_old s).
Variable pi_old_norm : Id (sum_over_S pi_old) one.
Variable advantage_fn : S -> R.
Variable advantage_nonneg : forall s, le zero (advantage_fn s).
Variable epsilon : R.
Variable epsilon_pos : lt zero epsilon.

(* 重要性采样比率：r(s) := pi_star(s)/pi_old(s) *)
Definition importance_ratio (s : S) : R :=
  mult (pi_star s) (inv_pos (pi_old s) (pi_old_pos s)).

(* 裁剪：clip(r) := max(min(r, 1+eps), 1-eps) *)
Definition clip (r : R) : R :=
  r_max (min r (plus one epsilon)) (minus one epsilon).

(* PPO 裁剪代理目标：E_pi_old[min(r, clip(r)) · advantage] *)
Definition ppo_objective : R :=
  sum_over_S (fun s => mult (pi_old s)
                         (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))).

(* 未裁剪 IS 目标（对照基线） *)
Definition is_objective : R :=
  sum_over_S (fun s => mult (pi_old s) (mult (importance_ratio s) (advantage_fn s))).

(* 裁剪下界：clip(r) ≥ 1 - eps（r_max_le_r） *)
Lemma clip_lower : forall r : R, le (minus one epsilon) (clip r).
Proof.
  intro r. unfold clip. apply r_max_le_r.
Qed.

(* PPO 保守性：min(r, clip(r)) ≤ r（min_le_l）⟹ ppo_objective ≤ is_objective。
   裁剪牺牲一点目标值换取方差稳定——"不优于未裁剪"的定量证明。 *)
Theorem ppo_conservative :
  le ppo_objective is_objective.
Proof.
  unfold ppo_objective, is_objective.
  apply sum_over_S_le.
  intro s.
  (* 逐点：pi_old·min(...)·adv ≤ pi_old·r·adv（min ≤ r 且各因子非负） *)
  assert (Hmin : le (min (importance_ratio s) (clip (importance_ratio s))) (importance_ratio s))
    by exact (min_le_l (importance_ratio s) (clip (importance_ratio s))).
  assert (Hinner : le (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))
                      (mult (importance_ratio s) (advantage_fn s)))
    by exact (le_mult_compat_weak (min (importance_ratio s) (clip (importance_ratio s))) (importance_ratio s) (advantage_fn s)
                                  (advantage_nonneg s) Hmin).
  assert (Hpi : le zero (pi_old s))
    by (apply (lt_le_iff _ _); left; apply pi_old_pos).
  exact (le_mult_compat_r (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))
                          (mult (importance_ratio s) (advantage_fn s)) Hpi Hinner).
Qed.

(* ============================================================ *)
(* T1.1：标准 PPO 代理目标与无前提保守性（2026-09-02 合入）    *)
(*   标准形式 min(r·A, clip(r)·A) ≤ r·A 是纯定义性的           *)
(*   （min_le_l，无需 advantage_nonneg）——把 §6 使用限制 2     *)
(*   的"形式非标准"改写为等价性引理 + 无前提保守性            *)
(* ============================================================ *)

(* 标准 PPO 代理目标：E_pi_old[min(r·A, clip(r)·A)] *)
Definition std_ppo_objective : R :=
  sum_over_S (fun s => mult (pi_old s)
    (min (mult (importance_ratio s) (advantage_fn s))
         (mult (clip (importance_ratio s)) (advantage_fn s)))).

(* 标准 PPO 保守性（无符号前提）：min(rA, clip(rA)) ≤ rA（min_le_l 定义性） *)
Theorem std_ppo_conservative : le std_ppo_objective is_objective.
Proof.
  unfold std_ppo_objective, is_objective.
  apply sum_over_S_le.
  intro s.
  assert (Hmin : le (min (mult (importance_ratio s) (advantage_fn s))
                         (mult (clip (importance_ratio s)) (advantage_fn s)))
                    (mult (importance_ratio s) (advantage_fn s)))
    by exact (min_le_l (mult (importance_ratio s) (advantage_fn s))
                       (mult (clip (importance_ratio s)) (advantage_fn s))).
  assert (Hpi : le zero (pi_old s))
    by (apply (lt_le_iff _ _); left; apply pi_old_pos).
  exact (le_mult_compat_r (pi_old s) (min (mult (importance_ratio s) (advantage_fn s))
                                          (mult (clip (importance_ratio s)) (advantage_fn s)))
                          (mult (importance_ratio s) (advantage_fn s)) Hpi Hmin).
Qed.

(* ============================================================ *)
(* RLHF 硬核扩展：策略比率 / 裁剪有界 / DPO 基线恢复            *)
(* （可微性代数闭环.txt 模块二节选，修正方向错误）              *)
(* ============================================================ *)

(* 策略比率：r(θ) = π(s)/π_old(s)（PPO/TRPO 相对更新的支撑） *)
Definition policy_ratio (pi pi_old : S -> R) (s : S) (Hpos : lt zero (pi_old s)) : R :=
  mult (pi s) (inv_pos (pi_old s) Hpos).

(* 裁剪函数：clip(r, low, high) = min(max(low, r), high)（标准 PPO 形态） *)
Definition ppo_clip (r low high : R) : R :=
  min (r_max low r) high.

(* PPO 代理目标（单步 bandit）：E[ min(r·A, clip(r)·A) ] *)
Definition ppo_surrogate (pi pi_old : S -> R) (adv : S -> R) (eps : R)
  (pi_old_pos : forall s, lt zero (pi_old s)) : R :=
  sum_over_S (fun s => mult (pi_old s)
    (min (mult (policy_ratio pi pi_old s (pi_old_pos s)) (adv s))
         (mult (ppo_clip (policy_ratio pi pi_old s (pi_old_pos s))
                         (minus one eps) (plus one eps))
               (adv s)))).

(* 未裁剪 IS 目标（带自由变量 pi）：E_pi_old[r·A]（ppo_surrogate 的对照基线） *)
Definition is_objective_of (pi pi_old : S -> R) (adv : S -> R)
  (pi_old_pos : forall s, lt zero (pi_old s)) : R :=
  sum_over_S (fun s => mult (pi_old s) (mult (policy_ratio pi pi_old s (pi_old_pos s)) (adv s))).


(* 裁剪上界：clip(r) ≤ high（min_le_r；下界 low ≤ clip(r) 需 min 的
   "最小元"性质，接口仅给 min_le_l/r，暂缺——见注记） *)
Lemma ppo_clip_upper :
  forall r low high, le (ppo_clip r low high) high.
Proof.
  intros r low high. unfold ppo_clip. apply min_le_r.
Qed.

(* DPO 隐式奖励的显式对数形式（与 dpo_implicit_reward 逐点恒等） *)
Definition dpo_reward_explicit (pi : S -> R) (s : S) : R :=
  mult beta (minus (log (pi s)) (log (pi_ref s))).

Theorem dpo_reward_is_implicit :
  forall pi s,
    Id (dpo_reward_explicit pi s) (dpo_implicit_reward pi s).
Proof.
  intros pi s. unfold dpo_reward_explicit, dpo_implicit_reward. reflexivity.
Qed.

(* DPO 奖励在 π* 处的闭式值：r*(s) = r(s) − β·log Z_align（配分基线偏移——
   DPO 隐式奖励精确恢复真实奖励，差一个与状态无关的常数项 β·log Z_align）。
   注：可微性代数闭环.txt 原稿误写为 = r(s)（Z_align 项不消失），此处修正。 *)
Theorem dpo_reward_recovers_up_to_baseline :
  forall s,
    Id (dpo_reward_explicit pi_star s)
       (plus (reward s) (opp (mult beta (log Z_align)))).
Proof.
  intro s.
  unfold dpo_reward_explicit.
  assert (Hlog : Id (log (pi_star s))
                    (plus (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)))))
    by exact (log_pi_star s).
  rewrite Hlog.
  (* 消去 log pi_ref：minus (plus A (plus B C)) B = plus A C *)
  assert (H1 : Id (minus (plus (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)))) (log (pi_ref s)))
                  (plus (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s)))).
  {
    unfold minus.
    assert (Ha : Id (plus (plus (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)))) (opp (log (pi_ref s))))
                    (plus (opp (log Z_align)) (plus (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s))) (opp (log (pi_ref s))))))
      by exact (id_sym (plus_assoc (opp (log Z_align)) (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s))) (opp (log (pi_ref s))))).
    assert (Hb : Id (plus (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s))) (opp (log (pi_ref s))))
                    (mult (inv_pos beta beta_pos) (reward s))).
    {
      assert (Hb1 : Id (plus (plus (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s))) (opp (log (pi_ref s))))
                       (plus (log (pi_ref s)) (plus (mult (inv_pos beta beta_pos) (reward s)) (opp (log (pi_ref s))))))
        by exact (id_sym (plus_assoc (log (pi_ref s)) (mult (inv_pos beta beta_pos) (reward s)) (opp (log (pi_ref s))))).
      assert (Hb2 : Id (plus (log (pi_ref s)) (plus (mult (inv_pos beta beta_pos) (reward s)) (opp (log (pi_ref s)))))
                       (plus (log (pi_ref s)) (plus (opp (log (pi_ref s))) (mult (inv_pos beta beta_pos) (reward s)))))
        by exact (id_cong (fun z => plus (log (pi_ref s)) z) (plus_comm (mult (inv_pos beta beta_pos) (reward s)) (opp (log (pi_ref s))))).
      assert (Hb3 : Id (plus (log (pi_ref s)) (plus (opp (log (pi_ref s))) (mult (inv_pos beta beta_pos) (reward s))))
                       (plus (plus (log (pi_ref s)) (opp (log (pi_ref s)))) (mult (inv_pos beta beta_pos) (reward s))))
        by exact (plus_assoc (log (pi_ref s)) (opp (log (pi_ref s))) (mult (inv_pos beta beta_pos) (reward s))).
      assert (Hb4 : Id (plus (plus (log (pi_ref s)) (opp (log (pi_ref s)))) (mult (inv_pos beta beta_pos) (reward s)))
                       (mult (inv_pos beta beta_pos) (reward s)))
        by exact (id_trans (id_cong (fun z => plus z (mult (inv_pos beta beta_pos) (reward s))) (plus_opp (log (pi_ref s))))
                           (id_trans (plus_comm zero (mult (inv_pos beta beta_pos) (reward s)))
                                     (plus_zero (mult (inv_pos beta beta_pos) (reward s))))).
      exact (id_trans Hb1 (id_trans Hb2 (id_trans Hb3 Hb4))).
    }
    exact (id_trans Ha (id_cong (fun z => plus (opp (log Z_align)) z) Hb)).
  }
  rewrite H1.
  assert (H2 : Id (mult beta (plus (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s))))
                  (plus (mult beta (opp (log Z_align))) (mult beta (mult (inv_pos beta beta_pos) (reward s)))))
    by exact (distrib beta (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s))).
  rewrite H2.
  assert (H3 : Id (mult beta (mult (inv_pos beta beta_pos) (reward s))) (reward s)).
  {
    assert (H3a : Id (mult beta (mult (inv_pos beta beta_pos) (reward s))) (mult (mult beta (inv_pos beta beta_pos)) (reward s)))
      by exact (mult_assoc beta (inv_pos beta beta_pos) (reward s)).
    assert (H3b : Id (mult (mult beta (inv_pos beta beta_pos)) (reward s)) (mult one (reward s)))
      by exact (id_cong (fun z => mult z (reward s)) (inv_pos_correct beta beta_pos)).
    assert (H3c : Id (mult one (reward s)) (reward s))
      by exact (id_trans (mult_comm one (reward s)) (mult_one (reward s))).
    exact (id_trans H3a (id_trans H3b H3c)).
  }
  rewrite H3.
  assert (H4 : Id (mult beta (opp (log Z_align))) (opp (mult beta (log Z_align))))
    by exact (opp_mult_l beta (log Z_align)).
  rewrite H4.
  assert (H5 : Id (plus (opp (mult beta (log Z_align))) (reward s))
                  (plus (reward s) (opp (mult beta (log Z_align)))))
    by exact (plus_comm (opp (mult beta (log Z_align))) (reward s)).
  exact H5.
Qed.

(* 共同被加项消去：minus (plus A B) (plus A C) = minus B C（纯环代数） *)
Lemma minus_plus_common : forall A B C : R,
  Id (minus (plus A B) (plus A C)) (minus B C).
Proof.
  intros A B C.
  unfold minus.
  (* plus (plus A B) (opp (plus A C)) = plus (plus A B) (plus (opp A) (opp C)) *)
  assert (H1 : Id (plus (plus A B) (opp (plus A C)))
                  (plus (plus A B) (plus (opp A) (opp C))))
    by exact (id_cong (fun x => plus (plus A B) x) (opp_plus A C)).
  (* plus_swap_mid：plus (plus A B) (plus (opp A) (opp C)) = plus (plus A (opp A)) (plus B (opp C)) *)
  assert (H2 : Id (plus (plus A B) (plus (opp A) (opp C)))
                  (plus (plus A (opp A)) (plus B (opp C))))
    by exact (plus_swap_mid A B (opp A) (opp C)).
  assert (H3 : Id (plus (plus A (opp A)) (plus B (opp C)))
                  (plus zero (plus B (opp C))))
    by exact (id_cong (fun x => plus x (plus B (opp C))) (plus_opp A)).
  assert (H4 : Id (plus zero (plus B (opp C))) (plus B (opp C)))
    by exact (id_trans (plus_comm zero (plus B (opp C))) (plus_zero (plus B (opp C)))).
  exact (id_trans H1 (id_trans H2 (id_trans H3 H4))).
Qed.

(* DPO 隐式奖励的相对差分精确恢复：r_DPO(s) − r_DPO(s') = r(s) − r(s')。
   （配分函数基线 β·log Z_align 在差分中严格消去——DPO 隐式奖励的
     相对值无偏。非平凡：dpo_reward_recovers_up_to_baseline 给出
     r_DPO(π*,s) = r(s) + opp(β·log Z)，两状态相减后共同项消去。） *)
Theorem dpo_reward_relative_exact :
  forall s s',
    Id (minus (dpo_implicit_reward pi_star s) (dpo_implicit_reward pi_star s'))
       (minus (reward s) (reward s')).
Proof.
  intros s s'.
  (* 用已证闭式：dpo_reward_explicit pi_star s = r(s) + opp(beta·log Z) *)
  assert (Hrec_s : Id (dpo_reward_explicit pi_star s)
                      (plus (reward s) (opp (mult beta (log Z_align)))))
    by exact (dpo_reward_recovers_up_to_baseline s).
  assert (Hrec_s' : Id (dpo_reward_explicit pi_star s')
                       (plus (reward s') (opp (mult beta (log Z_align)))))
    by exact (dpo_reward_recovers_up_to_baseline s').
  (* dpo_reward_explicit = dpo_implicit_reward（同义） *)
  assert (Himp_s : Id (dpo_implicit_reward pi_star s) (dpo_reward_explicit pi_star s))
    by exact (id_sym (dpo_reward_is_implicit pi_star s)).
  assert (Himp_s' : Id (dpo_implicit_reward pi_star s') (dpo_reward_explicit pi_star s'))
    by exact (id_sym (dpo_reward_is_implicit pi_star s')).
  (* LHS 替换为 r(s) − r(s')（经共同项消去） *)
  assert (Hmain : Id (minus (dpo_reward_explicit pi_star s) (dpo_reward_explicit pi_star s'))
                     (minus (reward s) (reward s'))).
  {
    assert (H1 : Id (minus (dpo_reward_explicit pi_star s) (dpo_reward_explicit pi_star s'))
                    (minus (plus (reward s) (opp (mult beta (log Z_align))))
                           (plus (reward s') (opp (mult beta (log Z_align))))))
      by exact (id_cong2 minus Hrec_s Hrec_s').
    (* 共同项 opp(beta·log Z) 换到左边，匹配 minus_plus_common *)
    assert (H1a : Id (minus (plus (reward s) (opp (mult beta (log Z_align))))
                            (plus (reward s') (opp (mult beta (log Z_align)))))
                     (minus (plus (opp (mult beta (log Z_align))) (reward s))
                            (plus (opp (mult beta (log Z_align))) (reward s'))))
      by exact (id_cong2 minus (plus_comm (reward s) (opp (mult beta (log Z_align))))
                                (plus_comm (reward s') (opp (mult beta (log Z_align))))).
    assert (H2 : Id (minus (plus (opp (mult beta (log Z_align))) (reward s))
                           (plus (opp (mult beta (log Z_align))) (reward s')))
                    (minus (reward s) (reward s')))
      by exact (minus_plus_common (opp (mult beta (log Z_align))) (reward s) (reward s')).
    exact (id_trans H1 (id_trans H1a H2)).
  }
  (* 替换回 dpo_implicit_reward 形式 *)
  assert (Hlhs : Id (minus (dpo_implicit_reward pi_star s) (dpo_implicit_reward pi_star s'))
                    (minus (dpo_reward_explicit pi_star s) (dpo_reward_explicit pi_star s')))
    by exact (id_cong2 minus Himp_s Himp_s').
  exact (id_trans Hlhs Hmain).
Qed.

(* ============================================================ *)
(* DPO 差分结构（聚焦AI算法.txt 模块 4 补充）：                 *)
(*   1) minus_rearrange_four：四元差分重排                       *)
(*      (a−b) − (c−d) = (a−c) − (b−d)（纯环代数）              *)
(*   2) dpo_reward_diff_is_log_ratio_diff：一般策略 pi 的 DPO    *)
(*      隐式奖励差分分解为策略对数比率差与参考策略对数比率差    *)
(*      的双重差分——DPO/PPO 梯度方向的代数结构。                *)
(* ------------------------------------------------------------ *)

(* 四元差分重排：(a−b) − (c−d) = (a−c) − (b−d)（非平凡代数链：
   unfold minus + opp_plus + double_neg + plus_assoc/comm 重排） *)
Lemma minus_rearrange_four : forall a b c d : R,
  Id (minus (minus a b) (minus c d)) (minus (minus a c) (minus b d)).
Proof.
  intros a b c d.
  unfold minus.
  (* LHS: plus (plus a (opp b)) (opp (plus c (opp d)))
     = plus (plus a (opp b)) (plus (opp c) d)（opp_plus + double_neg）
     = a + ((−b) + (−c)) + d 重排为 (a−c) + ((−b)+d) = (a−c) − (b−d) *)
  assert (H1 : Id (plus (plus a (opp b)) (opp (plus c (opp d))))
                  (plus (plus a (opp b)) (plus (opp c) d)))
    by exact (id_cong (fun x => plus (plus a (opp b)) x)
                      (id_trans (opp_plus c (opp d))
                                (id_cong (fun y => plus (opp c) y) (double_neg d)))).
  assert (H2 : Id (plus (plus a (opp b)) (plus (opp c) d))
                  (plus (plus a (opp c)) (plus (opp b) d)))
    by exact (plus_swap_mid a (opp b) (opp c) d).
  assert (H3 : Id (plus (plus a (opp c)) (plus (opp b) d))
                  (plus (plus a (opp c)) (opp (plus b (opp d)))))
    by exact (id_cong (fun x => plus (plus a (opp c)) x)
                      (id_trans (id_cong (fun y => plus (opp b) y) (id_sym (double_neg d)))
                                (id_sym (opp_plus b (opp d))))).
  exact (id_trans H1 (id_trans H2 H3)).
Qed.

(* DPO 隐式奖励差分 = beta·(策略对数比率差 − 参考对数比率差)：
   r_DPO(pi,s) − r_DPO(pi,s') = beta·((log pi(s) − log pi(s'))
   − (log pi_ref(s) − log pi_ref(s')))。
   非平凡：mult_minus_distr_l 提取 beta + minus_rearrange_four 重排。 *)
Theorem dpo_reward_diff_is_log_ratio_diff :
  forall (pi : S -> R) (s s' : S),
    Id (minus (dpo_implicit_reward pi s) (dpo_implicit_reward pi s'))
       (mult beta (minus (minus (log (pi s)) (log (pi s')))
                         (minus (log (pi_ref s)) (log (pi_ref s'))))).
Proof.
  intros pi s s'.
  unfold dpo_implicit_reward.
  (* beta·(A−B) − beta·(C−D) = beta·((A−B)−(C−D)) *)
  assert (H1 : Id (minus (mult beta (minus (log (pi s)) (log (pi_ref s))))
                         (mult beta (minus (log (pi s')) (log (pi_ref s')))))
                  (mult beta (minus (minus (log (pi s)) (log (pi_ref s)))
                                    (minus (log (pi s')) (log (pi_ref s'))))))
    by exact (id_sym (mult_minus_distr_l beta (minus (log (pi s)) (log (pi_ref s))) (minus (log (pi s')) (log (pi_ref s'))))).
  rewrite H1.
  (* 四元重排：(a−b)−(c−d) = (a−c)−(b−d)，a=log pi s, b=log pi_ref s, c=log pi s', d=log pi_ref s' *)
  assert (H2 : Id (minus (minus (log (pi s)) (log (pi_ref s)))
                         (minus (log (pi s')) (log (pi_ref s'))))
                  (minus (minus (log (pi s)) (log (pi s')))
                         (minus (log (pi_ref s)) (log (pi_ref s')))))
    by exact (minus_rearrange_four (log (pi s)) (log (pi_ref s)) (log (pi s')) (log (pi_ref s'))).
  rewrite H2.
  reflexivity.
Qed.

(* ============================================================ *)
(* PPO/TRPO 单调改进与 KL 控制（单调改进与hentic KL 控制.txt 块1）*)
(* ============================================================ *)
(* 1) advantage_expectation_zero：E_pi[A_pi] = 0（优势期望自零；  *)
(*    TRPO/PPO 代理目标的基线性质；非平凡：求和线性 + 常数提取   *)
(*    + 归一化坍缩）                                            *)
(* 2) exact_improvement_identity：从 π_ref 出发的精确改进恒等式  *)
(*    J(π_new) − J(π_ref) = E_{π_new}[A_ref] − β·KL(π_new‖π_ref) *)
(*    （经 align_objective_advantage_decomp；KL 项对 π_ref，非    *)
(*    对 π_old——注意原草案概念有误）                            *)
(* 3) ppo_monotonic_improvement：E[A_ref] ≥ β·KL ⟹ J(π_ref) ≤    *)
(*    J(π_new)（单调改进的充分条件）                             *)
(* ------------------------------------------------------------ *)

(* 优势期望自零：Σ_s pi(s)·A_pi(s) = 0（pi 归一化）。
   证明：A_pi(s) = r(s) − V(pi)，Σ pi·r = V(pi)（state_value 定义），
   Σ pi·V(pi) = V(pi)·Σ pi = V(pi)（常数提取 + 归一化），相减为零。 *)
Theorem advantage_expectation_zero :
  forall pi : S -> R,
    normalized pi ->
    Id (sum_over_S (fun s => mult (pi s) (advantage pi s))) zero.
Proof.
  intros pi Hnorm.
  unfold advantage, state_value.
  (* 逐点：pi·(r − V) = pi·r − pi·V *)
  assert (Hpt : forall s, Id (mult (pi s) (minus (reward s) (sum_over_S (fun t => mult (pi t) (reward t)))))
                            (minus (mult (pi s) (reward s))
                                   (mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t))))))
    by (intro s; exact (mult_minus_distr_l (pi s) (reward s) (sum_over_S (fun t => mult (pi t) (reward t))))).
  assert (Hext : Id (sum_over_S (fun s => mult (pi s) (minus (reward s) (sum_over_S (fun t => mult (pi t) (reward t))))))
                    (sum_over_S (fun s => minus (mult (pi s) (reward s)) (mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t)))))))
    by exact (sum_over_S_ext _ _ Hpt).
  rewrite Hext.
  assert (Hadd : Id (sum_over_S (fun s => minus (mult (pi s) (reward s)) (mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t))))))
                    (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                           (sum_over_S (fun s => mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t)))))))
    by exact (sum_over_S_minus _ _).
  rewrite Hadd.
  (* Σ pi·V = V·Σ pi = V（常数提取 + 归一化） *)
  assert (Hsw : forall s, Id (mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t))))
                            (mult (sum_over_S (fun t => mult (pi t) (reward t))) (pi s)))
    by (intro s; apply mult_comm).
  assert (Hlin : Id (sum_over_S (fun s => mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t)))))
                    (mult (sum_over_S (fun t => mult (pi t) (reward t))) (sum_over_S pi))).
  {
    assert (Hsw_sum : Id (sum_over_S (fun s => mult (pi s) (sum_over_S (fun t => mult (pi t) (reward t)))))
                         (sum_over_S (fun s => mult (sum_over_S (fun t => mult (pi t) (reward t))) (pi s))))
      by exact (sum_over_S_ext _ _ Hsw).
    rewrite Hsw_sum.
    exact (sum_over_S_linear (sum_over_S (fun t => mult (pi t) (reward t))) pi).
  }
  rewrite Hlin.
  assert (Hm1 : Id (mult (sum_over_S (fun t => mult (pi t) (reward t))) one)
                   (sum_over_S (fun t => mult (pi t) (reward t))))
    by exact (mult_one (sum_over_S (fun t => mult (pi t) (reward t)))).
  (* minus (Σpi·r) (Σpi·r) = 0 *)
  assert (Hfinal : Id (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                             (mult (sum_over_S (fun t => mult (pi t) (reward t))) (sum_over_S pi)))
                      zero).
  {
    unfold minus.
    assert (Hid2 : Id (mult (sum_over_S (fun t => mult (pi t) (reward t))) (sum_over_S pi))
                      (sum_over_S (fun t => mult (pi t) (reward t))))
      by exact (id_trans (id_cong (fun x => mult (sum_over_S (fun t => mult (pi t) (reward t))) x) Hnorm) Hm1).
    assert (Hcancel : Id (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                               (opp (sum_over_S (fun t => mult (pi t) (reward t)))))
                         zero)
      by exact (plus_opp (sum_over_S (fun t => mult (pi t) (reward t)))).
    exact (id_trans (id_cong (fun x => plus (sum_over_S (fun s => mult (pi s) (reward s))) (opp x)) Hid2) Hcancel).
  }
  exact Hfinal.
Qed.

(* 从 π_ref 出发的精确改进恒等式：
   J(π_new) − J(π_ref) = E_{π_new}[A_ref] − β·KL(π_new‖π_ref)。
   非平凡：align_objective_advantage_decomp + 优势自零消去（π_ref
   处的 E_{π_ref}[A_ref] = 0）+ KL 自零（KL(π_ref‖π_ref) = 0）。 *)
Theorem exact_improvement_identity :
  forall pi_new : S -> R,
    normalized pi_new -> positive_dist pi_new ->
    Id (minus (align_objective pi_new) (align_objective pi_ref))
       (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
              (mult beta (kl_to_ref pi_new))).
Proof.
  intros pi_new Hnorm Hpos.
  (* J(pi_new) = J(pi_ref) + E_new[A_ref] − beta·KL(pi_new‖pi_ref) *)
  assert (Hnew : Id (align_objective pi_new)
                    (plus (align_objective pi_ref)
                          (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                                 (mult beta (kl_to_ref pi_new)))))
    by exact (align_objective_advantage_decomp pi_new Hnorm Hpos).
  (* 两侧减 J(pi_ref)：minus (J_ref + X) J_ref = X（minus_plus_cancel_r） *)
  assert (Hdiff : Id (minus (align_objective pi_new) (align_objective pi_ref))
                     (minus (plus (align_objective pi_ref)
                                  (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                                         (mult beta (kl_to_ref pi_new))))
                            (align_objective pi_ref)))
    by exact (id_cong (fun x => minus x (align_objective pi_ref)) Hnew).
  assert (Hcancel : Id (minus (plus (align_objective pi_ref)
                                    (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                                           (mult beta (kl_to_ref pi_new))))
                              (align_objective pi_ref))
                       (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                              (mult beta (kl_to_ref pi_new))))
    by exact (minus_plus_cancel_r (align_objective pi_ref)
                                  (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                                         (mult beta (kl_to_ref pi_new)))).
  exact (id_trans Hdiff Hcancel).
Qed.

(* PPO 单调改进：E_{π_new}[A_ref] − β·KL(π_new‖π_ref) ≥ 0
   ⟹ J(π_ref) ≤ J(π_new)（代理优势非负 ⟹ 真实目标改进）。
   非平凡：精确恒等式 + le_minus_nonneg（差分非负 ⟹ 被减数 ≤ 减数）。 *)
Theorem ppo_monotonic_improvement :
  forall pi_new : S -> R,
    normalized pi_new -> positive_dist pi_new ->
    le zero (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                   (mult beta (kl_to_ref pi_new))) ->
    le (align_objective pi_ref) (align_objective pi_new).
Proof.
  intros pi_new Hnorm Hpos Hsur.
  assert (Hid : Id (minus (align_objective pi_new) (align_objective pi_ref))
                   (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                          (mult beta (kl_to_ref pi_new))))
    by exact (exact_improvement_identity pi_new Hnorm Hpos).
  (* 0 ≤ J_new − J_ref（经 Hid 替换为代理优势差） *)
  assert (Hd : le zero (minus (align_objective pi_new) (align_objective pi_ref))).
  { rewrite Hid. exact Hsur. }
  (* le J_ref J_new：J_ref ≤ J_ref + (J_new − J_ref) = J_new（le_plus_nonneg_r + minus_plus_cancel） *)
  apply (le_id_r (align_objective pi_ref)
                 (plus (align_objective pi_ref) (minus (align_objective pi_new) (align_objective pi_ref)))
                 (align_objective pi_new)
                 (minus_plus_cancel (align_objective pi_ref) (align_objective pi_new))).
  exact (le_plus_nonneg_r (align_objective pi_ref) (minus (align_objective pi_new) (align_objective pi_ref)) Hd).
Qed.

(* KL 惩罚充分条件：若 KL(π_new‖π_ref) ≤ eps 且 E_{π_new}[A_ref] ≥ β·eps，
   则 J(π_ref) ≤ J(π_new)。
   非平凡：E − β·KL ≥ E − β·eps ≥ 0（le_plus_compat + opp_le_compat
   + le_mult_compat_r + le_minus_nonneg）。 *)
Theorem kl_penalty_sufficient :
  forall (pi_new : S -> R) (eps : R),
    normalized pi_new -> positive_dist pi_new ->
    le (kl_to_ref pi_new) eps ->
    le (mult beta eps) (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s))) ->
    le (align_objective pi_ref) (align_objective pi_new).
Proof.
  intros pi_new eps Hnorm Hpos Hkl Hadv.
  apply (ppo_monotonic_improvement pi_new Hnorm Hpos).
  (* 目标：0 ≤ E − β·KL。由 Hadv: β·eps ≤ E 且 Hkl: KL ≤ eps。 *)
  (* 链：0 ≤ E − β·eps ≤ E − β·KL（KL ≤ eps ⟹ −β·eps ≤ −β·KL） *)
  assert (H1 : le (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                         (mult beta eps))
                  (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                         (mult beta (kl_to_ref pi_new)))).
  {
    unfold minus.
    apply le_plus_compat.
    - apply le_refl.
    - apply opp_le_compat.
      apply (le_mult_compat_r beta (kl_to_ref pi_new) eps).
      + apply (lt_le_iff _ _). left. exact beta_pos.
      + exact Hkl.
  }
  assert (H2 : le zero (minus (sum_over_S (fun s => mult (pi_new s) (advantage pi_ref s)))
                              (mult beta eps))).
  { apply le_minus_nonneg. exact Hadv. }
  exact (le_trans _ _ _ H2 H1).
Qed.

(* ============================================================ *)
(* PPO 差距恒等式（RLHF 对齐扩展.txt 块 3）                     *)
(* ============================================================ *)
(* 1) ppo_gap_exact：is_objective − ppo_objective 精确等于被裁剪  *)
(*    部分（r − min(r, clip(r))）的期望。裁剪只发生在比率偏离     *)
(*    [1−ε, 1+ε] 时——差距的精确代数刻画。                      *)
(* 2) ppo_gap_nonneg：差距非负（ppo_conservative 的直接推论）。   *)
(* ------------------------------------------------------------ *)

(* PPO 差距恒等式：IS − CLIP = E[pi_old·(r − min(r, clip(r)))·adv]。
   非平凡：逐点 mult_minus_distr_l 两层展开 + 求和线性化。 *)
Theorem ppo_gap_exact :
  Id (minus is_objective ppo_objective)
     (sum_over_S (fun s => mult (pi_old s)
                            (mult (minus (importance_ratio s)
                                         (min (importance_ratio s) (clip (importance_ratio s))))
                                  (advantage_fn s)))).
Proof.
  unfold is_objective, ppo_objective.
  (* 逐点：pi_old·r·adv − pi_old·min·adv = pi_old·(r − min)·adv *)
  assert (Hpt : forall s, Id (minus (mult (pi_old s) (mult (importance_ratio s) (advantage_fn s)))
                                    (mult (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))))
                             (mult (pi_old s) (mult (minus (importance_ratio s)
                                                           (min (importance_ratio s) (clip (importance_ratio s))))
                                                    (advantage_fn s)))).
  {
    intro s.
    (* 外层：pi_old·X − pi_old·Y = pi_old·(X − Y)，X = r·adv, Y = min·adv。
       mult_minus_distr_l 方向是 mult a (minus b c) = minus (mult a b) (mult a c)，
       需要反向（id_sym）。 *)
    assert (H1 : Id (minus (mult (pi_old s) (mult (importance_ratio s) (advantage_fn s)))
                           (mult (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))))
                    (mult (pi_old s) (minus (mult (importance_ratio s) (advantage_fn s))
                                            (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))))
      by exact (id_sym (mult_minus_distr_l (pi_old s) (mult (importance_ratio s) (advantage_fn s))
                                           (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))).
    (* 内层：r·adv − min·adv = (r − min)·adv。
       无 mult_minus_distr_r，用 mult_comm 换序 + mult_minus_distr_l：
       先证反向 (r − min)·adv = r·adv − min·adv，再 id_sym。 *)
    assert (H2 : Id (minus (mult (importance_ratio s) (advantage_fn s))
                           (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))
                    (mult (minus (importance_ratio s) (min (importance_ratio s) (clip (importance_ratio s))))
                          (advantage_fn s))).
    {
      apply id_sym.
      (* (r − min)·adv = adv·(r − min)（mult_comm） *)
      assert (Hsw1 : Id (mult (minus (importance_ratio s) (min (importance_ratio s) (clip (importance_ratio s)))) (advantage_fn s))
                        (mult (advantage_fn s) (minus (importance_ratio s) (min (importance_ratio s) (clip (importance_ratio s))))))
        by (apply mult_comm).
      (* adv·(r − min) = adv·r − adv·min（mult_minus_distr_l 正向） *)
      assert (Hsw2 : Id (mult (advantage_fn s) (minus (importance_ratio s) (min (importance_ratio s) (clip (importance_ratio s)))))
                        (minus (mult (advantage_fn s) (importance_ratio s))
                               (mult (advantage_fn s) (min (importance_ratio s) (clip (importance_ratio s))))))
        by exact (mult_minus_distr_l (advantage_fn s) (importance_ratio s) (min (importance_ratio s) (clip (importance_ratio s)))).
      (* adv·r = r·adv，adv·min = min·adv（mult_comm） *)
      assert (Hsw3 : Id (minus (mult (advantage_fn s) (importance_ratio s))
                               (mult (advantage_fn s) (min (importance_ratio s) (clip (importance_ratio s)))))
                        (minus (mult (importance_ratio s) (advantage_fn s))
                               (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s))))
        by exact (id_cong2 minus (mult_comm (advantage_fn s) (importance_ratio s))
                                (mult_comm (advantage_fn s) (min (importance_ratio s) (clip (importance_ratio s))))).
      exact (id_trans Hsw1 (id_trans Hsw2 Hsw3)).
    }
    exact (id_trans H1 (id_cong (fun x => mult (pi_old s) x) H2)).
  }
  (* 求和：Σ(minus A B) = minus (Σ A) (Σ B)，经 sum_over_S_ext 换逐点 *)
  assert (Hstep1 : Id (sum_over_S (fun s => minus (mult (pi_old s) (mult (importance_ratio s) (advantage_fn s)))
                                                 (mult (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))))
                      (sum_over_S (fun s => mult (pi_old s) (mult (minus (importance_ratio s)
                                                                         (min (importance_ratio s) (clip (importance_ratio s))))
                                                                  (advantage_fn s)))))
    by exact (sum_over_S_ext _ _ Hpt).
  (* LHS：minus (Σ pi_old·r·adv) (Σ pi_old·min·adv) = 目标 Σ 形态 *)
  assert (Hlhs : Id (minus (sum_over_S (fun s => mult (pi_old s) (mult (importance_ratio s) (advantage_fn s))))
                           (sum_over_S (fun s => mult (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))))
                    (sum_over_S (fun s => mult (pi_old s) (mult (minus (importance_ratio s)
                                                                       (min (importance_ratio s) (clip (importance_ratio s))))
                                                                (advantage_fn s)))))
    by exact (id_trans (id_sym (sum_over_S_minus (fun s => mult (pi_old s) (mult (importance_ratio s) (advantage_fn s)))
                                                 (fun s => mult (pi_old s) (mult (min (importance_ratio s) (clip (importance_ratio s))) (advantage_fn s)))))
                       Hstep1).
  exact Hlhs.
Qed.

(* PPO 差距非负：is_objective ≥ ppo_objective（裁剪损失目标值，
   由 ppo_conservative + le_minus_nonneg 直接推出）。 *)
Theorem ppo_gap_nonneg :
  le zero (minus is_objective ppo_objective).
Proof.
  apply le_minus_nonneg.
  exact ppo_conservative.
Qed.

(* ============================================================ *)
(* 偏好对直接优化（偏好对直接优化.txt：DPO 对损失构造性代数）   *)
(* ============================================================ *)
(* 1) dpo_pair_loss：DPO 单对损失 = log(1 + e^{−(r_imp(w)−r_imp(l))}) *)
(*    分母正性（构造性：one_pos + exp_neg_pos）                  *)
(* 2) pi_star_implicit_reward_diff：π* 的隐式奖励差分 = 真实奖励  *)
(*    差分（经已证 dpo_reward_relative_exact——Z_align/π_ref 消去）*)
(* 3) dpo_pair_loss_at_star：π* 处损失退化为真实奖励差分的        *)
(*    Sigmoid 交叉熵                                            *)
(* ------------------------------------------------------------ *)

Variable Preference : Set.
Variable pref_win  : Preference -> S.
Variable pref_lose : Preference -> S.

(* 隐式奖励差分：DPO 的核心驱动量（策略比率的对数 odds） *)
Definition implicit_reward_diff (pi : S -> R) (pref : Preference) : R :=
  minus (dpo_implicit_reward pi (pref_win pref))
        (dpo_implicit_reward pi (pref_lose pref)).

(* DPO 单对损失：L(π; y_w, y_l) = log(1 + e^{−(r_imp(y_w) − r_imp(y_l))}) *)
Definition dpo_pair_loss (pi : S -> R) (pref : Preference) : R :=
  log (plus one (exp_neg (implicit_reward_diff pi pref))).

(* 分母严格正性：保证 log 良定义（构造性见证） *)
Lemma dpo_pair_loss_denom_pos : forall (pi : S -> R) (pref : Preference),
  lt zero (plus one (exp_neg (implicit_reward_diff pi pref))).
Proof.
  intros pi pref.
  apply plus_positive.
  - exact one_pos.
  - apply exp_neg_pos.
Qed.

(* π* 的隐式奖励差分 = 真实奖励差分（Z_align/π_ref 在差分中消去）。
   证明：经已证 dpo_reward_relative_exact（r_DPO(π*,s) − r_DPO(π*,s') = r(s) − r(s')）。 *)
Theorem pi_star_implicit_reward_diff : forall pref : Preference,
  Id (implicit_reward_diff pi_star pref)
     (minus (reward (pref_win pref)) (reward (pref_lose pref))).
Proof.
  intro pref.
  unfold implicit_reward_diff.
  exact (dpo_reward_relative_exact (pref_win pref) (pref_lose pref)).
Qed.

(* π* 处单对损失 = 真实奖励差分的 Sigmoid 交叉熵 *)
Definition dpo_pair_loss_star (pref : Preference) : R :=
  log (plus one (exp_neg (minus (reward (pref_win pref)) (reward (pref_lose pref))))).

Theorem dpo_pair_loss_at_star : forall pref : Preference,
  Id (dpo_pair_loss pi_star pref) (dpo_pair_loss_star pref).
Proof.
  intro pref.
  unfold dpo_pair_loss, dpo_pair_loss_star.
  assert (Hdiff : Id (implicit_reward_diff pi_star pref)
                     (minus (reward (pref_win pref)) (reward (pref_lose pref))))
    by exact (pi_star_implicit_reward_diff pref).
  exact (id_cong (fun x => log (plus one (exp_neg x))) Hdiff).
Qed.

(* 数据集级聚合：总损失 = 单对损失的 fold *)
Variable pref_dataset : list Preference.

Definition dpo_total_loss (pi : S -> R) : R :=
  fold_right (fun pref acc => plus (dpo_pair_loss pi pref) acc) zero pref_dataset.

Definition dpo_total_loss_star : R :=
  fold_right (fun pref acc => plus (dpo_pair_loss_star pref) acc) zero pref_dataset.

(* fold 外延性（Set 层工具引理） *)
Lemma fold_right_ext {A B : Set} (f g : A -> B -> B) (l : list A) (b : B) :
  (forall a b', Id (f a b') (g a b')) -> Id (fold_right f b l) (fold_right g b l).
Proof.
  intros Hfg. induction l as [| a rest IH]; simpl.
  - reflexivity.
  - (* 目标：Id (f a (fold f)) (g a (fold g))：Hfg a 与 IH 组合 *)
    apply (id_trans (Hfg a (fold_right f b rest))).
    exact (id_cong (fun x => g a x) IH).
Qed.

(* π* 处总损失 = 显式常数（仅由真实奖励决定，与策略无关） *)
Theorem dpo_total_loss_at_star : Id (dpo_total_loss pi_star) dpo_total_loss_star.
Proof.
  unfold dpo_total_loss, dpo_total_loss_star.
  apply fold_right_ext.
  intros pref acc.
  apply (id_cong (fun x => plus x acc)).
  exact (dpo_pair_loss_at_star pref).
Qed.

(* DPO 总损失单调性：逐对损失下降则总损失下降（非平凡：fold 归纳） *)
Theorem dpo_total_loss_monotone :
  forall pi1 pi2 : S -> R,
    (forall pref, InT pref pref_dataset ->
      le (dpo_pair_loss pi2 pref) (dpo_pair_loss pi1 pref)) ->
    le (dpo_total_loss pi2) (dpo_total_loss pi1).
Proof.
  intros pi1 pi2 Hpt.
  unfold dpo_total_loss.
  induction pref_dataset as [| p rest IH]; simpl.
  - apply le_refl.
  - apply le_plus_compat.
    + apply Hpt. apply InT_here.
    + apply IH. intros pref Hin. apply Hpt. apply InT_next. exact Hin.
Qed.

(* DPO 总损失在 π* 处的局部最优性刻画：若策略 π 的隐式奖励差分
   已与真实奖励差分一致（逐对），则其总损失等于 π* 的总损失。
   非平凡：逐对损失等价 + fold 外延性提升到数据集。 *)
Theorem dpo_total_loss_star_characterization :
  forall pi : S -> R,
    (forall pref, InT pref pref_dataset ->
      Id (implicit_reward_diff pi pref)
         (minus (reward (pref_win pref)) (reward (pref_lose pref)))) ->
    Id (dpo_total_loss pi) dpo_total_loss_star.
Proof.
  intros pi Heq.
  unfold dpo_total_loss, dpo_total_loss_star.
  induction pref_dataset as [| p rest IH]; simpl.
  - reflexivity.
  - (* 逐对等价：dpo_pair_loss pi p = dpo_pair_loss_star p *)
    assert (Hp : Id (dpo_pair_loss pi p) (dpo_pair_loss_star p)).
    {
      unfold dpo_pair_loss, dpo_pair_loss_star.
      assert (Hdiff : Id (implicit_reward_diff pi p)
                         (minus (reward (pref_win p)) (reward (pref_lose p))))
        by exact (Heq p (InT_here p rest)).
      exact (id_cong (fun x => log (plus one (exp_neg x))) Hdiff).
    }
    assert (Hrest : Id (fold_right (fun pref acc => plus (dpo_pair_loss pi pref) acc) zero rest)
                       (fold_right (fun pref acc => plus (dpo_pair_loss_star pref) acc) zero rest)).
    {
      apply IH.
      intros pref Hin. apply Heq. apply (InT_next pref p rest Hin).
    }
    exact (id_cong2 plus Hp Hrest).
Qed.

(* ============================================================ *)
(* RLHF 对齐核心定理补全与强化（RLHF 对齐核心定理补全与强化.txt）*)
(* ============================================================ *)
(* 1) relative_entropy_ext_r：相对熵对第二分布的外延性           *)
(* 2) minus_opp_opp：minus (opp a) (opp b) = minus b a           *)
(* 3) sum_mult_opp_r：Σ pi·opp g = opp (Σ pi·g)                  *)
(* 4) rlhf_free_energy_kl：F_align[pi] = F_align[pi*] + β·KL     *)
(* 5) align_objective_explicit：J(pi) = E[r] − β·KL(pi‖pi_ref)   *)
(* 6) rlhf_optimal_value：pi* 处奖励-熵权衡显式值                 *)
(* 7) rlhf_suboptimality_gap：J(pi* ) − J(pi) = β·KL(pi‖pi* ) ≥ 0   *)
(* 8) rlhf_policy_improvement：KL 到 pi* 不增 ⟹ 目标单调上升      *)
(* ------------------------------------------------------------ *)

(* 相对熵对第二个分布的外延性（构造性；逐点相等 ⟹ KL 相等） *)
Lemma relative_entropy_ext_r :
  forall p q1 q2 : S -> R,
    (forall s, Id (q1 s) (q2 s)) ->
    Id (relative_entropy p q1) (relative_entropy p q2).
Proof.
  intros p q1 q2 Hext.
  unfold relative_entropy.
  apply sum_over_S_ext.
  intro s.
  assert (Hlog : Id (log (q1 s)) (log (q2 s))) by exact (id_cong log (Hext s)).
  assert (Hminus : Id (minus (log (p s)) (log (q1 s)))
                      (minus (log (p s)) (log (q2 s))))
    by exact (id_cong2 minus (@id_refl R (log (p s))) Hlog).
  exact (id_cong (fun x => mult (p s) x) Hminus).
Qed.

(* minus (opp a) (opp b) = minus b a（double_neg + plus_comm） *)
Lemma minus_opp_opp :
  forall a b : R, Id (minus (opp a) (opp b)) (minus b a).
Proof.
  intros a b.
  unfold minus.
  assert (H1 : Id (plus (opp a) (opp (opp b))) (plus (opp a) b))
    by exact (id_cong (fun x => plus (opp a) x) (double_neg b)).
  assert (H2 : Id (plus (opp a) b) (plus b (opp a)))
    by exact (plus_comm (opp a) b).
  exact (id_trans H1 H2).
Qed.

(* Σ pi·opp g = opp (Σ pi·g)（sum_opp + 逐点 opp_mult_l） *)
Lemma sum_mult_opp_r :
  forall (pi : S -> R) (g : S -> R),
    Id (sum_over_S (fun s => mult (pi s) (opp (g s))))
       (opp (sum_over_S (fun s => mult (pi s) (g s)))).
Proof.
  intros pi g.
  assert (H1 : Id (sum_over_S (fun s => mult (pi s) (opp (g s))))
                 (sum_over_S (fun s => opp (mult (pi s) (g s)))))
    by (apply sum_over_S_ext; intro s; exact (opp_mult_l _ _)).
  assert (H2 : Id (sum_over_S (fun s => opp (mult (pi s) (g s))))
                 (opp (sum_over_S (fun s => mult (pi s) (g s)))))
    by exact (sum_opp _).
  exact (id_trans H1 H2).
Qed.

(* RLHF 自由能-KL 恒等式：F_align[pi] = F_align[pi* ] + β·KL(pi‖pi* )
   非平凡：自由能-KL 分解（相对 Boltzmann）+ Boltzmann = pi* 的
   三层替换（free_energy_ext / relative_entropy_ext_r）。 *)
Theorem rlhf_free_energy_kl :
  forall pi : S -> R,
    normalized pi ->
    Id (free_energy align_energy beta pi)
       (plus (free_energy align_energy beta pi_star)
             (mult beta (relative_entropy pi pi_star))).
Proof.
  intros pi Hnorm.
  (* 1. 应用通用自由能-KL 分解（base_loss=align_energy, D=beta） *)
  assert (Hdecomp : Id (free_energy align_energy beta pi)
                       (plus (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                             (mult beta (relative_entropy pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))))).
  { exact (free_energy_kl_decomp align_energy beta beta_pos Z_align Z_align_pos align_partition_condition pi Hnorm). }
  (* 2. Boltzmann 分布 = pi_star（逐点） *)
  assert (Hstar : forall s, Id (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s) (pi_star s))
    by exact (align_boltzmann_is_pi_star).
  (* 3. 替换自由能中的 Boltzmann 为 pi_star *)
  assert (Hfe : Id (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                   (free_energy align_energy beta pi_star)).
  { apply (free_energy_ext (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos) pi_star Hstar). }
  (* 4. 替换 KL 中的 Boltzmann 为 pi_star *)
  assert (Hkl : Id (relative_entropy pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                   (relative_entropy pi pi_star)).
  { apply (relative_entropy_ext_r pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos) pi_star Hstar). }
  (* 5. 组装 *)
  exact (id_trans Hdecomp (id_cong2 plus Hfe (id_cong (fun x => mult beta x) Hkl))).
Qed.

(* 奖励期望：E_π[r] = Σ_s pi(s)·r(s) *)
Definition expected_reward (pi : S -> R) : R :=
  sum_over_S (fun s => mult (pi s) (reward s)).

(* KL(pi||pi_ref) 的显式形式（相对参考策略） *)
Definition kl_reference (pi : S -> R) : R :=
  relative_entropy pi pi_ref.

(* 对齐目标显式分解：J(pi) = E[r] − β·KL(pi‖pi_ref)
   非平凡：align_energy 展开 + opp 分配（opp_plus）+ 求和线性
   （sum_over_S_add / sum_over_S_linear）+ 负号提取（sum_mult_opp_r
   / opp_mult_l）+ KL 逐点展开 + distrib 重组（约 12 步链）。 *)
Theorem align_objective_explicit :
  forall pi : S -> R,
    Id (align_objective pi)
       (minus (expected_reward pi) (mult beta (kl_reference pi))).
Proof.
  intro pi.
  unfold align_objective, free_energy, expected_reward, kl_reference, relative_entropy.
  (* 展开 align_energy（在 free_energy 参数内，逐点替换） *)
  assert (Hpt_ae : forall s, Id (align_energy s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))
    by (intro s; unfold align_energy; reflexivity).
  assert (Hsum_ae : Id (sum_over_S (fun s => mult (pi s) (align_energy s)))
                       (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
    by (apply sum_over_S_ext; intro s; exact (id_cong (fun x => mult (pi s) x) (Hpt_ae s))).
  (* Step 0: 目标 LHS 换为显式 align_energy 展开形式 *)
  assert (Hlhs : Id (opp (plus (sum_over_S (fun s => mult (pi s) (align_energy s)))
                               (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
                    (opp (plus (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s))))))
                               (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))).
  {
    apply (id_cong (fun z => opp (plus z (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))) Hsum_ae).
  }
  (* Step 1: opp (plus A B) = plus (opp A) (opp B) *)
  assert (H1 : Id (opp (plus (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s))))))
                             (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
                  (plus (opp (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
                        (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))))
    by exact (opp_plus _ _).
  (* 目标：Id LHS RHS；先用 Hlhs 换 LHS 为显式形式（H1/Hmid 在收尾组装） *)
  (* Step 2: 分解 align_energy 求和 *)
  assert (H2 : Id (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s))))))
                  (plus (sum_over_S (fun s => mult (pi s) (opp (reward s))))
                        (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s)))))))).
  {
    assert (Hpt : forall s, Id (mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))
                              (plus (mult (pi s) (opp (reward s))) (mult (pi s) (opp (mult beta (log (pi_ref s)))))))
      by (intro s;
          exact (id_trans (mult_minus_distr_l (pi s) (opp (reward s)) (mult beta (log (pi_ref s))))
                          (id_cong (fun x => plus (mult (pi s) (opp (reward s))) x)
                                   (id_sym (opp_mult_l (pi s) (mult beta (log (pi_ref s)))))))).
    assert (Hadd : Id (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s))))))
                     (sum_over_S (fun s => plus (mult (pi s) (opp (reward s))) (mult (pi s) (opp (mult beta (log (pi_ref s))))))))
      by exact (sum_over_S_ext _ _ Hpt).
    exact (id_trans Hadd (sum_over_S_add _ _)).
  }
  (* Step 3: opp (sum (pi·opp r)) = expected_reward *)
  assert (H3 : Id (opp (sum_over_S (fun s => mult (pi s) (opp (reward s)))))
                  (sum_over_S (fun s => mult (pi s) (reward s))))
    by exact (id_trans (id_cong opp (sum_mult_opp_r _ _)) (double_neg _)).
  (* Step 4: opp (sum (pi·opp (beta·log_ref))) = mult beta (sum (pi·log_ref)) *)
  assert (H4 : Id (opp (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s)))))))
                  (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))).
  {
    assert (Hso : Id (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s))))))
                     (opp (sum_over_S (fun s => mult (pi s) (mult beta (log (pi_ref s)))))))
      by exact (sum_mult_opp_r _ _).
    assert (Hsw : Id (sum_over_S (fun s => mult (pi s) (mult beta (log (pi_ref s)))))
                     (sum_over_S (fun s => mult beta (mult (pi s) (log (pi_ref s)))))).
    {
      apply sum_over_S_ext.
      intro s.
      (* mult (pi s) (mult beta (log ref)) = mult beta (mult (pi s) (log ref))：
         mult_assoc + mult_comm（同 free_energy_align_decomp.Hswp 模式） *)
      assert (Hs1 : Id (mult (pi s) (mult beta (log (pi_ref s)))) (mult (mult (pi s) beta) (log (pi_ref s))))
        by exact (mult_assoc (pi s) beta (log (pi_ref s))).
      assert (Hs2 : Id (mult (mult (pi s) beta) (log (pi_ref s))) (mult (mult beta (pi s)) (log (pi_ref s))))
        by exact (id_cong (fun x => mult x (log (pi_ref s))) (mult_comm (pi s) beta)).
      assert (Hs3 : Id (mult (mult beta (pi s)) (log (pi_ref s))) (mult beta (mult (pi s) (log (pi_ref s)))))
        by exact (id_sym (mult_assoc beta (pi s) (log (pi_ref s)))).
      exact (id_trans Hs1 (id_trans Hs2 Hs3)).
    }
    assert (Hlin : Id (sum_over_S (fun s => mult beta (mult (pi s) (log (pi_ref s)))))
                      (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
      by exact (sum_over_S_linear beta _).
    assert (Htot : Id (sum_over_S (fun s => mult (pi s) (mult beta (log (pi_ref s)))))
                      (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
      by exact (id_trans Hsw Hlin).
    exact (id_trans (id_cong opp Hso) (id_trans (double_neg _) Htot)).
  }
  (* Step 5: opp (sum align_energy) = plus E (mult beta (sum log_ref)) *)
  assert (H5 : Id (opp (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
                  (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                        (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))).
  {
    (* opp (Σ align_energy 分解) = opp (plus Σ1 Σ2)（H2 反向）
       = plus (opp Σ1) (opp Σ2)（opp_plus）= plus E (mult beta Σlog_ref)（H3 H4） *)
    assert (H2s : Id (opp (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
                     (opp (plus (sum_over_S (fun s => mult (pi s) (opp (reward s))))
                                (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s)))))))))
      by exact (id_cong opp H2).
    assert (Hopp : Id (opp (plus (sum_over_S (fun s => mult (pi s) (opp (reward s))))
                                 (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s))))))))
                      (plus (opp (sum_over_S (fun s => mult (pi s) (opp (reward s)))))
                            (opp (sum_over_S (fun s => mult (pi s) (opp (mult beta (log (pi_ref s)))))))))
      by exact (opp_plus _ _).
    exact (id_trans H2s (id_trans Hopp (id_cong2 plus H3 H4))).
  }
  (* Step 6: opp (mult beta (sum (pi·log pi))) = mult beta (sum (pi·opp log pi)) *)
  assert (H6 : Id (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))
                  (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))).
  {
    assert (Hopp : Id (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s))))))
                    (mult beta (opp (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
      by exact (id_sym (opp_mult_l beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))).
    assert (Hso : Id (opp (sum_over_S (fun s => mult (pi s) (log (pi s)))))
                    (sum_over_S (fun s => opp (mult (pi s) (log (pi s))))))
      by exact (id_sym (sum_opp (fun s => mult (pi s) (log (pi s))))).
    assert (Hpt : Id (sum_over_S (fun s => opp (mult (pi s) (log (pi s)))))
                    (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))
      by (apply sum_over_S_ext; intro s; exact (id_sym (opp_mult_l (pi s) (log (pi s))))).
    exact (id_trans Hopp (id_cong (fun x => mult beta x) (id_trans Hso Hpt))).
  }
  (* Step 7: 组合 LHS —— plus (opp A) (opp B) = plus (plus E X) Y（H5/H6） *)
  assert (H7 : Id (plus (opp (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
                        (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
                  (plus (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                              (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                        (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))).
  { exact (id_cong2 plus H5 H6). }
  (* Step 8: 提取 beta（重组） *)
  assert (H8 : Id (plus (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                              (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                        (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))
                  (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                        (mult beta (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                                         (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))))).
  {
    assert (Hdist : Id (mult beta (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                                        (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))
                       (plus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))
                             (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))))
      by exact (distrib _ _ _).
    assert (Hassoc : Id (plus (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                                    (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))))
                              (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))
                        (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                              (plus (mult beta (sum_over_S (fun s => mult (pi s) (log (pi_ref s)))))
                                    (mult beta (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))))
      by exact (id_sym (plus_assoc _ _ _)).
    exact (id_trans Hassoc (id_cong (fun x => plus (sum_over_S (fun s => mult (pi s) (reward s))) x) (id_sym Hdist))).
  }
  (* Step 9: 内部求和化简为 opp (KL 求和) *)
  assert (H9 : Id (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                        (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))
                  (opp (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s))))))).
  {
    assert (Hadd : Id (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                            (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))
                    (sum_over_S (fun s => plus (mult (pi s) (log (pi_ref s))) (mult (pi s) (opp (log (pi s)))))))
      by exact (id_sym (sum_over_S_add _ _)).
    assert (Hpt : forall s, Id (plus (mult (pi s) (log (pi_ref s))) (mult (pi s) (opp (log (pi s)))))
                              (opp (mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))).
    {
      intro s.
      assert (H9a : Id (plus (mult (pi s) (log (pi_ref s))) (mult (pi s) (opp (log (pi s)))))
                      (mult (pi s) (plus (log (pi_ref s)) (opp (log (pi s))))))
        by exact (id_sym (distrib _ _ _)).
      assert (H9b : Id (mult (pi s) (plus (log (pi_ref s)) (opp (log (pi s)))))
                      (opp (mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))).
      {
        assert (H9c : Id (plus (log (pi_ref s)) (opp (log (pi s))))
                         (opp (minus (log (pi s)) (log (pi_ref s))))).
        {
          assert (H9d : Id (opp (minus (log (pi s)) (log (pi_ref s))))
                          (plus (opp (log (pi s))) (log (pi_ref s))))
            by exact (opp_minus _ _).
          assert (H9e : Id (plus (opp (log (pi s))) (log (pi_ref s)))
                          (plus (log (pi_ref s)) (opp (log (pi s)))))
            by exact (plus_comm _ _).
          exact (id_sym (id_trans H9d H9e)).
        }
        assert (H9f : Id (mult (pi s) (opp (minus (log (pi s)) (log (pi_ref s)))))
                         (opp (mult (pi s) (minus (log (pi s)) (log (pi_ref s))))))
          by exact (opp_mult_l (pi s) (minus (log (pi s)) (log (pi_ref s)))).
        exact (id_trans (id_cong (fun x => mult (pi s) x) H9c) H9f).
      }
      exact (id_trans H9a H9b).
    }
    assert (Hext : Id (sum_over_S (fun s => plus (mult (pi s) (log (pi_ref s))) (mult (pi s) (opp (log (pi s))))))
                     (sum_over_S (fun s => opp (mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))))
      by exact (sum_over_S_ext _ _ Hpt).
    assert (Hso : Id (sum_over_S (fun s => opp (mult (pi s) (minus (log (pi s)) (log (pi_ref s))))))
                     (opp (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))))
      by exact (sum_opp _).
    exact (id_trans Hadd (id_trans Hext Hso)).
  }
  (* Step 10: 最终组合 *)
  assert (H10 : Id (mult beta (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                                    (sum_over_S (fun s => mult (pi s) (opp (log (pi s)))))))
                   (opp (mult beta (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s)))))))).
  {
    exact (id_trans (id_cong (fun x => mult beta x) H9) (opp_mult_l _ _)).
  }
  assert (Hfinal : Id (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                            (mult beta (plus (sum_over_S (fun s => mult (pi s) (log (pi_ref s))))
                                             (sum_over_S (fun s => mult (pi s) (opp (log (pi s))))))))
                      (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                            (opp (mult beta (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s))))))))).
  {
    exact (id_cong (fun x => plus (sum_over_S (fun s => mult (pi s) (reward s))) x) H10).
  }
  (* 目标（Step 1 后）：Id (plus (opp A) (opp B)) (minus E (mult beta KL))。
     链：plus (opp A) (opp B) → (H7) plus (plus E X) Y → (H8) plus E (plus X Y)
         → (Hfinal) plus E (opp KL') = minus E (mult beta KL)。 *)
  assert (Hmid : Id (plus (opp (sum_over_S (fun s => mult (pi s) (minus (opp (reward s)) (mult beta (log (pi_ref s)))))))
                          (opp (mult beta (sum_over_S (fun s => mult (pi s) (log (pi s)))))))
                    (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                          (opp (mult beta (sum_over_S (fun s => mult (pi s) (minus (log (pi s)) (log (pi_ref s))))))))).
  {
    exact (id_trans H7 (id_trans H8 Hfinal)).
  }
  exact (id_trans Hlhs (id_trans H1 Hmid)).
Qed.

(* pi* 的奖励-熵权衡显式值 *)
Corollary rlhf_optimal_value :
  Id (align_objective pi_star)
     (minus (expected_reward pi_star) (mult beta (kl_reference pi_star))).
Proof.
  exact (align_objective_explicit pi_star).
Qed.

(* 次优差距：J(pi* ) − J(pi) = β·KL(pi‖pi* ) ≥ 0。
   非平凡：取负翻转（minus_opp_opp）+ free_energy_kl_diff +
   Boltzmann = pi* 替换（free_energy_ext / relative_entropy_ext_r）。 *)
Theorem rlhf_suboptimality_gap :
  forall pi : S -> R,
    normalized pi -> positive_dist pi ->
    Id (minus (align_objective pi_star) (align_objective pi))
       (mult beta (relative_entropy pi pi_star)).
Proof.
  intros pi Hnorm Hpos.
  (* align_objective = -F，故 Jstar - J = (-Fstar) - (-F) = F - Fstar = beta·KL *)
  assert (H1 : Id (minus (opp (free_energy align_energy beta pi_star))
                          (opp (free_energy align_energy beta pi)))
                  (minus (free_energy align_energy beta pi)
                         (free_energy align_energy beta pi_star)))
    by exact (minus_opp_opp (free_energy align_energy beta pi_star) (free_energy align_energy beta pi)).
  assert (H2_raw : Id (minus (free_energy align_energy beta pi)
                             (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos)))
                      (mult beta (relative_entropy pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))))
    by exact (free_energy_kl_diff align_energy beta beta_pos Z_align Z_align_pos align_partition_condition pi Hnorm).
  assert (Hfe_b : Id (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                     (free_energy align_energy beta pi_star))
    by apply (free_energy_ext (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos) pi_star align_boltzmann_is_pi_star).
  assert (Hkl_b : Id (relative_entropy pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))
                     (relative_entropy pi pi_star))
    by apply (relative_entropy_ext_r pi (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos) pi_star align_boltzmann_is_pi_star).
  assert (H2 : Id (minus (free_energy align_energy beta pi) (free_energy align_energy beta pi_star))
                  (mult beta (relative_entropy pi pi_star))).
  {
    assert (Hlhs : Id (minus (free_energy align_energy beta pi) (free_energy align_energy beta pi_star))
                      (minus (free_energy align_energy beta pi) (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos))))
      by exact (id_cong2 minus id_refl (id_sym Hfe_b)).
    exact (id_trans Hlhs (id_trans H2_raw (id_cong (fun x => mult beta x) Hkl_b))).
  }
  exact (id_trans H1 H2).
Qed.

(* 策略改进单调性：KL(π_new‖πstar) ≤ KL(π_old‖πstar) ⟹ J(π_old) ≤ J(π_new)。
   非平凡：次优差距恒等式 ×2 + β > 0 保序 + 差分翻转（le_plus_compat
   + opp 消去 + double_neg，约 20 步）。 *)
Theorem rlhf_policy_improvement :
  forall (p_old p_new : S -> R),
    normalized p_old -> positive_dist p_old ->
    normalized p_new -> positive_dist p_new ->
    le (relative_entropy p_new pi_star) (relative_entropy p_old pi_star) ->
    le (align_objective p_old) (align_objective p_new).
Proof.
  intros p_old p_new Hn1 Hp1 Hn2 Hp2 Hkl_dec.
  (* J* - J_new = β·KL(new||pi* ) *)
  assert (Hgap_new : Id (minus (align_objective pi_star) (align_objective p_new))
                        (mult beta (relative_entropy p_new pi_star)))
    by exact (rlhf_suboptimality_gap p_new Hn2 Hp2).
  (* J* - J_old = β·KL(old||pi* ) *)
  assert (Hgap_old : Id (minus (align_objective pi_star) (align_objective p_old))
                        (mult beta (relative_entropy p_old pi_star)))
    by exact (rlhf_suboptimality_gap p_old Hn1 Hp1).
  (* β·KL_new ≤ β·KL_old（β > 0） *)
  assert (Hbeta_le : le (mult beta (relative_entropy p_new pi_star))
                        (mult beta (relative_entropy p_old pi_star)))
    by exact (le_mult_compat_r beta _ _ (lt_le_iff _ _ (inl beta_pos)) Hkl_dec).
  (* J* - J_new ≤ J* - J_old *)
  assert (Hle : le (minus (align_objective pi_star) (align_objective p_new))
                   (minus (align_objective pi_star) (align_objective p_old))).
  {
    exact (le_id_l (minus (align_objective pi_star) (align_objective p_new))
                   (mult beta (relative_entropy p_new pi_star))
                   (minus (align_objective pi_star) (align_objective p_old))
                   Hgap_new
                   (le_id_r (mult beta (relative_entropy p_new pi_star))
                            (mult beta (relative_entropy p_old pi_star))
                            (minus (align_objective pi_star) (align_objective p_old))
                            (id_sym Hgap_old)
                            Hbeta_le)).
  }
  unfold minus in Hle.
  (* 由 le (plus a (opp b)) (plus a (opp c)) 推出 le c b：
     两侧加 opp a，化简得 le (opp b) (opp c)，再取 opp 得 le c b *)
  assert (Hopp_le : le (opp (align_objective p_new)) (opp (align_objective p_old))).
  {
    assert (Hadd : le (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_new))))
                     (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_old))))).
    { exact (le_plus_compat _ _ _ _ (le_refl _) Hle). }
    assert (Hl : Id (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_new))))
                   (opp (align_objective p_new))).
    {
      assert (H1 : Id (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_new))))
                      (plus (plus (opp (align_objective pi_star)) (align_objective pi_star)) (opp (align_objective p_new))))
        by exact (plus_assoc (opp (align_objective pi_star)) (align_objective pi_star) (opp (align_objective p_new))).
      assert (H2 : Id (plus (plus (opp (align_objective pi_star)) (align_objective pi_star)) (opp (align_objective p_new)))
                      (plus zero (opp (align_objective p_new))))
        by exact (id_cong (fun x => plus x (opp (align_objective p_new)))
                          (id_trans (plus_comm (opp (align_objective pi_star)) (align_objective pi_star))
                                    (plus_opp (align_objective pi_star)))).
      exact (id_trans H1 (id_trans H2 (id_trans (plus_comm zero (opp (align_objective p_new))) (plus_zero (opp (align_objective p_new)))))).
    }
    assert (Hr : Id (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_old))))
                   (opp (align_objective p_old))).
    {
      assert (H1 : Id (plus (opp (align_objective pi_star)) (plus (align_objective pi_star) (opp (align_objective p_old))))
                      (plus (plus (opp (align_objective pi_star)) (align_objective pi_star)) (opp (align_objective p_old))))
        by exact (plus_assoc (opp (align_objective pi_star)) (align_objective pi_star) (opp (align_objective p_old))).
      assert (H2 : Id (plus (plus (opp (align_objective pi_star)) (align_objective pi_star)) (opp (align_objective p_old)))
                      (plus zero (opp (align_objective p_old))))
        by exact (id_cong (fun x => plus x (opp (align_objective p_old)))
                          (id_trans (plus_comm (opp (align_objective pi_star)) (align_objective pi_star))
                                    (plus_opp (align_objective pi_star)))).
      exact (id_trans H1 (id_trans H2 (id_trans (plus_comm zero (opp (align_objective p_old))) (plus_zero (opp (align_objective p_old)))))).
    }
    exact (le_id_l (opp (align_objective p_new)) _ _ (id_sym Hl) (le_id_r _ _ _ Hr Hadd)).
  }
  (* 由 le (opp new) (opp old) 得 le old new（opp_le_compat + double_neg） *)
  assert (Hdn : le (opp (opp (align_objective p_old))) (opp (opp (align_objective p_new))))
    by exact (opp_le_compat (opp (align_objective p_new)) (opp (align_objective p_old)) Hopp_le).
  assert (H1 : Id (opp (opp (align_objective p_old))) (align_objective p_old))
    by exact (double_neg _).
  assert (H2 : Id (opp (opp (align_objective p_new))) (align_objective p_new))
    by exact (double_neg _).
  exact (le_id_l (align_objective p_old) (opp (opp (align_objective p_old))) (align_objective p_new)
                 (id_sym H1) (le_id_r (opp (opp (align_objective p_old))) (opp (opp (align_objective p_new))) (align_objective p_new) H2 Hdn)).
Qed.

(* ============================================================ *)
(* PPO 单调保证（构造性单调保证.txt：比率消去 + 代理目标恒等式）*)
(* ============================================================ *)
(* 1) align_objective_decomp：J(pi) = V(pi) − β·KL(pi‖pi_ref)    *)
(* 2) importance_ratio_self_one：pi/pi = 1（比率自反）            *)
(* 3) ppo_surrogate_raw_is_value_improvement：L_raw = V(pi) −      *)
(*    V(pi_old)（比率消去 + 求和线性 + 归一化坍缩，核心非平凡）   *)
(* ------------------------------------------------------------ *)

(* 对齐目标显式分解：J(pi) = V(pi) − β·KL(pi‖pi_ref)
   （由 free_energy_align_decomp 取负推导；非平凡：opp 分配律） *)
Lemma align_objective_decomp :
  forall pi : S -> R,
    Id (align_objective pi)
       (minus (state_value pi) (mult beta (kl_to_ref pi))).
Proof.
  intro pi.
  unfold align_objective.
  assert (Hfe : Id (free_energy align_energy beta pi)
                  (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))
    by exact (free_energy_align_decomp pi).
  assert (H1 : Id (opp (free_energy align_energy beta pi))
                  (opp (plus (opp (state_value pi)) (mult beta (kl_to_ref pi)))))
    by exact (id_cong opp Hfe).
  assert (H2 : Id (opp (plus (opp (state_value pi)) (mult beta (kl_to_ref pi))))
                  (plus (state_value pi) (opp (mult beta (kl_to_ref pi)))))
    by exact (id_trans (opp_plus (opp (state_value pi)) (mult beta (kl_to_ref pi)))
                       (id_cong2 plus (double_neg (state_value pi))
                                 id_refl)).
  assert (H3 : Id (plus (state_value pi) (opp (mult beta (kl_to_ref pi))))
                  (minus (state_value pi) (mult beta (kl_to_ref pi))))
    by reflexivity.
  exact (id_trans H1 (id_trans H2 H3)).
Qed.

(* 策略比率自反：pi/pi = 1（非平凡：交换律 + 逆元公理） *)
Lemma importance_ratio_self_one :
  forall (pi : S -> R) (Hpos : positive_dist pi) (s : S),
    Id (policy_ratio pi pi s (Hpos s)) one.
Proof.
  intros pi Hpos s.
  unfold policy_ratio.
  exact (inv_pos_correct (pi s) (Hpos s)).
Qed.

(* 无裁剪代理目标恒等：L_raw(pi, pi_old) = V(pi) − V(pi_old)。
   非平凡：比率消去（pi_old·(pi/pi_old) = pi）+ 求和线性
   （sum_over_S_linear）+ 归一化坍缩（Σ pi = 1），约 20 步。 *)
Theorem ppo_surrogate_raw_is_value_improvement :
  forall (pi p_old : S -> R) (Hpos : positive_dist p_old)
         (Hnorm : normalized pi),
    Id (sum_over_S (fun s => mult (p_old s)
       (mult (policy_ratio pi p_old s (Hpos s)) (advantage p_old s))))
       (minus (state_value pi) (state_value p_old)).
Proof.
  intros pi p_old Hpos Hnorm.
  unfold policy_ratio, advantage, state_value.
  (* 逐点消去 p_old·(pi/p_old) = pi *)
  assert (Hpt : forall s,
    Id (mult (p_old s) (mult (mult (pi s) (inv_pos (p_old s) (Hpos s)))
                              (minus (reward s)
                                     (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
       (mult (pi s) (minus (reward s)
                           (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))).
  {
    intro s.
    assert (H1 : Id (mult (p_old s) (mult (mult (pi s) (inv_pos (p_old s) (Hpos s)))
          (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
        (mult (mult (p_old s) (mult (pi s) (inv_pos (p_old s) (Hpos s))))
              (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
      by exact (mult_assoc (p_old s) (mult (pi s) (inv_pos (p_old s) (Hpos s)))
                           (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))).
    assert (H2 : Id (mult (mult (p_old s) (mult (pi s) (inv_pos (p_old s) (Hpos s))))
                          (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
        (mult (mult (mult (pi s) (p_old s)) (inv_pos (p_old s) (Hpos s)))
              (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
      by exact (id_cong (fun x => mult x (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
               (id_trans (mult_assoc (p_old s) (pi s) (inv_pos (p_old s) (Hpos s)))
                         (id_cong (fun x => mult x (inv_pos (p_old s) (Hpos s)))
                                  (mult_comm (p_old s) (pi s))))).
    assert (H3 : Id (mult (mult (mult (pi s) (p_old s)) (inv_pos (p_old s) (Hpos s)))
                          (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
        (mult (pi s) (mult (mult (p_old s) (inv_pos (p_old s) (Hpos s)))
                           (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))).
    {
      set (X := mult (p_old s) (inv_pos (p_old s) (Hpos s))).
      set (M := minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))).
      (* 第一步：内层换序 mult (mult (pi s) (p_old s)) inv = mult (pi s) X *)
      assert (H3a : Id (mult (mult (mult (pi s) (p_old s)) (inv_pos (p_old s) (Hpos s))) M)
                       (mult (mult (pi s) X) M))
        by (unfold X; exact (id_cong (fun x => mult x M)
                                     (id_sym (mult_assoc (pi s) (p_old s) (inv_pos (p_old s) (Hpos s)))))).
      (* 第二步：外层重结合 mult (mult (pi s) X) M = mult (pi s) (mult X M) *)
      assert (H3b : Id (mult (mult (pi s) X) M) (mult (pi s) (mult X M)))
        by exact (id_sym (mult_assoc (pi s) X M)).
      exact (id_trans H3a H3b).
    }
    assert (H4 : Id (mult (pi s) (mult (p_old s) (inv_pos (p_old s) (Hpos s))))
                    (mult (pi s) one))
      by exact (id_cong (fun x => mult (pi s) x)
               (inv_pos_correct (p_old s) (Hpos s))).
    assert (H5 : Id (mult (pi s) one) (pi s))
      by exact (mult_one (pi s)).
    (* 收尾：LHS → H1 → H2 → H3（至 mult (pi s) (mult X M)）→
       H3b 反向（至 mult (mult (pi s) X) M）→ H4/H5 内层折叠 → mult (pi s) M *)
    set (M := minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))).
    assert (H6 : Id (mult (mult (pi s) (mult (p_old s) (inv_pos (p_old s) (Hpos s)))) M)
                     (mult (pi s) M))
      by exact (id_trans (id_cong (fun x => mult x M) H4)
                         (id_cong (fun x => mult x M) H5)).
    assert (H7 : Id (mult (mult (pi s) (mult (p_old s) (inv_pos (p_old s) (Hpos s)))) M)
                     (mult (pi s) M))
      by exact (id_trans (id_cong (fun x => mult x M) H4)
                         (id_cong (fun x => mult x M) H5)).
    (* H3 RHS = mult (pi s) (mult X M)；重结合到 mult (mult (pi s) X) M 再 H7 *)
    exact (id_trans H1 (id_trans H2 (id_trans H3
          (id_trans (mult_assoc (pi s) (mult (p_old s) (inv_pos (p_old s) (Hpos s))) M) H7)))).
  }
  assert (Hext : Id (sum_over_S (fun s => mult (p_old s)
       (mult (mult (pi s) (inv_pos (p_old s) (Hpos s)))
             (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
                   (sum_over_S (fun s => mult (pi s)
                       (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
    by exact (sum_over_S_ext _ _ Hpt).
  (* 逐点：mult (pi s) (minus r V) = minus (mult pi r) (mult pi V)（mult_minus_distr_l） *)
  assert (Hpt2 : forall s, Id (mult (pi s) (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
                             (minus (mult (pi s) (reward s))
                                    (mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
    by (intro s; exact (mult_minus_distr_l (pi s) (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))).
  assert (Hext2 : Id (sum_over_S (fun s => mult (pi s) (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
                     (sum_over_S (fun s => minus (mult (pi s) (reward s))
                                                 (mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
    by exact (sum_over_S_ext _ _ Hpt2).
  (* 目标换形：先 Hext 再 Hext2 再 Hdist *)
  assert (Hlhs : Id (sum_over_S (fun s => mult (p_old s)
       (mult (mult (pi s) (inv_pos (p_old s) (Hpos s)))
             (minus (reward s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
                   (sum_over_S (fun s => minus (mult (pi s) (reward s))
                                               (mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
    by exact (id_trans Hext Hext2).
  rewrite Hlhs.
  (* 分配求和：Σ (minus f g) = minus (Σf) (Σg) *)
  assert (Hdist : Id (sum_over_S (fun s => minus (mult (pi s) (reward s))
                                                 (mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))))
                     (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                            (sum_over_S (fun s => mult (pi s)
                                (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))))
    by exact (sum_over_S_minus (fun s => mult (pi s) (reward s))
                               (fun s => mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))).
  rewrite Hdist.
  (* 提取常数 V_old：Σ pi·V_old = V_old·Σ pi = V_old *)
  assert (Hconst : Id (sum_over_S (fun s => mult (pi s)
      (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
      (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (sum_over_S pi))).
  {
    assert (Hsw : Id (sum_over_S (fun s => mult (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
                     (sum_over_S (fun s => mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (pi s))))
      by exact (sum_over_S_ext _ _ (fun s => mult_comm (pi s) (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))).
    assert (Hlin : Id (sum_over_S (fun s => mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (pi s)))
                      (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (sum_over_S pi)))
      by exact (sum_over_S_linear (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) pi).
    exact (id_trans Hsw Hlin).
  }
  rewrite Hconst.
  (* Σ pi = 1（Hnorm：normalized pi = Id (sum_over_S pi) one） *)
  assert (Hnorm1 : Id (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (sum_over_S pi))
                       (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) one))
    by exact (id_cong (fun x => mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) x) Hnorm).
  assert (Hm1 : Id (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) one)
                   (sum_over_S (fun s0 => mult (p_old s0) (reward s0))))
    by exact (mult_one (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))).
  assert (Hfin : Id (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                           (mult (sum_over_S (fun s0 => mult (p_old s0) (reward s0))) (sum_over_S pi)))
                    (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                           (sum_over_S (fun s0 => mult (p_old s0) (reward s0)))))
    by (unfold minus; exact (id_cong (fun x => plus (sum_over_S (fun s => mult (pi s) (reward s))) (opp x))
                                     (id_trans Hnorm1 Hm1))).
  exact Hfin.
Qed.

(* ============================================================ *)
(* DPO 构造性骨架（对齐自由能显式.txt：sigmoid 与 BT 对数几率） *)
(* ============================================================ *)
(* 1) sigmoid_denom_pos：1 + e^{-x} > 0（sigmoid 良定义）          *)
(* 2) sigmoid：Set 层构造 σ(x) = 1/(1+e^{-x})（正性见证内嵌）      *)
(* 3) sigmoid_lt_one：σ(x) < 1（值域上界：lt_mult_compat + inv）   *)
(* 4) log_ratio：对数几率比 log π(s) − log π_ref(s)                *)
(* 5) dpo_loss_pair：成对 DPO 损失 −log σ(β·Δlog-ratio)            *)
(* 6) dpo_loss_at_pi_star：π* 处损失退化为 BT 模型对数几率          *)
(*    −log σ(r_w − r_l)（非平凡：log_pi_star 消去 Z_align/π_ref） *)
(* ------------------------------------------------------------ *)

(* Sigmoid 分母正性：1 + e^{-x} > 0（one_pos + exp_neg_pos） *)
Lemma sigmoid_denom_pos : forall x : R, lt zero (plus one (exp_neg x)).
Proof.
  intro x. apply plus_le_lt_pos.
  - apply (lt_le_iff _ _). left. apply one_pos.
  - apply exp_neg_pos.
Qed.

(* 构造性 Sigmoid：σ(x) = 1 / (1 + e^{-x})，值域 (0,1) *)
Definition sigmoid (x : R) : R :=
  inv_pos (plus one (exp_neg x)) (sigmoid_denom_pos x).

Lemma sigmoid_pos : forall x : R, lt zero (sigmoid x).
Proof. intro x. unfold sigmoid. apply inv_pos_pos. Qed.

(* 对数几率比：log(π(s) / π_ref(s)) = log π(s) − log π_ref(s) *)
Definition log_ratio (pi : S -> R) (s : S) : R :=
  minus (log (pi s)) (log (pi_ref s)).

(* 成对 DPO 损失（偏好 s_w ≻ s_l）：
   L_DPO = −log σ( β·log_ratio(π,s_w) − β·log_ratio(π,s_l) ) *)
Definition dpo_loss_pair (pi : S -> R) (s_w s_l : S) : R :=
  opp (log (sigmoid (minus (mult beta (log_ratio pi s_w))
                           (mult beta (log_ratio pi s_l))))).

(* DPO 在 π* 处的显式值：损失退化为 BT 模型的对数几率
   非平凡：log_pi_star 展开（消去 Z_align 与 π_ref）+ β·(1/β) = 1
   消去（mult_assoc + inv_pos_correct）+ id_cong 提升（约 30 步）。 *)
Theorem dpo_loss_at_pi_star :
  forall s_w s_l : S,
    Id (dpo_loss_pair pi_star s_w s_l)
       (opp (log (sigmoid (minus (reward s_w) (reward s_l))))).
Proof.
  intros s_w s_l.
  unfold dpo_loss_pair, log_ratio.
  (* 利用 log_pi_star 消去 π_ref，保留 −log Z + r/β（Z 项在差分中消去） *)
  assert (Hdiff_w : Id (minus (log (pi_star s_w)) (log (pi_ref s_w)))
                        (plus (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s_w)))).
  {
    assert (Hls : Id (log (pi_star s_w))
                     (plus (opp (log Z_align)) (plus (log (pi_ref s_w)) (mult (inv_pos beta beta_pos) (reward s_w)))))
      by exact (log_pi_star s_w).
    unfold minus. rewrite Hls.
    assert (H1 : Id (plus (plus (opp (log Z_align)) (plus (log (pi_ref s_w)) (mult (inv_pos beta beta_pos) (reward s_w)))) (opp (log (pi_ref s_w))))
                    (plus (opp (log Z_align)) (plus (plus (log (pi_ref s_w)) (mult (inv_pos beta beta_pos) (reward s_w))) (opp (log (pi_ref s_w))))))
      by exact (id_sym (plus_assoc (opp (log Z_align)) (plus (log (pi_ref s_w)) (mult (inv_pos beta beta_pos) (reward s_w))) (opp (log (pi_ref s_w))))).
    assert (H2 : Id (plus (plus (log (pi_ref s_w)) (mult (inv_pos beta beta_pos) (reward s_w))) (opp (log (pi_ref s_w))))
                    (plus (mult (inv_pos beta beta_pos) (reward s_w)) (plus (log (pi_ref s_w)) (opp (log (pi_ref s_w))))))
      by exact (id_trans (id_cong (fun x => plus x (opp (log (pi_ref s_w)))) (plus_comm _ _))
                         (id_sym (plus_assoc (mult (inv_pos beta beta_pos) (reward s_w)) (log (pi_ref s_w)) (opp (log (pi_ref s_w)))))).
    assert (H3 : Id (plus (mult (inv_pos beta beta_pos) (reward s_w)) (plus (log (pi_ref s_w)) (opp (log (pi_ref s_w)))))
                    (plus (mult (inv_pos beta beta_pos) (reward s_w)) zero))
      by exact (id_cong (fun x => plus (mult (inv_pos beta beta_pos) (reward s_w)) x) (plus_opp _)).
    assert (H4 : Id (plus (mult (inv_pos beta beta_pos) (reward s_w)) zero) (mult (inv_pos beta beta_pos) (reward s_w)))
      by exact (plus_zero _).
    exact (id_trans H1 (id_cong (fun x => plus (opp (log Z_align)) x) (id_trans H2 (id_trans H3 H4)))).
  }
  assert (Hdiff_l : Id (minus (log (pi_star s_l)) (log (pi_ref s_l)))
                        (plus (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s_l)))).
  {
    assert (Hls : Id (log (pi_star s_l))
                     (plus (opp (log Z_align)) (plus (log (pi_ref s_l)) (mult (inv_pos beta beta_pos) (reward s_l)))))
      by exact (log_pi_star s_l).
    unfold minus. rewrite Hls.
    assert (H1 : Id (plus (plus (opp (log Z_align)) (plus (log (pi_ref s_l)) (mult (inv_pos beta beta_pos) (reward s_l)))) (opp (log (pi_ref s_l))))
                    (plus (opp (log Z_align)) (plus (plus (log (pi_ref s_l)) (mult (inv_pos beta beta_pos) (reward s_l))) (opp (log (pi_ref s_l))))))
      by exact (id_sym (plus_assoc (opp (log Z_align)) (plus (log (pi_ref s_l)) (mult (inv_pos beta beta_pos) (reward s_l))) (opp (log (pi_ref s_l))))).
    assert (H2 : Id (plus (plus (log (pi_ref s_l)) (mult (inv_pos beta beta_pos) (reward s_l))) (opp (log (pi_ref s_l))))
                    (plus (mult (inv_pos beta beta_pos) (reward s_l)) (plus (log (pi_ref s_l)) (opp (log (pi_ref s_l))))))
      by exact (id_trans (id_cong (fun x => plus x (opp (log (pi_ref s_l)))) (plus_comm _ _))
                         (id_sym (plus_assoc (mult (inv_pos beta beta_pos) (reward s_l)) (log (pi_ref s_l)) (opp (log (pi_ref s_l)))))).
    assert (H3 : Id (plus (mult (inv_pos beta beta_pos) (reward s_l)) (plus (log (pi_ref s_l)) (opp (log (pi_ref s_l)))))
                    (plus (mult (inv_pos beta beta_pos) (reward s_l)) zero))
      by exact (id_cong (fun x => plus (mult (inv_pos beta beta_pos) (reward s_l)) x) (plus_opp _)).
    assert (H4 : Id (plus (mult (inv_pos beta beta_pos) (reward s_l)) zero) (mult (inv_pos beta beta_pos) (reward s_l)))
      by exact (plus_zero _).
    exact (id_trans H1 (id_cong (fun x => plus (opp (log Z_align)) x) (id_trans H2 (id_trans H3 H4)))).
  }
  (* 计算 β·(log_ratio_w − log_ratio_l) = r_w − r_l
     非平凡：Z 项消去（minus_plus_common）+ β·(1/β)·r = r（mult_assoc）+
     共同因子提取（mult_minus_distr_l 反向），约 15 步。 *)
  assert (Hmain : Id (minus (mult beta (minus (log (pi_star s_w)) (log (pi_ref s_w))))
                            (mult beta (minus (log (pi_star s_l)) (log (pi_ref s_l)))))
                     (minus (reward s_w) (reward s_l))).
  {
    rewrite Hdiff_w. rewrite Hdiff_l.
    (* 目标：minus (mult beta (plus A Rw)) (mult beta (plus A Rl)) = minus r_w r_l
       1) 提取 beta：mult beta (plus A R) = plus (mult beta A) (mult beta R)（distrib） *)
    set (A := opp (log Z_align)).
    assert (Hd_w : Id (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_w))))
                      (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_w)))))
      by (unfold A; exact (distrib beta (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s_w)))).
    assert (Hd_l : Id (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_l))))
                      (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_l)))))
      by (unfold A; exact (distrib beta (opp (log Z_align)) (mult (inv_pos beta beta_pos) (reward s_l)))).
    (* 2) 目标 LHS 换为 minus (plus BA BRw) (plus BA BRl)（共同项 A 消去） *)
    assert (Hlhs : Id (minus (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_w))))
                             (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_l)))))
                      (minus (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_w))))
                             (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_l))))))
      by exact (id_cong2 minus Hd_w Hd_l).
    (* 3) 共同被加项消去：minus (plus BA X) (plus BA Y) = minus X Y（minus_plus_common） *)
    assert (Hcom : Id (minus (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_w))))
                             (plus (mult beta A) (mult beta (mult (inv_pos beta beta_pos) (reward s_l)))))
                      (minus (mult beta (mult (inv_pos beta beta_pos) (reward s_w)))
                             (mult beta (mult (inv_pos beta beta_pos) (reward s_l)))))
      by exact (minus_plus_common (mult beta A)
                                  (mult beta (mult (inv_pos beta beta_pos) (reward s_w)))
                                  (mult beta (mult (inv_pos beta beta_pos) (reward s_l)))).
    (* 4) β·(1/β)·r_w = r_w、β·(1/β)·r_l = r_l *)
    assert (Hw : Id (mult beta (mult (inv_pos beta beta_pos) (reward s_w))) (reward s_w)).
    {
      assert (H1 : Id (mult beta (mult (inv_pos beta beta_pos) (reward s_w)))
                      (mult (mult beta (inv_pos beta beta_pos)) (reward s_w)))
        by exact (mult_assoc _ _ _).
      assert (H2a : Id (mult (mult beta (inv_pos beta beta_pos)) (reward s_w)) (mult one (reward s_w)))
        by exact (id_cong (fun x => mult x (reward s_w)) (inv_pos_correct beta beta_pos)).
      assert (H2b : Id (mult one (reward s_w)) (reward s_w))
        by exact (id_trans (mult_comm _ _) (mult_one _)).
      exact (id_trans H1 (id_trans H2a H2b)).
    }
    assert (Hl : Id (mult beta (mult (inv_pos beta beta_pos) (reward s_l))) (reward s_l))
      by exact (id_trans (mult_assoc _ _ _)
                         (id_trans (id_cong (fun x => mult x _) (inv_pos_correct beta beta_pos))
                                   (id_trans (mult_comm _ _) (mult_one _)))).
    (* 5) 组装：LHS → Hlhs → Hcom → 替换 Hw/Hl → reflexivity *)
    assert (Hmid : Id (minus (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_w))))
                             (mult beta (plus A (mult (inv_pos beta beta_pos) (reward s_l)))))
                      (minus (reward s_w) (reward s_l)))
      by exact (id_trans Hlhs (id_trans Hcom (id_cong2 minus Hw Hl))).
    exact Hmid.
  }
  exact (id_cong (fun x => opp (log (sigmoid x))) Hmain).
Qed.

(* ============================================================ *)
(* DPO 损失在 π* 处有界（对齐自由能显式.txt：dpo_loss_pi_star_  *)
(* bounded 的零 admit 版本）                                    *)
(* ============================================================ *)
(* 前提：两个构造性有序域标准定理（接口未提供，诚实 Variable—— *)
(* 与 proj_orthogonal_compat 同先例。 *)
(*   1) inv_pos 反单调：0 < a < b ⟹ inv b < inv a（有序域定理）  *)
(*   2) log 严格递增：0 < a < b ⟹ log a < log b（CReals 中可证） *)
(* 证明链：r_w > r_l ⟹ r_w − r_l > 0 ⟹ σ(r_w − r_l) > σ(0) = 1/2 *)
(*   ⟹ −log σ(r_w − r_l) < −log σ(0) = log 2（σ 严格递增 +       *)
(*   log 严格递增 + opp_lt_compat + log_inv_one_inv + double_neg）*)
(* ------------------------------------------------------------ *)

(* inv_pos 反单调（诚实 Variable：构造性有序域标准定理） *)
Variable inv_pos_lt_contra :
  forall (a b : R) (Ha : lt zero a) (Hb : lt zero b),
    lt a b -> lt (inv_pos b Hb) (inv_pos a Ha).

(* 严格序的加法保序混合版（诚实 Variable：le 与 lt 混合，构造性可接受） *)
Variable lt_plus_compat_le_lt :
  forall a b c d : R, le a b -> lt c d -> lt (plus a c) (plus b d).
Variable lt_plus_compat_lt_le :
  forall a b c d : R, lt a b -> le c d -> lt (plus a c) (plus b d).

(* log 严格递增（诚实 Variable：构造性分析标准定理） *)
Variable log_lt_mono :
  forall a b : R, lt zero a -> lt zero b -> lt a b -> lt (log a) (log b).

(* sigmoid 严格递增：x < y ⟹ σ(x) < σ(y)
   非平凡：exp_neg_decr（指数反序）⟹ 分母反序（le/lt 混合保序）⟹
   inv_pos_lt_contra。 *)
Lemma sigmoid_strict_inc : forall x y : R,
  lt x y -> lt (sigmoid x) (sigmoid y).
Proof.
  intros x y Hxy.
  unfold sigmoid.
  (* exp_neg_decr：x < y ⟹ e^{-y} < e^{-x} *)
  assert (Hexp : lt (exp_neg y) (exp_neg x)) by exact (exp_neg_decr x y Hxy).
  (* 分母：1 + e^{-y} < 1 + e^{-x}（le one one + Hexp 混合保序） *)
  assert (Hden : lt (plus one (exp_neg y)) (plus one (exp_neg x)))
    by exact (lt_plus_compat_le_lt one one (exp_neg y) (exp_neg x) (le_refl one) Hexp).
  exact (inv_pos_lt_contra (plus one (exp_neg y)) (plus one (exp_neg x))
                           (sigmoid_denom_pos y) (sigmoid_denom_pos x) Hden).
Qed.

(* σ(0) = 1/(1+1) = inv_pos 2：exp_neg_zero 折叠 + inv_pos_ext *)
Lemma sigmoid_zero_half :
  Id (sigmoid zero) (inv_pos (plus one one) two_pos).
Proof.
  unfold sigmoid.
  assert (He : Id (exp_neg zero) one) by exact (exp_neg_zero).
  assert (Hp : Id (plus one (exp_neg zero)) (plus one one))
    by exact (id_cong (fun x => plus one x) He).
  exact (inv_pos_ext (plus one (exp_neg zero)) (plus one one)
                     (sigmoid_denom_pos zero) two_pos Hp).
Qed.

(* DPO 损失在 π* 处有界：r_w > r_l ⟹ L_DPO(π*, s_w, s_l) < log 2
   非平凡：sigmoid 严格递增 + log 严格递增 + opp_lt_compat +
   σ(0)=1/2 + log_inv_one_inv（−log(1/2) = log 2），约 20 步。 *)
Theorem dpo_loss_pi_star_bounded :
  forall s_w s_l : S,
    lt (reward s_l) (reward s_w) ->
    lt (dpo_loss_pair pi_star s_w s_l) (log (plus one one)).
Proof.
  intros s_w s_l Hrw.
  rewrite (dpo_loss_at_pi_star s_w s_l).
  (* 1. r_w − r_l > 0（le_plus_compat + plus_opp 构造） *)
  assert (Hpos : lt zero (minus (reward s_w) (reward s_l))).
  {
    unfold minus.
    (* lt (plus r_l (opp r_l)) (plus r_w (opp r_l))：lt r_l r_w + le (opp r_l) (opp r_l) *)
    assert (H1 : lt (plus (reward s_l) (opp (reward s_l))) (plus (reward s_w) (opp (reward s_l))))
      by exact (lt_plus_compat_lt_le (reward s_l) (reward s_w) (opp (reward s_l)) (opp (reward s_l))
                                     Hrw (le_refl (opp (reward s_l)))).
    assert (H2 : Id (plus (reward s_l) (opp (reward s_l))) zero) by exact (plus_opp _).
    exact (lt_id_l zero (plus (reward s_l) (opp (reward s_l)))
                   (plus (reward s_w) (opp (reward s_l))) (id_sym H2) H1).
  }
  (* 2. σ(r_w − r_l) > σ(0)（sigmoid_strict_inc） *)
  assert (Hsig : lt (sigmoid zero) (sigmoid (minus (reward s_w) (reward s_l))))
    by exact (sigmoid_strict_inc zero (minus (reward s_w) (reward s_l)) Hpos).
  (* 3. log σ(r_w − r_l) > log σ(0)（log_lt_mono + sigmoid_pos） *)
  assert (Hlog : lt (log (sigmoid zero)) (log (sigmoid (minus (reward s_w) (reward s_l)))))
    by exact (log_lt_mono (sigmoid zero) (sigmoid (minus (reward s_w) (reward s_l)))
                          (sigmoid_pos zero) (sigmoid_pos (minus (reward s_w) (reward s_l))) Hsig).
  (* 4. −log σ(r_w − r_l) < −log σ(0)（opp_lt_compat） *)
  assert (Hopp : lt (opp (log (sigmoid (minus (reward s_w) (reward s_l)))))
                    (opp (log (sigmoid zero))))
    by exact (opp_lt_compat (log (sigmoid zero)) (log (sigmoid (minus (reward s_w) (reward s_l)))) Hlog).
  (* 5. −log σ(0) = log 2（σ(0) = 1/2，log_inv_one_inv，double_neg） *)
  assert (Hval : Id (opp (log (sigmoid zero))) (log (plus one one))).
  {
    rewrite sigmoid_zero_half.
    assert (Hlogi : Id (log (inv_pos (plus one one) two_pos)) (opp (log (plus one one))))
      by exact (log_inv_one_inv (plus one one) two_pos).
    assert (Hopp2 : Id (opp (opp (log (plus one one)))) (log (plus one one)))
      by exact (double_neg (log (plus one one))).
    exact (id_trans (id_cong opp Hlogi) Hopp2).
  }
  (* 6. 组装：L < −log σ(0) = log 2（lt_id_r 替换） *)
  exact (lt_id_r (opp (log (sigmoid (minus (reward s_w) (reward s_l)))))
                 (opp (log (sigmoid zero)))
                 (log (plus one one)) Hval Hopp).
Qed.

(* 对齐自由能显式：F_align[π] = −E_π[r] + β·KL(π‖π_ref)
   非平凡：由 align_objective_explicit（J = E − β·KL）取负推导——
   opp_plus 分配 + double_neg 折叠 + 显式展开（约 8 步，非公理重述）。 *)
Theorem align_free_energy_explicit :
  forall pi : S -> R,
    Id (free_energy align_energy beta pi)
       (plus (opp (sum_over_S (fun s => mult (pi s) (reward s))))
             (mult beta (relative_entropy pi pi_ref))).
Proof.
  intro pi.
  (* J(pi) = E[r] − β·KL（align_objective_explicit 显式展开） *)
  assert (Hj : Id (opp (free_energy align_energy beta pi))
                  (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                         (mult beta (relative_entropy pi pi_ref)))).
  {
    unfold align_objective in *.
    unfold expected_reward, kl_reference in *.
    exact (align_objective_explicit pi).
  }
  (* F = opp (J) = opp (E − β·KL) = −E + β·KL（取负 + opp_plus + double_neg） *)
  assert (Hopp : Id (opp (opp (free_energy align_energy beta pi)))
                    (opp (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                                (mult beta (relative_entropy pi pi_ref)))))
    by exact (id_cong opp Hj).
  assert (Hdd : Id (opp (opp (free_energy align_energy beta pi)))
                   (free_energy align_energy beta pi))
    by exact (double_neg (free_energy align_energy beta pi)).
  (* opp (minus E KL) = plus (opp E) (mult beta KL)：unfold minus + opp_plus + double_neg *)
  assert (Hrhs : Id (opp (minus (sum_over_S (fun s => mult (pi s) (reward s)))
                                (mult beta (relative_entropy pi pi_ref))))
                    (plus (opp (sum_over_S (fun s => mult (pi s) (reward s))))
                          (mult beta (relative_entropy pi pi_ref)))).
  {
    unfold minus.
    assert (H1 : Id (opp (plus (sum_over_S (fun s => mult (pi s) (reward s)))
                               (opp (mult beta (relative_entropy pi pi_ref)))))
                    (plus (opp (sum_over_S (fun s => mult (pi s) (reward s))))
                          (opp (opp (mult beta (relative_entropy pi pi_ref))))))
      by exact (opp_plus (sum_over_S (fun s => mult (pi s) (reward s)))
                         (opp (mult beta (relative_entropy pi pi_ref)))).
    assert (H2 : Id (plus (opp (sum_over_S (fun s => mult (pi s) (reward s))))
                          (opp (opp (mult beta (relative_entropy pi pi_ref)))))
                    (plus (opp (sum_over_S (fun s => mult (pi s) (reward s))))
                          (mult beta (relative_entropy pi pi_ref))))
      by exact (id_cong (fun x => plus (opp (sum_over_S (fun s => mult (pi s) (reward s)))) x)
                        (double_neg (mult beta (relative_entropy pi pi_ref)))).
    exact (id_trans H1 H2).
  }
  exact (id_trans (id_sym Hdd) (id_trans Hopp Hrhs)).
Qed.

(* ------------------------------------------------------------ *)
(* KL 正则化奖励最大化最优性定理链 3 小项（参考文件消化落地）     *)
(* 重叠项（rlhf_optimal/unique、align_free_energy_explicit、     *)
(* align_objective_explicit、sum_opp/sum_minus、kl_divergence）   *)
(* 已在前文实现；此处落地其余 3 项：                              *)
(*   ① align_free_energy_pi_star：F[π*] = F[boltzmann] 外延性    *)
(*   ② pi_star_objective_value：J(pi_star) 显式值（推论）        *)
(*   ③ align_cross_entropy：对齐交叉熵定义                       *)
(* ------------------------------------------------------------ *)

(* ① 核心外延性：π* 与 Boltzmann 分布共享对齐自由能              *)
Lemma align_free_energy_pi_star :
  Id (free_energy align_energy beta pi_star)
     (free_energy align_energy beta (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos)).
Proof.
  unfold free_energy.
  assert (Hext1 : Id (sum_over_S (fun s => mult (pi_star s) (align_energy s)))
                     (sum_over_S (fun s => mult (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s) (align_energy s)))).
  { apply sum_over_S_ext. intro s.
    exact (id_cong (fun x => mult x (align_energy s)) (id_sym (align_boltzmann_is_pi_star s))). }
  assert (Hext2 : Id (sum_over_S (fun s => mult (pi_star s) (log (pi_star s))))
                     (sum_over_S (fun s => mult (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s) (log (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s))))).
  { apply sum_over_S_ext. intro s.
    assert (Hlog : Id (log (pi_star s)) (log (boltzmann_dist align_energy beta beta_pos Z_align Z_align_pos s)))
      by exact (id_cong log (id_sym (align_boltzmann_is_pi_star s))).
    exact (id_cong2 mult (id_sym (align_boltzmann_is_pi_star s)) Hlog). }
  exact (id_cong2 plus Hext1 (id_cong (fun x => mult beta x) Hext2)).
Qed.

(* ② 推论：π* 的显式目标值 J(pi_star) = E_{π*}[r] − β·KL(π*‖π_ref) *)
Corollary pi_star_objective_value :
  Id (align_objective pi_star)
     (minus (expected_reward pi_star) (mult beta (kl_reference pi_star))).
Proof.
  exact (align_objective_explicit pi_star).
Qed.

(* ③ 对齐交叉熵：H_align(π, π_ref) = −Σ π·log π_ref
   （reward 视为 logits 负损失时，最小化交叉熵即最大化奖励；
     供外部模块如 LanguageModelInstance 实例化使用）             *)
Definition align_cross_entropy (pi : S -> R) : R :=
  sum_over_S (fun s => mult (pi s) (opp (log (pi_ref s)))).

(* ============================================================
   论文1 PPO 补强（T1.1，2026-09-01）：
   标准形式 PPO 保守性——任意符号 adv（无需 advantage_nonneg）。
   ppo_surrogate（L18056）已是标准形式 min(r·A, clip(r)·A)；
   其保守性 min(r·A, clip(r)·A) ≤ r·A 由 min_le_l 一步给出，
   不依赖 adv 的符号（对照：现有 ppo_conservative L18023 的
   min(r, clip(r))·A 形式需 advantage_nonneg L17994）。
   由此消除论文 §6 边界声明一的符号限制：标准形式的保守性
   对任意符号 adv 成立。Set 层 / 零经典 / 可提取。
   ============================================================ *)
Theorem ppo_surrogate_conservative :
  forall (pi : S -> R) (adv : S -> R) (eps : R),
  forall (Hpi_old_pos : forall s : S, lt zero (pi_old s)),
  le (ppo_surrogate pi pi_old adv eps Hpi_old_pos)
     (sum_over_S (fun s => mult (pi_old s) (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s)))).
Proof.
  intros pi adv eps Hpi_old_pos.
  unfold ppo_surrogate.
  apply sum_over_S_le.
  intro s.
  (* 逐点：min(r·A, clip·A) ≤ r·A（min_le_l，无需 adv 符号） *)
  assert (Hmin : le (min (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s))
                         (mult (ppo_clip (policy_ratio pi pi_old s (Hpi_old_pos s))
                                         (minus one eps) (plus one eps)) (adv s)))
                    (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s)))
    by exact (min_le_l (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s))
                       (mult (ppo_clip (policy_ratio pi pi_old s (Hpi_old_pos s))
                                       (minus one eps) (plus one eps)) (adv s))).
  (* pi_old ≥ 0（由 Hpi_old_pos 经 lt_le_iff） *)
  assert (Hpi : le zero (pi_old s))
    by (apply (lt_le_iff _ _); left; apply Hpi_old_pos).
  (* 乘正因子保序：pi_old·min(rA, cA) ≤ pi_old·(rA) *)
  exact (le_mult_compat_r (pi_old s)
                          (min (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s))
                               (mult (ppo_clip (policy_ratio pi pi_old s (Hpi_old_pos s))
                                               (minus one eps) (plus one eps)) (adv s)))
                          (mult (policy_ratio pi pi_old s (Hpi_old_pos s)) (adv s))
                          Hpi Hmin).
Qed.

(* ===== T1.2 新定义 ===== *)
Variable eta : R.
Variable eta_pos : lt zero eta.
Variable eta_le_one : le eta one.

(* 诚实接口假设：正项和为正（Real 层有限和可实例化；同 Z_align_pos 先例） *)
Variable sum_over_S_pos : forall (f : S -> R), (forall s : S, lt zero (f s)) -> lt zero (sum_over_S f).

Definition advantage_aug (pi_t : S -> R) (s : S) : R :=
  minus (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s)))).

Definition Z_rel (pi_t : S -> R) : R :=
  sum_over_S (fun s => mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))).

Lemma Z_rel_pos : forall (pi_t : S -> R),
  (forall s : S, lt zero (pi_t s)) ->
  lt zero (Z_rel pi_t).
Proof.
  intros pi_t Hpos.
  apply sum_over_S_pos.
  intro s.
  apply mult_positive.
  - exact (Hpos s).
  - apply exp_neg_pos.
Qed.

Definition energy_t (pi_t : S -> R) (s : S) : R :=
  minus (opp (mult eta (advantage_aug pi_t s))) (mult beta (log (pi_t s))).

Definition pi_next (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (s : S) : R :=
  mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
       (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))).

(* 引理 A：Boltzmann 因子桥 *)
Lemma boltzmann_factor_bridge :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (s : S),
    Id (exp_neg (mult (inv_pos beta beta_pos) (energy_t pi_t s)))
       (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))).
Proof.
  intros pi_t pi_t_pos s.
  unfold energy_t, advantage_aug.
  set (A := minus (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s))))).
  assert (H1a : Id (mult (inv_pos beta beta_pos) (opp (mult eta A)))
                   (opp (mult (mult eta (inv_pos beta beta_pos)) A))).
  {
    apply (id_trans (opp_mult_l (inv_pos beta beta_pos) (mult eta A))).
    apply (id_cong opp
           (id_trans (mult_assoc (inv_pos beta beta_pos) eta A)
                     (id_cong (fun x => mult x A) (mult_comm (inv_pos beta beta_pos) eta)))).
  }
  assert (H1b : Id (mult (inv_pos beta beta_pos) (mult beta (log (pi_t s)))) (log (pi_t s))).
  {
    apply (id_trans (mult_assoc (inv_pos beta beta_pos) beta (log (pi_t s)))).
    apply (id_trans (id_cong (fun x => mult x (log (pi_t s)))
                             (id_trans (mult_comm (inv_pos beta beta_pos) beta) (inv_pos_correct beta beta_pos)))).
    apply (id_trans (mult_comm one (log (pi_t s))) (mult_one (log (pi_t s)))).
  }
  assert (H1 : Id (mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s)))))
                  (minus (opp (mult (mult eta (inv_pos beta beta_pos)) A)) (log (pi_t s)))).
  {
    apply (id_trans (mult_minus_distr_l (inv_pos beta beta_pos) (opp (mult eta A)) (mult beta (log (pi_t s))))).
    apply (id_trans (id_cong (fun x => minus x (mult (inv_pos beta beta_pos) (mult beta (log (pi_t s))))) H1a)).
    apply (id_cong (fun x => minus (opp (mult (mult eta (inv_pos beta beta_pos)) A)) x) H1b).
  }
  assert (H2 : Id (mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s)))))
                  (minus (opp (mult (mult eta (inv_pos beta beta_pos)) A)) (log (pi_t s)))).
  { exact H1. }
  assert (H3 : Id (opp (mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s))))))
                  (plus (mult (mult eta (inv_pos beta beta_pos)) A) (log (pi_t s)))).
  {
    apply (id_trans (id_cong opp H2)).
    apply (id_trans (opp_minus (opp (mult (mult eta (inv_pos beta beta_pos)) A)) (log (pi_t s)))).
    apply (id_cong (fun x => plus x (log (pi_t s)))).
    apply double_neg.
  }
  assert (H4 : Id (mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s)))))
                  (opp (plus (mult (mult eta (inv_pos beta beta_pos)) A) (log (pi_t s))))).
  {
    set (X := mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s))))).
    apply (id_trans (id_sym (double_neg X)) (id_sym (id_cong opp (id_sym H3)))).
  }
  assert (H5 : Id (exp_neg (mult (inv_pos beta beta_pos) (minus (opp (mult eta A)) (mult beta (log (pi_t s))))))
                  (mult (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) A)))
                        (exp_neg (opp (log (pi_t s)))))).
  {
    apply (id_trans (id_cong (fun t => exp_neg t) H4)).
    apply exp_neg_opp_plus.
  }
  assert (H6 : Id (exp_neg (opp (log (pi_t s)))) (pi_t s))
    by exact (exp_neg_opp_log (pi_t s) (pi_t_pos s)).
  (* 目标重写：energy_t 展开后 *)
  unfold energy_t.
  apply (id_trans H5).
  apply (id_trans (id_cong (fun x => mult (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) A))) x) H6)).
  apply mult_comm.
Qed.

(* 引理 B：Z_rel 的 Boltzmann 形式 *)
Lemma Z_rel_boltzmann_form :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
    Id (Z_rel pi_t)
       (sum_over_S (fun s => exp_neg (mult (inv_pos beta beta_pos) (energy_t pi_t s)))).
Proof.
  intros pi_t pi_t_pos.
  unfold Z_rel.
  apply sum_over_S_ext.
  intro s.
  exact (id_sym (boltzmann_factor_bridge pi_t pi_t_pos s)).
Qed.

(* 引理 C：π_next 的对数展开 *)
Lemma pi_next_log_decomp :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (s : S),
    Id (log (pi_next pi_t pi_t_pos s))
       (plus (log (pi_t s))
             (plus (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))
                   (opp (log (Z_rel pi_t))))).
Proof.
  intros pi_t pi_t_pos s.
  unfold pi_next.
  assert (Hpos1 : lt zero (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)))
    by exact (inv_pos_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)).
  assert (Hpos2 : lt zero (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))).
  { apply mult_positive; [ exact (pi_t_pos s) | apply exp_neg_pos ]. }
  assert (Hlm : Id (log (mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                              (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))))
                   (plus (log (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)))
                         (log (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))))
    by exact (log_mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                       (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))
                       Hpos1 Hpos2).
  assert (Hli : Id (log (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))) (opp (log (Z_rel pi_t))))
    by exact (log_inv_one_inv (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)).
  assert (Hpos3 : lt zero (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))
    by exact (exp_neg_pos _).
  assert (Hlm2 : Id (log (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))
                    (plus (log (pi_t s)) (log (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))))
    by exact (log_mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))) (pi_t_pos s) Hpos3).
  assert (Hle : Id (log (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))
                   (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))
    by exact (id_trans (log_exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))
                       (double_neg (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))).
  assert (Hlm2b : Id (log (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))
                     (plus (log (pi_t s)) (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))
    by exact (id_trans Hlm2 (id_cong (fun x => plus (log (pi_t s)) x) Hle)).
  apply (id_trans Hlm).
  apply (id_trans (id_cong (fun x => plus x (log (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))) Hli)).
  apply (id_trans (id_cong (fun x => plus (opp (log (Z_rel pi_t))) x) Hlm2b)).
  (* 重组：opp(log Z) + (log pi_t + X) == log pi_t + (X + opp (log Z)) *)
  set (X := mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)).
  assert (Hre : Id (plus (opp (log (Z_rel pi_t))) (plus (log (pi_t s)) X))
                   (plus (log (pi_t s)) (plus X (opp (log (Z_rel pi_t)))))).
  {
    apply (id_trans (plus_assoc (opp (log (Z_rel pi_t))) (log (pi_t s)) X)).
    apply (id_trans (id_cong (fun y => plus y X) (plus_comm (opp (log (Z_rel pi_t))) (log (pi_t s))))).
    apply (id_trans (id_sym (plus_assoc (log (pi_t s)) (opp (log (Z_rel pi_t))) X))).
    apply (id_cong (fun y => plus (log (pi_t s)) y) (plus_comm (opp (log (Z_rel pi_t))) X)).
  }
  exact Hre.
Qed.

(* 引理 D：π_next 归一化 *)
Lemma pi_next_normalized :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
    Id (sum_over_S (pi_next pi_t pi_t_pos)) one.
Proof.
  intros pi_t pi_t_pos.
  assert (H1 : Id (sum_over_S (fun s => pi_next pi_t pi_t_pos s))
                  (sum_over_S (fun s => mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                                            (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))))
    by (apply sum_over_S_ext; intro s; reflexivity).
  assert (H2 : Id (sum_over_S (fun s => mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                                            (mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))))
                  (mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                        (sum_over_S (fun s => mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s))))))))
    by exact (sum_over_S_linear (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                                (fun s => mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))).
  assert (H3 : Id (mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)) (Z_rel pi_t)) one)
    by exact (id_trans (mult_comm (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)) (Z_rel pi_t))
                       (inv_pos_correct (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))).
  assert (Hdef : Id (sum_over_S (fun s => mult (pi_t s) (exp_neg (opp (mult (mult eta (inv_pos beta beta_pos)) (advantage_aug pi_t s)))))) (Z_rel pi_t))
    by reflexivity.
  apply (id_trans H1 (id_trans H2 (id_trans (id_cong (fun x => mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)) x) Hdef) H3))).
Qed.

(* free_energy 对分布的外延性 *)
Lemma free_energy_ext_t12 :
  forall (energy : S -> R) (D : R) (p q : S -> R),
    (forall s : S, Id (p s) (q s)) ->
    Id (free_energy energy D p) (free_energy energy D q).
Proof.
  intros energy D p q Hpq.
  unfold free_energy.
  apply (id_cong2 plus
         (sum_over_S_ext (fun s => mult (p s) (energy s)) (fun s => mult (q s) (energy s))
                         (fun s => id_cong (fun x => mult x (energy s)) (Hpq s)))
         (id_cong (fun x => mult D x)
                  (sum_over_S_ext (fun s => mult (p s) (log (p s))) (fun s => mult (q s) (log (q s)))
                                  (fun s => id_cong2 mult (Hpq s) (id_cong log (Hpq s)))))).
Qed.

(* 引理 E：相对自由能分解 *)
Lemma rel_free_energy_decomp :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (pi_t_norm : Id (sum_over_S pi_t) one),
    Id (free_energy (energy_t pi_t) beta pi_t)
       (plus (free_energy (energy_t pi_t) beta (pi_next pi_t pi_t_pos))
             (mult beta
               (sum_over_S (fun s => mult (pi_t s)
                 (minus (log (pi_t s)) (log (pi_next pi_t pi_t_pos s))))))).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  assert (Hext : forall s : S, Id (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos) s)
                                 (pi_next pi_t pi_t_pos s)).
  {
    intro s.
    unfold boltzmann_dist, pi_next.
    apply (id_cong (fun x => mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)) x)).
    exact (boltzmann_factor_bridge pi_t pi_t_pos s).
  }
  pose proof (free_energy_kl_decomp (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)
                                    (Z_rel_boltzmann_form pi_t pi_t_pos) pi_t pi_t_norm) as Hdec.
  apply (id_trans Hdec).
  apply (id_cong2 plus
         (free_energy_ext_t12 (energy_t pi_t) beta
                          (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                          (pi_next pi_t pi_t_pos) Hext)
         (id_cong (fun x => mult beta x)
                  (sum_over_S_ext
                    (fun s => mult (pi_t s) (minus (log (pi_t s)) (log (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos) s))))
                    (fun s => mult (pi_t s) (minus (log (pi_t s)) (log (pi_next pi_t pi_t_pos s))))
                    (fun s => id_cong (fun y => mult (pi_t s) (minus (log (pi_t s)) y)) (id_cong log (Hext s)))))).
Qed.

(* r(s) == A_t(s) + beta·(log pi_t(s) - log pi_ref(s))（advantage_aug 定义反解） *)
Lemma reward_expand :
  forall (pi_t : S -> R) (s : S),
    Id (reward s)
       (plus (advantage_aug pi_t s)
             (minus (mult beta (log (pi_t s))) (mult beta (log (pi_ref s))))).
Proof.
  intros pi_t s.
  unfold advantage_aug.
  (* A == minus (reward s) (mult beta (minus (log pi_t) (log pi_ref)))
     ⟹ reward s == A + mult beta (minus (log pi_t) (log pi_ref)) *)
  assert (Hc : Id (plus (minus (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s)))))
                        (mult beta (minus (log (pi_t s)) (log (pi_ref s)))))
                  (reward s))
    by exact (minus_plus_cancel_gap (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s))))).
  apply (id_trans (id_sym Hc)).
  apply (id_cong (fun y => plus (minus (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s))))) y)
                 (mult_minus_distr_l beta (log (pi_t s)) (log (pi_ref s)))).
Qed.


(* ===== T1.2 第二阶段：策略改进单调性主定理（2026-09-01） ===== *)
(* opp 提和：Σ (opp·f) == opp (Σ f) *)
Lemma sum_over_S_opp_t12 : forall (f : S -> R),
  Id (sum_over_S (fun s => opp (f s))) (opp (sum_over_S f)).
Proof.
  intro f.
  apply (id_trans (sum_over_S_ext _ _
        (fun s => id_sym (id_trans (opp_mult_r one (f s))
                                   (id_cong opp (id_trans (mult_comm one (f s)) (mult_one (f s)))))))).
  apply (id_trans (sum_over_S_linear (opp one) f)
                  (id_trans (opp_mult_r one (sum_over_S f))
                            (id_cong opp (id_trans (mult_comm one (sum_over_S f)) (mult_one (sum_over_S f)))))).
Qed.

(* F_t(pi_t) == opp (eta·Σ pi_t·A_t) *)
(* 通用：Σ pi_t·(opp(a·f)) == opp (a·Σ pi_t·f) *)
Lemma sum_ptimes_opp_scal_t12 :
  forall (pi_t : S -> R) (a : R) (f : S -> R),
    Id (sum_over_S (fun s => mult (pi_t s) (opp (mult a (f s)))))
       (opp (mult a (sum_over_S (fun s => mult (pi_t s) (f s))))).
Proof.
  intros pi_t a f.
  set (Lf := fun s : S => mult (pi_t s) (opp (mult a (f s)))).
  set (Rf := fun s : S => opp (mult a (mult (pi_t s) (f s)))).
  assert (Hpt : forall s : S, Id (Lf s) (Rf s)).
  {
    intro s. unfold Lf, Rf.
    assert (Hm : Id (mult (pi_t s) (mult a (f s))) (mult a (mult (pi_t s) (f s)))).
    {
      apply (id_trans (mult_assoc (pi_t s) a (f s))
                      (id_trans (id_cong (fun x => mult x (f s)) (mult_comm (pi_t s) a))
                                (id_sym (mult_assoc a (pi_t s) (f s))))).
    }
    apply (id_trans (opp_mult_l (pi_t s) (mult a (f s))) (id_cong opp Hm)).
  }
  assert (HsumR : Id (sum_over_S Rf) (opp (mult a (sum_over_S (fun s => mult (pi_t s) (f s)))))).
  {
    unfold Rf.
    apply (id_trans (sum_over_S_opp_t12 (fun s => mult a (mult (pi_t s) (f s))))
                    (id_cong opp (sum_over_S_linear a (fun s => mult (pi_t s) (f s))))).
  }
  unfold Lf.
  apply (id_trans (sum_over_S_ext Lf Rf Hpt) HsumR).
Qed.



(* 通用：Σ pi_t·(a·log) 直接由 sum_over_S_linear 经逐点重组给出——F_t_simpl_t 内联使用 *)

(* 通用：Σ pi_t·(a·f) == a·Σ pi_t·f *)
Lemma sum_ptimes_scal_t12 :
  forall (pi_t : S -> R) (a : R) (f : S -> R),
    Id (sum_over_S (fun s => mult (pi_t s) (mult a (f s))))
       (mult a (sum_over_S (fun s => mult (pi_t s) (f s)))).
Proof.
  intros pi_t a f.
  apply (id_trans (sum_over_S_ext _ _
    (fun s => id_trans (mult_assoc (pi_t s) a (f s))
                       (id_trans (id_cong (fun x => mult x (f s)) (mult_comm (pi_t s) a))
                                 (id_sym (mult_assoc a (pi_t s) (f s))))))).
  apply (sum_over_S_linear a (fun s => mult (pi_t s) (f s))).
Qed.

Lemma F_t_simpl_t :
  forall (pi_t : S -> R),
    Id (free_energy (energy_t pi_t) beta pi_t)
       (opp (mult eta (sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s))))).
Proof.
  intros pi_t.
  unfold free_energy, energy_t, advantage_aug.
  set (A := advantage_aug pi_t).
  set (S1t := sum_over_S (fun s => mult (pi_t s) (log (pi_t s)))).
  assert (H1 : Id (sum_over_S (fun s => mult (pi_t s) (opp (mult eta (A s)))))
                  (opp (mult eta (sum_over_S (fun s => mult (pi_t s) (A s)))))).
  { exact (sum_ptimes_opp_scal_t12 pi_t eta A). }
  assert (H2 : Id (sum_over_S (fun s => mult (pi_t s) (mult beta (log (pi_t s)))))
                  (mult beta S1t)).
  {
    unfold S1t.
    apply (id_trans (sum_over_S_ext _ _
      (fun s => id_trans (mult_assoc (pi_t s) beta (log (pi_t s)))
                         (id_trans (id_cong (fun x => mult x (log (pi_t s))) (mult_comm (pi_t s) beta))
                                   (id_sym (mult_assoc beta (pi_t s) (log (pi_t s)))))))).
    apply (sum_over_S_linear beta (fun s => mult (pi_t s) (log (pi_t s)))).
  }
  assert (Hsum : Id (sum_over_S (fun s => mult (pi_t s) (minus (opp (mult eta (A s))) (mult beta (log (pi_t s))))))
                    (minus (opp (mult eta (sum_over_S (fun s => mult (pi_t s) (A s))))) (mult beta S1t))).
  {
    apply (id_trans (sum_over_S_ext _ _
      (fun s => mult_minus_distr_l (pi_t s) (opp (mult eta (A s))) (mult beta (log (pi_t s)))))).
    apply (id_trans (sum_over_S_minus (fun s => mult (pi_t s) (opp (mult eta (A s))))
                                      (fun s => mult (pi_t s) (mult beta (log (pi_t s)))))).
    apply (id_cong2 minus H1 H2).
  }
  set (SX := opp (mult eta (sum_over_S (fun s => mult (pi_t s) (A s))))).
  apply (id_trans (id_cong2 plus Hsum (id_refl)) (minus_plus_cancel_gap SX (mult beta S1t))).
Qed.



(* F_t(pi_next) == opp (beta·log Z_rel)（pi_next_log_decomp + ΣNp 归一化） *)
(* 通用：Σ pi_t·(opp c) == opp c（Σ pi_t = 1） *)
Lemma sum_ptimes_opp_const_t12 :
  forall (pi_t : S -> R) (pi_t_norm : Id (sum_over_S pi_t) one) (c : R),
    Id (sum_over_S (fun s => mult (pi_t s) (opp c))) (opp c).
Proof.
  intros pi_t pi_t_norm c.
  apply (id_trans (sum_over_S_ext _ _ (fun s => mult_comm (pi_t s) (opp c)))).
  apply (id_trans (sum_over_S_linear (opp c) pi_t)
                  (id_trans (id_cong (fun x => mult (opp c) x) pi_t_norm)
                            (mult_one (opp c)))).
Qed.

(* beta·(eta·(1/beta)·a) == eta·a（inv_pos_correct 吸收） *)
Lemma beta_eta_inv_absorb_t12 : forall (a : R),
  Id (mult beta (mult (mult eta (inv_pos beta beta_pos)) a)) (mult eta a).
Proof.
  intro a.
  apply (id_trans (mult_assoc beta (mult eta (inv_pos beta beta_pos)) a)).
  apply (id_trans (id_cong (fun x => mult x a)
    (id_trans (mult_assoc beta eta (inv_pos beta beta_pos))
              (id_trans (id_cong (fun x => mult x (inv_pos beta beta_pos)) (mult_comm beta eta))
                        (id_sym (mult_assoc eta beta (inv_pos beta beta_pos))))))).
  apply (id_cong (fun x => mult x a)
               (id_trans (id_cong (fun x => mult eta x) (inv_pos_correct beta beta_pos))
                         (mult_one eta))).
Qed.

Lemma F_t_simpl_next :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
    Id (free_energy (energy_t pi_t) beta (pi_next pi_t pi_t_pos))
       (opp (mult beta (log (Z_rel pi_t)))).
Proof.
  intros pi_t pi_t_pos.
  unfold free_energy, energy_t, advantage_aug.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (S1n := sum_over_S (fun s => mult (Np s) (log (pi_t s)))).
  set (SAn := sum_over_S (fun s => mult (Np s) (A s))).
  set (M := mult eta (inv_pos beta beta_pos)).
  (* H1：Σ Np·energy_t == -eta·SAn - beta·S1n *)
  assert (H1 : Id (sum_over_S (fun s => mult (Np s) (minus (opp (mult eta (A s))) (mult beta (log (pi_t s))))))
                  (minus (opp (mult eta SAn)) (mult beta S1n))).
  {
    apply (id_trans (sum_over_S_ext _ _
      (fun s => mult_minus_distr_l (Np s) (opp (mult eta (A s))) (mult beta (log (pi_t s)))))).
    apply (id_trans (sum_over_S_minus (fun s => mult (Np s) (opp (mult eta (A s))))
                                      (fun s => mult (Np s) (mult beta (log (pi_t s)))))).
    apply (id_cong2 minus (sum_ptimes_opp_scal_t12 Np eta A)
                           (sum_ptimes_scal_t12 Np beta (fun s => log (pi_t s)))).
  }
  (* H2：Σ Np·log Np == S1n + M·SAn - log Z *)
  assert (HlogNp : forall s : S, Id (log (Np s))
                                   (plus (log (pi_t s)) (plus (mult M (A s)) (opp (log (Z_rel pi_t)))))).
  { intro s. unfold Np, A, M. exact (pi_next_log_decomp pi_t pi_t_pos s). }
  assert (H2 : Id (sum_over_S (fun s => mult (Np s) (log (Np s))))
                  (plus S1n (plus (mult M SAn) (opp (log (Z_rel pi_t)))))).
  {
    unfold S1n, SAn.
    apply (id_trans (sum_over_S_ext _ _
      (fun s => id_cong (fun y => mult (Np s) y) (HlogNp s)))).
    apply (id_trans (sum_over_S_ext _ _
      (fun s => distrib (Np s) (log (pi_t s)) (plus (mult M (A s)) (opp (log (Z_rel pi_t))))))).
    assert (Ht2 : Id (sum_over_S (fun s => mult (Np s) (plus (mult M (A s)) (opp (log (Z_rel pi_t))))))(
                     (plus (mult M SAn) (opp (log (Z_rel pi_t)))))).
    {
      unfold SAn.
      assert (Ht2a : Id (sum_over_S (fun s => mult (Np s) (mult M (A s)))) (mult M SAn)).
      { unfold SAn. exact (sum_ptimes_scal_t12 Np M A). }
      assert (Ht2b : Id (sum_over_S (fun s => mult (Np s) (opp (log (Z_rel pi_t))))) (opp (log (Z_rel pi_t)))).
      { exact (sum_ptimes_opp_const_t12 Np (pi_next_normalized pi_t pi_t_pos) (log (Z_rel pi_t))). }
      apply (id_trans (sum_over_S_ext _ _ (fun s => distrib (Np s) (mult M (A s)) (opp (log (Z_rel pi_t)))))).
      apply (id_trans (sum_over_S_add (fun s => mult (Np s) (mult M (A s)))
                                      (fun s => mult (Np s) (opp (log (Z_rel pi_t)))))).
      apply (id_cong2 plus Ht2a Ht2b).
    }
    apply (id_trans (sum_over_S_add (fun s => mult (Np s) (log (pi_t s)))
                            (fun s => mult (Np s) (plus (mult M (A s)) (opp (log (Z_rel pi_t))))))
                    (id_cong2 plus (id_refl) Ht2)).
  }
  set (SX := opp (mult eta SAn)).
  set (SY := mult beta S1n).
  apply (id_trans (id_cong2 plus H1 (id_cong (fun x => mult beta x) H2))).
  apply (id_trans (id_cong (fun x => plus (minus SX SY) x)
                           (distrib beta S1n (plus (mult M SAn) (opp (log (Z_rel pi_t))))))).
  apply (id_trans (id_cong (fun x => plus (minus SX SY) (plus (mult beta S1n) x))
                           (distrib beta (mult M SAn) (opp (log (Z_rel pi_t)))))).
  apply (id_trans (id_cong (fun x => plus (minus SX SY) (plus (mult beta S1n) (plus x (mult beta (opp (log (Z_rel pi_t)))))))
                           (beta_eta_inv_absorb_t12 SAn))).
  apply (id_trans (id_cong (fun x => plus (minus SX SY) (plus (mult beta S1n) (plus (mult eta SAn) x)))
                           (opp_mult_l beta (log (Z_rel pi_t))))).
  apply (id_trans (plus_assoc (minus SX SY) (mult beta S1n) (plus (mult eta SAn) (opp (mult beta (log (Z_rel pi_t))))))).
  apply (id_trans (id_cong (fun x => plus x (plus (mult eta SAn) (opp (mult beta (log (Z_rel pi_t)))))) (minus_plus_cancel_gap SX SY))).
  apply (id_trans (plus_assoc SX (mult eta SAn) (opp (mult beta (log (Z_rel pi_t)))))).
  unfold SX.
  apply (id_trans (id_cong (fun x => plus x (opp (mult beta (log (Z_rel pi_t)))))
                          (id_trans (plus_comm (opp (mult eta SAn)) (mult eta SAn))
                                    (plus_opp (mult eta SAn))))).
  apply (id_trans (plus_comm zero (opp (mult beta (log (Z_rel pi_t))))) (plus_zero (opp (mult beta (log (Z_rel pi_t)))))).
Qed.

(* F_t(pi_next) 的 KL 形式：-eta·Σπ_next·A + beta·KL(pi_next||pi_t)（定义性） *)
Lemma F_t_simpl_next_kl :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
    Id (free_energy (energy_t pi_t) beta (pi_next pi_t pi_t_pos))
       (plus (opp (mult eta (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))))
             (mult beta (relative_entropy (pi_next pi_t pi_t_pos) pi_t))).
Proof.
  intros pi_t pi_t_pos.
  unfold free_energy, energy_t, advantage_aug, relative_entropy.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (S1n := sum_over_S (fun s => mult (Np s) (log (pi_t s)))).
  set (SAn := sum_over_S (fun s => mult (Np s) (A s))).
  set (S2n := sum_over_S (fun s => mult (Np s) (log (Np s)))).
  assert (H1 : Id (sum_over_S (fun s => mult (Np s) (minus (opp (mult eta (A s))) (mult beta (log (pi_t s))))))
                  (minus (opp (mult eta SAn)) (mult beta S1n))).
  {
    apply (id_trans (sum_over_S_ext _ _
      (fun s => mult_minus_distr_l (Np s) (opp (mult eta (A s))) (mult beta (log (pi_t s)))))).
    apply (id_trans (sum_over_S_minus (fun s => mult (Np s) (opp (mult eta (A s))))
                                      (fun s => mult (Np s) (mult beta (log (pi_t s)))))).
    apply (id_cong2 minus (sum_ptimes_opp_scal_t12 Np eta A)
                           (sum_ptimes_scal_t12 Np beta (fun s => log (pi_t s)))).
  }
  set (SX := opp (mult eta SAn)).
  set (SY := mult beta S1n).
  (* S2n - S1n == Σ Np (log Np - log pi_t) == relative_entropy Np pi_t *)
  assert (Hkl : Id (minus S2n S1n) (sum_over_S (fun s => mult (Np s) (minus (log (Np s)) (log (pi_t s)))))).
  {
    unfold S2n, S1n.
    apply (id_trans (id_sym (sum_over_S_minus (fun s => mult (Np s) (log (Np s))) (fun s => mult (Np s) (log (pi_t s)))))).
    apply (sum_over_S_ext _ _ (fun s => id_sym (mult_minus_distr_l (Np s) (log (Np s)) (log (pi_t s))))).
  }
  apply (id_trans (id_cong (fun x => plus x (mult beta S2n)) H1)).
  assert (Hm : Id (plus (opp (mult beta S1n)) (mult beta S2n)) (mult beta (minus S2n S1n))).
  {
    unfold minus.
    apply (id_trans (id_cong2 plus (id_sym (opp_mult_l beta S1n)) (id_refl))).
    apply (id_trans (plus_comm (mult beta (opp S1n)) (mult beta S2n))
                    (id_sym (distrib beta S2n (opp S1n)))).
  }
  unfold minus.
  apply (id_trans (id_sym (plus_assoc (opp (mult eta SAn)) (opp (mult beta S1n)) (mult beta S2n)))).
  apply (id_trans (id_cong (fun x => plus (opp (mult eta SAn)) x) Hm)).
  apply (id_cong (fun x => plus (opp (mult eta SAn)) (mult beta x)) Hkl).
Qed.



(* 代理-真实差异恒等式：eta·(Xn - Xt) == beta·(KL(pi_next||pi_t) + KL(pi_t||pi_next)) *)
Lemma surrogate_diff_identity :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (pi_t_norm : Id (sum_over_S pi_t) one),
    forall (pi_next_pos : forall s : S, lt zero (pi_next pi_t pi_t_pos s)),
    Id (mult eta (minus (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))
                        (sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s)))))
       (mult beta (plus (relative_entropy (pi_next pi_t pi_t_pos) pi_t)
                        (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm pi_next_pos.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  pose proof (rel_free_energy_decomp pi_t pi_t_pos pi_t_norm) as Hdec.
  pose proof (F_t_simpl_t pi_t) as HFt.
  pose proof (F_t_simpl_next_kl pi_t pi_t_pos) as HFn.
  assert (Heq : Id (opp (mult eta Xt))
                  (plus (plus (opp (mult eta Xn)) (mult beta K1)) (mult beta K2))).
  {
    apply (id_trans (id_sym HFt)).
    apply (id_trans Hdec).
    apply (id_cong2 plus HFn (id_refl)).
  }
  assert (Heq2 : Id (opp (mult eta Xt))
                   (plus (opp (mult eta Xn)) (plus (mult beta K1) (mult beta K2)))).
  {
    apply (id_trans Heq).
    apply (id_sym (plus_assoc (opp (mult eta Xn)) (mult beta K1) (mult beta K2))).
  }
  assert (Hstep : Id (plus (mult eta Xn) (opp (mult eta Xt)))
                    (plus (mult beta K1) (mult beta K2))).
  {
    apply (id_trans (id_cong2 plus (id_refl) Heq2)).
    apply (id_trans (plus_assoc (mult eta Xn) (opp (mult eta Xn)) (plus (mult beta K1) (mult beta K2)))).
    apply (id_trans (id_cong (fun x => plus x (plus (mult beta K1) (mult beta K2))) (plus_opp (mult eta Xn)))
                    (id_trans (plus_comm zero (plus (mult beta K1) (mult beta K2)))
                              (plus_zero (plus (mult beta K1) (mult beta K2))))).
  }
  apply (id_trans (mult_minus_distr_l eta Xn Xt)
                  (id_trans Hstep (id_sym (distrib beta K1 K2)))).
Qed.

(* pi_next 正性（Boltzmann 构造） *)
Lemma pi_next_pos :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)) (s : S),
    lt zero (pi_next pi_t pi_t_pos s).
Proof.
  intros pi_t pi_t_pos s.
  unfold pi_next.
  apply mult_positive.
  - apply inv_pos_pos.
  - apply mult_positive.
    + exact (pi_t_pos s).
    + apply exp_neg_pos.
Qed.

(* ============ 辅助：le 逆与乘法非负 ============ *)

(* le a b ⟸ le zero (minus b a)（le_minus_nonneg 的逆） *)
Lemma le_nonneg_minus : forall a b : R, le zero (minus b a) -> le a b.
Proof.
  intros a b H.
  unfold minus in H.
  assert (Hstep : le (plus a zero) (plus a (plus b (opp a)))).
  { exact (le_plus_compat a a zero (plus b (opp a)) (le_refl a) H). }
  assert (Hl : Id (plus a zero) a) by exact (plus_zero a).
  assert (Hr : Id (plus a (plus b (opp a))) b).
  {
    apply (id_trans (plus_assoc a b (opp a))).
    apply (id_trans (id_cong (fun x => plus x (opp a)) (plus_comm a b))).
    apply (id_trans (id_sym (plus_assoc b a (opp a)))).
    apply (id_trans (id_cong (fun x => plus b x) (plus_opp a))).
    exact (plus_zero b).
  }
  exact (le_id_l a (plus a zero) b (id_sym Hl)
                (le_id_r (plus a zero) (plus a (plus b (opp a))) b Hr Hstep)).
Qed.

(* 非负乘非负仍非负 *)
Lemma le_mult_nonneg_t12 : forall a b : R, le zero a -> le zero b -> le zero (mult a b).
Proof.
  intros a b Ha Hb.
  assert (Hstep : le (mult zero b) (mult a b))
    by exact (le_mult_compat_weak zero a b Hb Ha).
  assert (Hl : Id (mult zero b) zero)
    by (apply (id_trans (mult_comm zero b)); apply mult_zero).
  exact (le_id_l zero (mult zero b) (mult a b) (id_sym Hl) Hstep).
Qed.

(* 右分配减法：mult (minus a b) c == minus (mult a c) (mult b c) *)
Lemma mult_minus_distr_r_t12 : forall a b c : R,
  Id (mult (minus a b) c) (minus (mult a c) (mult b c)).
Proof.
  intros a b c.
  unfold minus.
  apply (id_trans (mult_comm (plus a (opp b)) c)).
  apply (id_trans (distrib c a (opp b))).
  apply (id_trans (id_cong (fun x => plus x (mult c (opp b))) (mult_comm c a))).
  apply (id_trans (id_cong (fun x => plus (mult a c) x)
                           (id_trans (opp_mult_l c b) (id_cong opp (mult_comm c b))))).
  reflexivity.
Qed.

(* eta·a + (1-eta)·a == a *)
Lemma eta_absorb_t12 : forall a : R,
  Id (plus (mult eta a) (mult (minus one eta) a)) a.
Proof.
  intro a.
  assert (H1 : Id (plus eta (minus one eta)) one).
  {
    unfold minus.
    apply (id_trans (plus_assoc eta one (opp eta))).
    apply (id_trans (id_cong (fun x => plus x (opp eta)) (plus_comm eta one))).
    apply (id_trans (id_sym (plus_assoc one eta (opp eta)))).
    apply (id_trans (id_cong (fun x => plus one x) (plus_opp eta))).
    exact (plus_zero one).
  }
  assert (H2 : Id (plus (mult eta a) (mult (minus one eta) a))
                  (plus (mult a eta) (mult a (minus one eta)))).
  { apply (id_cong2 plus (mult_comm eta a) (mult_comm (minus one eta) a)). }
  assert (H3 : Id (plus (mult a eta) (mult a (minus one eta))) (mult a (plus eta (minus one eta)))).
  { exact (id_sym (distrib a eta (minus one eta))). }
  apply (id_trans H2 (id_trans H3 (id_trans (id_cong (fun x => mult a x) H1) (mult_one a)))).
Qed.

(* ============ 逐点能量差桥 ============ *)

(* align_energy s == energy_t(pi_t) s + (1-eta)·(-advantage_aug(pi_t) s)
   D(s) := align - energy_t == (1-eta)·(-A)（reward_expand + 抵消） *)
Lemma align_energy_expand :
  forall (pi_t : S -> R) (s : S),
    Id (align_energy s)
       (plus (energy_t pi_t s) (mult (minus one eta) (opp (advantage_aug pi_t s)))).
Proof.
  intros pi_t s.
  unfold align_energy, energy_t, advantage_aug.
  set (A := minus (reward s) (mult beta (minus (log (pi_t s)) (log (pi_ref s))))).
  set (B1 := mult beta (log (pi_t s))).
  set (B2 := mult beta (log (pi_ref s))).
  (* H0：reward 展开（advantage_aug 定义反解） *)
  assert (H0 : Id (reward s) (plus A (minus B1 B2))) by exact (reward_expand pi_t s).
  (* H1：opp (reward s) == plus (opp A) (plus (opp B1) B2) *)
  assert (H1 : Id (opp (reward s)) (plus (opp A) (plus (opp B1) B2))).
  {
    apply (id_trans (id_cong opp H0)).
    apply (id_trans (opp_plus A (minus B1 B2))).
    apply (id_cong (fun x => plus (opp A) x) (opp_minus B1 B2)).
  }
  (* H2：LHS 化简为 plus (opp A) (opp B1) *)
  assert (H2 : Id (minus (opp (reward s)) B2) (plus (opp A) (opp B1))).
  {
    unfold minus.
    apply (id_trans (id_cong2 plus H1 (id_refl))).
    apply (id_trans (id_sym (plus_assoc (opp A) (plus (opp B1) B2) (opp B2)))).
    apply (id_trans (id_cong (fun x => plus (opp A) x)
                             (id_sym (plus_assoc (opp B1) B2 (opp B2))))).
    apply (id_trans (id_cong (fun x => plus (opp A) (plus (opp B1) x)) (plus_opp B2))).
    apply (id_cong (fun x => plus (opp A) x) (plus_zero (opp B1))).
  }
  (* H3：(1-eta)·(opp A) == plus (opp A) (mult eta A) *)
  assert (H3 : Id (mult (minus one eta) (opp A)) (plus (opp A) (mult eta A))).
  {
    unfold minus.
    apply (id_trans (mult_comm (plus one (opp eta)) (opp A))).
    apply (id_trans (distrib (opp A) one (opp eta))).
    apply (id_trans (id_cong (fun x => plus x (mult (opp A) (opp eta))) (mult_one (opp A)))).
    apply (id_trans (id_cong (fun x => plus (opp A) x)
                             (id_trans (opp_mult_l (opp A) eta)
                                       (id_trans (id_cong opp (opp_mult_r A eta)) (double_neg (mult A eta)))))).
    apply (id_cong (fun x => plus (opp A) x) (mult_comm A eta)).
  }
  (* H4：RHS 化简为 plus (opp A) (opp B1) *)
  assert (H4 : Id (plus (minus (opp (mult eta A)) B1) (mult (minus one eta) (opp A)))
                  (plus (opp A) (opp B1))).
  {
    unfold minus.
    apply (id_trans (id_cong (fun x => plus (plus (opp (mult eta A)) (opp B1)) x) H3)).
    apply (id_trans (id_sym (plus_assoc (opp (mult eta A)) (opp B1) (plus (opp A) (mult eta A))))).
    apply (id_trans (id_cong (fun x => plus (opp (mult eta A)) x)
                             (id_cong (fun y => plus (opp B1) y)
                                      (plus_comm (opp A) (mult eta A))))).
    apply (id_trans (id_cong (fun x => plus (opp (mult eta A)) x)
                             (plus_assoc (opp B1) (mult eta A) (opp A)))).
    apply (id_trans (plus_assoc (opp (mult eta A)) (plus (opp B1) (mult eta A)) (opp A))).
    apply (id_trans (id_cong (fun x => plus x (opp A))
                             (id_cong (fun y => plus (opp (mult eta A)) y)
                                      (plus_comm (opp B1) (mult eta A))))).
    apply (id_trans (id_cong (fun x => plus x (opp A))
                             (plus_assoc (opp (mult eta A)) (mult eta A) (opp B1)))).
    apply (id_trans (id_cong (fun x => plus x (opp A))
                             (id_cong (fun y => plus y (opp B1))
                                      (plus_comm (opp (mult eta A)) (mult eta A))))).
    apply (id_trans (id_cong (fun x => plus x (opp A))
                             (id_cong (fun y => plus y (opp B1)) (plus_opp (mult eta A))))).
    apply (id_trans (id_cong (fun x => plus x (opp A))
                             (id_trans (plus_comm zero (opp B1)) (plus_zero (opp B1))))).
    apply (plus_comm (opp B1) (opp A)).
  }
  apply (id_trans H2 (id_sym H4)).
Qed.

(* ============ 核心桥：F_align == F_t + (1-eta)·(-Σ p·A) ============ *)

Lemma F_align_F_t_rel :
  forall (pi_t : S -> R) (p : S -> R),
    Id (free_energy align_energy beta p)
       (plus (free_energy (energy_t pi_t) beta p)
             (mult (minus one eta) (opp (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s)))))).
Proof.
  intros pi_t p.
  unfold free_energy.
  assert (Hpt : forall s : S,
    Id (mult (p s) (align_energy s))
       (plus (mult (p s) (energy_t pi_t s))
             (mult (p s) (mult (minus one eta) (opp (advantage_aug pi_t s)))))).
  {
    intro s.
    apply (id_trans (id_cong (fun x => mult (p s) x) (align_energy_expand pi_t s))).
    apply (distrib (p s) (energy_t pi_t s) (mult (minus one eta) (opp (advantage_aug pi_t s)))).
  }
  assert (Hsum : Id (sum_over_S (fun s => mult (p s) (align_energy s)))
                    (plus (sum_over_S (fun s => mult (p s) (energy_t pi_t s)))
                          (sum_over_S (fun s => mult (p s) (mult (minus one eta) (opp (advantage_aug pi_t s))))))).
  {
    apply (id_trans (sum_over_S_ext _ _ Hpt)).
    apply (sum_over_S_add (fun s => mult (p s) (energy_t pi_t s))
                          (fun s => mult (p s) (mult (minus one eta) (opp (advantage_aug pi_t s))))).
  }
  assert (Hscal : Id (sum_over_S (fun s => mult (p s) (mult (minus one eta) (opp (advantage_aug pi_t s)))))
                     (mult (minus one eta) (opp (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s)))))).
  {
    apply (id_trans (sum_ptimes_scal_t12 p (minus one eta) (fun s => opp (advantage_aug pi_t s)))).
    apply (id_cong (fun x => mult (minus one eta) x)
                   (id_trans (sum_over_S_ext _ _ (fun s => opp_mult_l (p s) (advantage_aug pi_t s)))
                             (sum_over_S_opp_t12 (fun s => mult (p s) (advantage_aug pi_t s))))).
  }
  set (SAl := sum_over_S (fun s => mult (p s) (align_energy s))).
  set (SEt := sum_over_S (fun s => mult (p s) (energy_t pi_t s))).
  set (SEnt := sum_over_S (fun s => mult (p s) (log (p s)))).
  set (SA := sum_over_S (fun s => mult (p s) (advantage_aug pi_t s))).
  set (SX := sum_over_S (fun s => mult (p s) (mult (minus one eta) (opp (advantage_aug pi_t s))))).
  apply (id_trans (id_cong2 plus Hsum (id_refl))).
  apply (id_trans (id_sym (plus_assoc SEt SX (mult beta SEnt)))).
  apply (id_trans (id_cong (fun x => plus SEt x)
                           (id_trans (id_cong (fun y => plus y (mult beta SEnt)) Hscal)
                                     (plus_comm (mult (minus one eta) (opp SA)) (mult beta SEnt))))).
  apply (plus_assoc SEt (mult beta SEnt) (mult (minus one eta) (opp SA))).
Qed.

(* ============ J(pi) 分解：align_objective == -F_t + (1-eta)·Σp·A ============ *)

Lemma align_objective_t12_decomp :
  forall (pi_t : S -> R) (p : S -> R),
    Id (align_objective p)
       (plus (opp (free_energy (energy_t pi_t) beta p))
             (mult (minus one eta) (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s))))).
Proof.
  intros pi_t p.
  unfold align_objective.
  pose proof (F_align_F_t_rel pi_t p) as Hrel.
  apply (id_trans (id_cong opp Hrel)).
  apply (id_trans (opp_plus (free_energy (energy_t pi_t) beta p)
                            (mult (minus one eta) (opp (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s))))))).
  apply (id_cong (fun x => plus (opp (free_energy (energy_t pi_t) beta p)) x)
                 (id_trans (id_cong opp (opp_mult_l (minus one eta) (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s)))))
                           (double_neg (mult (minus one eta) (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s))))))).
Qed.

(* ============ J(pi_t) == Σ pi_t·A ============ *)

Lemma J_pi_t_t12 :
  forall (pi_t : S -> R) (pi_t_norm : Id (sum_over_S pi_t) one),
    Id (align_objective pi_t)
       (sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s))).
Proof.
  intros pi_t pi_t_norm.
  pose proof (align_objective_t12_decomp pi_t pi_t) as Hdec.
  pose proof (F_t_simpl_t pi_t) as HFt.
  set (Xt := sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s))).
  apply (id_trans Hdec).
  apply (id_trans (id_cong (fun x => plus x (mult (minus one eta) Xt))
                           (id_trans (id_cong opp HFt) (double_neg (mult eta Xt))))).
  exact (eta_absorb_t12 Xt).
Qed.

(* ============ J(pi_next) == Σ pi_next·A - beta·KL(pi_next||pi_t) ============ *)

Lemma J_pi_next_t12 :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
    Id (align_objective (pi_next pi_t pi_t_pos))
       (minus (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))
              (mult beta (relative_entropy (pi_next pi_t pi_t_pos) pi_t))).
Proof.
  intros pi_t pi_t_pos.
  pose proof (align_objective_t12_decomp pi_t (pi_next pi_t pi_t_pos)) as Hdec.
  pose proof (F_t_simpl_next_kl pi_t pi_t_pos) as HFn.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  assert (Hopp : Id (opp (plus (opp (mult eta Xn)) (mult beta K1)))
                    (plus (mult eta Xn) (opp (mult beta K1)))).
  {
    apply (id_trans (opp_plus (opp (mult eta Xn)) (mult beta K1))).
    apply (id_cong2 plus (double_neg (mult eta Xn)) (id_refl)).
  }
  apply (id_trans Hdec).
  apply (id_trans (id_cong (fun x => plus x (mult (minus one eta) Xn))
                           (id_trans (id_cong opp HFn) Hopp))).
  unfold minus.
  apply (id_trans (id_sym (plus_assoc (mult eta Xn) (opp (mult beta K1)) (mult (minus one eta) Xn)))).
  apply (id_trans (id_cong (fun x => plus (mult eta Xn) x)
                           (plus_comm (opp (mult beta K1)) (mult (minus one eta) Xn)))).
  apply (id_trans (plus_assoc (mult eta Xn) (mult (minus one eta) Xn) (opp (mult beta K1)))).
  apply (id_cong (fun x => plus x (opp (mult beta K1))) (eta_absorb_t12 Xn)).
Qed.

(* ============ 主定理：策略改进单调性 ============ *)

Theorem policy_improvement_mono :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    le (align_objective pi_t) (align_objective (pi_next pi_t pi_t_pos)).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  assert (HNp_pos : forall s : S, lt zero (Np s)) by (intro s; unfold Np; apply pi_next_pos).
  assert (HNp_norm : Id (sum_over_S Np) one) by (unfold Np; apply pi_next_normalized).
  (* J 分解 *)
  assert (HJt : Id (align_objective pi_t) Xt) by (unfold Xt; apply J_pi_t_t12; exact pi_t_norm).
  assert (HJn : Id (align_objective Np) (minus Xn (mult beta K1)))
    by (unfold Xn, K1; apply J_pi_next_t12).
  assert (Hdiff : Id (minus (align_objective Np) (align_objective pi_t))
                     (minus (minus Xn (mult beta K1)) Xt)).
  { unfold minus. apply (id_cong2 plus HJn (id_cong opp HJt)). }
  (* surrogate 恒等式 *)
  assert (Hsur : Id (mult eta (minus Xn Xt)) (mult beta (plus K1 K2))).
  {
    unfold Np, A, Xn, Xt, K1, K2.
    apply (surrogate_diff_identity pi_t pi_t_pos pi_t_norm).
    intro s. unfold Np. apply pi_next_pos.
  }
  (* Xn - Xt == (1/eta)·(beta·(K1+K2)) *)
  assert (Hlc : Id (mult (inv_pos eta eta_pos) (mult eta (minus Xn Xt))) (minus Xn Xt)).
  {
    apply (id_trans (mult_assoc (inv_pos eta eta_pos) eta (minus Xn Xt))).
    apply (id_trans (id_cong (fun x => mult x (minus Xn Xt))
                             (id_trans (mult_comm (inv_pos eta eta_pos) eta) (inv_pos_correct eta eta_pos)))).
    apply (id_trans (mult_comm one (minus Xn Xt)) (mult_one (minus Xn Xt))).
  }
  assert (Hinv : Id (minus Xn Xt) (mult (inv_pos eta eta_pos) (mult beta (plus K1 K2)))).
  {
    apply (id_trans (id_sym Hlc)).
    apply (id_cong (fun x => mult (inv_pos eta eta_pos) x) Hsur).
  }
  (* 交换：minus (minus Xn B) Xt == minus (minus Xn Xt) B *)
  assert (Hswap : Id (minus (minus Xn (mult beta K1)) Xt) (minus (minus Xn Xt) (mult beta K1))).
  {
    unfold minus.
    apply (id_trans (id_sym (plus_assoc Xn (opp (mult beta K1)) (opp Xt)))).
    apply (id_trans (id_cong (fun x => plus Xn x)
                             (plus_comm (opp (mult beta K1)) (opp Xt)))).
    apply (plus_assoc Xn (opp Xt) (opp (mult beta K1))).
  }
  (* 内部代数：mult a (plus K1 K2) - K1 == mult (minus a one) K1 + mult a K2 *)
  assert (Hm1 : Id (mult one K1) K1)
    by (apply (id_trans (mult_comm one K1)); apply mult_one).
  assert (Hmm : Id (minus (mult (inv_pos eta eta_pos) K1) K1)
                   (mult (minus (inv_pos eta eta_pos) one) K1)).
  {
    apply (id_trans (id_cong (fun x => minus (mult (inv_pos eta eta_pos) K1) x) (id_sym Hm1))).
    apply (id_sym (mult_minus_distr_r_t12 (inv_pos eta eta_pos) one K1)).
  }
  assert (Hin : Id (minus (mult (inv_pos eta eta_pos) (plus K1 K2)) K1)
                   (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2))).
  {
    unfold minus.
    apply (id_trans (id_cong (fun x => plus x (opp K1)) (distrib (inv_pos eta eta_pos) K1 K2))).
    apply (id_trans (id_sym (plus_assoc (mult (inv_pos eta eta_pos) K1) (mult (inv_pos eta eta_pos) K2) (opp K1)))).
    apply (id_trans (id_cong (fun x => plus (mult (inv_pos eta eta_pos) K1) x)
                             (plus_comm (mult (inv_pos eta eta_pos) K2) (opp K1)))).
    apply (id_trans (plus_assoc (mult (inv_pos eta eta_pos) K1) (opp K1) (mult (inv_pos eta eta_pos) K2))).
    exact (id_trans (id_cong (fun x => plus x (mult (inv_pos eta eta_pos) K2)) Hmm) id_refl).
  }
  (* 整体 beta 形式 *)
  assert (Hbeta_form : Id (minus (mult (inv_pos eta eta_pos) (mult beta (plus K1 K2))) (mult beta K1))
                          (mult beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))).
  {
    apply (id_trans (id_cong (fun x => minus x (mult beta K1))
                             (id_trans (mult_assoc (inv_pos eta eta_pos) beta (plus K1 K2))
                                       (id_trans (id_cong (fun x => mult x (plus K1 K2)) (mult_comm (inv_pos eta eta_pos) beta))
                                                 (id_sym (mult_assoc beta (inv_pos eta eta_pos) (plus K1 K2))))))).
    apply (id_trans (id_sym (mult_minus_distr_l beta (mult (inv_pos eta eta_pos) (plus K1 K2)) K1))).
    apply (id_cong (fun x => mult beta x) Hin).
  }
  (* le 非负链 *)
  assert (Ha : le zero (minus (inv_pos eta eta_pos) one)).
  {
    assert (Hinv1 : Id (inv_pos one one_pos) one)
      by exact (id_trans (id_sym (id_trans (mult_comm one (inv_pos one one_pos)) (mult_one (inv_pos one one_pos))))
                         (inv_pos_correct one one_pos)).
    assert (Hinv_le : le (inv_pos one one_pos) (inv_pos eta eta_pos))
      by exact (inv_pos_le_compat eta one eta_pos one_pos eta_le_one).
    assert (Hle1 : le one (inv_pos eta eta_pos))
      by exact (le_id_l one (inv_pos one one_pos) (inv_pos eta eta_pos) (id_sym Hinv1) Hinv_le).
    exact (le_minus_nonneg one (inv_pos eta eta_pos) Hle1).
  }
  assert (Hb : le zero K1).
  {
    unfold K1.
    apply (gibbs_inequality Np pi_t HNp_norm HNp_pos pi_t_norm pi_t_pos).
  }
  assert (Hc : le zero K2).
  {
    unfold K2.
    apply (gibbs_inequality pi_t Np pi_t_norm pi_t_pos HNp_norm HNp_pos).
  }
  assert (Hd : le zero (mult (minus (inv_pos eta eta_pos) one) K1))
    by exact (le_mult_nonneg_t12 (minus (inv_pos eta eta_pos) one) K1 Ha Hb).
  assert (He : le zero (mult (inv_pos eta eta_pos) K2)).
  {
    apply (le_mult_nonneg_t12 (inv_pos eta eta_pos) K2).
    - apply (lt_le_iff zero (inv_pos eta eta_pos)). left. exact (inv_pos_pos eta eta_pos).
    - exact Hc.
  }
  assert (Hf : le zero (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2))).
  {
    assert (Hplus : le (plus zero zero)
                       (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))
      by exact (le_plus_compat zero (mult (minus (inv_pos eta eta_pos) one) K1) zero (mult (inv_pos eta eta_pos) K2) Hd He).
    exact (le_id_l zero (plus zero zero)
                    (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2))
                    (id_sym (plus_zero zero)) Hplus).
  }
  assert (Hg : le zero (mult beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))).
  {
    apply (le_mult_nonneg_t12 beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2))).
    - apply (lt_le_iff zero beta). left. exact beta_pos.
    - exact Hf.
  }
  (* 组装 *)
  assert (Hrep : Id (minus (minus Xn (mult beta K1)) Xt)
                    (mult beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))).
  {
    apply (id_trans Hswap).
    apply (id_trans (id_cong (fun x => minus x (mult beta K1)) Hinv)).
    exact Hbeta_form.
  }
  assert (Hstep : le zero (minus (minus Xn (mult beta K1)) Xt))
    by exact (le_id_r zero (mult beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))
                      (minus (minus Xn (mult beta K1)) Xt) (id_sym Hrep) Hg).
  apply le_nonneg_minus.
  exact (le_id_r zero (minus (minus Xn (mult beta K1)) Xt)
                 (minus (align_objective Np) (align_objective pi_t))
                 (id_sym Hdiff) Hstep).
Qed.
(* ============================================================ *)
(* T1.3：策略迭代向后 KL 显式递推（论文1 几何收敛的镜像下降核心） *)
(*   相对熵镜像下降（entropic mirror descent）的三点恒等式组装： *)
(*   KL(pi_star‖pi_{t+1}) == (1−ηβ)·KL(pi_star‖pi_t) − η·KL(pi_t‖pi_star)    *)
(*                        + KL(pi_t‖pi_{t+1})                     *)
(*   构件：F_t 分解（F_t_decomp_p）+ F_t 展开（F_t_simpl_p）+     *)
(*   surrogate 最优性（grad_cross_identity）+ rlhf_suboptimality_gap *)
(*   （κ := 1−ηβ 显式收缩因子；KL 双向项与步长 KL 显式保留）     *)
(* ============================================================ *)

(* F_t(p) == −η·Σp·A_t + β·KL(p‖pi_t)（F_t_simpl_t 对任意 p 的泛化） *)
Lemma F_t_simpl_p :
  forall (pi_t : S -> R) (p : S -> R),
    Id (free_energy (energy_t pi_t) beta p)
       (plus (opp (mult eta (sum_over_S (fun s => mult (p s) (advantage_aug pi_t s)))))
             (mult beta (relative_entropy p pi_t))).
Proof.
  intros pi_t p.
  unfold free_energy, energy_t, advantage_aug, relative_entropy.
  set (A := advantage_aug pi_t).
  set (S1p := sum_over_S (fun s => mult (p s) (log (pi_t s)))).
  set (X := opp (mult eta (sum_over_S (fun s => mult (p s) (A s))))).
  set (Sp := sum_over_S (fun s => mult (p s) (log (p s)))).
  assert (H1 : Id (sum_over_S (fun s => mult (p s) (opp (mult eta (A s)))))
                  (opp (mult eta (sum_over_S (fun s => mult (p s) (A s)))))).
  { exact (sum_ptimes_opp_scal_t12 p eta A). }
  assert (H2 : Id (sum_over_S (fun s => mult (p s) (mult beta (log (pi_t s)))))
                  (mult beta S1p)).
  {
    unfold S1p.
    apply (id_trans (sum_over_S_ext _ _
      (fun s => id_trans (mult_assoc (p s) beta (log (pi_t s)))
                         (id_trans (id_cong (fun x => mult x (log (pi_t s))) (mult_comm (p s) beta))
                                   (id_sym (mult_assoc beta (p s) (log (pi_t s)))))))).
    apply (sum_over_S_linear beta (fun s => mult (p s) (log (pi_t s)))).
  }
  assert (Hsum : Id (sum_over_S (fun s => mult (p s) (minus (opp (mult eta (A s))) (mult beta (log (pi_t s))))))
                    (minus (opp (mult eta (sum_over_S (fun s => mult (p s) (A s))))) (mult beta S1p))).
  {
    apply (id_trans (sum_over_S_ext _ _
      (fun s => mult_minus_distr_l (p s) (opp (mult eta (A s))) (mult beta (log (pi_t s)))))).
    apply (id_trans (sum_over_S_minus (fun s => mult (p s) (opp (mult eta (A s))))
                                      (fun s => mult (p s) (mult beta (log (pi_t s)))))).
    apply (id_cong2 minus H1 H2).
  }
  (* KL 桥：minus Sp S1p == Σ p·(minus (log p) (log pi_t)) *)
  assert (Hkl : Id (minus Sp S1p)
                   (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (pi_t s)))))).
  { unfold Sp, S1p.
    apply (id_trans (id_sym (sum_over_S_minus (fun s => mult (p s) (log (p s)))
                                              (fun s => mult (p s) (log (pi_t s)))))
           (sum_over_S_ext _ _
             (fun s => id_sym (mult_minus_distr_l (p s) (log (p s)) (log (pi_t s)))))). }
  (* β 提取桥：minus (mult beta Sp) (mult beta S1p) == mult beta (minus Sp S1p) *)
  assert (Hlin : Id (minus (mult beta Sp) (mult beta S1p))
                    (mult beta (minus Sp S1p))).
  { exact (id_sym (mult_minus_distr_l beta Sp S1p)). }
  (* 组装：Σ p·(minus ...) + β·Sp == X + β·(Σ p·(log p − log pi_t)) *)
  assert (Hmain : Id (plus (sum_over_S (fun s => mult (p s) (minus (opp (mult eta (A s))) (mult beta (log (pi_t s))))))
                           (mult beta Sp))
                     (plus X (mult beta (sum_over_S (fun s => mult (p s) (minus (log (p s)) (log (pi_t s)))))))).
  {
    rewrite Hsum.
    apply (id_trans (id_sym (plus_assoc X (opp (mult beta S1p)) (mult beta Sp)))
           (id_trans (id_cong (fun x => plus X x)
                              (plus_comm (opp (mult beta S1p)) (mult beta Sp)))
           (id_trans (id_cong (fun x => plus X x) Hlin)
                     (id_cong (fun x => plus X (mult beta x)) Hkl)))).
  }
  exact Hmain.
Qed.

(* F_t(p) == F_t(pi_next) + β·KL(p‖pi_next)（rel_free_energy_decomp 对任意归一化 p 的泛化） *)
Lemma F_t_decomp_p :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one) (p : S -> R),
  normalized p ->
  Id (free_energy (energy_t pi_t) beta p)
     (plus (free_energy (energy_t pi_t) beta (pi_next pi_t pi_t_pos))
           (mult beta (relative_entropy p (pi_next pi_t pi_t_pos)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm p Hp_norm.
  assert (Hext : forall s : S, Id (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos) s)
                                  (pi_next pi_t pi_t_pos s)).
  {
    intro s.
    unfold boltzmann_dist, pi_next.
    apply (id_cong (fun x => mult (inv_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)) x)).
    exact (boltzmann_factor_bridge pi_t pi_t_pos s).
  }
  pose proof (free_energy_kl_decomp (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos)
                                    (Z_rel_boltzmann_form pi_t pi_t_pos) p Hp_norm) as Hdec.
  apply (id_trans Hdec).
  apply (id_cong2 plus
         (free_energy_ext_t12 (energy_t pi_t) beta
                          (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos))
                          (pi_next pi_t pi_t_pos) Hext)
         (id_cong (fun x => mult beta x)
                  (sum_over_S_ext
                    (fun s => mult (p s) (minus (log (p s)) (log (boltzmann_dist (energy_t pi_t) beta beta_pos (Z_rel pi_t) (Z_rel_pos pi_t pi_t_pos) s))))
                    (fun s => mult (p s) (minus (log (p s)) (log (pi_next pi_t pi_t_pos s))))
                    (fun s => id_cong (fun y => mult (p s) (minus (log (p s)) y)) (id_cong log (Hext s)))))).
Qed.

(* Xn − Xt == Σ(pi_next − pi_t)·A_t（求和减法桥，surrogate 左侧换形） *)
Lemma sum_grad_cross :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
  Id (minus (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))
            (sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s))))
     (sum_over_S (fun s => mult (minus (pi_next pi_t pi_t_pos s) (pi_t s)) (advantage_aug pi_t s))).
Proof.
  intros pi_t pi_t_pos.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  apply (id_trans (id_sym (sum_over_S_minus (fun s => mult (Np s) (A s))
                                            (fun s => mult (pi_t s) (A s))))
         (sum_over_S_ext _ _
           (fun s => id_sym (mult_minus_distr_r (Np s) (pi_t s) (A s))))).
Qed.

(* 镜像步最优性（surrogate ÷ η）：Σ(pi_next − pi_t)·A_t == (β/η)·(KL(pi_next‖pi_t) + KL(pi_t‖pi_next)) *)
Lemma grad_cross_identity :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one)
         (pi_next_pos : forall s : S, lt zero (pi_next pi_t pi_t_pos s)),
  Id (sum_over_S (fun s => mult (minus (pi_next pi_t pi_t_pos s) (pi_t s)) (advantage_aug pi_t s)))
     (mult (mult (inv_pos eta eta_pos) beta)
           (plus (relative_entropy (pi_next pi_t pi_t_pos) pi_t)
                 (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm pi_next_pos.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  pose proof (surrogate_diff_identity pi_t pi_t_pos pi_t_norm pi_next_pos) as Hsur.
  (* Hsur : mult eta (minus Xn Xt) == mult beta (plus K1 K2) *)
  (* 目标：Σ(pi_next−pi_t)·A == mult (mult (inv_pos eta) beta) (plus K1 K2) *)
  assert (Hone : Id (mult (mult (inv_pos eta eta_pos) eta) (minus Xn Xt)) (mult one (minus Xn Xt))).
  { apply (id_cong (fun x => mult x (minus Xn Xt))
           (id_trans (mult_comm (inv_pos eta eta_pos) eta) (inv_pos_correct eta eta_pos))). }
  apply (id_trans (id_sym (sum_grad_cross pi_t pi_t_pos))
         (id_trans (id_sym (id_trans (mult_comm one (minus Xn Xt)) (mult_one (minus Xn Xt))))
         (id_trans (id_sym Hone)
         (id_trans (id_sym (mult_assoc (inv_pos eta eta_pos) eta (minus Xn Xt)))
         (id_trans (id_cong (fun x => mult (inv_pos eta eta_pos) x) Hsur)
                   (mult_assoc (inv_pos eta eta_pos) beta (plus K1 K2))))))).
Qed.

(* minus 对 plus 的分配：minus a (plus b c) == minus (minus a b) c *)
Lemma minus_sub_plus_t13 : forall a b c : R,
  Id (minus a (plus b c)) (minus (minus a b) c).
Proof.
  intros a b c.
  unfold minus.
  exact (id_trans (id_cong (fun x => plus a x) (opp_plus b c))
                  (plus_assoc a (opp b) (opp c))).
Qed.

(* minus 反对称：minus a b == opp (minus b a) *)
Lemma opp_minus_rev_t13 : forall a b : R,
  Id (minus a b) (opp (minus b a)).
Proof.
  intros a b.
  unfold minus.
  exact (id_sym (id_trans (opp_plus b (opp a))
                 (id_trans (id_cong (fun x => plus (opp b) x) (double_neg a))
                           (plus_comm (opp b) a)))).
Qed.

(* Xt − Xs == −β·KL(pi_t‖pi_star) − β·KL(pi_star‖pi_t)（对齐目标两展开 + 子优间隙） *)
Lemma sum_advance_gap :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
  Id (minus (sum_over_S (fun s => mult (pi_t s) (advantage_aug pi_t s)))
            (sum_over_S (fun s => mult (pi_star s) (advantage_aug pi_t s))))
     (plus (opp (mult beta (relative_entropy pi_t pi_star)))
           (opp (mult beta (relative_entropy pi_star pi_t)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  set (A := advantage_aug pi_t).
  set (Xs := sum_over_S (fun s => mult (pi_star s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  (* J(pi_star) == Xs − β·KL(pi_star‖pi_t)（align_objective_t12_decomp + F_t_simpl_p + eta_absorb） *)
  assert (Hstar : Id (align_objective pi_star)
                    (minus Xs (mult beta (relative_entropy pi_star pi_t)))).
  {
    unfold Xs.
    pose proof (align_objective_t12_decomp pi_t pi_star) as Ht12.
    pose proof (F_t_simpl_p pi_t pi_star) as HFp.
    assert (Hopp : Id (opp (plus (opp (mult eta (sum_over_S (fun s => mult (pi_star s) (A s)))))
                                 (mult beta (relative_entropy pi_star pi_t))))
                      (plus (mult eta (sum_over_S (fun s => mult (pi_star s) (A s))))
                            (opp (mult beta (relative_entropy pi_star pi_t))))).
    {
      apply (id_trans (opp_plus (opp (mult eta (sum_over_S (fun s => mult (pi_star s) (A s)))))
                                (mult beta (relative_entropy pi_star pi_t)))
             (id_cong (fun x => plus x (opp (mult beta (relative_entropy pi_star pi_t))))
                      (double_neg (mult eta (sum_over_S (fun s => mult (pi_star s) (A s))))))).
    }
    assert (Hmid : Id (plus (opp (free_energy (energy_t pi_t) beta pi_star))
                            (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s)))))
                      (plus (opp (plus (opp (mult eta (sum_over_S (fun s => mult (pi_star s) (A s)))))
                                       (mult beta (relative_entropy pi_star pi_t))))
                            (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s)))))).
    { apply (id_cong2 plus (id_cong opp HFp) id_refl). }
    assert (Hfinal : Id (plus (plus (mult eta (sum_over_S (fun s => mult (pi_star s) (A s))))
                                    (opp (mult beta (relative_entropy pi_star pi_t))))
                            (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s)))))
                      (plus (sum_over_S (fun s => mult (pi_star s) (A s)))
                            (opp (mult beta (relative_entropy pi_star pi_t))))).
    {
      apply (id_trans (id_sym (plus_assoc (mult eta (sum_over_S (fun s => mult (pi_star s) (A s))))
                                           (opp (mult beta (relative_entropy pi_star pi_t)))
                                           (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s))))))
             (id_trans (id_cong (fun x => plus (mult eta (sum_over_S (fun s => mult (pi_star s) (A s)))) x)
                                (plus_comm (opp (mult beta (relative_entropy pi_star pi_t)))
                                           (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s))))))
             (id_trans (plus_assoc (mult eta (sum_over_S (fun s => mult (pi_star s) (A s))))
                                   (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s))))
                                   (opp (mult beta (relative_entropy pi_star pi_t))))
                       (id_cong (fun x => plus x (opp (mult beta (relative_entropy pi_star pi_t))))
                                (eta_absorb_t12 (sum_over_S (fun s => mult (pi_star s) (A s)))))))).
    }
    apply (id_trans Ht12).
    apply (id_trans Hmid
           (id_trans (id_cong (fun x => plus x (mult (minus one eta) (sum_over_S (fun s => mult (pi_star s) (A s))))) Hopp)
                     Hfinal)).
  }
  (* 反解：Xs == J(pi_star) + β·KL(pi_star‖pi_t) *)
  assert (Hxs : Id Xs (plus (align_objective pi_star) (mult beta (relative_entropy pi_star pi_t)))).
  {
    apply (id_trans (id_sym (minus_plus_cancel_gap Xs (mult beta (relative_entropy pi_star pi_t))))
           (id_cong (fun x => plus x (mult beta (relative_entropy pi_star pi_t))) (id_sym Hstar))).
  }
  (* J(pi_t) == Xt（J_pi_t_t12） *)
  assert (Hxt : Id (align_objective pi_t) Xt)
    by (unfold Xt; exact (J_pi_t_t12 pi_t pi_t_norm)).
  (* gap == β·KL(pi_t‖pi_star) *)
  pose proof (rlhf_suboptimality_gap pi_t pi_t_norm pi_t_pos) as Hgap.
  (* 链：minus Xt Xs == minus (J(pi_t)) (J(pi_star) + βKLst) == minus (opp gap) (βKLst) == −βKLts − βKLst *)
  apply (id_trans (id_cong2 minus (id_sym Hxt) Hxs)
         (id_trans (minus_sub_plus_t13 (align_objective pi_t) (align_objective pi_star)
                                       (mult beta (relative_entropy pi_star pi_t)))
         (id_trans (id_cong (fun x => minus x (mult beta (relative_entropy pi_star pi_t)))
                            (opp_minus_rev_t13 (align_objective pi_t) (align_objective pi_star)))
         (id_trans (id_cong (fun x => minus (opp x) (mult beta (relative_entropy pi_star pi_t))) Hgap)
                   id_refl)))).
Qed.



(* minus 分配于 plus：minus (plus a b) (plus c d) == plus (minus a c) (minus b d) *)
Lemma minus_distr_t13 : forall a b c d : R,
  Id (minus (plus a b) (plus c d)) (plus (minus a c) (minus b d)).
Proof.
  intros a b c d.
  unfold minus.
  assert (Hmid : Id (plus b (plus (opp c) (opp d)))
                   (plus (opp c) (plus b (opp d)))).
  {
    apply (id_trans (plus_assoc b (opp c) (opp d))
           (id_trans (id_cong (fun x => plus x (opp d)) (plus_comm b (opp c)))
                     (id_sym (plus_assoc (opp c) b (opp d))))).
  }
  apply (id_trans (id_cong (fun x => plus (plus a b) x) (opp_plus c d))
         (id_trans (id_sym (plus_assoc a b (plus (opp c) (opp d))))
         (id_trans (id_cong (fun x => plus a x) Hmid)
                   (plus_assoc a (opp c) (plus b (opp d)))))).
Qed.

(* minus (opp (mult eta a)) (opp (mult eta b)) == mult eta (minus b a)（η 吸收） *)
Lemma minus_opp_opp_mult_t13 : forall (a b : R),
  Id (minus (opp (mult eta a)) (opp (mult eta b)))
     (mult eta (minus b a)).
Proof.
  intros a b.
  unfold minus.
  apply (id_trans (id_cong (fun x => plus (opp (mult eta a)) x) (double_neg (mult eta b)))
         (id_trans (plus_comm (opp (mult eta a)) (mult eta b))
         (id_trans (id_cong (fun x => plus (mult eta b) x) (id_sym (opp_mult_l eta a)))
                   (id_sym (distrib eta b (opp a)))))).
Qed.

(* 主定理辅助 1：Hexp——minus 展开到 mult 形式 *)
Lemma t13_hexp :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
  Id (minus (plus (opp (mult eta (sum_over_S (fun s => mult (pi_star s) (advantage_aug pi_t s)))))
                  (mult beta (relative_entropy pi_star pi_t)))
            (plus (opp (mult eta (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))))
                  (mult beta (relative_entropy (pi_next pi_t pi_t_pos) pi_t))))
     (plus (mult eta (minus (sum_over_S (fun s => mult (pi_next pi_t pi_t_pos s) (advantage_aug pi_t s)))
                            (sum_over_S (fun s => mult (pi_star s) (advantage_aug pi_t s)))))
           (mult beta (minus (relative_entropy pi_star pi_t)
                             (relative_entropy (pi_next pi_t pi_t_pos) pi_t)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xs := sum_over_S (fun s => mult (pi_star s) (A s))).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (Kst := relative_entropy pi_star pi_t).
  apply (id_trans (minus_distr_t13 (opp (mult eta Xs)) (mult beta Kst)
                                   (opp (mult eta Xn)) (mult beta K1))
         (id_cong2 plus
                   (minus_opp_opp_mult_t13 Xs Xn)
                   (id_sym (mult_minus_distr_l beta Kst K1)))).
Qed.

(* Xn − Xs == (Xn − Xt) + (Xt − Xs)（minus 拆） *)
Lemma minus_split_t13 : forall a b c : R,
  Id (minus a c) (plus (minus a b) (minus b c)).
Proof.
  intros a b c.
  unfold minus.
  apply (id_trans (id_sym (id_cong (fun x => plus x (opp c)) (plus_zero a)))
         (id_trans (id_sym (id_cong (fun x => plus (plus a x) (opp c))
                                    (id_trans (plus_comm (opp b) b) (plus_opp b))))
         (id_trans (id_sym (id_cong (fun x => plus x (opp c))
                                    (id_sym (plus_assoc a (opp b) b))))
                   (id_sym (plus_assoc (plus a (opp b)) b (opp c)))))).
Qed.

(* minus (plus a b) b == a（minus_plus_cancel_gap 的逆形态） *)
Lemma minus_plus_cancel_gap_rev_t13 : forall a b : R,
  Id (minus (plus a b) b) a.
Proof.
  intros a b.
  unfold minus.
  apply (id_trans (id_sym (plus_assoc a b (opp b)))
         (id_trans (id_cong (fun x => plus a x) (plus_opp b))
                   (plus_zero a))).
Qed.

(* 坍缩：a 与 −a 抵消，e − d 与 b 重组 *)
Lemma t13_collapse : forall a b c d e : R,
  Id (plus (plus (plus a b) (plus (opp c) (opp d))) (minus e a))
     (plus (minus e d) (plus (opp c) b)).
Proof.
  intros a b c d e.
  unfold minus.
  set (X := plus (plus a b) (plus (opp c) (opp d))).
  apply (id_trans (id_trans (plus_assoc X e (opp a))
                   (id_trans (id_cong (fun x => plus x (opp a)) (plus_comm X e))
                             (id_sym (plus_assoc e X (opp a)))))
         (id_trans (id_cong (fun x => plus e x) (plus_comm X (opp a)))
         (id_trans (id_cong (fun x => plus e x)
                            (plus_assoc (opp a) (plus a b) (plus (opp c) (opp d))))
         (id_trans (id_cong (fun x => plus e x)
                            (id_cong (fun x => plus x (plus (opp c) (opp d)))
                                     (plus_assoc (opp a) a b)))
         (id_trans (id_cong (fun x => plus e x)
                            (id_cong (fun x => plus (plus x b) (plus (opp c) (opp d)))
                                     (id_trans (plus_comm (opp a) a) (plus_opp a))))
         (id_trans (id_cong (fun x => plus e x)
                            (id_cong (fun x => plus x (plus (opp c) (opp d)))
                                     (id_trans (plus_comm zero b) (plus_zero b))))
         (id_trans (id_cong (fun x => plus e x)
                            (id_trans (plus_assoc b (opp c) (opp d))
                            (id_trans (plus_comm (plus b (opp c)) (opp d))
                                      (id_cong (fun x => plus (opp d) x) (plus_comm b (opp c))))))
                   (plus_assoc e (opp d) (plus (opp c) b))))))))).
Qed.

Theorem policy_iter_backward_kl_step_beta :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one)
         (pi_next_pos : forall s : S, lt zero (pi_next pi_t pi_t_pos s)),
  Id (mult beta (relative_entropy pi_star (pi_next pi_t pi_t_pos)))
     (plus (mult (minus one eta) (mult beta (relative_entropy pi_star pi_t)))
           (plus (opp (mult eta (mult beta (relative_entropy pi_t pi_star))))
                 (mult beta (relative_entropy pi_t (pi_next pi_t pi_t_pos))))).
Proof.
  intros pi_t pi_t_pos pi_t_norm pi_next_pos.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xs := sum_over_S (fun s => mult (pi_star s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  set (Kst := relative_entropy pi_star pi_t).
  set (Kts := relative_entropy pi_t pi_star).
  set (Ksn := relative_entropy pi_star Np).
  pose proof (F_t_decomp_p pi_t pi_t_pos pi_t_norm pi_star pi_star_normalized) as Hdec.
  pose proof (F_t_simpl_p pi_t pi_star) as HFp.
  pose proof (F_t_simpl_next_kl pi_t pi_t_pos) as HFn.
  assert (Hkl0 : Id (minus (free_energy (energy_t pi_t) beta pi_star)
                           (free_energy (energy_t pi_t) beta Np))
                    (mult beta Ksn)).
  {
    apply (id_trans (id_cong (fun x => minus x (free_energy (energy_t pi_t) beta Np)) Hdec)
           (id_trans (id_cong (fun x => minus x (free_energy (energy_t pi_t) beta Np))
                              (plus_comm (free_energy (energy_t pi_t) beta Np) (mult beta Ksn)))
                     (minus_plus_cancel_gap_rev_t13 (mult beta Ksn) (free_energy (energy_t pi_t) beta Np)))).
  }
  assert (Hkl1 : Id (minus (plus (opp (mult eta Xs)) (mult beta Kst))
                           (plus (opp (mult eta Xn)) (mult beta K1)))
                    (mult beta Ksn)).
  {
    apply (id_trans (id_cong (fun x => minus x (plus (opp (mult eta Xn)) (mult beta K1))) (id_sym HFp))
           (id_trans (id_cong (fun x => minus (free_energy (energy_t pi_t) beta pi_star) x) (id_sym HFn))
                     Hkl0)).
  }
  pose proof (t13_hexp pi_t pi_t_pos pi_t_norm) as Hhexp.
  assert (Hmain0 : Id (mult beta Ksn)
                      (plus (mult eta (minus Xn Xs)) (mult beta (minus Kst K1)))).
  { apply (id_trans (id_sym Hkl1) Hhexp). }
  assert (Heta1 : Id (mult eta (minus Xn Xt)) (mult beta (plus K1 K2))).
  {
    apply (id_trans (id_cong (fun x => mult eta x) (sum_grad_cross pi_t pi_t_pos))
           (id_trans (id_cong (fun x => mult eta x)
                              (grad_cross_identity pi_t pi_t_pos pi_t_norm pi_next_pos))
           (id_trans (mult_assoc eta (mult (inv_pos eta eta_pos) beta) (plus K1 K2))
           (id_trans (id_cong (fun x => mult x (plus K1 K2))
                              (mult_assoc eta (inv_pos eta eta_pos) beta))
           (id_trans (id_cong (fun x => mult x (plus K1 K2))
                              (id_cong (fun x => mult x beta) (inv_pos_correct eta eta_pos)))
                     (id_cong (fun x => mult x (plus K1 K2))
                              (id_trans (mult_comm one beta) (mult_one beta)))))))).
  }
  assert (Heta2 : Id (mult eta (minus Xt Xs))
                     (plus (opp (mult eta (mult beta Kts)))
                           (opp (mult eta (mult beta Kst))))).
  {
    apply (id_trans (id_cong (fun x => mult eta x) (sum_advance_gap pi_t pi_t_pos pi_t_norm))
           (id_trans (distrib eta (opp (mult beta Kts)) (opp (mult beta Kst)))
           (id_cong2 plus
                     (opp_mult_l eta (mult beta Kts))
                     (opp_mult_l eta (mult beta Kst))))).
  }
  assert (Hsplit : Id (minus Xn Xs) (plus (minus Xn Xt) (minus Xt Xs)))
    by (unfold Xn, Xt, Xs; apply (minus_split_t13 (sum_over_S (fun s => mult (Np s) (A s)))
                                                  (sum_over_S (fun s => mult (pi_t s) (A s)))
                                                  (sum_over_S (fun s => mult (pi_star s) (A s))))).
  assert (Heta3 : Id (mult eta (minus Xn Xs))
                     (plus (mult eta (minus Xn Xt)) (mult eta (minus Xt Xs)))).
  {
    apply (id_trans (id_cong (fun x => mult eta x) Hsplit)
           (distrib eta (minus Xn Xt) (minus Xt Xs))).
  }
  assert (Hmid : Id (mult beta Ksn)
                    (plus (plus (mult beta (plus K1 K2))
                                (plus (opp (mult eta (mult beta Kts)))
                                      (opp (mult eta (mult beta Kst)))))
                          (minus (mult beta Kst) (mult beta K1)))).
  {
    apply (id_trans Hmain0
           (id_trans (id_cong (fun x => plus x (mult beta (minus Kst K1))) Heta3)
           (id_trans (id_cong (fun x => plus (plus x (mult eta (minus Xt Xs))) (mult beta (minus Kst K1))) Heta1)
           (id_trans (id_cong (fun x => plus (plus (mult beta (plus K1 K2)) x) (mult beta (minus Kst K1))) Heta2)
                     (id_cong (fun x => plus (plus (mult beta (plus K1 K2)) (plus (opp (mult eta (mult beta Kts))) (opp (mult eta (mult beta Kst))))) x)
                              (mult_minus_distr_l beta Kst K1)))))).
  }
  assert (Hdistr : Id (mult beta (plus K1 K2)) (plus (mult beta K1) (mult beta K2)))
    by (apply (distrib beta K1 K2)).
  assert (Hone : Id (minus (mult beta Kst) (mult eta (mult beta Kst)))
                    (mult (minus one eta) (mult beta Kst))).
  {
    apply (id_trans (id_sym (id_cong (fun x => minus x (mult eta (mult beta Kst)))
                                    (mult_one (mult beta Kst))))
           (id_trans (id_sym (id_cong (fun x => minus x (mult eta (mult beta Kst)))
                                      (mult_comm one (mult beta Kst))))
                     (id_sym (mult_minus_distr_r one eta (mult beta Kst))))).
  }
  apply (id_trans Hmid
         (id_trans (id_cong (fun x => plus (plus x (plus (opp (mult eta (mult beta Kts))) (opp (mult eta (mult beta Kst)))))
                                          (minus (mult beta Kst) (mult beta K1))) Hdistr)
         (id_trans (t13_collapse (mult beta K1) (mult beta K2)
                                 (mult eta (mult beta Kts)) (mult eta (mult beta Kst)) (mult beta Kst))
                   (id_cong (fun x => plus x (plus (opp (mult eta (mult beta Kts))) (mult beta K2)))
                            Hone)))).
Qed.

(* 除 β 版：KL(pi_star‖pi_next) == (1−η)·KL(pi_star‖pi_t) − η·KL(pi_t‖pi_star) + KL(pi_t‖pi_next) *)
Theorem policy_iter_backward_kl_step :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one)
         (pi_next_pos : forall s : S, lt zero (pi_next pi_t pi_t_pos s)),
  Id (relative_entropy pi_star (pi_next pi_t pi_t_pos))
     (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
           (plus (opp (mult eta (relative_entropy pi_t pi_star)))
                 (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
Proof.
  intros pi_t pi_t_pos pi_t_norm pi_next_pos.
  pose proof (policy_iter_backward_kl_step_beta pi_t pi_t_pos pi_t_norm pi_next_pos) as Hbeta.
  assert (Hbsn : Id (mult (inv_pos beta beta_pos) (mult beta (relative_entropy pi_star (pi_next pi_t pi_t_pos))))
                    (relative_entropy pi_star (pi_next pi_t pi_t_pos))).
  {
    apply (id_trans (mult_assoc (inv_pos beta beta_pos) beta (relative_entropy pi_star (pi_next pi_t pi_t_pos)))).
    apply (id_trans (id_cong (fun x => mult x (relative_entropy pi_star (pi_next pi_t pi_t_pos)))
                             (mult_comm (inv_pos beta beta_pos) beta))).
    apply (id_trans (id_cong (fun x => mult x (relative_entropy pi_star (pi_next pi_t pi_t_pos)))
                             (inv_pos_correct beta beta_pos))).
    apply (id_trans (mult_comm one (relative_entropy pi_star (pi_next pi_t pi_t_pos)))
                    (mult_one (relative_entropy pi_star (pi_next pi_t pi_t_pos)))).
  }
  assert (Hb1 : Id (mult (inv_pos beta beta_pos)
                         (mult (minus one eta) (mult beta (relative_entropy pi_star pi_t))))
                   (mult (minus one eta) (relative_entropy pi_star pi_t))).
  {
    apply (id_trans (mult_assoc (inv_pos beta beta_pos) (minus one eta) (mult beta (relative_entropy pi_star pi_t)))).
    apply (id_trans (id_cong (fun x => mult x (mult beta (relative_entropy pi_star pi_t)))
                             (mult_comm (inv_pos beta beta_pos) (minus one eta)))).
    apply (id_trans (id_sym (mult_assoc (minus one eta) (inv_pos beta beta_pos) (mult beta (relative_entropy pi_star pi_t))))).
    apply (id_trans (id_cong (fun x => mult (minus one eta) x)
                             (mult_assoc (inv_pos beta beta_pos) beta (relative_entropy pi_star pi_t)))).
    apply (id_trans (id_cong (fun x => mult (minus one eta) x)
                             (id_cong (fun x => mult x (relative_entropy pi_star pi_t))
                                      (mult_comm (inv_pos beta beta_pos) beta)))).
    apply (id_trans (id_cong (fun x => mult (minus one eta) x)
                             (id_cong (fun x => mult x (relative_entropy pi_star pi_t))
                                      (inv_pos_correct beta beta_pos)))).
    apply (id_cong (fun x => mult (minus one eta) x)
                   (id_trans (mult_comm one (relative_entropy pi_star pi_t))
                             (mult_one (relative_entropy pi_star pi_t)))).
  }
  assert (Hb2 : Id (mult (inv_pos beta beta_pos)
                         (opp (mult eta (mult beta (relative_entropy pi_t pi_star)))))
                   (opp (mult eta (relative_entropy pi_t pi_star)))).
  {
    apply (id_trans (opp_mult_l (inv_pos beta beta_pos) (mult eta (mult beta (relative_entropy pi_t pi_star))))).
    apply (id_trans (id_cong opp
                             (mult_assoc (inv_pos beta beta_pos) eta (mult beta (relative_entropy pi_t pi_star))))).
    apply (id_trans (id_cong opp
                             (id_cong (fun x => mult x (mult beta (relative_entropy pi_t pi_star)))
                                      (mult_comm (inv_pos beta beta_pos) eta)))).
    apply (id_trans (id_cong opp
                             (id_sym (mult_assoc eta (inv_pos beta beta_pos) (mult beta (relative_entropy pi_t pi_star)))))).
    apply (id_trans (id_cong opp
                             (id_cong (fun x => mult eta x)
                                      (mult_assoc (inv_pos beta beta_pos) beta (relative_entropy pi_t pi_star))))).
    apply (id_trans (id_cong opp
                             (id_cong (fun x => mult eta x)
                                      (id_cong (fun x => mult x (relative_entropy pi_t pi_star))
                                               (mult_comm (inv_pos beta beta_pos) beta))))).
    apply (id_trans (id_cong opp
                             (id_cong (fun x => mult eta x)
                                      (id_cong (fun x => mult x (relative_entropy pi_t pi_star))
                                               (inv_pos_correct beta beta_pos))))).
    apply (id_cong opp
                   (id_cong (fun x => mult eta x)
                            (id_trans (mult_comm one (relative_entropy pi_t pi_star))
                                      (mult_one (relative_entropy pi_t pi_star))))).
  }
  assert (Hb3 : Id (mult (inv_pos beta beta_pos) (mult beta (relative_entropy pi_t (pi_next pi_t pi_t_pos))))
                   (relative_entropy pi_t (pi_next pi_t pi_t_pos))).
  {
    apply (id_trans (mult_assoc (inv_pos beta beta_pos) beta (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
    apply (id_trans (id_cong (fun x => mult x (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                             (mult_comm (inv_pos beta beta_pos) beta))).
    apply (id_trans (id_cong (fun x => mult x (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                             (inv_pos_correct beta beta_pos))).
    apply (id_trans (mult_comm one (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                    (mult_one (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
  }
  apply (id_trans (id_sym Hbsn)).
  apply (id_trans (id_cong (fun x => mult (inv_pos beta beta_pos) x) Hbeta)).
  apply (id_trans (distrib (inv_pos beta beta_pos)
                           (mult (minus one eta) (mult beta (relative_entropy pi_star pi_t)))
                           (plus (opp (mult eta (mult beta (relative_entropy pi_t pi_star))))
                                 (mult beta (relative_entropy pi_t (pi_next pi_t pi_t_pos)))))).
  apply (id_trans (id_cong (fun x => plus (mult (inv_pos beta beta_pos) (mult (minus one eta) (mult beta (relative_entropy pi_star pi_t)))) x)
                           (distrib (inv_pos beta beta_pos)
                                    (opp (mult eta (mult beta (relative_entropy pi_t pi_star))))
                                    (mult beta (relative_entropy pi_t (pi_next pi_t pi_t_pos)))))).
  apply (id_cong2 plus Hb1 (id_cong2 plus Hb2 Hb3)).
Qed.

(* le 版：KL(pi_star‖pi_next) ≤ (1−η)·KL(pi_star‖pi_t) + KL(pi_t‖pi_next)（丢弃 −η·KL(pi_t‖pi_star) ≤ 0） *)
(* 辅助：opp zero == zero（Section 内自证；set_opp_zero 定义在 Section 之后，不能向前引用） *)
Lemma opp_zero_t13 : Id (opp zero) zero.
Proof.
  apply id_sym.
  apply (plus_inv_unique zero zero (opp zero)).
  - apply (plus_zero zero).
  - apply (plus_opp zero).
Qed.

Theorem policy_iter_backward_kl_step_le :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one)
         (pi_next_pos : forall s : S, lt zero (pi_next pi_t pi_t_pos s)),
  le (relative_entropy pi_star (pi_next pi_t pi_t_pos))
     (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
           (relative_entropy pi_t (pi_next pi_t pi_t_pos))).
Proof.
  intros pi_t pi_t_pos pi_t_norm pi_next_pos.
  pose proof (policy_iter_backward_kl_step pi_t pi_t_pos pi_t_norm pi_next_pos) as Hstep.
  assert (Hkl : le zero (relative_entropy pi_t pi_star)).
  {
    apply (gibbs_inequality pi_t pi_star pi_t_norm pi_t_pos pi_star_normalized pi_star_pos).
  }
  assert (HleM : le zero (mult eta (relative_entropy pi_t pi_star))).
  {
    apply (le_id_l zero (mult zero eta) (mult eta (relative_entropy pi_t pi_star))).
    - apply (id_sym (id_trans (mult_comm zero eta) (mult_zero eta))).
    - apply (le_trans (mult zero eta) (mult (relative_entropy pi_t pi_star) eta)
                      (mult eta (relative_entropy pi_t pi_star))).
      + apply (le_mult_compat zero (relative_entropy pi_t pi_star) eta).
        * exact eta_pos.
        * exact Hkl.
      + apply (le_id_l (mult (relative_entropy pi_t pi_star) eta)
                       (mult eta (relative_entropy pi_t pi_star))
                       (mult eta (relative_entropy pi_t pi_star))
                       (mult_comm (relative_entropy pi_t pi_star) eta)
                       (le_refl (mult eta (relative_entropy pi_t pi_star)))).
  }
  assert (Hopp : le (opp (mult eta (relative_entropy pi_t pi_star))) zero).
  {
    apply (le_id_r (opp (mult eta (relative_entropy pi_t pi_star))) (opp zero) zero).
    - apply opp_zero_t13.
    - apply (opp_le_compat zero (mult eta (relative_entropy pi_t pi_star))).
      exact HleM.
  }
  apply (le_id_l (relative_entropy pi_star (pi_next pi_t pi_t_pos))
                 (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                       (plus (opp (mult eta (relative_entropy pi_t pi_star)))
                             (relative_entropy pi_t (pi_next pi_t pi_t_pos))))
                 (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                       (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
  - exact Hstep.
  - apply (le_id_r (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                         (plus (opp (mult eta (relative_entropy pi_t pi_star)))
                               (relative_entropy pi_t (pi_next pi_t pi_t_pos))))
                   (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                         (plus zero (relative_entropy pi_t (pi_next pi_t pi_t_pos))))
                   (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                         (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
    + apply (id_cong (fun x => plus (mult (minus one eta) (relative_entropy pi_star pi_t)) x)
                     (id_trans (plus_comm zero (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                               (plus_zero (relative_entropy pi_t (pi_next pi_t pi_t_pos))))).
    + apply (le_plus_compat (mult (minus one eta) (relative_entropy pi_star pi_t))
                            (mult (minus one eta) (relative_entropy pi_star pi_t))
                            (plus (opp (mult eta (relative_entropy pi_t pi_star)))
                                  (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                            (plus zero (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                            (le_refl (mult (minus one eta) (relative_entropy pi_star pi_t)))
                            (le_plus_compat (opp (mult eta (relative_entropy pi_t pi_star))) zero
                                            (relative_entropy pi_t (pi_next pi_t pi_t_pos))
                                            (relative_entropy pi_t (pi_next pi_t pi_t_pos))
                                            Hopp (le_refl (relative_entropy pi_t (pi_next pi_t pi_t_pos))))).
Qed.

(* ============================================================ *)
(* A-1：T1.3 几何收敛上界（镜像下降迭代的显式递推）           *)
(*   pi_{t+1} := pi_next pi_t（相对熵镜像下降单步）              *)
(*   1) policy_iterate：sigT 打包的迭代 Fixpoint（正性内嵌）     *)
(*   2) policy_iter_norm：迭代保持归一化                          *)
(*   3) step_kl_weighted：加权步长 KL 和（κ^{t-1-i} 权重）        *)
(*   4) policy_iter_backward_kl_iter_le：                        *)
(*      KL(pi*‖pi_t) ≤ κ^t·KL(pi*‖pi_0) + Σ_{i<t} κ^{t-1-i}·KL(pi_i‖pi_{i+1}) *)
(*      （κ := 1−η；归纳组装 policy_iter_backward_kl_step_le）   *)
(*   5) policy_iter_gap_diff：gap 单步显式恒等式                 *)
(*      J(pi_{t+1}) − J(pi_t) == β·[(1/η−1)·KL(pi_{t+1}‖pi_t)   *)
(*                                  + (1/η)·KL(pi_t‖pi_{t+1})]   *)
(*      （提取 policy_improvement_mono 的 Hbeta_form 链为独立定理）*)
(*   6) policy_iter_gap_mono：gap 单调不增（gap_{t+1} ≤ gap_t）  *)
(*   7) step_kl_eta_bound（R2.1 升级接口：前向步长 KL 被控为      *)
(*      ≤ η × 前向 KL 到最优（≡ 插值不等式 log Z ≤ 0，Real 层    *)
(*      Hölder 可证）；旧 step_kl_ratio_bound 对任意常数 c 非定理  *)
(*      已退役）+ policy_iter_kl_geom_step：单步真几何收缩 c := 0 *)
(*      KL(pi*‖pi_{t+1}) ≤ (1−η)·KL(pi*‖pi_t)                    *)
(*   8) policy_iter_kl_geom_iter：迭代几何上界（T1.3 核心交付）  *)
(*      KL(pi*‖pi_t) ≤ (1−η)^t·KL(pi*‖pi_0)                     *)
(* ============================================================ *)

(* 迭代 Fixpoint：分布 + 正性证明打包为 sigT（可提取） *)
Fixpoint policy_iterate (t : nat) (pi : S -> R)
         (pi_pos : forall s : S, lt zero (pi s)) :
  { pi' : S -> R & forall s : S, lt zero (pi' s) } :=
  match t with
  | 0%nat => existT _ pi pi_pos
  | Datatypes.S m =>
      let p := policy_iterate m pi pi_pos in
      existT _ (pi_next (projT1 p) (projT2 p)) (pi_next_pos (projT1 p) (projT2 p))
  end.

(* 迭代保持归一化 *)
Lemma policy_iter_norm : forall (t : nat) (pi : S -> R)
       (pi_pos : forall s : S, lt zero (pi s)),
  Id (sum_over_S pi) one ->
  Id (sum_over_S (projT1 (policy_iterate t pi pi_pos))) one.
Proof.
  intros t pi pi_pos Hnorm.
  induction t as [| m IH]; simpl.
  - exact Hnorm.
  - apply pi_next_normalized.
Qed.

(* 加权步长 KL 和：S(t) := Σ_{i<t} κ^{t-1-i}·KL(pi_i‖pi_{i+1})，κ := 1−η *)
(* 递推：S(S m) == KL(pi_m‖pi_{S m}) + κ·S(m) *)
Fixpoint step_kl_weighted (t : nat) (pi : S -> R)
         (pi_pos : forall s : S, lt zero (pi s)) : R :=
  match t with
  | 0%nat => zero
  | Datatypes.S m =>
      let p := policy_iterate m pi pi_pos in
      plus (relative_entropy (projT1 p) (pi_next (projT1 p) (projT2 p)))
           (mult (minus one eta) (step_kl_weighted m pi pi_pos))
  end.

(* 向后 KL 迭代递推（精确加权上界）：
   KL(pi*‖pi_t) ≤ κ^t·KL(pi*‖pi_0) + Σ_{i<t} κ^{t-1-i}·KL(pi_i‖pi_{i+1}) *)
Theorem policy_iter_backward_kl_iter_le :
  forall (t : nat) (pi : S -> R) (pi_pos : forall s : S, lt zero (pi s)),
    Id (sum_over_S pi) one ->
    le (relative_entropy pi_star (projT1 (policy_iterate t pi pi_pos)))
       (plus (mult (r_pow (minus one eta) t) (relative_entropy pi_star pi))
             (step_kl_weighted t pi pi_pos)).
Proof.
  intros t pi pi_pos Hnorm.
  induction t as [| m IH]; simpl.
  - (* t = 0：KL ≤ 1·KL + 0 *)
    apply (le_id_r (relative_entropy pi_star pi)
                   (plus (relative_entropy pi_star pi) zero)
                   (plus (mult one (relative_entropy pi_star pi)) zero)).
    + apply (id_sym (id_cong2 plus (id_trans (mult_comm one (relative_entropy pi_star pi))
                                             (mult_one (relative_entropy pi_star pi)))
                                  id_refl)).
    + apply (le_id_r (relative_entropy pi_star pi)
                     (relative_entropy pi_star pi)
                     (plus (relative_entropy pi_star pi) zero)).
      * apply (id_sym (plus_zero (relative_entropy pi_star pi))).
      * apply le_refl.
  - (* t = S m：KL(pi*‖pi_{S m}) ≤ (1−η)·KL(pi*‖pi_m) + KL(pi_m‖pi_{S m})
               ≤ (1−η)·(κ^m·KL0 + S_m) + KL_m
               == κ^{S m}·KL0 + (KL_m + (1−η)·S_m) *)
    set (K := minus one eta).
    set (Pm := projT1 (policy_iterate m pi pi_pos)).
    set (Pm_pos := projT2 (policy_iterate m pi pi_pos)).
    set (KL0 := relative_entropy pi_star pi).
    set (KSm := relative_entropy Pm (pi_next Pm Pm_pos)).
    set (Sm := step_kl_weighted m pi pi_pos).
    (* 单步向后 KL 递推 *)
    assert (H1 : le (relative_entropy pi_star (pi_next Pm Pm_pos))
                    (plus (mult K (relative_entropy pi_star Pm)) KSm)).
    { unfold K, KSm. exact (policy_iter_backward_kl_step_le Pm Pm_pos
                              (policy_iter_norm m pi pi_pos Hnorm) (pi_next_pos Pm Pm_pos)). }
    (* κ 非负：η ≤ 1 ⟹ 0 ≤ 1−η *)
    assert (Hk : le zero K).
    { unfold K. exact (le_minus_nonneg eta one eta_le_one). }
    (* 归纳前提乘 κ（le_mult_compat_weak + 交换换形） *)
    assert (H4 : le (mult K (relative_entropy pi_star Pm))
                    (mult K (plus (mult (r_pow K m) KL0) Sm))).
    {
      apply (le_id_l (mult K (relative_entropy pi_star Pm))
                     (mult (relative_entropy pi_star Pm) K)
                     (mult K (plus (mult (r_pow K m) KL0) Sm))).
      - apply mult_comm.
      - apply (le_id_r _ (mult (plus (mult (r_pow K m) KL0) Sm) K) _).
        + apply mult_comm.
        + apply (le_mult_compat_weak (relative_entropy pi_star Pm)
                                     (plus (mult (r_pow K m) KL0) Sm) K Hk).
          exact IH.
    }
    (* 加 KSm：le_plus_compat *)
    assert (H5 : le (plus (mult K (relative_entropy pi_star Pm)) KSm)
                    (plus (mult K (plus (mult (r_pow K m) KL0) Sm)) KSm)).
    { apply (le_plus_compat (mult K (relative_entropy pi_star Pm))
                            (mult K (plus (mult (r_pow K m) KL0) Sm))
                            KSm KSm H4 (le_refl KSm)). }
    (* 传递 *)
    assert (H6 : le (relative_entropy pi_star (pi_next Pm Pm_pos))
                    (plus (mult K (plus (mult (r_pow K m) KL0) Sm)) KSm)).
    { apply (le_trans _ (plus (mult K (relative_entropy pi_star Pm)) KSm) _).
      - exact H1.
      - exact H5. }
    (* 代数换形：mult K (plus A Sm) + KSm == κ^{S m}·KL0 + (KSm + κ·Sm) *)
    assert (Hid : Id (plus (mult K (plus (mult (r_pow K m) KL0) Sm)) KSm)
                     (plus (mult (mult K (r_pow K m)) KL0) (plus KSm (mult K Sm)))).
    {
      apply (id_trans (id_cong2 plus (distrib K (mult (r_pow K m) KL0) Sm) id_refl)).
      apply (id_trans (id_sym (plus_assoc (mult K (mult (r_pow K m) KL0)) (mult K Sm) KSm))).
      apply (id_trans (id_cong (fun x => plus (mult K (mult (r_pow K m) KL0)) x)
                               (plus_comm (mult K Sm) KSm))).
      apply (id_cong (fun x => plus x (plus KSm (mult K Sm)))
                     (mult_assoc K (r_pow K m) KL0)).
    }
    (* 目标换形后闭 *)
    apply (le_id_r (relative_entropy pi_star (pi_next Pm Pm_pos))
                   (plus (mult K (plus (mult (r_pow K m) KL0) Sm)) KSm)
                   (plus (mult (mult K (r_pow K m)) KL0) (plus KSm (mult K Sm)))).
    + exact Hid.
    + exact H6.
Qed.

(* gap 单步显式恒等式：
   J(pi_{t+1}) − J(pi_t) == β·[(1/η−1)·KL(pi_{t+1}‖pi_t) + (1/η)·KL(pi_t‖pi_{t+1})] *)
Lemma policy_iter_gap_diff :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    Id (minus (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t))
       (mult beta (plus (mult (minus (inv_pos eta eta_pos) one)
                              (relative_entropy (pi_next pi_t pi_t_pos) pi_t))
                        (mult (inv_pos eta eta_pos)
                              (relative_entropy pi_t (pi_next pi_t pi_t_pos))))).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  set (Np := pi_next pi_t pi_t_pos).
  set (A := advantage_aug pi_t).
  set (Xn := sum_over_S (fun s => mult (Np s) (A s))).
  set (Xt := sum_over_S (fun s => mult (pi_t s) (A s))).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  assert (HNp_pos : forall s : S, lt zero (Np s)) by (intro s; unfold Np; apply pi_next_pos).
  assert (HNp_norm : Id (sum_over_S Np) one) by (unfold Np; apply pi_next_normalized).
  assert (HJt : Id (align_objective pi_t) Xt) by (unfold Xt; apply J_pi_t_t12; exact pi_t_norm).
  assert (HJn : Id (align_objective Np) (minus Xn (mult beta K1)))
    by (unfold Xn, K1; apply J_pi_next_t12).
  assert (Hdiff : Id (minus (align_objective Np) (align_objective pi_t))
                     (minus (minus Xn (mult beta K1)) Xt)).
  { unfold minus. apply (id_cong2 plus HJn (id_cong opp HJt)). }
  assert (Hsur : Id (mult eta (minus Xn Xt)) (mult beta (plus K1 K2))).
  {
    unfold Np, A, Xn, Xt, K1, K2.
    apply (surrogate_diff_identity pi_t pi_t_pos pi_t_norm).
    intro s. unfold Np. apply pi_next_pos.
  }
  assert (Hlc : Id (mult (inv_pos eta eta_pos) (mult eta (minus Xn Xt))) (minus Xn Xt)).
  {
    apply (id_trans (mult_assoc (inv_pos eta eta_pos) eta (minus Xn Xt))).
    apply (id_trans (id_cong (fun x => mult x (minus Xn Xt))
                             (id_trans (mult_comm (inv_pos eta eta_pos) eta) (inv_pos_correct eta eta_pos)))).
    apply (id_trans (mult_comm one (minus Xn Xt)) (mult_one (minus Xn Xt))).
  }
  assert (Hinv : Id (minus Xn Xt) (mult (inv_pos eta eta_pos) (mult beta (plus K1 K2)))).
  {
    apply (id_trans (id_sym Hlc)).
    apply (id_cong (fun x => mult (inv_pos eta eta_pos) x) Hsur).
  }
  assert (Hswap : Id (minus (minus Xn (mult beta K1)) Xt) (minus (minus Xn Xt) (mult beta K1))).
  {
    unfold minus.
    apply (id_trans (id_sym (plus_assoc Xn (opp (mult beta K1)) (opp Xt)))).
    apply (id_trans (id_cong (fun x => plus Xn x)
                             (plus_comm (opp (mult beta K1)) (opp Xt)))).
    apply (plus_assoc Xn (opp Xt) (opp (mult beta K1))).
  }
  assert (Hm1 : Id (mult one K1) K1)
    by (apply (id_trans (mult_comm one K1)); apply mult_one).
  assert (Hmm : Id (minus (mult (inv_pos eta eta_pos) K1) K1)
                   (mult (minus (inv_pos eta eta_pos) one) K1)).
  {
    apply (id_trans (id_cong (fun x => minus (mult (inv_pos eta eta_pos) K1) x) (id_sym Hm1))).
    apply (id_sym (mult_minus_distr_r_t12 (inv_pos eta eta_pos) one K1)).
  }
  assert (Hin : Id (minus (mult (inv_pos eta eta_pos) (plus K1 K2)) K1)
                   (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2))).
  {
    unfold minus.
    apply (id_trans (id_cong (fun x => plus x (opp K1)) (distrib (inv_pos eta eta_pos) K1 K2))).
    apply (id_trans (id_sym (plus_assoc (mult (inv_pos eta eta_pos) K1) (mult (inv_pos eta eta_pos) K2) (opp K1)))).
    apply (id_trans (id_cong (fun x => plus (mult (inv_pos eta eta_pos) K1) x)
                             (plus_comm (mult (inv_pos eta eta_pos) K2) (opp K1)))).
    apply (id_trans (plus_assoc (mult (inv_pos eta eta_pos) K1) (opp K1) (mult (inv_pos eta eta_pos) K2))).
    exact (id_trans (id_cong (fun x => plus x (mult (inv_pos eta eta_pos) K2)) Hmm) id_refl).
  }
  assert (Hbeta_form : Id (minus (mult (inv_pos eta eta_pos) (mult beta (plus K1 K2))) (mult beta K1))
                          (mult beta (plus (mult (minus (inv_pos eta eta_pos) one) K1) (mult (inv_pos eta eta_pos) K2)))).
  {
    apply (id_trans (id_cong (fun x => minus x (mult beta K1))
                             (id_trans (mult_assoc (inv_pos eta eta_pos) beta (plus K1 K2))
                                       (id_trans (id_cong (fun x => mult x (plus K1 K2)) (mult_comm (inv_pos eta eta_pos) beta))
                                                 (id_sym (mult_assoc beta (inv_pos eta eta_pos) (plus K1 K2))))))).
    apply (id_trans (id_sym (mult_minus_distr_l beta (mult (inv_pos eta eta_pos) (plus K1 K2)) K1))).
    apply (id_cong (fun x => mult beta x) Hin).
  }
  apply (id_trans Hdiff).
  apply (id_trans Hswap).
  apply (id_trans (id_cong (fun x => minus x (mult beta K1)) Hinv)).
  exact Hbeta_form.
Qed.

(* gap 单调不增：gap_{t+1} := J* − J_{t+1} ≤ J* − J_t =: gap_t *)
Lemma policy_iter_gap_mono :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    le (minus (align_objective pi_star) (align_objective (pi_next pi_t pi_t_pos)))
       (minus (align_objective pi_star) (align_objective pi_t)).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  unfold minus.
  apply (le_plus_compat (align_objective pi_star) (align_objective pi_star)
                         (opp (align_objective (pi_next pi_t pi_t_pos)))
                         (opp (align_objective pi_t))
                         (le_refl (align_objective pi_star))
                         (opp_le_compat (align_objective pi_t) (align_objective (pi_next pi_t pi_t_pos))
                                        (policy_improvement_mono pi_t pi_t_pos pi_t_norm))).
Qed.

(* ============================================================
   诚实接口升级（R2.1 / 审稿 M4，sR21 判定 2026-09-03）：
   旧 step_kl_ratio_bound（前向 KL ≤ c·向后 KL）对任意常数 c
   非定理——两方向 KL 在单纯形上不可比（前向 KL 可无界
   而 KL(pi*‖pi_t) 有界，比值无界）。数学正确的几何插值收缩
   前提为 step_kl_eta_bound：
     KL(pi_t‖pi_next pi_t) ≤ η · KL(pi_t‖pi_star)
   （≡ 插值不等式 log Z ≤ 0，Z := Σ pi_t^{1−η}·pi*^η；Real 层
   Hölder/exp 凸可证，方向为真）。在此单一诚实前提下，用精确
   恒等 policy_iter_backward_kl_step（L22574）纯代数推出真几何
   收缩 κ := 1−η（c := 0），比旧 (1−η+c) 更紧。
   ============================================================ *)
Variable step_kl_eta_bound : forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s)),
  le (relative_entropy pi_t (pi_next pi_t pi_t_pos))
     (mult eta (relative_entropy pi_t pi_star)).

(* 纯序代数辅助：C ≤ B ⟹ −B + C ≤ 0 *)
Lemma plus_opp_le_zero : forall (B C : R), le C B -> le (plus (opp B) C) zero.
Proof.
  intros B C HCB.
  assert (H1 : le (plus (opp B) C) (plus (opp B) B))
    by (apply (le_plus_compat (opp B) (opp B) C B (le_refl (opp B)) HCB)).
  exact (le_id_r (plus (opp B) C) (plus (opp B) B) zero
                 (id_trans (plus_comm (opp B) B) (plus_opp B))
                 H1).
Qed.

(* plus A (plus (opp B) C) ≤ A  whenever  C ≤ B *)
Lemma plusA_opp_cancel_le : forall (A B C : R), le C B -> le (plus A (plus (opp B) C)) A.
Proof.
  intros A B C HCB.
  pose proof (plus_opp_le_zero B C HCB) as Hz.
  assert (Hadd : le (plus A (plus (opp B) C)) (plus A zero))
    by (apply (le_plus_compat A A (plus (opp B) C) zero (le_refl A) Hz)).
  exact (le_id_r (plus A (plus (opp B) C)) (plus A zero) A (plus_zero A) Hadd).
Qed.

(* ============================================================
   单步几何收缩（真几何率 c := 0，R2.1 升级）：
     KL(pi*‖pi_{t+1}) ≤ (1−η)·KL(pi*‖pi_t)
   路线：精确恒等 KL(pi*‖pi_next) == (1−η)·KL(pi*‖pi_t)
           − η·(前向 KL) + KL(pi_t‖pi_next)
         + step_kl_eta_bound 抵消两个 η 项。
   ============================================================ *)
Theorem policy_iter_kl_geom_step :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    le (relative_entropy pi_star (pi_next pi_t pi_t_pos))
       (mult (minus one eta) (relative_entropy pi_star pi_t)).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  set (KLst := relative_entropy pi_star pi_t).
  set (KLsn := relative_entropy pi_star (pi_next pi_t pi_t_pos)).
  set (KLts := relative_entropy pi_t pi_star).
  set (KLtn := relative_entropy pi_t (pi_next pi_t pi_t_pos)).
  (* 精确三 KL 恒等 *)
  assert (H : Id KLsn (plus (mult (minus one eta) KLst)
                            (plus (opp (mult eta KLts)) KLtn))).
  {
    unfold KLsn, KLst, KLts, KLtn.
    apply (policy_iter_backward_kl_step pi_t pi_t_pos pi_t_norm).
    intro s. apply (pi_next_pos pi_t pi_t_pos s).
  }
  (* 假设：KLtn ≤ η·KLts *)
  assert (Hb : le KLtn (mult eta KLts)).
  { unfold KLtn, KLts. exact (step_kl_eta_bound pi_t pi_t_pos). }
  (* RHS ≤ (1−η)·KLst *)
  apply (le_id_l KLsn (plus (mult (minus one eta) KLst)
                            (plus (opp (mult eta KLts)) KLtn))
                    (mult (minus one eta) KLst)).
  - exact H.
  - apply (plusA_opp_cancel_le (mult (minus one eta) KLst) (mult eta KLts) KLtn).
    exact Hb.
Qed.

(* ============================================================
   迭代几何上界（真几何率 (1−η)^t，T1.3 R2.1 升级）：
     KL(pi*‖pi_t) ≤ (1−η)^t·KL(pi*‖pi_0)
   ============================================================ *)
Theorem policy_iter_kl_geom_iter :
  forall (t : nat) (pi : S -> R) (pi_pos : forall s : S, lt zero (pi s))
         (pi_norm : Id (sum_over_S pi) one),
    le (relative_entropy pi_star (projT1 (policy_iterate t pi pi_pos)))
       (mult (r_pow (minus one eta) t) (relative_entropy pi_star pi)).
Proof.
  intros t pi pi_pos pi_norm.
  induction t as [| m IH]; simpl.
  - (* t = 0：KL ≤ 1·KL *)
    apply (le_id_r (relative_entropy pi_star pi) (relative_entropy pi_star pi)
                   (mult one (relative_entropy pi_star pi))).
    + apply (id_sym (id_trans (mult_comm one (relative_entropy pi_star pi))
                              (mult_one (relative_entropy pi_star pi)))).
    + apply le_refl.
  - (* t = S m：单步收缩 + 归纳 + r_pow 结合换形 *)
    set (K := minus one eta).
    set (Pm := projT1 (policy_iterate m pi pi_pos)).
    set (Pm_pos := projT2 (policy_iterate m pi pi_pos)).
    set (KL0 := relative_entropy pi_star pi).
    (* 单步收缩应用于第 m 次迭代 *)
    assert (H1 : le (relative_entropy pi_star (pi_next Pm Pm_pos))
                    (mult K (relative_entropy pi_star Pm))).
    { unfold K.
      apply (policy_iter_kl_geom_step Pm Pm_pos (policy_iter_norm m pi pi_pos pi_norm)). }
    (* κ 非负：η ≤ 1 ⟹ 0 ≤ 1−η *)
    assert (Hk : le zero K).
    { unfold K. exact (le_minus_nonneg eta one eta_le_one). }
    (* 归纳前提乘 κ（le_mult_compat_weak + 交换换形） *)
    assert (H4 : le (mult K (relative_entropy pi_star Pm))
                    (mult K (mult (r_pow K m) KL0))).
    {
      apply (le_id_l (mult K (relative_entropy pi_star Pm))
                     (mult (relative_entropy pi_star Pm) K)
                     (mult K (mult (r_pow K m) KL0))).
      - apply mult_comm.
      - apply (le_id_r _ (mult (mult (r_pow K m) KL0) K) _).
        + apply mult_comm.
        + apply (le_mult_compat_weak (relative_entropy pi_star Pm)
                                     (mult (r_pow K m) KL0) K Hk).
          exact IH.
    }
    apply (le_trans _ (mult K (mult (r_pow K m) KL0)) _).
    + apply (le_trans _ (mult K (relative_entropy pi_star Pm)) _).
      * unfold K in H1. exact H1.
      * exact H4.
    + apply (le_id_r (mult K (mult (r_pow K m) KL0))
                     (mult K (mult (r_pow K m) KL0))
                     (mult (mult K (r_pow K m)) KL0)).
      * apply (mult_assoc K (r_pow K m) KL0).
      * apply le_refl.
Qed.

(* ============================================================ *)
(* DPO 损失沿策略改进轨道单调不增（2026-09-02 合入）            *)
(*   dpo_loss(pi) := opp (align_objective pi)（L18360）          *)
(*   单步：dpo_loss(pi_{t+1}) ≤ dpo_loss(pi_t)                   *)
(*     （policy_improvement_mono + opp_le_compat 组装）           *)
(*   迭代：沿 policy_iterate 轨道 dpo_loss 单调不增               *)
(*     ——DPO 从"π* 处损失有界"升格为"沿改进轨道损失单调下降"，  *)
(*       评审 S3"无损失动态"的闭合                                 *)
(* ============================================================ *)

(* 单步：dpo_loss(pi_next pi_t) ≤ dpo_loss(pi_t) *)
Theorem dpo_loss_iter_step_le :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    le (dpo_loss (pi_next pi_t pi_t_pos)) (dpo_loss pi_t).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  unfold dpo_loss.
  apply (opp_le_compat (align_objective pi_t) (align_objective (pi_next pi_t pi_t_pos))).
  exact (policy_improvement_mono pi_t pi_t_pos pi_t_norm).
Qed.

(* 迭代：dpo_loss(pi_{t+1}) ≤ dpo_loss(pi_t)（policy_iterate 轨道） *)
Theorem dpo_loss_iter_mono :
  forall (t : nat) (pi : S -> R) (pi_pos : forall s : S, lt zero (pi s))
         (pi_norm : Id (sum_over_S pi) one),
    le (dpo_loss (projT1 (policy_iterate (Datatypes.S t) pi pi_pos)))
       (dpo_loss (projT1 (policy_iterate t pi pi_pos))).
Proof.
  intros t pi pi_pos pi_norm.
  apply (le_id_l (dpo_loss (projT1 (policy_iterate (Datatypes.S t) pi pi_pos)))
                 (dpo_loss (pi_next (projT1 (policy_iterate t pi pi_pos)) (projT2 (policy_iterate t pi pi_pos))))
                 (dpo_loss (projT1 (policy_iterate t pi pi_pos)))).
  - reflexivity.
  - apply (dpo_loss_iter_step_le (projT1 (policy_iterate t pi pi_pos))
                                 (projT2 (policy_iterate t pi pi_pos))
                                 (policy_iter_norm t pi pi_pos pi_norm)).
Qed.

End Alignment.

(* ============================================================ *)
(* 迭代 211 批量回收（2026-09-04）：U2 改进算子不动点与等值刻画  *)
(* （镜像 Section U2FixedPoint，整节后置于 End Alignment.）；     *)
(* 来源：演变/.ablation/sc2_u2_fixed/u2_fixedpoint.v；10 Qed；    *)
(* 零 Axiom / Admitted / Classical。                            *)
(* ============================================================ *)

Section U2FixedPoint.

(* ---- 镜像 Section Alignment 的声明（同名同序；未用变量不声明） ---- *)
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.
Local Existing Instance RI_base.

Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let inv_pos := @inv_pos RI.
Let le := @le RI.
Let lt := @lt RI.
Let log := @log RI.
Let exp_neg := @exp_neg RI.
Let sum_over_S := @sum_over_S RI SS SO.

Variable reward : S -> R.
Variable beta : R.
Variable beta_pos : lt zero beta.
Variable pi_ref : S -> R.
Variable pi_ref_pos : forall s : S, lt zero (pi_ref s).
Variable Z_align_pos : lt zero (Z_align reward beta beta_pos pi_ref).
Variable eta : R.
Variable eta_pos : lt zero eta.
Variable eta_le_one : le eta one.
Variable sum_over_S_pos : forall (f : S -> R), (forall s : S, lt zero (f s)) -> lt zero (sum_over_S f).

(* ---- 根库 Alignment 内局部名的实例化别名（同名 Let，正文可直移） ---- *)
Let pi_star := (pi_star reward beta beta_pos pi_ref Z_align_pos).
Let align_objective := (align_objective reward beta pi_ref).
Let pi_next := (pi_next reward beta beta_pos pi_ref eta sum_over_S_pos).
Let pi_star_pos := (pi_star_pos reward beta beta_pos pi_ref pi_ref_pos Z_align_pos).
Let pi_star_normalized := (pi_star_normalized reward beta beta_pos pi_ref Z_align_pos).
Let pi_next_normalized := (pi_next_normalized reward beta beta_pos pi_ref eta sum_over_S_pos).
Let pi_next_pos := (pi_next_pos reward beta beta_pos pi_ref eta sum_over_S_pos).
Let rlhf_optimal := (rlhf_optimal reward beta beta_pos pi_ref pi_ref_pos Z_align_pos).
Let policy_improvement_mono :=
  (policy_improvement_mono reward beta beta_pos pi_ref eta eta_pos eta_le_one sum_over_S_pos).
Let policy_iter_gap_diff :=
  (policy_iter_gap_diff reward beta beta_pos pi_ref eta eta_pos sum_over_S_pos).
Let policy_iter_backward_kl_step_le :=
  (policy_iter_backward_kl_step_le reward beta beta_pos pi_ref pi_ref_pos Z_align_pos eta eta_pos
     sum_over_S_pos).
Let free_energy_ext := (free_energy_ext reward beta pi_ref).

(* =====================================================================
   常规序-环辅助（同 4.8 证明风格；无三分律、无经典）
   ===================================================================== *)

(* 辅助 A：两非负项之和为零 ⟹ 每项为零（a + b == 0 且 0 ≤ a、0 ≤ b ⟹ a == 0） *)
Lemma u2_nonneg_sum_zero : forall a b : R,
  le zero a -> le zero b -> Id (plus a b) zero -> Id a zero.
Proof.
  intros a b Ha Hb Habs.
  (* a ≤ a + b（b ≥ 0），而 a + b == 0，故 a ≤ 0 *)
  assert (H1 : le a (plus a b)) by exact (le_plus_nonneg_r a b Hb).
  assert (H2 : le a zero) by exact (le_id_r a (plus a b) zero Habs H1).
  (* le_antisym：0 ≤ a 且 a ≤ 0 ⟹ a == 0 *)
  exact (id_sym (le_antisym zero a Ha H2)).
Qed.

(* 辅助 B：相对熵对第二参数逐点相等的外延性（KL 同余，U2c 换形用） *)
Lemma u2_kl_arg2_ext :
  forall (p q q' : S -> R),
    (forall s : S, Id (q s) (q' s)) ->
    Id (relative_entropy p q) (relative_entropy p q').
Proof.
  intros p q q' Hqq'.
  unfold relative_entropy.
  apply sum_over_S_ext.
  intro s.
  exact (id_cong2 mult (id_refl)
                      (id_cong (fun x => minus (log (p s)) x) (id_cong log (Hqq' s)))).
Qed.

(* 辅助 C：(a − b) − a == −b（U2c 的 −ηA 提取） *)
Lemma u2_minus_minus : forall a b : R,
  Id (minus (minus a b) a) (opp b).
Proof.
  intros a b.
  unfold minus.
  apply (id_trans (id_sym (plus_assoc a (opp b) (opp a)))).
  apply (id_trans (id_cong (fun x => plus a x) (plus_comm (opp b) (opp a)))).
  apply (id_trans (plus_assoc a (opp a) (opp b))).
  apply (id_trans (id_cong (fun x => plus x (opp b)) (plus_opp a))).
  apply (id_trans (plus_comm zero (opp b)) (plus_zero (opp b))).
Qed.

(* 辅助 D：对齐目标对策略逐点相等的外延性（rlhf_optimal_unique 同型引理） *)
Lemma u2_align_objective_ext :
  forall (p q : S -> R),
    (forall s : S, Id (p s) (q s)) ->
    Id (align_objective p) (align_objective q).
Proof.
  intros p q Hpq.
  unfold align_objective.
  apply (id_cong opp).
  apply (free_energy_ext p q Hpq).
Qed.

(* =====================================================================
   U2a：π* 是单步改进算子 pi_next 的不动点
     pi_next pi_star ps_pos == pi_star（逐点）
   证明：rlhf_optimal（J(Tπ*） ≤ J(π*））+ policy_improvement_mono
     （J(π*） ≤ J(Tπ*））夹逼出 J 差 == 0；代入 policy_iter_gap_diff 恒等式
     得 β·[(1/η−1)KL(Tπ*‖π*） + (1/η)KL(π*‖Tπ*）] == 0；非负项和为零且
     1/η > 0 ⟹ KL(π*‖Tπ*） == 0 ⟹ gibbs_equality ⟹ Tπ* == π* 逐点。
   ===================================================================== *)
Theorem u2_pi_next_pi_star_fixed :
  forall (ps_pos : forall s : S, lt zero (pi_star s))
         (ps_norm : Id (sum_over_S pi_star) one),
    forall s : S, Id (pi_next pi_star ps_pos s) (pi_star s).
Proof.
  intros ps_pos ps_norm s0.
  set (Np := pi_next pi_star ps_pos).
  set (K1 := relative_entropy Np pi_star).
  set (K2 := relative_entropy pi_star Np).
  assert (HNp_norm : Id (sum_over_S Np) one)
    by (unfold Np; apply (pi_next_normalized pi_star ps_pos)).
  assert (HNp_pos : forall s : S, lt zero (Np s))
    by (intro s; unfold Np; apply (pi_next_pos pi_star ps_pos s)).
  (* 1. 夹逼：J(Tπ*） ≤ J(π*） 且 J(π*） ≤ J(Tπ*） ⟹ 目标差 == 0 *)
  assert (Hopt : le (align_objective Np) (align_objective pi_star))
    by exact (rlhf_optimal Np HNp_norm HNp_pos).
  assert (Hmono : le (align_objective pi_star) (align_objective Np))
    by exact (policy_improvement_mono pi_star ps_pos ps_norm).
  assert (Hjeq : Id (align_objective Np) (align_objective pi_star))
    by exact (le_antisym (align_objective Np) (align_objective pi_star) Hopt Hmono).
  assert (Hdiff0 : Id (minus (align_objective Np) (align_objective pi_star)) zero)
    by exact (minus_self_zero (align_objective Np) (align_objective pi_star) Hjeq).
  (* 2. gap 恒等式：J(Tπ*） − J(π*） == β·[(1/η−1)·K1 + (1/η)·K2] *)
  assert (Hgap : Id (minus (align_objective Np) (align_objective pi_star))
                    (mult beta
                          (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                                (mult (inv_pos eta eta_pos) K2)))).
  {
    unfold Np, K1, K2.
    exact (policy_iter_gap_diff pi_star ps_pos ps_norm).
  }
  (* 3. β > 0 消去（mult_cancel_l）：括号内 == 0 *)
  assert (HX0 : Id (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                         (mult (inv_pos eta eta_pos) K2)) zero).
  {
    apply (mult_cancel_l beta
                         (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                               (mult (inv_pos eta eta_pos) K2))
                         zero beta_pos).
    exact (id_trans (id_trans (id_sym Hgap) Hdiff0) (id_sym (mult_zero beta))).
  }
  (* 4. 非负性：(1/η−1) ≥ 0（η ≤ 1 ⟹ 1 ≤ 1/η）、K1 ≥ 0、K2 ≥ 0 *)
  assert (HP : le zero (minus (inv_pos eta eta_pos) one)).
  {
    assert (Hinv1 : Id (inv_pos one one_pos) one)
      by exact (id_trans (id_sym (id_trans (mult_comm one (inv_pos one one_pos))
                                           (mult_one (inv_pos one one_pos))))
                         (inv_pos_correct one one_pos)).
    assert (Hinv_le : le (inv_pos one one_pos) (inv_pos eta eta_pos))
      by exact (inv_pos_le_compat eta one eta_pos one_pos eta_le_one).
    assert (Hle1 : le one (inv_pos eta eta_pos))
      by exact (le_id_l one (inv_pos one one_pos) (inv_pos eta eta_pos) (id_sym Hinv1) Hinv_le).
    exact (le_minus_nonneg one (inv_pos eta eta_pos) Hle1).
  }
  assert (HK1 : le zero K1)
    by (unfold K1; apply (gibbs_inequality Np pi_star HNp_norm HNp_pos ps_norm ps_pos)).
  assert (HK2 : le zero K2)
    by (unfold K2; apply (gibbs_inequality pi_star Np ps_norm ps_pos HNp_norm HNp_pos)).
  assert (HPK1 : le zero (mult (minus (inv_pos eta eta_pos) one) K1))
    by (apply (le_mult_nonneg_t12 (minus (inv_pos eta eta_pos) one) K1 HP HK1)).
  assert (HQK2 : le zero (mult (inv_pos eta eta_pos) K2)).
  {
    apply (le_mult_nonneg_t12 (inv_pos eta eta_pos) K2).
    - apply (lt_le_iff zero (inv_pos eta eta_pos)). left. exact (inv_pos_pos eta eta_pos).
    - exact HK2.
  }
  (* 5. 非负和为零 ⟹ (1/η)·K2 == 0 ⟹（1/η > 0）K2 == 0 *)
  assert (HQK2z : Id (mult (inv_pos eta eta_pos) K2) zero).
  {
    apply (u2_nonneg_sum_zero (mult (inv_pos eta eta_pos) K2)
                              (mult (minus (inv_pos eta eta_pos) one) K1)
                              HQK2 HPK1).
    apply (id_trans (plus_comm (mult (inv_pos eta eta_pos) K2)
                               (mult (minus (inv_pos eta eta_pos) one) K1)) HX0).
  }
  assert (HK2z : Id K2 zero).
  {
    apply (mult_cancel_l (inv_pos eta eta_pos) K2 zero (inv_pos_pos eta eta_pos)).
    apply (id_trans HQK2z (id_sym (mult_zero (inv_pos eta eta_pos)))).
  }
  (* 6. gibbs_equality：KL(π*‖Tπ*） == 0 ⟹ π* == Tπ* 逐点 ⟹ 结论（id_sym） *)
  assert (Hpi : forall s : S, Id (pi_star s) (Np s))
    by (apply (gibbs_equality pi_star Np ps_norm ps_pos HNp_norm HNp_pos);
        unfold K2 in HK2z; exact HK2z).
  exact (id_sym (Hpi s0)).
Qed.

(* =====================================================================
   U2b：无进展 ⟹ 不动点
     J(pi_next pi_t) == J(pi_t) ⟹ pi_next pi_t == pi_t（逐点）
   证明：与 U2a 第 3–6 步同构（目标等值直接给出 J 差 == 0，无需夹逼）。
   ===================================================================== *)
Theorem u2_no_progress_fixed_point :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    Id (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t) ->
    forall s : S, Id (pi_next pi_t pi_t_pos s) (pi_t s).
Proof.
  intros pi_t pi_t_pos pi_t_norm Hno s0.
  set (Np := pi_next pi_t pi_t_pos).
  set (K1 := relative_entropy Np pi_t).
  set (K2 := relative_entropy pi_t Np).
  assert (HNp_norm : Id (sum_over_S Np) one)
    by (unfold Np; apply (pi_next_normalized pi_t pi_t_pos)).
  assert (HNp_pos : forall s : S, lt zero (Np s))
    by (intro s; unfold Np; apply (pi_next_pos pi_t pi_t_pos s)).
  (* 1. 目标差 == 0（无进展假设） *)
  assert (Hdiff0 : Id (minus (align_objective Np) (align_objective pi_t)) zero)
    by (unfold Np; exact (minus_self_zero (align_objective Np) (align_objective pi_t) Hno)).
  (* 2. gap 恒等式：J(Tπ) − J(π) == β·[(1/η−1)·K1 + (1/η)·K2] *)
  assert (Hgap : Id (minus (align_objective Np) (align_objective pi_t))
                    (mult beta
                          (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                                (mult (inv_pos eta eta_pos) K2)))).
  {
    unfold Np, K1, K2.
    exact (policy_iter_gap_diff pi_t pi_t_pos pi_t_norm).
  }
  (* 3. β > 0 消去 *)
  assert (HX0 : Id (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                         (mult (inv_pos eta eta_pos) K2)) zero).
  {
    apply (mult_cancel_l beta
                         (plus (mult (minus (inv_pos eta eta_pos) one) K1)
                               (mult (inv_pos eta eta_pos) K2))
                         zero beta_pos).
    exact (id_trans (id_trans (id_sym Hgap) Hdiff0) (id_sym (mult_zero beta))).
  }
  (* 4. 非负性 *)
  assert (HP : le zero (minus (inv_pos eta eta_pos) one)).
  {
    assert (Hinv1 : Id (inv_pos one one_pos) one)
      by exact (id_trans (id_sym (id_trans (mult_comm one (inv_pos one one_pos))
                                           (mult_one (inv_pos one one_pos))))
                         (inv_pos_correct one one_pos)).
    assert (Hinv_le : le (inv_pos one one_pos) (inv_pos eta eta_pos))
      by exact (inv_pos_le_compat eta one eta_pos one_pos eta_le_one).
    assert (Hle1 : le one (inv_pos eta eta_pos))
      by exact (le_id_l one (inv_pos one one_pos) (inv_pos eta eta_pos) (id_sym Hinv1) Hinv_le).
    exact (le_minus_nonneg one (inv_pos eta eta_pos) Hle1).
  }
  assert (HK1 : le zero K1)
    by (unfold K1; apply (gibbs_inequality Np pi_t HNp_norm HNp_pos pi_t_norm pi_t_pos)).
  assert (HK2 : le zero K2)
    by (unfold K2; apply (gibbs_inequality pi_t Np pi_t_norm pi_t_pos HNp_norm HNp_pos)).
  assert (HPK1 : le zero (mult (minus (inv_pos eta eta_pos) one) K1))
    by (apply (le_mult_nonneg_t12 (minus (inv_pos eta eta_pos) one) K1 HP HK1)).
  assert (HQK2 : le zero (mult (inv_pos eta eta_pos) K2)).
  {
    apply (le_mult_nonneg_t12 (inv_pos eta eta_pos) K2).
    - apply (lt_le_iff zero (inv_pos eta eta_pos)). left. exact (inv_pos_pos eta eta_pos).
    - exact HK2.
  }
  (* 5. (1/η)·K2 == 0 ⟹ K2 == 0 *)
  assert (HQK2z : Id (mult (inv_pos eta eta_pos) K2) zero).
  {
    apply (u2_nonneg_sum_zero (mult (inv_pos eta eta_pos) K2)
                              (mult (minus (inv_pos eta eta_pos) one) K1)
                              HQK2 HPK1).
    apply (id_trans (plus_comm (mult (inv_pos eta eta_pos) K2)
                               (mult (minus (inv_pos eta eta_pos) one) K1)) HX0).
  }
  assert (HK2z : Id K2 zero).
  {
    apply (mult_cancel_l (inv_pos eta eta_pos) K2 zero (inv_pos_pos eta eta_pos)).
    apply (id_trans HQK2z (id_sym (mult_zero (inv_pos eta eta_pos)))).
  }
  (* 6. gibbs_equality：KL(π‖Tπ) == 0 ⟹ π == Tπ 逐点 ⟹ 结论（id_sym） *)
  assert (Hpi : forall s : S, Id (pi_t s) (Np s))
    by (apply (gibbs_equality pi_t Np pi_t_norm pi_t_pos HNp_norm HNp_pos);
        unfold K2 in HK2z; exact HK2z).
  exact (id_sym (Hpi s0)).
Qed.

(* =====================================================================
   U2c：不动点唯一 ⟹ π*
     (forall s, pi_next pi_t pi_t_pos s == pi_t s) ⟹ pi_t == pi_star（逐点）
   证明：不动点处向后 KL 单步 ≤ 化简为 KL(π*‖π_t) ≤ (1−η)·KL(π*‖π_t)，
     η > 0 乘回得 η·A ≤ 0；gibbs 给 0 ≤ A，η ≥ 0 ⟹ 0 ≤ η·A；夹逼
     η·A == 0 ⟹ A == 0 ⟹ gibbs_equality ⟹ π_t == π* 逐点。
   ===================================================================== *)
Theorem u2_fixed_point_unique :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    (forall s : S, Id (pi_next pi_t pi_t_pos s) (pi_t s)) ->
    forall s : S, Id (pi_t s) (pi_star s).
Proof.
  intros pi_t pi_t_pos pi_t_norm Hfix s0.
  set (A := relative_entropy pi_star pi_t).
  (* 1. 同余换形：KL(π*‖Tπ) == A 且 KL(π‖Tπ) == 0 *)
  assert (Hc1 : Id (relative_entropy pi_star (pi_next pi_t pi_t_pos))
                   (relative_entropy pi_star pi_t)).
  { apply (u2_kl_arg2_ext pi_star (pi_next pi_t pi_t_pos) pi_t). exact Hfix. }
  assert (Hc2 : Id (relative_entropy pi_t (pi_next pi_t pi_t_pos))
                   (relative_entropy pi_t pi_t)).
  { apply (u2_kl_arg2_ext pi_t (pi_next pi_t pi_t_pos) pi_t). exact Hfix. }
  assert (HC0 : Id (relative_entropy pi_t (pi_next pi_t pi_t_pos)) zero)
    by exact (id_trans Hc2 (relative_entropy_self_zero' pi_t)).
  (* 2. 向后 KL 单步（≤ 版）：KL(π*‖Tπ) ≤ (1−η)·KL(π*‖π) + KL(π‖Tπ) *)
  assert (HleA : le A (mult (minus one eta) A)).
  {
    assert (H1 : le (relative_entropy pi_star (pi_next pi_t pi_t_pos))
                    (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                          (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
    { apply (policy_iter_backward_kl_step_le pi_t pi_t_pos pi_t_norm).
      intro s. apply (pi_next_pos pi_t pi_t_pos s). }
    (* 右端 (1−η)KL(π*‖π_t) 换为 (1−η)A *)
    assert (H2 : Id (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                           (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                    (plus (mult (minus one eta) A)
                          (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
    {
      apply (id_cong (fun x => plus x (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
      apply (id_cong (fun x => mult (minus one eta) x)).
      unfold A. reflexivity.
    }
    (* 左端 KL(π*‖Tπ) 换为 A *)
    assert (H3 : le A (plus (mult (minus one eta) A)
                            (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
    {
      apply (le_id_l A (relative_entropy pi_star (pi_next pi_t pi_t_pos))
                       (plus (mult (minus one eta) A)
                             (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
      - unfold A. exact (id_sym Hc1).
      - apply (le_id_r (relative_entropy pi_star (pi_next pi_t pi_t_pos))
                       (plus (mult (minus one eta) (relative_entropy pi_star pi_t))
                             (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                       (plus (mult (minus one eta) A)
                             (relative_entropy pi_t (pi_next pi_t pi_t_pos)))).
        + exact H2.
        + exact H1.
    }
    (* KL(π‖Tπ) == 0 ⟹ 右端 == (1−η)A *)
    assert (H4 : Id (plus (mult (minus one eta) A)
                          (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                    (mult (minus one eta) A)).
    {
      apply (id_trans (id_cong (fun x => plus (mult (minus one eta) A) x) HC0)
                      (plus_zero (mult (minus one eta) A))).
    }
    apply (le_id_r A (plus (mult (minus one eta) A)
                           (relative_entropy pi_t (pi_next pi_t pi_t_pos)))
                   (mult (minus one eta) A) H4 H3).
  }
  (* 3. (1−η)A == A − ηA，故 A ≤ A − ηA *)
  assert (Hma : Id (mult (minus one eta) (relative_entropy pi_star pi_t))
                   (minus (relative_entropy pi_star pi_t)
                          (mult eta (relative_entropy pi_star pi_t)))).
  {
    apply (id_trans (mult_minus_distr_r one eta (relative_entropy pi_star pi_t))).
    apply (id_cong (fun x => minus x (mult eta (relative_entropy pi_star pi_t)))).
    apply (id_trans (mult_comm one (relative_entropy pi_star pi_t))
                    (mult_one (relative_entropy pi_star pi_t))).
  }
  assert (HleB : le (relative_entropy pi_star pi_t)
                    (minus (relative_entropy pi_star pi_t)
                           (mult eta (relative_entropy pi_star pi_t)))).
  {
    apply (le_id_r (relative_entropy pi_star pi_t)
                   (mult (minus one eta) (relative_entropy pi_star pi_t))
                   (minus (relative_entropy pi_star pi_t)
                          (mult eta (relative_entropy pi_star pi_t)))).
    - exact Hma.
    - unfold A in HleA. exact HleA.
  }
  (* 4. 0 ≤ −ηA（le_minus_nonneg + (A − ηA) − A == −ηA） *)
  assert (Hz1 : le zero (minus (minus (relative_entropy pi_star pi_t)
                                      (mult eta (relative_entropy pi_star pi_t)))
                               (relative_entropy pi_star pi_t)))
    by (apply (le_minus_nonneg (relative_entropy pi_star pi_t)
                               (minus (relative_entropy pi_star pi_t)
                                      (mult eta (relative_entropy pi_star pi_t))));
        exact HleB).
  assert (Hz2 : le zero (opp (mult eta (relative_entropy pi_star pi_t)))).
  {
    apply (le_id_r zero
                   (minus (minus (relative_entropy pi_star pi_t)
                                 (mult eta (relative_entropy pi_star pi_t)))
                          (relative_entropy pi_star pi_t))
                   (opp (mult eta (relative_entropy pi_star pi_t)))).
    - apply (u2_minus_minus (relative_entropy pi_star pi_t)
                            (mult eta (relative_entropy pi_star pi_t))).
    - exact Hz1.
  }
  (* 5. ηA ≤ 0（取负两次反号） *)
  assert (Hopp0 : le (opp (opp (mult eta (relative_entropy pi_star pi_t))))
                     (opp zero))
    by exact (opp_le_compat zero (opp (mult eta (relative_entropy pi_star pi_t))) Hz2).
  assert (Hopp1 : le (opp (opp (mult eta (relative_entropy pi_star pi_t)))) zero)
    by exact (le_id_r (opp (opp (mult eta (relative_entropy pi_star pi_t))))
                      (opp zero) zero opp_zero_t13 Hopp0).
  assert (Heta_le0 : le (mult eta (relative_entropy pi_star pi_t)) zero)
    by exact (le_id_l (mult eta (relative_entropy pi_star pi_t))
                      (opp (opp (mult eta (relative_entropy pi_star pi_t))))
                      zero (id_sym (double_neg (mult eta (relative_entropy pi_star pi_t))))
                      Hopp1).
  (* 6. 0 ≤ ηA（gibbs：0 ≤ A；η ≥ 0 ⟹ 0 ≤ ηA） *)
  assert (HA0 : le zero (relative_entropy pi_star pi_t))
    by (apply (gibbs_inequality pi_star pi_t pi_star_normalized pi_star_pos pi_t_norm pi_t_pos)).
  assert (Heta0 : le zero eta)
    by exact (lt_le_iff zero eta (inl eta_pos)).
  assert (HX0 : le zero (mult eta (relative_entropy pi_star pi_t)))
    by (apply (le_mult_nonneg_t12 eta (relative_entropy pi_star pi_t));
        [exact Heta0 | exact HA0]).
  (* 7. ηA == 0 ⟹（η > 0）A == 0 ⟹ gibbs_equality ⟹ π_t == π* 逐点 *)
  assert (HXz : Id (mult eta (relative_entropy pi_star pi_t)) zero)
    by exact (id_sym (le_antisym zero (mult eta (relative_entropy pi_star pi_t)) HX0 Heta_le0)).
  assert (HAz : Id (relative_entropy pi_star pi_t) zero).
  {
    apply (mult_cancel_l eta (relative_entropy pi_star pi_t) zero eta_pos).
    apply (id_trans HXz (id_sym (mult_zero eta))).
  }
  assert (Hpi : forall s : S, Id (pi_star s) (pi_t s))
    by (apply (gibbs_equality pi_star pi_t pi_star_normalized pi_star_pos pi_t_norm pi_t_pos HAz)).
  exact (id_sym (Hpi s0)).
Qed.

(* =====================================================================
   推论：无进展 ⟹ 已最优（u2b + u2c 组装）
     J(pi_next pi_t) == J(pi_t) ⟹ pi_t == pi_star（逐点）
   ===================================================================== *)
Theorem u2_no_progress_optimal :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    Id (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t) ->
    forall s : S, Id (pi_t s) (pi_star s).
Proof.
  intros pi_t pi_t_pos pi_t_norm Hno s0.
  (* Tπ == π（无进展 ⟹ 不动点） *)
  assert (Hfp : forall s : S, Id (pi_next pi_t pi_t_pos s) (pi_t s))
    by (apply (u2_no_progress_fixed_point pi_t pi_t_pos pi_t_norm); exact Hno).
  (* π == π*（不动点唯一 ⟹ π*） *)
  exact (u2_fixed_point_unique pi_t pi_t_pos pi_t_norm Hfp s0).
Qed.

(* =====================================================================
   反向：已最优 ⟹ 无进展
     pi_t == pi_star（逐点）⟹ J(pi_next pi_t) == J(pi_t)
   证明：逐点相等 + 目标外延 ⟹ J(π_t) == J(π*）；
     rlhf_optimal（J(Tπ) ≤ J(π*））+ policy_improvement_mono（J(π) ≤ J(Tπ)）
     夹逼 ⟹ J(Tπ) == J(π)（等值传递）。
   ===================================================================== *)
Theorem u2_optimal_no_progress :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
    (forall s : S, Id (pi_t s) (pi_star s)) ->
    Id (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t).
Proof.
  intros pi_t pi_t_pos pi_t_norm Hpi.
  set (Np := pi_next pi_t pi_t_pos).
  assert (HNp_norm : Id (sum_over_S Np) one)
    by (unfold Np; apply (pi_next_normalized pi_t pi_t_pos)).
  assert (HNp_pos : forall s : S, lt zero (Np s))
    by (intro s; unfold Np; apply (pi_next_pos pi_t pi_t_pos s)).
  (* J(π_t) == J(π*）（逐点外延） *)
  assert (Hext : Id (align_objective pi_t) (align_objective pi_star))
    by (apply (u2_align_objective_ext pi_t pi_star); exact Hpi).
  (* J(Tπ) ≤ J(π*） 与 J(π) ≤ J(Tπ) 夹逼 *)
  assert (Hopt : le (align_objective Np) (align_objective pi_star))
    by (unfold Np; exact (rlhf_optimal Np HNp_norm HNp_pos)).
  assert (Hmono : le (align_objective pi_t) (align_objective Np))
    by (unfold Np; exact (policy_improvement_mono pi_t pi_t_pos pi_t_norm)).
  assert (Hle1 : le (align_objective Np) (align_objective pi_t))
    by (apply (le_id_r (align_objective Np) (align_objective pi_star) (align_objective pi_t));
        [exact (id_sym Hext) | exact Hopt]).
  unfold Np.
  exact (le_antisym (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t)
                    Hle1 Hmono).
Qed.

(* =====================================================================
   等值刻画（双向，Set 层 And := A*B 乘积）：
     J(pi_next pi_t) == J(pi_t)  ⟺  pi_t == pi_star（逐点）
   ===================================================================== *)
Theorem u2_objective_eq_optimal_iff :
  forall (pi_t : S -> R) (pi_t_pos : forall s : S, lt zero (pi_t s))
         (pi_t_norm : Id (sum_over_S pi_t) one),
  And (Id (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t) ->
        forall s : S, Id (pi_t s) (pi_star s))
      ((forall s : S, Id (pi_t s) (pi_star s)) ->
        Id (align_objective (pi_next pi_t pi_t_pos)) (align_objective pi_t)).
Proof.
  intros pi_t pi_t_pos pi_t_norm.
  split.
  - intro H. apply (u2_no_progress_optimal pi_t pi_t_pos pi_t_norm H).
  - intro H. apply (u2_optimal_no_progress pi_t pi_t_pos pi_t_norm H).
Qed.

End U2FixedPoint.

(* ============================================================ *)
(* GRPO：组相对策略优化（组相对优势的构造性形式化）             *)
(* ============================================================ *)
(* DeepSeek-R1 核心算法：组内归一化优势 A_i = (r_i − μ)/σ 的      *)
(* 零均值性质。组求和用有限枚举列表 group_enum（同 S_enum 模式）；*)
(* 组均值 μ = (1/G)·Σr；σ 归一化对零均值无作用（Σ A_i·c = 0 对    *)
(* 任意缩放 c 成立）。                                           *)

Section GRPO.

Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let inv_pos := @inv_pos RI.
Let le := @le RI.
Let lt := @lt RI.

(* nat 到 R 的嵌入（构造性计数；0 ⟼ zero，S n ⟼ 1 + of_nat n） *)
Fixpoint of_nat (n : nat) : R :=
  match n with
  | O => zero
  | Datatypes.S n' => plus one (of_nat n')
  end.

Variable Group : Set.
Variable group_enum : list Group.
Variable group_cover : forall i : Group, InT i group_enum.
Definition group_size : nat := length group_enum.
Variable group_size_pos : lt zero (of_nat group_size).
Variable reward_group : Group -> R.

(* 组求和（列表 fold） *)
Fixpoint list_sum_g (f : Group -> R) (l : list Group) : R :=
  match l with
  | nil => zero
  | i :: rest => plus (f i) (list_sum_g f rest)
  end.

Lemma list_sum_g_linear : forall a : R, forall f : Group -> R, forall l : list Group,
  Id (list_sum_g (fun i => mult a (f i)) l) (mult a (list_sum_g f l)).
Proof.
  intros a f l. induction l as [| i rest IH]; simpl.
  - apply id_sym. apply mult_zero.
  - rewrite IH. apply id_sym. apply distrib.
Qed.

Lemma list_sum_g_add : forall f g : Group -> R, forall l : list Group,
  Id (list_sum_g (fun i => plus (f i) (g i)) l) (plus (list_sum_g f l) (list_sum_g g l)).
Proof.
  intros f g l. induction l as [| i rest IH]; simpl.
  - apply id_sym. apply plus_zero.
  - rewrite IH. exact (plus_swap_mid (f i) (g i) (list_sum_g f rest) (list_sum_g g rest)).
Qed.

Lemma list_sum_g_ext : forall f g : Group -> R, forall l : list Group,
  (forall i : Group, Id (f i) (g i)) -> Id (list_sum_g f l) (list_sum_g g l).
Proof.
  intros f g l Hfg. induction l as [| i rest IH]; simpl.
  - reflexivity.
  - assert (H1 : Id (plus (f i) (list_sum_g f rest)) (plus (f i) (list_sum_g g rest)))
      by exact (id_cong (fun x => plus (f i) x) IH).
    assert (H2 : Id (plus (f i) (list_sum_g g rest)) (plus (g i) (list_sum_g g rest)))
      by exact (id_cong (fun x => plus x (list_sum_g g rest)) (Hfg i)).
    exact (id_trans H1 H2).
Qed.

(* 常数求和：Σ_{i∈l} a = of_nat (length l) · a *)
Lemma list_sum_g_const : forall a : R, forall l : list Group,
  Id (list_sum_g (fun _ => a) l) (mult (of_nat (length l)) a).
Proof.
  intros a l. induction l as [| i rest IH]; simpl.
  - apply id_sym. exact (id_trans (mult_comm zero a) (mult_zero a)).
  - rewrite IH.
    assert (Hd : Id (mult (plus one (of_nat (length rest))) a)
                    (plus (mult one a) (mult (of_nat (length rest)) a)))
      by exact (mult_plus_distr_r one (of_nat (length rest)) a).
    assert (Ht : Id (plus a (mult (of_nat (length rest)) a))
                    (mult (plus one (of_nat (length rest))) a))
      by exact (id_trans (id_cong (fun x => plus x (mult (of_nat (length rest)) a))
                                  (id_trans (id_sym (mult_one a)) (mult_comm a one)))
                         (id_sym Hd)).
    exact Ht.
Qed.

(* 组求和的负号线性：Σ (-f) = -Σ f *)
Lemma list_sum_g_opp : forall f : Group -> R, forall l : list Group,
  Id (list_sum_g (fun i => opp (f i)) l) (opp (list_sum_g f l)).
Proof.
  intros f l. induction l as [| i rest IH]; simpl.
  - apply id_sym. apply (plus_inv_unique zero (opp zero) zero); [apply plus_opp | apply plus_zero].
  - assert (Hc : Id (plus (opp (f i)) (list_sum_g (fun i0 => opp (f i0)) rest))
                    (plus (opp (f i)) (opp (list_sum_g f rest))))
      by exact (id_cong (fun x => plus (opp (f i)) x) IH).
    assert (Ho : Id (plus (opp (f i)) (opp (list_sum_g f rest)))
                    (opp (plus (f i) (list_sum_g f rest))))
      by exact (id_sym (opp_plus (f i) (list_sum_g f rest))).
    exact (id_trans Hc Ho).
Qed.

(* 组求和的减法线性：Σ (f - g) = Σf - Σg *)
Lemma list_sum_g_minus : forall f g : Group -> R, forall l : list Group,
  Id (list_sum_g (fun i => minus (f i) (g i)) l) (minus (list_sum_g f l) (list_sum_g g l)).
Proof.
  intros f g l. unfold minus.
  assert (Hadd : Id (list_sum_g (fun i => plus (f i) (opp (g i))) l)
                    (plus (list_sum_g f l) (list_sum_g (fun i => opp (g i)) l)))
    by exact (list_sum_g_add f (fun i => opp (g i)) l).
  assert (Hopp : Id (list_sum_g (fun i => opp (g i)) l) (opp (list_sum_g g l)))
    by exact (list_sum_g_opp g l).
  exact (id_trans Hadd (id_cong (fun x => plus (list_sum_g f l) x) Hopp)).
Qed.

(* 组均值：μ = (1/G)·Σ r_i *)
Definition group_mean : R :=
  mult (inv_pos (of_nat group_size) group_size_pos) (list_sum_g reward_group group_enum).

(* 组相对优势：A_i = r_i − μ（σ 归一化在零均值定理中消去） *)
Definition grpo_advantage (i : Group) : R :=
  minus (reward_group i) group_mean.

(* 组相对优势的零均值性质：Σ_i (r_i − μ)·c = 0（对任意缩放 c）。
   证明：线性提取 c → Σ(r_i − μ) = Σr − G·μ = Σr − Σr = 0。 *)
Theorem grpo_advantage_zero_mean :
  forall c : R,
    Id (list_sum_g (fun i => mult (grpo_advantage i) c) group_enum) zero.
Proof.
  intros c.
  assert (Hext : Id (list_sum_g (fun i => mult (grpo_advantage i) c) group_enum)
                    (list_sum_g (fun i => mult c (grpo_advantage i)) group_enum))
    by (apply list_sum_g_ext; intro i; apply mult_comm).
  rewrite Hext.
  assert (Hlin : Id (list_sum_g (fun i => mult c (grpo_advantage i)) group_enum)
                    (mult c (list_sum_g grpo_advantage group_enum)))
    by exact (list_sum_g_linear c grpo_advantage group_enum).
  rewrite Hlin.
  assert (Hcancel : Id (list_sum_g grpo_advantage group_enum) zero).
  {
    unfold grpo_advantage.
    assert (Hmin : Id (list_sum_g (fun i => minus (reward_group i) group_mean) group_enum)
                      (minus (list_sum_g reward_group group_enum)
                             (list_sum_g (fun _ => group_mean) group_enum)))
      by exact (list_sum_g_minus reward_group (fun _ => group_mean) group_enum).
    rewrite Hmin.
    assert (Hconst : Id (list_sum_g (fun _ => group_mean) group_enum)
                        (mult (of_nat group_size) group_mean))
      by (unfold group_size; exact (list_sum_g_const group_mean group_enum)).
    rewrite Hconst.
    assert (Hcc : Id (mult (of_nat group_size) group_mean) (list_sum_g reward_group group_enum)).
    { unfold group_mean.
      assert (H1 : Id (mult (of_nat group_size) (mult (inv_pos (of_nat group_size) group_size_pos) (list_sum_g reward_group group_enum)))
                      (mult (mult (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos)) (list_sum_g reward_group group_enum)))
        by exact (mult_assoc (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos) (list_sum_g reward_group group_enum)).
      assert (H2 : Id (mult (mult (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos)) (list_sum_g reward_group group_enum))
                      (mult one (list_sum_g reward_group group_enum)))
        by exact (id_cong (fun z => mult z (list_sum_g reward_group group_enum))
                          (inv_pos_correct (of_nat group_size) group_size_pos)).
      assert (H3 : Id (mult one (list_sum_g reward_group group_enum)) (list_sum_g reward_group group_enum))
        by exact (id_trans (mult_comm one (list_sum_g reward_group group_enum)) (mult_one (list_sum_g reward_group group_enum))).
      exact (id_trans H1 (id_trans H2 H3)). }
    rewrite Hcc.
    exact (minus_self_zero _ _ (@id_refl R (list_sum_g reward_group group_enum))).
  }
  rewrite Hcancel.
  exact (mult_zero c).
Qed.

(* ============================================================ *)
(* GRPO 方差恒等式（聚焦AI算法.txt 模块 3）：                   *)
(*   Σ_i (r_i − μ)² = Σ_i r_i² − G·μ²                          *)
(* 证明：逐点展开 (r−μ)² = r² − 2·r·μ + μ²（distrib +          *)
(*   opp_mult_r/l + double_neg），求和线性化，用零均值性质       *)
(*   Σr = G·μ 消去交叉项，最终 −2·G·μ² + G·μ² = −G·μ²。         *)
(* ------------------------------------------------------------ *)

(* 组二阶矩：Σ r_i² *)
Definition group_raw_second_moment : R :=
  list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum.

(* 组方差（中心化二阶矩）：Σ (r_i − μ)² *)
Definition group_centered_second_moment : R :=
  list_sum_g (fun i => mult (grpo_advantage i) (grpo_advantage i)) group_enum.

(* 逐点展开：(r − μ)² = r² − 2·r·μ + μ²（非平凡代数链） *)
Lemma grpo_square_expand : forall i : Group,
  Id (mult (grpo_advantage i) (grpo_advantage i))
     (plus (mult (reward_group i) (reward_group i))
           (plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                 (mult group_mean group_mean))).
Proof.
  intro i.
  unfold grpo_advantage.
  (* (r − μ)² = (r + (−μ))·(r + (−μ)) *)
  assert (H1 : Id (mult (plus (reward_group i) (opp group_mean)) (plus (reward_group i) (opp group_mean)))
                  (plus (mult (reward_group i) (plus (reward_group i) (opp group_mean)))
                        (mult (opp group_mean) (plus (reward_group i) (opp group_mean)))))
    by exact (mult_plus_distr_r (reward_group i) (opp group_mean) (plus (reward_group i) (opp group_mean))).
  (* 第一项：r·(r + (−μ)) = r² + r·(−μ) = r² − r·μ *)
  assert (H2 : Id (mult (reward_group i) (plus (reward_group i) (opp group_mean)))
                  (plus (mult (reward_group i) (reward_group i)) (mult (reward_group i) (opp group_mean))))
    by exact (distrib (reward_group i) (reward_group i) (opp group_mean)).
  assert (H3 : Id (mult (reward_group i) (opp group_mean)) (opp (mult (reward_group i) group_mean)))
    by exact (opp_mult_l (reward_group i) group_mean).
  (* 第二项：(−μ)·(r + (−μ)) = (−μ)·r + (−μ)·(−μ) = −(μ·r) + μ² *)
  assert (H4 : Id (mult (opp group_mean) (plus (reward_group i) (opp group_mean)))
                  (plus (mult (opp group_mean) (reward_group i)) (mult (opp group_mean) (opp group_mean))))
    by exact (distrib (opp group_mean) (reward_group i) (opp group_mean)).
  assert (H5 : Id (mult (opp group_mean) (reward_group i)) (opp (mult group_mean (reward_group i))))
    by exact (opp_mult_r group_mean (reward_group i)).
  assert (H6 : Id (mult (opp group_mean) (opp group_mean)) (mult group_mean group_mean)).
  {
    assert (H6a : Id (mult (opp group_mean) (opp group_mean)) (opp (mult group_mean (opp group_mean))))
      by exact (opp_mult_r group_mean (opp group_mean)).
    assert (H6b : Id (opp (mult group_mean (opp group_mean))) (opp (opp (mult group_mean group_mean))))
      by exact (id_cong opp (opp_mult_l group_mean group_mean)).
    assert (H6c : Id (opp (opp (mult group_mean group_mean))) (mult group_mean group_mean))
      by exact (double_neg (mult group_mean group_mean)).
    exact (id_trans H6a (id_trans H6b H6c)).
  }
  (* 组装：r² − r·μ − μ·r + μ²；合并交叉项 −r·μ − μ·r = −2·r·μ *)
  assert (H7 : Id (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult (reward_group i) group_mean)))
                        (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)))
                  (plus (mult (reward_group i) (reward_group i))
                        (plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                              (mult group_mean group_mean)))).
  {
    (* 交叉项合并：−r·μ + (−μ·r) = −2·r·μ；用 μ·r = r·μ 换序 *)
    assert (Hsw : Id (opp (mult group_mean (reward_group i))) (opp (mult (reward_group i) group_mean)))
      by exact (id_cong opp (mult_comm group_mean (reward_group i))).
    assert (Hm1 : Id (plus (opp (mult (reward_group i) group_mean)) (opp (mult group_mean (reward_group i))))
                      (plus (opp (mult (reward_group i) group_mean)) (opp (mult (reward_group i) group_mean))))
      by exact (id_cong (fun x => plus (opp (mult (reward_group i) group_mean)) x) Hsw).
    assert (Hm2 : Id (plus (opp (mult (reward_group i) group_mean)) (opp (mult (reward_group i) group_mean)))
                      (opp (mult (mult (plus one one) (reward_group i)) group_mean))).
    {
      assert (Hm2a : Id (plus (opp (mult (reward_group i) group_mean)) (opp (mult (reward_group i) group_mean)))
                         (opp (plus (mult (reward_group i) group_mean) (mult (reward_group i) group_mean))))
        by exact (id_sym (opp_plus (mult (reward_group i) group_mean) (mult (reward_group i) group_mean))).
      assert (Hm2b : Id (mult (mult (plus one one) (reward_group i)) group_mean)
                        (plus (mult (reward_group i) group_mean) (mult (reward_group i) group_mean)))
        by exact (id_trans (id_cong (fun x => mult x group_mean) (two_mult (reward_group i)))
                           (mult_plus_distr_r (reward_group i) (reward_group i) group_mean)).
      exact (id_trans Hm2a (id_cong opp (id_sym Hm2b))).
    }
    (* 用 plus_swap_mid 重排四项为 r² + (交叉项和) + μ² 形态 *)
    assert (Hre : Id (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult (reward_group i) group_mean)))
                            (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)))
                      (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult group_mean (reward_group i))))
                            (plus (opp (mult (reward_group i) group_mean)) (mult group_mean group_mean))))
      by exact (plus_swap_mid (mult (reward_group i) (reward_group i)) (opp (mult (reward_group i) group_mean))
                              (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)).
    assert (Hre2 : Id (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult group_mean (reward_group i))))
                             (plus (opp (mult (reward_group i) group_mean)) (mult group_mean group_mean)))
                       (plus (mult (reward_group i) (reward_group i))
                             (plus (plus (opp (mult (reward_group i) group_mean)) (opp (mult group_mean (reward_group i))))
                                   (mult group_mean group_mean)))).
    {
      (* plus (plus r² x) (plus y μ²) = plus r² (plus (plus y x) μ²)
         用 plus_swap_mid 把 x,y 换到中间，再调整 y,x 顺序 *)
      assert (Hps : Id (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult group_mean (reward_group i))))
                             (plus (opp (mult (reward_group i) group_mean)) (mult group_mean group_mean)))
                       (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult (reward_group i) group_mean)))
                             (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean))))
        by exact (plus_swap_mid (mult (reward_group i) (reward_group i)) (opp (mult group_mean (reward_group i)))
                                (opp (mult (reward_group i) group_mean)) (mult group_mean group_mean)).
      assert (Hps2 : Id (plus (plus (mult (reward_group i) (reward_group i)) (opp (mult (reward_group i) group_mean)))
                              (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)))
                        (plus (mult (reward_group i) (reward_group i))
                              (plus (opp (mult (reward_group i) group_mean))
                                    (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)))))
        by exact (id_sym (plus_assoc (mult (reward_group i) (reward_group i))
                                     (opp (mult (reward_group i) group_mean))
                                     (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean)))).
      assert (Hps3 : Id (plus (mult (reward_group i) (reward_group i))
                              (plus (opp (mult (reward_group i) group_mean))
                                    (plus (opp (mult group_mean (reward_group i))) (mult group_mean group_mean))))
                        (plus (mult (reward_group i) (reward_group i))
                              (plus (plus (opp (mult (reward_group i) group_mean)) (opp (mult group_mean (reward_group i))))
                                    (mult group_mean group_mean))))
        by exact (id_cong (fun x => plus (mult (reward_group i) (reward_group i)) x)
                          (plus_assoc (opp (mult (reward_group i) group_mean))
                                      (opp (mult group_mean (reward_group i)))
                                      (mult group_mean group_mean))).
      exact (id_trans Hps (id_trans Hps2 Hps3)).
    }
    assert (Hre3 : Id (plus (mult (reward_group i) (reward_group i))
                            (plus (plus (opp (mult (reward_group i) group_mean)) (opp (mult group_mean (reward_group i))))
                                  (mult group_mean group_mean)))
                      (plus (mult (reward_group i) (reward_group i))
                            (plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                  (mult group_mean group_mean))))
      by exact (id_cong (fun x => plus (mult (reward_group i) (reward_group i)) (plus x (mult group_mean group_mean)))
                        (id_trans (id_cong (fun y => plus (opp (mult (reward_group i) group_mean)) y)
                                           (id_cong opp (mult_comm group_mean (reward_group i))))
                                  Hm2)).
    exact (id_trans Hre (id_trans Hre2 Hre3)).
  }
  exact (id_trans H1 (id_trans (id_cong2 plus (id_trans H2 (id_cong2 plus (@id_refl R (mult (reward_group i) (reward_group i))) H3))
                                              (id_trans H4 (id_cong2 plus H5 H6)))
                               H7)).
Qed.

(* GRPO 方差恒等式：Σ (r_i − μ)² = Σ r_i² − G·μ²
   非平凡：逐点展开 + 求和线性 + 零均值消交叉项（约 20 步代数链） *)
Theorem grpo_variance_identity :
  Id group_centered_second_moment
     (minus group_raw_second_moment (mult (of_nat group_size) (mult group_mean group_mean))).
Proof.
  unfold group_centered_second_moment, group_raw_second_moment.
  (* 逐点替换 (r−μ)² = r² − 2rμ + μ² *)
  assert (Hext : Id (list_sum_g (fun i => mult (grpo_advantage i) (grpo_advantage i)) group_enum)
                    (list_sum_g (fun i => plus (mult (reward_group i) (reward_group i))
                                              (plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                                    (mult group_mean group_mean))) group_enum))
    by (apply list_sum_g_ext; intro i; exact (grpo_square_expand i)).
  rewrite Hext.
  (* 求和线性化：Σ(r² + (−2rμ + μ²)) = Σr² + Σ(−2rμ) + Σμ² *)
  assert (Hadd1 : Id (list_sum_g (fun i => plus (mult (reward_group i) (reward_group i))
                                                (plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                                      (mult group_mean group_mean))) group_enum)
                     (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                           (list_sum_g (fun i => plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                                      (mult group_mean group_mean)) group_enum)))
    by exact (list_sum_g_add (fun i => mult (reward_group i) (reward_group i))
                             (fun i => plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                             (mult group_mean group_mean)) group_enum).
  rewrite Hadd1.
  assert (Hadd2 : Id (list_sum_g (fun i => plus (opp (mult (mult (plus one one) (reward_group i)) group_mean))
                                                (mult group_mean group_mean)) group_enum)
                     (plus (list_sum_g (fun i => opp (mult (mult (plus one one) (reward_group i)) group_mean)) group_enum)
                           (list_sum_g (fun _ => mult group_mean group_mean) group_enum)))
    by exact (list_sum_g_add (fun i => opp (mult (mult (plus one one) (reward_group i)) group_mean))
                             (fun _ => mult group_mean group_mean) group_enum).
  rewrite Hadd2.
  (* Σ(−2·r_i·μ) = −2·μ·Σr_i；Σμ² = G·μ² *)
  assert (Hopp : Id (list_sum_g (fun i => opp (mult (mult (plus one one) (reward_group i)) group_mean)) group_enum)
                    (opp (mult (mult (plus one one) (list_sum_g reward_group group_enum)) group_mean))).
  {
    assert (Hlin : Id (list_sum_g (fun i => mult (mult (plus one one) (reward_group i)) group_mean) group_enum)
                      (mult group_mean (list_sum_g (fun i => mult (plus one one) (reward_group i)) group_enum))).
    {
      assert (Hsw : Id (list_sum_g (fun i => mult (mult (plus one one) (reward_group i)) group_mean) group_enum)
                       (list_sum_g (fun i => mult group_mean (mult (plus one one) (reward_group i))) group_enum))
        by (apply list_sum_g_ext; intro i; apply mult_comm).
      rewrite Hsw. apply list_sum_g_linear.
    }
    assert (Hlin2 : Id (list_sum_g (fun i => mult (plus one one) (reward_group i)) group_enum)
                       (mult (plus one one) (list_sum_g reward_group group_enum)))
      by exact (list_sum_g_linear (plus one one) reward_group group_enum).
    assert (Hassoc : Id (mult group_mean (mult (plus one one) (list_sum_g reward_group group_enum)))
                        (mult (mult (plus one one) (list_sum_g reward_group group_enum)) group_mean))
      by exact (mult_comm group_mean (mult (plus one one) (list_sum_g reward_group group_enum))).
    assert (Hmid : Id (list_sum_g (fun i => mult (mult (plus one one) (reward_group i)) group_mean) group_enum)
                      (mult (mult (plus one one) (list_sum_g reward_group group_enum)) group_mean))
      by exact (id_trans Hlin (id_trans (id_cong (fun x => mult group_mean x) Hlin2) Hassoc)).
    exact (id_trans (list_sum_g_opp (fun i => mult (mult (plus one one) (reward_group i)) group_mean) group_enum)
                    (id_cong opp Hmid)).
  }
  rewrite Hopp.
  (* Σμ² = G·μ² *)
  assert (Hconst : Id (list_sum_g (fun _ => mult group_mean group_mean) group_enum)
                      (mult (of_nat group_size) (mult group_mean group_mean)))
    by (unfold group_size; exact (list_sum_g_const (mult group_mean group_mean) group_enum)).
  rewrite Hconst.
  (* 用 Σr = G·μ 消去：−2·μ·Σr + G·μ² = −2·G·μ² + G·μ² = −G·μ² *)
  assert (Hmu : Id (list_sum_g reward_group group_enum) (mult (of_nat group_size) group_mean)).
  {
    unfold group_mean.
    assert (H1 : Id (mult (of_nat group_size) (mult (inv_pos (of_nat group_size) group_size_pos) (list_sum_g reward_group group_enum)))
                    (mult (mult (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos)) (list_sum_g reward_group group_enum)))
      by exact (mult_assoc (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos) (list_sum_g reward_group group_enum)).
    assert (H2 : Id (mult (mult (of_nat group_size) (inv_pos (of_nat group_size) group_size_pos)) (list_sum_g reward_group group_enum))
                    (mult one (list_sum_g reward_group group_enum)))
      by exact (id_cong (fun z => mult z (list_sum_g reward_group group_enum)) (inv_pos_correct (of_nat group_size) group_size_pos)).
    assert (H3 : Id (mult one (list_sum_g reward_group group_enum)) (list_sum_g reward_group group_enum))
      by exact (id_trans (mult_comm one (list_sum_g reward_group group_enum)) (mult_one (list_sum_g reward_group group_enum))).
    exact (id_sym (id_trans H1 (id_trans H2 H3))).
  }
  assert (Hcross : Id (opp (mult (mult (plus one one) (list_sum_g reward_group group_enum)) group_mean))
                      (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))).
  { exact (id_cong opp (id_cong (fun x => mult (mult (plus one one) x) group_mean) Hmu)). }
  rewrite Hcross.
  (* 目标重组：Σr² + (opp(2·G·μ·μ) + G·μ²) = Σr² − G·μ² *)
  (* −2·G·μ² + G·μ² = −G·μ²（经 mult_assoc + 2·x − x = x） *)
  assert (Hcancel2 : Id (plus (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))
                              (mult (of_nat group_size) (mult group_mean group_mean)))
                        (opp (mult (of_nat group_size) (mult group_mean group_mean)))).
  {
    (* 2·(G·μ)·μ = 2·(G·μ²)；−2x + x = −x *)
    assert (H2a : Id (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean)
                     (mult (plus one one) (mult (of_nat group_size) (mult group_mean group_mean)))).
    {
      assert (H1 : Id (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean)
                      (mult (plus one one) (mult (mult (of_nat group_size) group_mean) group_mean)))
        by exact (id_sym (mult_assoc (plus one one) (mult (of_nat group_size) group_mean) group_mean)).
      assert (H2 : Id (mult (mult (of_nat group_size) group_mean) group_mean)
                      (mult (of_nat group_size) (mult group_mean group_mean)))
        by exact (id_sym (mult_assoc (of_nat group_size) group_mean group_mean)).
      exact (id_trans H1 (id_cong (fun x => mult (plus one one) x) H2)).
    }
    assert (H2b : Id (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))
                     (opp (mult (plus one one) (mult (of_nat group_size) (mult group_mean group_mean)))))
      by exact (id_cong opp H2a).
    (* 2x − x = x（对 x := G·μ²） *)
    set (x := mult (of_nat group_size) (mult group_mean group_mean)).
    assert (H2c : Id (plus (opp (mult (plus one one) x)) x) (opp x)).
    {
      (* 2x = x + x（two_mult），− (x+x) + x = −x（opp_plus + plus_assoc/opp） *)
      assert (Ht : Id (mult (plus one one) x) (plus x x)) by exact (two_mult x).
      assert (Hopp2 : Id (opp (plus x x)) (plus (opp x) (opp x))) by exact (opp_plus x x).
      assert (Hcomb : Id (plus (plus (opp x) (opp x)) x) (plus (opp x) (plus (opp x) x)))
        by exact (id_sym (plus_assoc (opp x) (opp x) x)).
      assert (Hoppx : Id (plus (opp x) x) zero)
        by exact (id_trans (plus_comm (opp x) x) (plus_opp x)).
      assert (Hzero : Id (plus (opp x) (plus (opp x) x)) (plus (opp x) zero))
        by exact (id_cong (fun y => plus (opp x) y) Hoppx).
      assert (Hz : Id (plus (opp x) zero) (opp x)) by exact (plus_zero (opp x)).
      assert (Hrhs : Id (plus (opp (plus x x)) x) (plus (plus (opp x) (opp x)) x))
        by exact (id_cong (fun y => plus y x) Hopp2).
      assert (Hfin : Id (plus (opp (plus x x)) x) (opp x))
        by exact (id_trans Hrhs (id_trans Hcomb (id_trans Hzero Hz))).
      exact (id_trans (id_cong (fun y => plus (opp y) x) Ht) Hfin).
    }
    exact (id_trans (id_cong (fun y => plus (opp y) (mult (of_nat group_size) (mult group_mean group_mean))) H2a) H2c).
  }
  (* 组装最终结果 *)
  assert (Hfinal : Id (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                            (plus (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))
                                  (mult (of_nat group_size) (mult group_mean group_mean))))
                      (minus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                             (mult (of_nat group_size) (mult group_mean group_mean)))).
  {
    assert (H1 : Id (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                          (plus (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))
                                (mult (of_nat group_size) (mult group_mean group_mean))))
                    (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                          (opp (mult (of_nat group_size) (mult group_mean group_mean)))))
      by exact (id_cong (fun y => plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum) y) Hcancel2).
    unfold minus.
    exact H1.
  }
  (* 组装主链：目标形态（含 Σr）→ 含 Gμ 形态（Hmid2）→ 最终 minus 形态（Hfinal） *)
  assert (Hmid2 : Id (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                           (plus (opp (mult (mult (plus one one) (list_sum_g reward_group group_enum)) group_mean))
                                 (mult (of_nat group_size) (mult group_mean group_mean))))
                     (plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                           (plus (opp (mult (mult (plus one one) (mult (of_nat group_size) group_mean)) group_mean))
                                 (mult (of_nat group_size) (mult group_mean group_mean)))))
    by exact (id_cong (fun y => plus (list_sum_g (fun i => mult (reward_group i) (reward_group i)) group_enum)
                                     (plus y (mult (of_nat group_size) (mult group_mean group_mean)))) Hcross).
  exact Hfinal.
Qed.

Definition group_variance : R :=
  mult (inv_pos (of_nat group_size) group_size_pos)
       (group_centered_second_moment).

(* 辅助：inv(G)·(G·(μ·μ)) == μ·μ（assoc + inv_pos_correct + one） *)
Lemma inv_G_absorb : forall (G : R) (Hg : lt zero G) (x : R),
  Id (mult (inv_pos G Hg) (mult G x)) x.
Proof.
  intros G Hg x.
  apply (id_trans (mult_assoc (inv_pos G Hg) G x)).
  apply (id_trans (id_cong (fun z => mult z x)
                           (id_trans (mult_comm (inv_pos G Hg) G) (inv_pos_correct G Hg)))).
  apply (id_trans (mult_comm one x)).
  apply (mult_one x).
Qed.

(* ===== 主定理：group_variance == (1/G)·Σr² − μ² =====
   grpo_variance_identity（L19774）给 Σ(r−μ)² == Σr² − G·μ²；
   两侧乘 inv(G)：invG·Σ(r−μ)² == invG·Σr² − invG·(G·μ²) == invG·Σr² − μ² *)
Theorem group_variance_identity :
  Id group_variance
     (minus (mult (inv_pos (of_nat group_size) group_size_pos)
                  (group_raw_second_moment))
            (mult (group_mean)
                  (group_mean))).
Proof.
  unfold group_variance.
  pose proof (grpo_variance_identity) as Hvar.
  (* 两侧乘 invG（id_trans 第一段：LHS == invG·(GRM − G·(μ·μ))） *)
  apply (id_trans (id_cong (fun z => mult (inv_pos (of_nat group_size) group_size_pos) z) Hvar)).
  (* 目标：Id (mult invG (minus GRM (mult G (mult μ μ))))
             (minus (mult invG GRM) (mult μ μ))
     展开 RHS 的分配：mult_minus_distr_l 正向（mult invG (minus A B) == minus (mult invG A) (mult invG B)） *)
  apply (id_trans (mult_minus_distr_l (inv_pos (of_nat group_size) group_size_pos)
                                      (group_raw_second_moment)
                                      (mult (of_nat group_size)
                                            (mult (group_mean)
                                                  (group_mean))))).
  (* 目标：Id (minus (mult invG GRM) (mult invG (mult G (mult μ μ))))
             (minus (mult invG GRM) (mult μ μ))
     内层：mult invG (mult G (mult μ μ)) == mult μ μ（inv_G_absorb） *)
  apply (id_cong (fun z => minus (mult (inv_pos (of_nat group_size) group_size_pos)
                                       (group_raw_second_moment)) z)
                 (inv_G_absorb (of_nat group_size) group_size_pos
                               (mult (group_mean)
                                     (group_mean)))).
Qed.

(* ============================================================ *)
(* T1.5（2026-09-02）：GRPO 基线方差归约（回应评审 3 的 S4）     *)
(*   Var ≤ (1/G)·Σr²：group_variance_identity（Var == raw − μ²） *)
(*   + 平方非负（μ² ≥ 0）——形式化 GRPO 核心动机"减均值降低二阶矩"； *)
(*   gap = μ²，等号当且仅当组均值零（square_zero 双向夹另行落地）。  *)
(*   诚实 Variable square_nonneg：构造性有序域无三分律，通用平方非负  *)
(*   需接口字段（E143-122；同 NaturalGradient）。                    *)
(* ============================================================ *)
Variable square_nonneg : forall a : R, le zero (mult a a).

(* 辅助：opp zero == zero（Section 内自证，set_opp_zero 定义在后） *)
Lemma grpo_opp_zero : Id (opp zero) zero.
Proof.
  apply id_sym.
  apply (plus_inv_unique zero zero (opp zero)).
  - apply (plus_zero zero).
  - apply (plus_opp zero).
Qed.

(* 辅助：0 ≤ b ⟹ a − b ≤ a（unfold minus + le_plus_compat + opp_le_compat） *)
Lemma grpo_le_minus : forall a b : R, le zero b -> le (minus a b) a.
Proof.
  intros a b Hb.
  unfold minus.
  apply (le_id_r (plus a (opp b)) (plus a zero) a).
  - apply (plus_zero a).
  - apply (le_plus_compat a a (opp b) zero).
    + apply le_refl.
    + apply (le_id_r (opp b) (opp zero) zero).
      * exact grpo_opp_zero.
      * apply (opp_le_compat zero b). exact Hb.
Qed.

(* T1.5 主定理：Var ≤ (1/G)·Σr²（基线方差归约，统计意义：减均值降低二阶矩） *)
Theorem group_variance_le_raw_second_moment :
  le group_variance
     (mult (inv_pos (of_nat group_size) group_size_pos)
           (group_raw_second_moment)).
Proof.
  apply (le_id_l group_variance
                 (minus (mult (inv_pos (of_nat group_size) group_size_pos)
                              (group_raw_second_moment))
                        (mult group_mean group_mean))
                 (mult (inv_pos (of_nat group_size) group_size_pos)
                       (group_raw_second_moment))).
  - exact group_variance_identity.
  - apply (grpo_le_minus (mult (inv_pos (of_nat group_size) group_size_pos)
                               (group_raw_second_moment))
                         (mult group_mean group_mean)).
    apply square_nonneg.
Qed.

End GRPO.

Section NaturalGradient.
Context {RI : RealInterfaceEnhanced}.
Context {SS : StateSpace RI}.
Context {SO : SumOver RI SS}.

(* 显式绑定基本类型与函数 *)
Let R := @R RI.
Let S := @S RI SS.
Let zero := @zero RI.
Let one := @one RI.
Let plus := @plus RI.
Let mult := @mult RI.
Let opp := @opp RI.
Let inv_pos := @inv_pos RI.
Let lt := @lt RI.
Let le := @le RI.
Let log := @log RI.                (* RealInterfaceEnhanced 中的 log *)
Let sum_over_S := @sum_over_S RI SS SO.

Variable Theta : Set.
Variable p_theta : Theta -> S -> R.
Variable partial : (Theta -> R) -> Theta -> R.

Definition fisher_info_scalar (theta : Theta) : R :=
  sum_over_S (fun s =>
    mult (p_theta theta s)
      (mult (partial (fun th => log (p_theta th s)) theta)
            (partial (fun th => log (p_theta th s)) theta))).

Variable free_energy_theta : Theta -> R.
(* 修正：梯度属于参数空间 Theta *)
Variable grad_free_energy : Theta -> Theta.

Variable theta_splus : Theta -> Theta -> Theta.
Variable theta_smult : R -> Theta -> Theta.
Variable theta_sopp : Theta -> Theta.

Variable fisher_pos : forall theta, lt zero (fisher_info_scalar theta).
Variable p_theta_pos : forall theta s, lt zero (p_theta theta s).

(* Fisher 正定性的核心：若 Fisher 信息为零（F(θ) = 0），则每个
   状态 s 上的权重项 p(θ,s)·(∂_θ log p(θ,s))² 为零。
   证明：F = Σ_s p·(∂log p)² 逐项非负（p > 0 × 平方非负），
   和为零且逐项非负 ⟹ 逐项为零（sum_over_S_zero_nonneg）。
   非平凡：非负和的零分解。平方非负由 square_nonneg 假设给出
   （构造性有序域无三分律，通用平方非负需接口字段）。 *)
Variable square_nonneg : forall a : R, le zero (mult a a).

Theorem fisher_zero_implies_pointwise :
  forall theta,
    Id (fisher_info_scalar theta) zero ->
    forall s : S, Id (mult (p_theta theta s)
                           (mult (partial (fun th => log (p_theta th s)) theta)
                                 (partial (fun th => log (p_theta th s)) theta)))
                     zero.
Proof.
  intros theta Hf0.
  unfold fisher_info_scalar in Hf0.
  (* 逐点非负：p·(∂log p)² ≥ 0（p > 0、平方非负、乘法保序） *)
  assert (Hpt_nonneg : forall s : S, le zero (mult (p_theta theta s)
       (mult (partial (fun th => log (p_theta th s)) theta)
             (partial (fun th => log (p_theta th s)) theta)))).
  {
    intro s.
    (* 0 ≤ p·(∂log p)²：经 0 ≤ (∂log p)² 与 p > 0 的乘法保序。
       le_mult_compat a b c : lt zero c -> le a b -> le (mult a c) (mult b c)。
       a := 0, b := (∂log p)², c := p（p > 0），再 mult_comm 换形。 *)
    assert (Hle_sq : le zero (mult (partial (fun th => log (p_theta th s)) theta)
                                  (partial (fun th => log (p_theta th s)) theta)))
      by exact (square_nonneg (partial (fun th => log (p_theta th s)) theta)).
    assert (Hle_p : le (mult zero (p_theta theta s))
                       (mult (mult (partial (fun th => log (p_theta th s)) theta)
                                   (partial (fun th => log (p_theta th s)) theta))
                             (p_theta theta s)))
      by exact (le_mult_compat zero (mult (partial (fun th => log (p_theta th s)) theta)
                                          (partial (fun th => log (p_theta th s)) theta))
                               (p_theta theta s) (p_theta_pos theta s) Hle_sq).
    (* mult 换形：mult 0 p = 0，mult ((∂logp)²) p = p·(∂logp)² *)
    assert (Hz0 : Id (mult zero (p_theta theta s)) zero)
      by exact (id_trans (mult_comm zero (p_theta theta s)) (mult_zero (p_theta theta s))).
    assert (Hswap : Id (mult (mult (partial (fun th => log (p_theta th s)) theta)
                                   (partial (fun th => log (p_theta th s)) theta))
                             (p_theta theta s))
                       (mult (p_theta theta s)
                             (mult (partial (fun th => log (p_theta th s)) theta)
                                   (partial (fun th => log (p_theta th s)) theta))))
      by exact (mult_comm (mult (partial (fun th => log (p_theta th s)) theta)
                                (partial (fun th => log (p_theta th s)) theta))
                          (p_theta theta s)).
    exact (le_id_l zero (mult zero (p_theta theta s))
                   (mult (p_theta theta s)
                         (mult (partial (fun th => log (p_theta th s)) theta)
                               (partial (fun th => log (p_theta th s)) theta)))
                   (id_sym Hz0)
                   (le_id_r (mult zero (p_theta theta s))
                            (mult (mult (partial (fun th => log (p_theta th s)) theta)
                                        (partial (fun th => log (p_theta th s)) theta))
                                  (p_theta theta s))
                            (mult (p_theta theta s)
                                  (mult (partial (fun th => log (p_theta th s)) theta)
                                        (partial (fun th => log (p_theta th s)) theta)))
                            Hswap Hle_p)).
  }
  (* F = 0 且逐项非负 ⟹ 逐项为零 *)
  exact (sum_over_S_zero_nonneg _ Hpt_nonneg Hf0).
Qed.

Definition natural_gradient_step (eta : R) (theta : Theta) : Theta :=
  theta_splus theta
    (theta_smult (opp eta)
      (theta_smult (inv_pos (fisher_info_scalar theta) (fisher_pos theta))
        (grad_free_energy theta))).

End NaturalGradient.

