         b5dD_atan_deriv_b5a_r_exp b5d1_b3rr_atan_deriv_lin
         b5dI_real_mult_positive_exp b5dM_b5i_one_plus_eps2_pos
         b5dM_real_const_pos real_min real_mult real_const real_plus
