Eval vm_compute in gbudget_at 7 (uloop (1#10)).

Lemma test_uloop_never : Id (gbottom_at 7 (uloop (1#10))) false.
Proof. vm_compute. reflexivity. Qed.

Lemma test_uloop_budget : Id (gbudget_at 7 (uloop (1#10))) 1%nat.
Proof. vm_compute. reflexivity. Qed.

